#: Tk's state bits for the modifiers ours keep, measured on Tk 9.0.2 with
#: ``event generate`` and ``%s``: Shift 1, Control 4, Mod1 8 - which is Alt
#: on X11, where a real Alt arrives - and Button1 to Button5 256 to 4096.
#: A generated ``<Alt-...>`` or ``<Meta-...>`` reports Tk's own masks
#: instead, 131072 and 65536, and those are matched as Alt and Meta too;
#: ``state=8`` fires an ``<Alt-...>`` binding, measured. TkCurses-vnmk.
_TK_SHIFT = 0x1
_TK_CONTROL = 0x4
_TK_MOD1 = 0x8
_TK_META_MASK = 0x10000
_TK_ALT_MASK = 0x20000
#: Every bit that means Alt or Meta is held, from a terminal or generated.
_TK_ALT_OR_META = _TK_MOD1 | _TK_ALT_MASK | _TK_META_MASK
_TK_BUTTONS = {MOD_BUTTONS[n]: 0x80 << n for n in range(1, 6)}


def _keysym_num(char: str) -> int:
    """The number of the keysym a key typing ``char`` has, 0 for none.

    X11's: Latin-1 is its own code point, and every other character is its
    code point plus 0x1000000, so 界 is 0x100754C.
    """
    if len(char) != 1:
        return 0
    code = ord(char)
    return code if code < 0x100 else 0x1000000 + code


def _tk_state(modifiers: int, *, generated: bool = False) -> int:
    """Tk's state number for our modifier bits.

    ``generated`` is for ``event_generate``, whose ``<Alt-...>`` and
    ``<Meta-...>`` report Tk's virtual masks; a key from the terminal reports
    Alt as Mod1, as a real X11 Alt does.
    """
    state = 0
    if modifiers & MOD_SHIFT:
        state |= _TK_SHIFT
    if modifiers & MOD_CTRL:
        state |= _TK_CONTROL
    if modifiers & MOD_ALT:
        state |= _TK_ALT_MASK if generated else _TK_MOD1
    if modifiers & MOD_META:
        state |= _TK_META_MASK
    for ours, tks in _TK_BUTTONS.items():
        if modifiers & ours:
            state |= tks
    return state


def _modifiers_of(state: int) -> int:
    """Our modifier bits for a Tk state number; bits we keep no modifier
    for - Lock, Mod2 to Mod5 - are reported in ``%s`` and match nothing."""
    modifiers = 0
    if state & _TK_SHIFT:
        modifiers |= MOD_SHIFT
    if state & _TK_CONTROL:
        modifiers |= MOD_CTRL
    if state & (_TK_MOD1 | _TK_ALT_MASK):
        modifiers |= MOD_ALT
    if state & _TK_META_MASK:
        modifiers |= MOD_META
    for ours, tks in _TK_BUTTONS.items():
        if state & tks:
            modifiers |= ours
    return modifiers


class EventType(enum.StrEnum):
    """What kind of event an :class:`Event` is: its ``type`` field.

    tkinter's names and values, which are X11's event numbers as strings, so
    ``event.type == EventType.KeyPress`` and ``event.type == "2"`` both hold
    for a key, and ``str(event.type)`` is ``"2"``. ``Key`` and ``Button`` are
    aliases of ``KeyPress`` and ``ButtonPress``, as in tkinter. Most of these
    never happen in a terminal; they are here because a program may name
    them.
    """

    # TkCurses-2q6o.10.

    KeyPress = "2"
    Key = KeyPress
    KeyRelease = "3"
    ButtonPress = "4"
    Button = ButtonPress
    ButtonRelease = "5"
    Motion = "6"
    Enter = "7"
    Leave = "8"
    FocusIn = "9"
    FocusOut = "10"
    Keymap = "11"
    Expose = "12"
    GraphicsExpose = "13"
    NoExpose = "14"
    Visibility = "15"
    Create = "16"
    Destroy = "17"
    Unmap = "18"
    Map = "19"
    MapRequest = "20"
    Reparent = "21"
    Configure = "22"
    ConfigureRequest = "23"
    Gravity = "24"
    ResizeRequest = "25"
    Circulate = "26"
    CirculateRequest = "27"
    Property = "28"
    SelectionClear = "29"
    SelectionRequest = "30"
    Selection = "31"
    Colormap = "32"
    ClientMessage = "33"
    Mapping = "34"
    VirtualEvent = "35"
    Activate = "36"
    Deactivate = "37"
    MouseWheel = "38"


#: The event a marked paste is delivered as. A TkCurses virtual event: Tk
#: has no paste that arrives as keystrokes, X11's being selections.
_TERMINAL_PASTE = EventPattern(type="Virtual", detail="TerminalPaste")


def _is_control(char: str) -> bool:
    """C0, DEL and C1: what a terminal would act on rather than show."""
    code = ord(char)
    return code < 0x20 or 0x7F <= code < 0xA0


def _without_controls(text: str) -> str:
    """``text`` with every control character taken out."""
    return "".join(char for char in text if not _is_control(char))


def _pasted_lines(text: str) -> str:
    """A paste for a Text: its line breaks as newlines - a terminal sends
    carriage returns - and tabs kept; every other control taken out."""
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    return "".join(c for c in text if c in "\n\t" or not _is_control(c))


def _pasted_line(text: str) -> str:
    """A paste for an entry, which has one line: each line break a space,
    every other control taken out."""
    text = text.replace("\r\n", " ").replace("\r", " ").replace("\n", " ")
    return _without_controls(text)


def _event_type(pattern_type: str) -> EventType:
    """The :class:`EventType` for a binding pattern's type name."""
    if pattern_type == "Virtual":
        return EventType.VirtualEvent
    return EventType[pattern_type]


class Event:
    """An event delivered to a binding callback.

    tkinter passes one object with a fixed set of attributes, whatever kind of
    event it describes, and application code reads whichever of them apply.
    That shape is kept here so existing handlers work unchanged.

    Unset fields hold ``0`` or ``""`` rather than tkinter's ``"??"`` sentinel.
    Code that tests a field it should not have read gets a falsy value instead
    of a string that crashes arithmetic two lines later, and nothing that reads
    the right field for its event type can tell the difference.

    Attributes:
        widget: The widget the binding fired on.
        type: Event type name, such as ``Key`` or ``ButtonPress``.
        time: When it happened, in seconds since the epoch.
        num: Mouse button number.
        keycode: Raw key code from curses.
        keysym: Key name, such as ``Return`` or ``a``.
        keysym_num: Numeric form of the keysym, for printable keys.
        char: The character the key produced, empty if it produced none.
        state: The modifiers held, as Tk's ``%s`` reports them: Shift 1,
            Control 4, Alt 8 - X11's Mod1 - and buttons 1 to 5 held 256 to
            4096. So ``event.state & 4`` is Control, as in tkinter.
        x, y: Position within the widget, in cells.
        x_root, y_root: Position on the screen, in cells.
        width, height: New size, for ``<Configure>``.
        delta: Scroll amount, positive for up.
        data: What a virtual event carries, as Tk's ``%d`` - the text, for
            ``<<TerminalPaste>>``. ``event_generate(..., data=...)`` sets
            it, as Tk's ``-data`` does.

    TkCurses extension:
        ``data``, which tkinter does not pass to a callback.
    """

    __slots__ = (
        "char",
        "data",
        "delta",
        "height",
        "keycode",
        "keysym",
        "keysym_num",
        "num",
        "state",
        "time",
        "type",
        "widget",
        "width",
        "x",
        "x_root",
        "y",
        "y_root",
    )

    def __init__(self, **fields: Any) -> None:
        """Create an event, defaulting every field the caller does not give."""
        self.widget: Any = None
        #: An :class:`EventType`; ``"??"`` until something says otherwise, as
        #: in tkinter.
        self.type: EventType | str = "??"
        self.time: float = time.time()
        self.num: int = 0
        self.keycode: int = 0
        self.keysym: str = ""
        self.keysym_num: int = 0
        self.char: str = ""
        self.state: int = 0
        self.x: int = 0
        self.y: int = 0
        self.x_root: int = 0
        self.y_root: int = 0
        self.width: int = 0
        self.height: int = 0
        self.delta: int = 0
        self.data: str = ""
        for name, value in fields.items():
            if name not in self.__slots__:
                raise TypeError(f"Event has no field {name!r}")
            setattr(self, name, value)

    def __repr__(self) -> str:
        """Show the fields that carry something, as tkinter's repr does."""
        shown = {
            name: getattr(self, name)
            for name in self.__slots__
            if name not in ("type", "time") and getattr(self, name)
        }
        fields = " ".join(f"{name}={value!r}" for name, value in shown.items())
        kind = getattr(self.type, "name", self.type)
        return f"<{kind} event{' ' if fields else ''}{fields}>"

    @classmethod
    def _from_core(cls, core: CoreEvent, widget: Misc) -> Event:
        """Build the tkinter-facing event for one internal input event."""
        event = cls(widget=widget, time=core.time)
        if isinstance(core, KeyEvent):
            event.type = EventType.KeyPress
            event.keycode = core.keycode
            event.keysym = core.keysym
            event.char = core.char
            event.state = _tk_state(core.modifiers)
            event.keysym_num = _keysym_num(core.char)
            event.x_root, event.y_root = widget.tk.pointer
        elif isinstance(core, MouseEvent):
            event.type = _MOUSE_EVENT_TYPES[core.state]
            event.num = core.button
            event.state = _tk_state(core.modifiers)
            event.x_root, event.y_root = core.x, core.y
            event.x = core.x - widget.winfo_rootx()
            event.y = core.y - widget.winfo_rooty()
            # Curses reports the wheel as buttons 4 and 5, as X11 does, so
            # delta is derived rather than reported.
            event.delta = {4: 1, 5: -1}.get(core.button, 0)
        elif isinstance(core, ResizeEvent):
            event.type = EventType.Configure
            event.width = core.width
            event.height = core.height
        return event


def _focus_next(event: Event) -> str:
    """Move the focus to the next widget that will take it."""
    _move_focus(event.widget, forwards=True)
    return "break"


def _focus_previous(event: Event) -> str:
    """Move the focus to the previous widget that will take it."""
    _move_focus(event.widget, forwards=False)
    return "break"


def _move_focus(widget: Misc, *, forwards: bool) -> None:
    """Hand the focus on, starting from wherever it currently is.

    From the widget the event reached rather than from the focus, because a
    key pressed with nothing focused still has to start somewhere.
    """
    focus = widget.focus_get()
    current = focus or widget
    target = current.tk_focusNext() if forwards else current.tk_focusPrev()
    if target is not None:
        # tk::TabToWindow: the widget left is told, then the one reached, so
        # that an entry can select its text when Tab arrives in it.
        # TkCurses-h0bj.
        if focus is not None:
            focus.event_generate("<<TraverseOut>>")
        target.focus_set()
        target.event_generate("<<TraverseIn>>")


