def _cursor_bitmap(path: str, *, hot_spot: bool) -> None:
    """Refuse a cursor's bitmap file as Tk does: one that cannot be read as
    an XBM is ``cleanup reading bitmap file``, and a cursor's own bitmap
    without a hot spot is ``bad hot spot in bitmap file`` - its mask needs
    none. Measured on Tk 9.0.2."""
    from tkcurses._core.images import _parse_xbm

    try:
        source = Path(path).read_text()
        _parse_xbm(source)
    except (OSError, UnicodeDecodeError, TclError):
        raise TclError(f'cleanup reading bitmap file "{path}"') from None
    if hot_spot and not all(
        re.search(rf"#define\s+\S*_{axis}_hot\s", source) for axis in "xy"
    ):
        raise TclError(f'bad hot spot in bitmap file "{path}"')


def _cursor_spec(widget: Any, value: Any) -> Any:
    """``cursor``, ``buttoncursor``, ``sashcursor``: a cursor Tk on X11 would
    make, though there is no pointer here to give it to.

    A name, with up to two colours (``watch red blue``), or a bitmap file
    with its colour (``@arrow.xbm black``), or file, mask and two colours.
    Measured on Tk 9.0.2: anything else is ``bad cursor spec "..."``, a
    colour Tk cannot read is ``invalid color name``, and the files are
    read: the bitmap must be an XBM with a hot spot.
    """
    if value is None or value == "":
        return value
    try:
        parts = _tcl_list(value)
    except TclError:
        parts = []
    text = " ".join(parts) if isinstance(value, (list, tuple)) else str(value)
    if not parts:
        raise TclError(f'bad cursor spec "{text}"')
    if parts[0].startswith("@"):
        if len(parts) not in (2, 4):
            raise TclError(f'bad cursor spec "{text}"')
        _cursor_bitmap(parts[0][1:], hot_spot=True)
        if len(parts) == 4:
            _cursor_bitmap(parts[1], hot_spot=False)
        colours = parts[-2:] if len(parts) == 4 else parts[1:]
    else:
        if parts[0] not in _CURSOR_NAMES or len(parts) > 3:
            raise TclError(f'bad cursor spec "{text}"')
        colours = parts[1:]
    for colour in colours:
        try:
            widget.winfo_rgb(colour)
        except (TclError, ValueError):
            raise TclError(f'invalid color name "{colour}"') from None
    return text


def _colour_or_terminals(widget: Any, value: Any) -> Any:
    """A colour, or "" for the terminal's own. Tk refuses "", and has no such
    thing as the terminal's colour to give it."""
    if value == "":
        return value
    try:
        widget.winfo_rgb(str(value))
    except (TclError, ValueError):
        raise TclError(f'unknown color name "{value}"') from None
    return value


def _distance_or_empty(widget: Any, value: Any) -> Any:
    """A size, or "" for none given: a PanedWindow's ``width`` and ``height``,
    Message's ``padx`` and ``pady``, ttk.Label's ``wraplength`` and the
    scrollbar's ``elementborderwidth``. Measured on Tk 9.0.2: -3 reads back
    -3 (but Message's padding "", :func:`_padding_or_empty`), and "x" is
    refused naming both."""
    if value == "":
        return value
    try:
        return _signed_distance(widget, value)
    except TclError:
        raise TclError(f'expected screen distance or "" but got "{value}"') from None


#: Options that move a container's children: its padding and its border.
#: Set on the root or a Toplevel after the children are laid out, they did
#: nothing until the next resize.
_INSET_OPTIONS = frozenset({"padx", "pady", "borderwidth"})


def _padding_or_empty(widget: Any, value: Any) -> Any:
    """Message's ``padx`` and ``pady``: a distance, below zero read as "".

    A Message reads a negative padding back as "", not 0, measured.
    """
    distance = _distance_or_empty(widget, value)
    return "" if distance == "" or distance < 0 else distance


#: The visual classes Tk names, in the order its message lists them.
_VISUALS = (
    "best",
    "directcolor",
    "grayscale",
    "greyscale",
    "pseudocolor",
    "staticcolor",
    "staticgray",
    "staticgrey",
    "truecolor",
    "default",
)


def _visual(widget: Any, value: Any) -> Any:
    """A ``-visual``: a class or a unique prefix of one, or a window, with an
    optional depth after one space. Checked and kept: there is no visual to
    choose here, so it changes nothing.

    Measured on Tk 9.0.2: ``truecolor 24``, ``tru``, ``b``, ``best -1`` and
    ``.`` are taken as given; ``s`` and ``d`` are ambiguous, but ``staticg``
    is not, ``gray`` and ``grey`` being one class; ``TrueColor``, a leading
    space and ``default 24`` are refused, and ``truecolor x`` wants an
    integer. Tk then asks the display for the visual, and fails with
    ``couldn't find an appropriate visual`` when it has none; a terminal has
    no visuals to ask.
    """
    text = str(value)
    if not text or text.startswith("."):
        return value
    name, _, depth = text.partition(" ")
    classes = {
        visual.replace("grey", "gray") for visual in _VISUALS if visual.startswith(name)
    }
    if len(classes) != 1 or (depth and "default" in classes):
        listed = ", ".join(_VISUALS[:-1])
        raise TclError(
            f'unknown or ambiguous visual name "{text}": class must be '
            f"{listed}, or {_VISUALS[-1]}"
        )
    if depth:
        _tcl_integer(widget, depth)
    return value


def _colormap(widget: Any, value: Any) -> Any:
    """A ``-colormap``: ``""``, ``new``, or a window to share one with.
    Measured: ``NEW`` is taken for a path and refused as one."""
    text = str(value)
    if text in ("", "new"):
        return value
    try:
        widget.nametowidget(text)
    except (KeyError, TclError):
        raise TclError(f'bad window path name "{text}"') from None
    return value


def _use(widget: Any, value: Any) -> Any:
    """A ``-use``: the window to embed in, which a terminal never has. Only
    ``""`` is taken; anything else fails as Tk fails on a window that does
    not exist."""
    del widget
    if str(value):
        raise TclError(f'couldn\'t create child of window "{value}"')
    return value


def _class_from(
    class_: str | None, cnf: dict[str, Any] | None, kw: dict[str, Any]
) -> tuple[str | None, dict[str, Any] | None, dict[str, Any]]:
    """Take ``-class`` out of the options, however it was spelt.

    ``class_=`` is the keyword; ``{"class": ...}`` in ``cnf`` or ``**kw`` is
    how the option itself arrives, and is what tkinter's own Frame looks for
    too. Either way it names the class, rather than being an option to store
    as given.
    """
    kw = dict(kw)
    named = kw.pop("class", None)
    if cnf is not None and "class" in cnf:
        cnf = dict(cnf)
        named = cnf.pop("class") if named is None else named
    return (class_ if class_ is not None else named), cnf, kw


