#: all take, with Tk's defaults. None has a meaning in a terminal: they are
#: checked as Tk checks them, kept, and answered. TkCurses-gm66.7.
_WINDOW_SYSTEM_OPTIONS: dict[str, Any] = {
    "class": "",
    "colormap": "",
    "container": 0,
    "visual": "",
}


#: The anchors a Canvas ``-offset`` may name instead of ``x,y``.
_OFFSET_ANCHORS = ("n", "ne", "e", "se", "s", "sw", "w", "nw", "center")


def _canvas_offset(widget: Any, value: Any) -> Any:
    """A Canvas ``-offset``: ``x,y``, ``#x,y`` or an anchor. Tk aligns its
    stipples with it, and there are no stipples here, so it is checked and
    kept. Measured on Tk 9.0.2, with its message."""
    del widget
    text = str(value)
    pair = text[1:] if text.startswith("#") else text
    x, _, y = pair.partition(",")
    if text in _OFFSET_ANCHORS or (_is_number(x) and _is_number(y)):
        return value
    raise TclError(
        f'bad offset "{text}": expected "x,y", "#x,y", n, ne, e, se, s, sw, w, '
        "nw, or center"
    )


#: Tcl's one-letter backslash sequences, as a list element reads them.
_TCL_ESCAPES = {
    "a": "\a",
    "b": "\b",
    "f": "\f",
    "n": "\n",
    "r": "\r",
    "t": "\t",
    "v": "\v",
}


def _tcl_list(value: Any) -> list[str]:
    r"""Split a Tcl list into its elements, as ``Tcl_SplitList`` does.

    A tuple or list is taken as already split, as tkinter hands one to Tcl.
    Otherwise elements are separated by whitespace and may be ``{braced}``,
    taken literally with nested braces counted, or ``"quoted"``, with
    backslash sequences read as in a bare word. A brace or quote that is not
    closed, or a closing one followed by anything but space, is an error with
    Tcl's message. Only the one-letter backslash sequences are read; Tcl's
    octal, ``\x`` and ``\u`` forms are not.
    """
    if isinstance(value, (tuple, list)):
        return [str(element) for element in value]
    text = str(value)
    elements: list[str] = []
    at = 0
    while True:
        while at < len(text) and text[at].isspace():
            at += 1
        if at == len(text):
            return elements
        opener = text[at]
        if opener == "{":
            depth, start = 1, at + 1
            at += 1
            while at < len(text) and depth:
                if text[at] == "\\":
                    at += 1
                elif text[at] in "{}":
                    depth += 1 if text[at] == "{" else -1
                at += 1
            if depth:
                raise TclError("unmatched open brace in list")
            element, kind = text[start : at - 1], "braces"
        else:
            chars: list[str] = []
            quoted = opener == '"'
            at += quoted
            while at < len(text) and (
                text[at] != '"' if quoted else not text[at].isspace()
            ):
                if text[at] == "\\" and at + 1 < len(text):
                    at += 1
                    chars.append(_TCL_ESCAPES.get(text[at], text[at]))
                else:
                    chars.append(text[at])
                at += 1
            if quoted and at == len(text):
                raise TclError("unmatched open quote in list")
            at += quoted
            element, kind = "".join(chars), "quotes"
        if (opener in '{"') and at < len(text) and not text[at].isspace():
            raise TclError(
                f'list element in {kind} followed by "{text[at]}" instead of space'
            )
        elements.append(element)


def _image_name(widget: Any, value: Any) -> str:
    """An image's name, or ``""``. Measured on Tk 9.0.2, for ``selectimage``
    and ``tristateimage``: ``image "nosuch" does not exist``."""
    name = str(value)
    if name and name not in widget.tk.images:
        raise TclError(f'image "{name}" does not exist')
    return name


def _tcl_index(value: Any, table: tuple[str, ...], what: str) -> str:
    """One of ``table``, or a unique prefix of one, returned whole - Tcl's
    ``Tcl_GetIndexFromObj``. Case counts, and a prefix of several, the empty
    one included, is ``ambiguous`` rather than ``bad``."""
    text = str(value)
    if text in table:
        return text
    matches = [name for name in table if name.startswith(text)]
    if len(matches) == 1:
        return matches[0]
    # Tcl's own punctuation: "a or b" for two, "a, b, or c" for more.
    listed = ", ".join(table[:-1]) + ("," if len(table) > 2 else "")
    kind = "ambiguous" if matches else "bad"
    raise TclError(f'{kind} {what} "{text}": must be {listed} or {table[-1]}')


def _choices(what: str, *table: str, empty: bool = False) -> Callable[[Any, Any], str]:
    """A check for an option Tk reads with ``Tcl_GetIndexFromObj``: one of
    ``table`` or a unique prefix of one, returned whole, in Tk's words when
    it is neither. With ``empty``, ``""`` is a choice too, listed last."""

    def check(widget: Any, value: Any) -> str:
        del widget
        if empty and value == "":
            return ""
        try:
            return _tcl_index(value, table, what)
        except TclError as error:
            if not empty:
                raise
            kind = str(error).split(" ", 1)[0]
            listed = ", ".join(table)
            raise TclError(
                f'{kind} {what} "{value}": must be {listed}, or ""'
            ) from None

    return check


def _canvas_state(widget: Any, value: Any) -> str:
    """A Canvas's ``state``: ``normal`` or ``disabled``, a prefix of either,
    or ``""``. Measured on Tk 9.0.2, with its own message - ``hidden``,
    which a canvas item takes, is refused."""
    del widget
    text = str(value)
    if text == "":
        return ""
    for name in ("normal", "disabled"):
        if name.startswith(text):
            return name
    raise TclError(f'bad state value "{text}": must be normal or disabled')


def _scrollbar_orient(widget: Any, value: Any) -> str:
    """A classic Scrollbar's ``orient``: a prefix of ``horizontal``, ``""``
    included, or of ``vertical``. Measured on Tk 9.0.2."""
    del widget
    text = str(value)
    for name in ("horizontal", "vertical"):
        if name.startswith(text):
            return name
    raise TclError(f'bad orientation "{text}": must be vertical or horizontal')


_UNDERLINE_NUMBER = re.compile(r"\s*([+-]?\d+)(?:([+-])(\d+))?\s*")
_UNDERLINE_END = re.compile(r"end(?:[+-]\d+)?")


def _underline(widget: Any, value: Any) -> Any:
    """An ``underline`` index, as Tk 9 reads one, measured on 9.0.2:
    ``3``, ``3+1`` (read back 4), ``end`` or ``end-1`` (kept as written), or
    ``""``; a number below zero reads back ``""``."""
    del widget
    if isinstance(value, bool):
        value = int(value)
    if isinstance(value, int):
        return value if value >= 0 else ""
    text = str(value)
    if text == "" or _UNDERLINE_END.fullmatch(text):
        return text
    found = _UNDERLINE_NUMBER.fullmatch(text)
    if found:
        number, sign, offset = found.groups()
        index = int(number) + (int(offset) if sign == "+" else -int(offset or 0))
        return index if index >= 0 else ""
    raise TclError(
        f'bad index "{text}": must be integer?[+-]integer?, end?[+-]integer?, or ""'
    )


def _underline_position(value: Any, text: str) -> int:
    """Which character of ``text`` an ``underline`` index picks: -1 for
    none. ``end`` is the last."""
    if value is None or value == "":
        return -1
    if isinstance(value, int):
        return value
    word = str(value)
    if word.startswith("end"):
        offset = int(word[3:] or 0)
        return len(text) - 1 + offset
    try:
        return int(word)
    except ValueError:
        return -1


def _draws_border(options: dict[str, Any]) -> bool:
    """Whether options with this ``relief`` and ``borderwidth`` draw a border.

    Tk's rule: a border of width 0 is not drawn whatever its relief, and a
    flat one is not seen whatever its width. A terminal border is a cell of
    box-drawing, so a flat border takes no cell - Tk's default of 1 on a
    Label is a pixel, and a blank cell round every label would be anything
    but. ``""``, a themed widget's border width, is the theme's: the relief
    decides.
    """
    relief = options.get("relief", FLAT)
    if relief in (FLAT, "", None):
        return False
    width = options.get("borderwidth", 0)
    if width == "":
        return True
    number = _tcl_number(width)
    return number is not None and not math.isnan(number) and number >= 1


def _justification(widget: Any, value: Any) -> str:
    """``left``, ``right`` or ``center``. Measured on Tk 9.0.2: ``cent``
    reads back ``center``, ``C`` is bad and ``""`` ambiguous."""
    del widget
    return _tcl_index(value, ("left", "right", "center"), "justification")


def _menu_type(widget: Any, value: Any) -> str:
    """A Menu's ``-type``. Measured on Tk 9.0.2: ``m`` reads back ``menubar``."""
    del widget
    return _tcl_index(value, ("menubar", "normal", "tearoff"), "type")


def _is_number(text: str) -> bool:
    try:
        float(text)
    except ValueError:
        return False
    return True


#: Tk's built-in bitmaps, as one cell each. The names are Tk's - measured on
#: Tk 9.0.2, exactly these ten and case counts - and the glyphs are ours: a
#: 16-pixel picture cannot be drawn in a cell, so each is the character
#: that reads as it. All are one cell wide, ambiguous width included.
_BITMAP_GLYPHS: dict[str, str] = {
    "error": "✖",
    "gray12": "·",
    "gray25": "░",
    "gray50": "▒",
    "gray75": "▓",
    "hourglass": "⧗",
    "info": "\u2139",  # INFORMATION SOURCE, which looks like an i
    "questhead": "⍰",
    "question": "?",
    "warning": "⚠",
}


def _bitmap(widget: Any, value: Any) -> str:
    """A ``bitmap``: one of Tk's ten names, ``@file`` naming an XBM file,
    or ``""`` for none - refused otherwise in Tk 9.0.2's words."""
    text = str(value)
    if text == "" or text in _BITMAP_GLYPHS:
        return text
    if text.startswith("@"):
        _file_bitmap(widget, text[1:])
        return text
    raise TclError(f'bitmap "{text}" not defined')


def _file_bitmap(widget: Any, path: str, foreground: str = "white") -> Image:
    """The XBM file ``bitmap="@path"`` names, as an image no one else sees.

    Made with :class:`BitmapImage` and taken straight back out of the
    application's images, so it is the widget's own and ``image_names()``
    does not list it.

    Raises:
        TclError: If the file cannot be read, in Tk's words.
    """
    try:
        if not path:  # BitmapImage takes file="" as none given
            raise TclError(path)
        image = BitmapImage(master=widget, file=path, foreground=foreground)
    except TclError:
        raise TclError(f'error reading bitmap file "{path}"') from None
    widget.tk.images.pop(str(image), None)
    return image


def _entry_flag(menu: Any, value: Any) -> bool:
    """A boolean menu-entry option, read as Tk reads one; unreadable is off."""
    try:
        return bool(_tcl_boolean(menu, value))
    except TclError:
        return False


def _script(widget: Any, value: Any) -> Any:
    """A command given as tkinter gives one to Tk: a tuple or list of words
    - a name :meth:`Misc.register` made, and Tk's percent codes - is kept as
    the one string tkinter would pass, so ``cget`` answers what it answers.
    A Python callable is kept as it is."""
    del widget
    if isinstance(value, (list, tuple)) and all(
        isinstance(word, (str, int)) and not isinstance(word, bool) for word in value
    ):
        return " ".join(_tcl_word(str(word)) for word in value)
    return value


#: The widget classes Tk's ``::tk_setPalette`` makes a prototype of, in its
#: order (palette.tcl, Tk 9.0).
_PALETTE_PROTOTYPES = (
    "Button", "Canvas", "Checkbutton", "Entry", "Frame", "Label",
    "LabelFrame", "Listbox", "Menubutton", "Menu", "Message", "Radiobutton",
    "Scale", "Scrollbar", "Spinbox", "Text",
)  # fmt: skip


def _exact_rgb16(widget: Any, color: str) -> tuple[int, int, int]:
    """A colour's channels, sixteen bits each, as asked for rather than as
    this terminal would show it - what Tk's ``winfo rgb`` gives on a
    true-colour display, so a palette worked out from it is the same."""
    rgb = rgb_for(color)
    if rgb is None:
        name = _x11colors.lookup(color)
        rgb = _x11colors.NAMES[name] if name is not None else None
    if rgb is None:
        return widget.winfo_rgb(color)  # type: ignore[no-any-return]
    return (rgb[0] * 257, rgb[1] * 257, rgb[2] * 257)


def _same_colour(widget: Any, first: Any, second: Any) -> bool:
    """Whether two colours are the same, either being empty for none."""
    if not first or not second:
        return str(first) == str(second)
    try:
        return _exact_rgb16(widget, str(first)) == _exact_rgb16(widget, str(second))
    except TclError:
        return str(first) == str(second)


def _tcl_word(text: str) -> str:
    """``text`` as one word of a Tcl list, braced if it needs to be."""
    if text and not any(char in text for char in ' \t\n{}"\\;$[]'):
        return text
    return "{" + text + "}"


def _tcl_boolean(widget: Any, value: Any) -> int:
    """A boolean option, answered as Tk answers it: ``yes`` reads back 1.

    Any number is a boolean in Tcl, not only 0 and 1: measured on Tk 9.0.2,
    ``-undo 2.5`` and ``-undo 0x10`` read back 1. tkinter's own
    ``getboolean`` refuses all of those, so this cannot go through it alone.
    """
    try:
        return int(widget.getboolean(value))
    except TclError:
        pass
    number = _tcl_number(value)
    if number is None:
        raise TclError(f'expected boolean value but got "{value}"')
    if math.isnan(number):
        raise TclError("floating point value is Not a Number")
    return int(number != 0)


def _insert_unfocussed(widget: Any, value: Any) -> str:
    """``hollow``, ``none`` or ``solid``, by any unique prefix, as Tk takes it."""
    del widget
    choices = ("hollow", "none", "solid")
    text = str(value)
    matches = [choice for choice in choices if text and choice.startswith(text)]
    if len(matches) != 1:
        raise TclError(f'bad insertunfocussed "{text}": must be hollow, none, or solid')
    return matches[0]


_RELIEFS = ("flat", "groove", "raised", "ridge", "solid", "sunken")


def _choose_relief(value: Any, choices: str) -> str:
    """A relief by its name or any unique prefix, as ``Tk_GetRelief`` takes it.

    Case matters and spaces are not stripped: Tk refuses ``RAISED`` and
    `` raised``, measured on 9.0.2.
    """
    text = str(value)
    if text in _RELIEFS:
        return text
    matches = [relief for relief in _RELIEFS if relief.startswith(text)]
    if len(matches) == 1 and text:
        return matches[0]
    problem = "bad" if not matches else "ambiguous"
    raise TclError(f'{problem} relief "{text}": must be {choices}')


def _relief(widget: Any, value: Any) -> str:
    """A relief, which may not be empty."""
    del widget
    return _choose_relief(value, "flat, groove, raised, ridge, solid, or sunken")


def _relief_or_none(widget: Any, value: Any) -> str:
    """A relief, or "" for none: ``overrelief``, whose "" means no change."""
    del widget
    if value == "":
        return ""
    return _choose_relief(value, 'flat, groove, raised, ridge, solid, sunken, or ""')


def _distance_number(value: Any) -> int | float | None:
    """A screen distance in cells, or None if it is not one: a Tcl number,
    or one with Tk's unit suffix - ``2c``, ``1i``, ``3m``, ``10p`` - at ten
    cells to the inch."""
    number = _tcl_number(value)
    if number is not None:
        return number
    try:
        return _geometry.distance_in_cells(value, _tcl_number)
    except ValueError:
        return None


def _signed_distance(widget: Any, value: Any) -> int:
    """A size Tk keeps below zero as given: ``sliderlength`` and
    ``activeborderwidth`` read back -5 after -5, measured. What is drawn
    treats one as its smallest instead.

    Tk's unit suffixes are converted to cells, and the cells are what is
    kept: Tk keeps ``2c`` as written, but everything here that draws reads
    a number of cells."""
    del widget
    number = _distance_number(value)
    if number is None or math.isnan(number):
        raise TclError(f'expected screen distance but got "{value}"')
    # Measured: Tk reads an infinite distance back as 0.
    return 0 if math.isinf(number) else round(number)


def _scroll_region_value(widget: Any, value: Any) -> Any:
    """A Canvas's ``scrollregion``: four distances, or "" (or None) for none.

    Measured on Tk 9.0.2: ``0``, ``" "``, three values and five are refused as
    ``bad scrollRegion "0"``, and a value that is not a distance names it -
    ``expected screen distance but got "a"``.
    """
    if value is None or value == "":
        return value
    elements = _tcl_list(value)
    if len(elements) != 4:
        shown = " ".join(elements) if isinstance(value, (tuple, list)) else value
        raise TclError(f'bad scrollRegion "{shown}"')
    for element in elements:
        _signed_distance(widget, element)
    return value


def _element_borderwidth(widget: Any, value: Any) -> Any:
    """A size, or "" for the scrollbar's own ``borderwidth``. Tk reads any
    negative width back as "", measured."""
    distance = _distance_or_empty(widget, value)
    return "" if distance == "" or distance < 0 else distance


def _variable(widget: Any, value: Any) -> Any:
    """A ``Variable``, or nothing - ``""`` read as None.

    Anything else is a NAME, and binds to the variable called that, as in
    Tk: ``textvariable=5`` is the variable ``5``, which ``setvar`` and any
    ``Variable(name="5")`` share. The traces are kept by name, so each
    hears the others' writes.
    """
    if value is None or value == "":
        return None
    if isinstance(value, Variable):
        return value
    return _NamedVariable(widget, str(value))


def _unchecked(widget: Any, value: Any) -> Any:
    """Kept as given, as Tk keeps it: what reads it must cope."""
    del widget
    return value


def _part_relief(relief: Any) -> int:
    """How a relief shows on a part one cell deep: a slider, an arrow, an entry.

    There are no edges to draw it with, so only the relief Tk's bindings put
    on a part while it is held, ``sunken``, is shown, and it is dim, as a
    sunken border is. The rest draw the part as it was. TkCurses-gm66.5.
    """
    return _curses.A_DIM if str(relief) == SUNKEN else _curses.A_NORMAL


