def _menubar_of(window: Any) -> Menu | None:
    """The Menu a window's ``menu`` option names, or None for no menubar.

    Tk takes the menu as a widget or as its path name, and ``""`` for none -
    which is also what ``cget("menu")`` answers by default, and how a program
    removes a menubar (TkCurses-un8i: it crashed here). Measured on Tk 9.0.2,
    the name is not checked when it is set: one that names nothing, or names a
    widget that is not a menu, is stored as given, and no bar is shown.
    """
    value = getattr(window, "_options", {}).get("menu")
    if isinstance(value, str):
        if not value:
            return None
        try:
            value = window.nametowidget(value)
        except KeyError:
            return None
    if isinstance(value, Menu) and value.winfo_exists():
        return value
    return None


def _answering_queries(method: Callable[..., Any]) -> Callable[..., Any]:
    """``method`` as a ``configure`` that also answers ``configure("name")``.

    See :meth:`Misc.__init_subclass__`, which applies it.
    """

    @functools.wraps(method)
    def configure(self: Misc, cnf: Any = None, **kw: Any) -> Any:
        if isinstance(cnf, str):
            return self._configure_query(cnf)
        if (cnf or kw) and not _given(cnf, kw):
            # Options given, every one None: tkinter drops them all and sets
            # nothing - it does not fall through to listing them, which is
            # what an empty call means. Measured, configure(text=None) is None.
            return None
        return method(self, cnf, **kw)

    configure._answers_queries = True  # type: ignore[attr-defined]
    return configure


def _abandoning_on_failure(method: Callable[..., Any]) -> Callable[..., Any]:
    """``method`` as an ``__init__`` that abandons the widget if it raises.

    See :meth:`Misc.__init_subclass__`, which applies it, and
    :meth:`Misc._abandon`, which is what abandoning means.
    """

    @functools.wraps(method)
    def __init__(self: Misc, *args: Any, **kw: Any) -> None:
        try:
            method(self, *args, **kw)
        except BaseException:
            # Only once registered. Before that there is nothing to undo, and
            # perhaps no self.tk to ask: "no default root" and a name with a
            # "." are both refused first, and must arrive as they were raised.
            state = vars(self)
            if "tk" in state and state["tk"].widgets.get(state.get("_w", "")) is self:
                self._abandon()
            raise

    __init__._abandons = True  # type: ignore[attr-defined]
    return __init__


class Misc:
    """Behaviour shared by every widget, and the application: bindings,
    focus, timers, the event loop, options, and the ``winfo`` queries.

    ``self.tk`` is there, as in tkinter, so code that reaches for it finds
    something. It is the application rather than a Tcl interpreter, and has
    no ``call`` or ``eval``.

    Differences from tkinter:
        Every position and size a ``winfo`` method answers is in character
        cells, not pixels.
    """

    # self.tk is the _core.application.Application. Widget geometry is kept in
    # _rect (position relative to the master) and _requested (the size the
    # widget asked for); this class only reads them, and until the geometry
    # managers set them every winfo query reports zeroes rather than failing.
    # _layout_manager is the manager laying out this widget's children, which
    # is different from the one that placed the widget itself - that is named
    # by winfo_manager(), and the container holding its options is
    # _manager_container.

    #: True for Tk and Toplevel. Bindings, focus history and coordinate
    #: origins all stop at a toplevel, so the widget layer marks them here.
    _is_toplevel = False

    #: False for a widget that is a window of its own in Tk, so that its
    #: master does not clip it: a toplevel, and a Menu, which is posted
    #: against the screen. See :meth:`_unclipped_part`.
    _clipped_by_master = True

    #: State shared with every other widget in the same application.
    tk: Application

    #: The parent widget, None for the root of the tree.
    master: Misc | None

    def __init_subclass__(cls, **kwargs: Any) -> None:
        """Let every ``configure`` a subclass defines answer a query.

        ``configure("relief")`` asks for one option rather than setting any,
        and Tk answers it on every widget. Nearly thirty classes here override
        ``configure`` to check or react to what is set, and every one began
        by merging ``cnf`` into a dict - so a string crashed them all with
        ``'str' object is not a mapping``, the root window included
        (TkCurses-kifn). Answering it here, once, means an override written
        later cannot forget to.
        """
        super().__init_subclass__(**kwargs)
        # What the class RESOLVES, not what it defines: the ttk widgets take
        # configure from ttk.Widget, a mixin that is no Misc and never comes
        # through here itself.
        for name in ("configure", "config"):
            method = getattr(cls, name)
            if not getattr(method, "_answers_queries", False):
                setattr(cls, name, _answering_queries(method))
        # And every constructor leaves a widget it could not finish as tkinter
        # does (TkCurses-lwoi). Wrapping the one class that checks options
        # was not enough: about thirty refuse a value - width="abc", a
        # textvariable that is no Variable - in their own __init__, after
        # BaseWidget's has returned.
        if not getattr(cls.__init__, "_abandons", False):
            cls.__init__ = _abandoning_on_failure(cls.__init__)  # type: ignore[method-assign]

    def __init__(self, master: Misc | None = None, name: str | None = None) -> None:
        """
        Args:
            master: Parent widget. None makes this the root of a new
                application with its own bindings, timers and clipboard;
                resolving a default root is the widget layer's job, not this
                one's.
            name: Path component for this widget. Generated from the class
                name when omitted, as tkinter does.

        Raises:
            ValueError: If the name contains a ``.``, which would make the
                widget path ambiguous.
        """
        self.master = master
        self.children: dict[str, Misc] = {}
        self.tk = Application() if master is None else master.tk

        if name is None:
            name = "." if master is None else self.tk.next_name(type(self).__name__)
        if master is not None and "." in name:
            raise ValueError(f"widget name {name!r} may not contain a '.'")
        self._name = name
        self._w = self._build_path(master, name)

        self._bindtags: tuple[str, ...] | None = None
        self._options: dict[str, Any] = {}
        self._rect = Rect(0, 0, 0, 0)
        self._requested = Size(0, 0)
        self._manager = ""
        #: The container whose geometry manager is laying this widget out.
        #: Usually the master, but ``in_`` allows another - and either way
        #: it is where the widget's own options live, which is what a later
        #: reconfigure has to merge into.
        self._manager_container: Misc | None = None
        #: The geometry manager laying out this widget's children, and
        #: whether this widget resizes itself to fit them.
        self._layout_manager: Layout | None = None
        #: The children placed in this widget. Apart from the manager above,
        #: because Tk lets place share a container with pack or grid: the
        #: overlay over packed content. TkCurses-huq9.
        self._place_manager: PlaceLayout | None = None
        #: A PanedWindow's panes. Apart from both of the above for the same
        #: reason: Tk lets pack or grid lay out children of a paned window
        #: beside its panes, measured on Tk 9.0.2. TkCurses-ect9.
        self._paned_manager: PanedLayout | None = None
        #: The windows a Canvas's items or a Text's characters position.
        self._embed_manager: EmbedLayout | None = None
        self._layout_propagate = True
        #: The stacked window this widget draws into, once it has one.
        self._panel: Panel | None = None
        #: Where that window starts within the widget, ``(x, y)``: nonzero
        #: when the left or top of the widget is clipped away, by the screen
        #: or by an ancestor. See :meth:`_visible_rect`.
        self._window_offset = (0, 0)
        self._mapped = False
        self._takefocus = True
        self._takefocus_given = False
        self._destroyed = False

        if master is not None and name in master.children:
            # tkinter's BaseWidget._setup: a name already taken destroys the
            # widget holding it, <Destroy> and descendants and all, and the new
            # one takes its place. Tk itself would refuse ("window name already
            # exists in parent"), but no tkinter program sees that. Measured on
            # Python 3.14 over Tk 9.0.2. TkCurses-use6.
            master.children[name].destroy()
        self.tk.widgets.add(self._w, self)
        if master is not None:
            master.children[name] = self

    def _abandon(self) -> None:
        """Leave a widget whose creation failed as tkinter leaves one.

        tkinter puts the object in ``master.children`` before Tk refuses an
        option, and nothing takes it out again: ``nametowidget`` still finds
        it. But Tk made no window, so it does not exist - ``winfo_exists`` is
        0 and ``winfo_children`` leaves it out - and destroying it only takes
        it out of ``children``. Measured on Python 3.14 over Tk 9.0.2.
        TkCurses-lwoi.
        """
        self._destroyed = True
        self.tk.widgets.remove(self._w)
        self.tk.bindings.unbind(self._w)
        self.tk.timers.cancel_for(self._w)

    def __repr__(self) -> str:
        """Identify the widget by class and path, as tkinter does."""
        return f"<{type(self).__name__} object {self._w}>"

    def __str__(self) -> str:
        """The widget's path name.

        Tk identifies widgets by path in every API that takes one, so a widget
        used where a string is expected has to render as its path.
        """
        return self._w

    @staticmethod
    def _build_path(master: Misc | None, name: str) -> str:
        """Full path name for a widget under ``master``.

        The root is ``.`` and its children are ``.name`` rather than
        ``..name``, which is why this is not a plain join.
        """
        if master is None:
            return name
        return f"{master._w}{name}" if master._w == "." else f"{master._w}.{name}"

    # ==================================================================
    # Core
    # ==================================================================

    def destroy(self) -> None:
        """Destroy this widget and everything under it.

        Children go first, so a handler bound to ``<Destroy>`` on a child
        still sees an intact parent. Destroying twice is harmless, which
        matters because a parent's teardown may reach a child the application
        has already destroyed.
        """
        if self._destroyed:
            # A widget whose creation failed is still in its master's
            # children, as in tkinter; see _abandon.
            if self.master is not None and self.master.children.get(self._name) is self:
                del self.master.children[self._name]
            return
        for child in list(self.children.values()):
            child.destroy()
        self.event_generate("<Destroy>")
        # Out of whatever lays it out, or its siblings keep its space and
        # pack_slaves goes on listing it. TkCurses-41zl.
        container = self._manager_container
        if container is not None and self._manager:
            self._leave_layout(container)

        self._destroyed = True
        self._mapped = False
        self.tk.bindings.unbind(self._w)
        # Pending callbacks go with it. Tk owns an after handle as a command
        # belonging to the widget, so destroying the widget drops it and the
        # callback never runs; here it used to run against a widget whose
        # window and panel were gone.
        self.tk.timers.cancel_for(self._w)
        self.tk.widgets.remove(self._w)
        self.tk.selections.disown(self)
        if self.tk.focus is self:
            self.tk.focus = None
        if self.tk.grab is self:
            self.grab_release()
        self.tk.focus_history.pop(id(self), None)
        if self.master is not None:
            self.master.children.pop(self._name, None)

    def register(
        self,
        func: Callable[..., Any],
        subst: Callable[..., Any] | None = None,
        needcleanup: int = 1,
    ) -> str:
        """Register ``func`` under a command name, and return the name.

        The name is what tkinter's validation idiom passes, with Tk's percent
        codes, as a ``validatecommand``::

            check = root.register(lambda text: text.isdigit())
            Entry(root, validate="key", validatecommand=(check, "%P"))

        Args:
            func: The callable.
            subst: Called with the arguments first, and ``func`` with what
                it returns, as in tkinter.
            needcleanup: Accepted for tkinter's signature; a name lasts until
                :meth:`deletecommand`.
        """
        del needcleanup
        name = repr(id(func))
        with contextlib.suppress(AttributeError):
            name += func.__name__
        if subst is None:
            self.tk.commands[name] = func
        else:
            self.tk.commands[name] = lambda *args: func(*subst(*args))
        return name

    _register = register

    def deletecommand(self, name: str) -> None:
        """Remove a command :meth:`register` made, or a binding by the handle
        ``bind`` returned."""
        if self.tk.commands.pop(name, None) is None:
            self.tk.bindings.unbind(self._w, funcid=name)

    # ==================================================================
    # Binding
    # ==================================================================

    def bind(
        self,
        sequence: str | None = None,
        func: Callable[[Event], Any] | None = None,
        add: bool | str | None = None,
    ) -> Any:
        """Bind ``func`` to ``sequence`` on this widget.

        With a callback, returns a handle that :meth:`unbind` accepts. With a
        sequence but no callback, returns the callbacks bound to it — tkinter
        returns a Tcl script string there, which has no meaning without Tcl,
        so the callables themselves are returned instead. With neither,
        returns the sequences currently bound.

        ``add`` keeps existing callbacks instead of replacing them. tkinter
        spells it ``"+"``; a true value works too.
        """
        return self._bind_on(self._w, sequence, func, add)

    def unbind(self, sequence: str, funcid: str | None = None) -> None:
        """Remove bindings for ``sequence``, or just the one named by ``funcid``."""
        self.tk.bindings.unbind(self._w, parse_sequence(sequence), funcid)

    def bind_all(
        self,
        sequence: str | None = None,
        func: Callable[[Event], Any] | None = None,
        add: bool | str | None = None,
    ) -> Any:
        """Bind on the ``all`` tag, so every widget in the application sees it."""
        return self._bind_on("all", sequence, func, add)

    def unbind_all(self, sequence: str) -> None:
        """Remove an application-wide binding."""
        self.tk.bindings.unbind("all", parse_sequence(sequence))

    def bind_class(
        self,
        className: str,
        sequence: str | None = None,
        func: Callable[[Event], Any] | None = None,
        add: bool | str | None = None,
    ) -> Any:
        """Bind on a widget class, so every widget of that class sees it.

        This is how a widget's own behaviour is defined: ``Entry`` handles
        typing through a class binding, which an instance binding can then
        override or suppress with ``"break"``.
        """
        return self._bind_on(className, sequence, func, add)

    def unbind_class(self, className: str, sequence: str) -> None:
        """Remove a class binding."""
        self.tk.bindings.unbind(className, parse_sequence(sequence))

    def bindtags(self, tagList: Sequence[str] | None = None) -> tuple[str, ...]:
        """Get or set the tags consulted when an event reaches this widget.

        The default is the widget's own path, its class, its toplevel, and
        ``all``, in that order. Reordering them is the supported way to make
        an instance binding run before its class binding rather than after.
        """
        if tagList is None:
            return self._binding_tags()
        self._bindtags = tuple(str(tag) for tag in tagList)
        return self._bindtags

    def _binding_tags(self) -> tuple[str, ...]:
        """The tags to consult, honouring any set by :meth:`bindtags`."""
        if self._bindtags is not None:
            return self._bindtags
        toplevel = self.winfo_toplevel()
        tags = [self._w, self.winfo_class()]
        if toplevel is not self:
            tags.append(toplevel._w)
        tags.append("all")
        return tuple(tags)

    def _bind_on(
        self,
        tag: str,
        sequence: str | None,
        func: Callable[[Event], Any] | None,
        add: bool | str | None,
    ) -> Any:
        """Shared implementation of the four ``bind`` variants."""
        if sequence is None:
            return self.tk.bindings.sequences(tag)
        pattern = parse_sequence(sequence)
        if func is None:
            return tuple(
                binding.func for binding in self.tk.bindings.bindings(tag, pattern)
            )
        return self.tk.bindings.bind(tag, pattern, func, add=bool(add))

    # ==================================================================
    # Virtual events
    # ==================================================================

    def event_add(self, virtual: str, *sequences: str) -> None:
        """Make each of ``sequences`` raise the virtual event ``virtual``."""
        self.tk.virtual_events.add(
            virtual, *(parse_sequence(sequence) for sequence in sequences)
        )

    def event_delete(self, virtual: str, *sequences: str) -> None:
        """Stop ``sequences`` raising ``virtual``; with none given, remove it."""
        self.tk.virtual_events.delete(
            virtual, *(parse_sequence(sequence) for sequence in sequences)
        )

    def event_info(self, virtual: str | None = None) -> tuple[str, ...]:
        """Sequences bound to ``virtual``, or every virtual event's name."""
        if virtual is None:
            return tuple(self.tk.virtual_events.names())
        return tuple(str(pattern) for pattern in self.tk.virtual_events.info(virtual))

    def event_generate(self, sequence: str, **kw: Any) -> None:
        """Deliver a synthetic event to this widget's bindings.

        Keyword arguments set fields on the :class:`Event` the callbacks receive,
        so a test or a widget can raise ``<<Paste>>`` or replay a click without a
        terminal in the loop.

        ``keysym=``, ``button=`` and ``state=`` also decide which bindings run,
        as Tk's ``-keysym``, ``-button`` and ``-state`` do: each takes the place
        of what the sequence said rather than adding to it. ``<KeyPress>`` with
        ``keysym="Up", state=1`` runs a ``<Shift-Key-Up>`` binding. ``state`` is
        Tk's number - see :class:`Event` - and anything but an integer is
        refused, as Tk refuses it.

        A key event's ``char`` is the character its keysym types, as in Tk -
        ``"z"`` for ``z``, ``"\\r"`` for ``Return``, ``""`` for ``Up`` - unless
        one is given. ``when="now"``, the default, delivers it before this
        returns; ``tail``, ``head`` and ``mark`` when the program next goes
        idle, as Tk's queue does at the next ``update``.

        TkCurses extension:
            Any :class:`Event` field may be given, ``char`` among them; Tk
            takes only its own options.
        """
        # Measured on Tk 9.0.2: <KeyPress> with keysym='Up', state=1 runs
        # <Shift-Key-Up>; <Shift-KeyPress-Up> with state=0 runs <Key-Up>;
        # <KeyPress-a> with keysym='b' runs <Key-b>; <ButtonPress-1> with
        # button=3 runs <Button-3>. Ours used them only to fill in the event.
        # TkCurses-vnmk.
        pattern = parse_sequence(sequence)
        if isinstance(pattern, PatternSequence):
            # Measured, Tk 9.0.2: event generate of a two-event sequence, or
            # of "ab", answers exactly this.
            raise TclError("only one event specification allowed")
        button = kw.pop("button", None)
        state = kw.pop("state", None)
        when = str(kw.pop("when", "now"))
        if when not in ("now", "head", "mark", "tail"):
            raise TclError(
                f'bad -when value "{when}": must be now, head, mark, or tail'
            )
        event = Event(widget=self, **kw)
        event.type = _event_type(pattern.type)
        if pattern.is_virtual:
            if state is not None:
                event.state = _tcl_integer(None, state)
            self._deliver_generated(event, [pattern], when)
            return
        detail, modifiers = pattern.detail, pattern.modifiers & ~MOD_ANY
        if pattern.type == "Key" and event.keysym:
            detail = event.keysym
        elif pattern.type == "Key":
            event.keysym = detail
        if pattern.type == "Key" and "char" not in kw:
            event.char = char_for_keysym(detail)
        if pattern.type.startswith("Button"):
            if button is not None:
                detail = str(_tcl_integer(None, button))
            with contextlib.suppress(ValueError):
                event.num = int(detail)
        if state is None:
            event.state = _tk_state(modifiers, generated=True)
        else:
            event.state = _tcl_integer(None, state)
            modifiers = _modifiers_of(event.state)
        patterns = [replace(pattern, detail=detail, modifiers=modifiers)]
        self._deliver_generated(event, patterns, when)

    def _deliver_generated(
        self, event: Event, patterns: list[EventPattern], when: str
    ) -> None:
        """Deliver a generated event now, or when the program next goes idle
        - where Tk's ``tail``, ``head`` and ``mark`` leave it in the queue
        for the next ``update``."""
        if when == "now":
            self._dispatch(event, patterns)
        else:
            self.after_idle(self._dispatch, event, patterns)

    # ==================================================================
    # Event delivery
    # ==================================================================

    def _handle(self, core: CoreEvent) -> bool:
        """Deliver one input event to this widget, returning True on break.

        The entry point the main loop uses once it has decided which widget an
        event belongs to.
        """
        if isinstance(core, MouseEvent):
            # The only report of where the mouse is; winfo_pointerxy() has
            # nothing else to go on, since curses cannot be asked.
            self.tk.pointer = (core.x, core.y)
            if core.state == "clicked":
                # ncurses merges a quick press and release into one CLICKED
                # report. Tk has no such event: a widget waits for the
                # release to decide whether the press counted, so delivering
                # only a press leaves a button held down for ever and never
                # invoked. The pair is put back here, where the knowledge that
                # curses coalesced them belongs.
                broke = self._handle(replace(core, state="pressed"))
                return self._handle(replace(core, state="released")) or broke
        pattern = pattern_for_event(core)
        return self._dispatch(Event._from_core(core, self), [pattern])

    def _binds(self, pattern: EventPattern) -> bool:
        """Whether anything on this widget's binding tags takes ``pattern``."""
        bindings = self.tk.bindings
        return any(
            next(iter(bindings.matching(tag, [pattern])), None) is not None
            for tag in self._binding_tags()
        )

    def _dispatch(self, event: Event, patterns: list[EventPattern]) -> bool:
        """Run the bindings matching ``patterns`` over this widget's tags.

        A physical event also raises whatever virtual events it is registered
        for, and within each tag they compete with its own bindings: one
        runs, as in Tk 9.0.2 - with ``<Control-v>`` and ``<<Paste>>`` both
        bound on one widget, only ``<Control-v>``; with ``<<Paste>>`` on the
        class instead, both. This used to run both on one tag.
        TkCurses-hkul.
        """
        if self._destroyed:
            return False
        all_patterns = list(patterns)
        raised: dict[str, Any] = {}
        for pattern in patterns:
            if not pattern.is_virtual:
                for name, rank in self.tk.virtual_events.raised_ranks(pattern).items():
                    raised[name] = rank
                    all_patterns.append(EventPattern(type="Virtual", detail=name))
        return self.tk.bindings.dispatch(
            self._binding_tags(), event, all_patterns, raised
        )

    # ==================================================================
    # Focus
    # ==================================================================

    def focus_set(self) -> None:
        """Give this widget the keyboard focus.

        The widget losing focus gets ``<FocusOut>`` and this one gets
        ``<FocusIn>``, in that order, which is the order Tk uses and the one
        an entry widget relies on to commit its value before the next one
        starts editing.
        """
        previous = self.tk.focus
        if previous is self:
            return
        self.tk.focus = self
        self.tk.focus_history[id(self.winfo_toplevel())] = self
        if previous is not None and previous.winfo_exists():
            previous.event_generate("<FocusOut>")
        self.event_generate("<FocusIn>")

    focus = focus_set

    def focus_force(self) -> None:
        """Take the focus.

        Identical to :meth:`focus_set`: the distinction in Tk is about wresting
        focus from another application's window, and a curses program owns the
        whole terminal already.
        """
        self.focus_set()

    def focus_get(self) -> Misc | None:
        """The widget with the keyboard focus, or None."""
        return self.tk.focus

    def focus_displayof(self) -> Misc | None:
        """The focused widget. There is one display, so this is :meth:`focus_get`."""
        return self.tk.focus

    def focus_lastfor(self) -> Misc:
        """The widget that last had focus in this widget's toplevel.

        Returns the toplevel itself if nothing in it has been focused, so the
        result is always something that can be focused.
        """
        toplevel = self.winfo_toplevel()
        last = self.tk.focus_history.get(id(toplevel))
        if last is None or not last.winfo_exists():
            return toplevel
        return last

    def tk_focusFollowsMouse(self) -> None:
        """Focus whichever widget the mouse is over.

        One-way, as in Tk: there is no call to turn it off again.
        """
        self.tk.focus_follows_mouse = True

    def tk_focusNext(self) -> Misc | None:
        """The next widget in tab order, or None if nothing can take focus."""
        return self._focus_step(1)

    def tk_focusPrev(self) -> Misc | None:
        """The previous widget in tab order."""
        return self._focus_step(-1)

    def _focus_step(self, direction: int) -> Misc | None:
        """Walk the focus order from this widget by one step, wrapping around.

        Tab order is the order widgets were created within the toplevel, which
        is the order they appear in each parent's children — the same rule Tk
        uses, and the reason reordering a layout does not reorder tabbing.

        The walk starts from this widget's place in that order **whether or
        not tabbing could stop on it**, as ``tk::FocusNext`` and
        ``tk::FocusPrev`` walk the tree from the widget itself. A clicked
        scrollbar has the focus and is no Tab stop; looking it up among the
        stops instead sent Tab back to the first one in the window and
        Shift-Tab to the last.
        """
        toplevel = self.winfo_toplevel()
        order = [widget for widget in toplevel._subtree() if widget is not toplevel]
        count = len(order)
        if self is toplevel:
            # Before the first, or after the last.
            index = -1 if direction > 0 else count
        else:
            index = order.index(self)
        for step in range(1, count + 1):
            candidate = order[(index + step * direction) % count]
            if candidate._focus_ok():
                return candidate
        return None

    def _focus_ok(self) -> bool:
        """Whether tabbing may stop on this widget.

        Tk settles this in ``::tk::FocusOK``, and it is three rules rather
        than one:

        * ``takefocus`` set to false - never.
        * ``takefocus`` set to true - always, **disabled or not**. A caller
          who named it meant it.
        * ``takefocus`` left alone - only while the widget is not disabled.

        The third is the one that was missing, so tabbing stopped on widgets
        that could not be typed into and said nothing about why; the next Tab
        moved on, making it read as a dead stop rather than a skipped one.

        The distinction needs to know whether ``takefocus`` was *asked for* or
        merely defaulted, which a bool cannot hold - hence
        ``_takefocus_given``. Tk keeps the same distinction by defaulting the
        option to the empty string rather than to a truth value.
        """
        if not self._takefocus:
            return False
        if self._takefocus_given:
            return True
        return str(self._options.get("state", "normal")) != "disabled"

    def _subtree(self) -> Iterator[Misc]:
        """This widget and its descendants, parents before children."""
        yield self
        for child in list(self.children.values()):
            yield from child._subtree()

    # ==================================================================
    # Event scheduling
    # ==================================================================

    def after(
        self, ms: int, func: Callable[..., Any] | None = None, *args: Any
    ) -> str | None:
        """Run ``func`` after ``ms`` milliseconds; return a cancellable handle.

        Without ``func`` this sleeps, as tkinter's does. That blocks the event
        loop for the whole delay and the display stops responding, which is
        why the callback form is the one to reach for; the blocking form is
        kept only because tkinter has it.
        """
        if func is None:
            time.sleep(ms / 1000.0)
            return None
        return self.tk.timers.after(ms, func, *args, owner=self._w)

    def after_idle(self, func: Callable[..., Any], *args: Any) -> str:
        """Run ``func`` when the event loop next has nothing else to do."""
        return self.tk.timers.after_idle(func, *args, owner=self._w)

    def after_cancel(self, id: str) -> None:
        """Cancel a scheduled callback.

        Raises:
            ValueError: If ``id`` is None, as tkinter does. Cancelling a
                handle that has already fired is not an error.
        """
        if id is None:
            raise ValueError("id must be a valid identifier returned from after")
        self.tk.timers.cancel(id)

    def after_info(self, id: str | None = None) -> Any:
        """Handles still scheduled, or ``(func, args, kind)`` for one of them."""
        return self.tk.timers.info(id)

    # ==================================================================
    # Audio
    # ==================================================================

    def bell(self, displayof: int = 0) -> None:  # noqa: ARG002 - tkinter signature
        """Ring the terminal bell.

        Whether anything is heard is the terminal emulator's decision; many
        flash the screen instead, and some do nothing at all.
        """
        if self.tk.screen is not None and self.tk.screen.started:
            with contextlib.suppress(_curses.error):
                _curses.beep()
            return
        with contextlib.suppress(OSError, ValueError):
            sys.stdout.write("\a")
            sys.stdout.flush()

    # ==================================================================
    # Clipboard and selection
    # ==================================================================

    def _copy_on_interrupt(self) -> bool:
        """Copy instead of closing, if the focused widget has a selection.

        Ctrl-C is the close gesture here (TkCurses-7l6), and Tk's copy key.
        Measured in the author's terminal (TkCurses-lw2), no OTHER copy key
        of Tk's reaches a program: Ctrl-Insert and Ctrl-Shift-V arrive as
        nothing, Ctrl-Shift-C arrives as plain Ctrl-C, and Alt-W as Escape
        then w. So the decision, the author's: **Ctrl-C copies when the focused
        widget has something selected, and closes otherwise.** Close stays
        one keystroke away - press it again once the selection is gone - and
        an application that binds ``<Control-c>`` still takes the key
        entirely, as before.

        Returns True if it copied, in which case nothing closes.
        """
        focused = self.focus_get()
        if focused is None or not focused._has_copyable_selection():
            return False
        focused.event_generate("<<Copy>>")
        return True

    def _focused_cursor_style(self) -> CursorStyle:
        """What the focused widget asks of the terminal cursor's look."""
        focused = self.tk.focus
        return TERMINALS_OWN if focused is None else focused._cursor_style()

    def _cursor_style(self) -> CursorStyle:
        """Nothing, for anything with no insertion cursor of its own."""
        return TERMINALS_OWN

    def _focused_insert_cell(self) -> tuple[int, int] | None:
        """Where the terminal's cursor belongs: the focused widget's insert point.

        None when nothing has the focus, or what has it takes no typing - or
        the insert point is in a part of the widget that is clipped away,
        where Tk's own cursor would not show either.
        """
        focused = self.tk.focus
        cell = None if focused is None else focused._insert_cell()
        panel = getattr(focused, "_panel", None)
        if cell is None or panel is None:
            return cell
        row, column = cell
        return cell if panel.rect.contains_point(Point(column, row)) else None

    def _insert_cell(self) -> tuple[int, int] | None:
        """The screen cell, ``(row, column)``, where typing would go here.

        None for a widget that takes no typing; Entry and Text say otherwise.
        """
        return None

    def _has_copyable_selection(self) -> bool:
        """Whether this widget has a selection Ctrl-C should copy.

        False here; Entry and Text, which bind ``<<Copy>>``, say otherwise.
        See :meth:`_copy_on_interrupt`.
        """
        return False

    def clipboard_get(self, **kw: Any) -> str:
        """Return the clipboard contents.

        Raises:
            TclError: If nothing has been copied, as tkinter does when no
                application owns the selection.
        """
        return self.tk.selections.get(kw.get("selection", CLIPBOARD))

    def clipboard_clear(self, **kw: Any) -> None:
        """Empty the clipboard."""
        self.tk.selections.clear(kw.get("selection", CLIPBOARD))

    def clipboard_append(self, string: str, **kw: Any) -> None:
        """Add ``string`` to the clipboard, claiming it if it was empty."""
        selection = kw.get("selection", CLIPBOARD)
        self.tk.selections.append(string, selection)
        self.tk.selections.own(self, selection)

    def selection_get(self, **kw: Any) -> str:
        """Return the selection, asking its owner's handler if it has one."""
        return self.tk.selections.resolve(kw.get("selection", PRIMARY))

    def selection_clear(self, **kw: Any) -> None:
        """Release the selection."""
        selection = kw.get("selection", PRIMARY)
        self.tk.selections.clear(selection)
        if self.tk.selections.owner(selection) is self:
            self.tk.selections.disown(self)

    def selection_own(self, **kw: Any) -> None:
        """Claim the selection for this widget.

        ``command``, as in tkinter, is called when another widget takes it.
        """
        self.tk.selections.own(
            self, kw.get("selection", PRIMARY), lost=kw.get("command")
        )

    def image_names(self) -> tuple[str, ...]:
        """The names of every image this application still holds.

        "Still" is the operative word, and it is not a quirk of this
        implementation: an image nothing references is collected, so a name
        can leave this list without anything having deleted it. That is Tk's
        behaviour too, and the registry is weak in order to keep it.
        """
        return tuple(sorted(self.tk.images))

    def image_types(self) -> tuple[str, ...]:
        """The image types that can be created, in Tk's order."""
        return ("photo", "bitmap")

    def selection_own_get(self, **kw: Any) -> Misc:
        """The widget owning the selection.

        Raises:
            TclError: If nothing owns it, matching tkinter.
        """
        selection = kw.get("selection", PRIMARY)
        owner: Misc | None = self.tk.selections.owner(selection)
        if owner is None:
            raise TclError(f"selection {selection} doesn't exist or form unknown")
        return owner

    def selection_handle(self, command: Callable[..., str], **kw: Any) -> None:
        """Supply the selection's contents from ``command`` when it is asked for."""
        self.tk.selections.handle(self, command, kw.get("selection", PRIMARY))

    # ==================================================================
    # Grab
    # ==================================================================

    def grab_set(self) -> None:
        """Direct events to this widget and its children only.

        How a modal dialog stays modal. The main loop honours it when deciding
        where an event goes.
        """
        self.tk.grab = self
        self.tk.grab_global = False

    def grab_set_global(self) -> None:
        """Grab globally.

        A curses application already owns the terminal, so this differs from
        :meth:`grab_set` only in what :meth:`grab_status` reports.
        """
        self.tk.grab = self
        self.tk.grab_global = True

    def grab_release(self) -> None:
        """Release the grab, if this widget holds it."""
        if self.tk.grab is self:
            self.tk.grab = None
            self.tk.grab_global = False

    def grab_current(self) -> Misc | None:
        """The widget holding the grab, or None."""
        return self.tk.grab

    def grab_status(self) -> str | None:
        """``"local"``, ``"global"``, or None if this widget has no grab."""
        if self.tk.grab is not self:
            return None
        return "global" if self.tk.grab_global else "local"

    # ==================================================================
    # Busy
    # ==================================================================

    # Tk's busy command, ``tk busy``. Tk maps a transparent window over the
    # one held, which takes every pointer event meant for it or its
    # descendants and shows a busy cursor. Here there is no window to map and
    # no cursor to show, and the router drops those pointer events instead:
    # see _busy_covers. Keyboard events are not stopped, as the busy manual
    # says they are not - a widget with the focus keeps it.

    def tk_busy_hold(self, **kw: Any) -> None:
        """Make this window busy: the pointer reaches neither it nor any of
        its descendants until :meth:`tk_busy_forget`.

        Keys still do - a widget inside that has the focus keeps it, and
        Tab can still reach one - so a program that wants the keyboard kept
        out too moves the focus elsewhere, as it would with Tk. Holding a
        window already held configures it.

        Args:
            **kw: The busy options: ``cursor``, kept and read back, since a
                terminal has no pointer to change.

        Raises:
            TclError: If an option is unknown or its value is refused. The
                window is busy all the same, as in Tk.

        Differences from tkinter:
            Nothing is drawn over a busy window, and the pointer's shape does
            not change.
        """
        path = str(self)
        if path not in self.tk.busy:
            self.tk.busy[path] = (self, {"cursor": "watch"})
        self.tk_busy_configure(**kw)

    busy = busy_hold = tk_busy = tk_busy_hold

    def _busy_options(self) -> dict[str, Any]:
        """This window's busy options, refused if it is not busy."""
        held = self.tk.busy.get(str(self))
        if held is None or held[0] is not self or not self.winfo_exists():
            raise TclError(f'cannot find busy window "{self}"')
        return held[1]

    def tk_busy_cget(self, option: str) -> Any:
        """The value of one busy option of this busy window.

        Raises:
            TclError: If the window is not busy, or the option is unknown.
        """
        options = self._busy_options()
        if option not in options:
            raise TclError(f'unknown option "-{option}"')
        return options[option]

    busy_cget = tk_busy_cget

    def tk_busy_configure(
        self, cnf: dict[str, Any] | str | None = None, **kw: Any
    ) -> Any:
        """Query or set this busy window's options, as :meth:`configure`
        does a widget's: with none, each option's five-tuple; with a name,
        that option's.

        Raises:
            TclError: If the window is not busy, or an option or value is
                refused.
        """
        options = self._busy_options()
        if isinstance(cnf, str):
            if cnf not in options:
                raise TclError(f'unknown option "-{cnf}"')
            return (cnf, cnf, cnf.capitalize(), "watch", options[cnf])
        given = {**(cnf or {}), **kw}
        if not given:
            return {
                name: (name, name, name.capitalize(), "watch", value)
                for name, value in options.items()
            }
        for name, value in given.items():
            if name not in options:
                raise TclError(f'unknown option "-{name}"')
            options[name] = _cursor_spec(self, value)
        return None

    busy_config = busy_configure = tk_busy_config = tk_busy_configure

    def tk_busy_current(self, pattern: str | None = None) -> list[Misc]:
        """The busy windows, or those whose path names match the glob
        ``pattern``."""
        found = []
        for path, (widget, _options) in list(self.tk.busy.items()):
            if not widget.winfo_exists():
                del self.tk.busy[path]
            elif pattern is None or fnmatch.fnmatchcase(path, pattern):
                found.append(widget)
        return found

    busy_current = tk_busy_current

    def tk_busy_forget(self) -> None:
        """Make this window take the pointer again.

        Raises:
            TclError: If it is not busy.
        """
        self._busy_options()
        del self.tk.busy[str(self)]

    busy_forget = tk_busy_forget

    def tk_busy_status(self) -> bool:
        """Whether this window is busy - itself, not one it is inside."""
        held = self.tk.busy.get(str(self))
        return held is not None and held[0] is self and self.winfo_exists()

    busy_status = tk_busy_status

    def _busy_covers(self) -> bool:
        """Whether a busy window takes the pointer from this widget: it is
        busy, or inside one that is."""
        busy = self.tk.busy
        if not busy:
            return False
        return any(
            str(each) in busy and busy[str(each)][0] is each
            for each in self._ancestry()
        )

    # ==================================================================
    # Stacking
    # ==================================================================

    def tkraise(self, aboveThis: Misc | None = None) -> None:
        """Raise this widget above its siblings, or just above ``aboveThis``."""
        self._restack(aboveThis, above=True)

    lift = tkraise

    def lower(self, belowThis: Misc | None = None) -> None:
        """Lower this widget below its siblings, or just below ``belowThis``."""
        self._restack(belowThis, above=False)

    def _restack(self, other: Misc | None, above: bool) -> None:
        """Move this widget within its parent's child order.

        Sibling order *is* stacking order: the panel stack is rebuilt from it,
        so moving a widget here is what puts its window in front once one
        exists.
        """
        if self.master is None:
            return
        siblings = self.master.children
        if self._name not in siblings:
            return
        order = [name for name in siblings if name != self._name]
        if other is None:
            position = len(order) if above else 0
        else:
            try:
                index = order.index(other._name)
            except ValueError:
                return
            position = index + 1 if above else index
        order.insert(position, self._name)
        self.master.children = {name: siblings[name] for name in order}

    # ------------------------------------------------------ negotiation

    def _content_rect(self) -> Rect:
        """The region this container offers its children, in screen cells.

        The widget's own region less its border and padding, per
        ARCHITECTURE.md "Content Coordinate Rules": a bordered 30x8 window
        offers 28x6 starting one cell in.
        """
        rect = Rect(
            self.winfo_rootx(), self.winfo_rooty(), self._rect.width, self._rect.height
        )
        if _menubar_of(self) is not None:
            # A menubar sits inside the window's border and above everything
            # else in it, so the row it occupies is not the children's to
            # use. Taken off here rather than in each window class, because
            # this is the one place that decides what a container offers.
            rect = Rect(rect.x, rect.y + 1, rect.width, max(0, rect.height - 1))
        return content_rect(
            rect, bordered=self._border_drawn, padding=self._content_padding()
        )

    def _content_padding(self) -> Insets:
        """Space inside the border that this container keeps from its children.

        One method because TWO things need the same answer - :meth:`_content_rect`
        places the children and :meth:`_outer_size` asks the parent for room -
        and a container whose two halves disagree either clips its children or
        leaves a gap. The scrollbar that drew seven of its nine rows was two
        predicates disagreeing in exactly this way.

        Overridable so a themed widget can add ttk's ``-padding`` to it.
        """
        return Insets.symmetric(
            horizontal=_as_int(self._options.get("padx", 0), 0),
            vertical=_as_int(self._options.get("pady", 0), 0),
        )

    def _outer_size(self, content: Size) -> Size:
        """How big this widget must be to offer ``content`` cells inside it.

        The inverse of :meth:`_content_rect`, and the thing a container has
        to tell its parent: a geometry manager works out what the children
        need, which is a *content* size, and the container is bigger than
        that by its own border, padding and menubar. Without this a bordered
        container sized to its children clips them by exactly its border.

        ``_bordered`` rather than ``_border_drawn``, deliberately: whether a
        border is drawn depends on the size the widget already has, and
        asking that here would be circular - a frame one row tall draws no
        border, so it would ask for no room for one, so it would stay one
        row tall.
        """
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        padding = self._content_padding()
        menu = 1 if _menubar_of(self) is not None else 0
        return Size(
            content.width + edge + padding.width,
            content.height + edge + padding.height + menu,
        )

    @property
    def _bordered(self) -> bool:
        """True if this widget draws a border, costing a cell on each edge.

        overrideredirect asks for a window a window manager leaves alone,
        which here means one that draws no decoration of its own.
        """
        if getattr(self, "_overrideredirect", False):
            return False
        return _draws_border(
            {
                "relief": self._drawn_relief(),
                "borderwidth": self._options.get("borderwidth", 0),
            }
        )

    #: The relief drawn when ``relief`` is ``""``, which only a themed widget
    #: takes: Tk answers ``""`` there, the theme's, and the theme here is
    #: drawn as this.
    _default_relief: ClassVar[str] = FLAT

    def _drawn_relief(self) -> str:
        """The relief to draw: the option, or the default it stands for."""
        return str(self._options.get("relief", "") or self._default_relief)

    @property
    def _border_drawn(self) -> bool:
        """True when there is a border *and* room on screen to draw it.

        A bordered widget too small for its own border draws none, so
        everything that measures the space left inside has to agree with the
        painting. It did not: an Entry squeezed to a single row subtracted
        an edge that was never drawn, came out with no content area at all,
        and rendered nothing - a blank rectangle indistinguishable from a
        widget that had failed to appear.
        """
        return self._bordered and self._rect.width >= 2 and self._rect.height >= 2

    def _restack_panels(self) -> None:
        """Put the panel stack back into tree order, parents behind children.

        ``_subtree`` yields a widget before its children, so raising each in
        turn leaves every child in front of its container and siblings in
        their own stacking order.
        """
        stack = self.tk.panels
        if stack is None:
            return
        for widget in self._subtree():
            panel = widget._panel
            if panel is not None and not panel.hidden:
                stack.raise_to_top(panel)

    def _redraw(self) -> None:
        """Repaint after this widget's window changed.

        Called whenever the window is created, replaced or moved - a resize
        builds a new curses window, so anything drawn into the old one is
        gone. Widgets that draw override this; the default does nothing,
        which is every widget until the widget set lands.
        """

    def _screen_rect(self) -> Rect:
        """Where this widget is on the screen, in absolute cells.

        ``_rect`` is an offset from the master; a curses panel is positioned
        absolutely. Confusing the two is invisible for a toplevel, whose
        master sits at the origin, and wrong for everything inside one.
        """
        x, y = self._root_offset()
        return Rect(x, y, self._rect.width, self._rect.height)

    def _visible_rect(self) -> Rect:
        """The part of this widget that is on the screen.

        A widget may be positioned partly or wholly outside the terminal -
        place() allows it and Tk clips the result - but a curses window may
        not: asking curses to move a panel past an edge fails outright, and
        the whole application goes down with it. The panel therefore covers
        the visible part only, while the widget's own geometry is left alone,
        so winfo_x() still reports where it was actually put.

        Nor does a widget show outside its master. X clips every window by
        its parent's, so in Tk a label placed 6 wide in a 5-wide pane shows 5
        cells and the pane's neighbour stays visible beside it; here it
        covered the sash, handle and all. Every ancestor clips, up to the
        enclosing toplevel, which only the screen does - TkCurses-wbov.
        """
        width, height = self._screen_size()
        return self._unclipped_part().intersection(Rect(0, 0, width, height))

    def _unclipped_part(self) -> Rect:
        """The part of this widget its ancestors leave showing, screen aside.

        Also what a click can reach: Tk's ``winfo containing`` passes over
        the part of a child its master clips away and finds whatever is
        underneath, measured against Tk 9.0.2.
        """
        visible = self._screen_rect()
        if self._is_toplevel or not self._clipped_by_master:
            return visible
        for ancestor in itertools.islice(self._ancestry(), 1, None):
            if not isinstance(ancestor, BaseWidget):
                # Only a widget has a window to clip by. The one Misc that is
                # not one is a bare root, which only a model of a tree has.
                break
            visible = visible.intersection(ancestor._clip_rect())
            if ancestor._is_toplevel or not ancestor._clipped_by_master:
                break
        return visible

    def _clip_rect(self) -> Rect:
        """The screen cells this widget's descendants may show in.

        All of it, as in X: a child may cover its container's own border.
        A toplevel keeps its border, because that border is the window
        manager's frame, which no window inside it can draw over - and a
        child placed at ``x=0`` already starts inside it.
        """
        rect = self._screen_rect()
        if self._is_toplevel and self._border_drawn:
            return content_rect(rect)
        return rect

    def _request_size(self, width: int, height: int) -> None:
        """Declare the size this widget would like to be.

        A widget calls this when its content changes - a label given longer
        text, a frame given another child. The request travels no further
        than it changes anything: the container is queued, and the run that
        follows stops at the first ancestor whose own size is unaffected.
        """
        requested = Size(max(0, width), max(0, height))
        if requested == self._requested:
            return
        self._requested = requested
        if self.master is not None:
            self.tk.layout.invalidate(self.master)
        host = self._manager_container
        if host is not None and host is not self.master:
            # Laid out by something other than its master - a canvas holding
            # a window of its parent's - which has to hear the new size.
            self.tk.layout.invalidate(host)
        if self._manager == "labelframe" and isinstance(
            self._manager_container, LabelFrame
        ):
            # A LabelFrame's label is in no layout to be re-placed by.
            self._manager_container._label_resized()

    def _invalidate_layout(self) -> None:
        """Ask for this container's children to be laid out again."""
        self.tk.layout.invalidate(self)

    def update_layout(self) -> int:
        """Lay out whatever is waiting, now, and answer the containers laid out.

        The main loop does this before drawing, so an application rarely needs
        to. A test that wants to read geometry without running a loop does.

        TkCurses extension:
            tkinter has no such method. :meth:`update_idletasks` lays widgets
            out too, and redraws.
        """
        return self.tk.layout.run()

    def _propagate_flag(self, flag: bool | None) -> bool:
        """Shared implementation of pack_propagate and grid_propagate."""
        if flag is None:
            return self._layout_propagate
        self._layout_propagate = bool(flag)
        if self._layout_propagate:
            self._invalidate_layout()
        return self._layout_propagate

    def pack_slaves(self) -> list[Misc]:
        """The children this container is packing, in packing order."""
        manager = self._layout_manager
        if not isinstance(manager, PackLayout):
            return []
        # cast, with a reason: a geometry manager hands back exactly the
        # objects it was given, and in this library those are always widgets.
        # It describes them as Managed because that is all IT needs of them -
        # see _core.geometry.Managed - while the public contract here is
        # tkinter's, a list of widgets. The cast is the one place that
        # difference is stated rather than papered over with Any. TkCurses-d40.
        return cast("list[Misc]", list(manager.slaves(self)))

    slaves: Any = pack_slaves

    def grid_slaves(
        self, row: int | None = None, column: int | None = None
    ) -> list[Misc]:
        """The children this container is gridding, optionally in one cell."""
        manager = self._layout_manager
        if not isinstance(manager, GridLayout):
            return []
        # cast, with a reason: a geometry manager hands back exactly the
        # objects it was given, and in this library those are always widgets.
        # It describes them as Managed because that is all IT needs of them -
        # see _core.geometry.Managed - while the public contract here is
        # tkinter's, a list of widgets. The cast is the one place that
        # difference is stated rather than papered over with Any. TkCurses-d40.
        return cast("list[Misc]", list(manager.slaves(self, row=row, column=column)))

    def grid_size(self) -> tuple[int, int]:
        """The grid's extent as ``(columns, rows)``."""
        manager = self._layout_manager
        return manager.size() if isinstance(manager, GridLayout) else (0, 0)

    def grid_bbox(
        self,
        column: int | None = None,
        row: int | None = None,
        col2: int | None = None,
        row2: int | None = None,
    ) -> tuple[int, int, int, int]:
        """The region a cell or range of cells covers, in screen cells."""
        manager = self._layout_manager
        if not isinstance(manager, GridLayout):
            return (0, 0, 0, 0)
        if column is None or row is None:
            columns, rows = manager.size()
            return manager.bbox(
                self._content_rect(), 0, 0, max(0, columns - 1), max(0, rows - 1)
            )
        return manager.bbox(
            self._content_rect(),
            column,
            row,
            col2 if col2 is not None else column,
            row2 if row2 is not None else row,
        )

    def grid_location(self, x: int, y: int) -> tuple[int, int]:
        """The cell at a screen position, or ``(-1, -1)`` outside the grid."""
        manager = self._layout_manager
        if not isinstance(manager, GridLayout):
            return (-1, -1)
        return manager.location(self._content_rect(), x, y)

    def grid_anchor(self, anchor: str | None = None) -> str:
        """Get or set where the grid sits when it is smaller than its container."""
        manager = _grid_layout_of(self)
        if anchor is not None:
            if anchor != "center":
                # Validate before storing, so a bad anchor fails here rather
                # than during the next layout.
                try:
                    parse_sticky(anchor)
                except ValueError as error:
                    raise TclError(str(error)) from None
            manager.anchor = anchor
            self.tk.layout.invalidate(self)
        return manager.anchor

    def grid_rowconfigure(
        self, index: int, cnf: dict[str, Any] | str | None = None, **kw: Any
    ) -> Any:
        """Get or set how one row behaves: weight, minsize, pad, uniform."""
        return self._line_configure("row", index, cnf, kw)

    def grid_columnconfigure(
        self, index: int, cnf: dict[str, Any] | str | None = None, **kw: Any
    ) -> Any:
        """Get or set how one column behaves."""
        return self._line_configure("column", index, cnf, kw)

    rowconfigure = grid_rowconfigure
    columnconfigure = grid_columnconfigure

    def _line_configure(
        self,
        axis: str,
        index: int,
        cnf: dict[str, Any] | str | None,
        kw: dict[str, Any],
    ) -> Any:
        """Shared implementation of grid_rowconfigure and grid_columnconfigure.

        Raises:
            TclError: If an option is not one Tk accepts for a grid line.
        """
        manager = _grid_layout_of(self)
        current = (
            manager.row_config(index) if axis == "row" else manager.column_config(index)
        )
        listing = {
            "weight": current.weight,
            "minsize": current.minsize,
            "pad": current.pad,
            "uniform": current.uniform,
        }
        if isinstance(cnf, str):
            # grid_columnconfigure(0, "weight") asks for one value. It crashed
            # here on "'str' object is not a mapping" - TkCurses-bx5b, found
            # beside the None handling; TkCurses-kifn was the same for
            # configure. Message measured on Tk 9.0.2.
            if cnf not in listing:
                raise TclError(
                    f'bad option "-{cnf}": must be -minsize, -pad, -uniform, or -weight'
                )
            return listing[cnf]
        # Measured: unlike configure, a call whose every option is None DOES
        # answer the listing in tkinter, since it checks after dropping them.
        given = _given(cnf, kw)
        if not given:
            return listing
        config = LineConfig(
            current.weight, current.minsize, current.pad, current.uniform
        )
        for name, value in given.items():
            if not hasattr(config, name):
                raise TclError(f'unknown option "-{name}"')
            if name == "uniform":
                config.uniform = str(value)
            else:
                try:
                    setattr(config, name, max(0, int(value)))
                except (TypeError, ValueError):
                    raise TclError(f'expected integer but got "{value}"') from None
        if axis == "row":
            manager.configure_row(index, config)
        else:
            manager.configure_column(index, config)
        self.tk.layout.invalidate(self)
        return None

    def place_slaves(self) -> list[Misc]:
        """The children this container is placing."""
        manager = self._place_manager
        if not isinstance(manager, PlaceLayout):
            return []
        # cast, with a reason: a geometry manager hands back exactly the
        # objects it was given, and in this library those are always widgets.
        # It describes them as Managed because that is all IT needs of them -
        # see _core.geometry.Managed - while the public contract here is
        # tkinter's, a list of widgets. The cast is the one place that
        # difference is stated rather than papered over with Any. TkCurses-d40.
        return cast("list[Misc]", list(manager.slaves(self)))

    def pack_propagate(self, flag: bool | None = None) -> bool:
        """Get or set whether this container resizes to fit its children.

        Switched off, the container keeps whatever size it was given and its
        children are laid out inside that, however little room it leaves.
        Tk offers one flag per manager name; there is one container and one
        setting, so these are the same flag under three spellings, as they
        effectively are in Tk.
        """
        return self._propagate_flag(flag)

    grid_propagate = pack_propagate
    propagate = pack_propagate

    # ==================================================================
    # Window information
    # ==================================================================

    def winfo_children(self) -> list[Misc]:
        """This widget's children, in stacking order.

        A child whose creation failed is not among them; as in tkinter it stays in
        ``children``, without a window.
        """
        # See _abandon.
        return [child for child in self.children.values() if not child._destroyed]

    def winfo_class(self) -> str:
        """The widget's class name, as bindings and the option database use it."""
        return type(self).__name__

    def winfo_name(self) -> str:
        """The widget's name within its parent; for the root, the
        application's name, as in Tk - its class name with the first letter
        in lower case, ``tk`` for a ``Tk()``."""
        if self.master is None:
            return self._app_name()
        return self._name

    def _app_name(self) -> str:
        """The application's name: the root's class name, first letter
        lowered, as tkinter makes it."""
        name = str(getattr(self._root(), "className", "Tk"))
        return name[:1].lower() + name[1:]

    def winfo_parent(self) -> str:
        """The parent's path name, empty for the root."""
        return "" if self.master is None else self.master._w

    def winfo_id(self) -> int:
        """A stable identifier for this widget.

        Tk returns an X window id. There are no windows to have ids, so the
        object's identity stands in: unique, stable for the widget's life, and
        meaningless to compare across runs, which is also true of the original.
        """
        return id(self)

    def winfo_exists(self) -> bool:
        """False once the widget has been destroyed."""
        return not self._destroyed

    def winfo_ismapped(self) -> bool:
        """True if a geometry manager has placed this widget."""
        return self._mapped

    def winfo_viewable(self) -> bool:
        """True if this widget and every ancestor are mapped.

        A mapped widget inside an unmapped frame is not on screen, which is
        the distinction this draws against :meth:`winfo_ismapped`. The root
        is exempt: nothing manages it, and the terminal is always there.
        """
        for widget in self._ancestry():
            if widget.master is not None and not widget._mapped:
                return False
        return True

    def _leave_for(self, container: Misc, manager: str = "") -> None:
        """Leave the container laying this widget out, before ``container``
        takes it on with ``manager`` - unless that is the same container and
        manager, which is a reconfigure.

        A LabelFrame's label packed into that same frame is not told here;
        the frame sees its label's manager has changed when it next looks.
        """
        previous = self._manager_container
        if previous is None:
            return
        # Between place and pack or grid in one container is a move as well:
        # each has its own layout there, and Tk takes the widget out of the
        # one it leaves. TkCurses-huq9.
        if previous is not container or (manager and manager != self._manager):
            self._leave_layout(previous)

    def _leave_manager(self) -> None:
        """Leave whichever geometry manager lays this widget out, if any."""
        container = self._manager_container
        if container is not None:
            self._leave_layout(container)
        self._manager = ""
        self._manager_container = None

    def _leave_layout(self, container: Misc) -> None:
        """Take this widget out of one container's layout.

        Called when a geometry call moves the widget somewhere else.
        Without it the container being left goes on laying the widget out:
        a widget moved with ``in_`` is then managed twice over, and drawn
        wherever the first of the two decides.
        """
        if isinstance(container, LabelFrame) and self._manager == "labelframe":
            container._label_taken(self)
            return
        layout = container._manager_layout(self._manager)
        if layout is None:
            return
        layout.remove(self)
        container.tk.layout.invalidate(container)

    def _manager_layout(self, name: str) -> Layout | None:
        """The layout ``name`` uses in this container: place and a paned
        window's panes have their own."""
        if name == "place":
            return self._place_manager
        if name == "panedwindow":
            return self._paned_manager
        if name in ("canvas", "text"):
            return self._embed_manager
        return self._layout_manager

    def _managed_layout(self, name: str) -> Layout | None:
        """The layout currently laying this widget out, if ``name`` is it.

        Tk merges every geometry reconfigure into the options the widget
        already has, and keeps doing so when it moves to a different
        container: ``place_configure(in_=other, x=5)`` leaves the anchor and
        the width alone. Only ``forget`` resets them - checked against Tk
        9.0.2, where a place after ``place_forget`` comes back with
        ``anchor=nw``. Those options live with the container doing the
        laying out, which ``in_`` allows to be something other than the
        master, so this is where a reconfigure goes looking for them.
        """
        if self._manager != name or self._manager_container is None:
            return None
        return self._manager_container._manager_layout(name)

    def winfo_manager(self) -> str:
        """The geometry manager handling this widget, or an empty string."""
        return self._manager

    def winfo_toplevel(self) -> Misc:
        """The nearest enclosing toplevel window."""
        widget = self
        while widget.master is not None and not widget._is_toplevel:
            widget = widget.master
        return widget

    def winfo_x(self) -> int:
        """Column offset within the parent, in cells."""
        return self._rect.x

    def winfo_y(self) -> int:
        """Row offset within the parent, in cells."""
        return self._rect.y

    def winfo_width(self) -> int:
        """Width in cells."""
        return self._rect.width

    def winfo_height(self) -> int:
        """Height in cells."""
        return self._rect.height

    def winfo_reqwidth(self) -> int:
        """Width the widget asked for, which may exceed what it was given."""
        return self._requested.width

    def winfo_reqheight(self) -> int:
        """Height the widget asked for."""
        return self._requested.height

    def winfo_rootx(self) -> int:
        """Column on the screen, in cells."""
        return self._root_offset()[0]

    def winfo_rooty(self) -> int:
        """Row on the screen, in cells."""
        return self._root_offset()[1]

    def _root_offset(self) -> tuple[int, int]:
        """Screen position, summing offsets up to the enclosing toplevel.

        The walk stops there rather than continuing to the root, because a
        toplevel's position is where it sits on the screen, not an offset from
        the widget it happened to be created under. Summing past it would move
        every dialog by its owner's position.
        """
        x = y = 0
        for widget in self._ancestry():
            x += widget._rect.x
            y += widget._rect.y
            if widget._is_toplevel:
                break
        return x, y

    def winfo_geometry(self) -> str:
        """Size and position as ``WxH+X+Y``, in cells."""
        return (
            f"{self.winfo_width()}x{self.winfo_height()}+{self._rect.x}+{self._rect.y}"
        )

    def winfo_containing(
        self,
        rootX: int,
        rootY: int,
        displayof: Any = 0,  # noqa: ARG002 - one terminal is one display
    ) -> Misc | None:
        """The topmost widget at a screen position, or None.

        Later siblings are on top, so the search runs back to front and takes
        the first hit, which is the widget a click at that cell would reach.
        ``displayof`` is accepted and has nothing to choose between: a
        terminal is one display.
        """
        return self._root()._containing(rootX, rootY)

    def _containing(self, x: int, y: int) -> Misc | None:
        """Depth-first hit test, topmost child first."""
        for child in reversed(list(self.children.values())):
            hit = child._containing(x, y)
            if hit is not None:
                return hit
        if not self._mapped:
            return None
        if self._unclipped_part().contains_point(Point(x, y)):
            return self
        return None

    def winfo_screenwidth(self) -> int:
        """Terminal width in cells."""
        return self._screen_size()[0]

    def winfo_screenheight(self) -> int:
        """Terminal height in cells."""
        return self._screen_size()[1]

    def winfo_vrootwidth(self) -> int:
        """Virtual root width. A terminal has no virtual desktop, so the screen."""
        return self.winfo_screenwidth()

    def winfo_vrootheight(self) -> int:
        """Virtual root height."""
        return self.winfo_screenheight()

    def winfo_vrootx(self) -> int:
        """Virtual root position across: 0, as there is no virtual desktop."""
        return 0

    def winfo_vrooty(self) -> int:
        """Virtual root position down: 0, as there is no virtual desktop."""
        return 0

    def winfo_screenmmwidth(self) -> int:
        """The screen's width in millimetres, at the ten cells to the inch
        every distance here is converted at."""
        return round(self.winfo_screenwidth() / _CELLS_PER_INCH * 25.4)

    def winfo_screenmmheight(self) -> int:
        """The screen's height in millimetres, at ten cells to the inch - a
        row taken as a cell, as ``winfo_fpixels`` takes it."""
        return round(self.winfo_screenheight() / _CELLS_PER_INCH * 25.4)

    def winfo_screen(self) -> str:
        """The terminal the application draws on - its device, such as
        ``/dev/pts/3`` - where Tk names an X display. Empty if there is none.
        """
        for stream in (sys.stdout, sys.stdin):
            with contextlib.suppress(AttributeError, OSError, ValueError):
                return os.ttyname(stream.fileno())
        return ""

    def winfo_server(self) -> str:
        """What draws the screen: TkCurses and the terminal type, where Tk
        names the X server's version and vendor."""
        return f"TkCurses {__version__} {os.environ.get('TERM', '')}".rstrip()

    def winfo_visual(self) -> str:
        """The screen's visual class, by how much colour the terminal has:
        ``truecolor`` for direct colour, ``staticcolor`` for a fixed palette,
        ``staticgray`` for none."""
        depth = self.winfo_colordepth()
        if depth >= ColorDepth.DIRECT:
            return "truecolor"
        return "staticcolor" if depth > ColorDepth.NONE else "staticgray"

    winfo_screenvisual = winfo_visual

    def winfo_visualid(self) -> str:
        """The screen's one visual, as Tk names a visual: a hexadecimal id.
        It is its depth."""
        return hex(self.winfo_depth())

    def winfo_visualsavailable(self, includeids: bool = False) -> list[tuple[Any, ...]]:
        """The visuals there are: the one the terminal has, as ``(class,
        depth)``, or ``(class, depth, id)`` with ``includeids``."""
        found: tuple[Any, ...] = (self.winfo_visual(), self.winfo_depth())
        if includeids:
            found += (self.winfo_depth(),)
        return [found]

    def winfo_screencells(self) -> int:
        """The colours in the screen's palette, as :meth:`winfo_cells`."""
        return self.winfo_cells()

    def winfo_colormapfull(self) -> bool:
        """False: a terminal's palette is fixed, and never fills."""
        return False

    def winfo_interps(self, displayof: Any = 0) -> tuple[str, ...]:
        """The applications that :meth:`send` can reach: this one."""
        del displayof
        return (self._app_name(),)

    def winfo_atom(self, name: str, displayof: Any = 0) -> int:
        """The number of the atom ``name``, made if it is new - X's own
        numbers for its predefined atoms, ``PRIMARY`` being 1."""
        del displayof
        atoms = self.tk.atoms
        text = str(name)
        if text not in atoms:
            atoms[text] = max(atoms.values()) + 1
        return atoms[text]

    def winfo_atomname(self, id: Any, displayof: Any = 0) -> str:
        """The name of the atom numbered ``id``.

        Raises:
            TclError: If ``id`` is not a whole number, or no atom has it.
        """
        del displayof
        number = _tcl_number(id)
        if not isinstance(number, int) or isinstance(number, bool):
            raise TclError(f'expected integer but got "{id}"')
        for name, each in self.tk.atoms.items():
            if each == number:
                return name
        raise TclError(f'no atom exists with id "{number}"')

    def winfo_pathname(self, id: Any, displayof: Any = 0) -> str:
        """The path name of the widget whose :meth:`winfo_id` is ``id``.

        Raises:
            TclError: If ``id`` is not a whole number, or names no widget.
        """
        del displayof
        number = _tcl_number(id)
        if not isinstance(number, int) or isinstance(number, bool):
            raise TclError(f'expected integer but got "{id}"')
        for path in self.tk.widgets:
            widget = self.tk.widgets.get(path)
            if widget is not None and widget.winfo_id() == number:
                return str(widget)
        raise TclError(f'window id "{hex(number)}" does not exist in this application')

    def send(self, interp: str, cmd: str, *args: Any) -> Any:
        """Run a command in the application named ``interp`` - which can
        only be this one, as there is no other to reach.

        Raises:
            TclError: If ``interp`` names another application, as Tk's
                ``no application named``.
        """
        if str(interp) != self._app_name():
            raise TclError(f'no application named "{interp}"')
        return self.tk.call(cmd, *args)

    # ------------------------------------------------------------ palette

    def tk_setPalette(self, *args: Any, **kw: Any) -> None:
        """Recolour every widget from one background colour, or from named
        colours, and make the colours the default for widgets made later.

        Given a background alone, the rest are worked out from it as Tk
        works them out: a foreground black or white by its brightness, an
        active background lighter, a select background and trough darker.
        ``tk_setPalette("#336699")``; ``tk_setPalette(background="black",
        foreground="yellow")``; ``tk_setPalette("background", "black")``.

        Raises:
            TclError: If no background is given, or the names and colours do
                not pair up.

        Differences from tkinter:
            Tk on X11 also recolours ttk's ``default`` theme; the themed
            widgets here are left as they are. A widget's own default colour
            here is the terminal's, ``""``, where Tk's is a colour such as
            ``black``, and Tk compares against it in deciding which colours
            to keep for a class: one palette over another can leave a class
            a different colour for widgets made afterwards.
        """
        # Tk's ::tk_setPalette, palette.tcl (Tk 9.0).
        if self.winfo_colordepth() == ColorDepth.NONE:
            return
        words = [*args]
        for name, value in kw.items():
            words += [name, value]
        if len(words) == 1:
            new = {"background": str(words[0])}
        elif len(words) % 2:
            raise TclError("list must have an even number of elements")
        else:
            new = {str(words[i]): str(words[i + 1]) for i in range(0, len(words), 2)}
        if "background" not in new:
            raise TclError("must specify a background color")
        bg = _exact_rgb16(self, new["background"])
        bright = bg[0] + 1.5 * bg[1] + 0.5 * bg[2] > 100000
        new.setdefault("foreground", "black" if bright else "white")
        fg = _exact_rgb16(self, new["foreground"])
        darker = "#" + "".join(f"{(9 * c) // 2560:02x}" for c in bg)
        for name in (
            "activeForeground",
            "insertBackground",
            "selectForeground",
            "highlightColor",
        ):
            new.setdefault(name, new["foreground"])
        new.setdefault(
            "disabledForeground",
            "#"
            + "".join(
                f"{(3 * b + f) // 1024:02x}" for b, f in zip(bg, fg, strict=True)
            ),
        )
        new.setdefault("highlightBackground", new["background"])
        if "activeBackground" not in new:
            lights = []
            for c in bg:
                light = c // 256
                light += max((light * 15) // 100, (255 - light) // 3)
                lights.append(min(light, 255))
            new["activeBackground"] = "#" + "".join(f"{c:02x}" for c in lights)
        new.setdefault("selectBackground", darker)
        new.setdefault("troughColor", darker)
        new.setdefault("buttonBackground", new["background"])
        new.setdefault("selectColor", "white" if bright else "black")
        # Tk makes one of each classic widget, in a window of its own made
        # last, to tell an option-database default that applies from one that
        # does not. They are recoloured with the rest, and since 9.0 that is
        # before they are compared, so each leaves its class's colours in the
        # database at priority 60 - measured, and why this keeps them.
        root = self._root()
        holder = Frame(root, name="___tk_set_palette")
        prototypes = {}
        for class_name in _PALETTE_PROTOTYPES:
            made = globals()[class_name](holder, name=class_name.lower())
            prototypes[made.winfo_class()] = made
        try:
            self._recolor_tree(root, new, prototypes)
        finally:
            holder.destroy()
        for name, value in new.items():
            self.option_add(f"*{name}", value, "widgetDefault")

    def _recolor_tree(
        self, widget: Misc, colors: dict[str, str], prototypes: dict[str, Misc]
    ) -> None:
        """Give ``widget`` and everything inside it each colour it has an
        option for, as Tk's ``::tk::RecolorTree`` does - whatever it was set
        to before, in Tk 9.0 - and keep a colour that is not the class's
        default in the option database, for that class."""
        for name, value in colors.items():
            option = name.lower()
            try:
                entry = widget._configure_query(option)
            except (TclError, KeyError):
                continue
            if len(entry) != 5:
                continue
            widget.configure({option: value})
            default = widget.option_get(name, name[:1].upper() + name[1:])
            prototype = prototypes.get(widget.winfo_class())
            if not default or (
                prototype is not None and str(prototype.cget(option)) != str(default)
            ):
                default = entry[3]
            if _same_colour(widget, default, entry[4]):
                continue
            self.option_add(f"*{widget.winfo_class()}.{name}", value, 60)
        for child in widget.winfo_children():
            self._recolor_tree(child, colors, prototypes)

    def tk_bisque(self) -> None:
        """Recolour everything in Tk's old bisque palette, as Tk's
        ``::tk_bisque`` does."""
        self.tk_setPalette(
            "activeBackground", "#e6ceb1", "activeForeground", "black",
            "background", "#ffe4c4", "disabledForeground", "#b0b0b0",
            "foreground", "black", "highlightBackground", "#ffe4c4",
            "highlightColor", "black", "insertBackground", "black",
            "selectBackground", "#e6ceb1", "selectForeground", "black",
            "troughColor", "#cdb79e",
        )  # fmt: skip

    def tk_strictMotif(self, boolean: Any = None) -> bool:
        """Get or set Tk's ``tk_strictMotif`` flag, and answer it.

        Differences from tkinter:
            Kept and read back; it changes no binding here.
        """
        if boolean is not None:
            self.tk.strict_motif = bool(_tcl_boolean(self, boolean))
        return self.tk.strict_motif

    def info_patchlevel(self) -> _VersionInfo:
        """The version of Tcl that TkCurses follows, as tkinter answers it:
        ``major``, ``minor``, ``micro``, ``releaselevel`` and ``serial``."""
        major, minor, micro = (
            int(part) for part in str(self.tk.call("info", "patchlevel")).split(".")
        )
        return _VersionInfo(major, minor, micro, "final", 0)

    def winfo_cells(self) -> int:
        """Number of colours available, which is what Tk means by cells."""
        return _curses.COLORS if self.tk.screen is not None else 8

    def winfo_depth(self) -> int:
        """Bits per cell, derived from the colour count."""
        return max(1, self.winfo_cells().bit_length() - 1)

    def winfo_screendepth(self) -> int:
        """Bits per cell for the screen, which is the only display there is."""
        return self.winfo_depth()

    def winfo_rgb(self, color: str) -> tuple[int, int, int]:
        """A colour's channel values, 16 bits each, as tkinter reports them.

        For a name or a hex string the terminal cannot show exactly, this is
        what will actually be rendered rather than what was asked for:
        reporting the request back would hide the approximation, and how
        close it gets depends on how many colours the terminal has.
        """
        depth = self.winfo_colordepth()
        direct = rgb_for(color)
        rgb = (
            direct
            if direct is not None
            else palette_rgb(parse_color(color, depth), depth)
        )
        return (rgb[0] * 257, rgb[1] * 257, rgb[2] * 257)

    def winfo_colordepth(self) -> ColorDepth:
        """How many colours this terminal has, as a :class:`ColorDepth`.

        A terminal may have no colour, eight, sixteen, 256 or true colour, and
        anything drawing a colour ramp has to know which. Before there is a
        screen to ask, it is ``ColorDepth.BASIC``, the eight every colour
        terminal has.

        TkCurses extension:
            X has no such question: ``winfo_screendepth`` answers in bits per
            pixel, and a display has the full range either way.
        """
        colors = self.tk.colors
        return colors.depth if colors is not None else ColorDepth.BASIC

    def winfo_pixels(self, number: str | int | float) -> int:
        """Convert a screen distance to whole cells."""
        return round(self.winfo_fpixels(number))

    def winfo_fpixels(self, number: str | int | float) -> float:
        """Convert a screen distance to cells, keeping the fraction.

        tkinter accepts ``"2c"``, ``"1i"``, ``"10p"`` and ``"3m"`` as well as
        bare numbers. A cell is the unit here, at ten to the inch.

        Raises:
            TclError: If the distance cannot be parsed, as tkinter does.
        """
        if isinstance(number, (int, float)):
            return float(number)
        value = _distance_number(number)
        if value is None or math.isnan(value):
            raise TclError(f'expected screen distance or "" but got "{number}"')
        return float(value)

    def winfo_pointerx(self) -> int:
        """Column the mouse was last reported at."""
        return self.tk.pointer[0]

    def winfo_pointery(self) -> int:
        """Row the mouse was last reported at."""
        return self.tk.pointer[1]

    def winfo_pointerxy(self) -> tuple[int, int]:
        """Where the mouse was last reported, as ``(x, y)``."""
        return self.tk.pointer

    def _ancestry(self) -> Iterator[Misc]:
        """This widget and every ancestor, innermost first."""
        widget: Misc | None = self
        while widget is not None:
            yield widget
            widget = widget.master

    def _root(self) -> Misc:
        """The root widget of this application."""
        widget = self
        while widget.master is not None:
            widget = widget.master
        return widget

    def _screen_size(self) -> tuple[int, int]:
        """Terminal size in cells, from the screen if one is running.

        Before ``mainloop()`` there is no curses screen to ask, and the answer
        still has to be something usable, so the environment is consulted and
        a conventional 80x24 stands in when even that fails — output redirected
        to a file, most often.
        """
        screen = self.tk.screen
        if screen is not None and screen.started:
            size = screen.size
            return size.width, size.height
        try:
            terminal = os.get_terminal_size()
        except OSError:
            return 80, 24
        return terminal.columns, terminal.lines

    # ==================================================================
    # Event loop
    # ==================================================================

    def update_idletasks(self) -> None:
        """Run pending idle callbacks, lay widgets out and redraw, without
        touching input.

        Geometry is idle work, as in Tk, so ``update_idletasks`` followed by
        ``winfo_width`` gives the width a widget will have, and a change made
        during a long computation is on the screen when it returns.
        """
        # Measured on Tk 9.0.2: a packed Button reads winfo_width() 1 and is
        # unmapped before root.update_idletasks(), 62 and mapped after, and
        # the same from a child widget's update_idletasks. Here it only ran
        # the idle callbacks and read 0 (TkCurses-q6b1).
        self.tk.timers.run_idle()
        self._settle()

    def update(self) -> None:
        """Run pending callbacks, then lay widgets out and redraw.

        Idle work first, then anything whose timer has expired, which is the
        order the main loop uses. Input is not read here: draining the
        keyboard from inside a callback is what makes tkinter's ``update()``
        reentrant and dangerous, and the loop in Tk is the one place that does
        it.
        """
        self.tk.timers.run_idle()
        self.tk.timers.run_due()
        self._settle()

    def _settle(self) -> None:
        """Lay out what is waiting and show it, as the main loop does after
        its callbacks."""
        self.tk.layout.run()
        announce = getattr(self._root(), "_announce_mapped", None)
        if announce is not None:
            announce()
        show = getattr(self._root(), "_update_display", None)
        if show is not None:
            show()

    def wait_variable(self, name: Variable) -> None:
        """Run the event loop until ``name`` is written to.

        A modal wait: it returns when something sets the variable, and hangs
        if nothing ever does - which is Tk's behaviour too, and why the usual
        caller is a dialog that has already arranged for a button to set it.
        """
        variable = (
            name if isinstance(name, Variable) else _NamedVariable(self, str(name))
        )
        written: list[bool] = []
        handle = variable._watch(lambda: written.append(True))
        try:
            self._wait_until(lambda: bool(written))
        finally:
            variable._unwatch(handle)

    waitvar = wait_variable

    def wait_window(self, window: Misc | None = None) -> None:
        """Run the event loop until ``window`` is destroyed.

        Returns at once if it is already gone, so a caller need not race the
        window it is waiting for.
        """
        target = window if window is not None else self
        self._wait_until(lambda: not target.winfo_exists())

    def wait_visibility(self, window: Misc | None = None) -> None:
        """Run the event loop until ``window`` is on the screen."""
        target = window if window is not None else self
        self._wait_until(lambda: target.winfo_viewable())

    def _wait_until(self, ready: Callable[[], bool]) -> None:
        """Pump the event loop until ``ready`` holds.

        Stops early if the root is destroyed: without that, closing the
        application during a wait would leave the loop spinning on a tree
        that no longer exists.
        """
        root = self._root()
        # Before mainloop nothing takes Ctrl-C, and the KeyboardInterrupt
        # came out of select() as a traceback. The wait takes it as mainloop
        # does - noted, answered between callbacks - and the answer is a
        # cancel. Inside mainloop the loop's own handling stands, which
        # cancels a modal window too: _answer_interrupt.
        release = None
        if isinstance(root, Tk) and not root._running:
            release = root._catch_interrupts()
            if release is not None:
                root._interrupt_cancels = True
        try:
            while not ready():
                if not root.winfo_exists():
                    return
                root.update()
        finally:
            if release is not None and isinstance(root, Tk):
                root._interrupt_cancels = False
                release()

    def quit(self) -> None:
        """Ask the main loop to stop.

        The loop notices on its next pass, so the calling callback runs to
        completion first.
        """
        self.tk.quit_requested = True

    def mainloop(self, n: int = 0) -> None:
        """Enter the event loop.

        Raises:
            TclError: Unless the root widget provides a loop. ``Tk()`` does;
                a bare ``Misc`` tree has nothing to run.
        """
        root = self._root()
        if root is self:
            raise TclError("no event loop is available; create a Tk() first")
        root.mainloop(n)

    # ==================================================================
    # Configuration
    # ==================================================================

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set widget options, or report them.

        With keyword arguments or a dictionary, sets them. Called with one option
        name, answers that option's five-tuple, as tkinter does: name, database
        name, database class, default, current value. Called with nothing,
        answers a dictionary of every option's five-tuple, by name.
        """
        # Those five-tuples come from Tcl's widget definitions; the one-option
        # form is answered by _configure_query.
        if isinstance(cast("object", cnf), str):
            return self._configure_query(cast("str", cnf))
        options = _given(cnf, kw)
        if not options:
            return {key: self._configure_query(key) for key in sorted(self._options)}
        for key, value in options.items():
            self._options[key] = value
        return None

    config = configure

    def _configure_query(self, key: str) -> tuple[Any, ...]:
        """``configure(key)``: Tk's five-tuple for one option.

        ``(name, database name, database class, default, value)``. A widget
        knows its defaults and its class, so :class:`BaseWidget` answers this
        properly; here there is only the value.
        """
        return (key, *database_names("", key), "", self.cget(key))

    def cget(self, key: str) -> Any:
        """The value of one option.

        Raises:
            TclError: If the widget has no such option.
        """
        try:
            return self._options[key]
        except KeyError:
            raise TclError(f'unknown option "-{key}"') from None

    def keys(self) -> list[str]:
        """The widget's option names, sorted."""
        return sorted(self._options)

    def __getitem__(self, key: str) -> Any:
        """``widget[key]`` reads an option, as in tkinter."""
        return self.cget(key)

    def __setitem__(self, key: str, value: Any) -> None:
        """``widget[key] = value`` sets an option."""
        self.configure({key: value})

    # ==================================================================
    # Option database
    # ==================================================================

    def option_add(
        self, pattern: str, value: Any, priority: int | str | None = None
    ) -> None:
        """Register a default for options matching ``pattern``."""
        self.tk.options.add(pattern, value, priority)

    def option_clear(self) -> None:
        """Discard every registered option default."""
        self.tk.options.clear()

    def option_get(self, name: str, className: str) -> Any:
        """The value the option database holds for this widget, or ``""``.

        Args:
            name: The option's database name, ``"highlightThickness"``.
            className: Its database class, ``"HighlightThickness"``. A
                pattern ending in either matches; the widget's own class
                and path select the rest, as in Tk.
        """
        found = self.tk.options.get(self._w, self.winfo_class(), name, className)
        return "" if found is None else found

    def option_readfile(
        self,
        fileName: str,  # noqa: ARG002 - tkinter signature
        priority: int | str | None = None,  # noqa: ARG002 - tkinter signature
    ) -> None:
        """Not supported.

        Raises:
            TclError: Always. The file format is Tcl's resource syntax, and
                nothing here can read it.
        """
        raise TclError("option_readfile is not supported: no Tcl resource parser")

    # ==================================================================
    # Utility
    # ==================================================================

    def _tcl_command(self, name: str, args: tuple[Any, ...]) -> Any:
        """Serve ``tk.call(widget, name, *args)``: a Tcl subcommand of this
        widget - ``cget`` and ``configure`` on every widget, with Tk's
        dashed option names, answering in Tk's shapes. A widget with more
        subcommands to serve overrides this and calls it for the rest.

        Measured on Tk 9.0.2: a unique prefix names the subcommand
        (``conf``), ``c`` is ambiguous, an option without its dash is
        unknown, and ``configure`` answers ``""`` once it has set something.
        """
        table = ("cget", "configure")
        matches = [entry for entry in table if name and entry.startswith(name)]
        if len(matches) > 1:
            raise TclError(f'ambiguous option "{name}": must be cget or configure')
        if not matches:
            raise TclError(
                f'TkCurses does not interpret "{self} {name}" through tk.call;'
                " use the widget's method"
            )
        if matches[0] == "cget":
            if len(args) != 1:
                raise TclError(f'wrong # args: should be "{self} cget option"')
            value = self.cget(_dashed(args[0]))
            return "" if value is None else value
        if not args:
            return tuple(
                ("-" + str(entry[0]), *entry[1:])
                if len(entry) == 2
                else _tcl_entry(self, key)
                for key, entry in self.configure().items()
            )
        if len(args) == 1:
            return _tcl_entry(self, _dashed(args[0]))
        if len(args) % 2:
            raise TclError(f'value for "{args[-1]}" missing')
        given = {
            _dashed(option): value
            for option, value in zip(args[::2], args[1::2], strict=True)
        }
        self.configure(**given)
        return ""

    def nametowidget(self, name: str | Misc) -> Misc:
        """The widget with the given path name.

        A name without a leading ``.`` is taken as relative to this widget,
        which is how Tk resolves the names it hands to callbacks.

        Raises:
            KeyError: If no such widget exists.
        """
        path = str(name)
        if not path.startswith("."):
            path = self._build_path(self, path)
        widget = self.tk.widgets.get(path)
        if widget is None:
            widget = self._child_at(path)
        if widget is None:
            raise KeyError(f"no widget named {path!r}")
        return widget

    _nametowidget = nametowidget

    def _child_at(self, path: str) -> Misc | None:
        """The widget at a path found through ``children``, as tkinter finds
        it - which reaches one whose creation failed, as tkinter's does. See
        :meth:`_abandon`."""
        widget: Misc = self
        while widget.master is not None:
            widget = widget.master
        for part in path.split(".")[1:]:
            found = widget.children.get(part)
            if found is None:
                return None
            widget = found
        return widget

    def getvar(self, name: str = "PY_VAR") -> Any:
        """Read an application variable, firing its read traces.

        Raises:
            TclError: If there is no variable of that name, in Tk's words.
        """
        name = str(name)
        _fire_traces(self.tk, name, "read")
        if name not in self.tk.variables:
            raise TclError(f'can\'t read "{name}": no such variable')
        return self.tk.variables[name]

    def setvar(self, name: str = "PY_VAR", value: Any = "1") -> None:
        """Write an application variable, firing its write traces: every
        Variable and widget bound to that name hears it."""
        name = str(name)
        self.tk.variables[name] = value
        _fire_traces(self.tk, name, "write")

    def getint(self, s: Any) -> int:
        """Parse an integer, accepting Tcl's ``0x``/``0o``/``0b`` prefixes."""
        if isinstance(s, int):
            return s
        return int(str(s), 0)

    def getdouble(self, s: Any) -> float:
        """Parse a float."""
        return float(s)

    def getboolean(self, s: Any) -> bool:
        """Parse a boolean the way Tcl does.

        Accepts ``1``/``0``, ``yes``/``no``, ``true``/``false``, ``on``/``off``
        in any case, as well as real booleans and numbers.

        Raises:
            TclError: If the value is not one of those, as tkinter does.
        """
        if isinstance(s, bool):
            return s
        if isinstance(s, (int, float)):
            return bool(s)
        text = str(s).strip().lower()
        if text in _TRUE:
            return True
        if text in _FALSE:
            return False
        raise TclError(f'expected boolean value but got "{s}"')

    # tkinter's bare names for grid's methods, on every widget: Misc.bbox is
    # Misc.grid_bbox. A widget with a bbox, size or anchor of its own - a
    # Listbox, a Canvas - answers with that instead, as in tkinter.
    # Typed loosely: a widget's own bbox and size take other arguments, as
    # tkinter's do, and an alias has to admit both.
    anchor = grid_anchor
    bbox: Any = grid_bbox
    size: Any = grid_size


# ======================================================================
# Default root
# ======================================================================

#: The root created implicitly when a widget is made with no master, as
#: tkinter does. Set by ``Tk()``; nothing here creates one, because creating a
#: root means taking over the terminal and that should never be a side effect
#: of forgetting an argument.
_default_root: Misc | None = None

#: Whether an implicit root is allowed at all. ``NoDefaultRoot()`` clears it.
_support_default_root = True


def NoDefaultRoot() -> None:
    """Require every widget to name its master explicitly.

    Worth calling in a library: an implicit root is a process-wide singleton,
    and code that relies on it cannot be used twice in one program.
    """
    global _support_default_root, _default_root
    _support_default_root = False
    _default_root = None


def _get_default_root(what: str = "create a widget") -> Misc:
    """The implicit root, or an error explaining what to do instead.

    Raises:
        TclError: If there is no root yet, or default roots are switched off.
            tkinter creates one here; TkCurses refuses, because initialising
            curses reconfigures the terminal and must be something the
            application asked for.
    """
    if not _support_default_root:
        raise TclError(
            f"No master specified and tkcurses is configured to not "
            f"support default root; cannot {what}"
        )
    if _default_root is None:
        raise TclError(f"No root window; create a Tk() before trying to {what}")
    return _default_root


# ----------------------------------------------------------------------
# tkinter's module-level names, TkCurses-2q6o.10
# ----------------------------------------------------------------------

#: The Tk and Tcl this library behaves as: it is measured against Tk 9.0.2.
#: Floats, as tkinter's are, so ``TkVersion >= 8.6`` works.
TkVersion = 9.0


class _VersionInfo(NamedTuple):
    """A version as ``info_patchlevel`` answers it, the shape of tkinter's."""

    major: int
    minor: int
    micro: int
    releaselevel: str
    serial: int


#: The Tcl this library behaves as, alongside :data:`TkVersion`.
TclVersion = 9.0

#: A release's version: digits, a pre-release, a post-release, a
#: development build and a local part, as PEP 440 orders them.
_RELEASE = re.compile(
    r"(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:(a|b|rc)(\d+))?"
    r"(?:\.post\d+)?(?:\.dev(\d+))?(?:\+.*)?"
)
_LEVELS = {"a": "alpha", "b": "beta", "rc": "candidate", None: "final"}


def _version_info(version: str) -> _VersionInfo:
    """``version`` - a ``__version__`` - as a :data:`version_info`."""
    found = _RELEASE.fullmatch(version)
    if found is None or version.startswith("0+"):
        # Not installed, so not known: lower than any release.
        return _VersionInfo(0, 0, 0, "alpha", 0)
    major, minor, micro, pre, serial, dev = found.groups()
    level, number = _LEVELS[pre], int(serial or 0)
    if dev is not None:
        # Development builds come before the release they lead to. CPython
        # marks its own as alpha 0 (3.14.0a0); one leading to a pre-release
        # is one serial short of it, so 0.3.0rc2.dev4 follows rc1.
        level, number = (level, number - 1) if pre else ("alpha", 0)
    return _VersionInfo(int(major), int(minor or 0), int(micro or 0), level, number)


#: :data:`__version__` as ``major``, ``minor``, ``micro``, ``releaselevel``
#: and ``serial`` - the shape of :data:`sys.version_info` and of
#: :meth:`~Misc.info_patchlevel` - so a program can ask
#: ``tkcurses.version_info >= (0, 3)``. ``releaselevel`` is ``"alpha"``,
#: ``"beta"``, ``"candidate"`` or ``"final"``.
#:
#: A build between releases compares below the release it leads up to, as
#: CPython's own do: ``0.3.1.dev5`` is ``(0, 3, 1, 'alpha', 0)``, and
#: ``0.3.0rc2.dev4`` is ``(0, 3, 0, 'candidate', 1)``. To tell two such
#: builds apart, read :data:`__version__`. A copy that was never installed
#: has no version to report, and gives ``(0, 0, 0, 'alpha', 0)``.
#:
#: TkCurses extension:
#:     The library's own version, beside the Tk it follows.
version_info = _version_info(__version__)

#: ``createfilehandler``'s masks, with tkinter's values.
READABLE = 2
WRITABLE = 4
EXCEPTION = 8

#: tkinter's are these two builtins, under these names.
getint = int
getdouble = float


def getboolean(s: Any) -> bool:
    """Parse a Tcl boolean, as :meth:`Misc.getboolean` does.

    Raises:
        ValueError: For anything that is not one, which is what tkinter's
            module-level function raises where the method raises TclError.
        TclError: If there is no root, as tkinter refuses without one.
    """
    root = _get_default_root("use getboolean()")
    try:
        return root.getboolean(s)
    except TclError:
        raise ValueError("invalid literal for getboolean()") from None


def mainloop(n: int = 0) -> None:
    """Run the default root's event loop, as ``Tk.mainloop`` does."""
    _get_default_root("run the main loop").mainloop(n)


def image_names() -> tuple[str, ...]:
    """The default root's :meth:`Misc.image_names`."""
    return _get_default_root("use image_names()").image_names()


def image_types() -> tuple[str, ...]:
    """The default root's :meth:`Misc.image_types`."""
    return _get_default_root("use image_types()").image_types()


# ======================================================================
# Widget base classes
# ======================================================================

#: Short spellings tkinter accepts for the options whose names are long.
#: Tk's own short spellings for long option names. These are *Tcl* synonyms:
#: Tk defines them, they appear in a widget's own option list, and ``cget``
#: takes them. Python-keyword workarounds like ``from_`` are a different thing
#: entirely and are deliberately not here - see :func:`_keyword_option`.
_OPTION_ALIASES: dict[str, str] = {
    "bg": "background",
    "fg": "foreground",
    "bd": "borderwidth",
}


def _keyword_option(
    name: str, spec: dict[str, Any], synonyms: dict[str, str] | None = None
) -> str:
    """The option a keyword argument names, allowing for Python's keywords.

    Tk's ``-from`` cannot be written ``from=2`` in Python, so tkinter lets a
    keyword carry one trailing underscore and strips it:
    ``Misc._options`` does ``if k[-1] == '_': k = k[:-1]``. That is a rule
    about *keywords*, not an alias - which is the distinction this library had
    lost. ``from_`` was stored as the canonical name, so ``configure()``
    reported ``from_`` where tkinter reports ``from``, and
    ``w.configure()["from"]`` raised KeyError here while working in tkinter.

    Measured on Tcl/Tk 9.0.2, and the asymmetry is the whole point:

    =====================  ============  ===========
    asked for as            ``from``      ``from_``
    =====================  ============  ===========
    in ``configure()``      yes           no
    ``cget``                yes           TclError
    keyword argument        yes           yes
    =====================  ============  ===========

    So the underscore is stripped here, on the keyword path, and nowhere else.
    ``cget`` resolves :data:`_OPTION_ALIASES` only, which is why
    ``cget("from_")`` now raises as tkinter's does. TkCurses-y5q.
    """
    table = _OPTION_ALIASES if synonyms is None else synonyms
    option = table.get(name, name)
    if option not in spec and option.endswith("_") and option[:-1] in spec:
        return option[:-1]
    return option


#: Merged option specifications, keyed by class. Walking the MRO on every
#: ``configure`` call would be wasted work; the spec cannot change once the
#: class exists.
_SPEC_CACHE: dict[type, dict[str, Any]] = {}
_CHECKS_CACHE: dict[type, dict[str, Callable[[Any, Any], Any]]] = {}


class BaseWidget(Misc):
    """A widget: a named node in the tree with a set of options.

    An option the widget does not take is an error, when the widget is made
    and when it is configured alike, as in tkinter - a misspelled option that
    silently did nothing would be a long afternoon.
    """

    # Subclasses declare what they accept in _widget_options, a mapping of
    # option name to default. The sets are merged down the inheritance chain,
    # so a widget lists only what it adds to the standard set. tkinter gets
    # the check from Tcl's widget definitions; without them it has to be
    # explicit.

    #: Tk's short spellings for this class's options. A *class* attribute and
    #: not a module constant, because the synonyms are per widget: measured on
    #: Tcl/Tk 9.0.2, ``tk.Entry`` takes ``vcmd`` while ``ttk.Entry`` refuses it
    #: although both have ``validatecommand``, and no themed widget has a
    #: synonym at all - ``ttk.Label(bg="red")`` raises. A single global table
    #: got both directions wrong: it was missing ``vcmd`` on the classic
    #: widgets and offering ``bg`` on the themed ones. The most derived
    #: declaration wins, so ttk's mixin empties it. TkCurses-oe5.
    _option_synonyms: ClassVar[dict[str, str]] = _OPTION_ALIASES

    #: Options Tk takes only when the widget is made. Measured on Tk 9.0.2,
    #: ``configure`` refuses each afterwards, even with the value it already
    #: has: ``can't modify -class option after widget is created``. The
    #: window-system ones among them - colormap, visual, container, screen,
    #: use - are fixed when the X window is, and ``-class`` is what the
    #: bindings and the option database were resolved against.
    #: TkCurses-gm66.7.
    _creation_only: ClassVar[frozenset[str]] = frozenset()

    #: Options every widget accepts. The set is deliberately smaller than
    #: tkinter's: X11 options with no cell equivalent (screen distances in
    #: pixels) are left out rather than accepted and ignored, so that setting
    #: one fails loudly instead of quietly.
    #:
    #: **The focus highlight ring is the exception** (TkCurses-gm66.1). Its
    #: three options are accepted, stored and answered, and draw nothing:
    #: every widget that takes the focus already shows it with a cue sized to
    #: a cell - brackets on a Button, an underline on a Checkbutton or a
    #: Listbox row, a bold border on an Entry, a reversed sash - and that cue
    #: stays whatever these say. Refusing them stopped programs at the line,
    #: and they are among the most common options tkinter code sets: usually
    #: ``highlightthickness=0``, to hide X11's ring for looks. Honouring that
    #: by hiding the cue would leave a terminal user no sign of where the
    #: keyboard is. The thickness defaults to Tk's, 1 on the widgets that take
    #: the focus and 0 here; the colours to "", as every colour here does.
    _widget_options: ClassVar[dict[str, Any]] = {
        "background": "",
        "borderwidth": 0,
        "cursor": "",
        "foreground": "",
        "highlightbackground": "",
        "highlightcolor": "",
        "highlightthickness": 0,
        "padx": 0,
        "pady": 0,
        "relief": FLAT,
        # False, because a widget with nothing to do with the keyboard must
        # not be a place the focus can land: Tab stopping on a Frame or a
        # Label shows the user nothing and looks like the focus vanished.
        # Widgets that answer the keyboard turn it back on for themselves,
        # which is how tkinter's "decide by class" default behaves in
        # practice.
        "takefocus": False,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget. Defaults to the implicit root, which must
                already exist; see :func:`_get_default_root`.
            cnf: Options as a dictionary, for names that are not identifiers.
            name: Path component for this widget, generated when omitted.
            **kw: Options as keywords.

        Raises:
            TclError: If an option is not one this widget accepts, or if no
                master was given and there is no root window.
        """
        if master is None:
            master = _get_default_root(f"create a {type(self).__name__}")
        super().__init__(master, name)
        given = _given(cnf, kw)
        self._options = self._initial_options(given)
        self._takefocus = bool(self._options.get("takefocus", False))
        self._takefocus_given = "takefocus" in given

    # ------------------------------------------------------------ options

    @classmethod
    def _option_spec(cls) -> dict[str, Any]:
        """Every option this class accepts, with defaults, merged down the MRO."""
        cached = _SPEC_CACHE.get(cls)
        if cached is None:
            spec: dict[str, Any] = {}
            for klass in reversed(cls.__mro__):
                spec.update(vars(klass).get("_widget_options", {}))
            cached = _SPEC_CACHE[cls] = spec
        return cached

    @classmethod
    def _public_options(cls) -> Collection[str]:
        """The options a program may name, a subset of :meth:`_option_spec`.

        Every one, less :attr:`_not_tk_options`, unless a class narrows it
        further. The themed widgets do: each is built on a classic one and
        keeps that widget's options as the defaults its drawing reads, but
        answers only Tk's ttk option names to a program, as Tk's does.
        """
        hidden = cls._not_tk_options
        if not hidden:
            return cls._option_spec().keys()
        return [name for name in cls._option_spec() if name not in hidden]

    #: Options this widget keeps for its drawing - often because the class it
    #: is built on has them - that Tk's widget of the same kind does not
    #: have, and refuses: measured on Tk 9.0.2 by comparing ``keys()``. A
    #: program naming one gets ``unknown option``, as it would under tkinter.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset()

    def _initial_options(self, given: dict[str, Any]) -> dict[str, Any]:
        """Resolve this widget's starting options.

        Three sources, weakest first: the class's declared defaults, then the
        option database, then whatever the caller passed. That ordering is
        what makes ``option_add("*Button.relief", "raised")`` reach a button
        that did not ask for a relief while leaving alone one that did.
        """
        spec = self._option_spec()
        options = dict(spec)
        database = self.tk.options
        if len(database):
            widget_class = self._database_class()
            for name in spec:
                db_name, db_class = database_names(widget_class, name)
                from_database = database.get(
                    self._w, self.winfo_class(), db_name, db_class
                )
                if from_database is not None:
                    options[name] = from_database
        options.update(self._checked(given))
        return options

    def _configured_menubar(self, given: dict[str, Any]) -> None:
        """Attach a menubar when one is set through the ``menu`` option.

        Only Tk and Toplevel have that option, and only they have the method
        - so the check is for both rather than for the class, which keeps
        BaseWidget from having to know about windows.
        """
        if "menu" in given and hasattr(self, "_attach_menubar"):
            self._attach_menubar()

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """Resolve aliases and reject anything this widget does not accept."""
        spec = self._option_spec()
        public = self._public_options()
        resolved: dict[str, Any] = {}
        for name, value in given.items():
            option = _keyword_option(name, spec, self._option_synonyms)
            if option not in spec or option not in public:
                raise TclError(f'unknown option "-{name}"')
            check = self._value_checks_of().get(option) or _OPTION_VALUES.get(option)
            resolved[option] = value if check is None else check(self, value)
        return resolved

    #: How this class reads an option whose meaning depends on the widget,
    #: over :data:`_OPTION_VALUES`, merged down the MRO as ``_widget_options``
    #: is. ``width`` is the case that needs it: a count of characters on a
    #: Button, a screen distance on a Frame, and not checked at all on a
    #: ttk.Label - three answers to ``width="abc"``, measured on Tk 9.0.2.
    #: TkCurses-vgkb.
    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {}

    @classmethod
    def _value_checks_of(cls) -> dict[str, Callable[[Any, Any], Any]]:
        cached = _CHECKS_CACHE.get(cls)
        if cached is None:
            checks: dict[str, Callable[[Any, Any], Any]] = {}
            for klass in reversed(cls.__mro__):
                checks.update(vars(klass).get("_value_checks", {}))
            cached = _CHECKS_CACHE[cls] = checks
        return cached

    def _cursor_style(self) -> CursorStyle:
        """What this widget asks of the terminal's cursor while it has the focus.

        Tk draws its own cursor and these options shape it. Here the cursor is
        the terminal's, as the person set it up (UAT 43, TkCurses-lw2), so an
        option left at Tk's default asks for nothing. One a program changed
        asks for the nearest thing a terminal has (TkCurses-gm66.2):

        - ``blockcursor`` on a Text: a block over the character, as Tk draws.
        - ``insertwidth`` at anything but Tk's 2: a bar, which is Tk's shape
          at every width. A terminal cell has no width to give it.
        - ``insertofftime`` of 0 or less: a cursor that does not blink, which
          is what Tk's manual says 0 means. Asked alone, it is a steady *bar*,
          because that is the cursor Tk would be drawing.
        - ``insertbackground``: the cursor's colour.

        ``insertontime``'s length and ``insertborderwidth``'s 3-D edge have no
        terminal request, nor has the blink's speed, and ``insertunfocussed``
        would need a second cursor; they are stored and answered only.
        """
        options = self._options
        if "insertwidth" not in options:
            return TERMINALS_OWN
        block = bool(options.get("blockcursor", 0))
        steady = _as_int(options["insertofftime"], 300) <= 0
        reshaped = _as_int(options["insertwidth"], _TK_INSERT_WIDTH) != _TK_INSERT_WIDTH
        shape = None
        if block or reshaped or steady:
            shape = (2 if steady else 1) if block else (6 if steady else 5)
        colour = None
        if options["insertbackground"]:
            red, green, blue = (
                channel // 257
                for channel in self.winfo_rgb(options["insertbackground"])
            )
            colour = f"#{red:02x}{green:02x}{blue:02x}"
        return CursorStyle(shape=shape, colour=colour)

    def _selection_attribute(
        self, attribute: int, foreground: Any = None, background: Any = None
    ) -> int:
        """How selected text is drawn: in the colours given, else reversed.

        ``foreground`` and ``background`` default to ``selectforeground`` and
        ``selectbackground``. With neither set, or no colour on the terminal,
        the selection is reversed, as it was before Tk's options were taken
        (TkCurses-gm66.3). One set alone keeps the widget's colour for the
        other, as a Text tag does.
        """
        options = self._options
        if foreground is None:
            foreground = options.get("selectforeground", "")
        if background is None:
            background = options.get("selectbackground", "")
        if self.tk.colors is None or not (foreground or background):
            return attribute | _curses.A_REVERSE
        return self._coloured(attribute, foreground, background)

    #: The options that colour each state, as ``(foreground, background)``
    #: option names, either of which may be None. See ``_in_state``.
    _STATE_COLOURS: ClassVar[dict[str, tuple[str | None, str | None]]] = {}

    def _coloured(self, attribute: int, foreground: Any, background: Any) -> int:
        """``attribute`` wearing these colours, the widget's own for a ``""``.

        Unchanged when neither is given or the terminal has no colour.
        """
        colors = self.tk.colors
        if colors is None or not (foreground or background):
            return attribute
        options = self._options
        return with_colors(
            attribute,
            colors.attribute_for(
                str(foreground or options.get("foreground") or "white"),
                str(background or options.get("background") or "black"),
            ),
        )

    def _state_colours(self, state: str) -> tuple[Any, Any] | None:
        """The colours a program gave ``state``, or None if it gave none.

        None too on a terminal with no colour, where they cannot be shown.
        """
        names = self._STATE_COLOURS.get(state)
        if names is None or self.tk.colors is None:
            return None
        foreground, background = (
            self._options.get(name, "") if name else "" for name in names
        )
        return (foreground, background) if foreground or background else None

    def _in_state(self, attribute: int, state: str | None = None) -> int:
        """``attribute`` as this widget looks in ``state``, its own by default.

        In the colours a program gave the state - ``activebackground``,
        ``disabledforeground`` and the rest - and otherwise reversed or dimmed
        as ``for_state`` has always drawn it. Tk's defaults for these are
        real colours; here they are ``""``, so a program that gives none
        looks as it did before they were taken (TkCurses-gm66.4).
        """
        if state is None:
            state = str(self._options.get("state", "normal"))
        colours = self._state_colours(state)
        if colours is not None:
            return self._coloured(attribute, *colours)
        with contextlib.suppress(ValueError):
            return for_state(state, attribute)
        return attribute

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, or report them all when called with none.

        Called with nothing, answers a dictionary of every option's five-tuple,
        as tkinter does - name, database name, database class, default, current
        value - with each short spelling Tk defines, such as ``bg``, as the
        pair ``("bg", "-background")``.

        Raises:
            TclError: If an option is not one this widget accepts.
        """
        given = _given(cnf, kw)
        if not given:
            synonyms = self._synonyms()
            return {
                name: (
                    (name, self._synonym_target(synonyms[name]))
                    if name in synonyms
                    else self._configure_query(name)
                )
                for name in self.keys()
            }
        checked = self._checked(given)
        for option in checked:
            if option in self._creation_only:
                raise TclError(f"can't modify -{option} option after widget is created")
        self._options.update(checked)
        if "takefocus" in given:
            self._takefocus = bool(self._options["takefocus"])
            self._takefocus_given = True
        self._configured_menubar(given)
        return None

    config = configure

    def cget(self, key: str) -> Any:
        """The value of one option, accepting the short spellings.

        Raises:
            TclError: If this widget has no such option.
        """
        option = self._option_synonyms.get(key, key)
        if option not in self._public_options():
            raise TclError(f'unknown option "-{key}"')
        try:
            return self._options[option]
        except KeyError:
            raise TclError(f'unknown option "-{key}"') from None

    def keys(self) -> list[str]:
        """The option names this widget accepts, sorted, with the short
        spellings Tk defines for them - ``bd``, ``bg``, ``fg`` and the like -
        as tkinter lists them."""
        return sorted({*self._public_options(), *self._synonyms()})

    #: Tk's canvas and scrollbar name a synonym's option by its database
    #: name, ``("bd", "borderWidth")``, where every other widget gives the
    #: option, ``("bd", "-borderwidth")``. Measured on Tk 9.0.2: the two are
    #: still configured through Tk's older option table.
    _synonyms_by_database_name: ClassVar[bool] = False

    def _synonyms(self) -> dict[str, str]:
        """The short spellings this widget answers to, each to its option.

        Only those whose option this widget has: measured on Tk 9.0.2, a
        Canvas has ``bd`` and ``bg`` but no ``fg``, having no foreground.
        """
        public = set(self._public_options())
        return {
            short: option
            for short, option in self._option_synonyms.items()
            if option in public
        }

    def _synonym_target(self, option: str) -> str:
        """What ``configure()`` lists as a synonym's option, as Tk spells it."""
        if self._synonyms_by_database_name:
            return database_names(self._database_class(), option)[0]
        return "-" + option

    def _configure_query(self, key: str) -> tuple[Any, ...]:
        """``configure(key)``: Tk's five-tuple for one option.

        Measured on Tk 9.0.2, a short spelling answers the FULL entry under the
        full name - ``configure("bg")`` is ``("background", "background",
        "Background", ...)``, not the two-tuple ``configure()`` lists for
        ``bg`` - and the name is taken as it stands: ``configure("-text")`` is
        ``unknown option "--text"``, as ``cget`` already refuses it.

        The database name and class are Tk's, from
        :mod:`tkcurses._core.option_names`. The default is this library's own,
        which is not always Tk's: colours and sizes here are cells and curses
        colours, not pixels and X colours.
        """
        value = self.cget(key)
        option = self._option_synonyms.get(key, key)
        return (
            option,
            *database_names(self._database_class(), option),
            self._option_spec().get(option, ""),
            value,
        )

    @classmethod
    def _database_class(cls) -> str:
        """Which of Tk's widget classes this is, for its database names.

        The nearest along the MRO, so a program's own subclass of
        ``ttk.Entry`` answers as a ttk Entry. ``""`` when there is none.
        """
        for klass in cls.__mro__:
            prefix = "ttk" if klass.__module__ == "tkcurses.ttk" else "tk"
            name = f"{prefix}.{klass.__name__}"
            if name in WIDGET_CLASSES:
                return name
        return ""

    # ---------------------------------------------------------- lifecycle

    @property
    def _window(self) -> Any:
        """The curses window behind this widget, or None if it has no panel."""
        return None if self._panel is None else self._panel.window

    def _write_line(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        row: int,
        column: int,
        text: str,
        attribute: int,
    ) -> None:
        """Write ``text`` at a cell of this widget, clipped to its window.

        Three things curses will not do for us. It wraps a write that runs past
        the right edge onto the next row rather than dropping it, so anything
        too wide has to be cut here; and it refuses a write that fills the
        last cell of the last row, because that would scroll a window with
        nowhere to scroll to - so that one cell is inserted instead, which
        puts the character there without advancing. insstr rather than insch
        because a box-drawing character is multibyte and does not fit in the
        single chtype insch takes.

        And the window may not start where the widget does. ``row`` and
        ``column`` are the widget's own, and a widget whose left or top is
        clipped away - by the screen or by its master - has a window holding
        only the rest, so they are moved into it here and whatever lands
        before its first cell is dropped. Only for the widget's own window:
        a PanedWindow's sash proxy is drawn through this into a window of its
        own, and is never clipped.
        """
        if window is self._window:
            left, top = self._window_offset
            row -= top
            column -= left
        rows, columns = dispatcher.call(window.getmaxyx)
        text = _one_cell_each(text)
        screen = self.tk.screen
        if screen is not None and screen.glyphs is not None:
            text = text.translate(screen.glyphs)
        if column < 0:
            # In cells: a wide character cut in half by the edge leaves its
            # other half blank, not drawn half off the window.
            text, blank = skip_cells(text, -column)
            column = blank
        if not 0 <= row < rows or not column < columns:
            return
        text = clip_cells(text, columns - column)
        if not text:
            return
        with contextlib.suppress(_curses.error):
            if column + cells(text) >= columns:
                # The last character, with any marks that combine with it,
                # inserted where it starts - the last cell, or the one before
                # for a wide one - so the write does not advance past the end.
                last = len(text) - 1
                while last > 0 and char_cells(text[last]) == 0:
                    last -= 1
                head, tail = text[:last], text[last:]
                if head:
                    dispatcher.call(window.addstr, row, column, head, attribute)
                dispatcher.call(
                    window.insstr, row, column + cells(head), tail, attribute
                )
            else:
                dispatcher.call(window.addstr, row, column, text, attribute)

    def _allocate(self, rect: Rect) -> None:
        """Give the widget the region a geometry manager decided on.

        Called by pack, grid and place, and by a resize that moves things
        around. The widget records the region whether or not there is a panel
        stack to build on: layout is decided before curses exists, and the
        window follows once it does.

        An empty region is how a manager says "no room for this" - it drops
        the window rather than asking curses for a zero-sized one, which
        curses refuses.
        """
        previous, self._rect = self._rect, rect
        if rect != previous:
            # tkinter raises <Configure> whenever a widget's size or position
            # changes, however it changed - geometry(), a manager, minsize, a
            # terminal resize. _allocate is the one place all of those meet,
            # so it is the one place this belongs.
            #
            # Only on a real change, which is what keeps a handler that calls
            # geometry() from recurring: its second call sets the same rect,
            # that is not a change, and nothing fires. Measured against Tk
            # 9.0.2, where such a handler produces two events and stops.
            self.event_generate(
                "<Configure>",
                width=rect.width,
                height=rect.height,
                x=rect.x,
                y=rect.y,
            )
        resized = (rect.width, rect.height) != (previous.width, previous.height)
        if resized:
            # How much of the content is visible is a function of the size, so
            # a scrollbar told before the widget had its final size was told a
            # fraction computed against the wrong height. Nothing corrected
            # it, and the ordinary idiom - create, fill, lay out - is the
            # broken order, so the common case was the wrong one.
            self._report_scroll_view()
        if resized and (
            self._layout_manager is not None
            or self._place_manager is not None
            or self._paned_manager is not None
            or self._embed_manager is not None
        ):
            # A container given a new size has to place its children again.
            # Propagation travels upward - what a widget needs - and this is
            # the other direction: what it was actually given. Without it a
            # container laid out before its own parent keeps children sized
            # against a region it no longer has.
            self.tk.layout.invalidate(self)
        if not self._sync_window():
            if resized and self._panel is not None:
                # The window did not change, because the screen edge was
                # already clipping it to the same few cells - but the widget
                # is a different size now and draws itself differently, so
                # the border it puts at its own right edge moves even though
                # nothing about the window did.
                self._redraw()
            return
        # The widget's window has changed and its descendants' have not:
        # their rects are offsets from this one and so did not change, which
        # is exactly why nothing above tells them anything. A container that
        # moves without changing size does not lay its children out again,
        # and one that goes off screen is not laid out at all - so without
        # this the children stay drawn where the container used to be.
        for widget in self._subtree():
            # A subtree is typed as Misc, and only a widget has a window; the
            # root is the one Misc that is not a widget, and it is nobody's
            # descendant.
            if widget is not self and isinstance(widget, BaseWidget):
                widget._sync_window()

    def _report_scroll_view(self) -> None:
        """Tell any scrollbar where the view is now. A no-op unless scrollable.

        Overridden by the widgets that have a view to report - Listbox, Text
        and Canvas - so that :meth:`_allocate` has one thing to call without
        knowing which widgets those are.
        """

    def _sync_window(self) -> bool:
        """Put this widget's curses window where its geometry now says.

        Returns:
            True if the window changed at all - made, dropped, moved or
            rebuilt - so that anything positioned relative to it has to be
            seen to as well. A widget that goes off screen counts: its own
            window is dropped, and the descendants whose windows are drawn
            over the same cells would otherwise stay exactly where they
            were, which is a label left behind on top of whatever is now in
            its place.
        """
        stack = self.tk.panels
        if stack is None:
            return False
        if not self._viewable:
            # Inside something that is not on screen. The widget keeps its
            # geometry and gets its window back when the ancestor returns -
            # the same treatment as one scrolled off the edge. Without this a
            # layout pass gives every hidden notebook page's contents a fresh
            # window, and two pages are drawn at once. TkCurses-mlw.
            return self._drop_window()
        if self._rect.is_empty:
            return self._drop_window()
        if self._panel is None:
            if self._mapped:
                self._create_window()
                return self._panel is not None
            return False
        # Compared against where the panel actually is, not against the
        # widget's previous rect: a rect is an offset from the master, so an
        # ancestor moving relocates the panel without changing it.
        target = self._visible_rect()
        if target.is_empty:
            # Entirely off screen, or outside its master. The widget keeps its
            # geometry and gets its window back when it comes into view again.
            return self._drop_window()
        offset = self._offset_of(target)
        shifted = offset != self._window_offset
        self._window_offset = offset
        current = self._panel.rect
        if (target.width, target.height) != (current.width, current.height):
            # Curses cannot resize a window in place, and replacing it is also
            # what keeps a shrink from leaving the vacated cells behind.
            stack.replace_window(self._panel, target)
            self._redraw()
            return True
        if (target.x, target.y) != (current.x, current.y):
            stack.move(self._panel, target.x, target.y)
            self._redraw()
            return True
        if shifted:
            # The same cells, showing a different part of the widget: one
            # wider than its container, sliding along underneath it.
            self._redraw()
            return True
        return False

    def _offset_of(self, visible: Rect) -> tuple[int, int]:
        """Where a window covering ``visible`` starts within this widget."""
        x, y = self._root_offset()
        return visible.x - x, visible.y - y

    def _drop_window(self) -> bool:
        """Release this widget's window and say whether there was one."""
        had_one = self._panel is not None
        self._destroy_window()
        return had_one

    def _map(self) -> None:
        """Put the widget on screen, creating its window if it has none.

        Idempotent: a geometry manager may re-map a widget it has already
        placed, and mapping twice should not raise ``<Map>`` twice.
        """
        if self._mapped:
            return
        self._mapped = True
        self._create_window()
        self._show_subtree()
        if not self._viewable:
            # Mapped, but inside something that is not: the widget belongs on
            # screen and cannot be seen yet. Tk keeps these apart as *mapped*
            # and *viewable*, and without the distinction a layout pass puts
            # the contents of every hidden notebook page back on the screen -
            # which is exactly what it did.
            self._hide_subtree()
            if self._panel is not None:
                self.tk.panels.hide(self._panel)  # type: ignore[union-attr]
            return
        self.event_generate("<Map>")

    @property
    def _viewable(self) -> bool:
        """True when this widget and every ancestor of it is mapped.

        Tk's rule. ``_mapped`` says whether the widget wants to be on screen;
        this says whether it can be, which is a property of the whole chain
        above it.
        """
        widget: Misc | None = self.master
        while widget is not None:
            if isinstance(widget, BaseWidget) and not widget._mapped:
                return False
            widget = widget.master
        return True

    def _show_subtree(self) -> None:
        """Put the panels of everything inside this widget back on screen.

        The counterpart of :meth:`_hide_subtree`. A child that was unmapped
        in its own right stays away: its ``_mapped`` is false, and this only
        shows the ones whose absence was their ancestor's doing. That is Tk's
        distinction between *mapped* and *viewable* - a widget is viewable
        only when it and every ancestor is mapped.
        """
        stack = self.tk.panels
        if stack is None:
            return
        for widget in self._subtree():
            if widget is self or not isinstance(widget, BaseWidget):
                continue
            if not widget._mapped:
                continue
            if widget._panel is None:
                # It gave its window up while it could not be seen - a child
                # laid out before its container was mapped does exactly that -
                # so it needs building rather than merely unhiding.
                widget._sync_window()
            elif widget._panel is not None:
                stack.show(widget._panel)
        # And put them back above this widget's own panel, which was created
        # after theirs and would otherwise be drawn over its own contents -
        # the same rule _restack_descendants keeps for raising and lowering.
        self._restack_descendants(stack)

    def _hide_subtree(self) -> None:
        """Take the panels of everything inside this widget off screen.

        A child draws on its own panel, so hiding only this widget's leaves
        every label and field inside it exactly where it was - measured, a
        notebook showed two pages at once. TkCurses-mlw, and the third time
        this shape has bitten: see also ``_restack_descendants`` and the
        descendant loop in ``_allocate``.
        """
        stack = self.tk.panels
        if stack is None:
            return
        for widget in self._subtree():
            if widget is self or not isinstance(widget, BaseWidget):
                continue
            if widget._panel is not None:
                stack.hide(widget._panel)

    def _unmap(self) -> None:
        """Take the widget off screen, keeping its window for a later map.

        The window is hidden rather than destroyed, because an unmapped
        widget is usually on its way back - a notebook tab, a hidden frame -
        and rebuilding the window each time would throw away its contents.
        """
        # Before the guard, not after it. A container may itself never have
        # been mapped while the children inside it were - a notebook page
        # laid out once and then put away - and returning early left every
        # one of them on screen.
        self._hide_subtree()
        if not self._mapped:
            return
        self._mapped = False
        if self._panel is not None:
            self.tk.panels.hide(self._panel)  # type: ignore[union-attr]
        if self.tk.focus is self:
            # A widget that is no longer on screen must not keep the
            # keyboard. Left holding it, every key afterwards is delivered to
            # something nobody can see and every binding further out - the
            # Escape that closes the application, most of all - stops firing.
            self.tk.focus = None
        self.event_generate("<Unmap>")

    def _create_window(self) -> None:
        """Allocate this widget's panel, if it can have one yet.

        Silent when there is no stack or no region: both mean "not yet", and
        the widget will get its window when :meth:`_allocate` or :meth:`_map`
        next finds the other half in place.
        """
        stack = self.tk.panels
        if stack is None or self._rect.is_empty:
            return
        visible = self._visible_rect()
        if visible.is_empty:
            return
        self._window_offset = self._offset_of(visible)
        if self._panel is None:
            self._panel = stack.new_panel(visible, userptr=self)
            # A panel goes on top of the stack when it is made, and windows
            # are made in layout order, which is not tree order: a container
            # laid out after its own children would sit in front of them and
            # hide them behind an empty window. Tree order is re-imposed each
            # time rather than relying on the order things happened to be
            # created in.
            self._root()._restack_panels()
        else:
            stack.show(self._panel)
        self._redraw()

    def _destroy_window(self) -> None:
        """Release this widget's panel.

        Safe to call on a widget that never had one, which is what makes
        destroy() able to call it unconditionally.
        """
        if self._panel is None:
            return
        stack = self.tk.panels
        if stack is not None:
            stack.destroy(self._panel)
        self._panel = None

    def _restack(self, other: Misc | None, above: bool) -> None:
        """Reorder among siblings, and move the window with it.

        Sibling order is the model; the panel stack is what the terminal
        shows. Changing one without the other leaves a widget that claims to
        be in front while drawing behind.
        """
        super()._restack(other, above)
        stack = self.tk.panels
        if stack is None or self._panel is None:
            return
        target = getattr(other, "_panel", None) if other is not None else None
        if target is None:
            if above:
                stack.raise_to_top(self._panel)
            else:
                stack.lower_to_bottom(self._panel)
        elif above:
            stack.raise_above(self._panel, target)
        else:
            stack.lower_below(self._panel, target)
        self._restack_descendants(stack)

    def _restack_descendants(self, stack: PanelStack) -> None:
        """Carry the children along, so the widget does not bury its own.

        A child draws on its own panel *above* its container's - that is what
        makes a label visible inside a frame at all. Moving only the
        container's panel therefore puts the container's own blank interior
        in front of everything it contains: measured, raising a Toplevel left
        a window with a border, a title, and nothing else. Every label, every
        grip, gone, and not left behind at the old position either - simply
        covered.

        Chaining rather than raising each to the top, and from the container
        upward: that keeps the subtree's own order intact and works for
        lowering as well, where the children have to come down and stay just
        above the parent rather than be left at the front.
        """
        previous = self._panel
        if previous is None:
            return
        for widget in self._subtree():
            if widget is self or not isinstance(widget, BaseWidget):
                continue
            panel = widget._panel
            if panel is None:
                continue
            stack.raise_above(panel, previous)
            previous = panel

    def destroy(self) -> None:
        """Destroy the widget, its children, and their windows.

        Children go first - Misc sees to that - so a panel is never left
        pointing at a destroyed parent, and this widget's own window is
        released last.
        """
        alive = not self._destroyed
        # Always, so that one whose creation failed leaves its master's
        # children; Misc.destroy is what knows how. See Misc._abandon.
        super().destroy()
        if alive:
            self._destroy_window()


# ======================================================================
# Geometry managers
# ======================================================================


class Pack:
    """Packing: place a widget against one edge of what space is left.

    Each widget packed takes a strip along one side - ``top`` by default -
    of whatever its parent has left, and the next one packed works in what
    remains. ``fill`` stretches a widget across its strip and ``expand``
    gives it a share of any room to spare. Sizes are in cells.

    Sample output:
        tk.Label(root, text="top", relief="solid").pack(side="top", fill="x")
        tk.Label(root, text="left", relief="solid").pack(side="left",
                                                          fill="y")
        tk.Label(root, text="the rest", relief="solid").pack(expand=True,
                                                              fill="both")
    """

    if TYPE_CHECKING:
        # Supplied by the widget this is mixed into, declared so the contract
        # is visible and the mixin still type-checks on its own.
        master: Misc | None

        # The rest of what a geometry manager needs of the widget this is
        # mixed into - see _core.geometry.Managed, which names exactly these
        # four. Only master was declared, so handing self to the manager
        # type-checked against nothing at all. TkCurses-d40.
        def winfo_reqwidth(self) -> int: ...
        def winfo_reqheight(self) -> int: ...
        def _allocate(self, rect: Rect) -> None: ...

        _manager: str
        _manager_container: Misc | None

        def _map(self) -> None: ...
        def _unmap(self) -> None: ...

        _is_toplevel: bool

        def _managed_layout(self, name: str) -> Layout | None: ...
        def _leave_layout(self, container: Misc) -> None: ...
        def _leave_for(self, container: Misc, manager: str = "") -> None: ...

    def pack_configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Pack this widget into its container.

        Args:
            cnf: Options as a dictionary, merged with the keywords.
            **kw: ``side``, ``fill``, ``expand``, ``anchor``, ``padx``,
                ``pady``, ``ipadx``, ``ipady``, plus ``in_`` to pack into
                something other than the master, and ``before``/``after`` to
                place this widget in the packing order.

        Raises:
            TclError: If an option or its value is not one Tk accepts, or
                grid still lays out a child of the container.
        """
        options = _given(cnf, kw)
        container = options.pop("in_", None) or options.pop("in", None) or self.master
        if container is None:
            raise TclError("cannot pack the root window")
        if self._is_toplevel:
            raise TclError(f"can't pack \"{self}\": it's a top-level window")
        before = options.pop("before", None)
        after = options.pop("after", None)

        layout = _pack_layout_of(container)
        current = self._managed_layout("pack")
        remembered = (
            current.options_for(self) if isinstance(current, PackLayout) else None
        )
        # A geometry call naming a different container is a move, and the
        # container being left has to stop laying this widget out.
        self._leave_for(container, "pack")
        layout.add(self, _pack_options(options, remembered), before=before, after=after)
        self._manager = "pack"
        self._manager_container = container
        self._map()
        container.tk.layout.invalidate(container)

    pack = pack_configure

    def pack_forget(self) -> None:
        """Stop packing this widget and take it off the screen.

        Its packing options are forgotten, which is what will separate this
        from ``grid_remove``: packing it again starts from the defaults.
        """
        container = self._manager_container or self.master
        # A widget another manager lays out is left alone, as Tk's
        # ``pack forget`` leaves it. TkCurses-huq9.
        if container is None or self._manager != "pack":
            return
        manager = container._layout_manager
        if isinstance(manager, PackLayout):
            manager.remove(self)
            container.tk.layout.invalidate(container)
        self._manager = ""
        self._manager_container = None
        self._unmap()

    forget = pack_forget

    def pack_info(self) -> dict[str, Any]:
        """How this widget is packed.

        Raises:
            TclError: If it is not packed. Tk reports that rather than
                returning defaults, which would read as though it were.
        """
        container = self._manager_container or self.master
        manager = container._layout_manager if container is not None else None
        options = manager.options_for(self) if isinstance(manager, PackLayout) else None
        if options is None:
            raise TclError(f'window "{self}" is not packed')
        return {
            "in": container,
            "side": options.side,
            "fill": options.fill,
            "expand": options.expand,
            "anchor": options.anchor,
            "padx": options.padx.value,
            "pady": options.pady.value,
            "ipadx": options.ipadx,
            "ipady": options.ipady,
        }

    info = pack_info

    # tkinter's bare names. On a widget, configure is the widget's own, and
    # forget and info are pack's, as tkinter's method order has them.
    configure = config = pack_configure
    propagate = Misc.pack_propagate
    slaves: Any = Misc.pack_slaves


#: What each layout class is called in the error a mixed container raises.
_MANAGER_NAMES = {
    "PackLayout": "pack",
    "GridLayout": "grid",
    "PanedLayout": "panedwindow",
}


def _make_way(container: Misc, name: str) -> None:
    """Refuse ``name`` in ``container`` if another manager still lays it out.

    The caller then replaces the container's manager with its own.

    Measured on Tk 9.0.2: pack and grid refuse each other only while the
    other has a child in the container - one whose last packed child was
    forgotten takes grid - and the error is Tk 9's, with both names quoted.
    Place is not this manager and never in the way. TkCurses-huq9.

    A paned window's panes are not in the way either: Tk lets pack or grid
    lay out other children beside them. TkCurses-ect9.

    Raises:
        TclError: If the container's manager still lays out a child.
    """
    manager = container._layout_manager
    if manager is None:
        return
    if manager.slaves(container):
        other = _MANAGER_NAMES.get(type(manager).__name__, type(manager).__name__)
        raise TclError(
            f'cannot use geometry manager "{name}" inside "{container}": '
            f"{other} is already managing its content windows"
        )


def _pack_layout_of(container: Misc) -> PackLayout:
    """The container's pack manager, created on first use.

    Raises:
        TclError: If grid, or a paned window, still lays out a child of the
            container. Tk refuses the same mixture: two managers each sizing
            the container to suit their own children is not a layout.
    """
    manager = container._layout_manager
    if isinstance(manager, PackLayout):
        return manager
    _make_way(container, "pack")
    manager = PackLayout()
    container._layout_manager = manager
    return manager


def _pack_options(
    given: dict[str, Any], remembered: PackOptions | None = None
) -> PackOptions:
    """Build and check one widget's packing options.

    Args:
        given: The options named in this call.
        remembered: The options the widget already has, which everything not
            named keeps. None starts from the defaults, which is what a
            widget not currently packed gets.

    Raises:
        TclError: If an option is unknown or its value is not one Tk accepts.
            Checked here rather than left to produce a strange layout later: a
            misspelled ``fill`` is otherwise invisible.
    """
    options = (
        PackOptions(**vars(remembered)) if remembered is not None else PackOptions()
    )
    for name, value in given.items():
        if not hasattr(options, name):
            raise TclError(f'unknown option "-{name}"')
        setattr(options, name, value)

    if options.side not in SIDES:
        raise TclError(f'bad side "{options.side}": must be {", ".join(SIDES)}')
    if options.fill not in FILLS:
        raise TclError(f'bad fill style "{options.fill}": must be {", ".join(FILLS)}')
    try:
        parse_anchor(options.anchor)
    except ValueError as error:
        raise TclError(str(error)) from None
    options.expand = bool(options.expand)
    _check_pads(options, given)
    return options


def _check_pads(options: PackOptions | GridOptions, given: dict[str, Any]) -> None:
    """Parse the four pad options of whichever manager is being configured.

    ``padx``/``pady`` take a distance per side; ``ipadx``/``ipady`` take one
    distance only. The asymmetry is Tk's own, measured rather than assumed:
    Tcl/Tk 9.0.2 accepts ``padx=(2, 8)`` and rejects ``ipadx=(2, 8)`` with
    ``bad ipadx value "2 8": must be positive screen distance``.

    Only options named in this call are re-parsed. Ones the widget already had
    are already :class:`Pad` instances, and feeding a ``Pad`` back through
    :func:`parse_pad` would be a second, lossy conversion.

    Raises:
        TclError: With Tk's wording, for a value Tk would refuse.
    """
    for name in ("padx", "pady"):
        if name not in given:
            continue
        try:
            setattr(options, name, parse_pad(getattr(options, name)))
        except ValueError as error:
            raise TclError(str(error)) from None
    for name in ("ipadx", "ipady"):
        if name not in given:
            continue
        try:
            setattr(options, name, parse_single_pad(getattr(options, name), name))
        except ValueError as error:
            raise TclError(str(error)) from None


class Grid:
    """Gridding: place a widget in a row and a column.

    Each row is as tall as its tallest widget and each column as wide as
    its widest, so widgets line up across the whole table. ``sticky`` says
    which sides of its cell a widget clings to, and ``columnspan`` and
    ``rowspan`` let it cover several. Sizes are in cells.

    Sample output:
        for row, label in enumerate(("Name", "Email address")):
            tk.Label(root, text=label).grid(row=row, column=0, sticky="e")
            tk.Entry(root, width=16).grid(row=row, column=1)
        tk.Button(root, text="OK").grid(row=2, column=0, columnspan=2)
    """

    if TYPE_CHECKING:
        master: Misc | None

        # The rest of what a geometry manager needs of the widget this is
        # mixed into - see _core.geometry.Managed, which names exactly these
        # four. Only master was declared, so handing self to the manager
        # type-checked against nothing at all. TkCurses-d40.
        def winfo_reqwidth(self) -> int: ...
        def winfo_reqheight(self) -> int: ...
        def _allocate(self, rect: Rect) -> None: ...

        _manager: str
        _manager_container: Misc | None

        def _map(self) -> None: ...
        def _unmap(self) -> None: ...

        _is_toplevel: bool

        def _managed_layout(self, name: str) -> Layout | None: ...
        def _leave_layout(self, container: Misc) -> None: ...
        def _leave_for(self, container: Misc, manager: str = "") -> None: ...

    def grid_configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Place this widget in its container's grid.

        Args:
            cnf: Options as a dictionary, merged with the keywords.
            **kw: ``row``, ``column``, ``rowspan``, ``columnspan``,
                ``sticky``, ``padx``, ``pady``, ``ipadx``, ``ipady``, plus
                ``in_`` to grid into something other than the master.

        A bare ``grid()`` on a widget that was hidden with
        :meth:`grid_remove` puts it back where it was.

        Raises:
            TclError: If an option or its value is not one Tk accepts, or
                pack still lays out a child of the container.
        """
        options = _given(cnf, kw)
        container = options.pop("in_", None) or options.pop("in", None) or self.master
        if container is None:
            raise TclError("cannot grid the root window")
        if self._is_toplevel:
            raise TclError(f"can't manage \"{self}\": it's a top-level window")
        layout = _grid_layout_of(container)
        # Two sources, and the live one wins: a widget being reconfigured
        # merges into the options it has now, while one that grid_remove()
        # hid merges into the ones that were kept for it.
        current = self._managed_layout("grid")
        held = current.options_for(self) if isinstance(current, GridLayout) else None
        remembered = held or layout.remembered(self)
        # A geometry call naming a different container is a move, and the
        # container being left has to stop laying this widget out.
        self._leave_for(container, "grid")
        if not options and remembered is not None:
            layout.add(self, remembered)
        else:
            layout.add(self, _grid_options(options, remembered))
        self._manager = "grid"
        self._manager_container = container
        self._map()
        container.tk.layout.invalidate(container)

    grid = grid_configure

    def grid_forget(self) -> None:
        """Take this widget out of the grid and forget where it was."""
        self._ungrid(keep=False)

    def grid_remove(self) -> None:
        """Take this widget out of the grid but remember where it was.

        A later bare ``grid()`` puts it back, which is what makes this the
        way to hide a widget temporarily.
        """
        self._ungrid(keep=True)

    def _ungrid(self, *, keep: bool) -> None:
        """Shared implementation of grid_forget and grid_remove."""
        container = self._manager_container or self.master
        if container is None or self._manager != "grid":
            return
        manager = container._layout_manager
        if isinstance(manager, GridLayout):
            manager.remove(self, keep=keep)
            container.tk.layout.invalidate(container)
        self._manager = ""
        self._manager_container = None
        self._unmap()

    def grid_info(self) -> dict[str, Any]:
        """Where this widget sits in the grid.

        Raises:
            TclError: If it is not gridded.
        """
        container = self._manager_container or self.master
        manager = container._layout_manager if container is not None else None
        options = manager.options_for(self) if isinstance(manager, GridLayout) else None
        if options is None:
            raise TclError(f'window "{self}" is not gridded')
        return {
            "in": container,
            "row": options.row,
            "column": options.column,
            "rowspan": options.rowspan,
            "columnspan": options.columnspan,
            "sticky": options.sticky,
            "padx": options.padx.value,
            "pady": options.pady.value,
            "ipadx": options.ipadx,
            "ipady": options.ipady,
        }

    # tkinter's bare names, reached on a widget only where neither Misc nor
    # Pack has one first: location, as in tkinter.
    configure = config = grid_configure
    bbox: Any = Misc.grid_bbox
    columnconfigure = Misc.grid_columnconfigure
    forget = grid_forget
    info = grid_info
    location = Misc.grid_location
    propagate = Misc.grid_propagate
    rowconfigure = Misc.grid_rowconfigure
    size: Any = Misc.grid_size
    slaves: Any = Misc.grid_slaves


def _grid_layout_of(container: Misc) -> GridLayout:
    """The container's grid manager, created on first use.

    Raises:
        TclError: If pack, or a paned window, still lays out a child of the
            container.
    """
    manager = container._layout_manager
    if isinstance(manager, GridLayout):
        return manager
    _make_way(container, "grid")
    manager = GridLayout()
    container._layout_manager = manager
    return manager


def _grid_options(
    given: dict[str, Any], remembered: GridOptions | None = None
) -> GridOptions:
    """Build and check one widget's grid options.

    Raises:
        TclError: If an option is unknown or its value is not one Tk accepts.
    """
    options = (
        GridOptions(**vars(remembered)) if remembered is not None else GridOptions()
    )
    for name, value in given.items():
        if not hasattr(options, name):
            raise TclError(f'unknown option "-{name}"')
        setattr(options, name, value)

    try:
        parse_sticky(options.sticky)
    except ValueError as error:
        raise TclError(str(error)) from None
    for name in ("row", "column"):
        value = getattr(options, name)
        try:
            setattr(options, name, max(0, int(value)))
        except (TypeError, ValueError):
            raise TclError(f'expected integer but got "{value}"') from None
    _check_pads(options, given)
    for name in ("rowspan", "columnspan"):
        value = getattr(options, name)
        try:
            setattr(options, name, max(1, int(value)))
        except (TypeError, ValueError):
            raise TclError(f'expected integer but got "{value}"') from None
    return options


class Place:
    """Placing: put a widget at a position you choose.

    ``x`` and ``y`` are cells from the parent's top left corner, and
    ``relx`` and ``rely`` fractions of its size; the two add up. ``anchor``
    says which point of the widget goes there. Placed widgets may overlap,
    and change nothing about how their parent is sized.

    Sample output:
        frame = tk.Frame(root, width=30, height=8, relief="groove", bd=1)
        frame.pack()
        tk.Label(frame, text="x=1, y=1").place(x=1, y=1)
        tk.Label(frame, text="centre", relief="solid").place(
            relx=0.5, rely=0.5, anchor="center"
        )
    """

    if TYPE_CHECKING:
        master: Misc | None

        # The rest of what a geometry manager needs of the widget this is
        # mixed into - see _core.geometry.Managed, which names exactly these
        # four. Only master was declared, so handing self to the manager
        # type-checked against nothing at all. TkCurses-d40.
        def winfo_reqwidth(self) -> int: ...
        def winfo_reqheight(self) -> int: ...
        def _allocate(self, rect: Rect) -> None: ...

        _manager: str
        _manager_container: Misc | None

        def _map(self) -> None: ...
        def _unmap(self) -> None: ...

        _is_toplevel: bool

        def _managed_layout(self, name: str) -> Layout | None: ...
        def _leave_layout(self, container: Misc) -> None: ...
        def _leave_for(self, container: Misc, manager: str = "") -> None: ...

    def place_configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Place this widget in its container.

        Args:
            cnf: Options as a dictionary, merged with the keywords.
            **kw: ``x``, ``y``, ``width``, ``height`` in cells; ``relx``,
                ``rely``, ``relwidth``, ``relheight`` as fractions of the
                container; ``anchor``; ``bordermode``; and ``in_`` to place
                into something other than the master.

        Raises:
            TclError: If an option or its value is not one Tk accepts. Place
                shares a container with pack or grid, as in Tk.
        """
        options = _given(cnf, kw)
        container = options.pop("in_", None) or options.pop("in", None) or self.master
        if container is None:
            raise TclError("cannot place the root window")
        if self._is_toplevel:
            raise TclError(
                f'can\'t use placer on top-level window "{self}"; use wm command instead'
            )
        layout = _place_layout_of(container)
        current = self._managed_layout("place")
        remembered = (
            current.options_for(self) if isinstance(current, PlaceLayout) else None
        )
        # A geometry call naming a different container is a move, and the
        # container being left has to stop laying this widget out.
        self._leave_for(container, "place")
        layout.add(self, _place_options(options, remembered))
        self._manager = "place"
        self._manager_container = container
        self._map()
        container.tk.layout.invalidate(container)

    place = place_configure

    def place_forget(self) -> None:
        """Stop placing this widget and take it off the screen."""
        container = self._manager_container or self.master
        if container is None or self._manager != "place":
            return
        manager = container._place_manager
        if manager is not None:
            manager.remove(self)
            container.tk.layout.invalidate(container)
        self._manager = ""
        self._manager_container = None
        self._unmap()

    def place_info(self) -> dict[str, Any]:
        """How this widget is placed.

        Raises:
            TclError: If it is not placed.
        """
        container = self._manager_container or self.master
        manager = container._place_manager if container is not None else None
        options = manager.options_for(self) if manager is not None else None
        if options is None:
            raise TclError(f'window "{self}" is not placed')
        return {"in": container, **vars(options)}

    # tkinter's bare names.
    configure = config = place_configure
    forget = place_forget
    info = place_info
    slaves: Any = Misc.place_slaves


def _place_layout_of(container: Misc) -> PlaceLayout:
    """The container's place manager, created on first use.

    Never refused: Tk places over a container that packs or grids, which is
    how a badge or a floating button sits over other content. TkCurses-huq9.
    """
    manager = container._place_manager
    if manager is None:
        manager = PlaceLayout()
        container._place_manager = manager
    return manager


def _place_options(
    given: dict[str, Any], remembered: PlaceOptions | None = None
) -> PlaceOptions:
    """Build and check one widget's placement options.

    Args:
        given: The options named in this call.
        remembered: The options the widget already has, which everything not
            named keeps. None starts from the defaults.

    Raises:
        TclError: If an option is unknown or its value is not one Tk accepts.
    """
    options = (
        PlaceOptions(**vars(remembered)) if remembered is not None else PlaceOptions()
    )
    for name, value in given.items():
        if not hasattr(options, name):
            raise TclError(f'unknown option "-{name}"')
        setattr(options, name, value)

    try:
        parse_anchor(options.anchor)
    except ValueError as error:
        raise TclError(str(error)) from None
    if options.bordermode not in BORDERMODES:
        raise TclError(
            f'bad bordermode "{options.bordermode}": must be {", ".join(BORDERMODES)}'
        )
    for name in ("x", "y"):
        options.__dict__[name] = _place_int(name, getattr(options, name))
    for name in ("width", "height"):
        value = getattr(options, name)
        if value is not None:
            # Not clamped here: a negative width is meaningful alongside
            # relwidth, and the result is clamped once it has been used.
            options.__dict__[name] = _place_int(name, value)
    for name in ("relx", "rely", "relwidth", "relheight"):
        value = getattr(options, name)
        if value is None:
            continue
        try:
            options.__dict__[name] = float(value)
        except (TypeError, ValueError):
            raise TclError(
                f'expected floating-point number but got "{value}"'
            ) from None
    return options


def _place_int(name: str, value: Any) -> int:
    """Parse one of place's cell-valued options: a screen distance, rounded.

    Measured on Tk 9.0.2: ``2.5`` is 3, ``1i`` is converted, ``-2c`` is kept
    negative, and anything else is ``expected screen distance but got``.

    Raises:
        TclError: If it is not a screen distance.
    """
    del name
    if isinstance(value, int):
        return value
    number = _distance_number(value)
    if number is None or math.isnan(number) or math.isinf(number):
        raise TclError(f'expected screen distance but got "{value}"')
    return math.floor(number + 0.5)


class Widget(BaseWidget, Pack, Grid, Place):
    """The base class for every ordinary widget.

    In tkinter this is where the three geometry managers are mixed in
    (``Widget(BaseWidget, Pack, Place, Grid)``); those arrive with the
    geometry manager epic, and this class is where they will attach. Until
    then it is what separates a widget that a manager can place from a
    toplevel that manages itself.
    """


# ======================================================================
# Window manager
# ======================================================================

#: A geometry string: ``WxH``, ``+X+Y``, or both. A leading ``-`` on an offset
#: measures from the right or bottom edge, as in Tk.
_GEOMETRY_RE = re.compile(
    r"^(?:(?P<width>\d+)x(?P<height>\d+))?"
    r"(?:(?P<x>[+-]-?\d+)(?P<y>[+-]-?\d+))?$"
)

#: Window states Tk recognises.
_WM_STATES = ("normal", "iconic", "withdrawn")

#: Attributes wm_attributes understands. Tk's list is mostly X11 compositing
#: and has no meaning for a character cell window; these two do.
_WM_ATTRIBUTES = ("-topmost", "-fullscreen")


def _requested_size(widget: Any) -> tuple[int, int]:
    """The size a widget asks for, at least one cell each way."""
    return max(1, widget.winfo_reqwidth()), max(1, widget.winfo_reqheight())


def _window_rect(widget: Any, width: int, height: int) -> Rect:
    """Where a new window of this size goes: centred, clamped to the screen,
    as a Toplevel's does when nothing has said."""
    screen_width, screen_height = widget._screen_size()
    width = clamp(width, 1, screen_width)
    height = clamp(height, 1, screen_height)
    return Rect(
        max(0, (screen_width - width) // 2),
        max(0, (screen_height - height) // 2),
        width,
        height,
    )


class Wm:
    """Window manager methods for the application and each toplevel.

    There is no window manager: a terminal has one surface, no title bars and
    no close buttons, so these are the library doing for itself what an X11
    window manager would.

    Differences from tkinter:
        A window is always inside the terminal, because there is nowhere for
        it to overflow to. A position or size that would take it outside is
        brought back in, and when the terminal is resized every window is
        moved to stay within it.
    """

    # Held by routing every path that moves or resizes a window through
    # _within_screen, and re-established by _reposition_for_screen when the
    # terminal changes size. The invariant used to be only established, never
    # maintained: the clamp lived in _apply_geometry and so held against
    # whatever the screen was when geometry was last set.

    if TYPE_CHECKING:
        # Supplied by the widget this is mixed into. Declared so the contract
        # is visible and so a mixin referring to them still type-checks.
        tk: Application
        _rect: Rect
        _options: dict[str, Any]
        _is_toplevel: bool

        _menubar_bound: bool
        _menubar_shown: Menu | None

        @property
        def _border_drawn(self) -> bool: ...

        def bind(
            self,
            sequence: str | None = None,
            func: Callable[[Event], Any] | None = None,
            add: bool | str | None = None,
        ) -> Any: ...
        def _allocate(self, rect: Rect) -> None: ...
        def _map(self) -> None: ...
        def _unmap(self) -> None: ...
        def _screen_size(self) -> tuple[int, int]: ...
        def winfo_exists(self) -> bool: ...
        def tkraise(self, aboveThis: Misc | None = None) -> None: ...
        def _invalidate_layout(self) -> None: ...

    def _attach_menubar(self) -> None:
        """Lay the window's ``menu`` across its top row, and keep it there.

        The menubar is a Menu like any other, drawn in a row instead of a
        box. It is positioned here rather than by a geometry manager because
        it is not part of the layout: the window takes its row away from the
        children first, and what is left is what they are offered. A
        ``<Configure>`` binding re-places it, so the bar follows the window
        when the terminal is resized.
        """
        bar = _menubar_of(self)
        old = self._menubar_shown
        if old is not None and old is not bar:
            # Replaced or removed: the old bar goes back to being an ordinary
            # menu, off screen, and its row goes back to the children. Left
            # alone it stayed drawn and live on top of whatever took the row.
            old._as_menubar = False
            if old.winfo_exists():
                old._unmap()
            self._invalidate_layout()
        self._menubar_shown = bar
        if bar is None:
            return
        if old is None:
            self._invalidate_layout()
        if not self._menubar_bound:
            self._menubar_bound = True
            self.bind("<Configure>", lambda _event: self._place_menubar(), add=True)
        self._place_menubar()

    def _place_menubar(self) -> None:
        """Put the menubar across the top of this window's border."""
        bar = self._menubar_shown
        if bar is None or not bar.winfo_exists():
            return
        bar._as_menubar = True
        bar._apply_requested_size()
        edge = BORDER_WIDTH if self._border_drawn else 0
        bar._allocate(Rect(edge, edge, max(0, self._rect.width - 2 * edge), 1))
        bar._map()
        bar._redraw()

    def _setup_wm(self) -> None:
        """Initialise the window manager state.

        Called from the constructor of each window class rather than from an
        ``__init__`` here: the mixin has no say in the order a widget builds
        itself, and these defaults have to be in place before geometry is.
        """
        self._menubar_bound = False
        self._menubar_shown = None
        self._title = ""
        self._protocols: dict[str, Callable[[], Any]] = {}
        self._min_size: tuple[int, int] = (1, 1)
        self._max_size: tuple[int, int] | None = None
        self._resizable: tuple[bool, bool] = (True, True)
        self._wm_state = "normal"
        self._transient_for: Misc | None = None
        self._overrideredirect = False
        self._focus_model = "passive"
        self._grid_spec: tuple[int, int, int, int] | None = None
        self._topmost = False
        self._fullscreen = False
        # Hints for a window manager, kept so that each reads back what was
        # set: wm_iconname, wm_group and the rest below.
        self._hints: dict[str, Any] = {}

    # ------------------------------------------------------------- titling

    def wm_title(self, string: str | None = None) -> str:
        """Get or set the window's title.

        A toplevel draws it centred on its top border, which is the only title
        bar there is. The main window has nowhere to put one and keeps it
        without showing it.

        Sample output:
            # size: 40x8
            top = tk.Toplevel(root)
            top.title("Untitled - Notes")
            top.geometry("26x4+1+1")
        """
        if string is not None:
            self._title = str(string)
            self._redraw_decoration()
        return self._title

    title = wm_title

    # ------------------------------------------------------------ geometry

    def wm_geometry(self, newGeometry: str | None = None) -> str:
        """Get or set size and position as ``WxH+X+Y``, in cells.

        Accepts the partial forms Tk does - ``80x24`` alone, ``+4+2`` alone -
        and a ``-`` offset measuring from the right or bottom edge. The result
        is clamped to the terminal, which a window cannot exceed and outside
        which it cannot be placed.

        Setting has no effect on the root: its size is the terminal's, and
        nothing here can resize that. The call is accepted rather than
        refused, because ``root.geometry("400x300")`` appears in most tkinter
        programs and failing on it would break them for no gain.

        Raises:
            TclError: If the geometry string cannot be parsed.
        """
        if newGeometry is not None and self._is_resizable_window():
            self._apply_geometry(newGeometry)
        rect = self._rect
        return f"{rect.width}x{rect.height}+{rect.x}+{rect.y}"

    geometry = wm_geometry

    #: The geometry the application last asked for, before the screen had its
    #: say. A window displaced by a shrinking terminal returns here when
    #: there is room again; None until geometry() is called.
    _wanted_rect: Rect | None = None

    def _is_resizable_window(self) -> bool:
        """False for the root, whose geometry the terminal decides."""
        return not isinstance(self, Tk)

    def _within_screen(self, rect: Rect) -> Rect:
        """``rect`` brought inside the terminal, size first and then position.

        **The one place that decides where a window may be.** Every path that
        moves or resizes a window goes through here, which is what makes
        "geometry is clamped to the terminal" an invariant rather than
        something that happened to be true when it was last set.

        It was the latter for a long time. The clamp lived inside
        ``_apply_geometry``, so it held against the screen size at the moment
        geometry was set and nothing re-established it afterwards. Two paths
        walked straight past it: a terminal resize, which changes the screen
        rather than the window, and ``minsize``, which grows a window without
        going near ``geometry()``. Measured before this existed, a window at
        ``+30+10`` on a terminal shrunk to 28x8 still reported ``+30+10`` -
        a position ``geometry()`` itself, asked for it, would have refused.

        Size before position, because the position a window can have depends
        on how big it is: clamping x against the old width leaves a window
        hanging off the edge by however much it then shrinks.
        """
        width, height = self._clamp_size(rect.width, rect.height)
        screen_width, screen_height = self._screen_size()
        return Rect(
            clamp(rect.x, 0, max(0, screen_width - width)),
            clamp(rect.y, 0, max(0, screen_height - height)),
            width,
            height,
        )

    def _reposition_for_screen(self) -> None:
        """Put this window back inside a terminal that has changed size.

        Called for every window when the terminal is resized. Two things
        happen, and the second is what keeps the first from being destructive.

        The window is brought inside the new screen, so it cannot end up
        somewhere nothing can reach. That matters most for a modal window:
        measured before this, shrinking the terminal under a dialog left it
        invisible, still holding the grab, and every click in the application
        going to a window nobody could see - a button that looked entirely
        normal and did nothing, with nothing on screen to explain it.

        And the position the application actually asked for is remembered, so
        that growing the terminal again puts the window back where it was
        rather than leaving it wherever a transient shrink pushed it. Without
        that, a one-column shrink and back would quietly rearrange the screen.
        """
        wanted = self._wanted_rect or self._rect
        target = self._within_screen(wanted)
        if target != self._rect:
            self._allocate(target)

    def _apply_geometry(self, spec: str) -> None:
        """Parse a geometry string and move or resize the window to match."""
        match = _GEOMETRY_RE.match(spec.strip())
        if match is None or not any(match.groupdict().values()):
            raise TclError(f'bad geometry specifier "{spec}"')
        screen_width, screen_height = self._screen_size()
        rect = self._rect

        width, height = rect.width, rect.height
        if match["width"] is not None:
            if self._resizable[0]:
                width = int(match["width"])
            if self._resizable[1]:
                height = int(match["height"])
        width, height = self._clamp_size(width, height)

        x, y = rect.x, rect.y
        if match["x"] is not None:
            x = self._edge_offset(match["x"], screen_width, width)
            y = self._edge_offset(match["y"], screen_height, height)
        # What the application asked for, before the screen has its say. This
        # is what the window goes back to if a shrink displaces it and the
        # terminal is later big enough again, and an explicit geometry() call
        # replaces it - a position the application named is the one it meant.
        self._wanted_rect = Rect(x, y, width, height)
        self._allocate(self._within_screen(Rect(x, y, width, height)))

    @staticmethod
    def _edge_offset(token: str, screen: int, extent: int) -> int:
        """Resolve one ``+n`` or ``-n`` offset into a left or top position.

        ``-n`` measures from the far edge, so ``-0`` is flush right and
        ``-10`` leaves ten cells beyond the window.
        """
        value = int(token[1:])
        if token[0] == "-":
            return screen - extent - value
        return value

    def _clamp_size(self, width: int, height: int) -> tuple[int, int]:
        """Hold a size within the window's own limits and the terminal's."""
        screen_width, screen_height = self._screen_size()
        min_width, min_height = self._min_size
        max_width, max_height = self._max_size or (screen_width, screen_height)
        return (
            clamp(width, min_width, min(max_width, screen_width)),
            clamp(height, min_height, min(max_height, screen_height)),
        )

    def wm_minsize(self, width: int | None = None, height: int | None = None) -> Any:
        """Get or set the smallest size this window may be given."""
        if width is None:
            return self._min_size
        self._min_size = (max(1, int(width)), max(1, int(height or 1)))
        self._reapply_size()
        return None

    minsize = wm_minsize

    def wm_maxsize(self, width: int | None = None, height: int | None = None) -> Any:
        """Get or set the largest size this window may be given."""
        if width is None:
            return self._max_size or self._screen_size()
        self._max_size = (int(width), int(height or 1))
        self._reapply_size()
        return None

    maxsize = wm_maxsize

    def wm_resizable(
        self, width: bool | None = None, height: bool | None = None
    ) -> Any:
        """Get or set whether each axis may be resized.

        A locked axis is left alone by :meth:`wm_geometry` rather than making
        the call fail, which is how Tk behaves when a window manager refuses
        a resize.
        """
        if width is None:
            return self._resizable
        self._resizable = (bool(width), bool(height))
        return None

    resizable = wm_resizable

    def _reapply_size(self) -> None:
        """Re-clamp the current size after the limits changed."""
        if not self._is_resizable_window():
            return
        # Through _within_screen rather than _clamp_size alone: a window at
        # the edge that minsize makes bigger has to come back inside, and
        # measured before this it did not - minsize(24, 9) on a 10x4 window
        # at +28+7 of a 40x12 terminal left it hanging 12 columns and 4 rows
        # off the screen, with no resize involved at all.
        target = self._within_screen(self._rect)
        if target != self._rect:
            self._allocate(target)

    def wm_grid(
        self,
        baseWidth: int | None = None,
        baseHeight: int | None = None,
        widthInc: int | None = None,
        heightInc: int | None = None,
    ) -> Any:
        """Get or set the window's size increments.

        Tk uses this to make a window resize in units of a text cell. Here
        every window already does, so this records the request and reports it
        back rather than changing anything.
        """
        if baseWidth is None:
            return self._grid_spec
        self._grid_spec = (
            int(baseWidth),
            int(baseHeight or 0),
            int(widthInc or 1),
            int(heightInc or 1),
        )
        return None

    grid = wm_grid

    # --------------------------------------------------------------- state

    def wm_state(self, newstate: str | None = None) -> str:
        """Get or set the window state: normal, iconic, or withdrawn.

        Iconic and withdrawn both take the window off the screen; they differ
        in intent, and a window manager would show an icon for the first.
        There is nowhere to put an icon, so the two look the same here and
        remain distinct only in what :meth:`wm_state` reports.

        Raises:
            TclError: If the state is not one Tk recognises.
        """
        if newstate is None:
            return self._wm_state
        if newstate not in _WM_STATES:
            raise TclError(f'bad window state "{newstate}"')
        if newstate == "normal":
            self.wm_deiconify()
        elif newstate == "iconic":
            self.wm_iconify()
        else:
            self.wm_withdraw()
        return self._wm_state

    state = wm_state

    def wm_withdraw(self) -> None:
        """Take the window off the screen, forgetting it was ever placed."""
        self._wm_state = "withdrawn"
        self._unmap()

    withdraw = wm_withdraw

    def wm_iconify(self) -> None:
        """Take the window off the screen, as minimising would."""
        self._wm_state = "iconic"
        self._unmap()

    iconify = wm_iconify

    def wm_deiconify(self) -> None:
        """Put the window back on the screen."""
        self._wm_state = "normal"
        self._map()
        self._redraw_decoration()

    deiconify = wm_deiconify

    # ----------------------------------------------------------- protocols

    def wm_protocol(
        self, name: str | None = None, func: Callable[[], Any] | None = None
    ) -> Any:
        """Register, query, or list window manager protocol handlers.

        ``WM_DELETE_WINDOW`` is the one worth having, and **Ctrl-C raises it**.
        A terminal has no close button, but it does have the gesture: Ctrl-C on
        an application that has not bound ``<Control-c>`` is a person saying
        "stop this", and :meth:`Tk.mainloop` delivers it here. A handler may
        save, may ask, or may return and leave the application running; with no
        handler the application closes.
        """
        # This docstring used to say that nothing raised it. The mechanism was
        # right and the gesture had been missed. The dialogs invoke it
        # themselves through _invoke_protocol.
        if name is None:
            return tuple(self._protocols)
        if func is None:
            return self._protocols.get(name)
        self._protocols[name] = func
        return None

    protocol = wm_protocol

    def _invoke_protocol(self, name: str) -> bool:
        """Run a registered protocol handler. True if there was one."""
        handler = self._protocols.get(name)
        if handler is None:
            return False
        handler()
        return True

    # -------------------------------------------------------- relationships

    def wm_transient(self, master: Misc | None = None) -> Misc | None:
        """Get or set the window this one is a transient of.

        A transient window belongs to another - a dialog to the window that
        opened it - and follows it: it stays in front of its owner, and goes
        off the screen when the owner does.
        """
        if master is None:
            return self._transient_for
        self._transient_for = master
        self.tkraise(master)
        return None

    transient = wm_transient

    def wm_frame(self) -> str:
        """The window's identifier.

        Tk returns the window manager's frame id, which is a different window
        wrapped around this one. There is no frame, so this is the window's
        own id.
        """
        return str(self.winfo_id())  # type: ignore[attr-defined]

    frame = wm_frame

    def wm_focusmodel(self, model: str | None = None) -> str:
        """Get or set the focus model.

        Recorded rather than acted on: both models describe how a window
        manager hands focus to a window, and focus here never leaves the
        application.

        Raises:
            TclError: If the model is neither "active" nor "passive".
        """
        if model is None:
            return self._focus_model
        if model not in ("active", "passive"):
            raise TclError(f'bad focus model "{model}"')
        self._focus_model = model
        return self._focus_model

    focusmodel = wm_focusmodel

    # ---------------------------------------------------------- decoration

    def wm_overrideredirect(self, boolean: bool | None = None) -> bool:
        """Get or set whether the window manager should ignore this window.

        In Tk this strips the title bar and border a window manager would
        add. The equivalent here is the border the window draws for itself,
        since that is the only decoration there is.
        """
        if boolean is None:
            return self._overrideredirect
        self._overrideredirect = bool(boolean)
        self._redraw_decoration()
        return self._overrideredirect

    overrideredirect = wm_overrideredirect

    def wm_attributes(self, *args: Any) -> Any:
        """Get or set window attributes.

        Two are supported. ``-topmost`` keeps the window in front of the
        others; ``-fullscreen`` makes it the size of the terminal. The rest of
        Tk's list describes X11 compositing - transparency, window type hints -
        and has no meaning for a grid of characters.

        Raises:
            TclError: If an attribute is not one of the supported two.
        """
        if not args:
            return (
                "-topmost",
                self._topmost,
                "-fullscreen",
                self._fullscreen,
            )
        if len(args) == 1:
            return self._attribute(self._checked_attribute(args[0]))
        for name, value in zip(args[::2], args[1::2], strict=False):
            self._set_attribute(self._checked_attribute(name), value)
        return None

    attributes = wm_attributes

    @staticmethod
    def _checked_attribute(name: str) -> str:
        """Validate an attribute name, which Tk spells with a leading dash."""
        if name not in _WM_ATTRIBUTES:
            raise TclError(f'bad attribute "{name}"')
        return str(name)

    def _attribute(self, name: str) -> Any:
        """Read one attribute."""
        return self._topmost if name == "-topmost" else self._fullscreen

    def _set_attribute(self, name: str, value: Any) -> None:
        """Write one attribute, applying what it means."""
        if name == "-topmost":
            self._topmost = bool(value)
            if self._topmost:
                self.tkraise()
            return
        self._fullscreen = bool(value)
        if self._fullscreen and self._is_resizable_window():
            width, height = self._screen_size()
            self._allocate(Rect(0, 0, width, height))

    def _redraw_decoration(self) -> None:
        """Repaint whatever decoration this window draws.

        The root draws none; Toplevel overrides this.
        """

    # ------------------------------------------------------------ reparenting

    def wm_manage(self, widget: Misc) -> None:
        """Make ``widget`` a window of its own.

        It leaves whichever geometry manager had it, keeps its master, its
        children and its bindings, and is drawn where a new toplevel would
        be, at the size it asks for. ``winfo_manager`` then answers ``wm``,
        and packing, gridding or placing it is refused until
        :meth:`wm_forget` hands it back. A Toplevel that was forgotten is a
        window again; one that is a window already is left as it is.

        Raises:
            TclError: If ``widget`` is not a Frame, LabelFrame or Toplevel,
                in Tk's words. A themed frame is not one, as in Tk.
        """
        # Measured on Tk 9.0.2.
        if isinstance(widget, Toplevel):
            if not widget._is_toplevel:
                widget._leave_manager()
                del widget._is_toplevel  # back to the class's True
                widget._allocate(widget._default_rect())
                widget._map()
            return
        if not isinstance(widget, (Frame, LabelFrame)) or _is_ttk(widget):
            raise TclError(
                f'window "{widget}" is not manageable: must be a frame,'
                " labelframe or toplevel"
            )
        if widget._is_toplevel:
            return
        widget._leave_manager()
        widget._is_toplevel = True
        widget._manager = "wm"
        widget._allocate(_window_rect(widget, *_requested_size(widget)))
        widget._map()

    manage = wm_manage

    def wm_forget(self, window: Misc) -> None:
        """Take ``window`` off the screen as a window, so that a geometry
        manager can lay it out inside its master.

        It is unmapped until one does, and its children's
        ``winfo_toplevel`` is its own again. The root, and a widget that is
        not a window, are left alone, as in Tk.
        """
        if (
            not isinstance(window, BaseWidget)
            or window.master is None
            or not window._is_toplevel
        ):
            return
        window._is_toplevel = False
        window._manager = ""
        window._unmap()

    forget = wm_forget

    # ------------------------------------------------- hints with no effect
    #
    # Each asks a window manager for something a terminal has none of - an
    # icon, a group, a session's command line, an aspect ratio. Each is
    # checked as Tk 9.0.2 on X11 checks it, kept, and read back, so that a
    # program setting one runs unchanged and one reading one back gets what
    # it set. Nothing on the screen changes.

    def _hint(self, name: str, value: Any, empty: Any = "") -> Any:
        """Set the hint ``name`` when a value is given and answer ``""``, or
        answer the one it has: ``empty`` for none, or a cleared one."""
        if value is None:
            return self._hints.get(name, empty)
        if value == "":
            self._hints.pop(name, None)
        else:
            self._hints[name] = value
        return ""

    def _window_path(self, window: Any) -> str:
        """``window``'s path name, refused as Tk refuses a path naming no
        window."""
        text = str(window)
        try:
            self.nametowidget(text)  # type: ignore[attr-defined]
        except (KeyError, TclError):
            raise TclError(f'bad window path name "{text}"') from None
        return text

    @staticmethod
    def _hint_ints(values: tuple[Any, ...]) -> tuple[int, ...]:
        """Whole numbers for ``wm aspect`` or ``wm iconposition``, or all
        empty to clear them: an empty tuple."""
        if all(value == "" for value in values):
            return ()
        numbers = []
        for value in values:
            number = _tcl_number(value)
            if not isinstance(number, int) or isinstance(number, bool):
                raise TclError(f'expected integer but got "{value}"')
            numbers.append(number)
        return tuple(numbers)

    def wm_aspect(
        self,
        minNumer: Any = None,
        minDenom: Any = None,
        maxNumer: Any = None,
        maxDenom: Any = None,
    ) -> tuple[int, int, int, int] | None:
        """Get or set the range of width-to-height ratios the window may have.

        Kept and read back; the window is not held to it. Four empty
        strings clear it.

        Raises:
            TclError: If only some of the four are given, one is not a whole
                number, or one is not above zero.
        """
        given = (minNumer, minDenom, maxNumer, maxDenom)
        if all(value is None for value in given):
            return self._hints.get("aspect")
        if any(value is None for value in given):
            raise TclError(
                'wrong # args: should be "wm aspect window '
                '?minNumer minDenom maxNumer maxDenom?"'
            )
        numbers = self._hint_ints(given)
        if any(number <= 0 for number in numbers):
            raise TclError("aspect number can't be <= 0")
        self._hint("aspect", numbers or "")
        return None

    aspect = wm_aspect

    def wm_client(self, name: str | None = None) -> str:
        """Get or set the name of the machine the program runs on, for a
        session manager. Kept and read back; ``""`` clears it."""
        return str(self._hint("client", name))

    client = wm_client

    def wm_colormapwindows(self, *wlist: Any) -> list[Misc] | None:
        """Get or set the windows whose colour maps the window manager should
        install. Kept and read back as the widgets; nothing is installed.

        Raises:
            TclError: If one names no window.
        """
        if not wlist:
            paths = self._hints.get("colormapwindows", [])
            return [self.nametowidget(path) for path in paths]  # type: ignore[attr-defined]
        if len(wlist) == 1 and isinstance(wlist[0], (list, tuple)):
            wlist = tuple(wlist[0])
        self._hints["colormapwindows"] = [self._window_path(w) for w in wlist]
        return None

    colormapwindows = wm_colormapwindows

    def wm_command(self, value: Any = None) -> str:
        """Get or set the command line that would start the program again,
        for a session manager. Kept and read back; ``""`` clears it."""
        if isinstance(value, (list, tuple)):
            value = " ".join(str(part) for part in value)
        return str(self._hint("command", value))

    command = wm_command

    def wm_group(self, pathName: Any = None) -> str:
        """Get or set the window that leads this one's group, as a path name.
        Kept and read back; ``""`` clears it.

        Raises:
            TclError: If the path names no window.
        """
        if pathName is None or pathName == "":
            return str(self._hint("group", pathName))
        return str(self._hint("group", self._window_path(pathName)))

    group = wm_group

    def wm_iconbitmap(self, bitmap: Any = None, default: Any = None) -> str:
        """Get or set the bitmap for the window's icon: one of Tk's built-in
        names or ``@file``. Kept and read back; there is no icon.

        Differences from tkinter:
            ``default``, which on Windows sets the icon of windows yet to be
            made, is refused, as Tk on X11 refuses it.

        Raises:
            TclError: If the bitmap is not one Tk knows, or ``default`` is
                given.
        """
        if default is not None:
            raise TclError('wrong # args: should be "wm iconbitmap window ?bitmap?"')
        if bitmap is None or bitmap == "":
            return str(self._hint("iconbitmap", bitmap))
        return str(self._hint("iconbitmap", _bitmap(self, bitmap)))

    iconbitmap = wm_iconbitmap

    def wm_iconmask(self, bitmap: Any = None) -> str:
        """Get or set the mask for the window's icon bitmap. Kept and read
        back, as :meth:`wm_iconbitmap`.

        Raises:
            TclError: If the bitmap is not one Tk knows.
        """
        if bitmap is None or bitmap == "":
            return str(self._hint("iconmask", bitmap))
        return str(self._hint("iconmask", _bitmap(self, bitmap)))

    iconmask = wm_iconmask

    def wm_iconname(self, newName: str | None = None) -> str:
        """Get or set the name shown with the window's icon. Kept and read
        back; ``""`` clears it."""
        return str(self._hint("iconname", newName))

    iconname = wm_iconname

    def wm_iconphoto(self, default: bool = False, *args: Any) -> None:
        """Set the window's icon from one or more photo images. Checked and
        kept; there is no icon to show.

        Raises:
            TclError: If no image is given, or one is not a photo image.
        """
        if not args:
            raise TclError(
                'wrong # args: should be "wm iconphoto window ?-default? '
                'image1 ?image2 ...?"'
            )
        names = []
        for image in args:
            name = str(image)
            found = self.tk.images.get(name)
            kind = getattr(found, "type", None)
            if found is None or not callable(kind) or kind() != "photo":
                raise TclError(f'can\'t use "{name}" as iconphoto: not a photo image')
            names.append(name)
        self._hints["iconphoto"] = names
        if default:
            self._hints["iconphoto_default"] = names
        return None

    iconphoto = wm_iconphoto

    def wm_iconposition(self, x: Any = None, y: Any = None) -> tuple[int, int] | None:
        """Get or set where the window's icon should go. Kept and read back;
        two empty strings clear it.

        Raises:
            TclError: If only one is given, or one is not a whole number.
        """
        if x is None and y is None:
            return self._hints.get("iconposition")
        if x is None or y is None:
            raise TclError('wrong # args: should be "wm iconposition window ?x y?"')
        numbers = self._hint_ints((x, y))
        self._hint("iconposition", numbers or "")
        return None

    iconposition = wm_iconposition

    def wm_iconwindow(self, pathName: Any = None) -> str:
        """Get or set a window to show as this one's icon, as a path name.
        Kept and read back; the window is not used.

        Raises:
            TclError: If the path names no window.
        """
        if pathName is None or pathName == "":
            return str(self._hint("iconwindow", pathName))
        return str(self._hint("iconwindow", self._window_path(pathName)))

    iconwindow = wm_iconwindow

    def _who_from(self, name: str, who: str | None) -> str:
        """``wm positionfrom`` and ``wm sizefrom``: ``program``, ``user``,
        or ``""``, abbreviated as Tk allows."""
        if who is None or who == "":
            return str(self._hint(name, who))
        for choice in ("program", "user"):
            if choice.startswith(who):
                return str(self._hint(name, choice))
        raise TclError(f'bad argument "{who}": must be program or user')

    def wm_positionfrom(self, who: str | None = None) -> str:
        """Get or set who chose the window's position, ``program`` or
        ``user``. Kept and read back; it changes nothing here.

        Raises:
            TclError: If it is neither.
        """
        return self._who_from("positionfrom", who)

    positionfrom = wm_positionfrom

    def wm_sizefrom(self, who: str | None = None) -> str:
        """Get or set who chose the window's size, ``program`` or ``user``.
        Kept and read back; it changes nothing here.

        Raises:
            TclError: If it is neither.
        """
        return self._who_from("sizefrom", who)

    sizefrom = wm_sizefrom


# ======================================================================
# The root window
# ======================================================================

#: Longest the loop will wait on input when no timer is due. It does not sit
#: on a blocking read forever: quit() may be called from another thread, a
#: SIGWINCH may need servicing, and work queued through the dispatcher has to
#: be picked up. A twentieth of a second is below the threshold of noticing
#: and costs nothing while idle.
_IDLE_TIMEOUT_MS = 50

#: The exit status of a program whose terminal hung up under ``mainloop``:
#: 128 + SIGHUP, what a shell reports for a process the signal killed.
_HANGUP_EXIT_STATUS = 129

#: How many queued cross-thread calls to run per pass. Bounded so a thread
#: posting work in a tight loop cannot starve input handling.
_DISPATCH_BATCH = 64

#: How many input events to handle per pass, for the same reason: a terminal
#: sending without pause - a mouse dragged across a large screen, a long
#: paste - held the loop in input until it stopped, and a 10 ms timer ran
#: once in seven seconds of drag reports. Measured, TkCurses-tcbj.21.
_INPUT_BATCH = 256

#: The root that currently owns the terminal. Curses is process-global -
#: there is one screen, whatever the object model says - so a second live
#: root is refused rather than allowed to corrupt the first.
_active_root: Tk | None = None


def _backdrop_cells(
    image: Image, width: int, height: int, edge: int, tile: bool
) -> dict[tuple[int, int], tuple[str, str, str | None]]:
    """The cells a ``backgroundimage`` paints in a window of ``width`` by
    ``height`` cells with ``edge`` cells of border, keyed by ``(column, row)``.

    Follows ``DrawFrameBackground`` in Tk's tkFrame.c, in pixels - a cell is
    one pixel wide and two tall, as everywhere an image is drawn. Tiled, the
    first copy starts at the top left of the inside of the border and the
    copies are cut off there. Centred, an image that fits is centred on the
    whole window, border included; one that does not is cut to the inside of
    the border, keeping its middle. Composed in the window's own pixels rather
    than the image's, so an image centred on an odd pixel row pairs its rows
    where they land.
    """
    image_width, image_height = image.width(), image.height()
    across, down = width, height * ROWS_PER_CELL
    left, top = edge, edge * ROWS_PER_CELL
    inner_width, inner_height = across - 2 * left, down - 2 * top
    if min(image_width, image_height, inner_width, inner_height) <= 0:
        return {}
    pixels: dict[tuple[int, int], str] = {}
    if tile:
        lit = image.lit(
            (0, 0, min(image_width, inner_width), min(image_height, inner_height))
        )
        right, bottom = left + inner_width, top + inner_height
        for x0 in range(left, right, image_width):
            for y0 in range(top, bottom, image_height):
                for (x, y), colour in lit.items():
                    if x0 + x < right and y0 + y < bottom:
                        pixels[(x0 + x, y0 + y)] = colour
        return compose(pixels)

    def fitted(inner: int, size: int, whole: int, start: int) -> tuple[int, int, int]:
        # (first source pixel, how many, where they go): Tk's two branches.
        if inner > size:
            return 0, size, (whole - size) // 2
        return (size - inner) // 2, inner, start

    source_x, shown_x, at_x = fitted(inner_width, image_width, across, left)
    source_y, shown_y, at_y = fitted(inner_height, image_height, down, top)
    region = (source_x, source_y, source_x + shown_x, source_y + shown_y)
    for (x, y), colour in image.lit(region).items():
        pixels[(at_x + x - source_x, at_y + y - source_y)] = colour
    return compose(pixels)


def _repaint_backdrop_when_collected(reference: weakref.ref[Any]) -> None:
    """Repaint the window behind ``reference``, its background image gone.

    Module level and weak for the reason
    :func:`_repaint_when_image_is_collected` gives.
    """
    widget = reference()
    if widget is not None and widget.winfo_exists():
        widget._repaint_backdrop()


# The mixin is typed as the widget it is mixed into; at run time it is a
# plain class, so the MRO of Frame, Toplevel and Tk is unchanged.
if TYPE_CHECKING:
    _BackdropBase = BaseWidget
else:
    _BackdropBase = object


class _Backdrop(_BackdropBase):
    """``backgroundimage`` and ``tile``, shared by the frame, the toplevel
    and the root - the three windows Tk gives the option to.

    Tk's labelframe has neither ``backgroundimage`` nor ``bgimg``, so
    LabelFrame, built on Frame here, hides them from a program.
    """

    #: ``bgimg`` is Tk's own short spelling of the option.
    _option_synonyms: ClassVar[dict[str, str]] = {
        **_OPTION_ALIASES,
        "bgimg": "backgroundimage",
    }

    #: The image the option names and is listening to, kept by NAME, as a
    #: Label's is: holding the object would make the window its image's owner.
    _backdrop_watched: str = ""
    _backdrop_finalizer: weakref.finalize[Any, None] | None = None
    #: The last cells composed, and what they were composed for: a whole
    #: window of pixels is too much to fold again on every repaint.
    _backdrop_cache: tuple[tuple[Any, ...], dict[Any, Any]] | None = None

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """The shared checks, and Tk's for the background image.

        Tk looks the image up again on every configure that sets anything,
        not only when the option changes. Measured on Tk 9.0.2: once a
        frame's image has been deleted, ``configure(width=10)`` is refused
        with ``image "pyimage1" does not exist`` and nothing changes, and
        ``configure(backgroundimage="")`` is what lets the frame be
        configured again.
        """
        resolved = super()._checked(given)
        if not given or "backgroundimage" not in self._public_options():
            return resolved
        if "backgroundimage" in resolved:
            # The name, which is what Tk stores: cget answers 'pyimage1' for
            # an image passed as an object.
            resolved["backgroundimage"] = str(resolved["backgroundimage"] or "")
            name = resolved["backgroundimage"]
        else:
            name = str(getattr(self, "_options", {}).get("backgroundimage") or "")
        if name and self.tk.images.get(name) is None:
            raise TclError(f'image "{name}" does not exist')
        return resolved

    def _follow_backdrop(self) -> None:
        """Listen to the background image, dropping any previous one."""
        previous = self.tk.images.get(self._backdrop_watched)
        if previous is not None:
            previous._unwatch(self)
        if self._backdrop_finalizer is not None:
            self._backdrop_finalizer.detach()
            self._backdrop_finalizer = None
        self._backdrop_watched = ""
        self._backdrop_cache = None
        name = str(self._options.get("backgroundimage") or "")
        image = self.tk.images.get(name) if name else None
        if image is None:
            return
        image._watch(self, self._backdrop_image_changed)
        self._backdrop_watched = name
        self._backdrop_finalizer = weakref.finalize(
            image, _repaint_backdrop_when_collected, weakref.ref(self)
        )

    def _backdrop_image_changed(self) -> None:
        """Repaint after the image moved. The window keeps its size: Tk's
        frame asks for none on its image's account."""
        self._backdrop_cache = None
        self._repaint_backdrop()

    def _repaint_backdrop(self) -> None:
        """Paint the window again; the root paints the screen instead."""
        self._redraw()

    def _backdrop(
        self, width: int, height: int, edge: int
    ) -> dict[tuple[int, int], tuple[str, str, str | None]]:
        """The cells the background image paints, or none."""
        name = str(self._options.get("backgroundimage") or "")
        image = self.tk.images.get(name) if name else None
        if image is None:
            return {}
        tile = bool(self._options.get("tile"))
        key = (id(image), width, height, edge, tile)
        cached = self._backdrop_cache
        if cached is None or cached[0] != key:
            cached = (key, _backdrop_cells(image, width, height, edge, tile))
            self._backdrop_cache = cached
        return cached[1]

    def _paint_backdrop(
        self, dispatcher: CursesDispatcher, window: Any, edge: int, background: str
    ) -> None:
        """Paint the background image into ``window``, inside ``edge``.

        Through curses only, never the direct painter a Label's image also
        uses: that writes over everything after curses has finished, and a
        background is the one image that has windows in front of it.
        """
        rect = self._rect
        colors = self.tk.colors
        name = str(self._options.get("backgroundimage") or "")
        image = self.tk.images.get(name) if name else None
        # Fitted to the colour pairs left, as a Label's picture is.
        palette = (
            _pair_palette(image, colors)
            if colors is not None and image is not None
            else None
        ) or {}
        for (column, row), (glyph, fore, back) in self._backdrop(
            rect.width, rect.height, edge
        ).items():
            attribute = (
                _curses.A_NORMAL
                if colors is None
                else colors.attribute_for(
                    palette.get(fore, fore),
                    background if back is None else palette.get(back, back),
                )
            )
            self._write_line(dispatcher, window, row, column, glyph, attribute)


class Tk(_Backdrop, BaseWidget, Wm):
    """The application: its main window, and the event loop that drives
    everything.

    Creating one takes over the terminal; destroying it gives the terminal
    back, and that happens even when the application fails, so a program that
    dies does not leave the shell unusable. Only one may exist at a time,
    because the terminal is shared by the whole process.

    Sample output:
        tk.Label(root, text="Hello from the main window").pack()

    Its ``background`` fills every cell no widget covers, and its ``padx``
    and ``pady`` keep its children that far from the terminal's edges.

    Differences from tkinter:
        The main window is the whole terminal: its size is the terminal's,
        and it has no title bar, so a title is kept and not shown.
        ``background`` is empty until set, which leaves the terminal's own
        colour showing, where Tk's root starts with a light grey. A
        ``backgroundimage`` fills the screen behind every window, as
        :class:`Frame` describes; the root draws no border, so it starts at
        the top left corner.

        Where tkinter raises ``TclError`` for a display it cannot connect
        to, this raises one for a terminal it cannot draw on: one whose
        ``TERM`` has no way to position the cursor, such as ``dumb``.
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"foreground"})

    _is_toplevel = True

    #: The root accepts the standard options; the rest of its configuration
    #: is window manager business.
    #: The menubar this window shows, if any. Declared here as well as on
    #: Toplevel because a menubar on the root window is the common case.
    #:
    #: The window-system options are taken, checked and kept, as on a
    #: Toplevel. ``width`` and ``height`` are kept and change nothing: the
    #: root is the terminal, whose size is the person's to set. TkCurses-gm66.7.
    _widget_options: ClassVar[dict[str, Any]] = {
        **_WINDOW_SYSTEM_OPTIONS,
        "backgroundimage": "",
        "height": 0,
        "menu": None,
        "screen": "",
        "tile": 0,
        "use": "",
        "width": 0,
    }

    _creation_only = frozenset({*_WINDOW_SYSTEM_OPTIONS, "screen", "use"})

    def __init__(
        self,
        screenName: str | None = None,  # noqa: ARG002 - tkinter signature
        baseName: str | None = None,  # noqa: ARG002 - tkinter signature
        className: str = "Tk",
        useTk: bool = True,
        sync: bool = False,  # noqa: ARG002 - tkinter signature
        use: str | None = None,  # noqa: ARG002 - tkinter signature
    ) -> None:
        """
        Args:
            screenName: Ignored. Names an X display, of which there is none.
            baseName: Ignored. Names the resource file tkinter would read.
            className: The widget class this root binds and looks options up
                under, as in tkinter.
            useTk: False leaves the terminal alone until :meth:`loadtk`,
                the nearest thing here to tkinter's Tcl-without-Tk mode.
            sync: Ignored. X11 synchronous mode.
            use: Ignored. Embeds Tk in a foreign window.

        Raises:
            TclError: If another root already owns the terminal.
        """
        global _default_root, _active_root

        if _active_root is not None and _active_root.winfo_exists():
            raise TclError(
                "a Tk() already owns the terminal; destroy it before creating "
                "another, since curses has one screen per process"
            )

        Misc.__init__(self, None, ".")
        self._setup_wm()
        self.className = className
        self._options = dict(self._option_spec())
        self._options["class"] = className
        self._takefocus = True
        self._takefocus_given = False

        self._screen = CursesScreen()
        self._mouse_owner: Misc | None = None
        #: The widget the pointer was last known to be over, which has had
        #: ``<Enter>`` and not yet ``<Leave>``; see :meth:`_cross_before`.
        self._pointer_widget: Misc | None = None
        #: Whether the terminal reports the pointer between presses.
        self._hover_reported = False
        self._input: InputHandler | None = None
        self._motion_asserted = False
        #: A Ctrl-C the loop has yet to answer; see :meth:`_catch_interrupts`.
        self._interrupt_pending = False
        #: A suspend the loop has yet to carry out; see :meth:`_catch_suspend`.
        self._suspend_pending = False
        #: The terminal hung up; the loop ends the program at the end of the
        #: pass. See :meth:`_catch_hangup`.
        self._hangup = False
        #: What puts SIGTSTP back, while this root has it.
        self._release_suspend: Callable[[], None] | None = None
        #: Set while a wait runs before mainloop: a Ctrl-C then cancels the
        #: dialog, as Escape does, instead of closing everything. Inside
        #: mainloop a held grab says the same; see :meth:`_answer_interrupt`.
        self._interrupt_cancels = False
        #: Tracebacks that would have landed on the screen, kept until the
        #: terminal is handed back.
        self._held_reports: list[str] = []
        #: Whether the screen behind the widgets holds a background colour of
        #: the root's, which taking the colour away has to clear.
        self._background_painted = False
        self._started = False
        self._running = False
        #: Whether the root has sent its first <Configure> and <Map>.
        self._announced = False

        if useTk:
            self._start()

        self._install_default_bindings()
        _active_root = self
        if _default_root is None and _support_default_root:
            _default_root = self

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """The shared checks, and Tk's for the root's ``width`` and
        ``height``: measured, -5 reads back 0 and "x" is refused."""
        resolved = super()._checked(given)
        for option in ("width", "height"):
            if option in resolved:
                resolved[option] = _screen_distance(self, resolved[option])
        return resolved

    # ------------------------------------------------------------- startup

    def loadtk(self) -> None:
        """Take over the terminal, if ``Tk(useTk=False)`` did not.

        tkinter's loads Tk into an interpreter made without it. The
        equivalent here is starting curses, so a root that already has, or
        has been destroyed, is left as it is.
        """
        if not self._started and not self._destroyed:
            self._start()

    def readprofile(self, baseName: str, className: str) -> None:
        """Run ``~/.<className>.py`` and then ``~/.<baseName>.py``, if they exist.

        tkinter's profile hook, kept for programs that call it. Each file is
        run with ``self`` bound to this root and everything from
        ``tkcurses`` imported, as tkinter imports itself. The ``.tcl`` files
        tkinter would source beside them are skipped: there is no Tcl.

        Differences from tkinter:
            ``Tk()`` never calls this itself. tkinter's constructor does,
            unless Python was started with ``-E``, which means any program
            would run code from the home directory without asking. A
            program that wants it calls it.

            With ``HOME`` unset nothing is run; tkinter looks in the current
            directory instead, which runs whatever a downloaded folder holds.
            A profile that is not the user's own, or that someone else may
            write to, is skipped, as OpenSSH treats its own files.
        """
        home = os.environ.get("HOME")
        if not home:
            return
        namespace: dict[str, Any] = {"self": self}
        namespace.update((name, globals()[name]) for name in __all__)
        for name in (className, baseName):
            path = Path(home) / f".{name}.py"
            if _a_profile_to_trust(path):
                # Running the user's own profile is what this is for; the
                # file was checked to be theirs and writable by them alone.
                exec(path.read_text(encoding="utf-8"), namespace)  # nosec B102

    def _start(self) -> None:
        """Initialise curses and hang the screen-dependent pieces off it.

        Anything that fails here must still give the terminal back, which is
        why the whole body is guarded rather than just the parts that look
        risky: ``initscr()`` has already changed the terminal by the time the
        next line runs.
        """
        # Before curses starts: deciding on OSC 52 asks the terminal a
        # question, and curses would read the answer as keystrokes.
        settings = TkCursesConfig.load()
        unanswered: list[bool] = []
        route = choose_route(
            settings.clipboard.system,
            os.environ,
            ask_terminal=lambda: ask_terminal_for_osc52(
                unanswered=lambda: unanswered.append(True)
            ),
        )
        if not settings.clipboard.primary:
            route.primary = None
        self.tk.selections.route = route
        buffer = self._screen.start()
        try:
            if not self._screen.addressable:
                # Tk refuses a display it cannot use at construction, with
                # 'couldn't connect to display'; the equivalent here is a
                # terminal that cannot be drawn on.
                raise TclError(
                    "this terminal cannot position the cursor "
                    f"(TERM={os.environ.get('TERM', '')}); "
                    "run in one that can, such as TERM=xterm-256color"
                )
            # Malformed values and settings that no longer do anything, said
            # once the terminal is back: there is nowhere to say them now.
            self._held_reports.extend(
                f"tkcurses: {warning}\n" for warning in settings.warnings
            )
            if not self._screen.utf8:
                self._held_reports.append(_not_utf8_report(os.environ))
            # ncurses cannot tell a lone Escape from the start of an escape
            # sequence until this long has passed with nothing following. The
            # default is a full second, which makes Escape - the key that
            # cancels things - feel broken.
            #
            # Read from the configuration, not hardcoded: a slow serial link
            # or a terminal that splits a sequence across packets needs
            # longer, and until this line existed the setting was accepted,
            # validated and tested while changing nothing at all.
            with contextlib.suppress(AttributeError, _curses.error):
                _curses.set_escdelay(settings.input.escape_delay)
            mouse = settings.mouse
            self._hover_reported = bool(mouse.report_hover and mouse.enabled)
            self._input = InputHandler(
                self._screen.stdscr,
                click_interval=mouse.click_interval,
                report_motion=mouse.report_motion,
                report_hover=mouse.report_hover,
                mouse=mouse.enabled,
                bracketed_paste=settings.input.bracketed_paste,
            )
            if unanswered:
                # The answer may yet come, over a slow link, and curses
                # would read it as typing. TkCurses-tcbj.24.
                self._input.expect_late_reply()
            # Bindings are almost always made before mainloop(), so the
            # terminal has to be told what they wanted once it exists.
            self.tk.input = self._input
            self.tk.refresh_signal_keys()
            mode = settings.display.color_mode
            colors = ColorManager(
                ceiling=ColorDepth(int(mode)) if mode.isdigit() else None
            )
            if colors.start():
                # Cells are painted through this; without colour support the
                # screen keeps its attributes-only resolver.
                self._screen.attribute_resolver = colors.attribute_for
            # Pictures need more (foreground, background) combinations than
            # curses can name - 255, and a photograph wants thousands - so
            # their cells are written past it when the terminal takes direct
            # colour. See _core/direct.py.
            painter = DirectPainter()
            allowed = settings.display.direct_images
            if not allowed:
                pass
            elif (
                colors.depth >= ColorDepth.DIRECT
                or mode == "truecolor"
                or (mode == "auto" and truecolor_hinted())
            ):
                # Exact colour, written as ESC[38;2;r;g;b.
                painter.enable(True)
            elif colors.depth >= ColorDepth.EXTENDED:
                # A palette rather than direct colour, so written as
                # ESC[38;5;N against it. Worth doing for the same reason:
                # a 256-colour terminal has no pair ceiling either once the
                # sequences are written by hand, and going through curses
                # costs a photograph most of its colours.
                painter.enable(True, index_of=colors.index_of)
            self.tk.painter = painter
            # Kept either way, since it is also what anything asking how many
            # colours there are has to ask - and the answer on a terminal
            # without any is a real answer rather than a missing one.
            self.tk.colors = colors
            self._screen.glyphs = (
                None if settings.display.unicode_borders else ASCII_GLYPHS
            )
            self.tk.screen = self._screen
            self.tk.panels = PanelStack()
            # The terminal's own cursor, at the focused widget's insert point;
            # see TerminalCursor. Both flush paths place it.
            cursor = TerminalCursor(
                self._focused_insert_cell, self._focused_cursor_style
            )
            self._screen.cursor = cursor
            self.tk.panels.cursor = cursor
            if self.tk.painter is not None:
                # A widget gone from the screen draws no more, so nothing
                # else would forget its cells: they were painted again over
                # whatever came after it, the next time any picture changed.
                self.tk.panels.on_gone = self.tk.painter.clear
            self._rect = Rect(0, 0, buffer.width, buffer.height)
            self._mapped = True
            self._started = True
            self._paint_background()
            self._release_suspend = self._catch_suspend()
        except BaseException:
            self._screen.stop()
            self._flush_held_reports()
            raise

    def _install_default_bindings(self) -> None:
        """Bindings every application gets, on the ``all`` tag.

        Tab traversal lives here rather than in any widget: moving the focus
        is the application's business, not the business of whichever widget
        happens to have it. Tk does the same, which is why a widget can leave
        Tab alone and still be reachable from the keyboard.

        Registered on ``all``, the last tag consulted, so a widget that wants
        Tab for itself - a text editor inserting one - binds it and returns
        "break" without having to remove anything.
        """
        if "all" in self.tk.bound_classes:
            return
        self.tk.bound_classes.add("all")
        self.bind_all("<Key-Tab>", _focus_next)
        self.bind_all("<Key-ISO_Left_Tab>", _focus_previous)
        # F6 and Shift-F6 as well, because Tab cannot always be spared.
        #
        # A Text wants Tab for indentation, and tkinter's Text takes it: Tk binds
        # <Tab> to insert one and gives traversal to <Control-Tab> instead. That
        # split is not available here - Tab, Control-I and Control-Tab are all the
        # byte 0x09 in a terminal, and the modern CSI encodings for Control-Tab
        # are not parsed, so pressing it would type ";9~" into the document. See
        # TkCurses-87e for the measurements and TkCurses-99j for the parsing.
        #
        # F6 is the conventional "next pane" key - GTK and GNOME use it, and so do
        # many terminal applications - and it survives the journey, measured.
        # Alt-arrows were considered and rejected: i3 and sway bind Mod1+Left and
        # Mod1+Right to window focus by default, so the window manager would eat
        # them before the application saw anything. GNOME reserves Alt-F6 and
        # Shift-Alt-F6 for cycling an application's own windows, which is why the
        # pair here is PLAIN F6 and SHIFT-F6 rather than anything with Alt.
        self.bind_all("<Key-F6>", _focus_next)
        # F18, and this is not a typo. terminfo encodes the shifted function keys
        # as F13 to F24 - this terminal's own kf18 entry is \E[17;2~, which is
        # literally F6 with shift - so Shift-F6 arrives as a key NAMED F18 with
        # no shift bit set. Measured: CSI 17~ gives keysym F6, CSI 17;2~ gives
        # keysym F18, state 0 in both. The <Shift-Key-F6> form is bound too, for
        # a terminal that reports the modifier properly instead.
        self.bind_all("<Key-F18>", _focus_previous)
        self.bind_all("<Shift-Key-F6>", _focus_previous)
        # The menu bar from the keyboard: Tk's menu.tcl binds both on "all"
        # under X11 - "bind all <F10> {tk::FirstMenu %W}" and "bind all
        # <Alt-Key> {tk::TraverseToMenu %W %A}", read from Tk 9.0.2. Without
        # them nothing but the mouse reached the bar (TkCurses-r3og). Alt
        # matters more here: GNOME Terminal keeps F10 for its own menu, and a
        # terminal sends Alt-f as ESC f, which the input layer reads as Alt.
        self.bind_all("<Key-F10>", _first_menu)
        self.bind_all("<Alt-Key>", _traverse_to_menu)

    def winfo_class(self) -> str:
        """The class this root binds and reads options under."""
        return self.className

    # ---------------------------------------------------------- event loop

    def mainloop(self, n: int = 0) -> None:
        """Run until :meth:`quit` is called or the root is destroyed.

        The terminal is given back however the loop ends - normal mode, the
        cursor, the main screen, mouse reporting off - and before an exception
        that ends it is reported, so the traceback appears where it can be read.

        Args:
            n: Run at most this many passes, or unlimited when 0, as tkinter's
                does; it is what lets a test drive the loop a step at a time.

        Differences from tkinter:
            **Ctrl-C closes the application rather than raising
            KeyboardInterrupt.** A TkCurses program *is* the terminal, so Ctrl-C
            is typed by whoever is using it and means "stop": it is delivered to
            ``WM_DELETE_WINDOW``, the protocol for "the user asked to close
            this window". A handler registered with :meth:`Wm.wm_protocol` runs and
            decides - it may save, ask, or let the application carry on - and
            with none the application closes. To have the interrupt itself, bind
            ``<Control-c>``, which takes the key from the terminal entirely;
            raise from a ``WM_DELETE_WINDOW`` handler; or install a SIGINT
            handler.

            It is answered between callbacks, never in the middle of one. A
            second Ctrl-C while a callback has still not returned raises
            KeyboardInterrupt inside it, so a program stuck in a callback
            can still be stopped.

            A dialog - any window holding a grab, or shown before
            ``mainloop()`` - is cancelled by Ctrl-C, as Escape cancels it,
            rather than closing the application; a second Ctrl-C reaches the
            main window. A modal window with no Escape binding is closed as
            if by its ``WM_DELETE_WINDOW`` protocol. With text selected in
            the dialog, Ctrl-C copies it instead, as it does everywhere.

            **The terminal hanging up ends the program with**
            ``SystemExit(129)``. Closing the terminal's window, or losing
            the connection it came over, sends SIGHUP, whose default kills
            the process at once. While the loop runs the hangup is answered
            between callbacks instead, so ``finally`` blocks and ``atexit``
            handlers run - somewhere to save work. 129 is the status a
            shell reports for a process SIGHUP killed. A SIGHUP handler of
            the program's own is left in charge; if the loop goes on
            running, it finds the terminal gone and ends the same way, as
            it does when SIGHUP is ignored.
        """
        # This docstring once claimed the terminal was restored before it was
        # true - measured, Ctrl-C left cbreak, the hidden cursor, the
        # alternate screen and mouse reporting all set. Ctrl-C arrives as a
        # signal only when nothing bound <Control-c>; see
        # _core.application.Application. refresh_signal_keys. wm_protocol used
        # to say nothing raised WM_DELETE_WINDOW; Ctrl-C is that gesture.
        self._running = True
        self.tk.quit_requested = False
        passes = 0
        release = self._catch_interrupts()
        release_hangup = self._catch_hangup()
        try:
            while self._running and not self.tk.quit_requested:
                if not self.winfo_exists():
                    break
                try:
                    self._loop_once()
                except KeyboardInterrupt:
                    # Handled inside the loop rather than let out of it, so
                    # that a handler which decides NOT to close can simply
                    # return and the application carries on - which is how
                    # WM_DELETE_WINDOW behaves everywhere else.
                    if not self._copy_on_interrupt():
                        self._close_requested()
                passes += 1
                if n and passes >= n:
                    break
        except BaseException:
            # Before the exception goes on, not after: something is about to
            # print it on this terminal, and on the alternate screen it
            # would be swapped away unread. KeyboardInterrupt included - the
            # application may be catching it around this call.
            self._running = False
            with contextlib.suppress(BaseException):
                self.destroy()
            raise
        finally:
            self._running = False
            if release is not None:
                release()
            if release_hangup is not None:
                release_hangup()

    def _catch_interrupts(self) -> Callable[[], None] | None:
        """Take Ctrl-C as a request the loop answers between callbacks.

        Python turns SIGINT into a KeyboardInterrupt raised wherever the
        program happens to be, and here Ctrl-C is not an interrupt but the
        copy-or-close gesture. Raised inside a callback, it tore that callback
        in half: measured, a poll that rescheduled itself with ``after`` died
        on the Ctrl-C and never ran again, though the program carried on.
        So while the loop runs the signal only marks the request, and the
        loop answers it at the end of the pass, as it would a key - within
        the input wait's twentieth of a second when it is idle, since a
        signal ends ``select`` early and it is retried for what is left.

        A second Ctrl-C while the first is still waiting means the loop is
        not coming back - a callback is stuck - and is raised as
        KeyboardInterrupt, as before, so a wedged program can still be
        stopped. Nothing is changed outside the main thread, or when the
        program has a SIGINT handler of its own.

        Returns:
            What puts the signal back, or None if it was left alone.
        """
        if threading.current_thread() is not threading.main_thread():
            return None
        if signal.getsignal(signal.SIGINT) is not signal.default_int_handler:
            return None
        self._interrupt_pending = False
        signal.signal(signal.SIGINT, self._on_interrupt)

        def release() -> None:
            signal.signal(signal.SIGINT, signal.default_int_handler)
            self._interrupt_pending = False

        return release

    def _catch_hangup(self) -> Callable[[], None] | None:
        """Take SIGHUP as a request the loop answers between callbacks.

        The terminal closing - its window shut, the SSH connection lost -
        sends SIGHUP, whose default kills the process where it stands: no
        ``finally``, no ``atexit``, nothing a program wrote to save its work.
        While the loop runs the signal only marks the hangup, and the loop
        answers it at the end of the pass with SystemExit, so all of those
        run. Nothing is changed outside the main thread, where there is no
        such signal, or when the program has a SIGHUP handler of its own or
        ignores it; a hangup it lets through is still noticed, by the
        terminal, in :meth:`_read_input`.

        Returns:
            What puts the signal back, or None if it was left alone.
        """
        hangup = getattr(signal, "SIGHUP", None)
        if hangup is None or threading.current_thread() is not threading.main_thread():
            return None
        if signal.getsignal(hangup) is not signal.SIG_DFL:
            return None
        self._hangup = False
        signal.signal(hangup, self._on_hangup)

        def release() -> None:
            signal.signal(hangup, signal.SIG_DFL)

        return release

    def _on_hangup(self, signum: int, frame: Any) -> None:
        """SIGHUP while the loop runs: note it for the end of the pass."""
        del signum, frame
        self._hangup = True

    def _answer_hangup(self) -> None:
        """End the program for a hangup noted since the last pass.

        SystemExit, with the status a shell reports for a process SIGHUP
        killed, 128 + 1: nothing is left to show a traceback on, and a
        caller looking at the status sees the same reason as before.
        """
        if self._hangup:
            self._hangup = False
            raise SystemExit(_HANGUP_EXIT_STATUS)

    def _on_interrupt(self, signum: int, frame: Any) -> None:
        """SIGINT while the loop runs: note it, or raise if one is waiting."""
        del signum, frame
        if self._interrupt_pending:
            self._interrupt_pending = False
            raise KeyboardInterrupt
        self._interrupt_pending = True

    def _answer_interrupt(self) -> None:
        """Copy, cancel or close for a Ctrl-C noted since the last pass.

        Copy when the focused widget has a selection, as everywhere. Then,
        while a modal window holds the grab - a dialog, inside mainloop or
        before it - or a wait before mainloop runs, cancel it; otherwise
        close the application.
        """
        if not self._interrupt_pending:
            return
        self._interrupt_pending = False
        if self._copy_on_interrupt():
            return
        modal = self.tk.grab
        if self._interrupt_cancels or modal is not None:
            self._cancel_on_interrupt(modal)
            return
        self._close_requested()

    def _cancel_on_interrupt(self, modal: Misc | None) -> None:
        """Ctrl-C in a modal window: cancel it, as Escape would.

        Inside mainloop this used to be the close gesture, so a Ctrl-C in
        a "Save changes?" question destroyed the application and the dialog
        answered as if refused (TkCurses-28wi). The author's decision,
        2026-11-08: Ctrl-C closes the innermost thing - the dialog, as
        Escape does, and as it does before mainloop (TkCurses-ubwt) - and
        a second one reaches the main window.

        The Escape key is delivered as if typed, so a dialog cancels exactly
        as its own binding says. A modal window with no Escape binding is
        then closed through its ``WM_DELETE_WINDOW`` protocol, destroyed if
        it has none, so Ctrl-C never does nothing; a grab on the main window
        itself is the ordinary close.
        """
        self._guard(self._route, KeyEvent(keycode=27, keysym="Escape"))
        if modal is None or self.tk.grab is not modal or not modal.winfo_exists():
            return
        top = modal.winfo_toplevel()
        if top is self:
            self._close_requested()
            return

        def close() -> None:
            if not top._invoke_protocol("WM_DELETE_WINDOW"):  # type: ignore[attr-defined]
                top.destroy()

        self._guard(close)

    def _close_requested(self) -> None:
        """The user asked to close the application. Ctrl-C means this.

        Routed through ``WM_DELETE_WINDOW`` so that an application says what
        should happen using tkinter's own API, rather than one invented
        here. With no handler registered the default is to close, which is
        what a terminal user pressing Ctrl-C expects.

        A handler that returns without quitting leaves the application
        running, exactly as declining to close a window does elsewhere.
        """
        if not self._invoke_protocol("WM_DELETE_WINDOW"):
            self.destroy()

    def _loop_once(self) -> None:
        """One pass: queued work, idle work, timers, input, then output.

        The order is not arbitrary. Work queued from another thread runs
        first because it may schedule timers; idle work runs before timers
        because that is what "idle" means; input is read last, with a timeout
        derived from the next timer, so the loop sleeps exactly as long as it
        can afford to. Layout comes after all of them and before drawing,
        since any of them may have changed what there is to draw.
        """
        # Fetched rather than stored: shutdown resets the dispatcher, and a
        # held reference would outlive the one the rest of the process uses.
        CursesDispatcher.get().process_queue(limit=_DISPATCH_BATCH)
        self._guard(self.tk.timers.run_idle)
        # Mapping is idle work in Tk, and done before any input is read: a
        # key read first would be cut off from a chord it starts by the
        # root's <Configure>, an event in another window.
        self._guard(self._announce_mapped)
        self._guard(self.tk.timers.run_due)
        self._guard(self.tk.selections.push_primary, time.monotonic())
        self._read_input()
        # Layout settles before anything is drawn, so a widget is never
        # painted at a size it is about to stop having.
        self._guard(self.tk.layout.run)
        self._update_display()
        # Last, between passes, where a callback cannot be cut in half.
        self._answer_interrupt()
        self._answer_suspend()
        self._answer_hangup()

    def _catch_suspend(self) -> Callable[[], None] | None:
        """Take the suspend key, Control-Z, as something the loop does
        between passes.

        curses' own handler suspends from inside the signal, wherever the
        program is, and knows only what curses set: the mouse motion and
        paste modes stayed on in the shell, and came back without motion -
        its return asks for clicks alone, so dragging stopped working after
        ``fg``. Left alone when the program has a handler of its own, and
        outside the main thread, where none can be set.

        Returns:
            What puts the signal back, or None if it was left alone.
        """
        if threading.current_thread() is not threading.main_thread():
            return None
        if not hasattr(signal, "SIGTSTP"):
            return None
        # None is a handler set outside Python: curses' own.
        if signal.getsignal(signal.SIGTSTP) not in (None, signal.SIG_DFL):
            return None
        self._suspend_pending = False

        def noted(signum: int, frame: Any) -> None:
            del signum, frame
            self._suspend_pending = True

        signal.signal(signal.SIGTSTP, noted)

        def release() -> None:
            signal.signal(signal.SIGTSTP, signal.SIG_DFL)
            self._suspend_pending = False

        return release

    def _answer_suspend(self) -> None:
        """Suspend, for a Control-Z noted since the last pass, and come back
        when the shell continues the program.

        The terminal is handed back as it was found - curses ended, the
        modes off, the tty's keys its own - and the process stops itself
        with the signal's default action. ``fg`` returns here, and the
        screen is taken again and painted from scratch, at whatever size
        the terminal is by then.
        """
        if not self._suspend_pending:
            return
        self._suspend_pending = False
        if self._input is None or not self._started:
            return
        handler = signal.getsignal(signal.SIGTSTP)
        self._input.pause()
        with contextlib.suppress(Exception):
            CursesDispatcher.get().call(_curses.endwin)
        signal.signal(signal.SIGTSTP, signal.SIG_DFL)
        try:
            os.kill(os.getpid(), signal.SIGTSTP)
        finally:
            signal.signal(signal.SIGTSTP, handler)
            with contextlib.suppress(Exception):
                self._handle_resize()
            self._input.resume()

    def _announce_mapped(self) -> None:
        """Tell the root's bindings it is on screen, once: ``<Configure>``
        with its size, then ``<Map>``.

        Tk delivers both when the root is first mapped, after the loop has
        started, so a program that binds ``<Configure>`` on the root learns
        its size at start-up. Measured on Tk 9.0.2: bindings made before
        ``mainloop()`` saw ``<Configure>`` at the window's size and then
        ``<Map>``, after an ``after(5)`` callback had already run. Here the
        root takes its size from the terminal when it is made, before any
        binding can exist, so nothing ever reported it until a resize.

        Not while the root is withdrawn or iconified - a program that only
        shows dialogs never maps it. Showing it maps it, which sends
        ``<Map>``, and :meth:`_map` sends the first ``<Configure>`` ahead of
        it.
        """
        if self._announced or not self._started or self._destroyed:
            return
        if self._wm_state != "normal" or not self._mapped:
            return
        self._announce_size()
        self.event_generate("<Map>")

    def _announce_size(self) -> None:
        """The root's first ``<Configure>``; see :meth:`_announce_mapped`."""
        self._announced = True
        rect = self._rect
        self.event_generate(
            "<Configure>", width=rect.width, height=rect.height, x=rect.x, y=rect.y
        )

    def _map(self) -> None:
        if not self._mapped and self._started and not self._announced:
            self._announce_size()
        super()._map()

    def _renew_colour_pairs(self) -> None:
        """Rebuild an exhausted colour-pair table, and put the screen back.

        A pair is the scarcest thing the terminal has - 255 of them, because
        that is all an attribute can name - and they were never given back
        once handed out. Measured on xterm-256color: one demo photograph took
        238 of them and the *second* one exhausted the table, after which
        every later picture was drawn in whatever palette the first had left
        behind. An image viewer is exactly the program that does this.

        Renewing is done here, at the frame boundary, rather than wherever
        the table happens to run dry. Recycling a pair number changes what
        every cell already painted with it *shows*, so it may only happen
        when the whole screen can be put back in the same breath - half way
        through a paint would leave the first half of the frame recoloured.

        Both layers have to be dealt with, and they need different things:

        - The screen buffer holds a cell's colours as **names**, so it only
          needs marking dirty; the repaint re-asks for every one.
        - A widget resolved its attribute once and baked the pair number into
          its curses window, which nothing re-reads. It has to draw again.

        What makes this safe rather than merely hopeful is that the rebuilt
        table is populated by the repaint itself, so it ends up holding
        exactly the colours still on screen. A picture that has gone is
        simply never asked for again.
        """
        colors = self.tk.colors
        if colors is None or not colors.renew_if_exhausted():
            return
        self._screen.buffer.touch_all()
        for child in list(self.children.values()):
            for widget in child._subtree():
                if isinstance(widget, BaseWidget):
                    widget._redraw()
        if self.tk.panels is not None:
            self.tk.panels.touch_all()

    def _read_input(self) -> None:
        """Wait for input up to the next timer's deadline, then route it."""
        if self._input is None:
            return
        if not self._motion_asserted:
            # Once more, now that the screen has been painted and whatever
            # ncurses wanted to say to the terminal has been said. A mouse
            # mode lost during startup is the difference between drags
            # working and a terminal that never reports one, and the cost of
            # being sure is a single write.
            self._motion_asserted = True
            self._input.enable_motion()
        delay = self.tk.timers.next_delay()
        timeout = (
            _IDLE_TIMEOUT_MS
            if delay is None
            else min(int(delay * 1000), _IDLE_TIMEOUT_MS)
        )
        readable = False
        if not self._input.more_pending:
            # Not after a pass that stopped at its limit: what is left may be
            # inside curses already, where select() cannot see it.
            readable = self._input.wait_for_input(max(timeout, 0))
        events = self._input.poll(_INPUT_BATCH)
        if readable and not events and self._input.terminal_gone():
            # Readable with nothing to read is how a hung-up terminal looks
            # when SIGHUP did not end the program - ignored, as under nohup,
            # or handled by a handler that carried on. Left alone the loop
            # spun on it at full CPU for ever.
            self._hangup = True
        for event in self._collapse_motion(events):
            self._guard(self._route, event)

    def _paste(self, text: str) -> None:
        """Hand a paste the terminal marked to the focus, as
        ``<<TerminalPaste>>`` with the text in ``event.data``.

        A widget that binds nothing to it - a button, a list, a program's own
        canvas - gets the text as the keys typing it would send, less every
        control character: a pasted line break is not Return to a dialog's
        default button, nor Escape the key that closes it.
        """
        target = self._through_grab(self.tk.focus or self)
        if target._binds(_TERMINAL_PASTE):
            event = Event(widget=target, data=text)
            event.type = EventType.VirtualEvent
            target._dispatch(event, [_TERMINAL_PASTE])
            return
        if self._input is not None:
            for key in self._input.keys_for(_without_controls(text)):
                self._route(key)

    def _collapse_motion(self, events: list[CoreEvent]) -> list[CoreEvent]:
        """``events`` with each run of motion in one window cut to its last.

        As Tk collapses them: ``Tk_QueueWindowEvent`` (``tkEvent.c``) keeps
        a motion event back and replaces it with the next one in the same
        window, and anything else sends it on first. The window is the
        widget under the pointer, or under a drag the one pressed, which
        holds the pointer until the release. A change of modifier keys ends
        a run too, as X's key event between them would.
        """
        collapsed: list[CoreEvent] = []
        window: Misc | None = None
        for event in events:
            if isinstance(event, MouseEvent) and event.state in ("motion", "drag"):
                # A drag runs from a press to a release, neither of which is
                # motion, so a run of drags is all in the one window pressed.
                here = (
                    None if event.state == "drag" else self._widget_at(event.x, event.y)
                )
                last = collapsed[-1] if collapsed else None
                if (
                    isinstance(last, MouseEvent)
                    and last.state == event.state
                    and last.button == event.button
                    and last.modifiers == event.modifiers
                    and here is window
                ):
                    collapsed[-1] = event
                    continue
                window = here
            collapsed.append(event)
        return collapsed

    def _route(self, event: CoreEvent) -> None:
        """Deliver one event to the widget it belongs to.

        Keyboard goes to the focus, mouse to whatever is under the pointer,
        and a resize to the root, which owns the screen. A grab overrides all
        three: that is what makes a modal dialog modal.
        """
        if isinstance(event, ResizeEvent):
            self._handle_resize()
            return
        if isinstance(event, PasteEvent):
            self._paste(event.text)
            return
        if isinstance(event, MouseEvent):
            if event.state in _PRESSES and self.tk.repeat is not None:
                self._release_lost()
            held = self._mouse_owner
            target = self._mouse_target(event)
            if (
                held is None
                and target._busy_covers()
                and self._through_grab(target) is target
            ):
                # Taken by the busy window, as Tk's takes it. A press made
                # before the hold still gets its release, through the
                # implicit grab, so nothing is left held down.
                self._mouse_owner = None
                self._cross_to(None, event)
                return
            if event.is_scroll:
                self._through_grab(target)._handle(event)
                return
            self._cross_before(event, held)
            self._through_grab(target)._handle(event)
            self._cross_after(event)
            return
        target = self._through_grab(self.tk.focus or self)
        target._handle(event)

    # Crossings. The terminal does not report the pointer between presses -
    # hover reporting (DEC 1003) is off by default, because it floods the
    # application and takes the terminal's own selection away - so the
    # pointer is known only from a press to its release, and <Enter> and
    # <Leave> are made from those reports as X11 makes them under the
    # implicit grab: the widget pressed hears the pointer leave and come
    # back, and nothing else hears anything until the release. A release
    # ends the visit, since nothing will say when the pointer goes, so a
    # button is not left drawn active under a pointer long gone.

    def _cross_before(self, event: MouseEvent, held: Misc | None) -> None:
        """The crossings due before ``event`` is delivered."""
        if event.state in _PRESSES:
            self._cross_to(self._crossable(self._widget_at(event.x, event.y)), event)
        elif held is not None and held.winfo_exists():
            # Under the implicit grab only the widget pressed is entered or
            # left - and not even that one if a modal grab took its press.
            inside = _point_within(held, event.x, event.y)
            self._cross_to(self._crossable(held) if inside else None, event)
        elif event.state == "motion":
            self._cross_to(self._crossable(self._widget_at(event.x, event.y)), event)

    def _cross_after(self, event: MouseEvent) -> None:
        """The crossings due after ``event``: a release ends the grab."""
        if event.state not in ("released", "clicked"):
            return
        if self._hover_reported:
            # X11's ungrab: the widget now under the pointer is entered.
            self._cross_to(self._crossable(self._widget_at(event.x, event.y)), event)
        else:
            self._cross_to(None, event)

    def _crossable(self, widget: Misc) -> Misc | None:
        """``widget``, or None if a grab elsewhere keeps the pointer from it."""
        grab = self.tk.grab
        if grab is None or not grab.winfo_exists():
            return widget
        if any(each is grab for each in widget._ancestry()):
            return widget
        return None

    def _cross_to(self, widget: Misc | None, event: MouseEvent) -> None:
        """Move the pointer to ``widget``: ``<Leave>`` the old, ``<Enter>``
        the new, in that order, as Tk delivers them."""
        old = self._pointer_widget
        if old is widget:
            return
        self._pointer_widget = widget
        for each, sequence in ((old, "<Leave>"), (widget, "<Enter>")):
            if each is not None and each.winfo_exists():
                each.event_generate(
                    sequence,
                    x=event.x - each.winfo_rootx(),
                    y=event.y - each.winfo_rooty(),
                    x_root=event.x,
                    y_root=event.y,
                )

    def _release_lost(self) -> None:
        """Stop an auto-repeat whose release never arrived.

        A press is held for as long as no release is reported, and ncurses
        drops reports it is not drained fast enough for (see
        ``_arm_press_recovery``), so a repeating Button or Scale could repeat
        for ever. A second press cannot happen with the first button still
        down: it is the proof that the release was lost. The held widget is
        put back up, as its release would have done.
        """
        _cancel_repeat(self)
        owner: Any = self._mouse_owner
        if owner is not None and getattr(owner, "_pressed", False):
            owner._pressed = False
            owner._redraw()

    def _mouse_target(self, event: MouseEvent) -> Misc:
        """The widget a mouse event belongs to, honouring the implicit grab.

        Everything between a press and its release goes to the widget that
        was pressed, wherever the pointer has since wandered. X11 gives a
        widget this grab automatically and Tk relies on it; routing each
        event by position instead means a pointer that drifts a single cell
        between press and release delivers the release somewhere else. The
        pressed widget then never hears that the button came up and stays
        held down, so the *next* click appears to be the one that works -
        intermittently, depending on whether the hand moved.
        """
        # A double or triple click is a press too, and takes the grab like
        # one: without it, the drag after a double-click - which extends the
        # selection a word at a time - went to whatever was under the pointer
        # instead of to the widget pressed. TkCurses-svtr.
        if event.state in _PRESSES:
            self._mouse_owner = self._widget_at(event.x, event.y)
            return self._mouse_owner
        owner = self._mouse_owner
        if owner is not None and owner.winfo_exists():
            if event.state == "released":
                self._mouse_owner = None
            return owner
        self._mouse_owner = None
        return self._widget_at(event.x, event.y)

    def _widget_at(self, x: int, y: int) -> Misc:
        """The widget under a screen cell, falling back to the root.

        The panel stack answers this when there is one, because it knows the
        z-order; before there is, the widget tree's own geometry does.
        """
        stack = self.tk.panels
        if stack is not None:
            panel = stack.panel_at(x, y)
            if panel is not None:
                widget = panel.userptr()
                if isinstance(widget, Misc) and widget.winfo_exists():
                    return widget
        return self.winfo_containing(x, y) or self

    def _through_grab(self, target: Misc) -> Misc:
        """Redirect an event to the grab holder unless it is already inside it."""
        grab = self.tk.grab
        if grab is None or not grab.winfo_exists():
            return target
        if any(widget is grab for widget in target._ancestry()):
            return target
        return grab

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, painting the screen if the background changed."""
        given = {self._option_synonyms.get(key, key) for key in _given(cnf, kw)}
        result = super().configure(cnf, **kw)
        if "backgroundimage" in given:
            self._follow_backdrop()
        if given & {"background", "backgroundimage", "tile"}:
            self._paint_background()
        if given & _INSET_OPTIONS:
            self._invalidate_layout()
        return result

    config = configure

    def _paint_background(self) -> None:
        """Fill the screen behind every widget with the root's ``background``.

        The root has no curses window - giving it one would put an opaque
        panel over everything - so its background is the screen buffer the
        panels are drawn over. Tk paints a toplevel's background behind its
        children, and a root configured with one showed none until
        TkCurses-0awl. A root with no background leaves the buffer alone, so
        what a curses program or a test wrote there survives.
        """
        screen = self.tk.screen
        if screen is None or not self._started:
            return
        background = str(self._options["background"] or "")
        buffer = screen.buffer
        # The root draws no border, so its image starts at the corner. The
        # screen buffer takes colours, not attributes, and has no direct
        # painter in front of it to bypass.
        cells = self._backdrop(buffer.width, buffer.height, 0)
        if not background and not cells and not self._background_painted:
            return
        buffer.fill(buffer.bounds, bg=background or "black")
        for (column, row), (glyph, fore, back) in cells.items():
            buffer.write(row, column, glyph, fg=fore, bg=back or background or "black")
        self._background_painted = bool(background or cells)

    def _repaint_backdrop(self) -> None:
        """Paint the screen again: the root's background is the screen's."""
        self._paint_background()
        if self.tk.panels is not None:
            self.tk.panels.touch_all()

    def _handle_resize(self) -> None:
        """Take the terminal's new size and tell the tree about it.

        The event carries a size, but it is not the one used: curses reports
        the old dimensions until resize_term() has been given what the
        terminal actually is, which is what handle_resize() does.
        """
        size = self._screen.handle_resize()
        # The cells the terminal grew by are new, and new cells are black.
        self._paint_background()
        # The screen is cleared and written again from scratch, so the panels
        # over it have to be written again too - otherwise every widget that
        # happens to keep its geometry through the resize simply vanishes.
        if self.tk.panels is not None:
            self.tk.panels.touch_all()
        self._rect = Rect(0, 0, size.width, size.height)
        # The root's rect is set directly rather than through _allocate, which
        # would give the root a panel it does not want - so its layout has to
        # be told separately. Without this, everything sized against the
        # terminal keeps the size the terminal used to be.
        self.tk.layout.invalidate(self)
        # Laid out here rather than left to the next idle pass, because the
        # windows are put right immediately below and that has to happen
        # against the geometry the new size gives, not the old one.
        self.update_layout()
        # A window is clipped to the screen rather than allowed off the edge,
        # so a widget that was on screen at the old size may be clipped, gone
        # or restorable at the new one. The layout only re-allocates what it
        # manages, and a toplevel is not that: without this a toplevel keeps
        # whatever window the smallest terminal it ever saw left it with.
        # The children's subtrees, not the root's: the root deliberately has
        # no window of its own, and giving it one puts an opaque full-screen
        # panel over everything drawn on the screen behind the widgets.
        # Windows first, and by moving rather than clipping. A Toplevel is
        # both a Wm, which may not overflow the terminal, and a Misc, which
        # may and gets clipped - and it is the Misc rule that _sync_window
        # applies. Re-establishing the stronger one here is what stops a
        # window, and with it a grab, from ending up where nothing can reach.
        for child in list(self.children.values()):
            if isinstance(child, Wm):
                child._reposition_for_screen()
        for child in list(self.children.values()):
            for widget in child._subtree():
                if isinstance(widget, BaseWidget):
                    widget._sync_window()
        self.event_generate("<Configure>", width=size.width, height=size.height)

    def _update_display(self) -> None:
        """Push what changed to the terminal.

        The screen goes first and the panels over it, which is the order they
        are stacked in. Widgets do not draw anything yet; when they do, their
        rendering happens before this.
        """
        if not self._started:
            return
        self._repaint_due()
        self._renew_colour_pairs()
        painted = bool(self._screen.refresh())
        if self.tk.panels is not None:
            # The widgets draw on panels, not on the screen buffer, so what
            # the screen painted says nothing about them: the stack is asked
            # too. Counting the screen alone, a frame that redrew a picture's
            # widget never painted the picture again, and curses' nearest
            # colours stayed where it had drawn - TkCurses-gdvq.
            painted = self.tk.panels.update() or painted
        # After doupdate, never before: curses has finished writing and
        # cannot paint over the picture within this frame. Every frame it
        # has cells, because curses repaints them whenever anything near
        # them changes and does not say so.
        painter = getattr(self.tk, "painter", None)
        if painter is not None and painter.pending:
            CursesDispatcher.get().call(painter.paint, painted)

    def _repaint_due(self) -> None:
        """Repaint the widgets that asked to be repainted before the screen
        is next shown, each once."""
        due = self.tk.repaint_due
        while due:
            widget = next(iter(due))
            del due[widget]
            if widget.winfo_exists():
                self._guard(widget._redraw)

    def update(self) -> None:
        """Process everything pending without entering the loop.

        Unlike :meth:`Misc.update`, this does read input, because the root is
        the one object entitled to. It is still the reentrancy hazard it is
        in tkinter: a callback that calls ``update()`` can be re-entered by
        the event that arrives during it.
        """
        self._loop_once()

    # ------------------------------------------------------------ teardown

    def quit(self) -> None:
        """Stop the loop without destroying anything.

        The loop notices on its next pass, so the callback calling this runs
        to completion first. The widgets survive, which is what allows
        ``mainloop()`` to be entered again.
        """
        self._running = False
        self.tk.quit_requested = True

    def destroy(self) -> None:
        """Destroy every widget and give the terminal back.

        Ordering matters on the way out as much as on the way in: the widget
        tree goes first, so panels are released while the stack still exists,
        and curses is shut down last.
        """
        global _default_root, _active_root
        if self._destroyed:
            return
        self._running = False
        try:
            super().destroy()
        finally:
            self._shutdown()
        if _default_root is self:
            _default_root = None
        if _active_root is self:
            _active_root = None

    def _shutdown(self) -> None:
        """Release curses and everything hanging off it, once.

        Every step is independent and none may prevent the next: this runs
        while something has already gone wrong, and the terminal has to come
        back regardless.
        """
        if not self._started:
            return
        self._started = False
        if self._release_suspend is not None:
            self._release_suspend()
            self._release_suspend = None
        self.tk.layout.clear()
        with contextlib.suppress(Exception):
            if self.tk.panels is not None:
                self.tk.panels.clear()
        self.tk.panels = None
        self.tk.screen = None
        self.tk.colors = None
        if self._input is not None:
            self._input.restore()
        self._input = None
        self.tk.input = None
        with contextlib.suppress(Exception):
            self._screen.stop()
            self._flush_held_reports()
            self._report_clipboard_kept_inside()
        route = self.tk.selections.route
        if route is not None and route.primary is not None:
            with contextlib.suppress(Exception):
                route.primary.close()
        CursesDispatcher.reset()

    def __enter__(self) -> Tk:
        """Support ``with Tk() as root:``.

        Not tkinter API. It is here because the alternative to guaranteed
        teardown in a curses program is a wrecked terminal, and a context
        manager is the one construct that guarantees it.
        """
        return self

    def __exit__(self, *exc_info: object) -> None:
        """Destroy the root, restoring the terminal."""
        self.destroy()

    # ----------------------------------------------------------- callbacks

    def _guard(self, func: Callable[..., Any], *args: Any) -> None:
        """Run ``func``, reporting rather than propagating what it raises.

        One misbehaving binding should not take the application down, which
        is tkinter's rule too. KeyboardInterrupt and SystemExit are not
        caught: those are the user asking to leave.
        """
        try:
            func(*args)
        except (KeyboardInterrupt, SystemExit):
            raise
        except BaseException:
            self.report_callback_exception(*sys.exc_info())

    def report_callback_exception(self, exc: Any, val: Any, tb: Any) -> None:
        """Report an exception that escaped a callback.

        Held back while the screen is up and stderr is the same terminal,
        and printed once the screen has been given back. A traceback written
        to a terminal curses is drawing on lands on top of the display, and
        the buffer repaints only what it knows has changed - so the damage
        stays until something else happens to write over it.

        Written immediately when stderr is a redirect or a pipe, because
        then it cannot damage anything and a developer watching a log wants
        it now.

        The screen is repainted either way. An override that draws its own
        report into the buffer survives that, since a repaint paints from
        the buffer; only writes that went straight to the terminal are
        undone, which is exactly the damage worth undoing.
        """
        text = "".join(traceback.format_exception(exc, val, tb))
        screen = self.tk.screen
        if screen is not None and screen.started and _stderr_is_a_terminal():
            self._held_reports.append(text)
        else:
            _write_to_stderr(text)
        with contextlib.suppress(_curses.error):
            self.tk.repaint()

    def _report_clipboard_kept_inside(self) -> None:
        """Say once, on the way out, that a copy never left this program.

        The acceptance the issue asked for: a terminal that cannot carry the
        clipboard is detected and said, not silently trusted. Said after the
        screen is given back, so it is read rather than painted over.
        TkCurses-hpr.
        """
        selections = self.tk.selections
        route = selections.route
        if not selections.kept_inside or route is None:
            return
        selections.kept_inside = False
        _write_to_stderr(
            "tkcurses: what was copied stayed inside this program - "
            f"{route.reason}. Set clipboard.system to change how it is tried.\n"
        )

    def _flush_held_reports(self) -> None:
        """Print anything held back, now that the screen has been given up."""
        held, self._held_reports = self._held_reports, []
        for text in held:
            _write_to_stderr(text)


def _not_utf8_report(environ: Mapping[str, str]) -> str:
    """What to say when the locale cannot carry Unicode, naming the setting
    that chose it.

    The C library reads ``LC_ALL``, then ``LC_CTYPE``, then ``LANG``, so the
    first of them that is set is the one to change: setting ``LANG`` does
    nothing while ``LC_ALL=C`` stands over it.
    """
    for name in ("LC_ALL", "LC_CTYPE", "LANG"):
        if environ.get(name):
            chosen, to_set = f"{name}={environ[name]}", name
            break
    else:
        chosen, to_set = "no LANG set", "LANG"
    return (
        f"tkcurses: the locale is not UTF-8 ({chosen}), so letters outside "
        "ASCII and the lines of boxes were drawn wrong. "
        f"Set {to_set}=C.UTF-8, or another UTF-8 locale.\n"
    )


def _stderr_is_a_terminal() -> bool:
    """True when writing to stderr would land on a terminal.

    Which is the question that decides whether a report can be printed now:
    a redirect or a pipe cannot be damaged, a terminal curses is drawing on
    can.
    """
    stream = sys.stderr
    try:
        return bool(stream is not None and stream.isatty())
    except (OSError, ValueError):
        return False


def _a_profile_to_trust(path: Path) -> bool:
    """Whether ``path`` is a regular file the user owns and no one else may
    write to. Followed if it is a link, as tkinter's ``isfile`` follows it:
    what is checked is the file that would be run."""
    try:
        info = path.stat()
    except OSError:
        return False
    return (
        stat.S_ISREG(info.st_mode)
        and info.st_uid == os.getuid()
        and not info.st_mode & (stat.S_IWGRP | stat.S_IWOTH)
    )


def _write_to_stderr(text: str) -> None:
    """Write a report out.

    No line-ending translation, and none needed. curses clears ONLCR, so a
    traceback printed while the screen is up comes out as a staircase with
    each line starting where the last one ended - which is why one is never
    printed then: it either goes to a stream curses has no say over, or it
    waits until curses has given the terminal back.
    """
    with contextlib.suppress(OSError, ValueError):
        # A report can quote the environment - a locale name, a path under
        # XDG_CONFIG_HOME - and a value there is not ours to trust: an
        # escape sequence in it would otherwise drive the terminal.
        sys.stderr.write(printable(text))
        sys.stderr.flush()


class Toplevel(_Backdrop, BaseWidget, Wm):
    """A window of its own, drawn over the main window.

    A terminal has no window manager to give a window its frame, title bar
    and place, so a toplevel draws its own border, with its title in it, and
    chooses its own position. It appears the moment it is made; it is not
    packed or gridded. :meth:`~Wm.wm_geometry` moves and sizes it, in cells.

    Sample output:
        # size: 50x10
        tk.Label(root, text="The main window").pack(anchor="w")
        top = tk.Toplevel(root)
        top.title("Settings")
        top.geometry("24x6+10+3")
        tk.Label(top, text="A second window").pack()
        tk.Button(top, text="Close", command=top.destroy).pack()

    It takes ``backgroundimage`` and ``tile`` as :class:`Frame` describes
    them, and draws the image inside its border.

    Differences from tkinter:
        A toplevel is always inside the terminal, and its title is drawn on
        its top border.
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"foreground"})

    _is_toplevel = True

    @property
    def _bordered(self) -> bool:
        """A toplevel's frame is its window manager's, not a Tk border.

        So Tk's rule for a border does not apply: any ``borderwidth`` draws
        the frame, flat or not, and ``borderwidth=0`` with a flat relief - or
        overrideredirect - leaves it off.
        """
        if getattr(self, "_overrideredirect", False):
            return False
        return bool(self._options.get("borderwidth")) or (
            self._options.get("relief", FLAT) != FLAT
        )

    #: ``width`` and ``height`` are cells, and zero means "not asked for",
    #: which is what sends the window to its default size. borderwidth is 1
    #: rather than tkinter's 0: there is no window manager to draw a frame,
    #: so without one a toplevel is indistinguishable from what is behind it.
    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "height": _signed_distance,
        "width": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        **_WINDOW_SYSTEM_OPTIONS,
        "backgroundimage": "",
        "borderwidth": 1,
        "height": 0,
        "menu": None,
        "screen": "",
        "tile": 0,
        "use": "",
        "width": 0,
    }

    _creation_only = frozenset({*_WINDOW_SYSTEM_OPTIONS, "screen", "use"})

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        class_: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: The window this one belongs to. Defaults to the root.
            cnf: Options as a dictionary.
            name: Path component, generated when omitted.
            class_: The class this window binds and reads options under, as
                tkinter's ``class_`` does. Construction-time only, because
                bindings and option lookups are resolved against it.
            **kw: Options as keywords.
        """
        class_, cnf, kw = _class_from(class_, cnf, kw)
        self._class_name = class_
        self._drag_origin: tuple[int, int, int, int] | None = None
        super().__init__(master, cnf, name=name, **kw)
        self._options["class"] = self.winfo_class()
        self._follow_backdrop()
        self._setup_wm()
        self._allocate(self._default_rect())
        self._map()
        self._install_class_bindings()

    def winfo_class(self) -> str:
        """The class this window binds and reads options under."""
        return self._class_name or type(self).__name__

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register title-row dragging for every window of this class.

        Under ``winfo_class()`` rather than the literal ``"Toplevel"``, which
        matters because a subclass reports its own name here - so
        :class:`tkcurses.simpledialog.Dialog` binds under ``Dialog`` and gets
        the behaviour, where a hard-coded tag would have left every dialog
        in the library the one kind of window that cannot be moved.

        Class bindings rather than instance ones, so an application that
        binds the title row itself runs first and can stop this with
        ``"break"``.
        """
        tag = self.winfo_class()
        if tag in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(tag)
        self.bind_class(tag, "<Button-1>", _toplevel_press)
        self.bind_class(tag, "<B1-Motion>", _toplevel_drag)
        self.bind_class(tag, "<ButtonRelease-1>", _toplevel_release)

    def _default_rect(self) -> Rect:
        """Where the window goes when nothing has said.

        Centred, and clamped to the screen. Tk would hand this to the window
        manager, which typically cascades or centres; centring is the choice
        that keeps a dialog visible on a terminal of any size, and Wm's
        geometry() will override it.
        """
        screen_width, screen_height = self._screen_size()
        width = int(self._options["width"]) or min(
            _DEFAULT_TOPLEVEL_SIZE.width, screen_width
        )
        height = int(self._options["height"]) or min(
            _DEFAULT_TOPLEVEL_SIZE.height, screen_height
        )
        width = clamp(width, 1, screen_width)
        height = clamp(height, 1, screen_height)
        return Rect(
            clamp((screen_width - width) // 2, 0, max(0, screen_width - width)),
            clamp((screen_height - height) // 2, 0, max(0, screen_height - height)),
            width,
            height,
        )

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, resizing the window if its size options changed."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if "backgroundimage" in {self._option_synonyms.get(key, key) for key in given}:
            self._follow_backdrop()
        if given and {"width", "height"} & set(given):
            self._allocate(self._default_rect())
        elif given:
            self._draw()
        if {self._option_synonyms.get(key, key) for key in given} & _INSET_OPTIONS:
            self._invalidate_layout()
        return result

    config = configure

    def _redraw(self) -> None:
        """Repaint the border and title whenever the window changes."""
        self._draw()

    def _draw(self) -> None:
        """Paint the border into this window's curses window.

        The only rendering in the library so far: a toplevel without a border
        is indistinguishable from whatever it covers, and there is no window
        manager to draw one. Widget rendering proper arrives with the widget
        set, and will draw the interior before this is pushed to the terminal.

        Silent without a screen, which is what lets the geometry above be
        tested with no terminal in the loop.
        """
        window = self._window
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        # Its background behind its children, as Tk paints a toplevel's; the
        # window's own plain one when it has none. TkCurses-0awl.
        background = str(self._options["background"] or "")
        colors = self.tk.colors
        attribute = (
            colors.attribute_for("white", background)
            if background and colors is not None
            else _curses.A_NORMAL
        )
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._bordered:
                dispatcher.call(window.border)
                self._draw_title(dispatcher, window)
            edge = BORDER_WIDTH if self._bordered else 0
            self._paint_backdrop(dispatcher, window, edge, background or "black")

    def _draw_title(self, dispatcher: CursesDispatcher, window: Any) -> None:
        """Write the title into the top border, centred and truncated.

        The top border is the only title bar a terminal window has. A title
        longer than the border can hold is cut rather than allowed to run
        over the corners.
        """
        title = getattr(self, "_title", "")
        if not title:
            return
        room = self._rect.width - 2 * BORDER_WIDTH - 2
        text = clip_text(f" {title} ", max(0, room + 2))
        if len(text) < 3:
            return
        column = max(BORDER_WIDTH, (self._rect.width - len(text)) // 2)
        with contextlib.suppress(_curses.error):
            # A_NORMAL: the title had no attribute of its own before this
            # went through _write_line, and the border it sits in has none
            # either.
            self._write_line(dispatcher, window, 0, column, text, _curses.A_NORMAL)

    def _redraw_decoration(self) -> None:
        """Repaint the border and title after the window manager changed them."""
        self._draw()


def _toplevel_press(event: Event) -> Any:
    """Start a drag, if the press landed on the title row.

    A terminal has no window manager, so moving a decorated window is this
    library's job - the same job Mutter or KWin would be doing, and the
    reason it is a class binding rather than something an application has to
    write. An ``overrideredirect`` window is excluded on purpose: it has no
    decoration to grab, and on a desktop such a window is the application's
    to move. See ARCHITECTURE.md, "Window Management".

    The title row is row zero, and only row zero. A press anywhere else
    belongs to whatever is there.
    """
    window = event.widget
    if not isinstance(window, Toplevel) or not window._bordered or event.y != 0:
        return None
    window._drag_origin = (
        event.x_root,
        event.y_root,
        window.winfo_x(),
        window.winfo_y(),
    )
    # Clicking a window to move it and having it stay behind another would be
    # surprising, and here there is no window manager to do the raising.
    window.tkraise()
    return None


def _toplevel_drag(event: Event) -> Any:
    """Move the window by however far the pointer has travelled.

    By the distance travelled rather than to the position arrived at, so the
    column of the title that was grabbed stays under the pointer - the rule
    the scrollbar thumb and the sizegrip already follow. ``geometry`` clamps
    to the screen, so a window dragged at the edge stops rather than leaving.
    """
    window = event.widget
    if not isinstance(window, Toplevel):
        return None
    origin = window._drag_origin
    if origin is None:
        return None
    press_x, press_y, left, top = origin
    x = left + (event.x_root - press_x)
    y = top + (event.y_root - press_y)
    window.geometry(f"{window.winfo_width()}x{window.winfo_height()}+{x}+{y}")
    window.update_layout()
    return None


def _toplevel_release(event: Event) -> Any:
    """Finish the drag, leaving the window where it was let go."""
    window = event.widget
    if isinstance(window, Toplevel):
        window._drag_origin = None
    return None


# ======================================================================
# Variables
# ======================================================================


class Variable:
    """A value widgets can share and watch.

    Two widgets given the same variable stay in step, and a trace added with
    :meth:`trace_add` runs when it is written, read or unset. Variables belong
    to the application, so two applications in one process keep separate
    ones.
    """

    # tkinter's variables live in the Tcl interpreter; these live in the
    # _core.application.Application, reached through the master. _default is
    # the value a variable of this class starts with.

    _default: Any = ""

    #: Names automatic variables PY_VAR0, PY_VAR1, as tkinter does, so a
    #: printed variable name reads the same under either library.
    _counter = itertools.count()

    def __init__(
        self,
        master: Misc | None = None,
        value: Any = None,
        name: str | None = None,
    ) -> None:
        """
        Args:
            master: Any widget of the application the variable belongs to.
                Defaults to the implicit root.
            value: Initial value. Without one the variable takes its class's
                default, unless a variable of that name already holds
                something, which is how two Variables can share one name.
            name: The variable's name, generated when omitted.

        Raises:
            TclError: If no master was given and there is no root window.
        """
        if master is None:
            master = _get_default_root("create a variable")
        self._master = master
        self._tk = master.tk
        self._name = name or f"PY_VAR{next(Variable._counter)}"
        #: The handles of the traces added through this object, which go
        #: when it does, as tkinter deletes the commands it made for them.
        self._own_traces: set[str] = set()
        if value is not None:
            self.initialize(value)
        elif self._name not in self._tk.variables:
            self.initialize(self._default)

    def __str__(self) -> str:
        """The variable's name, which is how Tk refers to one."""
        return self._name

    def __repr__(self) -> str:
        """Name and current value, for a traceback or a debugger."""
        return f"<{type(self).__name__} {self._name}={self._raw()!r}>"

    def __eq__(self, other: object) -> bool:
        """Equal to another variable of the same class with the same name.

        Not by value: two variables are the same variable or they are not,
        and comparing the values would make an IntVar equal to a StringVar
        that happened to hold the same digits.
        """
        if not isinstance(other, Variable):
            return NotImplemented
        return type(other) is type(self) and other._name == self._name

    def __hash__(self) -> int:
        """Hash by name, to match :meth:`__eq__`."""
        return hash((type(self).__name__, self._name))

    def __del__(self) -> None:
        """Forget the value when the last reference goes.

        Its own traces go with it. The value is kept while anything else
        still traces the name: tkinter unsets it, and a widget bound to it
        puts it straight back - measured on Tk 9.0.2, a Label keeps its
        variable alive after every StringVar of that name is collected.

        Guarded to the point of silence: this runs during garbage collection
        and at interpreter shutdown, where the application may already be
        half torn down and an exception here would be reported out of any
        useful context.
        """
        with contextlib.suppress(Exception):
            traces = self._tk.variable_traces.get(self._name, {})
            for handle in self._own_traces:
                traces.pop(handle, None)
            if not traces:
                self._tk.variable_traces.pop(self._name, None)
                self._tk.variables.pop(self._name, None)

    # --------------------------------------------------------------- value

    def get(self) -> Any:
        """The variable's value, converted to this class's type."""
        self._fire("read")
        return self._convert(self._raw())

    def set(self, value: Any) -> None:
        """Set the value, firing any write traces."""
        self._tk.variables[self._name] = value
        self._fire("write")

    initialize = set

    def _raw(self) -> Any:
        """The stored value, unconverted, defaulting if it was never set."""
        return self._tk.variables.get(self._name, self._default)

    def _convert(self, value: Any) -> Any:
        """Coerce a stored value to this class's type. Identity by default."""
        return value

    # -------------------------------------------------------------- traces

    def trace_add(self, mode: str | Sequence[str], callback: Callable[..., Any]) -> str:
        """Call ``callback`` when the variable is read, written, or unset.

        Args:
            mode: One of ``read``, ``write``, ``unset``, or several.
            callback: Invoked as ``callback(name, index, mode)``, the
                arguments Tcl passes and tkinter hands on unchanged.

        Returns:
            A handle for :meth:`trace_remove`.

        Raises:
            TclError: If a mode is not one Tk recognises.
        """
        modes = (mode,) if isinstance(mode, str) else tuple(mode)
        for one in modes:
            if one not in _TRACE_MODES:
                raise TclError(f'bad operation "{one}"')
        handle = self._add_trace(modes, callback, listed=True)
        self._own_traces.add(handle)
        return handle

    def _add_trace(
        self, modes: tuple[str, ...], callback: Callable[..., Any], *, listed: bool
    ) -> str:
        """Put a trace on the name, where every Variable of it sees it."""
        handle = f"{self._name}_trace{next(self._tk.trace_counter)}"
        traces = self._tk.variable_traces.setdefault(self._name, {})
        traces[handle] = (modes, callback, listed)
        return handle

    def _watch(self, callback: Callable[[], Any]) -> str:
        """A widget's own write trace: fired like any other, and not listed
        by :meth:`trace_info`, as Tk's are not."""
        return self._add_trace(("write",), lambda *_: callback(), listed=False)

    def _unwatch(self, handle: str) -> None:
        """Drop a trace :meth:`_watch` added."""
        self._drop_trace(handle)

    def _drop_trace(self, handle: str) -> None:
        traces = self._tk.variable_traces.get(self._name)
        if traces is not None:
            traces.pop(handle, None)
            if not traces:
                del self._tk.variable_traces[self._name]

    def trace_remove(
        self,
        mode: str | Sequence[str],  # noqa: ARG002 - tkinter signature
        cbname: str,
    ) -> None:
        """Remove a trace by the handle :meth:`trace_add` returned.

        The mode is accepted for tkinter's signature and not consulted: the
        handle already identifies one registration. Any Variable of the
        same name can remove it, since the trace is on the name.
        """
        self._own_traces.discard(cbname)
        self._drop_trace(cbname)

    def trace_info(self) -> list[tuple[tuple[str, ...], str]]:
        """Every trace on this variable's name, as ``(modes, handle)`` pairs,
        whichever Variable of that name added it."""
        traces = self._tk.variable_traces.get(self._name, {})
        return [
            (modes, handle) for handle, (modes, _, listed) in traces.items() if listed
        ]

    def trace_variable(self, mode: str, callback: Callable[..., Any]) -> str:
        """Add a trace using the old single-letter modes.

        ``r``, ``w`` and ``u`` are what Tk called read, write and unset
        before ``trace_add``. Kept because tkinter code written before 3.6
        still uses them.

        Raises:
            TclError: If the mode letter is not one of the three.
        """
        return self.trace_add(self._legacy_modes(mode), callback)

    #: The oldest spelling of all, which tkinter still defines as this alias.
    trace = trace_variable

    def trace_vdelete(self, mode: str, cbname: str) -> None:
        """Remove a trace added with :meth:`trace_variable`."""
        self.trace_remove(self._legacy_modes(mode), cbname)

    def trace_vinfo(self) -> list[tuple[str, str]]:
        """Traces in the old format: single-letter modes and handles."""
        return [
            ("".join(_LEGACY_LETTERS[one] for one in modes), handle)
            for modes, handle in self.trace_info()
        ]

    @staticmethod
    def _legacy_modes(mode: str) -> tuple[str, ...]:
        """Translate ``rwu`` letters into the modern mode names."""
        try:
            return tuple(_LEGACY_MODES[letter] for letter in mode)
        except KeyError:
            raise TclError(f'bad operation "{mode}"') from None

    def _fire(self, mode: str) -> None:
        """Run the traces on this name registered for ``mode``."""
        _fire_traces(self._tk, self._name, mode)


def _fire_traces(tk: Any, name: str, mode: str) -> None:
    """Run the traces on variable ``name`` registered for ``mode``.

    The list is copied first, so a callback may add or remove a trace -
    including its own - without disturbing the pass it is in.
    """
    for modes, callback, _ in list(tk.variable_traces.get(name, {}).values()):
        if mode in modes:
            callback(name, "", mode)


class _NamedVariable(Variable):
    """A variable a widget was given by name.

    It reads and writes the value of that name and neither creates it -
    the widget seeds it, as Tk's do, from what it shows - nor unsets it
    when collected. It compares equal to the name, so ``cget`` reads back
    what was given, as tkinter's parsedVarName object does.
    """

    def __init__(self, master: Misc, name: str) -> None:
        self._master = master
        self._tk = master.tk
        self._name = name
        self._own_traces = set()

    def __eq__(self, other: object) -> bool:
        if isinstance(other, str):
            return other == self._name
        return super().__eq__(other)

    def __hash__(self) -> int:
        return hash(self._name)

    def __del__(self) -> None:
        with contextlib.suppress(Exception):
            for handle in list(self._own_traces):
                self._drop_trace(handle)


def _seed_variable(widget: Any, variable: Variable, value: Any) -> None:
    """Give a variable named for a widget its first value, if it has none.

    Measured on Tk 9.0.2: a classic widget bound to a variable that does not
    exist creates it from itself - a Label from its text, an Entry empty, a
    Spinbox at ``from``, a Checkbutton with its offvalue, a Scale with its
    value. A themed widget leaves it alone and reads it as empty: a
    ``ttk.Checkbutton`` starts ``alternate`` for that reason.
    """
    if _is_ttk(widget):
        return
    if str(variable) not in variable._tk.variables:
        variable._tk.variables[str(variable)] = value


#: Trace modes Tk recognises. "array" is accepted for compatibility; nothing
#: here is an array, so it never fires.
_TRACE_MODES = ("read", "write", "unset", "array")

#: The single letters Tk used for trace modes before trace_add existed.
_LEGACY_MODES = {"r": "read", "w": "write", "u": "unset"}
_LEGACY_LETTERS = {name: letter for letter, name in _LEGACY_MODES.items()}


class StringVar(Variable):
    """A variable holding text.

    Sample output:
        name = tk.StringVar(value="Ada")
        tk.Entry(root, textvariable=name).pack()
        tk.Label(root, textvariable=name).pack()
        name.set("Ada Lovelace")
    """

    _default = ""

    def _convert(self, value: Any) -> str:
        """Render the value as text, as Tcl would."""
        return "" if value is None else str(value)


class IntVar(Variable):
    """A variable holding a whole number."""

    _default = 0

    def _convert(self, value: Any) -> int:
        """Parse the value as an integer.

        Raises:
            TclError: If it is not one, matching tkinter, which reports the
                Tcl conversion failure.
        """
        if isinstance(value, int) and not isinstance(value, bool):
            return value
        try:
            return int(str(value), 0)
        except (TypeError, ValueError):
            raise TclError(f'expected integer but got "{value}"') from None


class DoubleVar(Variable):
    """A variable holding a number with a fractional part."""

    _default = 0.0

    def _convert(self, value: Any) -> float:
        """Parse the value as a float.

        Raises:
            TclError: If it is not one.
        """
        try:
            return float(value)
        except (TypeError, ValueError):
            raise TclError(
                f'expected floating-point number but got "{value}"'
            ) from None


class BooleanVar(Variable):
    """A variable holding a truth value."""

    _default = False

    def _convert(self, value: Any) -> bool:
        """Parse the value the way Tcl reads a boolean.

        Raises:
            TclError: If it is none of the spellings Tcl accepts.
        """
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return bool(value)
        text = str(value).strip().lower()
        if text in _TRUE:
            return True
        if text in _FALSE:
            return False
        raise TclError(f'expected boolean value but got "{value}"')


# ======================================================================
# Widgets
# ======================================================================


class XView:
    """The horizontal half of Tk's scroll protocol, as ``tkinter.XView``.

    A widget that scrolls sideways supplies ``xview(*args)`` - the query, and
    the ``moveto`` and ``scroll`` forms a Scrollbar sends. This adds the two
    spellings a program writes itself, :meth:`xview_moveto` and
    :meth:`xview_scroll`.
    """

    # One definition here instead of one per widget; TkCurses-019 found seven
    # widgets with xview and without these.

    def xview(self, *args: Any) -> Any:  # pragma: no cover - always overridden
        """Query or move the horizontal view. Every user overrides this."""
        raise NotImplementedError

    def xview_moveto(self, fraction: float) -> None:
        """Put ``fraction`` of the total width off-screen to the left."""
        self.xview("moveto", fraction)

    def xview_scroll(self, number: int, what: str) -> None:
        """Shift the view by ``number`` ``"units"`` or ``"pages"``."""
        self.xview("scroll", number, what)


class YView:
    """The vertical half of Tk's scroll protocol. ``tkinter.YView``.

    ``tree.yview_moveto(0.0)`` - back to the top - and
    ``listbox.yview_scroll(1, "units")`` are what a program's own key handlers
    write. See :class:`XView`.
    """

    def yview(self, *args: Any) -> Any:  # pragma: no cover - always overridden
        """Query or move the vertical view. Every user overrides this."""
        raise NotImplementedError

    def yview_moveto(self, fraction: float) -> None:
        """Put ``fraction`` of the total height off-screen above."""
        self.yview("moveto", fraction)

    def yview_scroll(self, number: int, what: str) -> None:
        """Shift the view by ``number`` ``"units"`` or ``"pages"``."""
        self.yview("scroll", number, what)


class _Drawable(Widget):
    """Painting shared by the widgets that draw a background and a border."""

    def _font_attribute(self) -> int:
        """What this widget's ``font`` option does to its text.

        A terminal has one typeface, so the part of a Tk font specification
        that survives is the styling: bold, italic and underline. A widget
        with no ``font`` option - a Frame, a Scrollbar - has no text of its
        own to style and gets nothing.
        """
        option = self._options.get("font", "")
        named = self.tk.fonts.get(str(option))
        if named is not None:
            # A font created through tkcurses.font. Tk keeps these in the
            # interpreter and a widget names one; the styling lives with the
            # font rather than in the widget's own option string.
            return from_font(
                bold=str(named.get("weight", "normal")) == "bold",
                italic=str(named.get("slant", "roman")) == "italic",
                underline=bool(named.get("underline", False)),
            )
        font = str(option).lower()
        return from_font(
            bold="bold" in font,
            italic="italic" in font,
            underline="underline" in font,
        )

    @property
    def _disabled(self) -> bool:
        """True while the widget refuses to answer the user.

        Here rather than on any one widget: every widget that takes a click
        or a key asks the same question, and the ones that have no ``state``
        at all - a Frame - answer no.
        """
        return str(self._options.get("state", "normal")) == "disabled"

    def _background_attribute(self) -> int:
        """The curses attribute this frame's colours resolve to.

        Falls back to plain when no colour manager is running, which is what a
        terminal without colour gives anyway.
        """
        colors = self.tk.colors
        if colors is None:
            return _curses.A_NORMAL
        return colors.attribute_for(
            str(self._options["foreground"] or "white"),
            str(self._options["background"] or "black"),
        )

    def _border_style(self) -> BorderStyle:
        """The characters this widget's border is drawn with.

        Its own method so that a subclass can answer differently: a themed
        widget takes its box from the theme's glyph set rather than from the
        relief, which is what makes ``Style.theme_use`` visible on screen.
        Before this existed, the nine themed widgets built on ordinary ones
        drew the relief's own characters and a theme change reached none of
        them - TkCurses-5vu, found by a person pressing Ctrl-T in UAT 40.
        """
        return style_for_relief(self._drawn_relief())

    def _draw_border(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        width: int,
        height: int,
        attribute: int,
    ) -> None:
        """Draw the box for this frame's relief.

        Drawn character by character rather than with curses' own ``border``,
        because a relief is a choice of line style - single, double, heavy -
        and ``border`` only knows one.
        """
        style = self._border_style()
        attribute |= style.attr
        # The window can be smaller than the widget: one clipped by a screen
        # edge or by its master gets only the part of itself that shows.
        # Every write goes through _write_line, which drops what falls
        # outside it rather than letting curses wrap it onto the next row.
        right = width - 1
        self._write_line(dispatcher, window, 0, 0, style.top(width), attribute)
        for row in range(1, height - 1):
            self._write_line(dispatcher, window, row, 0, style.vertical, attribute)
            self._write_line(dispatcher, window, row, right, style.vertical, attribute)
        self._write_line(
            dispatcher, window, height - 1, 0, style.bottom(width), attribute
        )


#: What a character that does not print is drawn as instead, where that is
#: not a question mark. A tab becomes a space because a tab IS whitespace -
#: it simply does not advance to a tab stop yet; see TkCurses-wy7. A
#: no-break space and a soft hyphen are typed on purpose, so they are drawn
#: as what they look like. Any other space is a space too.
_STAND_IN = {"\t": " ", "\u00a0": " ", "\u00ad": "-"}


def _stand_in(character: str) -> str:
    """What ``character``, which does not print, is drawn as: as many cells
    as :func:`~tkcurses._core.cells.char_cells` measures it, so that what
    is drawn and what is measured agree.

    A zero-width format character - a zero-width space or joiner, a
    direction mark - is drawn as nothing; given to the terminal, a joiner
    would join two emoji the widths here count apart, and a direction
    override could reorder the row. A control character, and anything else
    with no better stand-in, is a question mark, which is visible: a stray
    control character in a widget is a bug somewhere, and drawing nothing
    would hide it.
    """
    if is_embedded(character):
        return "?"  # a Text draws its embedded windows and images itself
    width = char_cells(character)
    mark = _STAND_IN.get(character)
    if mark is None:
        mark = " " if unicodedata.category(character) == "Zs" else "?"
    return mark * width


def _one_cell_each(text: str) -> str:
    """Replace each character that does not print with a stand-in of the
    same width in cells (see :func:`_stand_in`).

    Column calculations here - clipping to a window, the insert cursor,
    ``bbox``, mapping a click back to an index - measure a character by
    :func:`~tkcurses._core.cells.char_cells`. A control character has no
    width at all until curses draws it as the terminal sees fit, which is
    after the arithmetic has been done.

    Measured before this existed: a Text holding "\tAB" drew A at column 10
    while reporting it at column 4, because curses expanded the tab to a tab
    stop and the widget had counted it as one. A Label holding "A\tB" lost
    the B entirely, and an Entry holding "C\tD" pushed the D seven columns
    into a twenty-column box. Every widget was affected, because they all
    write through here.

    The substitution keeps the width in cells, not the length: a
    zero-width space measured as no cells and drawn as a one-cell ``?``
    put the cursor of the Entry holding it a column short.
    """
    if text.isprintable():
        return text
    return "".join(
        character if character.isprintable() else _stand_in(character)
        for character in text
    )


class Frame(_Backdrop, _Drawable):
    """A container: a rectangle of background, an optional border, and
    somewhere to put other widgets.

    Its size comes from its children unless ``width`` or ``height`` says
    otherwise. Setting either, and turning off propagation, fixes that
    dimension, which is how a frame is made to hold a shape its contents
    would not produce on their own.

    Sample output:
        frame = tk.Frame(root, relief="groove", bd=1, padx=1)
        frame.pack()
        tk.Label(frame, text="Inside a frame").pack()
        tk.Button(frame, text="OK").pack()

    Sample output (backgroundimage, tile):
        # size: 40x8
        squares = tk.PhotoImage(width=4, height=2)
        squares.put("navy", to=(0, 0, 4, 2))
        squares.put("teal", to=(0, 0, 2, 1))
        squares.put("teal", to=(2, 1, 4, 2))
        frame = tk.Frame(root, width=30, height=6, relief="solid", bd=1,
                         backgroundimage=squares, tile=True)
        frame.pack()
        tk.Label(frame, text="Over the tiles").place(x=8, y=2)

    Options:
        backgroundimage: An image drawn behind the frame's children, inside
            its border, or ``""`` for none. Also spelled ``bgimg``. It must
            exist when it is set, and while the image it names has been
            deleted every configure that sets something is refused, until
            this is set again. It does not change the frame's size.
        class: The class name bindings and the option database know the frame
            by. It cannot be changed once the frame is made.
        colormap: An X colormap, in Tk. Checked as Tk checks it, and kept.
        container: Whether another application's window is embedded in it.
            Kept; nothing can be embedded in a terminal.
        tile: How ``backgroundimage`` is drawn: true repeats it across the
            inside of the border from its top left corner, false (the
            default) centres one copy, cutting it at the border if it is too
            big.
        visual: An X visual, in Tk. Checked as Tk checks it, and kept.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``height``,
    ``highlightbackground``, ``highlightcolor``, ``highlightthickness``,
    ``padx``, ``pady``, ``relief``, ``takefocus``, ``width``.

    Differences from tkinter:
        ``class``, ``colormap``, ``container`` and ``visual`` are about an X
        window and change nothing in a terminal; each is checked and read back
        as Tk does. A ``backgroundimage`` is drawn a pixel to a cell across and
        two to a cell down, as every image is, and in the nearest colours the
        terminal's colour pairs give: a Label's image can be painted in exact
        colour over the screen, but a background has the frame's children in
        front of it. ``highlightbackground``, ``highlightcolor`` and
        ``highlightthickness`` are accepted and draw nothing: the focus is shown
        by markers instead. So is ``cursor``: the mouse pointer belongs to the
        terminal.
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"foreground"})

    #: ``width`` and ``height`` are cells; zero means "ask the children".
    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "height": _signed_distance,
        "width": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        **_WINDOW_SYSTEM_OPTIONS,
        "backgroundimage": "",
        "height": 0,
        "tile": 0,
        "width": 0,
    }

    _creation_only = frozenset(_WINDOW_SYSTEM_OPTIONS)

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        class_: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            class_: The class this frame binds and reads options under, as
                tkinter's ``class_`` does. Construction-time only.
            **kw: Options as keywords.
        """
        class_, cnf, kw = _class_from(class_, cnf, kw)
        self._class_name = class_
        super().__init__(master, cnf, name=name, **kw)
        if not _is_ttk(self):
            self._options["class"] = self.winfo_class()
        self._follow_backdrop()
        self._apply_requested_size()

    def winfo_class(self) -> str:
        """The class this frame binds and reads options under."""
        return self._class_name or type(self).__name__

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, repainting and resizing as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if "backgroundimage" in {self._option_synonyms.get(key, key) for key in given}:
            self._follow_backdrop()
        if {"width", "height"} & set(given):
            self._apply_requested_size()
        self._invalidate_layout()
        self._redraw()
        return result

    config = configure

    def _apply_requested_size(self) -> None:
        """Fix the size from the options, or hand the question to the children.

        Setting only one fixes that axis and leaves the other to the children,
        which is what makes a fixed-width sidebar of variable height
        expressible.

        The size is a *request*, not a guarantee: once the frame has children,
        its geometry manager works out what they need and that wins. Tk
        behaves the same way, and the way to keep an explicit size is
        pack_propagate(False) - the gotcha every tkinter user meets once.
        """
        width = int(self._options["width"])
        height = int(self._options["height"])
        if width or height:
            self._request_size(
                width or self._requested.width, height or self._requested.height
            )

    def _redraw(self) -> None:
        """Paint the frame: background first, then its border.

        Silent without a window or a screen, which is every frame until it has
        been laid out and the terminal is running.
        """
        window = self._window
        if window is None or self.tk.screen is None:
            return
        width, height = self._rect.width, self._rect.height
        dispatcher = CursesDispatcher.get()
        attribute = self._background_attribute()
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(dispatcher, window, width, height, attribute)
            edge = BORDER_WIDTH if self._border_drawn else 0
            background = str(self._options["background"] or "black")
            self._paint_backdrop(dispatcher, window, edge, background)


def _repaint_when_image_is_collected(reference: weakref.ref[Any]) -> None:
    """Repaint the widget behind ``reference``, its image having gone.

    Module level and weak on purpose: a bound method here would make the
    image own the widget, and the point of the whole arrangement is that it
    does not.
    """
    widget = reference()
    if widget is not None and widget.winfo_exists():
        # Repaint, and deliberately do NOT re-measure. Measured on Tk 9.0.2,
        # deleting an image a Label was showing left the label at its old
        # 22x12 after an update: the geometry it negotiated stays, and only
        # the drawing stops. Re-measuring here would collapse it to nothing,
        # which is tidier and is not what tkinter code has been written
        # against.
        widget._redraw()


#: Cells left between an image and the text beside it. Tk leaves one pixel,
#: which is a fraction of a cell and rounds to nothing; horizontally a whole
#: cell is needed or the art and the first letter run together, while stacked
#: rows are already distinct without one.
IMAGE_GAP = 1


class _TextWidget(_Drawable):
    """A widget whose size and appearance come from a run of text.

    Label and Button both are: they measure themselves from their text, wrap
    it, justify it against itself and anchor the block within whatever area
    they were given. What separates them is what they do afterwards, not how
    the text gets there.

    ``justify`` and ``anchor`` are different questions and a one-line widget
    shows no difference between them: justify aligns the lines against each
    other, anchor puts the resulting block within the widget.
    """

    #: Measured on Tk 9.0.2 by making each widget with a bad value: a
    #: label's size is in characters and its padding in screen distance.
    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "height": _tcl_integer,
        "padx": _screen_distance,
        "pady": _screen_distance,
        "width": _tcl_integer,
        "wraplength": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "anchor": "center",
        "compound": "none",
        "font": "",
        "height": 0,
        "image": "",
        "justify": "center",
        "state": "normal",
        "text": "",
        "textvariable": None,
        "underline": -1,
        "width": 0,
        "wraplength": 0,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``text``, ``textvariable``, ``anchor``, ``justify``,
                ``wraplength``, ``width``, ``height``, ``state``,
                ``underline``, ``font``, and the standard options.
        """
        self._variable_trace: tuple[Variable, str] | None = None
        #: The name of the image this widget is listening to, so that
        #: pointing it at a second one can stop listening to the first. The
        #: NAME, not the image: holding the object would keep it alive, and
        #: an image a widget cannot outlive is the one thing Tk's arrangement
        #: guarantees against.
        self._watched_image: str = ""
        #: Fires when that image is collected, so the widget can repaint
        #: itself empty. See _follow_image.
        self._image_finalizer: weakref.finalize[Any, None] | None = None
        super().__init__(master, cnf, name=name, **kw)
        self._follow_variable()
        self._follow_image()
        self._apply_requested_size()

    # -------------------------------------------------------------- content

    #: Tk's classic menubutton stores an image name before it looks it up, so
    #: one it refuses is kept: measured on Tk 9.0.2, ``cget("image")`` then
    #: answers ``nosuch``. Every other widget of the family keeps the old one.
    _stores_refused_image: ClassVar[bool] = False

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """The shared checks, and Tk's for the ``image``.

        Tk looks the image up again on every configure that sets anything,
        not only when the option changes. Measured on
        Tk 9.0.2: a name that is not an image is refused, ``image "nosuch"
        does not exist``, and the widget keeps the image it had; and once a
        label's image has been deleted, ``configure(text="x")`` is refused
        with ``image "pyimage1" does not exist`` until ``image`` names one
        that exists, or ``""``.
        """
        resolved = super()._checked(given)
        if not given or "image" not in self._public_options():
            return resolved
        if "image" in resolved:
            name = str(resolved["image"] or "")
        else:
            name = str(getattr(self, "_options", {}).get("image") or "")
        if name and self.tk.images.get(name) is None:
            if "image" in resolved and self._stores_refused_image:
                self._options["image"] = name
            raise TclError(f'image "{name}" does not exist')
        return resolved

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-measuring and repainting as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if "textvariable" in given:
            self._follow_variable()
        if "image" in given:
            self._follow_image()
        self._apply_requested_size()
        self._invalidate_layout()
        self._redraw()
        return result

    config = configure

    # ---------------------------------------------------------------- images

    def _follow_image(self) -> None:
        """Listen to the ``image`` option's image, dropping any previous one.

        Measured on Tk 9.0.2: resizing an image from 4x2 to 20x10 moved a
        live Label's requested size from 6x4 to 22x12 with nothing asked of
        the label at all. A widget follows its image, so it has to be told.

        Raises:
            TclError: If the option names an image that does not exist, which
                is what Tk raises: ``image "nosuch" does not exist``.
        """
        previous = self.tk.images.get(self._watched_image)
        if previous is not None:
            previous._unwatch(self)
        if self._image_finalizer is not None:
            self._image_finalizer.detach()
            self._image_finalizer = None
        self._watched_image = ""
        option = self._options["image"]
        if not option:
            return
        # Normalised to the name, because that is what Tk stores: measured on
        # 9.0.2, a Label built with image=<PhotoImage> answers cget("image")
        # with 'pyimage1'. Keeping the object instead would quietly make the
        # widget an owner of its image, and the whole weak arrangement - a
        # widget outliving its art rather than the other way round - would
        # stop being true the moment anyone passed an object.
        name = str(option)
        self._options["image"] = name
        image = self.tk.images.get(name)
        if image is None:
            raise TclError(f'image "{name}" does not exist')
        image._watch(self, self._image_changed)
        self._watched_image = name
        # An image going away has to repaint the widget, and collection is
        # silent: the registry simply stops holding it, and _users dies with
        # it, so the watch above cannot be what says so. Without this a
        # widget goes on showing art whose image no longer exists - not
        # merely stale, but undrawable, since _image() already returns None
        # and only the last painted cells are still on the screen.
        #
        # Weak on the widget, or the image would keep alive the very widget
        # that is supposed to outlive it. atexit=False because this paints,
        # and interpreter shutdown is no time to be calling curses.
        self._image_finalizer = weakref.finalize(
            image, _repaint_when_image_is_collected, weakref.ref(self)
        )

    def _image_changed(self) -> None:
        """Re-measure and repaint after the image under this widget moved."""
        self._apply_requested_size()
        self._invalidate_layout()
        self._redraw()

    def _image(self) -> Image | None:
        """The image to draw, or None.

        A name that no longer resolves gives None rather than raising. That
        is deliberate and it is Tk's behaviour: measured, deleting an image a
        Label was showing left the label alive at its old size with the dead
        name still in its ``image`` option. Only *setting* an unknown name is
        an error; having one go away underneath is the documented trap.
        """
        name = str(self._options["image"])
        if not name:
            return self._bitmap_image()
        return self.tk.images.get(name)

    def _bitmap_image(self) -> Image | None:
        """The image ``bitmap="@file"`` names, kept until the file or the
        colour changes; an image wins over a bitmap, as in Tk."""
        bitmap = str(self._options.get("bitmap", ""))
        if not bitmap.startswith("@"):
            return None
        key = (bitmap, str(self._options.get("foreground") or "white"))
        cached = getattr(self, "_bitmap_cache", None)
        if cached is None or cached[0] != key:
            try:
                image = _file_bitmap(self, bitmap[1:], key[1])
            except TclError:
                return None
            cached = self._bitmap_cache = (key, image)
        return cached[1]

    def _bitmap_glyph(self) -> str:
        """The cell a named ``bitmap`` draws as, or ``""``. An ``image``
        wins over it, as Tk measures: the request becomes the image's."""
        if str(self._options["image"]):
            return ""
        return _BITMAP_GLYPHS.get(str(self._options.get("bitmap", "")), "")

    def _drawn_image(self) -> Image | None:
        """The image painted, which a check or radio button may swap for its
        state's. The size is always measured from :meth:`_image`."""
        return self._image()

    def _follow_variable(self) -> None:
        """Track the ``textvariable``, dropping any previous one.

        The old trace has to go: a label pointed at a second variable that
        still answered to the first would take its text from whichever was
        written to last.
        """
        if self._variable_trace is not None:
            variable, handle = self._variable_trace
            variable._unwatch(handle)
            self._variable_trace = None
        variable = self._options["textvariable"]
        if variable is None:
            return
        _seed_variable(self, variable, self._options["text"])
        handle = variable._watch(self._variable_changed)
        self._variable_trace = (variable, handle)
        self._variable_changed()

    def _variable_changed(self) -> None:
        """Re-measure and repaint after the variable behind the text moved.

        The ``text`` option is kept in step with the variable, which is what
        Tk does: measured on 9.0.2, a Label built with ``textvariable=`` and
        no ``text=`` answers ``cget("text")`` with the variable's value and
        keeps answering with it as the variable changes.

        It did not here, and the display was right the whole time - ``_text``
        prefers the variable - so every screen looked correct and only code
        that *asked* a widget what it was showing got an answer that was not
        on the screen.

        Written into the options directly rather than through ``configure``:
        that would re-enter the option machinery on every write, and a
        ``configure`` that wrote the variable back would have the two chasing
        each other.
        """
        variable = self._options["textvariable"]
        if variable is not None:
            self._options["text"] = str(variable.get())
        self._apply_requested_size()
        self._invalidate_layout()
        self._redraw()

    def _text(self) -> str:
        """The text to display.

        A ``textvariable`` wins over ``text`` when both are set, which is what
        tkinter does: the variable is the live one.
        """
        variable = self._options["textvariable"]
        if variable is not None:
            return str(variable.get())
        return str(self._options["text"])

    def _lines(self) -> list[str]:
        """The text as display lines, wrapped if ``wraplength`` says so."""
        return wrap(self._text(), _as_int(self._options["wraplength"], 0))

    def _content_size(self) -> tuple[int, int]:
        """How big the image and text together are, in cells."""
        width, height = 0, 0
        for _, rect in self._content_layout():
            width = max(width, rect.x + rect.width)
            height = max(height, rect.y + rect.height)
        return width, height

    def _content_layout(self) -> list[tuple[str, Rect]]:
        """Where the image and the text sit relative to each other.

        Returns ``("image", rect)`` and ``("text", rect)`` pairs, each
        positioned within a block whose origin is (0, 0); the caller anchors
        that block wherever the widget's area allows.

        The arrangement is ``compound``, and its default is the part that
        surprises people. Measured on Tk 9.0.2, a Label with both
        ``text='hello'`` and an 8x4 image:

            compound=none (DEFAULT)  10x6  <- the image, and no text at all
            compound=left/right      45x23    side by side
            compound=top/bottom      36x28    stacked
            compound=center          36x23    the text over the image

        So setting an image on a labelled widget silently hides its text
        unless compound says otherwise, and reproducing that matters more
        than the arrangement being a sensible default.
        """
        lines = self._lines()
        text = Rect(0, 0, *measure(lines))
        image = self._image()
        glyph = self._bitmap_glyph() if image is None else ""
        if image is None and not glyph:
            # Including when there is no text either: an empty label still
            # occupies a row, because measure([""]) is one line high, and
            # that is what keeps a blank label from collapsing.
            return [("text", text)]
        # In CELLS. The image is a plane of pixels half a cell tall, so its
        # height halves here and its width does not - see ARCHITECTURE.md's
        # "The pixel". Laying out in pixels would make every image twice as
        # tall as it draws. A named bitmap is one glyph, laid out as an
        # image is: Tk draws a bitmap in place of the text unless
        # ``compound`` says otherwise, and so is it here.
        if image is not None:
            picture = Rect(0, 0, image.width(), image.cell_height())
        else:
            picture = Rect(0, 0, cells(glyph), 1)
        compound = str(self._options["compound"] or "none")
        if compound == "none" or not self._text():
            # An image and no text is just the image, however compound reads:
            # otherwise an empty string would reserve a gap and a row for
            # nothing.
            return [("image", picture)]
        if compound == "center":
            width = max(picture.width, text.width)
            height = max(picture.height, text.height)
            return [
                (
                    "image",
                    picture.translated(
                        (width - picture.width) // 2, (height - picture.height) // 2
                    ),
                ),
                (
                    "text",
                    text.translated(
                        (width - text.width) // 2, (height - text.height) // 2
                    ),
                ),
            ]
        if compound in ("left", "right"):
            height = max(picture.height, text.height)
            first, second = (picture, text) if compound == "left" else (text, picture)
            names = ("image", "text") if compound == "left" else ("text", "image")
            return [
                (names[0], first.translated(0, (height - first.height) // 2)),
                (
                    names[1],
                    second.translated(
                        first.width + IMAGE_GAP, (height - second.height) // 2
                    ),
                ),
            ]
        width = max(picture.width, text.width)
        first, second = (picture, text) if compound == "top" else (text, picture)
        names = ("image", "text") if compound == "top" else ("text", "image")
        return [
            (names[0], first.translated((width - first.width) // 2, 0)),
            (names[1], second.translated((width - second.width) // 2, first.height)),
        ]

    def _apply_requested_size(self) -> None:
        """Ask for room for the content, or for the size the options name.

        Padding and any border are included: a label asks for what it needs to
        draw, not for what is left after the frame around it. The padding is
        :meth:`_content_padding`'s, so a themed widget's ``padding`` is in it
        too.
        """
        text_width, text_height = self._content_size()
        # _as_int throughout: a ttk label keeps a width Tk does not check,
        # "abc" too, and Message takes "" for its padding. TkCurses-vgkb.
        width = _as_int(self._options["width"], 0) or text_width
        height = _as_int(self._options["height"], 0) or text_height
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        padding = self._content_padding()
        self._request_size(width + padding.width + edge, height + padding.height + edge)

    # ------------------------------------------------------------- painting

    def _redraw(self) -> None:
        """Paint the background, the border if any, and then the text."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        attribute = self._background_attribute()
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            self._draw_text(dispatcher, window, attribute)

    def _draw_text(
        self, dispatcher: CursesDispatcher, window: Any, attribute: int
    ) -> None:
        """Write the image and the lines into the area left after the border."""
        # Cleared here rather than in _draw_image, which is only reached when
        # there IS an image. A widget whose image has been collected draws
        # nothing and never gets there, so its cells would be repainted past
        # curses for ever - the stale art UAT 35 exists to demonstrate.
        painter = getattr(self.tk, "painter", None)
        if painter is not None:
            painter.clear(self)
        area = self._text_area()
        if area.is_empty:
            return
        layout = self._content_layout()
        places = dict(layout)
        if "image" in places:
            self._draw_image(dispatcher, window, area, places["image"], layout)
        if "text" not in places:
            # compound=none with an image: the text is not drawn at all.
            return
        lines = self._lines()
        attribute |= self._text_attribute()
        across, down = parse_anchor(str(self._options["anchor"]))
        block_width, _ = measure(lines)
        # Clamped to the top, the way the column below is clamped to the
        # left: text taller than the widget has to lose its end rather than
        # its beginning, or it cannot be read at all.
        content_width, content_height = self._content_size()
        text_place = places["text"]
        origin_x = area.x + int((area.width - content_width) * across)
        origin_y = max(area.y, area.y + int((area.height - content_height) * down))
        top = origin_y + text_place.y
        justify = str(self._options["justify"])
        for index, line in enumerate(lines):
            row = top + index
            if not (area.y <= row < area.y + area.height):
                continue
            # Justify from the line's real length, then clip. Clipping first
            # measures the wrong thing: a line wider than the area comes back
            # shortened, and centring the shortened version pushes it right,
            # so text too long to fit ends up hard against the far edge with
            # its beginning cut off.
            column = origin_x + text_place.x
            column += align_offset(cells(line), block_width, justify)
            skipped = self._cells_cut_before(column, area)
            line, blank = skip_cells(line, skipped)
            column = max(column + skipped + blank, area.x)
            text = clip_text(line, area.x + area.width - column)
            # Through _write_line, which clips again to the window: the area
            # is the widget's, and a widget the screen edge cuts in half has
            # a window smaller than that.
            self._write_line(dispatcher, window, row, column, text, attribute)
        self._draw_underline(dispatcher, window, area, lines, attribute)

    def _draw_bitmap_glyph(
        self, dispatcher: CursesDispatcher, window: Any, area: Rect, place: Rect
    ) -> None:
        """Write a named bitmap's glyph where the layout put it, in the
        widget's foreground, as Tk draws a bitmap's set bits."""
        glyph = self._bitmap_glyph()
        if not glyph:
            return
        content_width, content_height = self._content_size()
        across, down = parse_anchor(str(self._options["anchor"]))
        column = area.x + int((area.width - content_width) * across) + place.x
        row = max(area.y, area.y + int((area.height - content_height) * down))
        row += place.y
        if (
            area.y <= row < area.y + area.height
            and area.x <= column < area.x + area.width
        ):
            attribute = self._background_attribute() | self._text_attribute()
            self._write_line(dispatcher, window, row, column, glyph, attribute)

    def _cells_cut_before(self, column: int, area: Rect) -> int:
        """How many cells of a line starting at ``column`` the area cuts off.

        Measured on Tk 9.0: a classic Label, Button, Checkbutton or
        Radiobutton with ``width=5``, text ``abcdefghij`` and ``anchor="e"``
        shows ``fghij``, and ``cdefg`` centred - the anchor puts the text
        where it would go in a wide enough widget, and the window cuts what
        falls outside, start included. The themed widgets show ``abcde``
        whatever the anchor: their text is never placed left of the area.
        TkCurses-tyd9.
        """
        if column >= area.x:
            return 0
        return area.x - column if not _is_ttk(self) else 0

    def _draw_image(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        place: Rect,
        layout: list[tuple[str, Rect]],
    ) -> None:
        """Paint the image's cells into ``area`` at ``place``.

        A cell holding None is a hole and is skipped rather than written as a
        space, so art that is not a full rectangle - and a bitmap's clear
        bits - show whatever is behind them instead of punching a block of
        background through it.
        """
        image = self._drawn_image()
        if image is None:
            self._draw_bitmap_glyph(dispatcher, window, area, place)
            return
        del layout
        content_width, content_height = self._content_size()
        across, down = parse_anchor(str(self._options["anchor"]))
        origin_x = area.x + int((area.width - content_width) * across)
        origin_y = max(area.y, area.y + int((area.height - content_height) * down))
        _paint_image(
            self,
            dispatcher,
            window,
            image,
            origin_x + place.x,
            origin_y + place.y,
            area,
            str(self._options["background"] or "black"),
        )

    def _text_area(self) -> Rect:
        """Where the text may go, in cells relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padding = self._content_padding()
        return Rect(
            edge + padding.left,
            edge + padding.top,
            max(0, self._rect.width - 2 * edge - padding.width),
            max(0, self._rect.height - 2 * edge - padding.height),
        )

    _STATE_COLOURS: ClassVar[dict[str, tuple[str | None, str | None]]] = {
        "active": ("activeforeground", "activebackground"),
        "disabled": ("disabledforeground", None),
    }

    def _shown_state(self) -> str:
        """The state the widget is drawn in: ``active`` while held down.

        Tk's press is always on an active button - the pointer is over it,
        or Space has set the state for the flash, in ``tk::ButtonInvoke`` -
        so its active colours show through a press. Here a press is ``_pressed``, on the widgets that
        have one.
        """
        if self._held_down():
            return "active"
        return str(self._options["state"])

    def _held_down(self) -> bool:
        """True while drawn pressed: held, and the pointer not dragged off.

        Tk's ``tk::ButtonLeave`` puts a held button's relief back and
        ``tk::ButtonEnter`` sinks it again, so dragging off a button shows
        that letting go there will not press it.
        """
        return bool(getattr(self, "_pressed", False)) and not getattr(
            self, "_pointer_away", False
        )

    def _background_attribute(self) -> int:
        """The widget's colours, or its state's if a program gave them.

        The whole widget, as Tk paints it: an active button's background is
        ``activebackground`` from edge to edge, not only behind the text.
        """
        attribute = super()._background_attribute()
        colours = self._state_colours(self._shown_state())
        return attribute if colours is None else self._coloured(attribute, *colours)

    def _text_attribute(self) -> int:
        """Attributes the font and state put on the text.

        A state given colours is shown by them, in ``_background_attribute``,
        and not reversed or dimmed as well.
        """
        attribute = self._font_attribute()
        state = str(self._options["state"])
        if self._state_colours(state) is None:
            with contextlib.suppress(ValueError):
                attribute = for_state(state, attribute)
        return attribute

    def _draw_underline(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        lines: list[str],
        attribute: int,
    ) -> None:
        """Underline one character, as tkinter's ``underline`` index does.

        The index counts through the text as written, so on wrapped text it
        has to be resolved to a line and a column rather than used directly.
        """
        index = _underline_position(self._options["underline"], "".join(lines))
        if index < 0:
            return
        remaining = index
        line_number: int | None = None
        for number, line in enumerate(lines):
            if remaining < len(line):
                line_number = number
                break
            remaining -= len(line)
        # The index counts characters; where the letter is counts cells.
        letter = remaining
        if line_number is None:
            # The index runs past the end of the text, which is how tkinter
            # code switches the underline off without removing the option.
            return
        block_width, block_height = measure(lines)
        across, down = parse_anchor(str(self._options["anchor"]))
        top = max(area.y, area.y + int((area.height - block_height) * down))
        row = top + line_number
        column = area.x + int((area.width - block_width) * across)
        line = lines[line_number]
        column += align_offset(cells(line), block_width, str(self._options["justify"]))
        remaining = cells(line[:letter])
        # Where the line was drawn, so the mark is under its letter; and not
        # at all when that letter is cut off.
        if column < area.x and not self._cells_cut_before(column, area):
            column = area.x
        if not area.x <= column + remaining < area.x + area.width:
            return
        with contextlib.suppress(_curses.error):
            self._write_line(
                dispatcher,
                window,
                row,
                column + remaining,
                line[letter],
                attribute | _curses.A_UNDERLINE,
            )


def _pair_palette(image: Image, colors: Any) -> dict[str, str] | None:
    """The colours to write ``image`` through curses in, so that it fits the
    colour pairs left: each pixel colour mapped to its stand-in, or None when
    the picture fits as it is.

    A picture can want far more combinations than the 255 pairs hold - a
    busy photograph at 256 colours wants over a thousand - and drawn as it
    is, it fills the table, after which every colour asked for falls back to
    whichever pair happened to be allocated first. Not only the picture's:
    measured, Labels packed under one drew in ``#87005f`` on ``#0000ff``
    instead of the reds and blues they asked for.

    **A new picture that does not fit asks for the table to be emptied
    first**, and is fitted on the repaint that follows. Fitted at once, it
    would be fitted into whatever the previous picture left behind - pairs
    nothing shows any more, which only emptying the table gives back.
    Measured, a second picture came out in 24 colour pairs of the 192 it
    was built from.

    Fitting a full-screen photograph costs about 200ms, so the answer is
    kept on the image and chosen again only when the picture changes, the
    pair table is emptied, or the depth moves: a repaint compares a tuple.
    The budget is what the table has left, less an eighth of it for
    whatever is drawn after the picture - text in colours of its own, which
    would otherwise find the table full.
    """
    if not isinstance(image, PhotoImage):
        return None
    key = (image._revision, colors.generation, colors.depth)
    cached = image._fit_cache
    if cached is not None and cached[0] == key:
        return cached[1]
    seen = cached is not None and cached[0][0] == image._revision
    remaining = colors.remaining
    budget = max(remaining - max(8, colors.capacity // 8), min(remaining, 16))
    palette: dict[str, str] | None = None
    if budget > 0 and image.pairs_needed(colors.depth) > budget:
        if not seen:
            colors.ask_for_renewal()
            # Never a hit, so the repaint after the renewal fits it - and
            # if no renewal comes, the next draw does.
            image._fit_cache = ((image._revision, None, colors.depth), None)
            return None
        fitted = image.fit_pairs(budget, colors.depth)
        palette = {}
        for row, fitted_row in zip(image._pixels, fitted._pixels, strict=True):
            for pixel, stand_in in zip(row, fitted_row, strict=True):
                if pixel is not None and stand_in is not None:
                    palette[pixel] = stand_in
    image._fit_cache = (key, palette)
    return palette


def _paint_image(
    widget: Any,
    dispatcher: CursesDispatcher,
    window: Any,
    image: Image,
    left: int,
    top: int,
    area: Rect,
    background: str,
) -> None:
    """Paint ``image`` with its top-left cell at ``(left, top)`` in
    ``widget``'s window, only where it falls inside ``area``.

    A cell holding None is a hole and is skipped rather than written as a
    space, so art that is not a full rectangle shows what is behind it.
    """
    painter = getattr(widget.tk, "painter", None)
    # The same compose() a Canvas draws through, on the same plane: it
    # folds each pair of pixel rows into one cell and says which glyph
    # and which two colours that cell needs. A background of None means
    # the unlit half should show the widget's own colour rather than one
    # of the image's.
    colors = widget.tk.colors
    direct = painter is not None and painter.enabled
    palette = None
    if colors is not None and not direct:
        palette = _pair_palette(image, colors)
    # Absolute screen position, because the painter writes past curses
    # and curses windows are the only thing that knows about offsets.
    where = widget._screen_rect()
    buffer = widget.tk.screen.buffer if widget.tk.screen is not None else None
    # Only the pixels that can land in the area. Composing the whole
    # image and discarding what falls outside made a repaint cost what
    # the IMAGE costs rather than what the WINDOW costs: measured, a
    # 320x200 photograph took 47ms a repaint on a 24-row screen, which
    # is past the 50-80ms boundary where ncurses starts dropping mouse
    # reports once a runner is a few times slower.
    # Exact, with no slack. A cell holds ROWS_PER_CELL pixel rows and
    # compose() pairs them from the image's own origin, so area.height
    # cells span exactly that many rows - a spare cell either way was
    # only ever a margin against arithmetic nobody had checked.
    first_row = (area.y - top) * ROWS_PER_CELL
    last_row = first_row + area.height * ROWS_PER_CELL
    first_column = area.x - left
    last_column = first_column + area.width
    visible = image.lit((first_column, first_row, last_column, last_row))
    for (x, y), (glyph, fore, back) in compose(visible).items():
        line = top + y
        column = left + x
        if not (area.y <= line < area.y + area.height):
            continue
        if not (area.x <= column < area.x + area.width):
            continue
        if colors is None:
            attribute = _curses.A_NORMAL
        else:
            if direct:
                # Shows only where the writes past curses do not, so eight
                # colours will do, and they cannot fill the pair table.
                attribute = colors.fallback_attribute_for(fore, back or background)
            elif palette is None:
                attribute = colors.attribute_for(fore, back or background)
            else:
                attribute = colors.attribute_for(
                    palette.get(fore, fore),
                    background if back is None else palette.get(back, back),
                )
        # Written through curses as well, always. If direct painting
        # never happens - no truecolor, a terminal that ignores it, a
        # closed stream - what shows is the ordinary rendering rather
        # than a hole where the picture was.
        widget._write_line(dispatcher, window, line, column, glyph, attribute)
        if direct and painter is not None:
            screen_row = where.y + line
            screen_column = where.x + column
            # Clipped to the screen, because this writes to the terminal
            # rather than to a window: a position outside it is not
            # ignored the way curses ignores one, it lands somewhere
            # else and can scroll what is already there.
            on_screen = buffer is not None and buffer.contains(
                screen_row, screen_column
            )
            exact_fore = rgb_of(fore) if on_screen else None
            exact_back = rgb_of(back or background) if on_screen else None
            if exact_fore is not None and exact_back is not None:
                painter.add(
                    widget,
                    screen_row,
                    screen_column,
                    glyph,
                    exact_fore,
                    exact_back,
                )


class Label(_TextWidget):
    """A run of text, or an image.

    Its size comes from the text unless ``width`` or ``height`` says
    otherwise, so a label is as wide as its longest line and as tall as it has
    lines. ``wraplength`` breaks the text at that many cells, at word
    boundaries where it can.

    Sample output:
        tk.Label(root, text="Hello, terminal").pack()

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeforeground``, ``anchor``, ``background``,
    ``bitmap``, ``borderwidth``, ``compound``,
    ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``image``, ``justify``,
    ``padx``, ``pady``, ``relief``, ``state``, ``takefocus``, ``text``,
    ``textvariable``, ``underline``, ``width``, ``wraplength``.

    Differences from tkinter:
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.
    """

    _widget_options: ClassVar[dict[str, Any]] = {
        **_STATE_COLOUR_OPTIONS,
        "bitmap": "",
        "borderwidth": 1,  # Tk's default
    }


class Button(_TextWidget):
    """A button: text in a box that runs something when pressed.

    Invoked by a mouse click, by Return, or by the space bar when it has the
    focus - the three gestures a terminal offers. ``invoke()`` does the same
    thing from code.

    Focus is shown by markers either side of the text, ``▶ OK ◀``, rather
    than by colour alone, and the text reverses while the button is held
    down. A terminal cannot be relied on for colour, and a button nobody can
    see the focus on is a button nobody can use from the keyboard.

    Sample output:
        tk.Button(root, text="Save").pack()

    Options:
        command: Called with no arguments when the button is pressed.
        default: ``normal``, ``active`` or ``disabled``: whether this is the
            button Return presses in a dialog.
        overrelief: The relief while the mouse is over the button; ``""``,
            the default, leaves it unchanged.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeforeground``, ``anchor``, ``background``,
    ``bitmap``, ``borderwidth``, ``compound``,
    ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``image``, ``justify``,
    ``padx``, ``pady``, ``relief``, ``repeatdelay``, ``repeatinterval``,
    ``state``, ``takefocus``, ``text``, ``textvariable``, ``underline``,
    ``width``, ``wraplength``.

    Differences from tkinter:
        ``default`` is accepted and not drawn: Tk rings the default button, and
        here it looks like any other. ``highlightbackground``,
        ``highlightcolor`` and ``highlightthickness`` are accepted and draw
        nothing: the focus is shown by markers instead. So is ``cursor``: the
        mouse pointer belongs to the terminal.
    """

    #: The markers drawn either side of the text. Room for them is reserved
    #: whether or not they are showing, so a button does not change width when
    #: it gains the focus.
    _FOCUS_MARKERS = ("\u25b6", "\u25c0")
    _PRESSED_MARKERS = ("\u258c", "\u2590")

    #: Cells the markers and their spacing occupy, either side of the text.
    _MARKER_WIDTH = 2

    _widget_options: ClassVar[dict[str, Any]] = {
        "bitmap": "",
        "borderwidth": 1,  # Tk's default
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        **_STATE_COLOUR_OPTIONS,
        "command": None,
        "default": "disabled",
        # The relief while the pointer is over it; "" for no change. Put in
        # place by the <Enter> binding, as Tk's is. TkCurses-gm66.5.
        "overrelief": "",
        "relief": "raised",
        # How long a press waits before invoking again, and how often after
        # that; 0 for never, Tk's default. TkCurses-gm66.6.
        "repeatdelay": 0,
        "repeatinterval": 0,
        "takefocus": True,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``command``, ``state``, plus everything a Label takes.
        """
        self._pressed = False
        self._pointer_away = False
        self._entered_relief: tuple[str, str] | None = None
        self._repeated = 0
        self._pointer_inside = False
        super().__init__(master, cnf, name=name, **kw)
        self._install_class_bindings()

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register the default behaviour for every Button in this application.

        Class bindings rather than instance ones, so that a binding of the
        same event on one button runs first and can stop this one with
        ``"break"`` - which is what tkinter's binding order is for, and what
        lets an application override a default without removing it.
        """
        # winfo_class() and not the literal "Button": a subclass that reports
        # another name - ttk.Button reports TButton - binds under that name,
        # and binding under this one would leave it with no bindings at all.
        # Binding tags name one class rather than a chain, so a themed button
        # would have been a button that answered nothing. _ChoiceWidget and
        # Menubutton already ask; this one did not, and it is the same fault
        # that has bitten Spinbox/Entry, OptionMenu/Menubutton and
        # ScrolledText/Text from the other direction.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        self.bind_class(name, "<Button-1>", _button_press)
        self.bind_class(name, "<ButtonRelease-1>", _button_release)
        self.bind_class(name, "<Key-Return>", _button_key)
        self.bind_class(name, "<Key-space>", _button_key)
        self.bind_class(name, "<FocusIn>", _button_refresh)
        self.bind_class(name, "<FocusOut>", _button_refresh)
        if not _is_ttk(self):
            self.bind_class(name, "<Enter>", _button_enter)
            self.bind_class(name, "<Leave>", _button_leave)
            # Where a held press is, for auto-repeat: Tk's Priv(window).
            self.bind_class(name, "<Motion>", _button_motion)

    # ------------------------------------------------------------ behaviour

    def invoke(self) -> Any:
        """Run the button's command and return whatever it returns.

        Does nothing when the button is disabled, which is the whole point of
        disabling one: the guard belongs here rather than in every caller.
        """
        if self._disabled:
            return None
        command = self._options["command"]
        if command is None:
            return None
        return command()

    def flash(self) -> None:
        """Blink the button, as tkinter's does.

        Drawn twice through the dispatcher rather than with a sleep: a button
        that stopped the event loop to flash would also stop the thing it just
        invoked.
        """
        if self._disabled:
            return
        self._pressed = not self._pressed
        self._redraw()
        self.after(80, self._end_flash)

    def _end_flash(self) -> None:
        """Put the button back the way it was after a flash."""
        self._pressed = False
        self._redraw()

    # ------------------------------------------------------------- painting

    def _apply_requested_size(self) -> None:
        """Ask for the text's room plus the markers either side of it."""
        super()._apply_requested_size()
        self._request_size(
            self._requested.width + 2 * self._MARKER_WIDTH, self._requested.height
        )

    def _redraw(self) -> None:
        """Paint the button, then its focus or pressed markers."""
        super()._redraw()
        self._draw_markers()

    def _draw_markers(self) -> None:
        """Draw the markers either side of the text, if there are any to draw."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        if self._held_down():
            left, right = self._PRESSED_MARKERS
        elif self.focus_get() is self:
            left, right = self._FOCUS_MARKERS
        else:
            return
        area = self._text_area()
        if area.is_empty or area.width < 2 * self._MARKER_WIDTH:
            return
        row = area.y + area.height // 2
        attribute = self._background_attribute() | self._text_attribute()
        dispatcher = CursesDispatcher.get()
        with contextlib.suppress(_curses.error):
            self._write_line(dispatcher, window, row, area.x, left, attribute)
            self._write_line(
                dispatcher, window, row, area.x + area.width - 1, right, attribute
            )


def _button_press(event: Event) -> None:
    """Show the button held down.

    Shared with Checkbutton, which presses and releases the same way and
    differs only in what invoking it does.

    The focus is deliberately left where it was, which is what Tk does -
    checked against Tk 9.0.2, where clicking a button, checkbutton,
    radiobutton, scale or menubutton leaves the focus alone and only an
    entry, spinbox, text or listbox takes it. The rule is worth stating,
    because taking the focus here is superficially helpful and actively
    harmful: a button binds Space and Return to invoke itself, so a button
    that took the focus on being clicked would quietly swallow both from
    whatever had them, and every later Space would press it again.
    """
    button = event.widget
    if button._disabled:
        return
    button._pressed = True
    button._redraw()
    # tk::ButtonDown: a repeatdelay starts the auto-repeat. A repeating press
    # is held on purpose for longer than the recovery allows, so it is not
    # armed for one; Tk._release_lost stands in for it.
    button._repeated = 0
    button._pointer_inside = True
    button._pointer_away = False
    delay = _repeat_option(button, "repeatdelay")
    if delay > 0:
        _repeat_after(button, delay, _button_auto_invoke, button)
    else:
        _arm_press_recovery(button)


def _button_auto_invoke(button: Any) -> None:
    """Invoke a held button again: Tk's ``tk::ButtonAutoInvoke``.

    Only while the pointer is still over it, as Tk's ``Priv(window)`` says;
    the repeat itself goes on, so coming back over it carries on invoking.
    """
    if button._pointer_inside:
        button._repeated += 1
        button.invoke()
    interval = _repeat_option(button, "repeatinterval")
    if interval > 0:
        _repeat_after(button, interval, _button_auto_invoke, button)


def _button_motion(event: Event) -> None:
    """Note whether a held press is still over the button."""
    button = event.widget
    if button._pressed:
        button._pointer_inside = _within(button, event)


#: The mouse states that put a button down: a double or triple click is a
#: press as well.
_PRESSES = ("pressed", "clicked", "double", "triple")

#: How long a button may stay drawn pressed with no release in sight.
#: Longer than any click, and shorter than a person will spend looking at a
#: control that has stopped working.
PRESS_RECOVERY_MS = 700


def _arm_press_recovery(button: Any) -> None:
    """Put the button back up if its release never arrives.

    **ncurses drops mouse reports that arrive faster than the application
    drains them.** Measured with a plain curses program, no TkCurses
    involved: a handler taking 120ms loses two of the four events from two
    clicks. So a release can simply never be delivered, and a button whose
    look depends on it stays drawn pressed and never invokes - until
    something else happens to repaint it.

    It was filed as needing "a handler slower than any in the library"
    (TkCurses-9lr). Measured on a real screen, that is not so: a Text of
    5000 lines redraws in 350ms and a Canvas of 500 items in 766ms, either
    of which is well past the 50-80ms where reports start being lost. A
    click handler that repaints one of those is enough.

    Recovering rather than preventing, because nothing downstream can
    recover a report ncurses never parsed. The worst case becomes a flicker
    instead of a control that has to be clicked twice to come back.
    """
    handle = getattr(button, "_press_recovery", None)
    if handle is not None:
        with contextlib.suppress(Exception):
            button.after_cancel(handle)

    def recover() -> None:
        button._press_recovery = None
        if button._pressed and button.winfo_exists():
            button._pressed = False
            button._redraw()

    button._press_recovery = button.after(PRESS_RECOVERY_MS, recover)


def _disarm_press_recovery(button: Any) -> None:
    """Drop the safety timer once the release has actually arrived."""
    handle = getattr(button, "_press_recovery", None)
    if handle is not None:
        button._press_recovery = None
        with contextlib.suppress(Exception):
            button.after_cancel(handle)


def _cancel_repeat(widget: Misc) -> None:
    """Stop whatever is auto-repeating: Tk's ``tk::CancelRepeat``."""
    handle = widget.tk.repeat
    if handle is not None:
        widget.tk.repeat = None
        with contextlib.suppress(Exception):
            widget.after_cancel(handle)


def _repeat_after(widget: Misc, ms: int, func: Callable[..., Any], *args: Any) -> None:
    """Schedule the next step of an auto-repeat, in place of any pending one."""
    _cancel_repeat(widget)

    def step() -> None:
        widget.tk.repeat = None
        if widget.winfo_exists():
            func(*args)

    widget.tk.repeat = widget.after(ms, step)


#: ``ttk::Repeatedly``'s timing, ttk/utils.tcl's ``Repeat(delay)`` and
#: ``Repeat(interval)``: fixed, where the classic widgets' are options.
_TTK_REPEAT_DELAY = 300
_TTK_REPEAT_INTERVAL = 100


def _ttk_repeatedly(widget: Misc, func: Callable[..., Any], *args: Any) -> None:
    """``ttk::Repeatedly``: ``func`` now, again after 300 ms, then every
    100 ms until :func:`_cancel_repeat` - ``ttk::CancelRepeat`` - stops it.
    Each repeat is scheduled before it runs, as ``ttk::Repeat`` does."""

    def again() -> None:
        _repeat_after(widget, _TTK_REPEAT_INTERVAL, again)
        func(*args)

    _repeat_after(widget, _TTK_REPEAT_DELAY, again)
    func(*args)


def _repeat_option(widget: Any, name: str) -> int:
    """``repeatdelay`` or ``repeatinterval``, as milliseconds; 0 for none.

    A ttk widget has neither, in Tk: its repeat is ``ttk::Repeatedly``, with
    fixed timing - :func:`_ttk_repeatedly` - and a ttk button has none.
    """
    if _is_ttk(widget) or name not in widget._options:
        return 0
    return _as_int(widget._options[name], 0)


def _button_release(event: Event) -> None:
    """Invoke the button, unless the pointer left it first.

    Tk invokes on release rather than press so that pressing and moving away
    is a way to change your mind, which is what every other toolkit does too.
    The release reaches this widget wherever the pointer ended up, because of
    the implicit grab, so whether it counts has to be decided here.
    """
    button = event.widget
    _disarm_press_recovery(button)
    _cancel_repeat(button)
    if not button._pressed:
        return
    button._pressed = False
    button._pointer_away = False
    button._redraw()
    # tk::ButtonUp: a press that has auto-repeated has invoked already.
    if not button._disabled and _within(button, event) and not button._repeated:
        button.invoke()


def _within(widget: Misc, event: Event) -> bool:
    """True if an event's position lies inside a widget."""
    return _point_within(widget, event.x_root, event.y_root)


def _point_within(widget: Misc, x: int, y: int) -> bool:
    """True if the screen cell (x, y) lies inside a widget."""
    left, top = widget.winfo_rootx(), widget.winfo_rooty()
    return (
        left <= x < left + widget.winfo_width()
        and top <= y < top + widget.winfo_height()
    )


def _button_key(event: Event) -> str:
    """Invoke the button from the keyboard.

    Bound to Return and space on a Button and to space alone on a
    Checkbutton, so which keys reach here is the caller's choice.

    Returns ``"break"`` so the key does not also reach whatever else is bound
    to it - a Return that both presses the button and submits a dialog would
    do the same thing twice.
    """
    button = event.widget
    if not button._disabled:
        button.invoke()
    return "break"


def _button_refresh(event: Event) -> None:
    """Repaint after the focus moved in or out."""
    event.widget._redraw()


def _button_enter(event: Event) -> None:
    """The pointer arrives: the button goes active, in its ``overrelief``.

    Tk's ``tk::ButtonEnter`` and ``tk::CheckEnter``, their X11 versions, in
    ``button.tcl``. ``configure`` rather than a flag, as there, so ``cget``
    reads the relief that is showing. Tk sinks a button re-entered while held;
    a press here is drawn by markers and not by a relief, so a held one is
    drawn pressed again and keeps the relief it has.
    """
    button = event.widget
    if button._disabled:
        return
    if button._pressed:
        button._pointer_inside = True
        button._pointer_away = False
    button.configure(state=ACTIVE)
    over = str(button.cget("overrelief"))
    if over and not button._pressed:
        button._entered_relief = (str(button.cget("relief")), over)
        button.configure(relief=over)


def _button_leave(event: Event) -> None:
    """The pointer goes: back to normal, and the relief it entered with.

    Tk's ``tk::ButtonLeave``: the relief goes back only if it is still the
    one the entry put there, so a program that changed it meanwhile keeps
    its change.
    """
    button = event.widget
    if button._pressed:
        # Drawn released while the pointer is off it: letting go here will
        # not press it.
        button._pointer_inside = False
        button._pointer_away = True
    if not button._disabled:
        button.configure(state=NORMAL)
    button._redraw()
    saved, button._entered_relief = button._entered_relief, None
    if saved is not None and saved[1] == str(button.cget("relief")):
        button.configure(relief=saved[0])


class _ChoiceWidget(_TextWidget):
    """Shared by the two widgets whose state lives in a variable.

    Checkbutton and Radiobutton draw the same way - a small indicator, a
    space, then a label - and keep the same relationship with their
    variable: neither holds any state of its own, both repaint when the
    variable is written, and both let two widgets over one variable agree
    without either knowing the other exists. What separates them is what the
    indicator means and what pressing one does, which is all a subclass has
    to say.
    """

    #: The indicator in each state, unfocused and focused. Focus changes the
    #: brackets rather than the colour: the width is the same either way, so
    #: nothing moves under the hand when the focus arrives, and it survives a
    #: terminal with no colour - the same reason Button draws markers.
    _INDICATORS: ClassVar[dict[str, tuple[str, str]]] = {}

    #: Cells the indicator and the space after it take from the text.
    _INDICATOR_WIDTH = 4

    _widget_options: ClassVar[dict[str, Any]] = {
        "bitmap": "",
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        **_STATE_COLOUR_OPTIONS,
        # The indicator's background, and an indicatorless button's while it
        # is on. "" here, Tk's #ffffff: the indicator as it was drawn before.
        "selectcolor": "",
        "command": None,
        "indicatoron": True,
        # An indicatorless button's relief while off, and any button's while
        # the pointer is over it. TkCurses-gm66.5.
        "offrelief": "raised",
        "overrelief": "",
        # Drawn in place of "image" while the button is on, or in its third
        # state; nothing without an "image". TkCurses-gm66.10.
        "selectimage": "",
        "takefocus": True,
        "tristateimage": "",
        "variable": None,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``variable``, ``command``, ``indicatoron``, whatever else
                the subclass declares, plus everything a Label takes.
        """
        self._pressed = False
        self._pointer_away = False
        self._entered_relief: tuple[str, str] | None = None
        self._repeated = 0
        self._pointer_inside = False
        self._value_trace: tuple[Variable, str] | None = None
        super().__init__(master, cnf, name=name, **kw)
        if self._options["variable"] is None:
            self._options["variable"] = self._make_variable()
        self._follow_value()
        self._install_class_bindings()

    def _make_variable(self) -> Variable:
        """The variable to use when the caller named none."""
        raise NotImplementedError

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register the default behaviour for every widget of this class.

        The same handlers Button uses, less Return: Tk's checkbutton and
        radiobutton answer the space bar and not Return, so that Return
        still reaches a dialog's default button from wherever the focus is.
        """
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Button-1>", _button_press)
        bind(name, "<ButtonRelease-1>", _button_release)
        bind(name, "<Key-space>", _button_key)
        bind(name, "<FocusIn>", _button_refresh)
        bind(name, "<FocusOut>", _button_refresh)
        if not _is_ttk(self):
            bind(name, "<Enter>", _button_enter)
            bind(name, "<Leave>", _button_leave)

    # --------------------------------------------------------------- options

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, following a new variable if one was named."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if "variable" in given:
            self._follow_value()
            self._redraw()
        return result

    config = configure

    def _follow_value(self) -> None:
        """Track the ``variable``, dropping any previous one.

        The old trace has to go for the same reason a Label's does: a widget
        still answering the variable it used to show would repaint itself
        whenever something unrelated wrote to it.
        """
        if self._value_trace is not None:
            previous, handle = self._value_trace
            previous._unwatch(handle)
            self._value_trace = None
        variable = self._options["variable"]
        if variable is None:
            return
        # A Checkbutton's offvalue, and "" for a Radiobutton: Tk 9.0.2's.
        _seed_variable(self, variable, self._options.get("offvalue", ""))
        handle = variable._watch(self._value_written)
        self._value_trace = (variable, handle)

    def _value_written(self) -> None:
        """The variable was written: show what it holds now."""
        self._redraw()

    def _drawn_image(self) -> Image | None:
        """``selectimage`` while on, ``tristateimage`` in the third state.

        Measured on Tk 9.0.2: neither does anything without an ``image``, and
        neither changes the size, which ``image`` alone decides.
        """
        image = self._image()
        if image is None:
            return None
        option = {"on": "selectimage", "tristate": "tristateimage"}.get(
            self._indicator_state, ""
        )
        name = str(self._options[option]) if option else ""
        return self.tk.images.get(name, image) if name else image

    @property
    def _indicator_on(self) -> bool:
        """True while the indicator is drawn, false while it is not."""
        try:
            return self.getboolean(self._options["indicatoron"])
        except TclError:
            return True

    # ----------------------------------------------------------------- value

    @property
    def _indicator_state(self) -> str:
        """Which state the variable puts this widget in. Subclasses decide."""
        raise NotImplementedError

    def _value(self) -> Any:
        """What the variable holds, or None if there is no variable left."""
        variable = self._options["variable"]
        return None if variable is None else variable.get()

    def _write(self, value: Any) -> None:
        """Put a value in the variable, if there still is one."""
        variable = self._options["variable"]
        if variable is not None:
            variable.set(value)

    # ------------------------------------------------------------ behaviour

    def _activate(self) -> None:
        """What pressing this widget does to its variable."""
        raise NotImplementedError

    def invoke(self) -> Any:
        """Do what a click does, and run the command.

        Returns whatever the command returns. Does nothing while disabled -
        the guard belongs here rather than in every caller, and ``invoke`` is
        how a key binding, a test and a click all reach one path.
        """
        if self._disabled:
            return None
        self._activate()
        command = self._options["command"]
        return None if command is None else command()

    def flash(self) -> None:
        """Blink the indicator, as tkinter's does.

        Drawn twice through the after-queue rather than with a sleep: a
        widget that stopped the event loop to flash would also stop whatever
        it was flashing about.
        """
        if self._disabled:
            return
        self._pressed = not self._pressed
        self._redraw()
        self.after(80, self._end_flash)

    def _end_flash(self) -> None:
        """Put the indicator back the way it was after a flash."""
        self._pressed = False
        self._redraw()

    # ------------------------------------------------------------- painting

    def _apply_requested_size(self) -> None:
        """Ask for the text's room plus the indicator to the left of it."""
        super()._apply_requested_size()
        if self._indicator_on:
            self._request_size(
                self._requested.width + self._INDICATOR_WIDTH,
                self._requested.height,
            )

    def _text_area(self) -> Rect:
        """Where the text goes: what is left once the indicator has its cells."""
        area = super()._text_area()
        if not self._indicator_on:
            return area
        return Rect(
            area.x + self._INDICATOR_WIDTH,
            area.y,
            max(0, area.width - self._INDICATOR_WIDTH),
            area.height,
        )

    def _text_attribute(self) -> int:
        """Attributes on the text, including the state of an indicatorless one.

        Without an indicator there is nothing else to show it with, so the
        text carries both: reversed while the widget is on, underlined while
        it has the focus.
        """
        attribute = super()._text_attribute()
        if self._indicator_on:
            return attribute
        if self._indicator_state == "on" and not self._selected_colour():
            attribute |= _curses.A_REVERSE
        if self.focus_get() is self:
            attribute |= _curses.A_UNDERLINE
        return attribute

    def _selected_colour(self) -> bool:
        """True if ``selectcolor`` is given and the terminal can show it."""
        return bool(self._options.get("selectcolor")) and self.tk.colors is not None

    def _background_attribute(self) -> int:
        """An indicatorless button that is on takes ``selectcolor`` as its
        background, "in place of background or activeBackground", as Tk's
        manual has it. With an indicator, ``selectcolor`` is the indicator's.
        """
        attribute = super()._background_attribute()
        if (
            self._indicator_on
            or self._indicator_state != "on"
            or not self._selected_colour()
        ):
            return attribute
        active = self._state_colours(self._shown_state())
        foreground = active[0] if active is not None else ""
        return self._coloured(attribute, foreground, self._options["selectcolor"])

    @property
    def _bordered(self) -> bool:
        """An indicatorless button's border is drawn in its shown relief.

        That is sunken while it is on, so a border one cell wide is always
        there to draw, whatever ``relief`` and ``offrelief`` say; one with an
        indicator follows Tk's rule for its own relief.
        """
        if self._indicator_on or _is_ttk(self):
            return super()._bordered
        return _draws_border(
            {"relief": SUNKEN, "borderwidth": self._options.get("borderwidth", 0)}
        )

    def _border_style(self) -> BorderStyle:
        """The relief an indicatorless button is drawn in, which is not its own.

        Tk's ``TkpDisplayButton``, in ``unix/tkUnixButton.c``: sunken while
        on; otherwise ``offrelief``, unless the relief is the ``overrelief``,
        which is how it tells that the pointer is over it - the ``<Enter>``
        binding has copied one into the other. With an indicator, the relief
        is the widget's own. TkCurses-gm66.5.
        """
        relief = self._drawn_relief()
        if not self._indicator_on and not _is_ttk(self):
            if self._indicator_state == "on":
                relief = SUNKEN
            elif relief != str(self._options["overrelief"]):
                relief = str(self._options["offrelief"])
        return style_for_relief(relief)

    def _redraw(self) -> None:
        """Paint the widget, then the indicator to the left of the text."""
        super()._redraw()
        self._draw_indicator()

    def _draw_indicator(self) -> None:
        """Draw the indicator, on the row the text's first line sits on."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        place = self._indicator_place()
        if place is None:
            return
        column, row = place
        focused = self.focus_get() is self
        mark = self._INDICATORS[self._indicator_state][1 if focused else 0]
        attribute = self._background_attribute() | self._text_attribute()
        if self._selected_colour():
            attribute = self._coloured(attribute, "", self._options["selectcolor"])
        if self._held_down() and self._state_colours("active") is None:
            attribute |= _curses.A_REVERSE
        with contextlib.suppress(_curses.error):
            self._write_line(
                CursesDispatcher.get(), window, row, column, mark, attribute
            )

    def _indicator_place(self) -> tuple[int, int] | None:
        """Where the indicator's first cell is, as ``(column, row)``, if drawn.

        On the row the text's first line sits on. Shared by the painting and
        by ttk's ``identify``, which must name the cells that were drawn.
        """
        if not self._indicator_on:
            return None
        # The whole area, not the text's - _text_area() has already handed
        # the indicator's cells away and would put it on top of the text.
        area = super()._text_area()
        if area.is_empty or area.width < self._INDICATOR_WIDTH:
            return None
        _, block_height = measure(self._lines())
        _, down = parse_anchor(str(self._options["anchor"]))
        return (area.x, area.y + int((area.height - block_height) * down))


class Checkbutton(_ChoiceWidget):
    """A box that is ticked or not, and a variable that says which.

    The widget keeps no state of its own: the tick comes from comparing its
    ``variable`` against ``onvalue`` every time it paints. That is what makes
    two checkbuttons over one variable show the same tick, and what makes
    setting the variable from code move both of them. A checkbutton made
    without a variable is given one, as tkinter's is.

    Tk's third state is drawn too. A variable holding ``tristatevalue`` - the
    "some of the selected files are read-only" case - shows ``[-]``, and a
    click from there turns the button on.

    Sample output:
        choices = [tk.StringVar(value=v) for v in ("0", "1", "")]
        for text, variable in zip(("Off", "On", "Mixed"), choices):
            tk.Checkbutton(root, text=text, variable=variable).pack(anchor="w")

    Options:
        command: Called with no arguments each time the button is toggled.
        indicatoron: Whether the box is drawn. Without it the text reverses
            while the button is on, which is how a checkbutton is used as a
            toggle in a toolbar.
        offrelief: The relief while the button is off, when ``indicatoron`` is
            false.
        offvalue: The variable's value while the button is off; 0 by default.
        onvalue: The variable's value while the button is on; 1 by default.
        overrelief: The relief while the mouse is over the button.
        selectcolor: The colour of the box's tick, or of the whole button
            while it is on when there is no box.
        selectimage: The image shown while the button is on, in place of
            ``image``.
        tristateimage: The image shown in the third state.
        tristatevalue: The variable's value in the third state; ``""`` by
            default.
        variable: The variable holding the button's value.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeforeground``, ``anchor``, ``background``,
    ``bitmap``, ``borderwidth``, ``compound``,
    ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``image``, ``justify``,
    ``padx``, ``pady``, ``relief``, ``state``, ``takefocus``, ``text``,
    ``textvariable``, ``underline``, ``width``, ``wraplength``.

    Differences from tkinter:
        ``highlightbackground``, ``highlightcolor`` and
        ``highlightthickness`` are accepted and draw
        nothing: the focus is shown by markers instead. So is ``cursor``: the
        mouse pointer belongs to the terminal.

    Sample output (indicatoron):
        for name in ("Bold", "Italic"):
            button = tk.Checkbutton(root, text=name, indicatoron=0)
            button.pack(side="left", padx=1)
        button.select()

    Sample output (offrelief):
        for relief in ("raised", "groove"):
            tk.Checkbutton(root, text=relief, indicatoron=0, borderwidth=1,
                           offrelief=relief).pack(side="left", padx=1)

    Sample output (selectcolor):
        button = tk.Checkbutton(root, text="Ticked", selectcolor="green")
        button.pack()
        button.select()

    Sample output (selectimage):
        off = tk.PhotoImage(width=4, height=2)
        off.put("grey", to=(0, 0, 4, 2))
        on = tk.PhotoImage(width=4, height=2)
        on.put("green", to=(0, 0, 4, 2))
        for state in ("off", "on"):
            button = tk.Checkbutton(root, text=state, image=off, selectimage=on,
                                    compound="left")
            button.pack(side="left", padx=1)
        button.select()

    Sample output (tristateimage):
        off = tk.PhotoImage(width=4, height=2)
        off.put("grey", to=(0, 0, 4, 2))
        mixed = tk.PhotoImage(width=4, height=2)
        mixed.put("yellow", to=(0, 0, 4, 2))
        state = tk.StringVar(value="")
        tk.Checkbutton(root, text="mixed", variable=state, image=off,
                       tristateimage=mixed, compound="left").pack()
    """

    _INDICATORS: ClassVar[dict[str, tuple[str, str]]] = {
        "on": ("[x]", "<x>"),
        "off": ("[ ]", "< >"),
        "tristate": ("[-]", "<->"),
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        "offvalue": 0,
        "onvalue": 1,
        "tristatevalue": "",
    }

    def _make_variable(self) -> Variable:
        """A variable of this checkbutton's own, starting at ``offvalue``.

        Plain Variable rather than IntVar: what it has to hold is whatever
        ``onvalue`` and ``offvalue`` are, and those are only integers by
        default. Each checkbutton gets its own, because two unrelated boxes
        that happened to be made without variables must not move together.
        """
        return Variable(master=self, value=self._options["offvalue"])

    @property
    def _indicator_state(self) -> str:
        """Which of the three states the variable puts this button in.

        Tk's order, which matters: on, then the third state, then off as the
        fallback. So an empty variable with the default ``tristatevalue`` of
        ``""`` shows ``[-]`` rather than ``[ ]``, exactly as Tk's does - a
        surprise worth keeping, because code that means "off" should say so.
        """
        value = self._value()
        if _same_value(value, self._options["onvalue"]):
            return "on"
        if _same_value(value, self._options["tristatevalue"]):
            return "tristate"
        return "off"

    def select(self) -> None:
        """Turn the button on by writing ``onvalue`` to its variable."""
        self._write(self._options["onvalue"])

    def deselect(self) -> None:
        """Turn it off by writing ``offvalue``."""
        self._write(self._options["offvalue"])

    def toggle(self) -> None:
        """Flip the button. From the third state it turns on, as Tk does."""
        if self._indicator_state == "on":
            self.deselect()
        else:
            self.select()

    _activate = toggle


class Radiobutton(_ChoiceWidget):
    """One of a set of choices, of which the variable names the one in force.

    A radiobutton is on when its ``variable`` equals its ``value``, so a
    group is not a container or a list - it is however many radiobuttons
    happen to share a variable. Nothing has to be told which buttons belong
    together, and nothing has to turn the others off: they all repaint from
    the same variable and only one of them can match it.

    A radiobutton made without a variable joins Tk's default group, named
    ``selectedButton``, along with every other one in the same application
    that did the same - so two sets of choices both left without variables
    fight over one value.

    Sample output:
        size = tk.StringVar(value="medium")
        for name in ("small", "medium", "large"):
            tk.Radiobutton(root, text=name, value=name, variable=size).pack(
                anchor="w"
            )

    Options:
        command: Called with no arguments when the button is selected.
        indicatoron: Whether the round indicator is drawn. Without it the text
            reverses while the button is on.
        offrelief: The relief while the button is off, when ``indicatoron`` is
            false.
        overrelief: The relief while the mouse is over the button.
        selectcolor: The colour of the indicator's dot, or of the whole button
            while it is on when there is no indicator.
        selectimage: The image shown while the button is on.
        tristateimage: The image shown in the third state.
        tristatevalue: The variable's value that shows the third state.
        value: The variable's value while this button is the one chosen.
        variable: The variable shared by the group.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeforeground``, ``anchor``, ``background``,
    ``bitmap``, ``borderwidth``, ``compound``,
    ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``image``, ``justify``,
    ``padx``, ``pady``, ``relief``, ``state``, ``takefocus``, ``text``,
    ``textvariable``, ``underline``, ``width``, ``wraplength``.

    Differences from tkinter:
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.

    Sample output (indicatoron):
        view = tk.StringVar(value="List")
        for name in ("List", "Icons"):
            tk.Radiobutton(root, text=name, value=name, variable=view,
                           indicatoron=0).pack(side="left", padx=1)

    Sample output (offrelief):
        view = tk.StringVar(value="")
        for relief in ("raised", "groove"):
            tk.Radiobutton(root, text=relief, value=relief, variable=view,
                           indicatoron=0, borderwidth=1,
                           offrelief=relief).pack(side="left", padx=1)

    Sample output (selectcolor):
        choice = tk.StringVar(value="a")
        tk.Radiobutton(root, text="Chosen", value="a", variable=choice,
                       selectcolor="green").pack()

    Sample output (selectimage):
        off = tk.PhotoImage(width=4, height=2)
        off.put("grey", to=(0, 0, 4, 2))
        on = tk.PhotoImage(width=4, height=2)
        on.put("green", to=(0, 0, 4, 2))
        choice = tk.StringVar(value="on")
        for name in ("off", "on"):
            tk.Radiobutton(root, text=name, value=name, variable=choice,
                           image=off, selectimage=on,
                           compound="left").pack(side="left", padx=1)

    Sample output (tristateimage):
        off = tk.PhotoImage(width=4, height=2)
        off.put("grey", to=(0, 0, 4, 2))
        mixed = tk.PhotoImage(width=4, height=2)
        mixed.put("yellow", to=(0, 0, 4, 2))
        choice = tk.StringVar(value="")
        tk.Radiobutton(root, text="mixed", value="a", variable=choice,
                       image=off, tristateimage=mixed,
                       compound="left").pack()
    """

    _INDICATORS: ClassVar[dict[str, tuple[str, str]]] = {
        "on": ("(•)", "<•>"),
        "off": ("( )", "< >"),
        "tristate": ("(-)", "<->"),
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        # The value that shows the third state. TkCurses-gm66.10.
        "tristatevalue": "",
        "value": "",
    }

    #: The group a radiobutton joins when the caller named no variable.
    _DEFAULT_GROUP = "selectedButton"

    def _make_variable(self) -> Variable:
        """Tk's shared default group, one Variable per application.

        Owned by the application rather than made fresh for each button. A
        Variable forgets its value when its last reference goes, and a group
        whose only owners are its own buttons would be at the mercy of which
        of them outlived the others.
        """
        shared = self.tk.shared_variables.get(self._DEFAULT_GROUP)
        if shared is None:
            shared = Variable(master=self, name=self._DEFAULT_GROUP)
            self.tk.shared_variables[self._DEFAULT_GROUP] = shared
        return shared

    @property
    def _indicator_state(self) -> str:
        """On when the variable holds this button's ``value``, in the third
        state when it holds ``tristatevalue``, and off otherwise.

        Tk's order, as a Checkbutton's. Seen on Tk 9.0.2's screen: an empty
        variable, with the default ``tristatevalue`` of ``""``, draws every
        button of the group greyed and set until one is chosen - the
        well-known look of radiobuttons over a fresh ``StringVar()``.
        """
        value = self._value()
        if _same_value(value, self._options["value"]):
            return "on"
        if _same_value(value, self._options["tristatevalue"]):
            return "tristate"
        return "off"

    def select(self) -> None:
        """Choose this button by writing its ``value`` to the variable."""
        self._write(self._options["value"])

    def deselect(self) -> None:
        """Leave the group with nothing chosen.

        Writes an empty value rather than this button's, which is what Tk
        does: there is no other way to say "none of them" through a variable
        that names the choice in force.
        """
        self._write("")

    _activate = select


def _same_value(left: Any, right: Any) -> bool:
    """True if two option values are the same value as Tcl would see them.

    Tcl has one type, so a StringVar holding ``"1"`` and an ``onvalue`` of
    the integer 1 are the same thing there. Compared by value first, so that
    1 and 1.0 match, and then as text, so that 1 and "1" do.
    """
    if left is None or right is None:
        return left is right
    with contextlib.suppress(TypeError):
        if left == right:
            return True
    return str(left) == str(right)


class Entry(_Drawable, XView):
    """A one-line text field.

    Typing, the arrow keys, Home and End, selection with the shifted keys or
    the mouse, and cut, copy and paste all work as they do in Tk. A
    ``textvariable`` is kept in step both ways.

    ``state`` has three values rather than two. ``readonly`` shows the text
    and lets it be selected and copied but refuses every edit, which is what
    a field displaying a computed value wants; ``disabled`` refuses the focus
    as well.

    Sample output:
        entry = tk.Entry(root, width=24)
        entry.insert(0, "Some text to edit")
        entry.pack()

    Options:
        disabledbackground: The background while ``state`` is ``disabled``.
        invalidcommand: Called when ``validatecommand`` refuses a change.
        readonlybackground: The background while ``state`` is ``readonly``.
        show: A character to show in place of each one typed, for a password:
            ``show="*"``.
        validate: When ``validatecommand`` is asked: ``none``, ``focus``,
            ``focusin``, ``focusout``, ``key`` or ``all``.
        validatecommand: Asked whether a change may be made; returns true to
            allow it. As in tkinter, a name :meth:`~Misc.register` made with
            Tk's percent codes - ``(root.register(check), "%P")`` - is called
            with each code substituted: ``%d`` 1 for an insert, 0 for a
            delete, -1 otherwise; ``%i`` the index; ``%P`` the text if the
            change is allowed; ``%s`` the text before it; ``%S`` the text
            inserted or deleted; ``%v`` the ``validate`` mode; ``%V`` what
            asked - ``key``, ``focusin``, ``focusout`` or ``forced``; ``%W``
            the entry. A Python callable may be given instead.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``disabledforeground``,
    ``exportselection``, ``font``, ``foreground``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``insertbackground``,
    ``insertborderwidth``, ``insertofftime``, ``insertontime``,
    ``insertwidth``, ``justify``, ``placeholder``,
    ``placeholderforeground``, ``relief``, ``selectbackground``,
    ``selectborderwidth``, ``selectforeground``, ``state``, ``takefocus``,
    ``textvariable``, ``width``, ``xscrollcommand``.

    Differences from tkinter:
        The insertion cursor is the terminal's own, so ``insertbackground``,
        ``insertborderwidth``, ``insertofftime``, ``insertontime`` and
        ``insertwidth`` draw nothing, and nor does ``selectborderwidth``. It
        takes a cell where Tk's is a line between two, so while the field has
        the focus a right-justified or centred text keeps one cell free for it
        at the right. ``highlightbackground``, ``highlightcolor`` and
        ``highlightthickness`` are accepted and draw nothing: the focus is shown
        by markers instead. So is ``cursor``: the mouse pointer belongs to the
        terminal.

        A ``validatecommand`` that edits the entry while it is being asked
        about a write to the ``textvariable`` - the ``forced`` condition -
        keeps both the write and its own edit, and the variable holds the
        result. Tk discards both and leaves the entry showing its old text
        while the variable holds the new one. Validation is turned off either
        way.

    TkCurses extension:
        A ``validatecommand`` may be a Python callable rather than a
        registered name. It is given the text the change would make, ``%P``,
        if it takes an argument, and nothing if it does not - which is how
        tkinter calls one.

    Sample output (disabledbackground, readonlybackground):
        for state, colour in (("disabled", "red"), ("readonly", "blue")):
            entry = tk.Entry(root, width=12)
            entry.insert(0, state)
            entry.configure(state=state, disabledbackground=colour,
                            readonlybackground=colour)
            entry.pack(side="left", padx=1)

    Sample output (show):
        password = tk.Entry(root, show="*")
        password.insert(0, "secret")
        password.pack()
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"padx", "pady"})

    #: Tk's validation pair carries short spellings on the classic Entry, and
    #: they are the ones tkinter's own documentation uses - so a program copied
    #: from it failed here on its first line with ``unknown option "-vcmd"``.
    #: Measured: ttk.Entry has validatecommand and refuses vcmd, which is why
    #: these live on this class rather than in the module table.
    _option_synonyms: ClassVar[dict[str, str]] = {
        **_OPTION_ALIASES,
        "vcmd": "validatecommand",
        "invcmd": "invalidcommand",
    }

    _STATE_COLOURS: ClassVar[dict[str, tuple[str | None, str | None]]] = {
        "disabled": ("disabledforeground", "disabledbackground"),
        "readonly": (None, "readonlybackground"),
    }

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "state": _choices("state", "disabled", "normal", "readonly"),
        "width": _tcl_integer,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        **_INSERT_CURSOR_OPTIONS,
        **_SELECTION_OPTIONS,
        # The disabled and readonly looks; see _STATE_COLOURS. Tk's defaults
        # are real colours, these are "": dimmed, and as normal.
        "disabledbackground": "",
        "disabledforeground": "",
        "readonlybackground": "",
        # tkinter reports 1, not True: the value is what cget answers.
        "exportselection": 1,
        # Tk 9.0's ghost text - TkCurses-xe9.3. On the CLASSIC entry as well as
        # the themed ones: measured, all four of tk.Entry, ttk.Entry,
        # ttk.Combobox and ttk.Spinbox carry both, as standard options.
        "placeholder": "",
        "placeholderforeground": "",
        "font": "",
        "justify": "left",
        "relief": "sunken",
        "show": "",
        "state": "normal",
        "takefocus": True,
        "textvariable": None,
        "validate": "none",
        "validatecommand": None,
        # The third of Tk's validation trio, and -xscrollcommand, both of which
        # this widget lacked: validatecommand could say what was valid and
        # nothing could say what to do when an edit was refused, and an entry
        # could not be attached to a scrollbar. TkCurses-ale.
        "invalidcommand": None,
        "xscrollcommand": None,
        "width": 20,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``width``, ``textvariable``, ``show``, ``state``,
                ``justify``, ``validate``, ``validatecommand``, and the
                standard options.
        """
        self._field = TextField()
        self._field.measure = self._shown_cells
        self._variable_trace: tuple[Variable, str] | None = None
        self._syncing = False
        # True while a validation callback is running, so an edit made from
        # inside one can be told apart from an ordinary edit. TkCurses-tvj.
        self._validating = False
        self._edited_while_validating = False
        # True between a press in the text and its release; see _entry_drag.
        self._dragging = False
        # What a drag extends by - "char", "word" after a double-click, "line"
        # after a triple - whether it has moved off the press, where the
        # pointer was last, and the pending autoscroll. TkCurses-svtr.
        self._select_mode = "char"
        self._moved = False
        self._drag_x = 0
        self._autoscan: str | None = None
        # The screen cell the terminal's cursor goes in; see _draw_cursor.
        self._insert_at: tuple[int, int] | None = None
        super().__init__(master, cnf, name=name, **kw)
        self._follow_variable()
        self._apply_requested_size()
        self._install_class_bindings()

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register the editing keys for every Entry in this application."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Any-Key>", _entry_key)
        bind(name, "<Button-1>", _entry_click)
        bind(name, "<Motion>", _entry_drag)
        bind(name, "<ButtonRelease-1>", _entry_release)
        bind(name, "<Double-Button-1>", _entry_double)
        bind(name, "<Triple-Button-1>", _entry_triple)
        if not _is_ttk(self):
            # ttk binds no Ctrl-click: there it is a plain click.
            bind(name, "<Control-Button-1>", _entry_control_click)
        for extend in _EXTEND_MODIFIERS:
            bind(name, f"<{extend}-Button-1>", _entry_shift_click)
            if not _is_ttk(self):
                # ttk binds neither; a doubled shift-click there is just one.
                bind(name, f"<Double-{extend}-Button-1>", _entry_double_shift)
                bind(name, f"<Triple-{extend}-Button-1>", _entry_triple_shift)
        bind(name, "<FocusIn>", _entry_focus_in)
        bind(name, "<FocusOut>", _entry_focus_out)
        bind(name, "<<TraverseIn>>", _entry_traverse_in)
        _bind_entry_clipboard(bind, name)
        _bind_entry_navigation(bind, name, themed=_is_ttk(self))

    # ---------------------------------------------------------------- state

    @property
    def _editable(self) -> bool:
        """True while the field accepts changes from the keyboard."""
        return str(self._options["state"]) == "normal"

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, following a new variable and repainting as needed."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if "textvariable" in given:
            self._follow_variable()
        if "exportselection" in given:
            # Both directions take effect at once, measured: turning it off
            # drops PRIMARY with the selection still in place, and turning it
            # on exports what is already selected without reselecting it.
            self._claim_primary()
        if "width" in given:
            self._apply_requested_size()
            self._invalidate_layout()
        self._redraw()
        return result

    config = configure

    def _apply_requested_size(self) -> None:
        """Ask for the field's width plus whatever the border and padding need."""
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        self._request_size(
            int(self._options["width"]) + 2 * int(self._options["padx"]) + edge,
            1 + 2 * int(self._options["pady"]) + edge,
        )

    # ----------------------------------------------------------- the variable

    def _follow_variable(self) -> None:
        """Track the ``textvariable``, dropping any previous one."""
        if self._variable_trace is not None:
            variable, handle = self._variable_trace
            variable._unwatch(handle)
            self._variable_trace = None
        variable = self._options["textvariable"]
        if variable is None:
            return
        _seed_variable(self, variable, self.get())
        handle = variable._watch(self._variable_changed)
        self._variable_trace = (variable, handle)
        self._variable_changed()

    def _variable_changed(self) -> None:
        """Take the variable's value, unless this widget is what changed it.

        Without the guard the two would chase each other: every keystroke
        writes the variable, whose trace writes the field, which resets the
        cursor the keystroke just moved.
        """
        if self._syncing:
            return
        variable = self._options["textvariable"]
        if variable is None:
            return
        previous = self._field.text
        self._field.text = str(variable.get())
        # Tk's "forced" condition. Measured: this fires when the variable is
        # written AND when one is first attached, at construction or by
        # configure(), which is why it lives here rather than in the trace
        # handler alone. TkCurses-3xb.
        self._validate_forced(previous)
        self._publish_view()
        self._redraw()

    def _publish(self) -> None:
        """Write the field's contents back to the variable, if there is one."""
        variable = self._options["textvariable"]
        if variable is None:
            return
        self._syncing = True
        try:
            variable.set(self._field.text)
        finally:
            self._syncing = False

    # ------------------------------------------------------------ public API

    def get(self) -> str:
        """The text in the field."""
        return self._field.text

    def insert(self, index: Any, string: str) -> None:
        """Insert ``string`` at ``index``, if the state and validator allow it.

        A programmatic edit is validated exactly as a keystroke is, and ignored
        outright when the entry is ``disabled`` or ``readonly``, as in Tk. An
        insert that would change nothing - an empty string - runs no callback.
        """
        # Both measured on real Tk, and this method once did neither: a digits-
        # only entry sent insert(0, "x") ended up holding "x", with no callback
        # to tell the program its validator had been bypassed. TkCurses-tvj.
        if not string:
            return
        where = self.index(index)
        text = self._field.text
        self._edit(
            lambda: self._field.insert(where, string),
            text[:where] + string + text[where:],
            action=1,
            index=where,
            changed=string,
        )

    def delete(self, first: Any, last: Any = None) -> None:
        """Delete from ``first`` up to but not including ``last``.

        Validated and state-gated like :meth:`insert`. A delete that would
        change nothing - an empty range, or a range starting past the end -
        runs no callback, as measured: ``delete(1, 1)`` and ``delete(5, 9)`` on
        a two-character entry leave the validator untouched.
        """
        start = self.index(first)
        end = start + 1 if last is None else self.index(last)
        text = self._field.text
        if start >= len(text) or end <= start:
            return
        self._edit(
            lambda: self._field.delete(start, end),
            text[:start] + text[end:],
            action=0,
            index=start,
            changed=text[start:end],
        )

    def icursor(self, index: Any) -> None:
        """Put the insertion cursor at ``index``, keeping any selection."""
        # Measured on Tk 9.0.2: a selection survives icursor. This dropped it
        # until TkCurses-elb, which mattered because ttk's own combobox pick
        # selects everything and then moves the cursor to the end.
        self._field.place_cursor(self.index(index))
        self._redraw()

    def index(self, index: Any) -> int:
        """Resolve one of Tk's index forms to a number.

        Understands integers, ``end``, ``insert``, ``anchor``, ``sel.first``,
        ``sel.last`` and ``@x`` for a screen column.

        Raises:
            TclError: If the form is not one Tk defines, or names a selection
                that does not exist.
        """
        if isinstance(index, int):
            return self._field.clamp(index)
        text = str(index)
        if text.isdigit() or (text.startswith("-") and text[1:].isdigit()):
            return self._field.clamp(int(text))
        if text in ("end", END):
            return len(self._field.text)
        if text in ("insert", INSERT):
            return self._field.cursor
        if text.startswith("@"):
            area = self._text_area()
            return self._field.index_at(int(text[1:]) - area.x - self._shift(area))
        selection = self._field.selection
        if text in ("sel.first", SEL_FIRST):
            if selection is None:
                raise TclError("selection isn't in widget " + str(self))
            return selection[0]
        if text in ("sel.last", SEL_LAST):
            if selection is None:
                raise TclError("selection isn't in widget " + str(self))
            return selection[1]
        if text in ("anchor", ANCHOR):
            return self._field.cursor
        raise TclError(f'bad entry index "{index}"')

    def _exports_selection(self) -> bool:
        """Whether this widget puts its selection on PRIMARY."""
        return bool(self._options["exportselection"])

    def _claim_primary(self) -> None:
        """Take ownership of PRIMARY, or give it up, as the option says.

        Ownership is claimed when a selection is made rather than held from
        construction: in Tk, creating a second entry does not take PRIMARY from
        the first, and the widget that selected most recently owns it.

        The contents are not copied. The widget registers a handler and
        :meth:`~tkcurses._core.clipboard.Selections.resolve` asks it at the
        moment PRIMARY is read, which is X11's design and what tkinter exposes
        as ``selection_handle``. Three of the four behaviours measured on
        Tcl/Tk 9.0.2 then need no bookkeeping: clearing the selection makes
        PRIMARY stop existing, selecting again makes it exist, and an edit that
        moves the selection needs noticing by nobody.
        """
        selections = self.tk.selections
        if self._exports_selection():
            selections.own(self, PRIMARY, lost=self._lost_primary)
            selections.handle(self, self._primary_selection, PRIMARY)
        elif selections.owner(PRIMARY) is self:
            # Measured: turning -exportselection off drops PRIMARY at once,
            # even though the widget's own selection is untouched.
            selections.disown(self)

    def _lost_primary(self) -> None:
        """Another widget took PRIMARY: drop this one's selection, as Tk does.

        Measured on Tk 9.0.2 - select in one entry, then in another, and the
        first is no longer selected. Without this both stayed highlighted,
        which a person running UAT 43 reported. TkCurses-lw2.
        """
        self._field.select_clear()
        self._redraw()

    def _primary_selection(self, *_args: Any) -> str:
        """The selected text, for whoever is reading PRIMARY.

        Raises:
            TclError: If nothing is selected. A widget owning PRIMARY with an
                empty selection has to read as "doesn't exist" rather than as
                the empty string: tkinter raises, and a caller needs to tell
                "nothing is selected" from "an empty string was selected".
        """
        selection = self._field.selection
        if selection is None:
            raise TclError(f"{PRIMARY} selection doesn't exist or form unknown")
        first, last = selection
        # What is shown, not what is held: a field with ``show="*"`` hands
        # out asterisks, as Tk's EntryFetchSelection does and as <<Copy>>
        # here already did - a password selected by a stray double-click
        # would otherwise be on every desktop application's PRIMARY.
        return str(self._displayed()[first:last])

    def selection_range(self, start: Any, end: Any) -> None:
        """Select from ``start`` to ``end``, leaving the anchor where it is.

        A range given backwards or empty clears the selection, as Tk's does.
        """
        # The field's own select_range does the work; TkCurses-bfy.
        self._field.select_range(self.index(start), self.index(end))
        self._claim_primary()
        self._redraw()

    select_range = selection_range

    def selection_clear(self, **kw: Any) -> None:  # noqa: ARG002 - Misc signature
        """Drop the selection; the anchor stays, as Tk's does."""
        self._field.select_clear()
        self._redraw()

    select_clear = selection_clear

    def selection_present(self) -> bool:
        """True if anything is selected."""
        return self._field.selection is not None

    def _has_copyable_selection(self) -> bool:
        return self._field.selection is not None

    select_present = selection_present

    # The three below are Tk's entry selection commands as measured on 9.0.2,
    # which this followed loosely until TkCurses-bfy: selection_from cleared
    # the selection and moved the cursor, selection_to moved the cursor, and
    # selection_adjust was selection_to under another name. None of them
    # moves the cursor in Tk.

    def selection_from(self, index: Any) -> None:
        """Set the anchor for the next :meth:`selection_to`, and only that."""
        self._field.select_from(self.index(index))

    select_from = selection_from

    def selection_to(self, index: Any) -> None:
        """Select from the anchor to ``index``."""
        self._field.select_to(self.index(index))
        self._claim_primary()
        self._redraw()

    select_to = selection_to

    def selection_adjust(self, index: Any) -> None:
        """Move the nearer end of the selection to ``index``.

        See :meth:`TextField.select_adjust` for which end is nearer.
        """
        self._field.select_adjust(self.index(index))
        self._claim_primary()
        self._redraw()

    select_adjust = selection_adjust

    def scan_mark(self, x: Any) -> None:
        """Remember ``x`` and the view, for a :meth:`scan_dragto` to come."""
        self._scan_mark = (int(x), self._field.view)

    def scan_dragto(self, x: Any) -> None:
        """Move the view ten times as far as ``x`` is from the mark.

        ``EntryScanTo`` in Tk's ``tkEntry.c``: a character a cell, and at
        either end the mark moves with the pointer, so dragging back moves
        the view at once.
        """
        x = int(x)
        mark_x, mark_index = getattr(self, "_scan_mark", (x, self._field.view))
        last = len(self._field.text) - 1
        first = mark_index - 10 * (x - mark_x)
        if first >= last:
            first = mark_index = max(0, last)
            mark_x = x
        if first < 0:
            first = mark_index = 0
            mark_x = x
        if first != self._field.view:
            self.xview(first)
            if self._field.view != first:
                mark_index, mark_x = self._field.view, x
        self._scan_mark = (mark_x, mark_index)

    def xview(self, *args: Any) -> Any:
        """Report or move the view, as Tk's entry does.

        With no arguments it answers the pair of fractions a scrollbar wants:
        where the view begins and ends, over the width of the text. With
        ``("moveto", fraction)`` or ``("scroll", count, "units"|"pages")`` it is
        a scrollbar driving the entry, and an index scrolls that character to
        the left edge.

        Only the view moves: the insertion cursor stays where it is, and a
        selection survives. A unit is one character and a page is the width
        less two, at least one; the view stops with the last character at the
        right edge, and a text shorter than the field never scrolls.

        Differences from tkinter:
            Tk measures the fractions and a page in pixels; here they are in
            cells, which is the same thing for most text. A CJK ideograph or
            most emoji takes two cells, so a page of them is half as many
            characters.
        """
        # It used to return the first visible character as an int, so
        # -xscrollcommand could not be honoured; tkinter's Entry answers
        # fractions - measured, xview() on a 10-wide entry holding 43 characters
        # is (0.0, 0.023255813953488372). TkCurses-ale.
        #
        # It also used to move the insertion cursor and so drop the selection.
        # Measured on Tk 9.0.2, an entry 5 wide holding a-z, the cursor at 3:
        # moveto f shows character f * length first, halves rounded up; scroll n
        # pages moves n * max(1, width - 2) - 1 at widths 1 to 3, 3 at 5, 6 at
        # 8; every form stops at length - width; the cursor stays at 3 and a
        # selection survives. TkCurses-i8s.
        if not args:
            return self._view_fractions()
        width = self._text_area().width
        field = self._field
        if args[0] == "moveto":
            # Halves round UP, as Tk's do (2.5 of 26 shows character 3);
            # Python's round() would send them to the even neighbour. A
            # fraction of the cells, as Tk's is of the pixels: the character
            # that cell is in comes first.
            total = field.measure(field.text)
            first = field.index_at_cell(math.floor(float(args[1]) * total + 0.5))
        elif args[0] == "scroll" and args[2] == "pages":
            # A page is cells, so it moves as far across wide text as narrow.
            count = int(args[1])
            cell = field.cell_of(field.view) + count * max(1, width - 2)
            first = field.index_at_cell(cell)
            if count > 0 and field.cell_of(first) < cell:
                first += 1  # Never short of the page, or wide text sticks.
        elif args[0] == "scroll":
            first = field.view + int(args[1])
        else:
            first = self.index(args[0])
        self._field.set_view(first, width)
        self._publish_view()
        self._redraw()
        return None

    def _char_bbox(self, index: Any) -> tuple[int, int, int, int]:
        """The cell box of one character, for the subclasses whose Tk has one.

        ``tk.Spinbox`` and the three ttk entries offer ``bbox(index)``; the
        classic ``tk.Entry`` does not - in tkinter its ``bbox`` IS
        ``Misc.bbox``, the grid alias - so this is private here and public
        on each of those. Measured on Tk 9.0.2 (``(x, y, width, height)``,
        relative to the widget):

        * an index past the last character answers the last character's box -
          ``end``, ``len`` and ``99`` all give the same as ``len - 1``;
        * the box is where the character IS, view and all: scrolled off to
          the left its x is negative, off to the right it is past the edge;
        * an empty entry answers a box of width 0 at the start.

        One cell high, and as wide as the character is drawn: two cells for a
        wide one, none for a combining mark. TkCurses-52q, TkCurses-9t4l.
        """
        area = self._text_area()
        field = self._field
        length = len(field.text)
        if length == 0:
            return (area.x, area.y, 0, 1)
        position = min(self.index(index), length - 1)
        column = area.x + self._shift(area) + field.column_of(position)
        return (column, area.y, field.measure(field.text[position]), 1)

    def _view_fractions(self) -> tuple[float, float]:
        """Where the visible run sits in the text, as two fractions."""
        field = self._field
        total = field.measure(field.text)
        if total <= 0:
            return (0.0, 1.0)
        width = max(1, self._text_area().width)
        field.fit_view(width)
        first = field.cell_of(field.view)
        return (first / total, min(1.0, (first + width) / total))

    def _publish_view(self) -> None:
        """Tell a scrollbar where the view is, if one is listening."""
        command = self._options.get("xscrollcommand")
        if command is not None:
            first, last = self._view_fractions()
            command(first, last)

    # -------------------------------------------------------------- editing

    def _validated(
        self,
        proposed: str,
        *,
        action: int = -1,
        index: int = -1,
        changed: str = "",
        condition: str = "key",
    ) -> bool:
        """Ask the ``validatecommand`` whether an edit may go ahead.

        A registered command is called with Tk's percent codes substituted,
        and a Python callable with the proposed contents - see
        :meth:`_run_validator`. Anything it raises counts as a refusal - a
        validator that fails should not take the application with it.

        Only ``key`` and ``all`` gate an edit. The focus modes validate when
        the focus moves and let every edit through, which was measured rather
        than assumed: a ``validate="focusout"`` entry sent an insert its
        validator refuses keeps the text. This used to test for ``none``
        instead, so the three focus modes vetoed keystrokes that Tk allows.

        A validator that edits the entry, or that raises, turns validation off
        - see :meth:`_turn_validation_off` for why that is Tk's answer rather
        than a shortcut taken here.

        The other two conditions are :meth:`_validate_focus` and
        :meth:`_validate_forced`.
        """
        if self._validating:
            # Noticed under every mode, as Tk notices it: a focus validator
            # that edits the entry fails even though no key validation runs.
            self._edited_while_validating = True
        if str(self._options["validate"]) not in _EDIT_VALIDATED:
            return True
        return self._ask_validator(
            proposed,
            can_raise=True,
            action=action,
            index=index,
            changed=changed,
            condition=condition,
        )

    def _ask_validator(
        self,
        proposed: str,
        *,
        notify: bool = True,
        can_raise: bool = False,
        action: int = -1,
        index: int = -1,
        changed: str = "",
        condition: str = "forced",
        current: str | None = None,
    ) -> bool:
        """Run the ``validatecommand``, and the ``invalidcommand`` after it.

        The half every validation condition shares. What the answer *means* is
        the condition's business: an edit that is refused is discarded, a focus
        change that is refused still happens, and a ``textvariable`` write
        cannot be refused at all. So this reports the verdict and does not act
        on it.

        Args:
            proposed: The contents being judged - the value the field would
                hold for an edit, the value it holds for every other condition.
            notify: Whether a refusal runs the ``invalidcommand``. The forced
                condition passes False, because - measured - Tk stays silent
                when a variable write fails validation.
            can_raise: Whether there is a caller to hand an error to - an edit
                or ``validate()``, not a focus change. The classic Entry never
                raises; ttk's does, see :meth:`_validator_raised`.
            action: Tk's ``%d``: 1 for an insert, 0 for a delete, -1 else.
            index: Tk's ``%i``: where the edit is, or -1.
            changed: Tk's ``%S``: the text inserted or deleted.
            condition: Tk's ``%V``: ``key``, ``focusin``, ``focusout`` or
                ``forced``.
            current: Tk's ``%s``, when the field has already changed: the
                text before a variable write.

        Returns:
            Whether the validator approved. A validator that raises, or that
            turns validation off by editing the entry, counts as a refusal and
            runs no ``invalidcommand`` whatever ``notify`` says.
        """
        command = self._options["validatecommand"]
        if command is None:
            return True
        if self._validating:
            # An edit from inside a validation callback - _validated has
            # already flagged it. Tk does not recurse: it lets this edit
            # through, which also discards the edit that was being validated -
            # the check below - and the classic Entry turns validation off as
            # well (see _nested_edit).
            self._nested_edit()
            return True
        mode = str(self._options["validate"])
        percents = {
            "d": str(action),
            "i": str(index),
            "P": proposed,
            "s": self._field.text if current is None else current,
            "S": changed,
            "v": mode,
            "V": condition,
            "W": self._w,
        }
        self._edited_while_validating = False
        self._validating = True
        try:
            try:
                allowed = self._run_validator(command, percents)
            except Exception:
                # tkinter hands Tcl nothing when a Python callback raises, Tcl
                # cannot read that as a boolean, and Tk turns validation off.
                # Measured: the edit is refused and invalidcommand does NOT
                # run, which is why this never reaches _refused.
                self._turn_validation_off()
                self._validator_raised(can_raise=can_raise)
                return False
            if self._edited_while_validating or (
                mode != "none" and str(self._options["validate"]) == "none"
            ):
                # The callback edited the entry, or turned validation off.
                # Whatever it returned, the edit is discarded.
                return False
            if not allowed and notify:
                self._refused(proposed, percents)
            return allowed
        finally:
            self._validating = False

    def _run_validator(self, command: Any, percents: dict[str, str]) -> bool:
        """Call a ``validatecommand`` and read its answer.

        A Python callable is given the proposed text if it takes an argument
        and nothing if it does not. tkinter's form - a name :meth:`register`
        made, with Tk's percent codes, as a tuple or one string - is called
        with each code substituted, and its answer read as Tcl reads one, so
        ``"no"`` refuses.

        Raises:
            Exception: Whatever the callable raises; ``TclError`` for a name
                nothing registered, or an answer that is not a boolean - as
                Tk, the caller turns validation off for any of them.
        """
        if callable(command):
            if _takes_an_argument(command):
                return bool(command(percents["P"]))
            return bool(command())
        answer = _call_registered(self, command, percents)
        if isinstance(answer, bool):
            return answer
        return bool(_tcl_boolean(self, answer))

    def _nested_edit(self) -> None:
        """What an edit made from inside a validation callback does to the mode.

        The classic Entry turns validation off - measured, see
        :meth:`_turn_validation_off`. ttk's does not, and overrides this.
        TkCurses-4ag.
        """
        self._turn_validation_off()

    def _validator_raised(self, *, can_raise: bool) -> None:
        """After a validator raised and validation was turned off.

        The classic Entry says nothing: the edit is refused and that is all.
        ttk's raises ``TclError`` to whoever made the edit, and overrides
        this. TkCurses-4ag.
        """

    def _validate_focus(self, condition: str) -> bool | None:
        """Validate because the focus arrived or left, if the mode asks for it.

        Tk's second validation condition, and nothing here acted on it: the
        focus modes were accepted as values of ``validate`` and never did
        anything. Measured on Tcl/Tk 9.0.2, with the mode on the left and the
        condition that fires across the top:

        =========== ========= =========
        mode        focusin   focusout
        =========== ========= =========
        focus       yes       yes
        focusin     yes       -
        focusout    -         yes
        all         yes       yes
        key, none   -         -
        =========== ========= =========

        Unlike an edit, this gates nothing - there is no proposed value to
        refuse, only the value already there. A refusal runs the
        ``invalidcommand`` and leaves the text alone. TkCurses-jd1.
        """
        wanted = _FOCUS_IN_VALIDATED if condition == "focusin" else _FOCUS_OUT_VALIDATED
        if str(self._options["validate"]) not in wanted:
            return None
        return self._ask_validator(self._field.text, condition=condition)

    def _validate_forced(self, previous: str) -> None:
        """Revalidate after the ``textvariable`` was written behind our back.

        Tk calls this condition ``forced``, and it is the one that cannot say
        no: the variable already holds the value, so there is nothing to
        refuse. Measured on Tcl/Tk 9.0.2 - the value is kept, the
        ``invalidcommand`` does *not* run, and Tk resolves the contradiction by
        turning validation off. It fires under every mode but ``none``,
        including the focus modes, which is why this does not consult
        :data:`_EDIT_VALIDATED`. TkCurses-3xb.

        One deliberate divergence, the single disagreement left in a 31-case
        differential probe: a validator that *edits* the entry while being
        asked about a variable write. Tk abandons the whole update, discards
        the validator's edit too, and leaves the widget holding the old text
        while the variable holds the new - a widget out of step with its own
        textvariable. Here the write and the edit both land. Both agree on the
        part that matters, which is that validation is turned off.
        TkCurses-doh.
        """
        if str(self._options["validate"]) == "none":
            return
        if not self._ask_validator(self._field.text, notify=False, current=previous):
            self._turn_validation_off()

    def _turn_validation_off(self) -> None:
        """Set ``validate`` to ``none``, as Tk does when a callback misbehaves.

        Tk's own recursion guard, and the reason this library needs one: once
        programmatic edits are validated, a validator that calls ``insert`` on
        the entry it is validating would call itself forever. Tk cuts the loop
        by disabling validation outright, and leaves it disabled - the
        application has to put it back. Measured on real Tk, for a validator
        that inserts into its own entry: the nested edit lands, the edit being
        validated does not, and ``cget("validate")`` reads ``none`` afterwards.

        Written straight to the option dict rather than through
        :meth:`configure`, because this runs from inside a callback that
        ``configure`` may itself have started.
        """
        self._options["validate"] = "none"

    def _border_style(self) -> BorderStyle:
        """The box this entry draws, brightened while it has the focus.

        Tk shows the focus on an entry two ways, and only one of them is the
        insertion cursor. The other is the focus highlight ring, which is drawn
        whatever the state - and the ring is what tells you a *readonly* entry
        has the keyboard, because Tk's manual is explicit that readonly draws
        "no insertion cursor ... even if the input focus is in the widget".

        This library draws no ring, having no cell for it, and until now put
        nothing in its place. So a focused
        readonly entry was indistinguishable from an unfocused one: Tk's cursor
        rule was copied faithfully and Tk's other half of the signal was not.
        Reported from UAT 41 - "though readonly is not modifiable, it should
        still reflect its focus status".

        The border is the cell equivalent: a focused entry draws its box bold
        and an unfocused one does not. ``BorderStyle.attr`` exists for exactly
        this, "used where line style alone is not enough to tell two reliefs
        apart", and ``relief="flat"`` still draws nothing. ``highlightthickness``
        is accepted and does not turn it off (TkCurses-gm66.1): programs set it
        to 0 to hide X11's ring, not to hide the keyboard.

        A_DIM is dropped rather than combined: the default relief for an entry
        is ``sunken``, whose border is dim, and dim-and-bold on one cell is
        whatever the terminal decides.
        """
        style = super()._border_style()
        if self.focus_get() is not self:
            return style
        return replace(style, attr=(style.attr & ~_curses.A_DIM) | _curses.A_BOLD)

    def _refused(
        self, proposed: str = "", percents: dict[str, str] | None = None
    ) -> None:
        """Run the ``invalidcommand``, which is what Tk does on a refusal.

        The third of Tk's validation trio, and it was missing: a program could
        say what counted as valid and not what to do when an edit did not. As
        with validatecommand, anything it raises is swallowed - a handler for a
        rejected keystroke should not take the application down with it, and
        measured, an invalidcommand that raises does *not* turn validation off
        the way a raising validator does.

        The handler is given the refused text if it will take it, and called
        with nothing if it will not. Tk's invalidcommand is a registered
        command that may ask for any substitution or none, so both arities are
        legitimate there; here, ``invalidcommand=lambda: ...`` was the only
        form that worked, which left a handler no way to see what it was
        rejecting except by reading back the text that had been *kept*.
        TkCurses-1d1.
        """
        command = self._options.get("invalidcommand")
        if command is None:
            return
        with contextlib.suppress(Exception):
            if not callable(command):
                _call_registered(self, command, percents or {"P": proposed})
            elif _takes_an_argument(command):
                command(proposed)
            else:
                command()

    def _edit(
        self,
        change: Callable[[], None],
        proposed: str,
        *,
        action: int,
        index: int,
        changed: str,
    ) -> None:
        """Apply an edit if the state and the validator both allow it.

        ``action``, ``index`` and ``changed`` are what Tk substitutes for
        ``%d``, ``%i`` and ``%S``: 1 for an insert or 0 for a delete, where,
        and the text inserted or deleted.
        """
        if not self._editable or not self._validated(
            proposed, action=action, index=index, changed=changed
        ):
            return
        change()
        self._changed()

    def _set_value(self, value: Any) -> None:
        """Replace the whole text the way ttk's ``set`` does: unconditionally.

        Tk's ``EntrySetValue``, which ``ttk::combobox set`` and
        ``ttk::spinbox set`` both are. Measured against Tk 9.0.2, it is
        nothing like :meth:`delete` followed by :meth:`insert`:

        * **No validation.** A validatecommand that refuses everything is not
          even called, under ``validate="all"`` or ``"key"``, and the value
          lands anyway.
        * **No state gate.** ``readonly`` and ``disabled`` both take the value.
        * **The cursor and selection stay**, clamped to the new text - see
          :attr:`TextField.text`.

        The textvariable is written, as for any change.
        """
        self._field.text = str(value)
        self._changed()

    def _changed(self) -> None:
        """Publish and repaint after the contents changed.

        Not rescroll: an edit made by the program leaves the view where it
        was, as Tk's does. The bindings scroll, through :meth:`_see_cursor`.
        """
        self._publish()
        self._publish_view()
        self._redraw()

    def _see_cursor(self) -> None:
        """Scroll so the cursor is on screen, and say where the view ended up.

        Tk's ``see insert``: for keystrokes and clicks, not for the program's
        own calls. TkCurses-i8s.
        """
        self._field.scroll_into_view(self._text_area().width)
        self._publish_view()

    # ------------------------------------------------------------- painting

    def _text_area(self) -> Rect:
        """Where the text goes, in cells relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        return Rect(
            edge + padx,
            edge + pady,
            max(0, self._rect.width - 2 * (edge + padx)),
            max(0, self._rect.height - 2 * (edge + pady)),
        )

    def _shift(self, area: Rect) -> int:
        """How many cells ``justify`` puts before the text, while it all fits.

        Tk's ``EntryComputeGeometry``: a text no wider than the field starts
        at the left, flush with the right edge, or at half the room left over;
        one that does not fit starts at the left and scrolls, whatever the
        justification. Measured on Tk 9.0.2, the same in all five entries:
        ``Sample`` in 20 starts at character 14 right and 7 centred.

        Tk's insertion cursor is a line on the right edge of the last
        character. Ours takes a cell, so while it is shown - the field has
        the focus and can be edited - one cell more is kept for it, and the
        text does not move as the cursor does.
        """
        justify = str(self._options["justify"])
        if justify not in ("right", "center"):
            return 0
        room = area.width - cells(self._displayed())
        if self.focus_get() is self and self._editable:
            room -= 1
        if room <= 0:
            return 0
        return room if justify == "right" else room // 2

    def _showing_placeholder(self) -> bool:
        """Whether the ghost text is what the field is displaying.

        Empty contents and a placeholder to show, and nothing else: measured on
        screen, Tk draws it **whatever the focus and whatever the state**. A
        focused field keeps it, with the insertion cursor before its first
        character; a ``disabled`` or ``readonly`` field keeps it too, which is
        the opposite of how the insertion cursor behaves. TkCurses-xe9.3.
        """
        return not self._field.text and bool(str(self._options["placeholder"]))

    def _displayed(self) -> str:
        """What is on screen: the contents masked by ``show``, or the placeholder.

        **The placeholder is not masked.** Measured, and the one thing here that
        would have been got wrong: a field with ``show="*"`` and a placeholder
        shows the placeholder as plain text, not as asterisks. ``show`` hides
        *contents* - there are none to hide - so the placeholder short-circuits
        it rather than passing through it.
        """
        if self._showing_placeholder():
            return str(self._options["placeholder"])
        mask = str(self._options["show"])
        text = self._field.text
        return mask[0] * len(text) if mask else text

    def _shown_cells(self, text: str) -> int:
        """The cells a run of the contents takes as drawn: the mask's, with
        ``show`` set, whatever characters it hides."""
        mask = str(self._options.get("show") or "")
        return cells(mask[0]) * len(text) if mask else cells(text)

    def _placeholder_attribute(self, attribute: int) -> int:
        """How the ghost text is drawn, as distinct from real contents.

        ``placeholderforeground`` is honoured when it is set. When it is not -
        which is the default - the text is drawn **dim**, and that is a
        deliberate divergence rather than an oversight. Tk's default leaves the
        placeholder in the ordinary foreground colour, which a GUI gets away
        with because the ghost text is a different shade of grey anyway; in a
        terminal it would be indistinguishable from real content, so a field
        that reads as full while ``get()`` answers ``""`` would actively
        mislead. Dim is the terminal's own idiom for "this is not your text".
        """
        colour = str(self._options["placeholderforeground"])
        colors = self.tk.colors
        if colour and colors is not None:
            return (
                colors.attribute_for(
                    colour, str(self._options["background"] or "black")
                )
                | _curses.A_DIM
            )
        return attribute | _curses.A_DIM

    def _redraw(self) -> None:
        """Paint the field, its selection, and the cursor."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        area = self._text_area()
        # Only pulled back if the text has shrunk away from the right edge; it
        # does not follow the cursor here, or every redraw would undo an
        # xview (TkCurses-i8s). Before layout the width is 0 and this is a
        # no-op, so text inserted early is not scrolled against no width.
        self._field.fit_view(area.width)
        dispatcher = CursesDispatcher.get()
        attribute = self._in_state(
            self._background_attribute() | self._font_attribute()
        )
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            if area.is_empty:
                return
            text = clip_cells(self._displayed()[self._field.view :], area.width)
            self._write_line(
                dispatcher,
                window,
                area.y,
                area.x + self._shift(area),
                text,
                self._placeholder_attribute(attribute)
                if self._showing_placeholder()
                else attribute,
            )
            self._draw_selection(dispatcher, window, area, attribute)
            self._draw_cursor(dispatcher, window, area, attribute)

    def _draw_selection(
        self, dispatcher: CursesDispatcher, window: Any, area: Rect, attribute: int
    ) -> None:
        """Show the selected range in the select colours, else reversed."""
        selection = self._field.selection
        if selection is None:
            return
        first, last = selection
        field = self._field
        start = max(0, field.column_of(first))
        stop = min(area.width, field.column_of(last))
        if stop <= start:
            return
        text = clip_cells(
            self._displayed()[max(first, field.view) : last], stop - start
        )
        with contextlib.suppress(_curses.error):
            self._write_line(
                dispatcher,
                window,
                area.y,
                area.x + self._shift(area) + start,
                text,
                self._selection_attribute(attribute),
            )

    def _draw_cursor(
        self, dispatcher: CursesDispatcher, window: Any, area: Rect, attribute: int
    ) -> None:
        """Note where typing will go, while the field has the focus.

        **Noted, not painted.** This painted the insertion point as a reversed
        cell, which is also how a selection is drawn, and a person could not
        tell the cursor from the selected text beside it (UAT 43,
        TkCurses-lw2). The terminal's own cursor is put there instead - see
        :class:`~tkcurses._core.screen.TerminalCursor` - which blinks and has
        the shape the person's terminal is set to.

        Not in an unfocused field, which would claim the keyboard is there
        when it is not; not in a readonly one, which Tk's manual says draws
        no insertion cursor; not when the cursor is scrolled out of view.
        """
        del dispatcher, window, attribute
        self._insert_at = None
        if self.focus_get() is not self or not self._editable:
            return
        column = self._field.column_of(self._field.cursor) + self._shift(area)
        if not (0 <= column < area.width):
            return
        self._insert_at = (
            self.winfo_rooty() + area.y,
            self.winfo_rootx() + area.x + column,
        )

    def _insert_cell(self) -> tuple[int, int] | None:
        return self._insert_at


#: Keys that move the cursor, as offsets or as absolute positions.
def _takes_an_argument(command: Callable[..., Any]) -> bool:
    """Whether a callback will accept one positional argument.

    Tk's validation callbacks are registered commands that may ask for any
    substitution or for none, so a handler written against Tk may legitimately
    take the refused text or take nothing. Both have to work here.

    A callable whose signature cannot be read - some builtins - is assumed to
    take nothing, which is the arity that worked before this existed.
    """
    try:
        signature = inspect.signature(command)
    except (TypeError, ValueError):
        return False
    try:
        signature.bind("")
    except TypeError:
        return False
    return True


#: Validation modes under which an edit is checked before it is applied.
#: Measured on real Tk: "focus", "focusin" and "focusout" validate when the
#: focus moves and let every edit through, so they are deliberately absent.
_EDIT_VALIDATED = ("key", "all")

#: Modes that validate when the focus arrives, and when it leaves. "focus"
#: means both. Measured; see Entry._validate_focus for the table.
_FOCUS_IN_VALIDATED = ("focus", "focusin", "all")
_FOCUS_OUT_VALIDATED = ("focus", "focusout", "all")


def _entry_key(event: Event) -> str | None:
    """Handle one key in an Entry, then bring the cursor into view.

    Returns ``"break"`` for keys the field consumed, so a Left arrow moving
    the cursor does not also reach whatever else is bound to it. Scrolling to
    the cursor belongs here and not in the edits themselves: Tk's bindings
    do it, its ``insert`` and ``icursor`` do not. TkCurses-i8s.
    """
    result = _entry_keystroke(event)
    if result == "break":
        event.widget._see_cursor()
        event.widget._redraw()
    return result


def _entry_keystroke(event: Event) -> str | None:
    """Apply one key to an Entry's field."""
    entry = event.widget
    field = entry._field
    keysym = event.keysym

    if keysym == "BackSpace":
        if field.selection:
            _delete_selected(entry)
        elif field.cursor > 0:
            at = field.cursor - 1
            entry._edit(
                lambda: field.delete(at, at + 1),
                field.text[:at] + field.text[at + 1 :],
                action=0,
                index=at,
                changed=field.text[at],
            )
        else:
            entry._changed()
        return "break"

    if keysym == "Delete" and not event.state & _TK_SHIFT:
        # Shift-Delete is <<Cut>>, and Tk lets the virtual event have it:
        # measured, it cuts the selection and deletes nothing else.
        if field.selection:
            _delete_selected(entry)
        elif field.cursor < len(field.text):
            at = field.cursor
            entry._edit(
                lambda: field.delete(at, at + 1),
                field.text[:at] + field.text[at + 1 :],
                action=0,
                index=at,
                changed=field.text[at],
            )
        else:
            entry._changed()
        return "break"

    if event.state & _TK_ALT_OR_META:
        # Not typed, and not kept: entry.tcl, spinbox.tcl and ttk/entry.tcl
        # bind <Alt-Key> and <Meta-Key> to "# nothing", so Alt-f opens a menu
        # through "all" rather than putting an f in the field. TkCurses-r3og.
        return None
    if event.char and not any(map(_is_control, event.char)):
        # Any character but a control one, as tk::EntryInsert takes any %A
        # that is not empty - a no-break space or a soft hyphen too, which
        # str.isprintable() refuses. A control character reaches Tk with
        # Control held, or as a key bound to "# nothing" above.
        # Two edits, each validated, as tk::EntryInsert makes them: the
        # selection is deleted, then the character inserted at the cursor -
        # even if the validator kept the selection.
        if field.selection:
            _delete_selected(entry)
        at = field.cursor
        char = event.char
        entry._edit(
            lambda: field.insert(at, char),
            field.text[:at] + char + field.text[at:],
            action=1,
            index=at,
            changed=char,
        )
        return "break"
    return None


def _delete_selected(entry: Any) -> None:
    """Delete an Entry's selection, as a validated edit - as Tk's
    ``tk::EntryBackspace`` and ``tk::EntryInsert`` do, through the widget's
    own ``delete``."""
    field = entry._field
    first, last = field.selection
    text = field.text
    entry._edit(
        lambda: field.delete(first, last),
        text[:first] + text[last:],
        action=0,
        index=first,
        changed=text[first:last],
    )


def _call_registered(widget: Any, command: Any, percents: dict[str, str]) -> Any:
    """Call a command given as tkinter gives one to Tk: a name ``register``
    made and its arguments, as a tuple or one string, with Tk's percent codes
    substituted in each - ``%%`` is ``%``, and a code Tk does not know is its
    letter, as measured on Tk 9.0.2.

    Raises:
        TclError: If no command has the name.
    """
    words = (
        [str(word) for word in command]
        if isinstance(command, (list, tuple))
        else _tcl_list(str(command))
    )
    if not words:
        return None
    func = widget.tk.commands.get(words[0])
    if func is None:
        raise TclError(f'invalid command name "{words[0]}"')
    return func(*(_substituted(word, percents) for word in words[1:]))


def _substituted(word: str, percents: dict[str, str]) -> str:
    """``word`` with each ``%`` code replaced from ``percents``."""
    if "%" not in word:
        return word
    out = []
    at = 0
    while at < len(word):
        char = word[at]
        if char == "%" and at + 1 < len(word):
            code = word[at + 1]
            out.append("%" if code == "%" else percents.get(code, code))
            at += 2
        else:
            out.append(char)
            at += 1
    return "".join(out)


def _entry_click(event: Event) -> None:
    """Take the focus and put the cursor where the click landed."""
    entry = event.widget
    if str(entry._options["state"]) == "disabled":
        return
    entry.focus_set()
    index = _entry_index_at(entry, event.x)
    entry._field.move_to(index)
    # Tk's tk::EntryButton1 anchors there too: a click, then selection_to,
    # selects from the click (measured). TkCurses-bfy.
    entry._field.select_from(index)
    _entry_start_drag(entry, "char")
    entry._see_cursor()
    entry._redraw()


# ------------------------------------------- selecting with the mouse, Entry
#
# Tk's own Entry bindings, READ from the running interpreter - bind_class
# Entry and TEntry, and the bodies of tk::EntryMouseSelect,
# tk::EntryAutoScan, ttk::entry::Select, WordSelect, CharSelect, ExtendTo
# and AutoScroll - and the selections MEASURED on Tk 9.0.2 by calling those
# procedures at each character (TkCurses-svtr):
#
# * a double-click selects the run around the pointer, word or not (see
#   tkcurses._core.editing.run_start), and a drag after it extends a word at
#   a time; a triple-click selects everything, and a drag after it keeps it;
#   the cursor goes to the end of what was selected.
# * Shift-click: classic Tk adjusts the selection - the nearer end moves, the
#   cursor stays; ttk extends from the far end and moves the cursor there.
# * a drag past either edge scrolls two characters every 50ms, selecting as
#   it goes, until the pointer comes back or the button is let go. A
#   terminal reports the pointer only inside itself, so an entry against the
#   terminal's edge cannot be dragged past that edge.
#
# Two families, because ttk's procedures are not classic Tk's: ttk's word
# drag measures from the anchor where classic measures from the character
# before it, and ttk binds no Double-Shift or Triple-Shift at all. Classic
# Spinbox has its own copy of the selection code with one difference, a
# double-click on the first character of a word selecting nothing - a Tk
# defect, measured, and not copied: it uses Entry's rule here.


#: The modifiers whose click extends a selection. Shift is Tk's. Alt is ours,
#: and a deliberate departure: VTE terminals - GNOME Terminal, Ptyxis and the
#: rest - keep every Shift-click for their own text selection and never send
#: it, even to a program that has asked for the mouse. Measured with a raw
#: probe in the author's terminal: plain, Ctrl- and Alt-clicks all arrived,
#: and not one Shift-click. Tk binds nothing to Alt-click, so nothing is lost;
#: Ctrl-click was the other candidate, and is Tk's "move the cursor and leave
#: the selection". TkCurses-svtr.
_EXTEND_MODIFIERS = ("Shift", "Alt")


def _is_ttk(widget: Any) -> bool:
    """True for a ttk widget, whose bindings are ttk's own procedures."""
    return getattr(widget, "_ttk_class", None) is not None


def _entry_index_at(entry: Any, x: int) -> int:
    """The gap a pointer at widget column ``x`` stands for.

    A terminal cell is a whole character, so the pointer on a character means
    the gap before it - Tk's ClosestGap with the pointer in the left half.

    Held to the visible columns, as Tk's ``@x`` is: a pointer dragged past
    the edge means the edge. Without that it named a character off screen,
    and keeping the cursor in view then jumped the field by the whole
    overshoot instead of the autoscroll's two characters.
    """
    area = entry._text_area()
    column = min(max(x - area.x, 0), max(area.width - 1, 0))
    return int(entry._field.index_at(column - entry._shift(area)))


def _entry_start_drag(entry: Any, mode: str) -> None:
    """Begin a press: what a drag extends by, and nothing moved yet."""
    _cancel_autoscan(entry)
    entry._select_mode = mode
    entry._moved = False
    entry._dragging = True


def _entry_select_to(entry: Any, x: int) -> None:
    """Select from the anchor to the pointer by the current mode.

    Classic Tk's ``tk::EntryMouseSelect`` or ttk's ``ttk::entry::DragTo``,
    by the widget's family. The anchor is the field's own, which a press or a
    shift-click set.
    """
    field = entry._field
    text = field.text  # the real text, as Tk's [$w get]: not what show= shows
    cur = _entry_index_at(entry, x)
    anchor = field._anchor
    if cur != anchor:
        entry._moved = True
    mode = entry._select_mode
    if _is_ttk(entry):
        if mode == "char":
            entry.selection_range(min(cur, anchor), max(cur, anchor))
            entry.icursor(cur)
        elif mode == "word":
            if cur < anchor:
                entry.selection_range(run_start(text, cur), run_end(text, anchor))
                entry.icursor(run_start(text, cur))
            else:
                last = run_end(text, cur)
                entry.selection_range(run_start(text, anchor), last)
                entry.icursor(last)
        elif mode == "line":
            entry.selection_range(0, "end")
            entry.icursor("end")
        entry._see_cursor()
        entry._redraw()
        return
    if mode == "char":
        if entry._moved:
            if cur == anchor:
                entry.selection_clear()
            else:
                entry.selection_range(min(cur, anchor), max(cur, anchor))
    elif mode == "word":
        if cur < anchor:
            first, last = run_start(text, cur), run_end(text, anchor - 1)
        elif cur > anchor:
            first, last = run_start(text, anchor), run_end(text, cur - 1)
        else:
            first, last = run_start(text, anchor), run_end(text, anchor)
        entry.selection_range(first, last)
    elif mode == "line":
        entry.selection_range(0, "end")
    if entry._moved:
        entry.icursor(cur)
    entry._see_cursor()
    entry._redraw()


def _entry_selects(entry: Any) -> bool:
    """Whether a mouse selection gesture applies: not to a disabled entry."""
    return str(entry._options["state"]) != "disabled"


def _entry_double(event: Event) -> None:
    """Select the word under the pointer; a drag then extends by words."""
    entry = event.widget
    if not _entry_selects(entry):
        return
    if _is_ttk(entry):
        # ttk::entry::Select: the anchor moves to the pointer first.
        entry._field.select_from(_entry_index_at(entry, event.x))
    _entry_start_drag(entry, "word")
    _entry_select_to(entry, event.x)
    if not _is_ttk(entry) and entry._field.selection is not None:
        entry.icursor(entry._field.selection[1])
    entry._see_cursor()
    entry._redraw()


def _entry_triple(event: Event) -> None:
    """Select everything; a drag then keeps it so."""
    entry = event.widget
    if not _entry_selects(entry):
        return
    if _is_ttk(entry):
        entry._field.select_from(_entry_index_at(entry, event.x))
    _entry_start_drag(entry, "line")
    _entry_select_to(entry, event.x)
    entry.icursor("end")
    entry._see_cursor()
    entry._redraw()


def _entry_shift_click(event: Event) -> None:
    """Extend the selection to the pointer.

    Classic: ``selection adjust`` - the nearer end moves and the cursor does
    not. ttk: ``ttk::entry::ExtendTo`` - from the far end, or from the cursor
    with nothing selected, and the cursor goes to the pointer.
    """
    entry = event.widget
    if not _entry_selects(entry):
        return
    index = _entry_index_at(entry, event.x)
    _entry_start_drag(entry, "char")
    if not _is_ttk(entry):
        entry.selection_adjust(index)
        return
    field = entry._field
    selection = field.selection
    insert = field.cursor
    if selection is None:
        anchor = insert
    else:
        first, last = selection
        anchor = last if index < first or (insert == first and index <= last) else first
    entry.focus_set()
    field.select_from(anchor)
    entry.selection_range(min(anchor, index), max(anchor, index))
    entry.icursor(index)
    entry._see_cursor()
    entry._redraw()


def _entry_control_click(event: Event) -> None:
    """Move the cursor to the pointer and leave everything else alone.

    Tk's classic Entry and Spinbox bind ``<Control-Button-1>`` to ``%W
    icursor @%x`` and nothing more: the selection stays, its anchor stays,
    and the focus does not move. No drag follows - a Ctrl-drag in Tk selects
    from whatever anchor the LAST plain press left, through state its
    bindings share, which is not copied. TkCurses-mndh.
    """
    entry = event.widget
    _cancel_autoscan(entry)
    entry._dragging = False
    entry.icursor(_entry_index_at(entry, event.x))
    entry._see_cursor()
    entry._redraw()


def _entry_double_shift(event: Event) -> None:
    """Extend the selection from the anchor by whole words (classic only)."""
    entry = event.widget
    if _entry_selects(entry):
        _entry_start_drag(entry, "word")
        _entry_select_to(entry, event.x)


def _entry_triple_shift(event: Event) -> None:
    """Select everything, extending (classic only)."""
    entry = event.widget
    if _entry_selects(entry):
        _entry_start_drag(entry, "line")
        _entry_select_to(entry, event.x)


def _cancel_autoscan(widget: Any) -> None:
    """Stop scrolling a drag along, if it was."""
    pending = getattr(widget, "_autoscan", None)
    if pending is not None:
        widget.after_cancel(pending)
        widget._autoscan = None


def _entry_autoscan(entry: Any) -> None:
    """Scroll two characters towards the pointer and select to it, again.

    Tk's ``tk::EntryAutoScan``: every 50ms while the button is held with the
    pointer past either side of the widget. Motion reports stop when the hand
    does, so without the repeat a drag past the edge would scroll once.
    """
    entry._autoscan = None
    if not entry._dragging or not entry.winfo_exists():
        return
    x = entry._drag_x
    if x >= entry.winfo_width():
        entry.xview("scroll", 2, "units")
    elif x < 0:
        entry.xview("scroll", -2, "units")
    else:
        return
    _entry_select_to(entry, x)
    entry._autoscan = entry.after(50, lambda: _entry_autoscan(entry))


# ------------------------------------------------- the clipboard, on an Entry
#
# Tk's own Entry bindings for the clipboard virtual events, MEASURED on Tk
# 9.0.2 with "hello world" and 0-5 selected (TkCurses-lw2):
#
# * <<Copy>> puts the selection on the clipboard - what is SHOWN, so a
#   show="*" entry copies "*****" - and with nothing selected does nothing.
# * <<Cut>> is copy, then delete. A readonly or disabled entry still copies
#   and refuses the delete.
# * <<Paste>> replaces the selection with the clipboard - a deliberate
#   departure from classic Tk on Linux, which keeps it (see _entry_paste).
#   An empty clipboard pastes nothing.
# * <<Clear>> deletes the selection; <<SelectAll>> selects everything and
#   leaves the cursor; <<PasteSelection>> (middle button) inserts PRIMARY
#   where the click landed.
#
# All of them edit through insert() and delete(), so a validator and the
# state have their say exactly as for any other edit.


def _entry_selected(entry: Any) -> str | None:
    """The selected text as it is shown, or None with nothing selected."""
    selection = entry._field.selection
    if selection is None:
        return None
    first, last = selection
    return str(entry._displayed()[first:last])


def _entry_copy(event: Event) -> None:
    """Put the selection on the clipboard."""
    text = _entry_selected(event.widget)
    if text is not None:
        event.widget.clipboard_clear()
        event.widget.clipboard_append(text)


def _entry_cut(event: Event) -> None:
    """Copy the selection, then delete it if the entry allows."""
    entry = event.widget
    text = _entry_selected(entry)
    if text is None:
        return
    entry.clipboard_clear()
    entry.clipboard_append(text)
    first, last = entry._field.selection
    entry.delete(first, last)
    entry._see_cursor()
    entry._redraw()


def _entry_paste(event: Event) -> None:
    """Insert the clipboard at the cursor, replacing any selection.

    A deliberate departure from classic Tk on Linux, which inserts and keeps
    the selection (X11's rule). Replacing is what ttk does on every platform,
    and classic Tk on Windows and macOS - ttk's PendingDelete: the cursor
    goes to the start of the selection, which is deleted, then the clipboard
    is inserted. A read-only entry refuses both. TkCurses-lw2.
    """
    entry = event.widget
    try:
        text = entry.clipboard_get()
    except TclError:
        return
    selection = entry._field.selection
    if selection is not None and entry._editable:
        entry.icursor(selection[0])
        entry.delete(selection[0], selection[1])
    entry.insert("insert", text)
    entry._see_cursor()
    entry._redraw()


def _entry_clear(event: Event) -> None:
    """Delete the selection."""
    selection = event.widget._field.selection
    if selection is not None:
        event.widget.delete(*selection)


def _entry_select_all(event: Event) -> None:
    """Select everything; the cursor stays where it was."""
    event.widget.selection_range(0, "end")


def _entry_paste_selection(event: Event) -> None:
    """Insert PRIMARY where the middle button was released."""
    entry = event.widget
    if not entry._editable:
        return
    area = entry._text_area()
    entry.icursor(entry._field.index_at(event.x - area.x - entry._shift(area)))
    try:
        text = entry.selection_get()
    except TclError:
        return
    entry.insert("insert", text)
    entry.focus_set()
    entry._see_cursor()
    entry._redraw()


def _entry_terminal_paste(event: Event) -> str:
    """Put a paste the terminal marked in, replacing any selection.

    One edit, validated once with the whole result, as a key is: a
    validator sees ``%d`` 1, ``%S`` the pasted text. Line breaks become
    spaces and control characters go, since an entry holds one line of
    text and a pasted Return would otherwise be a keystroke.
    """
    entry = event.widget
    pasted = _pasted_line(event.data)
    if not pasted:
        return "break"
    field = entry._field
    text = field.text
    first, last = field.selection or (field.cursor, field.cursor)

    def change() -> None:
        if last > first:
            field.delete(first, last)
        field.insert(first, pasted)
        field.place_cursor(first + len(pasted))

    entry._edit(
        change,
        text[:first] + pasted + text[last:],
        action=1,
        index=first,
        changed=pasted,
    )
    entry._see_cursor()
    entry._redraw()
    return "break"


def _bind_entry_clipboard(bind: Callable[..., Any], name: str) -> None:
    """Install the clipboard bindings under one entry class's name.

    Entry, Spinbox and ttk.Combobox each install Entry's keys under their own
    class name - binding tags name one class, not a chain - so each calls
    this.
    """
    bind(name, "<<Copy>>", _entry_copy)
    bind(name, "<<Cut>>", _entry_cut)
    bind(name, "<<Paste>>", _entry_paste)
    bind(name, "<<Clear>>", _entry_clear)
    bind(name, "<<SelectAll>>", _entry_select_all)
    bind(name, "<<PasteSelection>>", _entry_paste_selection)
    bind(name, "<<TerminalPaste>>", _entry_terminal_paste)


# ------------------------------------------------- moving through an entry
#
# entry.tcl and spinbox.tcl bind tk.tcl's navigation events, and ttk's
# entry.tcl binds the same ones differently: classic Tk extends a selection
# from the anchor `selection from` set (tk::EntryKeySelect), ttk from
# whichever end of the selection the cursor is not at (ttk::entry::ExtendTo).
# Measured over 750 recorded sequences, tests/support/navigation_keys.json.
# None breaks, as none of Tk's does. TkCurses-wmaq.


def _entry_previous_char(entry: Entry) -> int:
    """``tk::EntryPreviousChar``, and ttk's ``PrevChar``: one back, or 0."""
    return max(0, entry.index("insert") - 1)


def _entry_next_char(entry: Entry) -> int:
    """``tk::EntryNextChar``: one on, or the end."""
    return min(len(entry.get()), entry.index("insert") + 1)


def _entry_hides_words(entry: Entry) -> bool:
    """Whether word motion goes straight to an end, as for a password.

    Only for the class named in each script's check, ``winfo class $w eq
    "Entry"`` or ``"TEntry"``: a Spinbox or a Combobox with ``show`` set
    still moves by word.
    """
    return entry.winfo_class() in ("Entry", "TEntry") and bool(entry.cget("show"))


def _entry_previous_word(entry: Entry) -> int:
    """``tk::EntryPreviousWord``, and ttk's ``PrevWord``."""
    if _entry_hides_words(entry):
        return 0
    found = start_of_previous_word(entry.get(), entry.index("insert"))
    return 0 if found is None else found


def _entry_next_word(entry: Entry) -> int:
    """``tk::EntryNextWord``, and ttk's ``NextWord``: past the end of this
    word and the space after it."""
    text = entry.get()
    if _entry_hides_words(entry):
        return len(text)
    found = end_of_word(text, entry.index("insert"))
    if found is not None:
        found = start_of_next_word(text, found)
    return len(text) if found is None else found


def _entry_select_next_word(entry: Entry) -> int:
    """``tk::EntrySelectNextWord``, and ttk's ``SelectNextWord``: to the end
    of this word only."""
    text = entry.get()
    if _entry_hides_words(entry):
        return len(text)
    found = end_of_word(text, entry.index("insert"))
    return len(text) if found is None else found


def _entry_start(entry: Entry) -> int:
    del entry
    return 0


def _entry_end(entry: Entry) -> int:
    return len(entry.get())


def _entry_set_cursor(entry: Entry, index: int) -> None:
    """``tk::EntrySetCursor`` and ``ttk::entry::Move``: the cursor to
    ``index``, the selection cleared, the cursor brought into view."""
    entry.icursor(index)
    entry.selection_clear()
    entry._see_cursor()
    entry._redraw()


def _entry_key_select(entry: Entry, index: int) -> None:
    """``tk::EntryKeySelect``: a selection begun from the cursor, or the
    nearer end of the one there is moved; then the cursor follows."""
    if not entry.selection_present():
        entry.selection_from("insert")
        entry.selection_to(index)
    else:
        entry.selection_adjust(index)
    entry.icursor(index)
    entry._see_cursor()
    entry._redraw()


def _ttk_entry_extend_to(entry: Entry, index: int) -> None:
    """``ttk::entry::ExtendTo``: the selection runs from its end away from
    the cursor - or from the cursor, if there is none - to ``index``."""
    insert = entry.index("insert")
    if not entry.selection_present():
        anchor = insert
    else:
        first, last = entry.index("sel.first"), entry.index("sel.last")
        before = index < first or (insert == first and index <= last)
        anchor = last if before else first
    entry.selection_range(min(anchor, index), max(anchor, index))
    entry.icursor(index)
    entry._see_cursor()
    entry._redraw()


#: Each navigation event, and where it goes: the target, and whether it
#: extends the selection. As entry.tcl, spinbox.tcl and ttk/entry.tcl bind
#: them, which agree on every target.
_ENTRY_NAVIGATION: dict[str, tuple[Callable[[Entry], int], bool]] = {
    "<<PrevChar>>": (_entry_previous_char, False),
    "<<NextChar>>": (_entry_next_char, False),
    "<<SelectPrevChar>>": (_entry_previous_char, True),
    "<<SelectNextChar>>": (_entry_next_char, True),
    "<<PrevWord>>": (_entry_previous_word, False),
    "<<NextWord>>": (_entry_next_word, False),
    "<<SelectPrevWord>>": (_entry_previous_word, True),
    "<<SelectNextWord>>": (_entry_select_next_word, True),
    "<<LineStart>>": (_entry_start, False),
    "<<LineEnd>>": (_entry_end, False),
    "<<SelectLineStart>>": (_entry_start, True),
    "<<SelectLineEnd>>": (_entry_end, True),
}


def _entry_navigation(
    target: Callable[[Entry], int], extend: bool, themed: bool
) -> Callable[[Event], None]:
    """The binding for one navigation event in a classic or a ttk entry."""
    if not extend:
        return lambda event: _entry_set_cursor(event.widget, target(event.widget))
    select = _ttk_entry_extend_to if themed else _entry_key_select
    return lambda event: select(event.widget, target(event.widget))


def _bind_entry_navigation(
    bind: Callable[..., Any], name: str, *, themed: bool, lines: bool = True
) -> None:
    """Install the navigation events under one entry class's name.

    ``lines`` binds ``<<PrevLine>>`` and ``<<NextLine>>`` to nothing, as
    entry.tcl and ttk/entry.tcl do, so that Up and Down reach no other
    binding on the class; a Spinbox binds them itself.
    """
    for virtual, (target, extend) in _ENTRY_NAVIGATION.items():
        bind(name, virtual, _entry_navigation(target, extend, themed))
    bind(name, "<<SelectNone>>", lambda event: event.widget.selection_clear())
    if lines:
        bind(name, "<<PrevLine>>", _do_nothing)
        bind(name, "<<NextLine>>", _do_nothing)


def _entry_drag(event: Event) -> None:
    """Select from the press to the pointer while the button is held.

    Tk's own ``<B1-Motion>`` binding, read from the running interpreter
    (``tk::EntryMouseSelect``, character mode): the selection runs from the
    anchor the press set to the gap under the pointer, either way round, and
    is cleared where the two meet; the cursor follows the pointer. Entry had
    no drag at all until a person running UAT 43 tried one - TkCurses-lw2.

    A drag arrives as ``<Motion>``, as Text's does: curses reports motion
    with a button held and there is no Button1 modifier to match against,
    and the implicit grab keeps it with the widget that was pressed.
    """
    entry = event.widget
    if not entry._dragging:
        return
    entry._drag_x = event.x
    _entry_select_to(entry, event.x)
    # Past either side, Tk's <B1-Leave> starts the repeat; back inside, its
    # <B1-Enter> stops it. TkCurses-svtr.
    if event.x < 0 or event.x >= entry.winfo_width():
        if entry._autoscan is None:
            entry._autoscan = entry.after(50, lambda: _entry_autoscan(entry))
    else:
        _cancel_autoscan(entry)


def _entry_release(event: Event) -> None:
    """Stop dragging, wherever the pointer ended up."""
    event.widget._dragging = False
    _cancel_autoscan(event.widget)


def _entry_focus_in(event: Event) -> None:
    """Validate if the mode asks for it, then repaint so the cursor appears."""
    event.widget._validate_focus("focusin")
    event.widget._redraw()


def _entry_traverse_in(event: Event) -> None:
    """Tab arrived: select everything, cursor at the end, so typing replaces it.

    entry.tcl's and ttk's entry.tcl's ``<<TraverseIn>>``, which
    ``tk::TabToWindow`` sends to the widget Tab moved the focus to.
    """
    event.widget.selection_range(0, "end")
    event.widget.icursor("end")


def _entry_focus_out(event: Event) -> None:
    """Validate if the mode asks for it, then repaint so the cursor goes.

    Validation first: a focus validator is allowed to edit the entry - measured
    - and painting before it ran would show the text it was about to change.
    """
    event.widget._validate_focus("focusout")
    event.widget._redraw()


class Menubutton(_TextWidget):
    """A button that posts a menu instead of running a command.

    Everything a Label is, plus a ``menu`` and the gestures that open it: a
    click, Return, the space bar, or Down. It is what sits in a toolbar where
    a menubar would be too much, and what :class:`OptionMenu` is built from.

    The menu decides whether there is room for it where ``direction`` asks -
    a menubutton near the bottom of the terminal posts upwards whatever it
    was asked for, because a menu that runs off the screen cannot be read.

    Sample output:
        button = tk.Menubutton(root, text="File", relief="raised")
        button["menu"] = tk.Menu(button)
        button.pack()

    Options:
        direction: Where the menu appears: ``below``, ``above``, ``left``,
            ``right`` or ``flush`` - over the button.
        indicatoron: Whether a ``▾`` is drawn to show there is a menu.
        menu: The Menu to post.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeforeground``, ``anchor``, ``background``,
    ``bitmap``, ``borderwidth``, ``compound``,
    ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``image``, ``justify``,
    ``padx``, ``pady``, ``relief``, ``state``, ``takefocus``, ``text``,
    ``textvariable``, ``underline``, ``width``, ``wraplength``.

    Differences from tkinter:
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.

    Sample output (indicatoron):
        for on in (0, 1):
            tk.Menubutton(root, text=f"indicatoron={on}", indicatoron=on,
                          relief="raised").pack(side="left", padx=1)
    """

    #: Measured on Tk 9.0.2: an image name it refuses is kept.
    _stores_refused_image: ClassVar[bool] = True

    #: Drawn at the right when ``indicatoron`` is true, so a menubutton can
    #: be told from an ordinary button without opening it.
    _INDICATOR = "▾"

    _widget_options: ClassVar[dict[str, Any]] = {
        "bitmap": "",
        "borderwidth": 1,  # Tk's default
        **_STATE_COLOUR_OPTIONS,
        "direction": "below",
        "indicatoron": False,
        "menu": None,
        "relief": "flat",  # Tk's default
        "takefocus": True,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``menu``, ``direction``, ``indicatoron``, plus everything a
                Label takes.
        """
        super().__init__(master, cnf, name=name, **kw)
        self._install_class_bindings()

    def _install_class_bindings(self) -> None:
        """Register the gestures that post a menubutton's menu.

        Under this widget's own class name, not the literal "Menubutton":
        binding tags name one class rather than a chain of them, so an
        OptionMenu - which is a Menubutton - would otherwise match none of
        these and never open. The same trap Spinbox meets with Entry.
        """
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Button-1>", _menubutton_post)
        bind(name, "<Key-Return>", _menubutton_key)
        bind(name, "<Key-space>", _menubutton_key)
        bind(name, "<Key-Down>", _menubutton_key)
        bind(name, "<FocusIn>", _button_refresh)
        bind(name, "<FocusOut>", _button_refresh)

    @property
    def _indicator_on(self) -> bool:
        """True while the little arrow is drawn."""
        try:
            return self.getboolean(self._options["indicatoron"])
        except TclError:
            return False

    def post_menu(self) -> None:
        """Open the menu where ``direction`` says, if there is one.

        TkCurses extension:
            tkinter has no method for this: in Tk, only the menubutton's
            own bindings post its menu.
        """
        menu = self._options["menu"]
        if menu is None or self._disabled:
            return
        left, top = self.winfo_rootx(), self.winfo_rooty()
        width, height = self._rect.width, self._rect.height
        direction = str(self._options["direction"])
        if direction == "above" or direction == "left":
            where = (left, top)
        elif direction == "right":
            where = (left + width, top)
        elif direction == "flush":
            where = (left, top)
        else:
            where = (left, top + height)
        menu.post(*where)

    # -------------------------------------------------------------- painting

    def _apply_requested_size(self) -> None:
        """Ask for the text's room, plus the indicator if it is showing."""
        super()._apply_requested_size()
        if self._indicator_on:
            self._request_size(self._requested.width + 2, self._requested.height)

    def _text_area(self) -> Rect:
        """Where the text goes, less the indicator's cells."""
        area = super()._text_area()
        if not self._indicator_on:
            return area
        return Rect(area.x, area.y, max(0, area.width - 2), area.height)

    def _redraw(self) -> None:
        """Paint the button, then its indicator and focus marker."""
        super()._redraw()
        self._draw_indicator()

    def _draw_indicator(self) -> None:
        """Draw the arrow at the right, and underline the text when focused.

        Focus is shown by underlining rather than by a marker, because a
        menubutton is usually one of several in a row and markers either side
        would make the row twice as wide.
        """
        window = self._window
        if window is None or self.tk.screen is None:
            return
        area = super()._text_area()
        if area.is_empty:
            return
        attribute = self._background_attribute() | self._text_attribute()
        if self.focus_get() is self:
            attribute |= _curses.A_UNDERLINE
        dispatcher = CursesDispatcher.get()
        cell = self._indicator_cell()
        if cell is not None:
            with contextlib.suppress(_curses.error):
                self._write_line(
                    dispatcher, window, cell[1], cell[0], self._INDICATOR, attribute
                )

    def _indicator_cell(self) -> tuple[int, int] | None:
        """The arrow's cell, as ``(column, row)``, if one is drawn.

        Shared by the painting and by ttk's ``identify``, which names it
        ``Menubutton.indicator``.
        """
        area = super()._text_area()
        if area.is_empty or not self._indicator_on or area.width < 2:
            return None
        return (area.x + area.width - 1, area.y + (area.height - 1) // 2)


def _menubutton_post(event: Event) -> None:
    """Open the menu, leaving the focus where it was, as Tk does."""
    event.widget.post_menu()


def _menubutton_key(event: Event) -> str:
    """Open the menu from the keyboard, and keep the key to ourselves."""
    event.widget.post_menu()
    return "break"


class OptionMenu(Menubutton):
    """A menubutton showing the current value of a variable.

    The menu is built for you: one radiobutton entry per value, all sharing
    the variable, so choosing one both sets the variable and changes what the
    button says. The menu is reachable as ``widget["menu"]``, which is how
    code adds to it or replaces it afterwards.

    Sample output:
        colour = tk.StringVar(value="Green")
        tk.OptionMenu(root, colour, "Red", "Green", "Blue").pack()

    Options:
        direction: Where the menu appears, as for a Menubutton.
        indicatoron: Whether the ``▾`` is drawn.
        menu: The menu of values.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeforeground``, ``anchor``, ``background``,
    ``bitmap``, ``borderwidth``, ``compound``,
    ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``image``, ``justify``,
    ``padx``, ``pady``, ``relief``, ``state``, ``takefocus``, ``text``,
    ``textvariable``, ``underline``, ``width``, ``wraplength``.

    Differences from tkinter:
        The button shows its variable's value, so ``text`` is not drawn.
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.

    Sample output (indicatoron):
        choice = tk.StringVar(value="Medium")
        menu = tk.OptionMenu(root, choice, "Small", "Medium", "Large")
        menu.configure(indicatoron=0)
        menu.pack()
    """

    #: tkinter's, which its OptionMenu passes and Tk 9.0.2 reads back: a
    #: menubutton is flat, but the option menu is raised, two wide.
    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 2,
        "highlightthickness": 2,
        "relief": "raised",
    }

    def __init__(
        self,
        master: Misc | None,
        variable: Variable,
        value: Any = None,
        *values: Any,
        command: Callable[[Any], Any] | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget.
            variable: The variable the choice is written to, and the one the
                button's text follows.
            value: The value to start on. Included in the menu.
            *values: The rest of the choices.
            command: Called with the chosen value, after the variable is set.
            **kw: Anything else a Menubutton takes.

        Raises:
            TclError: If no values were given at all.
        """
        choices = [] if value is None else [value, *values]
        if not choices:
            raise TclError("OptionMenu needs at least one value")
        kw.setdefault("indicatoron", True)
        kw.setdefault("textvariable", variable)
        super().__init__(master, **kw)
        self._variable = variable
        self._command = command
        self._options["menu"] = Menu(self, name="menu")
        self.set_menu(*choices)

    def set_menu(self, *values: Any, current: Any = None) -> None:
        """Replace the choices, and choose ``current`` if it is given.

        Building the menu does not touch the variable: an OptionMenu over an
        empty variable shows nothing until something is chosen, and one over a
        variable that already holds a value leaves it alone.

        TkCurses extension:
            The classic OptionMenu has no ``set_menu`` in tkinter; this is the
            one ``ttk.OptionMenu`` has.
        """
        # Checked against Tk 9.0.2.
        menu = self._options["menu"]
        menu.delete(0, "end")
        for choice in values:
            # Command entries, as tkinter builds them - not radiobuttons.
            # A tick beside the current choice would read better in a
            # terminal, but code that asks the menu what type its entries
            # are would get a different answer than it does under Tk.
            menu.add_command(
                label=str(choice),
                command=lambda chosen=choice: self._chose(chosen),
            )
        if current is not None:
            self._variable.set(current)

    def _chose(self, value: Any) -> None:
        """Set the variable, then run the command with what was chosen."""
        self._variable.set(value)
        if self._command is not None:
            self._command(value)

    def __getitem__(self, key: str) -> Any:
        """``widget["menu"]`` reaches the menu, as it does in tkinter."""
        if key == "menu":
            return self._options["menu"]
        return super().__getitem__(key)


class Message(_TextWidget):
    """A run of text that chooses its own line length.

    A Label wraps where it is told and is otherwise as wide as its longest
    line. A Message is the other way round: given no width at all it picks
    one, aiming for a block of text whose width is ``aspect`` percent of its
    height. The default of 150 gives a block half again as wide as it is
    tall, which is roughly the shape of a paragraph.

    ``width`` overrides the aspect.
    Everything else - justification, anchoring, padding, the border - is a
    Label's.

    Sample output:
        tk.Message(root, text="A message picks its own line length, "
                   "aiming for a paragraph's shape.").pack()

    Options:
        aspect: The width the text aims for, as a percentage of its height.

    Standard options, described in :doc:`/reference/options`: ``anchor``,
    ``background``, ``borderwidth``, ``cursor``, ``font``, ``foreground``,
    ``highlightbackground``, ``highlightcolor``, ``highlightthickness``,
    ``justify``, ``padx``, ``pady``, ``relief``, ``takefocus``, ``text``,
    ``textvariable``, ``width``.

    Differences from tkinter:
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.

    Sample output (aspect):
        # size: 60x10
        text = "The same words at three aspect ratios, narrow to wide."
        for aspect in (100, 300, 900):
            tk.Message(root, text=text, aspect=aspect, relief="solid").pack(
                side="left", padx=1, anchor="n"
            )
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset(
        {"compound", "height", "image", "state", "underline", "wraplength"}
    )

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "padx": _padding_or_empty,
        "pady": _padding_or_empty,
        "width": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        "aspect": 150,
        # Tk's Message justifies left rather than centre, which is what makes
        # it read as a paragraph instead of a banner.
        "justify": "left",
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``aspect``, plus everything a Label takes.
        """
        self._aspect_cache: tuple[tuple[str, int], int] | None = None
        super().__init__(master, cnf, name=name, **kw)

    def _lines(self) -> list[str]:
        """The text as display lines, wrapped to whatever width was settled on."""
        return wrap(self._text(), self._wrap_width())

    def _wrap_width(self) -> int:
        """Where the text breaks: the option that says so, or the aspect."""
        for option in ("wraplength", "width"):
            value = int(self._options[option])
            if value > 0:
                return value
        return self._aspect_width()

    def _aspect_width(self) -> int:
        """The line length whose block comes closest to the aspect ratio.

        Searched rather than solved: wrapping is a step function of the width
        - nothing changes until a word moves - so there is no formula that
        gives the answer, and the candidates are few enough to try. The
        result is cached, because it is wanted on every repaint and only the
        text and the aspect can change it.
        """
        text = self._text()
        words = text.split()
        if not words:
            return 0
        aspect = max(1, int(self._options["aspect"]))
        key = (text, aspect)
        if self._aspect_cache is not None and self._aspect_cache[0] == key:
            return self._aspect_cache[1]
        # No narrower than the longest word - narrower than that changes
        # nothing except where the word overflows - and no wider than the
        # whole text on one line.
        narrowest = max(cells(word) for word in words)
        best, closest = narrowest, None
        for width in range(narrowest, cells(text) + 1):
            block_width, block_height = measure(wrap(text, width))
            if not block_height:
                continue
            error = abs(100 * block_width / block_height - aspect)
            if closest is None or error < closest:
                best, closest = width, error
            if error == 0:
                break
        self._aspect_cache = (key, best)
        return best


class LabelFrame(Frame):
    """A frame with a caption written into its border.

    Everything a Frame is, with a name on it. The caption sits on the border
    line rather than inside the frame, so it costs no room: the children get
    exactly what they would have got from a plain frame of the same size.

    Sample output:
        group = tk.LabelFrame(root, text="Options", padx=1)
        group.pack()
        tk.Checkbutton(group, text="Wrap lines").pack(anchor="w")
        tk.Checkbutton(group, text="Show numbers").pack(anchor="w")

    Options:
        class: The class name, ``Labelframe`` unless given. It cannot be
            changed once the frame is made.
        colormap: An X colormap, in Tk. Checked as Tk checks it, and kept.
        container: Whether another application's window is embedded in it.
            Kept; nothing can be embedded in a terminal.
        labelanchor: Where on the border the caption goes: ``nw``, ``n``,
            ``ne`` along the top, ``sw``, ``s``, ``se`` along the bottom, or
            ``wn``, ``w``, ``ws``, ``en``, ``e``, ``es`` on the sides.
        labelwidget: A widget to use as the caption instead of ``text``.
        visual: An X visual, in Tk. Checked as Tk checks it, and kept.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``font``, ``foreground``,
    ``height``, ``highlightbackground``, ``highlightcolor``,
    ``highlightthickness``, ``padx``, ``pady``, ``relief``, ``takefocus``,
    ``text``, ``width``.

    Differences from tkinter:
        Tk puts a caption anchored on the left or right edge on that edge,
        turned on its side. A terminal cannot turn text, so those anchors put it
        at the nearest end of the top or bottom edge instead. A ``labelwidget``
        taller than the border sits over the border rather than pushing the
        children down. ``highlightbackground``, ``highlightcolor`` and
        ``highlightthickness`` are accepted and draw nothing: the focus is shown
        by markers instead. So is ``cursor``: the mouse pointer belongs to the
        terminal.

    Sample output (labelanchor):
        # size: 50x8
        for anchor in ("nw", "n", "se"):
            tk.LabelFrame(root, text=anchor, labelanchor=anchor, width=14,
                          height=4).pack(side="left", padx=1)
    """

    #: Where each of Tk's twelve labelanchor values puts the caption here,
    #: as (edge, alignment). The six that name a vertical edge in Tk are
    #: folded onto the horizontal one nearest them.
    _CAPTION_PLACES: ClassVar[dict[str, tuple[str, str]]] = {
        "nw": ("top", "left"),
        "n": ("top", "centre"),
        "ne": ("top", "right"),
        "wn": ("top", "left"),
        "en": ("top", "right"),
        "w": ("top", "left"),
        "e": ("top", "right"),
        "ws": ("bottom", "left"),
        "es": ("bottom", "right"),
        "sw": ("bottom", "left"),
        "s": ("bottom", "centre"),
        "se": ("bottom", "right"),
    }

    #: Tk's labelframe has no background image, so no ``bgimg`` and no
    #: ``tile`` either: measured on Tk 9.0.2, all three are
    #: ``unknown option``.
    _option_synonyms: ClassVar[dict[str, str]] = _OPTION_ALIASES

    #: Tk's labelframe has a foreground, which its frame does not.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset()

    @classmethod
    def _public_options(cls) -> Collection[str]:
        """Frame's, less the background image Tk's labelframe lacks."""
        hidden = ("backgroundimage", "tile")
        return [name for name in super()._public_options() if name not in hidden]

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 2,  # Tk's default
        "font": "",
        "labelanchor": "nw",
        # A widget drawn on the border in place of the text. TkCurses-gm66.10.
        "labelwidget": "",
        "relief": GROOVE,
        "text": "",
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        class_: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            class_: The class this frame binds and reads options under.
            **kw: ``text``, ``labelanchor``, ``labelwidget``, plus
                everything a Frame takes.
        """
        self._label: BaseWidget | None = None
        super().__init__(master, cnf, name=name, class_=class_, **kw)
        self._adopt_label()
        self._apply_requested_size()

    def winfo_class(self) -> str:
        """``Labelframe``, as Tk spells the class, measured on Tk 9.0.2.

        So ``option_add("*Labelframe.foreground", ...)`` reaches it. A
        subclass answers its own name, as every subclass here does.
        """
        if self._class_name:
            return self._class_name
        return "Labelframe" if type(self) is LabelFrame else type(self).__name__

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, adopting a new ``labelwidget`` if one was named."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if "labelwidget" in given:
            self._adopt_label()
        if given:
            self._apply_requested_size()
            self._invalidate_layout()
            self._place_label()
            self._redraw()
        return result

    config = configure

    def cget(self, key: str) -> Any:
        """As every widget's, with a ``labelwidget`` that has gone answering
        ``""``, as Tk's does."""
        self._label_widget()
        return super().cget(key)

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """As every widget's, and a ``labelwidget`` must be one Tk would take.

        Measured on Tk 9.0.2: a widget whose parent is this frame or one of
        its ancestors, so that it can be drawn over it. Anything else - a
        child of a sibling, the root - is ``can't use .x as label in this
        frame``, and a path naming nothing is ``bad window path name``.
        """
        resolved = super()._checked(given)
        if "labelwidget" not in resolved:
            return resolved
        value = resolved["labelwidget"]
        if value in (None, ""):
            return resolved
        if isinstance(value, Misc):
            widget = value
        else:
            try:
                widget = self.nametowidget(str(value))
            except KeyError:
                raise TclError(f'bad window path name "{value}"') from None
        holders = []
        holder: Misc | None = self
        while holder is not None:
            holders.append(holder)
            holder = holder.master
        if (
            not isinstance(widget, BaseWidget)
            or widget._is_toplevel
            or not any(widget.master is holder for holder in holders)
        ):
            raise TclError(f"can't use {widget} as label in this frame")
        resolved["labelwidget"] = widget
        return resolved

    def _label_widget(self) -> BaseWidget | None:
        """The ``labelwidget``, while it is still this frame's label.

        Measured on Tk 9.0.2: destroyed, or packed somewhere else, and the
        option reads ``""`` and the text caption comes back. Destroying tells
        no manager here, so this checks rather than waits to be told.
        """
        label = self._label
        if label is None:
            return None
        if label._destroyed or label._manager != "labelframe":
            self._label = None
            if self._options.get("labelwidget") is label:
                self._options["labelwidget"] = ""
            return None
        return label

    def _adopt_label(self) -> None:
        """Take the ``labelwidget`` on, letting the previous one go.

        Measured on Tk 9.0.2: the one let go is unmapped and managed by
        nothing; the one taken is taken from whatever managed it, and raised
        above this frame, so a sibling made before it is not hidden under it.
        """
        new = self._options["labelwidget"] or None
        previous = self._label_widget()
        if previous is not None and previous is not new:
            previous._manager = ""
            previous._manager_container = None
            previous._unmap()
        if new is not None and new is not previous:
            new._leave_for(self)
            new._manager = "labelframe"
            new._manager_container = self
            if new.master is not self:
                new.tkraise(self)
            new._map()
        self._label = new

    def _label_taken(self, label: Misc) -> None:
        """Another manager has taken the label: the caption is text again."""
        if label is self._label:
            label._manager = ""
            label._manager_container = None
            self._label_widget()
            self._apply_requested_size()
            self._invalidate_layout()
            self._redraw()

    def _allocate(self, rect: Rect) -> None:
        """As every widget's, and the label follows the border it sits on."""
        super()._allocate(rect)
        self._place_label()

    def _label_size(self, label: BaseWidget) -> tuple[int, int]:
        """What the label is given: what it asks for, kept inside the edge."""
        inset = 2 * BORDER_WIDTH + 2 if self._border_drawn else 0
        width = min(label.winfo_reqwidth(), max(0, self._rect.width - inset))
        return (width, max(1, label.winfo_reqheight()))

    def _place_label(self) -> None:
        """Put the label on the border, where the anchor puts a caption.

        A caption's text sits one cell in from the corner, after its space,
        and so does a label widget. On the bottom edge its last row is the
        border row. Coordinates are the label's master's, which need not be
        this frame.
        """
        label = self._label_widget()
        if label is None:
            return
        width, height = self._label_size(label)
        edge, alignment = self._CAPTION_PLACES.get(
            str(self._options["labelanchor"]).lower(), ("top", "left")
        )
        inset = BORDER_WIDTH + 1 if self._border_drawn else 0
        if alignment == "centre":
            column = (self._rect.width - width) // 2
        elif alignment == "right":
            column = self._rect.width - inset - width
        else:
            column = inset
        row = 0 if edge == "top" else self._rect.height - height
        holder = label.master
        origin_x = holder.winfo_rootx() if holder is not None else 0
        origin_y = holder.winfo_rooty() if holder is not None else 0
        label._allocate(
            Rect(
                self.winfo_rootx() + column - origin_x,
                self.winfo_rooty() + row - origin_y,
                width,
                height,
            )
        )

    def _content_padding(self) -> Insets:
        """As a Frame's, and more on the label's edge when it is taller than
        the border row. Measured on Tk 9.0.2: a 40-pixel label put the first
        child at 40, below it, rather than at the border's 2."""
        padding = super()._content_padding()
        label = self._label_widget()
        if label is None:
            return padding
        extra = max(1, label.winfo_reqheight()) - (1 if self._border_drawn else 0)
        if extra <= 0:
            return padding
        edge, _ = self._CAPTION_PLACES.get(
            str(self._options["labelanchor"]).lower(), ("top", "left")
        )
        if edge == "top":
            return replace(padding, top=padding.top + extra)
        return replace(padding, bottom=padding.bottom + extra)

    def _caption(self) -> str:
        """The caption as it is drawn, spaced away from the border corners.

        Empty while a ``labelwidget`` stands in for it, as in Tk, where the
        ``text`` is kept and not drawn.
        """
        if self._label_widget() is not None:
            return ""
        text = str(self._options["text"])
        return f" {text} " if text else ""

    def _apply_requested_size(self) -> None:
        """Never narrower than the caption, whatever the children want.

        A frame that asks for less than its own name leaves the name cut in
        half, which reads as a rendering fault rather than as a small frame.
        """
        super()._apply_requested_size()
        label = self._label_widget()
        if label is not None:
            width, height = label.winfo_reqwidth() + 2, max(1, label.winfo_reqheight())
        else:
            width, height = cells(self._caption()), 1
        if not width:
            return
        self._request_size(
            max(self._requested.width, width + 2 * BORDER_WIDTH),
            max(self._requested.height, height + 1),
        )

    def _label_resized(self) -> None:
        """The label asked for another size: move it, and make room."""
        self._apply_requested_size()
        self._invalidate_layout()
        self._place_label()

    def _redraw(self) -> None:
        """Paint the frame, then write the caption over its border."""
        super()._redraw()
        self._draw_caption()

    def _draw_caption(self) -> None:
        """Write the caption into the border line the anchor names."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        place = self._caption_place()
        if place is None:
            return
        row, column, text = place
        attribute = self._background_attribute() | self._font_attribute()
        dispatcher = CursesDispatcher.get()
        with contextlib.suppress(_curses.error):
            # The last-cell case this used to handle here - curses scrolls a
            # window whose cursor has nowhere left to go - is one of the two
            # things _write_line exists for, along with the clipping.
            self._write_line(dispatcher, window, row, column, text, attribute)

    def _caption_place(self) -> tuple[int, int, str] | None:
        """Where the caption is written, as ``(row, column, text)``, if it is.

        Shared by the painting and by ttk's ``identify``, which answers
        nothing over the caption, as Tk's does.
        """
        if not self._border_drawn:
            return None
        caption = self._caption()
        width, height = self._rect.width, self._rect.height
        if not caption or width < 3 or height < 2:
            return None
        edge, alignment = self._CAPTION_PLACES.get(
            str(self._options["labelanchor"]).lower(), ("top", "left")
        )
        room = width - 2 * BORDER_WIDTH
        text = clip_text(caption, room)
        if alignment == "centre":
            column = BORDER_WIDTH + (room - cells(text)) // 2
        elif alignment == "right":
            column = width - BORDER_WIDTH - cells(text)
        else:
            column = BORDER_WIDTH
        row = 0 if edge == "top" else height - 1
        return (row, column, text)


#: A number at the start of a spinbox's text, as C's ``sscanf("%g")`` reads
#: it for Tk: leading space allowed, and anything after the number ignored.
_LEADING_NUMBER_RE = re.compile(r"\s*[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?")


def _leading_number(text: str) -> float | None:
    """The number ``text`` starts with, or None if it does not start with one."""
    found = _LEADING_NUMBER_RE.match(text)
    return float(found.group()) if found else None


class Spinbox(Entry):
    """An entry with a pair of arrows that step through a set of values.

    Everything an Entry does, a Spinbox does: it is a text field, it can be
    typed into, and its contents are text whatever the arrows put there. What
    it adds is a way to arrive at a value without typing it - which in a
    terminal, where there is often no mouse, is what the Up and Down keys are
    for.

    There are two kinds. Given ``values``, it steps through that list and the
    numeric options are ignored. Given ``from_`` and ``to``, it counts by
    ``increment`` between them. ``wrap`` decides what happens at the end:
    stop, or come round to the other side.

    ``readonly`` is the state that makes a spinbox a chooser rather than a
    field - the arrows still work, the keyboard cannot put anything else in.

    Sample output:
        tk.Spinbox(root, from_=1, to=10, width=6).pack()

    Options:
        buttonbackground: The colour of the arrows.
        buttoncursor: The mouse pointer over the arrows.
        buttondownrelief: Accepted and kept. Tk draws the down arrow raised,
            and sunken while it is pressed, whatever this says.
        buttonuprelief: Accepted and kept, as ``buttondownrelief`` is.
        command: Called with no arguments when an arrow is used.
        disabledbackground: The background while ``state`` is ``disabled``.
        format: How a number is written, as ``%5.2f``.
        from: The lowest value. Given as ``from_``, ``from`` being a Python
            keyword.
        increment: The step between values.
        invalidcommand: Called when ``validatecommand`` refuses a change.
        readonlybackground: The background while ``state`` is ``readonly``.
        to: The highest value.
        validate: When ``validatecommand`` is asked, as for an Entry.
        validatecommand: Asked whether a change may be made.
        values: The values to step through, which take the place of ``from``,
            ``to`` and ``increment``.
        wrap: Whether stepping past one end comes round to the other.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``background``, ``borderwidth``, ``cursor``,
    ``disabledforeground``, ``exportselection``, ``font``, ``foreground``,
    ``highlightbackground``, ``highlightcolor``, ``highlightthickness``,
    ``insertbackground``, ``insertborderwidth``, ``insertofftime``,
    ``insertontime``, ``insertwidth``, ``justify``, ``placeholder``,
    ``placeholderforeground``, ``relief``, ``repeatdelay``,
    ``repeatinterval``, ``selectbackground``, ``selectborderwidth``,
    ``selectforeground``, ``state``, ``takefocus``, ``textvariable``,
    ``width``, ``xscrollcommand``.

    Differences from tkinter:
        ``select_adjust``, ``select_clear``, ``select_from``,
        ``select_present``, ``select_range`` and ``select_to`` are here as on
        an Entry; tkinter's Spinbox has only the ``selection_`` names.

        ``buttoncursor`` changes nothing, the pointer being the terminal's.
        The insertion cursor is the terminal's own, so ``insertbackground``,
        ``insertborderwidth``, ``insertofftime``, ``insertontime`` and
        ``insertwidth`` draw nothing, and nor does ``selectborderwidth``. It
        takes a cell where Tk's is a line between two, so while the field has
        the focus a right-justified or centred text keeps one cell free for it
        at the right. ``highlightbackground``, ``highlightcolor`` and
        ``highlightthickness`` are accepted and draw nothing: the focus is shown
        by markers instead. So is ``cursor``: the mouse pointer belongs to the
        terminal.

    Sample output (buttonbackground):
        tk.Spinbox(root, from_=0, to=5, width=6, buttonbackground="blue").pack()

    Sample output (disabledbackground, readonlybackground):
        for state, colour in (("disabled", "red"), ("readonly", "blue")):
            tk.Spinbox(root, values=(state,), width=10, state=state,
                       disabledbackground=colour,
                       readonlybackground=colour).pack(side="left", padx=1)

    Sample output (format, from):
        tk.Spinbox(root, from_=2.5, to=10, increment=0.5, format="%06.2f",
                   width=10).pack()

    Sample output (increment, to):
        for step, end in ((1, 10), (0.5, 10), (1, 2.25)):
            tk.Spinbox(root, from_=1, to=end, increment=step,
                       width=8).pack()

    Sample output (values):
        tk.Spinbox(root, values=("Small", "Medium", "Large"), width=10).pack()
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"padx", "pady", "show"})

    #: The two arrows, drawn at the right-hand end of the field. Tk stacks
    #: them; a terminal row is one cell tall, so they sit side by side.
    _ARROWS = ("▲", "▼")

    #: Cells the arrows take. Taken out of the text area rather than added to
    #: the widget, so a Spinbox and an Entry of the same ``width`` are the
    #: same size on screen - which is what makes a column of them line up.
    _ARROW_WIDTH = 2

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "wrap": _tcl_boolean,
        "from": _tcl_float,
        "increment": _tcl_float,
        "to": _tcl_float,
    }

    #: Whether ``values``, ``from`` and ``to`` put something in the field -
    #: see :meth:`_contents_from_options`. ttk's never do.
    _options_set_contents: ClassVar[bool] = True

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        # The arrows: activebackground is stored only, since an arrow is not
        # drawn held down; buttonbackground is theirs. TkCurses-gm66.4.
        "activebackground": "",
        "buttonbackground": "",
        # The pointer over the arrows, which a terminal has none of, and their
        # reliefs: sunken is drawn dim. TkCurses-gm66.5.
        "buttoncursor": "",
        "buttondownrelief": "raised",
        "buttonuprelief": "raised",
        "command": None,
        "format": "",
        "from": 0.0,
        "increment": 1.0,
        # An arrow held down steps again after repeatdelay, then every
        # repeatinterval; Tk's defaults. TkCurses-gm66.6.
        "repeatdelay": 400,
        "repeatinterval": 100,
        "to": 0.0,
        "values": None,
        "wrap": False,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``values``, ``from_``, ``to``, ``increment``, ``wrap``,
                ``format``, ``command``, plus everything an Entry takes.
        """
        self._held_arrow: str | None = None
        self._repeated = 0
        #: The arrow drawn pressed: ``selection element``.
        self._selected_element = "none"
        super().__init__(master, cnf, name=name, **kw)
        self._order_range()
        # Construction is the first configure, from Tk's defaults of no
        # values and a range of 0 to 0.
        self._contents_from_options(
            values_given=bool(self._value_list()), old_range=(0.0, 0.0)
        )

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """As Entry's, and ``values``, ``from`` and ``to`` may reset the text."""
        old_range = self._range()
        result = super().configure(cnf, **kw)
        given = _given(cnf, kw)
        if given:
            self._order_range()
            self._contents_from_options(
                values_given="values" in given, old_range=old_range
            )
        return result

    config = configure

    def _range(self) -> tuple[float, float]:
        return float(self._options["from"]), float(self._options["to"])

    #: Whether a ``from`` above ``to`` is swapped, as the classic Tk
    #: spinbox does; ttk's keeps them as given.
    _swaps_range: ClassVar[bool] = True

    def _order_range(self) -> None:
        """Swap ``from`` and ``to`` when ``from`` is the larger.

        Measured on Tk 9.0.2: ``Spinbox(from_=10, to=0)`` reports ``from``
        0.0 and ``to`` 10.0 and steps up from ``0`` to ``1``, and
        ``configure(from_=20)`` over ``to=10`` gives 10 and 20.
        """
        if not self._swaps_range:
            return
        low, high = self._range()
        if low > high:
            self._options["from"], self._options["to"] = high, low

    def _contents_from_options(
        self, *, values_given: bool, old_range: tuple[float, float]
    ) -> None:
        """Put in the field what configuring ``values``, ``from`` or ``to``
        puts there in Tk, which is not documented and was measured on Tk
        9.0.2 - TkCurses-fdl9:

        - ``values`` given, and not empty: the first of them, even if it is
          the same list and the field held another of its values.
        - Otherwise, with no ``values``, ``from`` and ``to`` apart, and either
          of them changed: the number the text starts with, clamped to the
          range, in the spinbox's format. Text that does not start with one
          is ``from``. So a spinbox with the default range of 0 to 0 starts
          empty, and ``Spinbox(to=10)`` starts at ``0``.

        Neither ``state`` nor the validator stops it, and a ``textvariable``
        is overwritten: ``Spinbox(textvariable=StringVar(value="x"), to=10)``
        holds ``0``. ttk's spinbox does none of it.
        """
        if not self._options_set_contents:
            return
        values = self._value_list()
        if values:
            if not values_given:
                return
            text = values[0]
        else:
            low, high = self._range()
            if low == high or (low, high) == old_range:
                return
            number = _leading_number(self._field.text)
            if number is None:
                number = low
            text = self._number_text(min(max(number, low), high))
        # Straight into the field, not through _replace: that refuses a
        # disabled widget, and Tk's does not.
        self._field.text = text
        self._changed()

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register the editing keys and the arrows for every Spinbox.

        Binding tags name one class, not a chain of them, so a Spinbox does
        not inherit Entry's class bindings and has to say the same things
        again. Up and Down step: spinbox.tcl binds them as ``<<PrevLine>>``
        and ``<<NextLine>>``, ttk/spinbox.tcl as the keys themselves.
        """
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Any-Key>", _entry_key)
        bind(name, "<Button-1>", _spinbox_click)
        bind(name, "<Motion>", _entry_drag)
        bind(name, "<ButtonRelease-1>", _spinbox_release)
        bind(name, "<Double-Button-1>", _spinbox_double)
        if not _is_ttk(self):
            # ttk binds no triple-click: there a third click matches the
            # double-click binding again, a count of at least two.
            bind(name, "<Triple-Button-1>", _spinbox_triple)
        if not _is_ttk(self):
            bind(name, "<Control-Button-1>", _entry_control_click)
        for extend in _EXTEND_MODIFIERS:
            bind(name, f"<{extend}-Button-1>", _entry_shift_click)
            if not _is_ttk(self):
                bind(name, f"<Double-{extend}-Button-1>", _entry_double_shift)
                bind(name, f"<Triple-{extend}-Button-1>", _entry_triple_shift)
        bind(name, "<FocusIn>", _entry_focus_in)
        bind(name, "<FocusOut>", _entry_focus_out)
        bind(name, "<<TraverseIn>>", _entry_traverse_in)
        _bind_entry_clipboard(bind, name)
        themed = _is_ttk(self)
        _bind_entry_navigation(bind, name, themed=themed, lines=themed)
        if themed:
            # ttk/spinbox.tcl: the keys and the arrows generate the virtual
            # events, and only those step, so a program can generate them.
            bind(name, "<Key-Up>", _spinbox_generate("<<Increment>>"))
            bind(name, "<Key-Down>", _spinbox_generate("<<Decrement>>"))
            bind(name, "<<Increment>>", _spinbox_step(1))
            bind(name, "<<Decrement>>", _spinbox_step(-1))
        else:
            bind(name, "<<PrevLine>>", _spinbox_step(1))
            bind(name, "<<NextLine>>", _spinbox_step(-1))

    # --------------------------------------------------------------- values

    def _value_list(self) -> list[str]:
        """The ``values`` option as a list, or empty if there is none.

        A string is split on whitespace, because that is what a Tcl list
        looks like arriving through the option database.
        """
        values = self._options["values"]
        if not values:
            return []
        if isinstance(values, str):
            return values.split()
        return [str(value) for value in values]

    def _number_text(self, value: float) -> str:
        """One number as text, in ``format`` if it was given and otherwise
        in the one :meth:`_computed_format` works out."""
        template = str(self._options["format"])
        if template:
            with contextlib.suppress(TypeError, ValueError):
                return template % value
        return self._computed_format() % value

    def _computed_format(self) -> str:
        """The ``%f`` or ``%e`` format Tk gives every number in the range.

        Follows ``ComputeFormat`` in Tk's tkEntry.c: enough digits after the
        point to show multiples of the increment, counted from the most
        significant digit any number in the range needs, and ``%e`` when
        that is shorter. Measured on Tk 9.0.2 - an increment of 0.5 shows
        ``1.0``, ``1.5``, ``2.0``; 0.001 up to 1000 shows ``0.000``; 1e-8
        up to 1e-6 shows ``0.00e+00`` - and every decimal is kept, where
        this used to strip them.
        """
        low, high = self._range()
        biggest = max(abs(low), abs(high)) or 1.0
        most = math.floor(math.log10(biggest))
        increment = abs(float(self._options["increment"])) or 1.0
        least = math.floor(math.log10(increment))
        digits = most - least + 1 if most >= least else 1
        e_width = digits + 4 + (1 if digits > 1 else 0)
        after = max(0, digits - most - 1)
        f_width = (most + after if most >= 0 else after) + (after > 0) + (most < 0)
        return f"%.{after}f" if f_width <= e_width else f"%.{digits - 1}e"

    def _replace(self, text: str) -> None:
        """Put ``text`` in the field, as the arrows do.

        Not through :meth:`Entry._edit`: that refuses anything but the normal
        state, and a readonly spinbox's arrows are the whole point of the
        readonly state. The validator still gets its say.
        """
        if self._disabled or not self._validated(text, condition="forced"):
            return
        self._field.text = text
        self._field.select_clear()
        self._changed()

    def scan(self, *args: Any) -> tuple[()]:
        """``scan mark x`` or ``scan dragto x``, as tkinter's Spinbox has it.

        Raises:
            TclError: For any other, in Tk's words.
        """
        if len(args) != 2:
            raise TclError(f'wrong # args: should be "{self} scan mark|dragto x"')
        option = str(args[0])
        if option and "mark".startswith(option):
            self.scan_mark(args[1])
        elif option and "dragto".startswith(option):
            self.scan_dragto(args[1])
        else:
            raise TclError(f'bad scan option "{option}": must be dragto or mark')
        return ()

    def _arrow_relief(self, element: str) -> str:
        """How an arrow is drawn: sunken while it is the selection element,
        and raised otherwise, as ``DisplayEntry`` in Tk's ``tkEntry.c``
        draws it. ``buttonuprelief`` and ``buttondownrelief`` play no part:
        the code there that would draw them is under ``#if 0`` in Tk 9.0.2."""
        if getattr(self, "_selected_element", "none") == element:
            return SUNKEN
        return RAISED

    def selection_element(self, element: Any = None) -> Any:
        """The arrow drawn pressed, or name one: buttonup, buttondown or none.

        Tk's bindings name the arrow a press is on, and none on the
        release; a program can do the same.

        Raises:
            TclError: For any other name, in Tk's words.
        """
        if element is None:
            return self._selected_element
        chosen = _tcl_index(
            element, ("buttondown", "buttonup", "none"), "selection element"
        )
        if chosen != self._selected_element:
            self._selected_element = chosen
            self._redraw()
        return None

    def selection(self, *args: Any) -> Any:
        """Tk's ``selection`` command, of which ``selection_range`` and the
        rest are the named forms: adjust, clear, element, from, present,
        range or to, with their arguments.

        Answers as tkinter's does, a tuple of the numbers in the reply:
        ``(1,)`` for a selection ``present``, ``()`` for most.

        Raises:
            TclError: For a subcommand Tk lacks, in Tk's words.
        """
        if not args:
            raise TclError(f'wrong # args: should be "{self} selection option ?index?"')
        option = _tcl_index(
            args[0],
            ("adjust", "clear", "element", "from", "present", "range", "to"),
            "selection option",
        )
        rest = args[1:]
        if option == "element":
            return self.selection_element(*rest)
        if option == "present":
            return (int(self.selection_present()),)
        if option == "clear":
            self.selection_clear()
        else:
            getattr(self, f"selection_{option}")(*rest)
        return ()

    def bbox(self, index: Any) -> tuple[int, int, int, int]:
        """The box of the character at ``index``, as ``(x, y, width, height)``.

        As in tkinter, the classic Entry has no ``bbox`` of its own and
        answers with the grid's, :meth:`Misc.grid_bbox`.
        """
        # TkCurses-52q.
        return self._char_bbox(index)

    # ------------------------------------------------------------- stepping

    def _step(self, direction: int) -> None:
        """Move one place up or down the values, or the range."""
        values = self._value_list()
        text = (
            self._list_step(values, direction)
            if values
            else self._number_step(direction)
        )
        if text is None:
            return
        self._replace(text)
        command = self._options["command"]
        if command is not None:
            command()

    def _list_step(self, values: list[str], direction: int) -> str | None:
        """The next entry in ``values``, or None at an end that does not wrap.

        Contents that are not in the list at all - typed in, or left over
        from a previous ``values`` - step to whichever end the arrow points
        away from, so that either arrow gets a spinbox out of that state.
        """
        try:
            index = values.index(self._field.text) + direction
        except ValueError:
            return values[0] if direction > 0 else values[-1]
        if 0 <= index < len(values):
            return values[index]
        if not self._wraps:
            return None
        return values[index % len(values)]

    def _number_step(self, direction: int) -> str | None:
        """The next number in the range; None when the range is empty.

        ``SpinboxInvoke`` in Tk's tkEntry.c, measured on Tk 9.0.2: a step
        past an end stops on it - 9.9 up by 0.3 to 10 is ``10.0`` - or,
        with ``wrap``, goes to the other end; text that does not start
        with a number goes to ``from``.
        """
        low, high = self._range()
        if low == high:
            return None
        return self._stepped(low, high, direction)

    def _stepped(self, low: float, high: float, direction: int) -> str:
        """One step from the number the text starts with, kept between
        ``low`` and ``high`` - a value below ``low`` going to ``low``, or
        with ``wrap`` to ``high``, and the other way round."""
        current = _leading_number(self._field.text)
        if current is None:
            return self._number_text(low)
        increment = abs(float(self._options["increment"])) or 1.0
        value = current + increment * direction
        if value < low:
            value = high if self._wraps else low
        elif value > high:
            value = low if self._wraps else high
        return self._number_text(value)

    @property
    def _wraps(self) -> bool:
        """True while stepping past an end comes round to the other."""
        try:
            return self.getboolean(self._options["wrap"])
        except TclError:
            return False

    # ------------------------------------------------------------ public API

    def invoke(self, element: str) -> None:
        """Press one of the arrows from code.

        Args:
            element: ``"buttonup"`` or ``"buttondown"``.

        Raises:
            TclError: If it is neither.
        """
        if element == "buttonup":
            self._step(1)
        elif element == "buttondown":
            self._step(-1)
        else:
            raise TclError(f'bad element "{element}": must be buttondown or buttonup')

    def identify(self, x: int, y: int) -> str:
        """Which part of the spinbox is at a position within this widget.

        Args:
            x: Column within this widget, as an Event reports it.
            y: Row within this widget.

        Returns:
            ``"buttonup"``, ``"buttondown"``, ``"entry"``, or ``"none"``
            for anywhere outside the widget.
        """
        if not (0 <= x < self._rect.width and 0 <= y < self._rect.height):
            return "none"
        up, down = self._arrow_columns()
        if up is None or down is None:
            return "entry"
        if x == up:
            return "buttonup"
        if x == down:
            return "buttondown"
        return "entry"

    # -------------------------------------------------------------- painting

    def _apply_requested_size(self) -> None:
        """Ask for the field's width plus room for the two arrows."""
        super()._apply_requested_size()
        self._request_size(
            self._requested.width + self._ARROW_WIDTH, self._requested.height
        )

    def _text_area(self) -> Rect:
        """Where the text goes: the field, less the arrows at its right end."""
        area = super()._text_area()
        return Rect(area.x, area.y, max(0, area.width - self._ARROW_WIDTH), area.height)

    def _arrow_columns(self) -> tuple[int | None, int | None]:
        """Which columns the two arrows occupy, or None if there is no room."""
        area = super()._text_area()
        if area.width < self._ARROW_WIDTH:
            return (None, None)
        return (area.x + area.width - 2, area.x + area.width - 1)

    def _redraw(self) -> None:
        """Paint the field, then the arrows at its right-hand end."""
        super()._redraw()
        window = self._window
        if window is None or self.tk.screen is None:
            return
        up_column, down_column = self._arrow_columns()
        if up_column is None or down_column is None:
            return
        area = super()._text_area()
        attribute = self._in_state(
            self._background_attribute() | self._font_attribute()
        )
        if self._options["buttonbackground"]:
            state = self._state_colours(str(self._options["state"]))
            attribute = self._coloured(
                attribute,
                state[0] if state is not None else "",
                self._options["buttonbackground"],
            )
        dispatcher = CursesDispatcher.get()
        # Through the shared writer, for the reason the listbox uses it: the
        # second arrow used to go on with insstr, which shifted the row along
        # and pushed a bordered spinbox's right border off the end.
        # Unbordered, the arrows really do reach the last cell and insstr
        # really is needed - _write_line is what tells the two cases apart.
        up, down = self._ARROWS
        for column, arrow, relief in (
            (up_column, up, self._arrow_relief("buttonup")),
            (down_column, down, self._arrow_relief("buttondown")),
        ):
            self._write_line(
                dispatcher,
                window,
                area.y,
                column,
                arrow,
                attribute | _part_relief(relief),
            )


def _spinbox_step(amount: int) -> Callable[[Event], None]:
    """Step the value: spinbox.tcl's ``<<PrevLine>>`` and ``<<NextLine>>``,
    which ``invoke buttonup`` and ``buttondown``, and ttk/spinbox.tcl's
    ``<<Increment>>`` and ``<<Decrement>>``. Neither breaks."""
    return lambda event: event.widget._step(amount)


def _spinbox_generate(sequence: str) -> Callable[[Event], None]:
    """ttk/spinbox.tcl's Up and Down: ``event generate %W <<Increment>>``."""
    return lambda event: event.widget.event_generate(sequence)


def _spinbox_click(event: Event) -> None:
    """Press an arrow, or place the cursor in the text.

    A classic arrow steps when it is released, or repeatedly while it is
    held, as ``tk::spinbox::ArrowPress`` arranges. ttk's steps on the press,
    and again while it is held (``ttk::spinbox::Press``, through
    ``ttk::Repeatedly``); a disabled one does nothing.
    """
    spinbox = event.widget
    # The classic method, by name: a ttk subclass's own identify answers
    # ttk's element names, which this binding cannot act on. TkCurses-d5u.
    part = Spinbox.identify(spinbox, event.x, event.y)
    if part not in ("buttonup", "buttondown"):
        _entry_click(event)
        return
    if _is_ttk(spinbox):
        # ttk::spinbox::Press: the arrow generates the event, which steps,
        # and goes on generating it while held.
        if spinbox.instate(["disabled"]):
            return
        spinbox.focus_set()
        sequence = "<<Increment>>" if part == "buttonup" else "<<Decrement>>"
        _ttk_repeatedly(spinbox, spinbox.event_generate, sequence)
        return
    spinbox.focus_set()
    spinbox._held_arrow = part
    spinbox.selection_element(part)  # tk::spinbox::ArrowPress
    spinbox._repeated = 0
    delay = _repeat_option(spinbox, "repeatdelay")
    if delay > 0:
        _repeat_after(spinbox, delay, _spinbox_invoke, spinbox, part)


def _spinbox_invoke(spinbox: Any, part: str) -> None:
    """Step for a held arrow and go on doing so: ``tk::spinbox::Invoke``."""
    spinbox._step(1 if part == "buttonup" else -1)
    spinbox._repeated += 1
    interval = _repeat_option(spinbox, "repeatinterval")
    if interval > 0:
        _repeat_after(spinbox, interval, _spinbox_invoke, spinbox, part)


def _spinbox_release(event: Event) -> None:
    """Step for an arrow that was pressed and not held: ``tk::spinbox::ButtonUp``.

    Wherever the pointer is now: Tk steps on a release away from the arrow,
    which a press that changes its mind cannot take back.
    """
    spinbox = event.widget
    _cancel_repeat(spinbox)
    part, spinbox._held_arrow = spinbox._held_arrow, None
    if part is not None and not spinbox._repeated:
        spinbox._step(1 if part == "buttonup" else -1)
    if part is not None:
        spinbox.selection_element("none")  # tk::spinbox::ButtonUp
    _entry_release(event)


def _spinbox_arrow(spinbox: Any, event: Event) -> bool:
    """True if the press was on an arrow, which steps instead of selecting."""
    return Spinbox.identify(spinbox, event.x, event.y) in ("buttonup", "buttondown")


def _spinbox_double(event: Event) -> None:
    """On an arrow, another step; in the text, select.

    Classic: a word, the cursor at its START (``tk::spinbox::MouseSelect`` is
    given ``sel.first``, where Entry's binding moves to ``sel.last``). ttk:
    everything (``ttk::spinbox::DoubleClick`` calls SelectAll). Measured.
    """
    spinbox = event.widget
    if _spinbox_arrow(spinbox, event):
        _spinbox_click(event)
        return
    if not _entry_selects(spinbox):
        return
    if _is_ttk(spinbox):
        _entry_start_drag(spinbox, "char")
        spinbox._dragging = False  # ttk's DoubleClick starts no drag
        spinbox.selection_range(0, "end")
        spinbox.icursor("end")
    else:
        _entry_start_drag(spinbox, "word")
        _entry_select_to(spinbox, event.x)
        if spinbox._field.selection is not None:
            spinbox.icursor(spinbox._field.selection[0])
    spinbox._see_cursor()
    spinbox._redraw()


def _spinbox_triple(event: Event) -> None:
    """On an arrow, another step; in the text, select everything.

    Classic only - ttk binds no triple-click. The cursor goes to 0
    (``MouseSelect ... 0``).
    """
    spinbox = event.widget
    if _spinbox_arrow(spinbox, event):
        _spinbox_click(event)
        return
    if not _entry_selects(spinbox):
        return
    _entry_start_drag(spinbox, "line")
    _entry_select_to(spinbox, event.x)
    spinbox.icursor(0)
    spinbox._see_cursor()
    spinbox._redraw()


#: The tag options whose values are cells and therefore move text about.
#: Setting one of these is what makes a Text pay for margin resolution.
_MARGIN_OPTIONS = frozenset({"lmargin1", "lmargin2", "rmargin"})


def _common_head(old: list[str], new: list[str]) -> int:
    """How many lines at the start of ``old`` and ``new`` are the same.

    The first position where they differ, found by itertools and operator
    rather than a Python loop: one pass, stopping there. Typing into line n
    of thousands compares n lines.
    """
    unequal = map(operator.ne, old, new)
    return next(itertools.compress(itertools.count(), unequal), min(len(old), len(new)))


def _common_tail(old: list[str], new: list[str], limit: int) -> int:
    """How many lines at the end of ``old`` and ``new``, at most ``limit``,
    are the same; as :func:`_common_head`, from the end."""
    unequal = map(operator.ne, reversed(old), reversed(new))
    limit = max(0, limit)
    found = itertools.compress(itertools.count(), itertools.islice(unequal, limit))
    return next(found, limit)


def _spaced(
    rows: list[tuple[int, int, int]], above: int, between: int, below: int
) -> list[tuple[int, int, int]]:
    """One line's display rows, with Tk's spacing as blank rows among them.

    A blank row is its neighbour with the line number negated, so it holds
    no index - nothing matches a negative line - and still says which row
    a click on it means. ``spacing2`` is split as Tk splits it, the larger
    half above each continuation row and the rest below the row before:
    measured on Tk 9.0.2, spacing2 of 3 pixels put 1 under the first row
    and 2 over the second.
    """
    out: list[tuple[int, int, int]] = []
    last = len(rows) - 1
    for n, (line, start, stop) in enumerate(rows):
        gap = above if n == 0 else between - between // 2
        out.extend([(-line, start, stop)] * gap)
        out.append((line, start, stop))
        gap = below if n == last else between // 2
        out.extend([(-line, start, stop)] * gap)
    return out


#: Tk's ``-align`` for an embedded window or image, as its refusal lists them.
_EMBED_ALIGNS = ("baseline", "bottom", "center", "top")
#: Each kind's options and their defaults, as Tk 9.0.2's configure lists them.
_EMBED_OPTIONS: dict[str, dict[str, Any]] = {
    "window": {
        "align": "center",
        "create": "",
        "padx": 0,
        "pady": 0,
        "stretch": 0,
        "window": "",
    },
    "image": {"align": "center", "image": "", "name": "", "padx": 0, "pady": 0},
}


class _Embedded:
    """One window or image embedded in a Text: what its character stands for.

    The text holds a reserved character in its place, so it is one index as
    in Tk; this says how wide that character is, how tall its line has to
    be, and what to do when the character is deleted.
    """

    def __init__(self, owner: Text, kind: str, options: dict[str, Any]) -> None:
        self.owner = owner
        self.kind = kind
        self.options = options
        self.char = ""
        #: An image's name, unique in its text: its ``name`` or its image's,
        #: then ``#1`` and on, as Tk names them.
        self.image_name = ""

    @property
    def name(self) -> str:
        """What ``dump`` reports and an index may name: the window's path or
        the image's name."""
        if self.kind == "image":
            return self.image_name
        return str(self.options.get("window") or "")

    def widget(self) -> BaseWidget | None:
        """The embedded window, if there is one and it is alive."""
        path = str(self.options.get("window") or "")
        widget = self.owner.tk.widgets.get(path) if path else None
        return widget if isinstance(widget, BaseWidget) else None

    def image(self) -> Image | None:
        """The embedded image, if it still exists."""
        return self.owner.tk.images.get(str(self.options.get("image") or ""))

    def content(self) -> tuple[int, int]:
        """Its own size in cells, padding left out."""
        if self.kind == "image":
            image = self.image()
            return (image.width(), image.cell_height()) if image else (0, 0)
        widget = self.widget()
        if widget is None:
            return (0, 0)
        return (widget.winfo_reqwidth(), widget.winfo_reqheight())

    def _padding(self) -> tuple[int, int]:
        return (
            max(0, int(self.options.get("padx") or 0)),
            max(0, int(self.options.get("pady") or 0)),
        )

    def cells(self) -> int:
        """How wide its character is: its width and ``padx`` either side."""
        padx, _ = self._padding()
        return self.content()[0] + 2 * padx

    def rows(self) -> int:
        """How tall it is with ``pady`` above and below."""
        _, pady = self._padding()
        return self.content()[1] + 2 * pady

    def reach(self) -> tuple[int, int]:
        """The rows it needs above and below the text row it is on.

        Measured on Tk 9.0.2: a centred window taller than the text makes
        its line taller and the text sits in the middle. ``top`` hangs from
        the line's top, so the text is at the top; ``bottom`` and
        ``baseline`` stand on the text row.
        """
        height = self.rows()
        if height <= 1:
            return (0, 0)
        align = str(self.options.get("align") or "center")
        if align == "top" or (self.options.get("stretch") and align != "baseline"):
            return (0, height - 1)
        if align == "center":
            above = (height - 1) // 2
            return (above, height - 1 - above)
        return (height - 1, 0)

    def place(self, row: int, above: int, below: int) -> tuple[int, int]:
        """Its own top row and height, for a text row and the rows its line
        has above and below it."""
        _, pady = self._padding()
        height = self.content()[1]
        align = str(self.options.get("align") or "center")
        if self.options.get("stretch") and align != "baseline":
            return row - above + pady, max(0, above + below + 1 - 2 * pady)
        if align == "top":
            return row - above + pady, height
        if align == "bottom":
            return row + below - pady - height + 1, height
        if align == "center":
            return row - (height + 2 * pady - 1) // 2 + pady, height
        return row - (height + 2 * pady - 1) + pady, height

    def lost(self) -> None:
        """Its character was deleted: Tk destroys the window, and the image's
        name is free again."""
        EMBEDDED.pop(self.char, None)
        widget = self.widget()
        self.owner._release_window(self)
        if widget is not None and widget.winfo_exists():
            widget.destroy()


class _TagStyles(MutableMapping[str, dict[str, Any]]):
    """A Text's tag styles: its peers', with ``sel`` its own.

    Tk's manual: "the sel tag exists separately and independently in each
    peer", while every other tag's configuration is shared.
    """

    def __init__(self, shared: dict[str, dict[str, Any]]) -> None:
        self._shared = shared
        self._own: dict[str, dict[str, Any]] = {}

    def _table(self, name: str) -> dict[str, dict[str, Any]]:
        return self._own if name == "sel" else self._shared

    def __getitem__(self, name: str) -> dict[str, Any]:
        return self._table(name)[name]

    def __setitem__(self, name: str, value: dict[str, Any]) -> None:
        self._table(name)[name] = value

    def __delitem__(self, name: str) -> None:
        del self._table(name)[name]

    def __iter__(self) -> Iterator[str]:
        yield from self._own
        yield from (name for name in self._shared if name != "sel")

    def __len__(self) -> int:
        return len(self._own) + sum(1 for name in self._shared if name != "sel")


class Text(_Drawable, XView, YView):
    """An editable block of text, with marks and tags.

    Everything is addressed by index, written ``line.char`` with lines
    counting from 1. ``insert`` is the cursor, ``end`` is past everything, and
    ``sel.first``/``sel.last`` are the ends of the selection. Because Tk keeps
    a newline at the end of the text that no edit can remove, ``end`` on a
    one-line Text is ``2.0`` and ``get("1.0", "end")`` comes back with a
    newline nobody typed. That is kept, because tkinter code depends on it.

    ``wrap`` decides what a long line does: ``none`` scrolls sideways,
    ``char`` breaks wherever the width runs out, ``word`` at the last space
    that fits. Up and Down move by *display* lines, as they do in every
    editor, while ``insert linestart`` means the beginning of the real line.

    Sample output:
        # size: 40x8
        text = tk.Text(root, width=30, height=4)
        text.insert("1.0", "Some text, and some of it\\nin bold.")
        text.tag_configure("strong", font="TkDefaultFont 10 bold")
        text.tag_add("strong", "2.3", "2.7")
        text.pack()

    Options:
        autoseparators: Whether undo groups edits by itself.
        blockcursor: Whether the insertion cursor covers a whole character.
        endline: The line after the last one shown, to show part of a text.
        inactiveselectbackground: The selection's background while the text
            does not have the focus.
        insertunfocussed: How the insertion cursor looks without the focus:
            ``none``, ``hollow`` or ``solid``.
        maxundo: How many edits undo keeps; 0 is no limit.
        spacing1: Space above each line of the text.
        spacing2: Space between the display lines a wrapped line becomes.
        spacing3: Space below each line of the text.
        startline: The first line shown, to show part of a text.
        tabs: Where tab stops are, and how text lines up on them: ``"8 20
            right"``.
        tabstyle: ``tabular``, or ``wordprocessor`` - each tab goes to the next
            stop after the text before it.
        undo: Whether edits can be undone.
        wrap: ``none``, ``char`` or ``word``.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``exportselection``,
    ``font``, ``foreground``, ``height``, ``highlightbackground``,
    ``highlightcolor``, ``highlightthickness``, ``insertbackground``,
    ``insertborderwidth``, ``insertofftime``, ``insertontime``,
    ``insertwidth``, ``padx``, ``pady``, ``relief``, ``selectbackground``,
    ``selectborderwidth``, ``selectforeground``, ``setgrid``, ``state``,
    ``takefocus``, ``width``, ``xscrollcommand``, ``yscrollcommand``.

    Differences from tkinter:
        The insertion cursor is the terminal's own, so ``blockcursor``,
        ``insertunfocussed``, ``insertbackground``, ``insertborderwidth``,
        ``insertofftime``, ``insertontime`` and ``insertwidth`` draw nothing,
        and nor does ``selectborderwidth``. ``setgrid`` changes nothing, a
        terminal being a grid already. ``highlightbackground``,
        ``highlightcolor`` and ``highlightthickness`` are accepted and draw
        nothing: the focus is shown by markers instead. So is ``cursor``: the
        mouse pointer belongs to the terminal.

    Sample output (spacing1, spacing2, spacing3):
        # size: 40x12
        text = tk.Text(root, width=14, height=9, wrap="word", spacing1=1,
                       spacing2=1, spacing3=1)
        text.insert("1.0", "A line long enough to wrap.\\nAnother.")
        text.pack()

    Sample output (tabs, tabstyle):
        text = tk.Text(root, width=30, height=3, tabs="10 20 right",
                       tabstyle="wordprocessor")
        text.insert("1.0", "Name\\tQty\\tPrice\\nPears\\t4\\t1.20")
        text.pack()

    Sample output (wrap):
        # size: 50x7
        for wrap in ("char", "word"):
            text = tk.Text(root, width=12, height=4, wrap=wrap)
            text.insert("1.0", "Wrapped by character or by word")
            text.pack(side="left", padx=1)

    Sample output (inactiveselectbackground):
        text = tk.Text(root, width=24, height=2, inactiveselectbackground="blue")
        text.insert("1.0", "Selected, not focused")
        text.tag_add("sel", "1.0", "1.8")
        text.pack()
    """

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "state": _choices("state", "disabled", "normal"),
        "wrap": _choices("wrap", "char", "none", "word"),
        "height": _signed_distance,
        "padx": _screen_distance,
        "pady": _screen_distance,
        "width": _tcl_integer,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        **_INSERT_CURSOR_OPTIONS,
        **_SELECTION_OPTIONS,
        "blockcursor": 0,
        "inactiveselectbackground": _TerminalsOwn(),
        "insertunfocussed": "none",
        "autoseparators": True,
        # The store's lines this widget shows, from and up to; "" for no
        # limit. See _text_line. TkCurses-gm66.13.
        "endline": "",
        "exportselection": True,
        "font": "",
        "height": 24,
        # Undo groups kept, 0 for all; and blank rows above each line, between
        # the rows of a wrapped one, and below each. Tk's are pixels, and
        # these are rows. TkCurses-gm66.8.
        "maxundo": 0,
        "relief": "sunken",
        # Kept: a terminal is already a grid of characters. TkCurses-gm66.7.
        "setgrid": 0,
        "spacing1": 0,
        "spacing2": 0,
        "spacing3": 0,
        "startline": "",
        "state": "normal",
        "tabs": "",
        "tabstyle": "tabular",
        "takefocus": True,
        "undo": False,
        "width": 80,
        "wrap": "char",
        "xscrollcommand": None,
        "yscrollcommand": None,
    }

    #: What a tag can be given. Smaller than Tk's, but no longer by as much:
    #: this list used to exclude MARGINS, on the grounds that they have "no
    #: meaning in a character grid". That was wrong, and the correction is
    #: worth keeping visible. What has no meaning in a character grid is a
    #: PIXEL, not a margin - an indent of four cells is perfectly meaningful,
    #: and the project already maps every other screen distance to cells
    #: (padx, pady, place coordinates, winfo_fpixels at ten to the inch).
    #: Indentation in Tk is a tag feature rather than a tab feature, so
    #: dropping these dropped indentation altogether - TkCurses-wy7.
    #:
    #: Still left out, and correctly: ``offset`` is a sub-cell baseline shift
    #: for super- and subscripts. ``spacing1/2/3`` work in whole rows on the
    #: widget (TkCurses-gm66.8) and are not yet taken per tag. Borders and
    #: bitmaps have no cell equivalent.
    #: Setting one of those still fails loudly rather than quietly doing
    #: nothing.
    _TAG_OPTIONS: ClassVar[dict[str, Any]] = {
        "background": "",
        "foreground": "",
        "font": "",
        "justify": "",
        "lmargin1": 0,
        "lmargin2": 0,
        "lmargincolor": "",
        "rmargin": 0,
        "underline": False,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``width``, ``height``, ``wrap``, ``state``, ``undo``,
                ``autoseparators``, ``maxundo``, ``spacing1``, ``spacing2``,
                ``spacing3``, ``startline``, ``endline``, ``xscrollcommand``,
                ``yscrollcommand``, and the standard options.
        """
        # A peer shares its creator's store; see peer_create.
        creator: Text | None = kw.pop("_peer_of", None)
        self._buffer: TextBuffer = (
            TextBuffer() if creator is None else creator._buffer.peer()
        )
        #: The windows this text lays out, and what each was last given.
        self._embedded_windows: dict[BaseWidget, _Embedded] = {}
        self._embed_places: dict[BaseWidget, Rect | None] = {}
        # The view: its first row, kept as an index (see _top), and how far
        # it is scrolled sideways (see _left).
        self._top_row = 0
        self._top_extra = 0
        self._top_key: tuple[Any, ...] | None = None
        self._left_value = 0
        self._left_key: tuple[Any, ...] | None = None
        # The display rows last worked out (see _display_lines): the view
        # key they were made under, the rows, the buffer lines they were
        # made from, each line's own rows, and the row each line starts on.
        self._rows_key: tuple[Any, ...] | None = None
        self._rows: list[tuple[int, int, int]] = []
        self._rows_lines: list[str] = []
        self._line_rows: list[list[tuple[int, int, int]]] = []
        self._line_first: list[int] = []
        self._anchor: Index | None = None
        # tk::TextUpDownLine's Priv(prevPos) and Priv(textPosOrig): where Up
        # or Down last left the cursor, and the index whose column they keep.
        # Tk's are global; one per Text here, as the Listbox's are.
        self._prev_pos: Index | None = None
        self._pos_orig: Index | None = None
        self._dragging = False
        # What a drag extends by, whether it has moved off the press, where the
        # press and the pointer were, and the pending autoscroll. TkCurses-svtr.
        self._select_mode = "char"
        self._moved = False
        self._press_x = 0
        self._drag_at = (0, 0)
        self._autoscan: str | None = None
        # The screen cell the terminal's cursor goes in; see _draw_cursor.
        self._insert_at: tuple[int, int] | None = None
        # tkTextTag.c's curTagArrayPtr and BUTTON_DOWN: the tags of the
        # character last picked under the pointer, lowest priority first, and
        # whether a button is held, which stops the pick. See _pick_current.
        self._current_tags: list[str] = []
        self._button_down = False
        # scan mark: x, y, the sideways scroll then, and how far the drag has
        # scrolled down so far - tkTextDisp.c's scanMarkX, scanMarkY,
        # scanMarkXPixel and scanTotalYScroll.
        self._scan = (0, 0, 0, 0)
        # Peers share tag styles and their order, except sel's: Tk's manual,
        # and measured on Tk 9.0.2 - a sel colour set in one is not the other's.
        shared = self._buffer.shared
        self._tag_options = _TagStyles(shared.setdefault("tag_options", {}))
        self._tag_order: list[str] = shared.setdefault("tag_order", [])
        shared.setdefault("modified", False)
        shared.setdefault("margined", False)
        #: Whether ANY tag sets a margin. Almost none ever do, and resolving
        #: margins means asking which tags cover a row and walking the raise
        #: order - per row, inside wrapping, which is hot. Measured: doing it
        #: unconditionally took a Text repaint from under 25ms to 31.6ms and
        #: failed the redraw budget. This is the flag that keeps the common
        #: case free.
        try:
            super().__init__(master, cnf, name=name, **kw)
        except BaseException:
            # A refused option must not leave a view behind in the store.
            self._buffer.detach()
            raise
        self._apply_window()
        self._buffer.undo_enabled = self.getboolean(self._options["undo"])
        self._buffer.auto_separators = self._auto_separators
        self._buffer.max_undo = _as_int(self._options["maxundo"], 0)
        self._stops = parse_tabs(self._options["tabs"], self.winfo_fpixels)
        # current first, so that insert is the later of the two: dump lists
        # marks at one index newest first, and Tk's lists insert first.
        self._buffer.mark_set("current", "1.0")
        self._buffer.mark_set("insert", "1.0")
        # The selection is a tag like any other, which is why sel.first works
        # as an index. Its colours are the widget's select colours, and in Tk
        # each follows the other: see _SELECTION_TAG_OPTIONS.
        self.tag_configure(
            "sel",
            background=self._options["selectbackground"],
            foreground=self._options["selectforeground"],
        )
        self._apply_requested_size()
        self._install_class_bindings()
        self._buffer.owner = self

    @property
    def _modified(self) -> bool:
        """Tk's "has this been changed since it was last saved" flag.

        It is NOT the undo stack: it works with ``-undo false``, and clearing
        it leaves the stack alone. Peers share it, as they share the stack.
        """
        return bool(self._buffer.shared["modified"])

    # ------------------------------------------------------------- the view

    @property
    def _top(self) -> int:
        """The display row at the top of the view.

        Kept as an index, as Tk keeps it, and the row worked out from that
        whenever the text or its layout has changed: a hidden mark at the
        start of the top row, with left gravity, and how many rows of
        spacing above that row's text the view starts. So an edit above the
        view - by this widget, a peer or an undo - leaves the same text at
        the top, as a resize or a change of wrapping does; text inserted at
        the top's own index shows there; and a deletion across it takes the
        view to where the deletion began. Measured on Tk 9.0.2, every one.
        It used to be a row number, and the text slid under it.
        TkCurses-ntu4.
        """
        key = self._view_key()
        if key != self._top_key:
            anchor = self._buffer.view_top()
            if anchor is None:
                self._top_key = key
            else:
                rows = self._display_lines()
                # Set again, as Tk keeps the top it fills the view from:
                # measured, a view pulled up by a deletion stays there when
                # text is added below it, rather than going back down.
                self._set_top(self._row_at_anchor(anchor, rows), rows)
        return self._top_row

    @_top.setter
    def _top(self, row: int) -> None:
        self._set_top(row, self._display_lines())

    def _set_top(self, row: int, rows: list[tuple[int, int, int]]) -> None:
        """Put the view's top at a row of ``rows``, the display rows now."""
        row = max(0, min(row, len(rows) - 1))
        first = self._group_bounds(rows, row)[0]
        line, start, _ = rows[row]
        self._buffer.view_top(Index(abs(line), start))
        self._top_row, self._top_extra = row, row - first
        self._top_key = self._view_key()
        # Tk lays the view out again as it moves, and that is when the
        # sideways scroll is bounded by what is now on screen: measured, a
        # view scrolled 7 across, moved to the top where nothing is wider
        # than it, and back down, comes back at 0.
        self._clamp_left(rows)

    def _view_key(self) -> tuple[Any, ...]:
        """What the display rows are worked out from: the text, and how it
        is laid out.

        A tag's margins are the exception, held in tag ranges and tag
        options that no version follows, so a Text with any works its top
        out from the index at every reading: never equal to the last key.
        """
        return (
            self._buffer.version,
            self._view_size(),
            self._wrap_mode(),
            object() if self._margined else None,
            *(
                self._options[name]
                for name in ("spacing1", "spacing2", "spacing3", "tabs", "tabstyle")
            ),
        )

    @staticmethod
    def _group_bounds(rows: list[tuple[int, int, int]], row: int) -> tuple[int, int]:
        """The first and last of the rows that are one row of text and the
        spacing around it, for the row at ``row``."""
        line, start = abs(rows[row][0]), rows[row][1]
        first = last = row
        while first > 0 and (abs(rows[first - 1][0]), rows[first - 1][1]) == (
            line,
            start,
        ):
            first -= 1
        while last + 1 < len(rows) and (abs(rows[last + 1][0]), rows[last + 1][1]) == (
            line,
            start,
        ):
            last += 1
        return first, last

    def _row_at_anchor(self, anchor: Index, rows: list[tuple[int, int, int]]) -> int:
        """The top row, from where the anchor has got to: the row holding
        it, the spacing above as before, and the view kept full."""
        first, last = self._group_bounds(rows, self._row_of(anchor, rows))
        row = min(first + self._top_extra, last)
        return max(0, min(row, max(0, len(rows) - self._view_size()[1])))

    @property
    def _left(self) -> int:
        """How many columns the view is scrolled sideways.

        Never further than puts the end of the longest row IN VIEW at the
        right edge, as Tk's: measured on Tk 9.0.2, a view at column 40 of a
        line of 60 goes to 14 when the rows it shows are 30 long and to 0
        when they are short, and stays there when the long line comes back.
        It used to be measured over every line. Wrapped, always 0.
        TkCurses-8tjr.
        """
        if (self._top, self._top_key) != self._left_key:
            self._clamp_left(self._display_lines())
        return self._left_value

    @_left.setter
    def _left(self, value: int) -> None:
        self._left_value = value
        self._left_key = None

    def _clamp_left(self, rows: list[tuple[int, int, int]]) -> None:
        """Bound the sideways scroll by the rows now in view."""
        self._left_key = (self._top_row, self._top_key)
        if self._wrap_mode() != "none":
            self._left_value = 0
        else:
            room = max(0, self._widest_in_view(rows) - self._view_size()[0])
            self._left_value = max(0, min(self._left_value, room))

    def _widest_in_view(self, rows: list[tuple[int, int, int]] | None = None) -> int:
        """The width of the widest row on screen, margin and tabs included.

        ``rows`` are the display rows, when the caller has them and the top
        is already worked out from them.
        """
        if rows is None:
            self._top  # noqa: B018 - brings the top up to date first
            rows = self._display_lines()
        top = self._top_row
        widest = 0
        for line, start, stop in rows[top : top + self._view_size()[1]]:
            number = abs(line)
            text = self._row_text(number, start, stop)
            left, _ = self._row_margins(number, start)
            if "\t" in text:
                text = render(
                    text,
                    start=left,
                    stops=self._stops,
                    style=str(self._options["tabstyle"]),
                )
            widest = max(widest, left + cells(text))
        return widest

    @property
    def _margined(self) -> bool:
        """Whether ANY tag sets a margin; see __init__. Shared by peers, as
        the tags are."""
        return bool(self._buffer.shared["margined"])

    @_margined.setter
    def _margined(self, value: bool) -> None:
        self._buffer.shared["margined"] = value

    # ----------------------------------------------------------------- peers

    def peer_create(
        self, newPathName: str, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Make another Text showing this one's contents, at ``newPathName``.

        tkinter makes no Python object for the peer and neither does Tk -
        the path is all a program has - so the widget made here is reachable
        through :meth:`nametowidget`. Peers share the text, every tag but
        ``sel`` with its style, every mark but ``insert`` and ``current``,
        the undo stack and the modified flag; each has its own options.

        Measured on Tk 9.0.2: a new peer takes ``-startline``, ``-endline``,
        ``-undo``, ``-maxundo`` and ``-autoseparators`` from this widget, and
        everything else from the defaults.

        Raises:
            TclError: If the path is not a new widget's, or an option is bad.
        """
        path = str(newPathName)
        if not path.startswith("."):
            raise TclError(f'bad window path name "{path}"')
        parent_path, _, leaf = path.rpartition(".")
        try:
            parent = self.nametowidget(parent_path or ".")
        except KeyError:
            raise TclError(f'bad window path name "{parent_path}"') from None
        # Tk's message for "." too, whose last name is the empty one.
        if not leaf or leaf in parent.children:
            raise TclError(f'window name "{leaf}" already exists in parent')
        inherited = {
            option: self.cget(option)
            for option in ("startline", "endline", "undo", "maxundo", "autoseparators")
        }
        try:
            Text(parent, {**inherited, **(cnf or {})}, name=leaf, _peer_of=self, **kw)
        except BaseException:
            # Not even the object a failed constructor leaves behind: tkinter
            # makes none for a peer, so a refused one leaves nothing at all.
            parent.children.pop(leaf, None)
            raise

    def peer_names(self) -> tuple[str, ...]:
        """The paths of this widget's peers - not its own, as in Tk."""
        return tuple(
            view.owner._w for view in self._buffer.peers() if view.owner is not None
        )

    def _peer_widgets(self) -> list[Text]:
        return [view.owner for view in self._buffer.peers() if view.owner is not None]

    def _text_line(self, value: Any) -> int | str:
        """A ``-startline`` or ``-endline``, as Tk reads one.

        Measured on Tk 9.0.2 over ten lines: 1 to 11 are kept, and anything
        past them, 0 or negative is ``""``, no limit. 11 is the line ``end``
        names, so ``-startline 11`` shows nothing at all.
        """
        if value in ("", None):
            return ""
        line = _tcl_integer(self, value)
        return line if 1 <= line <= self._buffer.store_line_count() + 1 else ""

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """As every widget's, with the line range read as Tk reads it.

        Raises:
            TclError: If ``startline`` would come after ``endline`` - with
                Tk's message, and leaving both as they were.
        """
        resolved = super()._checked(given)
        for option in ("startline", "endline"):
            if option in resolved:
                resolved[option] = self._text_line(resolved[option])
        start = resolved.get("startline", self._window_option(0))
        end = resolved.get("endline", self._window_option(1))
        if start != "" and end != "" and start > end:
            raise TclError("-startline must be less than or equal to -endline")
        return resolved

    def _window_option(self, which: int) -> int | str:
        """``-startline`` or ``-endline`` as it is now.

        From the buffer, not from the options: the range moves with edits,
        and measured on Tk 9.0.2 the options read back where it has moved to.
        """
        line = self._buffer.window_lines()[which]
        return "" if line is None else line

    def _apply_window(self) -> None:
        start, end = self._options["startline"], self._options["endline"]
        self._buffer.set_window(start or None, end or None)

    def cget(self, key: str) -> Any:
        """As every widget's, with the line range read where it now is."""
        if key in ("startline", "endline"):
            return self._window_option(0 if key == "startline" else 1)
        return super().cget(key)

    def destroy(self) -> None:
        """As every widget's, leaving the text to any peers.

        Measured on Tk 9.0.2: destroying the widget a peer was made from
        leaves the peer, its text and its marks as they were.
        """
        alive = not self._destroyed
        store = self._buffer._store
        super().destroy()
        if alive:
            self._buffer.detach()
            if not store.views:
                # The last view of the text: nothing can show what it
                # embeds, so nothing need say how wide those are.
                for char in store.embeds:
                    EMBEDDED.pop(char, None)

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register the editing keys and the mouse for every Text here."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Any-Key>", _text_key)
        bind(name, "<<Copy>>", _text_copy)
        bind(name, "<<Cut>>", _text_cut)
        bind(name, "<<Paste>>", _text_paste)
        bind(name, "<<Clear>>", _text_clear)
        bind(name, "<<SelectAll>>", _text_select_all)
        bind(name, "<<SelectNone>>", _text_select_none)
        bind(name, "<<PasteSelection>>", _text_paste_selection)
        bind(name, "<<TerminalPaste>>", _text_terminal_paste)
        bind(name, "<<Undo>>", _text_undo)
        bind(name, "<<Redo>>", _text_redo)
        # Alt-z. Ours, not Tk's, whose X11 <<Redo>> is Control-Z alone. It was
        # the sequence Escape then z, which is what a terminal sends, until
        # the input layer read the two as the one key they are. TkCurses-r3og.
        bind(name, "<Alt-Key-z>", _text_redo)
        for sequence, (goes_to, selects) in _TEXT_NAVIGATION.items():
            bind(name, sequence, _text_navigation(goes_to, selects))
        # text.tcl: sideways a page, the cursor left where it is.
        bind(name, "<Control-Key-Prior>", lambda e: e.widget.xview_scroll(-1, "pages"))
        bind(name, "<Control-Key-Next>", lambda e: e.widget.xview_scroll(1, "pages"))
        bind(name, "<Button-1>", _text_press)
        bind(name, "<Double-Button-1>", _text_double)
        bind(name, "<Triple-Button-1>", _text_triple)
        bind(name, "<Control-Button-1>", _text_control_click)
        # Tk binds this to nothing, on purpose: without it a double-click
        # with Ctrl held would select a word, as a plain one does.
        bind(name, "<Control-Double-Button-1>", _do_nothing)
        for extend in _EXTEND_MODIFIERS:
            bind(name, f"<{extend}-Button-1>", _text_shift_press)
            bind(name, f"<Double-{extend}-Button-1>", _text_double_shift)
            bind(name, f"<Triple-{extend}-Button-1>", _text_triple_shift)
        # A drag arrives as Motion - curses reports motion-with-a-button and
        # there is no Button1 modifier to match against - and the implicit
        # grab keeps it with the widget that was pressed.
        bind(name, "<Motion>", _text_motion)
        bind(name, "<ButtonRelease-1>", _text_release)
        bind(name, "<Button-4>", _text_wheel)
        bind(name, "<Button-5>", _text_wheel)
        bind(name, "<FocusIn>", _text_refresh)
        bind(name, "<FocusOut>", _text_refresh)

    # --------------------------------------------------------------- options

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-measuring and repainting as the change requires."""
        given = _given(cnf, kw)
        if not given:
            for option in ("startline", "endline"):
                self._options[option] = self.cget(option)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if {"startline", "endline"} & set(given):
            self._apply_window()
        selection = self._tag_options["sel"]
        for widget_option, tag_option in _SELECTION_TAG_OPTIONS.items():
            selection[tag_option] = self._options[widget_option]
        if {"width", "height"} & set(given):
            self._apply_requested_size()
            self._invalidate_layout()
        if "undo" in given:
            # Turning it off does NOT throw the stack away: Tk keeps it, so
            # switching undo off and on again leaves the history intact.
            self._buffer.undo_enabled = self.getboolean(self._options["undo"])
            if self.tk.focus is self:
                self.tk.refresh_signal_keys()
        if "autoseparators" in given:
            self._buffer.auto_separators = self._auto_separators
        if "maxundo" in given:
            self._buffer.max_undo = _as_int(self._options["maxundo"], 0)
            self._buffer.trim_undo()
        if "tabs" in given:
            self._stops = parse_tabs(self._options["tabs"], self.winfo_fpixels)
        self._clamp_view()
        self._redraw()
        self._report_view()
        return result

    config = configure

    @property
    def _editable(self) -> bool:
        """True while the keyboard may change the contents."""
        return str(self._options["state"]) == "normal"

    def _apply_requested_size(self) -> None:
        """Ask for the configured rows and columns, plus border and padding."""
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        self._request_size(
            int(self._options["width"]) + 2 * int(self._options["padx"]) + edge,
            int(self._options["height"]) + 2 * int(self._options["pady"]) + edge,
        )

    # --------------------------------------------------------------- indices

    def index(self, spec: Any) -> str:
        """Resolve an index and return it as ``line.char``.

        Returns a string rather than an object, because that is what tkinter
        returns and what code written against it compares and slices.
        """
        return str(self._resolve(spec))

    def compare(self, first: Any, op: str, last: Any) -> bool:
        """Compare two indices with ``<``, ``<=``, ``==``, ``!=``, ``>``, ``>=``."""
        return self._buffer.compare(self._resolve(first), op, self._resolve(last))

    def _resolve(self, spec: Any) -> Index:
        """One index, including the ``@x,y`` form only the widget can answer."""
        if isinstance(spec, Index):
            return self._buffer.clamp(spec)
        text = str(spec).strip()
        if text.startswith("@"):
            position, _, rest = text[1:].partition(",")
            column, _, modifiers = rest.partition(" ")
            try:
                index = self._index_at_cell(int(position), int(column))
                if modifiers.strip():
                    return self._buffer.index(f"{index} {modifiers.strip()}")
            except (ValueError, TclError):
                # Quoted whole, as every other bad index is.
                raise TclError(f'bad text index "{spec}"') from None
            return index
        return self._buffer.index(text)

    # -------------------------------------------------------------- contents

    def get(self, first: Any, last: Any = None) -> str:
        """The text between two indices, or one character from ``first``."""
        if last is None:
            return self._buffer.get(self._resolve(first))
        return self._buffer.get(self._resolve(first), self._resolve(last))

    def insert(self, index: Any, chars: str, *args: Any) -> None:
        """Insert text before ``index``.

        As in Tk, the arguments after ``chars`` are a tag list, then more
        text and its tag list, and so on: ``insert("end", "a", "bold", "b",
        ("red", "big"))`` puts in ``a`` with ``bold`` and ``b`` with ``red``
        and ``big``. A tag list is a tuple, or a string of names separated
        by spaces. Text given a tag list, even an empty one, has exactly
        those tags; text given none has the tags on both sides of it.

        A disabled Text ignores it, silently, as Tk's does. The usual way to
        keep a Text read-only and still fill it is to set the state to
        ``normal`` around the insert.
        """
        # Tk's manual: "no insertions or deletions are allowed", and measured on
        # Tk 9.0.2 nothing is raised either. TkCurses-aah.
        if not self._editable:
            return
        self._insert_chunks(self._resolve(index), chars, args)
        self._after_edit()

    def _insert_chunks(self, at: Index, chars: Any, args: tuple[Any, ...]) -> None:
        """Insert ``chars`` and the text-and-tag-list pairs after it.

        Measured on Tk 9.0.2: ``insert 1.0 a t1 b t2`` tags ``a`` with t1
        and ``b`` with t2, a tag list "my tag" is two tags, and text given
        a list, even ``()``, loses the tags it would have taken from both
        sides. This took every argument for a tag name until TkCurses-mzj.
        """
        pieces = [chars, *args]
        for number in range(0, len(pieces), 2):
            text = str(pieces[number])
            end = self._buffer.insert(at, text)
            start = self._buffer.index_of(self._buffer.offset_of(end) - len(text))
            if number + 1 < len(pieces):
                given = pieces[number + 1]
                names = (
                    given.split()
                    if isinstance(given, str)
                    else [str(name) for name in given]
                )
                for name in self._buffer.tag_names():
                    self._buffer.tag_remove(name, start, end)
                for name in names:
                    self.tag_add(name, start, end)
            at = end

    def replace(self, index1: Any, index2: Any, chars: str, *args: Any) -> None:
        """Replace the text from ``index1`` up to ``index2`` with ``chars``,
        taking tag lists as :meth:`insert` does.

        One step for undo. The cursor stays where it is unless it was inside
        what was replaced, when it keeps its distance from the start, as far
        as the new text reaches - tkText.c's rule.

        Raises:
            TclError: If ``index2`` is before ``index1``, in Tk's words.
        """
        first, last = self._resolve(index1), self._resolve(index2)
        if self._buffer.compare(first, ">", last):
            raise TclError(f'index "{index2}" before "{index1}" in the text')
        if not self._editable:
            return
        cursor = self._buffer.mark_index("insert")
        keep: int | None = None
        if (
            cursor is not None
            and self._buffer.compare(first, "<", cursor)
            and self._buffer.compare(last, ">", cursor)
        ):
            length = sum(len(str(piece)) for piece in (chars, *args)[::2])
            keep = min(len(self._buffer.get(first, cursor)), length)
        start = self._buffer.offset_of(first)
        with self._buffer.grouped("replace"):
            self._buffer.delete(first, last)
            self._insert_chunks(self._buffer.index_of(start), chars, args)
        if keep is not None:
            self._buffer.mark_set("insert", self._buffer.index_of(start + keep))
        self._after_edit()

    _COUNT_OPTIONS = (
        "chars",
        "displaychars",
        "displayindices",
        "displaylines",
        "indices",
        "lines",
        "update",
        "xpixels",
        "ypixels",
    )

    def count(
        self, index1: Any, index2: Any, *options: str, return_ints: bool = False
    ) -> Any:
        """Count what lies between two indices: ``chars``, ``indices``,
        ``lines``, ``displaylines``, ``xpixels``, ``ypixels``,
        ``displaychars`` or ``displayindices``, ``indices`` when none is
        named. Negative when ``index1`` is after ``index2``. ``update`` is
        accepted and changes nothing.

        Shaped as tkinter shapes it: a tuple, one count per option, or None
        when the only count is 0; with ``return_ints``, a bare number for a
        single option.

        Raises:
            TclError: If an option is not one of those, in Tk's words.

        Differences from tkinter:
            Pixels are cells: ``xpixels`` counts columns and ``ypixels``
            rows, spacing included. Nothing is ever elided or embedded, so
            ``displaychars`` and ``displayindices`` count what ``chars``
            does.
        """
        wanted = []
        for option in options:
            word = f"-{option}"
            found = [
                name for name in self._COUNT_OPTIONS if f"-{name}".startswith(word)
            ]
            exact = f"-{option}"[1:] in self._COUNT_OPTIONS
            if not (exact or len(found) == 1) or word == "-":
                raise TclError(
                    f'bad option "{word}": must be -chars, -displaychars,'
                    " -displayindices, -displaylines, -indices, -lines, -update,"
                    " -xpixels, or -ypixels"
                )
            wanted.append(str(option) if exact else found[0])
        first, last = self._resolve(index1), self._resolve(index2)
        sign = 1
        if self._buffer.compare(first, ">", last):
            first, last, sign = last, first, -1
        counts = [name for name in wanted if name != "update"] or ["indices"]
        values = [sign * self._count(name, first, last) for name in counts]
        result: Any = values[0] if len(values) == 1 else tuple(values)
        # tkinter's own post-processing of Tk's answer, step for step.
        if not return_ints:
            if not result:
                result = None
            elif len(options) <= 1:
                result = (result,)
        return result

    def _count(self, name: str, first: Index, last: Index) -> int:
        """One of :meth:`count`'s measures, with ``first`` not after ``last``."""
        if name == "lines":
            return last.line - first.line
        if name == "displaylines":
            rows = self._text_rows()
            return self._row_of(last, rows) - self._row_of(first, rows)
        if name == "ypixels":
            rows = self._display_lines()
            return self._row_of(last, rows) - self._row_of(first, rows)
        if name == "xpixels":
            rows = self._display_lines()
            return (
                self._display_position(last, rows)[1]
                - self._display_position(first, rows)[1]
            )
        if name in ("indices", "displayindices"):
            # An embedded window or image is an index and not a character:
            # measured on Tk 9.0.2, -indices counts it and -chars does not.
            return self._buffer.offset_of(last) - self._buffer.offset_of(first)
        return len(self._buffer.get(first, last))

    def dump(
        self,
        index1: Any,
        index2: Any = None,
        command: Callable[..., Any] | None = None,
        **kw: Any,
    ) -> list[tuple[str, str, str]] | None:
        """What lies from ``index1`` up to ``index2``, as ``(key, value,
        index)`` triples: ``text``, ``mark``, ``tagon``, ``tagoff``,
        ``window`` and ``image``. One character's worth when ``index2`` is
        not given.

        ``text``, ``mark``, ``tag``, ``window`` and ``image`` set true choose
        which; none, or ``all``, means every kind. With ``command``, it is
        called with each triple and nothing is returned.

        Raises:
            TclError: If a keyword is not one Tk takes, in Tk's words.

        Differences from tkinter:
            Of several marks at one index, those
            with left gravity come first, then the rest most recently set
            first; Tk lists them in the order its storage holds them, which
            is usually that and can differ after edits.
        """
        kinds = ("all", "image", "mark", "tag", "text", "window")
        chosen = {key for key, value in kw.items() if value}
        for key in chosen:
            if key not in kinds:
                raise TclError(
                    f'bad option "-{key}": must be -all, -command, -image, -mark,'
                    " -tag, -text, or -window"
                )
        if not chosen or "all" in chosen:
            chosen = set(kinds)
        triples = self._buffer.dump(
            self._resolve(index1),
            self._resolve(index2) if index2 else None,
            text="text" in chosen,
            tags="tag" in chosen,
            marks="mark" in chosen,
            embeds=frozenset(chosen & {"window", "image"}),
        )
        found = [(key, value, str(index)) for key, value, index in triples]
        if command is None:
            return found
        for triple in found:
            command(*triple)
        return None

    # --------------------------------------------- embedded windows, images

    def window_create(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Embed a widget in the text at ``index``, where it takes one index
        and as many cells as it is wide.

        The text becomes the widget's geometry manager - ``winfo_manager``
        answers ``text`` - and moves it with the text and the view; a line
        holding a widget taller than one row grows to fit it. ``align`` puts
        it against the line: ``top``, ``center``, ``bottom`` or
        ``baseline``. ``padx`` and ``pady`` add space round it, ``stretch``
        makes it as tall as its line, and ``create``, a function answering a
        widget, makes one the first time it is shown if ``window`` is empty.
        The widget must be the text's child or a child of one of its
        ancestors. Deleting its index destroys it, and an undo does not bring
        it back, as in Tk.

        Sample output:
            # size: 40x6
            text = tk.Text(root, width=36, height=4)
            text.insert("1.0", "Press  to go on.")
            text.window_create("1.6", window=tk.Button(text, text="OK"))
            text.pack()

        Raises:
            TclError: If an option or its value is not one Tk takes, in Tk's
                words.

        Differences from tkinter:
            A window shows in the text it was created in, not in its peers,
            which keep its place blank. ``create`` is a Python function
            rather than a Tcl script.
        """
        self._embed("window", index, _given(cnf, kw))

    def image_create(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> str:
        """Embed an image in the text at ``index``, and answer its name.

        The image takes one index, is drawn on the half-cell plane - a cell
        to two pixel rows - and follows the image as it changes. Its name is
        ``name``, or the image's own, with ``#1``, ``#2`` and on added when
        that is already taken in this text, as Tk names them. ``align``,
        ``padx`` and ``pady`` are as for :meth:`window_create`.

        Sample output:
            # size: 40x6
            dot = tk.PhotoImage(width=4, height=4)
            dot.put("orange", to=(0, 0, 4, 4))
            text = tk.Text(root, width=36, height=4)
            text.insert("1.0", "A dot:  and more text.")
            text.image_create("1.7", image=dot)
            text.pack()

        Raises:
            TclError: If an option or its value is not one Tk takes, in Tk's
                words.
        """
        holder = self._embed("image", index, _given(cnf, kw))
        return holder.image_name

    def _embed(self, kind: str, index: Any, given: dict[str, Any]) -> _Embedded:
        """Make an embedded window or image, with its options checked first."""
        options = dict(_EMBED_OPTIONS[kind])
        for name, value in given.items():
            options[name] = self._embed_value(kind, name, value)
        at = self._resolve(index)
        holder = _Embedded(self, kind, options)
        if kind == "image":
            holder.image_name = self._unique_image_name(
                str(options["name"] or options["image"])
            )
        holder.char = self._buffer.embed(at, holder)
        EMBEDDED[holder.char] = holder.cells
        if kind == "image" and holder.image():
            image = holder.image()
            assert image is not None
            image._watch(self, self._embeds_changed)
        if kind == "window" and options["window"]:
            self._hold_window(holder)
        self._embeds_changed()
        return holder

    def _embed_value(self, kind: str, option: str, value: Any) -> Any:
        """An embedded window's or image's option, checked as Tk checks it.

        Raises:
            TclError: In Tk 9.0.2's words.
        """
        if option not in _EMBED_OPTIONS[kind]:
            raise TclError(f'unknown option "-{option}"')
        if option == "align":
            return _tcl_index(value, _EMBED_ALIGNS, "align")
        if option in ("padx", "pady"):
            return _signed_distance(self, value)
        if option == "stretch":
            return _tcl_boolean(self, value)
        if option == "image":
            return _image_name(self, value)
        if option == "window":
            return self._embeddable(value)
        if option == "name":
            return str(value)
        return value  # create: a function, called when it is first shown

    def _embeddable(self, value: Any) -> str:
        """A window that may be embedded here, as its path.

        Raises:
            TclError: ``bad window path name`` for no such widget, and
                ``can't embed`` for a toplevel, this text, or a widget not
                inside the text's master - Tk 9.0.2's words.
        """
        if value is None or value == "":
            return ""
        try:
            widget = value if isinstance(value, Misc) else self.nametowidget(str(value))
        except (KeyError, TclError):
            raise TclError(f'bad window path name "{value}"') from None
        parent = widget.master
        allowed = parent is not None and any(
            parent is ancestor for ancestor in self._ancestry()
        )
        if (
            widget is self
            or widget._is_toplevel
            or not allowed
            or not isinstance(widget, BaseWidget)
        ):
            raise TclError(f"can't embed {widget} in {self}")
        return str(widget)

    def _unique_image_name(self, base: str) -> str:
        """``base``, or ``base#1`` and on when this text has it already."""
        taken = set(self.image_names())
        if base not in taken:
            return base
        number = 1
        while f"{base}#{number}" in taken:
            number += 1
        return f"{base}#{number}"

    def _embedded(self, kind: str, index: Any) -> _Embedded:
        """The window or image embedded at an index.

        Raises:
            TclError: If there is none of that kind there, in Tk's words.
        """
        holder = self._buffer.embedded_at(self._resolve(index))
        if not isinstance(holder, _Embedded) or holder.kind != kind:
            raise TclError(f'no embedded {kind} at index "{index}"')
        return holder

    def window_cget(self, index: Any, option: str) -> Any:
        """One option of the window embedded at ``index``."""
        return self._embed_cget(self._embedded("window", index), option)

    def image_cget(self, index: Any, option: str) -> Any:
        """One option of the image embedded at ``index``."""
        return self._embed_cget(self._embedded("image", index), option)

    def _embed_cget(self, holder: _Embedded, option: str) -> Any:
        name = option.lstrip("-")
        if name not in holder.options:
            raise TclError(f'unknown option "-{name}"')
        return holder.options[name]

    def window_configure(
        self, index: Any, cnf: dict[str, Any] | str | None = None, **kw: Any
    ) -> Any:
        """Set options of the window embedded at ``index``, or with none
        given, answer them all as Tk's configure lists them."""
        return self._embed_configure(self._embedded("window", index), cnf, kw)

    window_config = window_configure

    def image_configure(
        self, index: Any, cnf: dict[str, Any] | str | None = None, **kw: Any
    ) -> Any:
        """Set options of the image embedded at ``index``, or with none given,
        answer them all as Tk's configure lists them."""
        return self._embed_configure(self._embedded("image", index), cnf, kw)

    def _embed_configure(
        self, holder: _Embedded, cnf: dict[str, Any] | str | None, kw: dict[str, Any]
    ) -> Any:
        defaults = _EMBED_OPTIONS[holder.kind]

        def entry(name: str) -> tuple[str, str, str, str, Any]:
            return (name, "", "", str(defaults[name]), holder.options[name])

        if isinstance(cnf, str):
            name = cnf.lstrip("-")
            if name not in defaults:
                raise TclError(f'unknown option "-{name}"')
            return entry(name)
        given = _given(cnf, kw)
        if not given:
            return {name: entry(name) for name in defaults}
        checked = {
            name: self._embed_value(holder.kind, name, value)
            for name, value in given.items()
        }
        if "window" in checked and checked["window"] != holder.options["window"]:
            self._release_window(holder)
        holder.options.update(checked)
        if checked.get("window"):
            self._hold_window(holder)
        if "image" in checked and holder.image() is not None:
            image = holder.image()
            assert image is not None
            image._watch(self, self._embeds_changed)
        self._embeds_changed()
        return None

    def window_names(self) -> tuple[str, ...]:
        """The paths of every window embedded in the text."""
        return tuple(
            holder.name
            for holder in self._buffer._store.embeds.values()
            if holder.kind == "window" and holder.name
        )

    def image_names(self) -> tuple[str, ...]:
        """The names of every image embedded in the text."""
        return tuple(
            holder.image_name
            for holder in self._buffer._store.embeds.values()
            if holder.kind == "image"
        )

    def _hold_window(self, holder: _Embedded) -> None:
        """Become the geometry manager of a holder's window, taking it from
        wherever it was - another annotation leaves holding no window, as
        measured on Tk 9.0.2."""
        widget = holder.widget()
        if widget is None:
            return
        owner = holder.owner
        for other in self._buffer._store.embeds.values():
            if (
                other is not holder
                and other.kind == "window"
                and other.name == holder.name
            ):
                other.owner._release_window(other)
                other.options["window"] = ""
        if widget._manager_container is not owner or widget._manager != "text":
            widget._leave_manager()
        if owner._embed_manager is None:
            owner._embed_manager = EmbedLayout(owner)
        owner._embed_manager.add(widget)
        owner._embedded_windows[widget] = holder
        widget._manager = "text"
        widget._manager_container = owner
        owner._embed_places.pop(widget, None)
        owner.tk.layout.invalidate(owner)

    def _release_window(self, holder: _Embedded) -> None:
        """Stop laying out a holder's window, unmapping it, and leave the
        holder's options alone - its caller decides what they say."""
        widget = holder.widget()
        if widget is None or self._embedded_windows.get(widget) is not holder:
            return
        # Forgotten first, so that _embedded_lost, which leaving the layout
        # calls, finds nothing to empty.
        del self._embedded_windows[widget]
        self._embed_places.pop(widget, None)
        widget._leave_manager()
        if widget._mapped:
            widget._unmap()

    def _embedded_lost(self, widget: BaseWidget) -> None:
        """A window left the text - packed elsewhere, or destroyed - and its
        annotation is left holding none, as Tk's is."""
        holder = self._embedded_windows.pop(widget, None)
        self._embed_places.pop(widget, None)
        if holder is not None:
            holder.options["window"] = ""
            self._embeds_changed()

    def _embeds_changed(self) -> None:
        """Repaint after an embedded window or image changed, and lay the
        windows out again."""
        self._redraw()
        self._report_view()
        if self._embedded_windows:
            self.tk.layout.invalidate(self)

    def _embedded_rect(self, widget: BaseWidget, area: Rect) -> Rect | None:
        """Where an embedded window goes on the screen, or None while its
        line is out of view."""
        del area  # the text's own area, inside its border and padding
        place = self._embed_place(widget)
        self._embed_places[widget] = place
        if place is None:
            return None
        drawing = self._text_area()
        return Rect(
            self.winfo_rootx() + drawing.x + place.x,
            self.winfo_rooty() + drawing.y + place.y,
            place.width,
            place.height,
        )

    def _embed_place(self, widget: BaseWidget) -> Rect | None:
        """A window's cells relative to the text area, or None."""
        holder = self._embedded_windows.get(widget)
        if holder is None:
            return None
        return self._embed_layout().get(holder.char)

    def _embed_layout(self) -> dict[str, Rect]:
        """Where each embedded object in or near the view is drawn, by its
        character, in cells relative to the text area - the part out of
        view included, so a window half scrolled off is still clipped
        rather than dropped."""
        store = self._buffer._store
        if not store.embeds:
            return {}
        area = self._text_area()
        rows = self._display_lines()
        reach = max((holder.rows() for holder in store.embeds.values()), default=1)
        first = max(0, self._top - reach)
        last = min(len(rows), self._top + area.height + reach)
        lines = self._buffer.lines
        style = str(self._options["tabstyle"])
        out: dict[str, Rect] = {}
        for number in range(first, last):
            line, start, stop = rows[number]
            if line <= 0 or line > len(lines):
                continue
            text = lines[line - 1][start:stop]
            placed = [
                (index, store.embeds[char])
                for index, char in enumerate(text)
                if char in store.embeds
            ]
            if not placed:
                continue
            above, below = self._row_reach(text)
            left, _ = self._row_margins(line, start)
            laid = columns_of(text, start=left, stops=self._stops, style=style)
            for index, holder in placed:
                padx = max(0, int(holder.options.get("padx") or 0))
                top, height = holder.place(number - self._top, above, below)
                width = holder.content()[0]
                if top + height <= 0 or top >= area.height:
                    continue
                column = laid[index] + padx - self._left
                if column + width <= 0 or column >= area.width:
                    continue
                out[holder.char] = Rect(column, top, width, height)
        return out

    def _row_reach(self, text: str) -> tuple[int, int]:
        """The rows a display row's embedded objects need above and below it."""
        embeds = self._buffer._store.embeds
        above = below = 0
        for char in text:
            holder = embeds.get(char)
            if holder is not None:
                up, down = holder.reach()
                above, below = max(above, up), max(below, down)
        return above, below

    def _follow_embeds(self) -> None:
        """Lay the embedded windows out again if any has moved."""
        if not self._embedded_windows:
            return
        laid = self._embed_layout()
        for widget, holder in self._embedded_windows.items():
            if self._embed_places.get(widget, False) != laid.get(holder.char):
                self.tk.layout.invalidate(self)
                return

    def _create_embedded_windows(self) -> None:
        """Run ``create`` for each window annotation that has none yet and
        is in view, as Tk does when one is about to be shown."""
        for char, holder in list(self._buffer._store.embeds.items()):
            if (
                holder.kind != "window"
                or holder.owner is not self
                or holder.options["window"]
                or not callable(holder.options["create"])
                or char not in self._embeds_in_view()
            ):
                continue
            made = holder.options["create"]()
            if made:
                holder.options["window"] = self._embeddable(made)
                self._hold_window(holder)

    def _embeds_in_view(self) -> set[str]:
        """The embedded characters on the rows in view."""
        rows = self._display_lines()
        area = self._text_area()
        lines = self._buffer.lines
        found: set[str] = set()
        for line, start, stop in rows[self._top : self._top + area.height]:
            if 0 < line <= len(lines):
                found.update(
                    char for char in lines[line - 1][start:stop] if is_embedded(char)
                )
        return found

    def _paint_images(self, area: Rect, attribute: int) -> None:
        """Draw each embedded image in view over the blank cells it owns."""
        store = self._buffer._store
        window = self._window
        if window is None or not any(
            holder.kind == "image" for holder in store.embeds.values()
        ):
            return
        dispatcher = CursesDispatcher.get()
        colors = self.tk.colors
        background = str(self._options["background"] or "black")
        for char, place in self._embed_layout().items():
            holder = store.embeds.get(char)
            image = None if holder is None else holder.image()
            if image is None:
                continue
            first_row = max(0, -place.y) * ROWS_PER_CELL
            last_row = (min(area.height, place.y + place.height) - place.y) * (
                ROWS_PER_CELL
            )
            first_column = max(0, -place.x)
            last_column = min(area.width, place.x + place.width) - place.x
            visible = image.lit((first_column, first_row, last_column, last_row))
            # Fitted to the colour pairs left, as a Label's picture is.
            palette = (
                _pair_palette(image, colors) if colors is not None else None
            ) or {}
            for (x, y), (glyph, fore, back) in compose(visible).items():
                column, row = place.x + x, place.y + y
                if not (0 <= row < area.height and 0 <= column < area.width):
                    continue
                look = (
                    attribute
                    if colors is None
                    else colors.attribute_for(
                        palette.get(fore, fore),
                        background if back is None else palette.get(back, back),
                    )
                )
                self._write_line(
                    dispatcher, window, area.y + row, area.x + column, glyph, look
                )

    def delete(self, first: Any, last: Any = None) -> None:
        """Delete a range, or one character from ``first``.

        Ignored while disabled, as :meth:`insert` is.
        """
        # TkCurses-aah.
        if not self._editable:
            return
        if last is None:
            self._buffer.delete(self._resolve(first))
        else:
            self._buffer.delete(self._resolve(first), self._resolve(last))
        self._after_edit()

    def _after_edit(self, *, typed: bool = False) -> None:
        """Repaint after a change, and bring the cursor into view if it was
        typed.

        Only then: a program's ``insert`` or ``delete`` leaves the view
        alone in Tk, measured on Tk 9.0.2, and text.tcl's typing bindings
        are what call ``see`` - ``tk::TextInsert`` among them. TkCurses-5co5.
        """
        if typed:
            self.see("insert")
        self._redraw_soon()
        self._report_view()
        self._set_modified(True)

    def _redraw_soon(self) -> None:
        """Repaint before the screen is next shown, once however many edits
        and calls to ``see`` ask.

        Tk's text widget repaints from an idle handler for the same reason:
        ``TextChanged`` (``tkTextDisp.c``) schedules ``DisplayText`` with
        ``Tcl_DoWhenIdle``. Each key typed here repainted at once, and twice
        - the edit, then ``see`` - at a cost that grows with the lines in
        view: a paste of 1000 characters onto one line took seconds.
        TkCurses-tcbj.21.
        """
        if self.tk.screen is None:
            self._redraw()
            return
        self.tk.repaint_due[self] = None

    def _set_modified(self, state: bool) -> None:
        """Move the modified flag, announcing it only when it moves.

        Measured against Tk: ``<<Modified>>`` fires on the CHANGE, not on
        the edit. Two inserts in a row give one event, and clearing the flag
        with ``edit_modified(False)`` gives another - it is an event about
        the flag, not about the text. This used to fire on every edit, so a
        handler that saved on it saved far more often than Tk would.
        """
        if state == self._modified:
            return
        self._buffer.shared["modified"] = state
        # Measured on Tk 9.0.2: every peer hears it, the one edited first.
        for widget in (self, *self._peer_widgets()):
            widget.event_generate("<<Modified>>")

    # -------------------------------------------------------------- geometry

    def dlineinfo(self, index: Any) -> tuple[int, int, int, int, int] | None:
        """Where the display line holding ``index`` is, in cells.

        Returns ``(x, y, width, height, baseline)`` relative to this widget,
        or None when that line is not on screen - which is what tkinter
        does, and what makes this worth asking rather than calculating: the
        answer depends on where the view has been scrolled to.

        ``height`` is always 1 and ``baseline`` is always 0. Tk measures
        both in pixels, and in a character grid the row is one cell tall
        with nothing below the letters, so 0 is the honest answer rather
        than a placeholder. ``width`` is the length of the line's text, not
        the width of the widget.

        A *display* line, note, not a logical one: a wrapped paragraph has
        one of these per row on screen.
        """
        found = self._row_and_column(index)
        if found is None:
            return None
        row, _, (line_start, line_stop) = found
        rows = self._display_lines()
        number = rows[row][0]
        left, _ = self._row_margins(number, line_start)
        area = self._text_area()
        y = area.y + (row - self._top)
        if not 0 <= y - area.y < area.height:
            return None
        # The row's width in COLUMNS, not in characters: a tab is wider than
        # one cell, and the indent is not part of the text. Tk reports the
        # indent in x - measured, it answered x=64 for an eight-column
        # margin - and the text's own width beside it.
        text = self._row_text(number, line_start, line_stop)
        width = (
            column_of(
                text,
                len(text),
                start=left,
                stops=self._stops,
                style=str(self._options["tabstyle"]),
            )
            - left
        )
        return (area.x + left - self._left, y, width, 1, 0)

    def bbox(self, index: Any) -> tuple[int, int, int, int] | None:
        """Where the character at ``index`` is, as ``(x, y, width, height)``.

        One cell, so the size is usually ``1, 1``. None when the character is
        not on screen, horizontally as well as vertically: a long line scrolled
        sideways puts characters out of view without putting their line out of
        view.

        The last character of a row - the newline, or the space a word wrap
        broke at - is the exception, because Tk draws it to the right edge of
        the view: its box runs from where it is to that edge.
        """
        # Measured on Tk 9.0.2: the box runs off to the left if need be, and
        # past the edge it is a box of no width on it. tk::TextScrollPages reads
        # it, so a cursor at the end of a line scrolled out of view to the right
        # pages to the right edge. TkCurses-5co5.
        found = self._row_and_column(index)
        if found is None:
            return None
        row, column, (start, stop) = found
        area = self._text_area()
        x = area.x + (column - self._left)
        y = area.y + (row - self._top)
        if not 0 <= y - area.y < area.height:
            return None
        resolved = self._resolve(index)
        last = self._row_last(resolved.line, start, stop)
        right = area.x + area.width
        if resolved.char == last:
            x = min(x, right)
            return (x, y, right - x, 1)
        if x >= right and self._wrap_mode() != "none":
            # A space hanging past the edge of a wrapped row: where it would
            # be, with the negative width Tk gives it.
            return (x, y, right - x, 1)
        if not 0 <= x - area.x < area.width:
            return None
        # As wide as the character is drawn: two cells for an ideograph.
        lines = self._buffer.lines
        text = lines[resolved.line - 1] if resolved.line <= len(lines) else ""
        character = text[resolved.char] if resolved.char < len(text) else "\n"
        return (x, y, char_cells(character) if character.isprintable() else 1, 1)

    def _row_and_column(self, index: Any) -> tuple[int, int, tuple[int, int]] | None:
        """The display row and column for an index, and that row's extent.

        The inverse of :meth:`_index_at_cell`, and deliberately written as
        such: the two have to agree, or a click and a bbox disagree about
        where the same character is. Both work in rows across the whole
        document; the caller takes ``_top`` and ``_left`` off to reach the
        screen.
        """
        rows = self._display_lines()
        if not rows:
            return None
        resolved = self._resolve(index)
        row, column = self._display_position(resolved, rows)
        _, start, stop = rows[row]
        return row, column, (start, stop)

    # ---------------------------------------------------------------- search

    def search(
        self,
        pattern: str,
        index: Any,
        stopindex: Any = None,
        forwards: bool | None = None,
        backwards: bool | None = None,
        exact: bool | None = None,
        regexp: bool | None = None,
        nocase: bool | None = None,
        count: Any = None,
        elide: bool | None = None,
    ) -> str:
        """Find ``pattern``, returning where it starts as ``line.char``.

        Returns the empty string when there is no match, which is what
        tkinter returns and what calling code tests for.

        Args:
            pattern: Text to find, or a regular expression with ``regexp``.
            index: Where to start looking.
            stopindex: Where to give up. Without it the search WRAPS -
                forwards runs off the end and round to the beginning, and
                backwards the other way. This surprises people, and it is
                what Tk does.
            forwards: Search towards the end. The default.
            backwards: Search towards the beginning instead.
            exact: Match the pattern literally. The default.
            regexp: Match it as a regular expression, **line by line** - so
                ``^`` and ``$`` are the edges of a line and nothing matches
                across a newline. An exact search has no such limit and
                will happily match across one.
            nocase: Ignore case.
            count: A variable to put the match length in, in characters.
                Anything with a ``set`` method, as in tkinter, where it is
                usually an ``IntVar``.
            elide: Accepted and ignored. Tk skips elided text with this;
                nothing is ever elided here because there is no ``elide``
                tag option, so there is nothing for it to do. Taking it and
                doing nothing is better than rejecting a call that would
                work in tkinter.

        Passing both ``exact`` and ``regexp`` is not an error: ``regexp``
        wins, which is measured behaviour rather than a choice made here.
        """
        del forwards, exact, elide  # Defaults; named so the signature matches.
        found = self._buffer.search(
            pattern,
            self._resolve(index),
            None if stopindex is None else self._resolve(stopindex),
            backwards=bool(backwards),
            regexp=bool(regexp),
            nocase=bool(nocase),
        )
        if found is None:
            return ""
        where, length = found
        if count is not None:
            count.set(length)
        return str(where)

    # ------------------------------------------------------------------ undo

    def edit_undo(self) -> tuple[str, ...]:
        """Take back the most recent group of edits, and answer the ranges
        they changed, flat - Tk 9's ``edit undo``.

        As each edit is taken back, the cursor of the Text that made it - this
        one or a peer - goes to where it happened and is brought into view:
        before text that went, after text that comes back.

        With ``undo`` off this does nothing and raises nothing. A disabled Text
        changes nothing, but still raises on an empty stack. ``()`` where
        nothing is done, as tkinter answers ``""``.

        Raises:
            TclError: If there is nothing to undo, as tkinter does.

        Differences from tkinter:
            A disabled Text keeps its undo history as it was. Tk 9.0.2 takes
            the group off the stack while refusing its edits, so a later redo
            applies the same edit twice, and answers the ranges it refused.
        """
        # Measured on Tk 9.0.2: undoing an insertion of three lines at 1.0, made
        # with the cursor at 30.0, leaves the cursor at 1.0 and the view there;
        # a peer's edit undone here moves the peer's cursor and not this one's.
        # Ours left the cursor where it was and scrolled to it. TkCurses-2sbq.
        #
        # Tk treats "undo is off" and "undo is on but the stack is empty" as two
        # different situations, and only the second is an error. Tk's disabled
        # undo turned "hello world" into "hello world world" after a redo;
        # copying that would copy a defect. TkCurses-aah.
        if not self.getboolean(self._options["undo"]):
            return ()
        if not self._editable:
            if not self._buffer.can_undo:
                raise TclError("nothing to undo")
            return ()
        changed = self._buffer.edit_undo(_see_insert)
        if changed is None:
            raise TclError("nothing to undo")
        self._after_undo()
        return tuple(map(str, changed))

    def edit_redo(self) -> tuple[str, ...]:
        """Put back the most recently undone group, and answer the ranges
        it changed, as :meth:`edit_undo` does.

        Raises:
            TclError: If there is nothing to redo, as tkinter does.

        The cursor of each edit's Text goes to where it happened: after
        text put back, before text taken out again. Disabled, the same as
        :meth:`edit_undo`: nothing changes, the stack included, and an empty
        stack still raises.
        """
        if not self.getboolean(self._options["undo"]):
            return ()
        if not self._editable:
            if not self._buffer.can_redo:
                raise TclError("nothing to redo")
            return ()
        changed = self._buffer.edit_redo(_see_insert)
        if changed is None:
            raise TclError("nothing to redo")
        self._after_undo()
        return tuple(map(str, changed))

    def _after_undo(self) -> None:
        """Repaint after the stack changed the text: the cursors it moved
        were each brought into view as they moved (see _see_insert), and
        the scrollbars no longer describe what is there."""
        self._redraw()
        self._report_view()
        self._set_modified(True)

    def edit_separator(self) -> None:
        """Break the undo group, so the next edit undoes on its own."""
        self._buffer.edit_separator()

    def edit_reset(self) -> None:
        """Throw away the undo and redo history, keeping the text."""
        self._buffer.edit_reset()

    def edit_modified(self, arg: Any = None) -> int | None:
        """Read the modified flag, or set it.

        Returns 0 or 1 rather than a bool, which is what tkinter returns and
        what code written against it compares against.
        """
        if arg is None:
            return int(self._modified)
        self._set_modified(self.getboolean(arg))
        return None

    _EDIT_OPTIONS = (
        "canundo",
        "canredo",
        "modified",
        "redo",
        "reset",
        "separator",
        "undo",
    )

    def edit(self, *args: Any) -> Any:
        """Tk's ``edit`` command: ``canundo``, ``canredo``, ``modified``,
        ``redo``, ``reset``, ``separator`` or ``undo``, then its arguments.

        ``canundo`` and ``canredo`` answer 1 or 0, and are 0 while ``undo``
        is off. The others do what :meth:`edit_modified`, :meth:`edit_redo`,
        :meth:`edit_reset`, :meth:`edit_separator` and :meth:`edit_undo` do.

        Raises:
            TclError: If the option is not one of those, or has the wrong
                number of arguments, in Tk's words.
        """
        if not args:
            raise TclError(f'wrong # args: should be "{self._w} edit option ?arg ...?"')
        word = str(args[0])
        found = [name for name in self._EDIT_OPTIONS if name.startswith(word)]
        name = (
            word
            if word in self._EDIT_OPTIONS
            else (found[0] if word and len(found) == 1 else "")
        )
        if not name:
            raise TclError(
                f'bad edit option "{word}": must be canundo, canredo, modified,'
                " redo, reset, separator, or undo"
            )
        rest = args[1:]
        if name == "modified":
            if len(rest) > 1:
                raise TclError(
                    f'wrong # args: should be "{self._w} edit modified ?boolean?"'
                )
            if not rest:
                return self.edit_modified()
            self.edit_modified(rest[0])
            return ""
        if rest:
            raise TclError(f'wrong # args: should be "{self._w} edit {name}"')
        undoing = self.getboolean(self._options["undo"])
        if name == "canundo":
            return int(undoing and self._buffer.can_undo)
        if name == "canredo":
            return int(undoing and self._buffer.can_redo)
        if name == "undo":
            return self.edit_undo()
        if name == "redo":
            return self.edit_redo()
        if name == "reset":
            self.edit_reset()
        else:
            self.edit_separator()
        return ""

    def debug(self, boolean: Any = None) -> bool | None:
        """Read or set the debug flag, which Tk's text widgets share.

        Tk checks its text storage's consistency while it is on. Here it is
        kept and answered, and checks nothing: there is no B-tree to check.
        """
        if boolean is None:
            return bool(self.tk.text_debug)
        self.tk.text_debug = self.getboolean(boolean)
        return None

    def _claimed_signal_keys(self) -> set[str]:
        """The tty's signal keys this Text needs while it has the focus.

        Control-z, the suspend key, when ``<<Undo>>`` or ``<<Redo>>`` is on
        it and ``-undo`` is true: undo is what a person typing in a Text
        means by it, and suspend comes back the moment the focus leaves.
        A Text without undo leaves suspend alone. TkCurses-5t48.
        """
        if not self.getboolean(self._options["undo"]):
            return set()
        return {
            pattern.detail
            for virtual in ("<<Undo>>", "<<Redo>>")
            for pattern in self.tk.virtual_events.info(virtual)
            if isinstance(pattern, EventPattern)
            and pattern.type == "Key"
            and pattern.modifiers == MOD_CTRL
            and pattern.detail in SIGNAL_KEYS
        }

    @property
    def _auto_separators(self) -> bool:
        return bool(self.getboolean(self._options["autoseparators"]))

    def _separate_if_asked(self) -> None:
        """``if {[%W cget -autoseparators]} {%W edit separator}``, which
        text.tcl's bindings say wherever an operation should end the undo
        group: moving the cursor, a click, clearing the selection, after
        Return. A switch between inserting and deleting ends it as well, in
        the store, programmatic edits included - see ``_Store.record``.
        Ours kept that switch per widget, on the key paths only, and also
        broke the group before a newline, which Tk does not: typing
        ``abc``, Return, ``def`` undoes ``def`` and then ``abc`` with its
        newline. TkCurses-hy15.
        """
        if self._auto_separators:
            self._buffer.edit_separator()

    # ----------------------------------------------------------------- marks

    def mark_set(self, name: str, index: Any) -> None:
        """Put a mark at an index.

        The view stays where it is, even for ``insert``, as Tk's does: call
        :meth:`see` to bring the mark into view.
        """
        # text.tcl's bindings call see themselves. Measured on Tk 9.0.2.
        # TkCurses-5co5.
        self._buffer.mark_set(name, self._resolve(index))
        self._redraw()

    def mark_unset(self, *names: str) -> None:
        """Remove marks."""
        self._buffer.mark_unset(*names)
        self._redraw()

    def mark_names(self) -> tuple[str, ...]:
        """Every mark."""
        return self._buffer.mark_names()

    def mark_gravity(self, name: str, direction: str | None = None) -> str:
        """Read or set which side of an insertion a mark ends up on."""
        return self._buffer.mark_gravity(name, direction)

    def mark_next(self, index: Any) -> str | None:
        """The first mark after an index."""
        return self._buffer.mark_next(self._resolve(index))

    def mark_previous(self, index: Any) -> str | None:
        """The last mark before an index."""
        return self._buffer.mark_previous(self._resolve(index))

    # ------------------------------------------------------------------ tags

    def tag_add(self, name: str, first: Any, last: Any = None) -> None:
        """Tag a range."""
        self._note_tag(name)
        if last is None:
            self._buffer.tag_add(name, self._resolve(first))
        else:
            self._buffer.tag_add(name, self._resolve(first), self._resolve(last))
        if name == "sel":
            self._claim_primary()
        self._redraw()

    def tag_remove(self, name: str, first: Any, last: Any = None) -> None:
        """Untag a range."""
        if last is None:
            self._buffer.tag_remove(name, self._resolve(first))
        else:
            self._buffer.tag_remove(name, self._resolve(first), self._resolve(last))
        self._redraw()

    def tag_delete(self, *names: str) -> None:
        """Forget tags entirely, ranges, options and all."""
        self._buffer.tag_delete(*names)
        for name in names:
            self._tag_options.pop(name, None)
            if name in self._tag_order:
                self._tag_order.remove(name)
            # Tk forgets a deleted tag's bindings with it.
            tag = self._tag_binding_tag(name)
            for sequence in self.tk.bindings.sequences(tag):
                self.tk.bindings.unbind(tag, parse_sequence(sequence))
        self._current_tags = [name for name in self._current_tags if name not in names]
        self._redraw()

    def tag_names(self, index: Any = None) -> tuple[str, ...]:
        """Every tag, or only those covering one index."""
        if index is None:
            return tuple(self._tag_order)
        return self._buffer.tag_names(self._resolve(index))

    def _has_copyable_selection(self) -> bool:
        return bool(self.tag_ranges("sel"))

    def tag_ranges(self, name: str) -> list[str]:
        """Every range of a tag, flat, as ``line.char`` strings."""
        return [str(index) for index in self._buffer.tag_ranges(name)]

    def tag_nextrange(
        self, name: str, first: Any, last: Any = None
    ) -> tuple[str, str] | tuple[()]:
        """The first range of a tag at or after an index, or ``()``."""
        found = self._buffer.tag_nextrange(
            name, self._resolve(first), None if last is None else self._resolve(last)
        )
        return () if found is None else (str(found[0]), str(found[1]))

    def tag_prevrange(
        self, name: str, first: Any, last: Any = None
    ) -> tuple[str, str] | tuple[()]:
        """The last range of a tag before an index, or ``()``."""
        found = self._buffer.tag_prevrange(
            name, self._resolve(first), None if last is None else self._resolve(last)
        )
        return () if found is None else (str(found[0]), str(found[1]))

    def tag_configure(
        self, name: str, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> Any:
        """Set how a tag looks, or read what it is set to.

        Raises:
            TclError: If an option is not one a tag accepts here.
        """
        self._note_tag(name)
        options = self._tag_options[name]
        given = _given(cnf, kw)
        if not cnf and not kw:
            return dict(options)
        if not given:  # every option None, which tkinter drops
            return None
        for option, value in given.items():
            resolved = _OPTION_ALIASES.get(option, option)
            if resolved not in self._TAG_OPTIONS:
                raise TclError(f'unknown option "-{option}"')
            if resolved in _TAG_COLOUR_OPTIONS:
                # Refused here, as Tk refuses it, rather than when the text is
                # drawn - where it broke the window's layout. TkCurses-f760.
                _colour_or_terminals(self, value)
            options[resolved] = value
            if name == "sel" and resolved in _SELECTION_WIDGET_OPTIONS:
                self._options[_SELECTION_WIDGET_OPTIONS[resolved]] = value
            if resolved in _MARGIN_OPTIONS and value not in (0, "", None):
                # Latches on rather than being recomputed: a margin set and
                # then cleared is rare, and paying for the scan once is
                # cheaper than checking every tag on every configure.
                self._margined = True
        self._redraw()
        return None

    tag_config = tag_configure

    def tag_cget(self, name: str, option: str) -> Any:
        """One of a tag's options.

        Raises:
            TclError: If the tag or the option does not exist.
        """
        if name not in self._tag_options:
            raise TclError(f'tag "{name}" is not defined')
        resolved = _OPTION_ALIASES.get(option, option)
        if resolved not in self._TAG_OPTIONS:
            raise TclError(f'unknown option "-{option}"')
        return self._tag_options[name][resolved]

    def tag_raise(self, name: str, above: str | None = None) -> None:
        """Move a tag up the priority order, so it draws over the others."""
        self._reorder(name, above, offset=1)

    def tag_lower(self, name: str, below: str | None = None) -> None:
        """Move a tag down the priority order."""
        self._reorder(name, below, offset=0)

    #: The kinds of event a tag can be bound to, by pattern type: Tk refuses
    #: the rest.
    _TAG_EVENT_TYPES = frozenset(
        ("Key", "KeyRelease", "Button", "ButtonRelease", "Motion", "Enter", "Leave")
    )

    def _tag_binding_tag(self, name: str) -> str:
        """Where a text tag's bindings are kept: peers share them, as Tk's
        do, and no widget's binding tags can name it."""
        shared = self._buffer.shared
        if "bindings" not in shared:
            shared["bindings"] = next(_TEXT_BINDING_IDS)
        return f"\0text-tag\0{shared['bindings']}\0{name}"

    def tag_bind(
        self,
        tagName: str,
        sequence: str | None = None,
        func: Callable[[Event], Any] | None = None,
        add: bool | str | None = None,
    ) -> Any:
        """Bind an event on the characters a tag covers.

        A mouse event reaches the tags of the character under the pointer,
        which also hear ``<Enter>`` and ``<Leave>`` as the pointer moves onto
        and off them; a key event reaches the tags under the pointer, or,
        with none there, those at the insertion cursor. They run before the
        widget's own bindings, lowest priority tag first, as in Tk.

        Returns, as :meth:`Misc.bind` does, a handle :meth:`tag_unbind`
        takes, the callbacks bound to ``sequence``, or the sequences bound.

        Raises:
            TclError: For an event other than a key, button, motion, enter,
                leave or virtual one, in Tk's words.
        """
        tag = self._tag_binding_tag(tagName)
        if sequence is None:
            return self.tk.bindings.sequences(tag)
        pattern = parse_sequence(sequence)
        if func is None:
            return tuple(
                binding.func for binding in self.tk.bindings.bindings(tag, pattern)
            )
        if not pattern.is_virtual and pattern.type not in self._TAG_EVENT_TYPES:
            raise TclError(
                "requested illegal events; only key, button, motion, enter, leave,"
                " and virtual events may be used"
            )
        self._note_tag(tagName)
        return self.tk.bindings.bind(tag, pattern, func, add=bool(add))

    def tag_unbind(
        self,
        tagName: str,
        sequence: str,
        funcid: str | None = None,
    ) -> None:
        """Remove a tag's bindings for ``sequence``, or the one ``funcid`` names."""
        self.tk.bindings.unbind(
            self._tag_binding_tag(tagName), parse_sequence(sequence), funcid
        )

    def _dispatch(self, event: Event, patterns: list[EventPattern]) -> bool:
        """Run the tag bindings first, then the widget's, as Tk's text
        widget does from its own event handler (tkTextTag.c's
        TkTextBindProc)."""
        if not self._destroyed and patterns:
            self._tag_dispatch(event, patterns)
        return super()._dispatch(event, patterns)

    def _tag_dispatch(self, event: Event, patterns: list[EventPattern]) -> None:
        """TkTextBindProc, step for step."""
        kind = patterns[0].type
        repick = False
        if kind == "Button":
            self._button_down = True
        elif kind == "ButtonRelease":
            self._button_down = False
            repick = True
        elif kind in ("Enter", "Leave"):
            self._button_down = False
            self._pick_current(event, leaving=kind == "Leave")
            return
        elif kind == "Motion":
            self._pick_current(event)
        if self._current_tags:
            self._run_tag_bindings(list(self._current_tags), event, patterns)
        elif kind in ("Key", "KeyRelease"):
            # Measured, and so says the comment in Tk's: "Key events fire
            # independently of the 'current' mark and use the 'insert' mark."
            self._run_tag_bindings(self._sorted_tags("insert"), event, patterns)
        if repick and not self._destroyed:
            self._pick_current(event)

    def _sorted_tags(self, index: Any) -> list[str]:
        """The tags at an index, lowest priority first, as Tk's SortTags."""
        order = {name: rank for rank, name in enumerate(self._tag_order)}
        return sorted(
            self._buffer.tag_names(self._resolve(index)), key=lambda n: order.get(n, -1)
        )

    def _pick_current(self, event: Event, *, leaving: bool = False) -> None:
        """TkTextPickCurrent: put ``current`` on the character under the
        pointer, tell the tags it left that the pointer left, and the tags
        it came to that it came. Nothing while a button is held - the
        simulated grab - and no tags past a line's end."""
        if self._button_down or self._destroyed:
            return
        index: Index | None = None
        new: list[str] = []
        if not leaving:
            index, nearby = self._pointer_index(int(event.x), int(event.y))
            if not nearby:
                new = self._sorted_tags(index)
        old = self._current_tags
        gone = [name for name in old if name not in new]
        came = [name for name in new if name not in old]
        if gone:
            self._run_tag_bindings(
                gone, _crossing(event, "Leave"), [EventPattern(type="Leave")]
            )
        if index is not None:
            self._buffer.mark_set("current", index)
        self._current_tags = new
        if came and not self._destroyed:
            self._run_tag_bindings(
                came, _crossing(event, "Enter"), [EventPattern(type="Enter")]
            )

    def _pointer_index(self, x: int, y: int) -> tuple[Index, bool]:
        """The index at a cell, and whether the cell is only near it - past
        the end of its row, below the text, or outside the text area - as
        TkTextPixelIndex's ``nearby``."""
        index = self._index_at_cell(x, y)
        area = self._text_area()
        width, height = self._view_size()
        if not (area.x <= x < area.x + width and area.y <= y < area.y + height):
            return index, True
        rows = self._display_lines()
        row = self._top + (y - area.y)
        if row >= len(rows) or rows[row][0] <= 0:
            return index, True
        line, start, stop = rows[row]
        end = self._column_in(line, start, stop, self._row_last(line, start, stop))
        return index, x - area.x + self._left >= end

    def _run_tag_bindings(
        self, names: list[str], event: Event, patterns: list[EventPattern]
    ) -> None:
        """Run what is bound on each of ``names``, as one binding tag each,
        the virtual events the event raises included."""
        if not names:
            return
        all_patterns = list(patterns)
        raised: dict[str, Any] = {}
        for pattern in patterns:
            if not pattern.is_virtual:
                for virtual, rank in self.tk.virtual_events.raised_ranks(
                    pattern
                ).items():
                    raised[virtual] = rank
                    all_patterns.append(EventPattern(type="Virtual", detail=virtual))
        self.tk.bindings.dispatch(
            tuple(self._tag_binding_tag(name) for name in names),
            event,
            all_patterns,
            raised,
        )

    def _reorder(self, name: str, other: str | None, *, offset: int) -> None:
        """Shared by tag_raise and tag_lower."""
        self._note_tag(name)
        self._tag_order.remove(name)
        if other is None:
            self._tag_order.append(name) if offset else self._tag_order.insert(0, name)
        else:
            self._note_tag(other)
            self._tag_order.insert(self._tag_order.index(other) + offset, name)
        self._redraw()

    def _note_tag(self, name: str) -> None:
        """Record a tag's existence and its place in the priority order."""
        if name not in self._tag_options:
            self._tag_options[name] = dict(self._TAG_OPTIONS)
            # Known to the buffer too, ranges or none: a tag that exists and
            # covers nothing has a ``.first`` error of its own in Tk.
            self._buffer.tag_add(name, "1.0", "1.0")
        if name not in self._tag_order:
            # A peer's sel is new to it and already in the shared order.
            self._tag_order.append(name)

    # ------------------------------------------------------------- selection

    def _select(self, first: Any, last: Any) -> None:
        """Replace the selection with one range, dropping it if it is empty."""
        self._buffer.tag_remove("sel", "1.0", "end")
        start, stop = self._resolve(first), self._resolve(last)
        if start != stop:
            self._buffer.tag_add("sel", start, stop)
        self._claim_primary()

    def _claim_primary(self) -> None:
        """Take PRIMARY while something is selected and ``exportselection`` is on.

        The option was stored and never read (TkCurses-9e8): a Text's
        selection never reached PRIMARY, so selecting in a Text did not clear
        an Entry's selection, as Tk's does, and the middle button could not
        paste it. Measured on Tk 9.0.2 between Entry and Text, both ways.
        """
        if not self.tag_ranges("sel") or not self.getboolean(
            self._options["exportselection"]
        ):
            return
        selections = self.tk.selections
        selections.own(self, PRIMARY, lost=self._lost_primary)
        selections.handle(self, self._primary_selection, PRIMARY)

    def _lost_primary(self) -> None:
        """Another widget took PRIMARY: drop this one's selection, as Tk does."""
        self._buffer.tag_remove("sel", "1.0", "end")
        self._redraw()

    def _primary_selection(self, *_args: Any) -> str:
        """The selected text, for whoever reads PRIMARY; raises with none."""
        found = self._selection_range()
        if found is None:
            raise TclError(f"{PRIMARY} selection doesn't exist or form unknown")
        return str(self._buffer.get(*found))

    def _selection_range(self) -> tuple[Index, Index] | None:
        """The selection, or None."""
        ranges = self._buffer.tag_ranges("sel")
        return (ranges[0], ranges[-1]) if ranges else None

    def _delete_selection(self) -> bool:
        """Delete the selected text. True if there was any."""
        found = self._selection_range()
        if found is None:
            return False
        self._buffer.mark_set("insert", found[0])
        self._buffer.delete(found[0], found[1])
        self._anchor = None
        return True

    # ------------------------------------------------------------- editing

    def _row_edge(self, index: Index, *, end: bool) -> Index:
        """``display linestart`` and ``display lineend``: the start or end of
        the display row an index is on.

        The end of a row that wraps is its last character, since the index
        after that starts the next row: the space a word wrap broke at, or
        the last letter of a word broken across rows. Measured on Tk 9.0.2,
        End at 5.10 in a 16-column ``fourth_word-joined end`` goes to 5.15.
        The end of a line's last row is the end of the line, spaces and all.
        """
        rows = self._display_lines()
        line, start, stop = rows[self._row_of(index, rows)]
        if not end:
            return self._buffer.clamp(Index(line, start))
        text = self._buffer.lines[line - 1] if line <= len(self._buffer.lines) else ""
        if start < stop < len(text):
            stop -= 1
        return self._buffer.clamp(Index(line, stop))

    def _row_last(self, line: int, start: int, stop: int) -> int:
        """The last index on a display row: the character a word wrap broke
        after, or the end of the line on its last row. Measured on Tk 9.0.2,
        past the end of a wrapped row is that character and not the next
        row's first, for ``@x,y`` and for Up and Down. TkCurses-5co5."""
        text = self._buffer.lines[line - 1] if line <= len(self._buffer.lines) else ""
        return stop - 1 if start < stop < len(text) else stop

    def _type(self, characters: str) -> None:
        """Put typed characters in, replacing the selection if there is one.

        Grouped as ``tk::TextInsert`` groups them: text typed over the
        selection is one group of its own, the deletion and the insertion
        together, with autoseparators off between them. And Return, which is
        the newline, ends the group after it.
        """
        if not self._editable:
            return
        auto = self._auto_separators
        if self._selection_range() is not None:
            self._separate_if_asked()
            self._buffer.auto_separators = False
            try:
                self._delete_selection()
                self._insert_typed(characters)
            finally:
                self._buffer.auto_separators = auto
            self._separate_if_asked()
        else:
            self._insert_typed(characters)
        if "\n" in characters:
            self._separate_if_asked()
        self._anchor = None
        self._after_edit(typed=True)

    def _insert_typed(self, characters: str) -> None:
        insert = self._buffer.mark_index("insert") or Index(1, 0)
        self._buffer.insert(insert, characters)

    def _backspace(self) -> None:
        """Delete the selection, or the character before the cursor."""
        if not self._editable:
            return
        if not self._delete_selection():
            insert = self._buffer.mark_index("insert") or Index(1, 0)
            start = self._buffer.index(f"{insert} -1c")
            if start == insert:
                return
            self._buffer.delete(start, insert)
        self._after_edit(typed=True)

    def _delete_forward(self) -> None:
        """Delete the selection, or the character after the cursor."""
        if not self._editable:
            return
        if not self._delete_selection():
            insert = self._buffer.mark_index("insert") or Index(1, 0)
            self._buffer.delete(insert)
        self._after_edit(typed=True)

    # --------------------------------------------------------- display lines

    def _wrap_mode(self) -> str:
        """How long lines are broken, defaulting to Tk's ``char``."""
        mode = str(self._options["wrap"])
        return mode if mode in ("none", "char", "word") else "char"

    def _view_size(self) -> tuple[int, int]:
        """The cells the text is laid out in, as ``(width, height)``.

        Falls back to the configured width and height until the widget has
        been given a rect. Without that fallback, anything asking for the
        display lines or the view before layout wraps every line to a single
        cell - one display row per character - which makes `yview` nonsense
        and turns a large document into a very slow one.
        """
        area = self._text_area()
        if area.width > 0 and area.height > 0:
            return (area.width, area.height)
        return (
            max(1, int(self._options["width"])),
            max(1, int(self._options["height"])),
        )

    def _display_lines(self) -> list[tuple[int, int, int]]:
        """Every row the text would occupy, as ``(line, start, end)``.

        One entry per line on screen rather than per line in the buffer: with
        wrapping on, one is many of the other, and everything about scrolling
        and about Up and Down is counted in these.

        The list is shared until the text or its layout changes, so it must
        not be changed by the caller. Worked out again, a line whose text and
        place are as they were keeps its rows: typing re-wraps one line, not
        the whole text. Measured before: each key in a Text of 2000 lines
        wrapped all of them twice, 2.6 ms a key, where one line of 5000
        characters cost 0.16 ms. Margins and embedded windows are worked out
        afresh every time, as they depend on tag ranges and on other widgets'
        sizes, which nothing here follows.
        """
        key = self._view_key()
        embedding = bool(self._buffer._store.embeds)
        cacheable = not self._margined and not embedding
        if cacheable and key == self._rows_key:
            return self._rows
        width = self._view_size()[0]
        mode = self._wrap_mode()
        above, between, below = (
            _as_int(self._options[name], 0)
            for name in ("spacing1", "spacing2", "spacing3")
        )
        spaced = above > 0 or between > 0 or below > 0

        def lay(number: int, line: str) -> list[tuple[int, int, int]]:
            wrapped = self._wrap_line(number, line, width, mode)
            if embedding and not line.isascii():
                wrapped = self._embed_rows(wrapped, line)
            if spaced:
                wrapped = _spaced(wrapped, above, between, below)
            return wrapped

        lines = self._buffer.lines
        old = self._rows_lines
        if cacheable and self._rows_key is not None and key[1:] == self._rows_key[1:]:
            # The same layout, and only the text changed: the lines the
            # edit left alone at either end keep their rows, and those after
            # it are renumbered if it added or took away lines. A spacing
            # row's line is negated, so it moves the other way.
            head = _common_head(old, lines)
            tail = _common_tail(old, lines, min(len(old), len(lines)) - head)
            delta = len(lines) - len(old)
            middle = [
                lay(number, lines[number - 1])
                for number in range(head + 1, len(lines) - tail + 1)
            ]
            kept = self._line_rows[len(old) - tail :]
            first = self._line_first
            if delta:
                kept = [
                    [
                        (line + delta if line > 0 else line - delta, start, stop)
                        for line, start, stop in group
                    ]
                    for group in kept
                ]
                after = list(itertools.chain.from_iterable(kept))
            else:
                after = self._rows[first[len(old) - tail] :]
            line_rows = self._line_rows[:head] + middle + kept
            rows = (
                self._rows[: first[head]]
                + list(itertools.chain.from_iterable(middle))
                + after
            )
        else:
            line_rows = [lay(number, line) for number, line in enumerate(lines, 1)]
            rows = list(itertools.chain.from_iterable(line_rows))
        if not rows:
            rows = [(1, 0, 0)]
            cacheable = False
        if cacheable:
            self._rows_key, self._rows = key, rows
            self._rows_lines, self._line_rows = lines, line_rows
            self._line_first = list(
                itertools.accumulate(map(len, line_rows), initial=0)
            )
        else:
            self._rows_key, self._rows = None, []
            self._rows_lines, self._line_rows, self._line_first = [], [], []
        return rows

    def _embed_rows(
        self, wrapped: list[tuple[int, int, int]], line: str
    ) -> list[tuple[int, int, int]]:
        """One line's rows, each grown to hold the embedded windows and images
        on it: blank rows above and below, as spacing is, which hold no
        index. Measured on Tk 9.0.2, a line holding a widget three times
        the text's height is that tall, with the text in the middle."""
        out: list[tuple[int, int, int]] = []
        for number, start, stop in wrapped:
            above, below = self._row_reach(line[start:stop])
            out.extend([(-number, start, stop)] * above)
            out.append((number, start, stop))
            out.extend([(-number, start, stop)] * below)
        return out

    def _text_rows(self) -> list[tuple[int, int, int]]:
        """The display rows that hold text, leaving out the spacing.

        What Up and Down count in: a blank row of ``spacing1`` is somewhere
        the view can be, not somewhere the cursor can.
        """
        return [row for row in self._display_lines() if row[0] > 0]

    def _wrap_line(
        self, number: int, line: str, width: int, mode: str
    ) -> list[tuple[int, int, int]]:
        """Break one buffer line into the rows it occupies.

        Not ``wrap_spans``, which counts CHARACTERS and assumes every row is
        the same width. Neither holds here any more:

        - a tab is as wide as the gap to its next stop, so a row has to be
          measured in columns;
        - ``lmargin2`` indents the wrapped rows and not the first, so the
          width available CHANGES from one row to the next, and ``rmargin``
          narrows them all. Measured against Tk: a hanging indent of eight
          in a forty-column widget gave a first row of 38 characters and
          later rows of 28 and 29.

        So each row asks for its own margins before it is filled, which is
        the whole reason this exists rather than a width argument.
        """
        if mode == "none" or not line:
            return [(number, 0, len(line))]
        # FAST PATH, and it is not an optimisation so much as a repair. With
        # no margins and no tab in the line, a character is a cell and every
        # row is the same width - exactly what wrap_spans assumes - so the
        # arithmetic below is not needed and must not be paid for.
        #
        # Measured: without this, 5000 short lines cost a string slice, a
        # list allocation and a Python loop EACH, on every _display_lines
        # call. On Python 3.14 that was +1.5% and invisible; on 3.10 and
        # 3.11 it took the repaint from under 100ms to 146 and 132, and CI
        # failed on those two versions while the other three passed.
        # TkCurses-a0u covers the headroom that made it fatal rather than
        # merely slower.
        if not self._margined and "\t" not in line:
            return [
                (number, start, stop) for start, stop in wrap_spans(line, width, mode)
            ]
        style = str(self._options["tabstyle"])
        rows: list[tuple[int, int, int]] = []
        start = 0
        while True:
            left, right = self._row_margins(number, start)
            room = max(1, width - left - right)
            stop = self._fits(line, start, left, room, style)
            if mode == "word" and stop < len(line):
                stop = word_break(line, start, stop)
            rows.append((number, start, stop))
            if stop >= len(line):
                return rows
            if stop <= start:  # A single character wider than the row.
                rows[-1] = (number, start, start + 1)
                stop = start + 1
            start = stop

    def _fits(self, line: str, start: int, left: int, room: int, style: str) -> int:
        """How much of ``line`` from ``start`` fits in ``room`` columns.

        Walks and stops at the edge rather than laying the whole remainder
        out and then reading it: the first version built a column for every
        character after ``start``, once per row, which is quadratic in the
        length of a line and was wasted work even when it was affordable.
        """
        edge = left + room
        column = left
        tab = 0
        for offset in range(start, len(line)):
            if line[offset] != "\t":
                # A wide character that would straddle the edge starts the
                # next row; a combining mark stays with the one before.
                size = char_cells(line[offset])
                if size and column + size > edge:
                    return offset
                column += size
                continue
            if column >= edge:
                return offset
            number = self._stops.index_after(column) if style == WORDPROCESSOR else tab
            target = self._stops.nth(number)
            column = target if target > column else column + 1
            tab += 1
        return len(line)

    def _row_of(
        self, index: Index, rows: list[tuple[int, int, int]] | None = None
    ) -> int:
        """Which display row an index falls on."""
        return self._display_position(index, rows)[0]

    def _display_position(
        self, index: Index, rows: list[tuple[int, int, int]] | None = None
    ) -> tuple[int, int]:
        """Where an index sits, as ``(row, column within that row)``."""
        rows = self._display_lines() if rows is None else rows
        # Only the line's own rows can hold it, and the cached rows say where
        # those are; any other list is searched from the top.
        low, high = 0, len(rows)
        if rows is self._rows and 0 < index.line < len(self._line_first):
            low, high = self._line_first[index.line - 1], self._line_first[index.line]
        # A wrap boundary belongs to both rows: it is the end of one and the
        # start of the next. It has to resolve to the *later* one, or the
        # cursor is drawn one cell past the end of the row above - painting
        # the first character of the next row there into the bargain.
        for row in range(low, high):
            line, start, stop = rows[row]
            if line == index.line and start <= index.char < stop:
                return row, self._column_in(line, start, stop, index.char)
        # Nothing contains it, so it is at the end of a line: the last row of
        # that line is where it goes.
        for row in range(low, high):
            line, start, stop = rows[row]
            if line == index.line and index.char == stop:
                return row, self._column_in(line, start, stop, index.char)
        # `end` on a buffer whose last line has text is a line past every
        # display row, so it has none of its own; it belongs at the end of
        # the last one. Without this the cursor came back at column 0 and
        # blanked the first character of the bottom line.
        last = max(0, len(rows) - 1)
        while last > 0 and rows[last][0] < 0:
            last -= 1
        line, start, stop = rows[last]
        return last, self._column_in(line, start, stop, stop)

    def _margin_at(self, line: int, start: int, option: str) -> int:
        """A margin in cells, from the tags covering a display line's start.

        Tk decides by "the first non-elided character of the display line",
        not by the tag under the cursor and not by any tag overlapping the
        row - measured: a tag added from part way through the first row
        still indents the wrapped row below it, because that row's first
        character is inside the tag.

        The last tag in the raise order wins, which is how tag priority
        works everywhere else in this widget.
        """
        value = 0
        at = Index(line, start)
        covering = set(self._buffer.tag_names(at))
        for name in self._tag_order:
            if name not in covering:
                continue
            setting = self._tag_options.get(name, {}).get(option)
            if setting not in (None, ""):
                value = round(self.winfo_fpixels(cast("str | int | float", setting)))
        return max(0, value)

    def _row_margins(self, line: int, start: int) -> tuple[int, int]:
        """The left and right margins of one display row, in cells.

        ``start == 0`` is what makes a row the FIRST of its text line, which
        is the whole difference between lmargin1 and lmargin2: the first
        display line takes lmargin1 and every wrapped one takes lmargin2.
        """
        if not self._margined:
            return 0, 0
        left = self._margin_at(line, start, "lmargin1" if start == 0 else "lmargin2")
        return left, self._margin_at(line, start, "rmargin")

    def _row_text(self, line: int, start: int, stop: int) -> str:
        """The characters one display row holds."""
        lines = self._buffer.lines
        return lines[line - 1][start:stop] if line <= len(lines) else ""

    def _column_in(self, line: int, start: int, stop: int, char: int) -> int:
        """Which column of its row a character sits in.

        Was ``char - start`` until tabs existed, and still is for a row
        without any: a character is a cell everywhere else in this library.
        A tab is the exception, so the answer comes from the layout rather
        than from arithmetic - TkCurses-wy7.
        """
        text = self._row_text(line, start, stop)
        left, _ = self._row_margins(line, start)
        if "\t" not in text and text.isascii():
            return left + char - start
        return column_of(
            text,
            char - start,
            start=left,
            stops=self._stops,
            style=str(self._options["tabstyle"]),
        )

    def _index_at_cell(self, x: int, y: int) -> Index:
        """The index at a cell within this widget, for a click or ``@x,y``."""
        area = self._text_area()
        width, height = self._view_size()
        rows = self._display_lines()
        # Clamped into the text area as Tk clamps it: above the area is the
        # top row's first visible character and below it the last row's
        # last, whatever x says, and beside it the nearest column in view.
        # Measured on Tk 9.0.2, where tk::TextScrollPages leans on the first
        # - its @[winfo height / 2],0 lands in the border. TkCurses-5co5.
        if y < area.y:
            row, column = self._top, self._left
        elif y >= area.y + height:
            row = min(self._top + height, len(rows)) - 1
            column = self._left + width - 1
        else:
            row = self._top + (y - area.y)
            column = min(max(0, x - area.x), width - 1) + self._left
        line, start, stop = rows[min(max(row, 0), len(rows) - 1)]
        # Spacing belongs to the row beside it, measured: with spacing1 and
        # spacing3 of 16 pixels, every y from 2 to 40 answers 1.0 in Tk.
        line = abs(line)
        left, _ = self._row_margins(line, start)
        offset = char_at(
            self._row_text(line, start, stop),
            column,
            start=left,
            stops=self._stops,
            style=str(self._options["tabstyle"]),
        )
        last = self._row_last(line, start, stop)
        return self._buffer.clamp(Index(line, min(start + offset, last)))

    # --------------------------------------------------------------- the view

    def see(self, index: Any) -> None:
        """Put an index on screen, as Tk does: the least scroll when it is
        near the view, and otherwise centred on it, each way.

        An index up to a third of the height past the view - at least three
        rows - is scrolled to the edge; one further away is centred. Columns
        work the same way with the width.
        """
        # Measured on Tk 9.0.2 at heights 1 to 18 and widths 9 to 30: up to
        # max(3, height // 3) rows past, or max(3, width // 3) columns, goes to
        # the edge; further, its row goes (height + 1) // 2 from the top and its
        # column width // 2 from the left. A Text one row tall is the exception:
        # Tk's centring in pixels leaves that row half in view, which in cells
        # is out of it, so here it stays in view. TkCurses-5co5.
        self._see(index, sideways=True)

    def yview_pickplace(self, *what: Any) -> None:
        """Bring an index into view vertically, as :meth:`see` does - or,
        given a whole number, put that line, counted from 0, at the top.

        Tk keeps it only for old programs; :meth:`see` is its replacement.

        Raises:
            TclError: Unless given exactly one index, in Tk's words.
        """
        if len(what) != 1:
            raise TclError(
                f'wrong # args: should be "{self._w} yview -pickplace lineNum|index"'
            )
        # A whole number is a line counted from 0, put at the top as plain
        # yview puts it: tkTextDisp.c tries the number before the index.
        number = _tcl_number(what[0])
        if isinstance(number, int) and not isinstance(number, bool):
            self._yview_to(number)
        else:
            self._see(what[0], sideways=False)

    def _see(self, index: Any, *, sideways: bool) -> None:
        target = self._resolve(index)
        width, height = self._view_size()
        first = self._top
        rows = self._display_lines()
        row = self._row_of(target, rows)
        first = _see_offset(first, row, height, min((height + 1) // 2, height - 1))
        self._set_top(max(0, min(first, max(0, len(rows) - height))), rows)
        if sideways and self._wrap_mode() == "none":
            # Clamped as xview is, to the widest row now in view, which
            # leaves a cursor past its end out of view, as Tk's.
            left = _see_offset(self._left_value, target.char, width, width // 2)
            self._left_value = max(0, left)
            self._clamp_left(rows)
        self._redraw_soon()
        # A scrollbar cannot know the view moved unless it is told, and see()
        # is the one thing that moves it without going through _scroll.
        self._report_view(rows)

    def _clamp_view(self) -> None:
        """Keep the view inside the text after anything that could move it.

        Which reading it does: the top is worked out from its index, kept
        inside the text, and the sideways scroll bounded, whenever either is
        read after the text or its layout changed.
        """

    def yview(self, *args: Any) -> tuple[float, float] | None:
        """Read or move the vertical view, in the shape Tk uses.

        With no arguments returns ``(first, last)`` as fractions, which is
        what a Scrollbar's ``set`` wants. Otherwise takes ``("moveto", f)`` or
        ``("scroll", n, "units"|"pages")``, which is what a Scrollbar sends.

        Tk's older form is taken too, for old programs: one index puts the
        line holding it at the top of the view, and a whole number is a
        line counted from 0, so ``yview(3)`` shows line 4 at the top.
        ``yview("-pickplace", index)`` brings the index into view as
        :meth:`see` does.

        Raises:
            TclError: For a bad index, or ``-pickplace`` without exactly one
                index, in Tk's words.
        """
        if not args:
            return self._view_fractions()
        first = str(args[0])
        # tkTextDisp.c's TkTextYviewCmd: "-pickplace" by any prefix of two
        # letters or more, and then exactly one index; or one argument alone.
        pickplace = len(first) >= 2 and "-pickplace".startswith(first)
        if pickplace:
            self.yview_pickplace(*args[1:])
        elif len(args) == 1:
            self._yview_to(args[0])
        else:
            self._scroll(args, vertical=True)
        return None

    def _yview_to(self, where: Any) -> None:
        """Put the display line holding an index, or a line counted from 0,
        at the top of the view - as far as the end of the text allows.

        Measured on Tk 9.0.2: ``0`` and ``-1`` are line 1, ``0x3`` and
        ``" 3"`` are line 4, ``2.5`` is the index 2.5, ``6.25`` in a line
        wrapped at 20 puts 6.20 at the top, and a number or index past the
        end leaves the view as full as ``end`` does.
        """
        number = _tcl_number(where)
        if isinstance(number, int) and not isinstance(number, bool):
            target = self._resolve(f"{max(0, number) + 1}.0")
        else:
            target = self._resolve(where)
        rows = self._display_lines()
        row = self._row_of(target, rows)
        # The display line's own top: past the blank rows above its text,
        # which spacing and a tall embedded window put there.
        line, start, stop = rows[row] if 0 <= row < len(rows) else (0, 0, 0)
        while row > 0 and rows[row - 1] == (-line, start, stop):
            row -= 1
        height = self._view_size()[1]
        self._set_top(max(0, min(row, max(0, len(rows) - height))), rows)
        self._redraw()
        self._report_view(rows)

    def xview(self, *args: Any) -> tuple[float, float] | None:
        """Read or move the horizontal view, in the same shape."""
        if not args:
            return self._horizontal_fractions()
        self._scroll(args, vertical=False)
        return None

    def _scroll(self, args: tuple[Any, ...], *, vertical: bool) -> None:
        """Apply one Tk scrolling command to one axis."""
        view = self._view_size()
        span = view[1] if vertical else view[0]
        current = self._top if vertical else self._left
        rows = self._display_lines()
        total = len(rows) if vertical else self._widest_in_view(rows)
        action = str(args[0])
        if action == "moveto":
            current = int(float(args[1]) * total)
        elif action == "scroll":
            count = int(float(args[1]))
            unit = str(args[2]) if len(args) > 2 else "units"
            current += count * (
                _page_size(span, vertical) if unit.startswith("page") else 1
            )
        else:
            raise TclError(f'bad option "{action}": must be moveto or scroll')
        limit = max(0, total - (span if vertical else 0))
        if vertical:
            self._set_top(max(0, min(current, limit)), rows)
        elif self._wrap_mode() == "none":
            self._left_value = max(0, min(current, max(0, total - span)))
            self._left_key = (self._top_row, self._top_key)
        self._redraw()
        self._report_view(rows)

    def scan_mark(self, x: Any, y: Any) -> None:
        """Remember where a scan starts.

        Raises:
            TclError: If ``x`` or ``y`` is not an integer, in Tk's words.
        """
        self._scan = (
            _tcl_integer(None, x),
            _tcl_integer(None, y),
            self._left_value,
            0,
        )

    def scan_dragto(self, x: Any, y: Any, gain: Any = 10) -> None:
        """Scroll by ``gain`` times how far ``(x, y)`` is from the mark, as
        Tk's ``scan dragto`` does: sideways only while ``wrap`` is
        ``none``, and a drag that runs into an edge starts again from there,
        so the view moves as soon as the pointer turns back.

        Differences from tkinter:
            ``x`` and ``y`` are columns and rows, as ``event.x`` and
            ``event.y`` are here, so ``gain`` multiplies cells.
        """
        mark_x, mark_y, mark_left, total = self._scan
        x, y = _tcl_integer(None, x), _tcl_integer(None, y)
        factor = _tcl_integer(None, gain)
        rows = self._display_lines()
        width, height = self._view_size()
        # tkTextDisp.c's TkTextScanCmd.
        if self._wrap_mode() == "none":
            limit = max(0, self._widest_in_view(rows) - width)
            left = mark_left + factor * (mark_x - x)
            if left < 0 or left > limit:
                left = mark_left = 0 if left < 0 else limit
                mark_x = x
            self._left_value = left
            self._left_key = (self._top_row, self._top_key)
        scroll = factor * (mark_y - y)
        if scroll != total:
            before = self._top
            limit = max(0, len(rows) - height)
            self._set_top(max(0, min(before + scroll - total, limit)), rows)
            total = scroll
            if self._top == before:
                total, mark_y = 0, y
        self._scan = (mark_x, mark_y, mark_left, total)
        self._redraw()
        self._report_view(rows)

    def _view_fractions(
        self, rows: list[tuple[int, int, int]] | None = None
    ) -> tuple[float, float]:
        """Where the vertical view is, as two fractions of the whole."""
        self._top  # noqa: B018 - brings the top up to date first
        total = max(1, len(self._display_lines() if rows is None else rows))
        height = self._view_size()[1]
        return (
            min(1.0, self._top / total),
            min(1.0, (self._top + height) / total),
        )

    def _horizontal_fractions(
        self, rows: list[tuple[int, int, int]] | None = None
    ) -> tuple[float, float]:
        """Where the horizontal view is, as two fractions of the widest row
        in view - (0, 1) when it fits, as in Tk."""
        self._left  # noqa: B018 - bounds it by the rows in view first
        total = self._widest_in_view(rows)
        width = self._view_size()[0]
        if total <= width or self._wrap_mode() != "none":
            return (0.0, 1.0)
        return (
            min(1.0, self._left / total),
            min(1.0, (self._left + width) / total),
        )

    def _report_scroll_view(self) -> None:
        """A resize changes how much is visible, so the scrollbar is retold."""
        self._report_view()

    def _report_view(self, rows: list[tuple[int, int, int]] | None = None) -> None:
        """Tell the scrollbars where the view is, if anything is listening.

        ``rows`` are the display rows, when the caller has just laid them
        out and moved the view over them.
        """
        for option, fractions in (
            ("yscrollcommand", self._view_fractions),
            ("xscrollcommand", self._horizontal_fractions),
        ):
            command = self._options[option]
            if command is not None:
                command(*fractions(rows))

    # -------------------------------------------------------------- painting

    def _text_area(self) -> Rect:
        """Where the text goes, in cells relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        return Rect(
            edge + padx,
            edge + pady,
            max(0, self._rect.width - 2 * (edge + padx)),
            max(0, self._rect.height - 2 * (edge + pady)),
        )

    def _redraw(self) -> None:
        """Paint this widget, and any peer, since what changed here may be
        theirs too: the text, a shared tag, a shared tag's style."""
        self._paint()
        self._settle_embeds()
        for peer in self._peer_widgets():
            peer._clamp_view()
            peer._paint()
            peer._settle_embeds()
            peer._report_view()

    def _settle_embeds(self) -> None:
        """Make the windows due to be made, and lay out any that moved."""
        if self._buffer._store.embeds:
            self._create_embedded_windows()
            self._follow_embeds()

    def _paint(self) -> None:
        """Paint the border, the visible rows, their tags, and the cursor."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        attribute = self._in_state(
            self._background_attribute() | self._font_attribute()
        )
        area = self._text_area()
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            if area.is_empty:
                return
            rows = self._display_lines()
            lines = self._buffer.lines
            for offset in range(area.height):
                row = self._top + offset
                if row >= len(rows):
                    break
                self._draw_row(
                    dispatcher, window, area, offset, rows[row], lines, attribute
                )
            self._paint_images(area, attribute)
            self._draw_cursor(dispatcher, window, area, rows, attribute)

    def _draw_row(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        offset: int,
        span: tuple[int, int, int],
        lines: list[str],
        attribute: int,
    ) -> None:
        """Draw one display row, then whatever tags cover part of it."""
        line, start, stop = span
        if line < 0:
            return
        text = lines[line - 1][start:stop] if line <= len(lines) else ""
        left, _ = self._row_margins(line, start)
        # One entry a cell, so that a position in the list IS a column: the
        # margin as blanks, then the drawn form of the text. A tab is the gap
        # it spans - handing a raw one to curses is what made every widget
        # disagree with its own arithmetic (TkCurses-zrm) - and an ideograph
        # takes two entries. Beside it, the character each cell shows, which
        # is what the tags are looked up by.
        cell_text, owners = self._row_cells(text, left)
        self._draw_margin(dispatcher, window, area, offset, span, left)
        shown = cell_text[self._left : self._left + area.width]
        if shown and shown[0] == "":
            shown[0] = " "  # The second half of an ideograph scrolled off.
        end = self._left + len(shown)
        if shown and end < len(cell_text) and cell_text[end] == "":
            shown[-1] = " "  # The first half of one cut by the right edge.
        self._write_line(
            dispatcher, window, area.y + offset, area.x, "".join(shown), attribute
        )
        shown_owners = owners[self._left : end]
        for name in self._tag_order:
            self._draw_tagged(
                dispatcher,
                window,
                area,
                offset,
                span,
                (shown, shown_owners),
                name,
                attribute,
            )

    def _row_cells(self, text: str, left: int) -> tuple[list[str], list[int | None]]:
        """A row as drawn, one entry a cell, and the character each shows.

        The second list holds, for each cell, the offset in ``text`` of the
        character drawn there - a tab owns every cell of its gap - or None
        for the margin.
        """
        margin: list[int | None] = [None] * left
        if "\t" not in text and text.isascii():
            return [" "] * left + list(text), margin + list(range(len(text)))
        style = str(self._options["tabstyle"])
        drawn = glyphs(text, start=left, stops=self._stops, style=style)
        if self._buffer._store.embedding:
            # An embedded window or image owns its cells and draws itself:
            # the character standing for it is never written.
            blank = False
            for at, glyph in enumerate(drawn):
                if glyph and is_embedded(glyph[0]):
                    drawn[at], blank = " ", True
                elif glyph == "" and blank:
                    drawn[at] = " "
                else:
                    blank = False
        owners: list[int | None] = [None] * len(drawn)
        laid = columns_of(text, start=left, stops=self._stops, style=style)
        for index, column in enumerate(laid):
            following = laid[index + 1] if index + 1 < len(laid) else left + len(drawn)
            for at in range(column, following):
                owners[at - left] = index
        return [" "] * left + drawn, margin + owners

    def _draw_margin(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        offset: int,
        span: tuple[int, int, int],
        left: int,
    ) -> None:
        """Paint the cells an indent leaves empty, if a tag asks for it.

        Tk's ``-lmargincolor``: "the background color to use in regions that
        do not contain characters because they are indented". There is no
        text there to carry the colour, so it is written as blanks.
        """
        line, start, _ = span
        if left <= 0 or self._left >= left:
            return
        colour = ""
        covering = set(self._buffer.tag_names(Index(line, start)))
        for name in self._tag_order:
            if name in covering:
                setting = self._tag_options.get(name, {}).get("lmargincolor")
                if setting:
                    colour = str(setting)
        if not colour:
            return
        colors = self.tk.colors
        if colors is None:
            return
        attribute = colors.attribute_for(
            str(self._options["foreground"] or "white"), colour
        )
        width = min(left - self._left, area.width)
        self._write_line(
            dispatcher, window, area.y + offset, area.x, " " * width, attribute
        )

    def _draw_tagged(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        offset: int,
        span: tuple[int, int, int],
        visible: tuple[list[str], list[int | None]],
        name: str,
        attribute: int,
    ) -> None:
        """Redraw the parts of one row that a tag covers.

        Drawn over the plain text rather than worked out per character before
        anything is written: tags overlap, and painting them in priority order
        is what makes the topmost one win without having to resolve the whole
        stack up front.
        """
        line, start, _ = span
        tagged = self._tag_attribute(name)
        if tagged is None:
            return
        shown, owners = visible
        # The characters of this row the tag covers, asked once for the row
        # rather than of every cell: see TextBuffer.tag_spans.
        covered = {
            char
            for begin, end in self._buffer.tag_spans(name, line, start, span[2] + 1)
            for char in range(begin, end)
        }
        if not covered:
            return
        for column, character in enumerate(shown):
            owner = owners[column]
            if owner is None or character == "":
                continue
            if start + owner not in covered:
                continue
            self._write_line(
                dispatcher,
                window,
                area.y + offset,
                area.x + column,
                character,
                with_colors(attribute, tagged & _curses.A_COLOR)
                | (tagged & ~_curses.A_COLOR),
            )

    def _tag_attribute(self, name: str) -> int | None:
        """What a tag does to the cells it covers, or None if nothing.

        ``sel`` is the selection, drawn by ``_selected_text_attribute``.
        """
        options = self._tag_options.get(name)
        if options is None:
            return None
        attribute = 0
        font = str(options.get("font", "")).lower()
        attribute |= from_font(
            bold="bold" in font,
            italic="italic" in font,
            underline="underline" in font or bool(options.get("underline")),
        )
        foreground, background = options.get("foreground"), options.get("background")
        if name == "sel":
            return self._selected_text_attribute(attribute, foreground, background)
        colors = self.tk.colors
        if colors is not None and (foreground or background):
            attribute |= colors.attribute_for(
                str(foreground or self._options["foreground"] or "white"),
                str(background or self._options["background"] or "black"),
            )
        return attribute or None

    def _selected_text_attribute(
        self, attribute: int, foreground: Any, background: Any
    ) -> int | None:
        """What the ``sel`` tag does: the select colours, else reversed.

        Without the focus, ``inactiveselectbackground`` takes the background's
        place, as in Tk, and a ``""`` a program gave it hides the selection.
        The ``""`` it starts at does not: that one is the terminal's own look,
        the same as with the focus (TkCurses-gm66.3, and ``_TerminalsOwn``).
        """
        if self.focus_get() is not self:
            inactive = self._options["inactiveselectbackground"]
            if inactive == "" and not isinstance(inactive, _TerminalsOwn):
                return None
            if inactive:
                background = inactive
        return self._selection_attribute(attribute, foreground or "", background or "")

    def _draw_cursor(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        rows: list[tuple[int, int, int]],
        attribute: int,
    ) -> None:
        """Note where typing will go, while the widget has the focus.

        Noted for the terminal's own cursor rather than painted as a reversed
        cell, which could not be told from a selection - see Entry's
        ``_draw_cursor`` and TkCurses-lw2.
        """
        del dispatcher, window, attribute
        self._insert_at = None
        if self.focus_get() is not self:
            return
        insert = self._buffer.mark_index("insert")
        if insert is None:
            return
        at, within = self._display_position(insert, rows)
        row = at - self._top
        if not 0 <= row < area.height:
            return
        column = within - self._left
        if not 0 <= column < area.width:
            return
        self._insert_at = (
            self.winfo_rooty() + area.y + row,
            self.winfo_rootx() + area.x + column,
        )

    def _insert_cell(self) -> tuple[int, int] | None:
        return self._insert_at


def _page_size(span: int, vertical: bool) -> int:
    """How far ``yview scroll 1 pages`` goes in a Text ``span`` rows tall, or
    ``xview`` in one ``span`` columns wide.

    Tk's rule, in lines: three quarters of the height when a line
    is a quarter of it or more, and two lines less than the height
    otherwise; sideways, two columns less than the width. Measured on Tk
    9.0.2 at heights 1 to 10 and widths 1 to 30. TkCurses-5co5.
    """
    if not vertical:
        return max(0, span - 2)
    return max(1, 3 * span // 4) if span <= 4 else span - 2


def _see_offset(first: int, target: int, span: int, centre: int) -> int:
    """Where a view ``span`` long starting at ``first`` starts once ``target``
    is in it, by :meth:`Text.see`'s rule."""
    if first <= target < first + span:
        return first
    reach = max(3, span // 3)
    if first - reach <= target < first:
        return target
    if first + span <= target < first + span + reach:
        return target - span + 1
    return target - centre


def _text_key(event: Event) -> str | None:
    """Handle one key in a Text.

    Returns ``"break"`` for keys the widget consumed, so a Left arrow moving
    the cursor does not also reach whatever else is bound to it. Tab is left
    alone deliberately: a widget that swallowed it would trap the focus, and
    a terminal user with no mouse would have nowhere to go.
    """
    text = event.widget
    keysym = event.keysym

    if keysym == "BackSpace":
        text._backspace()
        return "break"
    if keysym == "Delete" and not event.state & _TK_SHIFT:
        text._delete_forward()
        return "break"
    if keysym == "Return":
        text._type("\n")
        return "break"
    if keysym == "Tab":
        return None
    if event.state & _TK_ALT_OR_META:
        # text.tcl binds <Alt-Key> and <Meta-Key> to "# nothing": see the
        # same test in the Entry's. TkCurses-r3og.
        return None
    if len(event.char) == 1 and not _is_control(event.char):
        # tk::TextInsert: any character, as in the Entry's handler.
        text._type(event.char)
        return "break"
    return None


# ------------------------------------------------------ moving through a Text
#
# text.tcl's bindings for tk.tcl's navigation events and for Control-Home
# and Control-End, each procedure named beside the code that follows it.
# Measured over 300 recorded sequences, wrapped and not,
# tests/support/navigation_keys.json.
# None breaks, as none of Tk's does. TkCurses-wmaq.


def _text_set_cursor(text: Text, index: str) -> None:
    """``tk::TextSetCursor``: the cursor to ``index`` - short of ``end``,
    which no cursor can be at - the selection cleared, the cursor in view."""
    if text.compare(index, "==", "end"):
        index = "end - 1c"
    text._separate_if_asked()
    text.mark_set("insert", index)
    text.tag_remove("sel", "1.0", "end")
    text.see("insert")
    text._redraw()


def _text_key_select(text: Text, index: str) -> None:
    """``tk::TextKeySelect``: select from the cursor to ``index``, or, with a
    selection already there, from its anchor; then move the cursor."""
    new = text.index(index)
    if not text.tag_ranges("sel"):
        if text.compare(new, "<", "insert"):
            text.tag_add("sel", new, "insert")
        else:
            text.tag_add("sel", "insert", new)
        text._anchor = text._buffer.mark_index("insert")
    else:
        if text._anchor is None:
            text._anchor = text._buffer.mark_index("insert")
        anchor = str(text._anchor)
        if text.compare(new, "<", anchor):
            first, last = new, anchor
        else:
            first, last = anchor, new
        text.tag_remove("sel", "1.0", first)
        text.tag_add("sel", first, last)
        text.tag_remove("sel", last, "end")
    text._separate_if_asked()
    text.mark_set("insert", new)
    text.see("insert")
    text._redraw()


def _text_next_pos(text: Text, start: str, op: Callable[[str, int], int | None]) -> str:
    """``tk::TextNextPos``: where ``op`` first answers in the text from
    ``start``, read a line at a time, or ``end``."""
    gathered = ""
    current = text.index(start)
    while text.compare(current, "<", "end"):
        gathered += text.get(current, f"{current} lineend + 1c")
        found = op(gathered, 0)
        if found is not None:
            return text.index(f"{start} + {found} chars")
        current = text.index(f"{current} lineend + 1c")
    return text.index("end")


def _text_prev_pos(text: Text, start: str, op: Callable[[str, int], int | None]) -> str:
    """``tk::TextPrevPos``: where ``op`` first answers in the text before
    ``start``, read a line at a time backwards, or the start."""
    gathered = ""
    current = text.index(start)
    while text.compare(current, ">", "1.0"):
        gathered = text.get(f"{current} linestart - 1c", current) + gathered
        # The procedure is given ``end``, which in Tk 9's C means the last
        # character and not the length: measured, startOfPreviousWord on
        # "\nx" answers 0 from end and 1 from 2.
        found = op(gathered, len(gathered) - 1)
        if found is not None:
            return text.index(f"{current} linestart - 1c + {found} chars")
        current = text.index(f"{current} linestart - 1c")
    return "1.0"


def _text_previous_char(text: Text) -> str:
    """``tk::TextPrevPos insert tk::startOfCluster``: one character back."""
    return text.index("insert - 1c")


def _text_next_char(text: Text) -> str:
    """``tk::TextNextPos insert tk::endOfCluster``: one on, which past the
    last character is ``end``."""
    return text.index("insert + 1 chars")


def _text_previous_word(text: Text) -> str:
    """``tk::TextPrevPos insert tk::startOfPreviousWord``."""
    return _text_prev_pos(text, "insert", start_of_previous_word)


def _text_next_word(text: Text) -> str:
    """``tk::TextNextWord``: past the end of this word, then on to the start
    of the next."""
    end = _text_next_pos(text, "insert", end_of_word)
    return _text_next_pos(text, end, start_of_next_word)


def _text_select_next_word(text: Text) -> str:
    """``tk::TextSelectNextWord``: to the end of this word only."""
    return _text_next_pos(text, "insert", end_of_word)


def _text_up_down_line(text: Text, count: int) -> str:
    """``tk::TextUpDownLine``: ``count`` display lines on from where the run
    of Up and Down began, at that index's column.

    The column is kept from the first press for as long as the cursor stays
    where the last press left it, so Down through a short line comes back
    out at the column it went in at. Above the first line is that line's
    start and below the last is the end, and landing on the last character -
    or on the start of the row the cursor was on - begins a new run.
    """
    insert = text._buffer.mark_index("insert") or Index(1, 0)
    if text._prev_pos != insert or text._pos_orig is None:
        text._pos_orig = insert
    rows = text._text_rows()
    origin = text._pos_orig
    row, column = text._display_position(origin, rows)
    # The column in cells, as Tk keeps the x position: an ideograph is two,
    # a tab its whole gap, and a margin counts.
    at_start = origin.char == rows[row][1]
    target = text._row_of(insert, rows) + count
    last = text._buffer.clamp(Index(rows[-1][0], rows[-1][2]))
    if target < 0:
        new = Index(rows[0][0], rows[0][1])
    elif target >= len(rows):
        # Measured on Tk 9.0.2: below the last row is ``end`` from the first
        # column and the last character from any other - "9.0 + 1
        # displaylines" is 10.0, "9.1 + 1 displaylines" 9.7. A plain Down
        # ends on the character either way; a shifted one selects to end.
        new = text._buffer.end() if at_start else last
    else:
        line, new_start, new_stop = rows[target]
        last_on_row = text._row_last(line, new_start, new_stop)
        left, _ = text._row_margins(line, new_start)
        offset = char_at(
            text._row_text(line, new_start, new_stop),
            column,
            start=left,
            stops=text._stops,
            style=str(text._options["tabstyle"]),
        )
        new = text._buffer.clamp(Index(line, min(new_start + offset, last_on_row)))
    text._prev_pos = new
    line, start, _ = rows[text._row_of(insert, rows)]
    # "end display lineend", which is the last character and not end.
    if new == last or new == Index(line, start):
        text._pos_orig = new
    return str(new)


def _text_past_indent(text: Text, line: str) -> str:
    """``line``, moved past its leading spaces and tabs if anything follows
    them, as text.tcl's paragraph procedures move it."""
    content = text.get(line, f"{line} lineend")
    stripped = content.lstrip(" \t")
    if stripped and len(stripped) < len(content):
        return text.index(f"{line} + {len(content) - len(stripped)} chars")
    return line


def _text_previous_para(text: Text) -> str:
    """``tk::TextPrevPara``: the start of this paragraph, or of the one
    before if the cursor is already there - the first line after an empty
    one, past its indent."""
    position = text.index("insert linestart")
    while True:
        starts = text.get(f"{position} - 1 line") == "\n"
        if (starts and text.get(position) != "\n") or position == "1.0":
            position = _text_past_indent(text, position)
            if text.compare(position, "!=", "insert") or position.startswith("1."):
                return position
        position = text.index(f"{position} - 1 line")


def _text_next_para(text: Text) -> str:
    """``tk::TextNextPara``: past the empty lines after this paragraph, to
    the next one's first line, past its indent; or the last character."""
    position = text.index("insert linestart + 1 line")
    while text.get(position) != "\n":
        if text.compare(position, "==", "end"):
            return text.index("end - 1c")
        position = text.index(f"{position} + 1 line")
    while text.get(position) == "\n":
        position = text.index(f"{position} + 1 line")
        if text.compare(position, "==", "end"):
            return text.index("end - 1c")
    return _text_past_indent(text, position)


def _text_line_edge(text: Text, *, end: bool) -> str:
    """``insert display linestart`` and ``insert display lineend``."""
    insert = text._buffer.mark_index("insert") or Index(1, 0)
    return str(text._row_edge(insert, end=end))


def _text_line_start(text: Text) -> str:
    return _text_line_edge(text, end=False)


def _text_line_end(text: Text) -> str:
    return _text_line_edge(text, end=True)


def _text_up(text: Text) -> str:
    return _text_up_down_line(text, -1)


def _text_down(text: Text) -> str:
    return _text_up_down_line(text, 1)


def _see_insert(view: TextBuffer) -> None:
    """The ``see insert`` of one of Tk's undo atoms, in the Text whose edit
    it replays - TextPushUndoAction, in tkText.c."""
    if view.owner is not None:
        view.owner.see("insert")


def _text_scroll_pages(text: Text, count: int) -> str:
    """``tk::TextScrollPages``: scroll the view ``count`` pages, and answer
    where the cursor was on screen - or, if it was not on screen, the top
    row's first visible character, which is where Tk's ``@[winfo height /
    2],0`` lands."""
    box = text.bbox("insert")
    text.yview_scroll(count, "pages")
    if box is None:
        return text.index(f"@{text.winfo_height() // 2},0")
    return text.index(f"@{box[0]},{box[1]}")


def _text_page_up(text: Text) -> str:
    return _text_scroll_pages(text, -1)


def _text_page_down(text: Text) -> str:
    return _text_scroll_pages(text, 1)


def _text_start(text: Text) -> str:
    del text
    return "1.0"


def _text_last(text: Text) -> str:
    """``end - 1 indices``: the last character, which is the final newline."""
    return text.index("end - 1c")


#: Each navigation event, and Prior, Next, Control-Home and Control-End,
#: with where it goes and whether it extends the selection.
_TEXT_NAVIGATION: dict[str, tuple[Callable[[Text], str], bool]] = {
    "<<PrevChar>>": (_text_previous_char, False),
    "<<NextChar>>": (_text_next_char, False),
    "<<PrevLine>>": (_text_up, False),
    "<<NextLine>>": (_text_down, False),
    "<<SelectPrevChar>>": (_text_previous_char, True),
    "<<SelectNextChar>>": (_text_next_char, True),
    "<<SelectPrevLine>>": (_text_up, True),
    "<<SelectNextLine>>": (_text_down, True),
    "<<PrevWord>>": (_text_previous_word, False),
    "<<NextWord>>": (_text_next_word, False),
    "<<PrevPara>>": (_text_previous_para, False),
    "<<NextPara>>": (_text_next_para, False),
    "<<SelectPrevWord>>": (_text_previous_word, True),
    "<<SelectNextWord>>": (_text_select_next_word, True),
    "<<SelectPrevPara>>": (_text_previous_para, True),
    "<<SelectNextPara>>": (_text_next_para, True),
    "<<LineStart>>": (_text_line_start, False),
    "<<SelectLineStart>>": (_text_line_start, True),
    "<<LineEnd>>": (_text_line_end, False),
    "<<SelectLineEnd>>": (_text_line_end, True),
    "<Key-Prior>": (_text_page_up, False),
    "<Shift-Key-Prior>": (_text_page_up, True),
    "<Key-Next>": (_text_page_down, False),
    "<Shift-Key-Next>": (_text_page_down, True),
    "<Control-Key-Home>": (_text_start, False),
    "<Control-Shift-Key-Home>": (_text_start, True),
    "<Control-Key-End>": (_text_last, False),
    "<Control-Shift-Key-End>": (_text_last, True),
}


def _text_navigation(
    target: Callable[[Text], str], extend: bool
) -> Callable[[Event], None]:
    """The binding for one navigation event in a Text."""
    move = _text_key_select if extend else _text_set_cursor
    return lambda event: move(event.widget, target(event.widget))


def _text_select_none(event: Event) -> None:
    """text.tcl's ``<<SelectNone>>``: no selection, and an undo separator."""
    text = event.widget
    text.tag_remove("sel", "1.0", "end")
    text._separate_if_asked()


# ---------------------------------------------------- the clipboard, on a Text
#
# The same rules as an Entry's (see _entry_copy), measured on Tk 9.0.2's Text:
# copy the "sel" range; cut is copy then delete, and a disabled Text still
# copies; paste replaces the selection (a deliberate departure from Linux Tk,
# see _entry_paste); select-all tags 1.0 to end and leaves the cursor.
# TkCurses-lw2.
#
# insert() and delete() ignore a disabled Text themselves (TkCurses-aah), but
# the handlers still ask first: a cut must know whether to delete after
# copying, and a paste must not move the cursor on its way to being refused.


def _text_selected(text: Any) -> tuple[str, str, str] | None:
    """The selection as ``(first, last, text)``, or None with nothing selected."""
    ranges = text.tag_ranges("sel")
    if not ranges:
        return None
    first, last = str(ranges[0]), str(ranges[1])
    return (first, last, str(text.get(first, last)))


def _text_writable(text: Any) -> bool:
    return str(text.cget("state")) != "disabled"


def _text_copy(event: Event) -> None:
    """Put the selection on the clipboard."""
    selected = _text_selected(event.widget)
    if selected is not None:
        event.widget.clipboard_clear()
        event.widget.clipboard_append(selected[2])


def _text_cut(event: Event) -> None:
    """Copy the selection, then delete it unless the Text is disabled."""
    text = event.widget
    selected = _text_selected(text)
    if selected is None:
        return
    text.clipboard_clear()
    text.clipboard_append(selected[2])
    if _text_writable(text):
        text.delete(selected[0], selected[1])
        text.see("insert")


def _text_paste(event: Event) -> None:
    """Insert the clipboard at the insert mark, replacing any selection.

    Classic Tk on Linux keeps the selection; on Windows and macOS it deletes
    it first, and this does too - a deliberate departure, as for Entry.
    TkCurses-lw2.
    """
    text = event.widget
    if not _text_writable(text):
        return
    try:
        data = text.clipboard_get()
    except TclError:
        return
    selected = _text_selected(text)
    if selected is not None:
        text.mark_set("insert", selected[0])
        text.delete(selected[0], selected[1])
    text.insert("insert", data)
    text.see("insert")


def _text_terminal_paste(event: Event) -> str:
    """Put a paste the terminal marked in at the insert mark, replacing any
    selection, as one undo step.

    Line breaks are kept, as newlines, and tabs; every other control
    character goes. Nothing is indented or completed: the text goes in as
    it was copied. A disabled Text takes none of it.
    """
    text = event.widget
    pasted = _pasted_lines(event.data)
    if not pasted or not _text_writable(text):
        return "break"
    buffer = text._buffer
    auto = buffer.auto_separators
    text._separate_if_asked()
    buffer.auto_separators = False
    try:
        selected = _text_selected(text)
        if selected is not None:
            text.mark_set("insert", selected[0])
            text.delete(selected[0], selected[1])
        text.insert("insert", pasted)
    finally:
        buffer.auto_separators = auto
    text._separate_if_asked()
    text.see("insert")
    return "break"


def _text_clear(event: Event) -> None:
    """Delete the selection."""
    selected = _text_selected(event.widget)
    if selected is not None and _text_writable(event.widget):
        event.widget.delete(selected[0], selected[1])


def _text_select_all(event: Event) -> None:
    """Select everything; the insert mark stays where it was."""
    event.widget.tag_add("sel", "1.0", "end")


def _text_undo(event: Event) -> None:
    """text.tcl's ``<<Undo>>``: separators either side, since the undo may
    take the one on top of the stack, and nothing to undo is no error."""
    text = event.widget
    if text._auto_separators:
        text.edit_separator()
    with contextlib.suppress(TclError):
        text.edit_undo()
    if text._auto_separators:
        text.edit_separator()


def _text_redo(event: Event) -> None:
    """text.tcl's ``<<Redo>>``, and Alt-z."""
    with contextlib.suppress(TclError):
        event.widget.edit_redo()


#: Numbers the stores whose text tags have bindings; see Text._tag_binding_tag.
_TEXT_BINDING_IDS = itertools.count(1)
#: Numbers behind the handles Canvas.tag_bind returns.
_CANVAS_BINDING_IDS = itertools.count(1)


def _crossing(event: Event, kind: str) -> Event:
    """A copy of ``event`` as the ``<Enter>`` or ``<Leave>`` Tk makes of it
    when the character under the pointer changes."""
    made: Event = copy.copy(event)
    made.type = EventType.Enter if kind == "Enter" else EventType.Leave
    return made


def _text_paste_selection(event: Event) -> None:
    """Insert PRIMARY where the middle button was released."""
    text = event.widget
    if not _text_writable(text):
        return
    text.mark_set("insert", f"@{event.x},{event.y}")
    try:
        data = text.selection_get()
    except TclError:
        return
    text.insert("insert", data)
    text.focus_set()
    text.see("insert")


def _text_press(event: Event) -> None:
    """Take the focus, put the cursor where the click was, and start a drag."""
    text = event.widget
    text.focus_set()
    text._separate_if_asked()
    index = text._index_at_cell(event.x, event.y)
    text._buffer.mark_set("insert", index)
    text._buffer.mark_set("current", index)
    text._anchor = index
    _text_start_drag(text, "char", event.x)
    text._select(index, index)
    text._redraw()


# -------------------------------------------- selecting with the mouse, Text
#
# Tk's Text bindings, READ from the running interpreter - bind_class Text and
# the bodies of tk::TextButton1, tk::TextSelectTo, tk::TextResetAnchor,
# tk::TextAutoScan, tk::TextPrevPos and tk::TextNextPos - and the selections
# MEASURED on Tk 9.0.2 by calling them (TkCurses-svtr):
#
# * a double-click selects the run around the pointer, as an Entry's does,
#   except that a run can cross lines - a newline is not a word character,
#   so "foo  \n  bar" double-clicked in the spaces selects "  \n  ". The
#   cursor goes to the START of it, where an Entry's goes to the end.
# * a triple-click selects the line with its newline.
# * a drag after either extends a word or a line at a time.
# * Shift-click moves whichever end of the selection Tk's
#   tk::TextResetAnchor picks - the far end from the pointer, decided by
#   character count - and selects from there to the pointer.
# * a drag past the top or bottom scrolls, one line more than the pointer
#   is past the edge, every 50ms; past either side, two columns.


def _text_start_drag(text: Any, mode: str, x: int) -> None:
    """Begin a press: what a drag extends by, and nothing moved yet."""
    _cancel_autoscan(text)
    text._select_mode = mode
    text._moved = False
    text._press_x = x
    text._dragging = True


def _text_select_to(text: Any, x: int, y: int) -> None:
    """Select from the anchor to the pointer by the mode - ``tk::TextSelectTo``.

    The anchor is taken to have right gravity, the pointer being on a
    character rather than between two: the word or line it is IN.
    """
    buffer = text._buffer
    # Held to the visible cells, as Tk's @x,y is: past an edge means the edge.
    # The autoscroll moves the view; this only says where in it. See
    # _entry_index_at for what went wrong without it.
    area = text._text_area()
    x = min(max(x, area.x), area.x + max(area.width - 1, 0))
    y = min(max(y, area.y), area.y + max(area.height - 1, 0))
    cur = text._index_at_cell(x, y)
    if text._anchor is None:
        text._anchor = cur
    anchor = text._anchor
    if cur != anchor or x != text._press_x:
        text._moved = True
    mode = text._select_mode
    if mode == "char":
        first, last = min(anchor, cur), max(anchor, cur)
    elif mode == "word":
        whole = buffer.text
        first_at = buffer.offset_of(anchor)
        last_at = min(first_at + 1, len(whole))
        here = buffer.offset_of(cur)
        if here < first_at:
            first_at = here
        elif here > last_at:
            last_at = here
        first = buffer.index_of(run_start(whole, first_at))
        last = buffer.index_of(run_end(whole, last_at - 1))
    else:
        first, last = Index(anchor.line, 0), Index(anchor.line + 1, 0)
        if cur < first:
            first = Index(cur.line, 0)
        elif cur >= last:
            last = Index(cur.line + 1, 0)
        last = min(last, buffer.end())
    if text._moved or mode != "char":
        buffer.mark_set("insert", cur)
        text._select(first, last)
    text.see("insert")
    text._redraw()
    text._report_view()


def _text_control_click(event: Event) -> None:
    """Move the insert mark to the pointer and leave the selection alone.

    Tk's ``<Control-Button-1>``: ``mark set insert @%x,%y``, and an undo
    separator when ``-autoseparators`` is on, because "an operation that
    moves the insert mark without making it one end of the selection must
    insert an autoseparator" (Tk's own comment, text.tcl). The focus does not
    move and no drag follows. TkCurses-mndh.
    """
    text = event.widget
    _cancel_autoscan(text)
    text._dragging = False
    text._separate_if_asked()
    text._buffer.mark_set("insert", text._index_at_cell(event.x, event.y))
    text.see("insert")
    text._redraw()


def _do_nothing(event: Event) -> None:
    """A binding that does nothing, to stand in front of a less specific one."""
    del event


def _text_double(event: Event) -> None:
    """Select the word under the pointer, the cursor at its start."""
    text = event.widget
    _text_start_drag(text, "word", event.x)
    _text_select_to(text, event.x, event.y)
    _text_cursor_to_selection(text)


def _text_triple(event: Event) -> None:
    """Select the line under the pointer and its newline."""
    text = event.widget
    _text_start_drag(text, "line", event.x)
    _text_select_to(text, event.x, event.y)
    _text_cursor_to_selection(text)


def _text_cursor_to_selection(text: Any) -> None:
    """Put the cursor at the start of the selection, as Tk's binding does."""
    found = text._selection_range()
    if found is not None:
        text._buffer.mark_set("insert", found[0])
        text._redraw()


def _text_shift_press(event: Event) -> None:
    """Extend from whichever end ``tk::TextResetAnchor`` keeps, to the pointer."""
    text = event.widget
    _text_reset_anchor(text, text._index_at_cell(event.x, event.y))
    text._select_mode = "char"
    text._dragging = True
    _text_select_to(text, event.x, event.y)


def _text_reset_anchor(text: Any, at: Index) -> None:
    """Make the end of the selection farther from ``at`` the anchor.

    ``tk::TextResetAnchor``, ported with its quirk: its test for a selection
    spanning few lines compares the first line with the LAST plus two, which
    always holds, so the choice is always made by counting characters - the
    nearer end moves when the click is inside. With nothing selected the
    anchor stays where the last click left it, so a click then a shift-click
    selects between the two (Tk's comment cites its bug 5929).
    """
    found = text._selection_range()
    if found is None:
        return
    first, last = found
    if at < first:
        text._anchor = last
        return
    if at > last:
        text._anchor = first
        return
    total = len(text._buffer.get(first, last))
    if total <= 2:
        return
    before = len(text._buffer.get(first, at))
    text._anchor = last if before < total // 2 else first


def _text_double_shift(event: Event) -> None:
    """Extend the selection from the anchor by whole words."""
    text = event.widget
    text._select_mode = "word"
    text._dragging = True
    _text_select_to(text, event.x, event.y)


def _text_triple_shift(event: Event) -> None:
    """Extend the selection from the anchor by whole lines."""
    text = event.widget
    text._select_mode = "line"
    text._dragging = True
    _text_select_to(text, event.x, event.y)


def _text_motion(event: Event) -> None:
    """Extend the selection to the pointer while a drag is going on."""
    text = event.widget
    if not text._dragging:
        return
    text._drag_at = (event.x, event.y)
    _text_select_to(text, event.x, event.y)
    outside = not (
        0 <= event.x < text.winfo_width() and 0 <= event.y < text.winfo_height()
    )
    if outside:
        if text._autoscan is None:
            text._autoscan = text.after(50, lambda: _text_autoscan(text))
    else:
        _cancel_autoscan(text)


def _text_autoscan(text: Any) -> None:
    """Scroll towards the pointer and select to it, every 50ms - ``tk::TextAutoScan``.

    Tk scrolls ``1 + y - height`` PIXELS past the bottom; a row is the unit
    here, and one row below a Text is roughly one line of Tk's, so it scrolls
    a line more than the pointer is past the edge.
    """
    text._autoscan = None
    if not text._dragging or not text.winfo_exists():
        return
    x, y = text._drag_at
    height, width = text.winfo_height(), text.winfo_width()
    if y >= height:
        text.yview("scroll", 1 + y - height, "units")
    elif y < 0:
        text.yview("scroll", -1 + y, "units")
    elif x >= width:
        text.xview("scroll", 2, "units")
    elif x < 0:
        text.xview("scroll", -2, "units")
    else:
        return
    _text_select_to(text, x, y)
    text._autoscan = text.after(50, lambda: _text_autoscan(text))


def _text_release(event: Event) -> None:
    """Stop dragging, wherever the pointer ended up."""
    event.widget._dragging = False
    _cancel_autoscan(event.widget)


def _text_wheel(event: Event) -> None:
    """Scroll the view without moving the cursor, as a wheel should."""
    event.widget.yview("scroll", -event.delta * 3, "units")


def _text_refresh(event: Event) -> None:
    """Repaint after the focus moved in or out."""
    event.widget._redraw()


@dataclass
class _CanvasItem:
    """One thing drawn on a Canvas.

    Attributes:
        ident: The number ``create_*`` returned, and the item's first tag.
        kind: ``line``, ``rectangle``, ``oval``, ``polygon`` or ``text``.
        coords: Pixel coordinates, flat, as Tk passes them.
        options: Everything else, already checked against the type's options.
    """

    ident: int
    kind: str
    coords: list[int]
    options: dict[str, Any]

    @property
    def tags(self) -> tuple[str, ...]:
        """The item's tags, as a tuple however they were given."""
        tags = self.options.get("tags") or ()
        if isinstance(tags, str):
            return tuple(tags.split())
        return tuple(str(tag) for tag in tags)

    def points(self) -> list[tuple[int, int]]:
        """The coordinates as pairs."""
        return list(zip(self.coords[::2], self.coords[1::2], strict=False))


class Canvas(_Drawable, XView, YView):
    """A drawing surface, measured in half-cells.

    A character cell is about twice as tall as it is wide, so a canvas that
    treated one cell as one unit would draw every circle as a tall ellipse.
    This one is a plane of **half-cells** instead - ``▀`` and ``▄`` divide a
    cell across the middle, and each half is very nearly square - so a circle
    is a circle.

    Sample output:
        # size: 40x10
        canvas = tk.Canvas(root, width=30, height=8)
        canvas.create_rectangle(1, 1, 12, 12, outline="cyan")
        canvas.create_oval(16, 1, 28, 13, fill="red")
        canvas.create_text(15, 15, text="half-cells")
        canvas.pack()

    Options:
        closeenough: How near, in pixels, the mouse must be to an item to be
            over it.
        confine: Whether the view is kept within ``scrollregion``.
        offset: Where stipple patterns start: ``x,y``, ``#x,y`` or a compass
            point.
        scrollregion: The area that can be scrolled to: ``"left top right
            bottom"``.
        xscrollincrement: The step a horizontal scroll moves by; 0 is a tenth
            of the view.
        yscrollincrement: The step a vertical scroll moves by.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``height``,
    ``highlightbackground``, ``highlightcolor``, ``highlightthickness``,
    ``insertbackground``, ``insertborderwidth``, ``insertofftime``,
    ``insertontime``, ``insertwidth``, ``relief``, ``selectbackground``,
    ``selectborderwidth``, ``selectforeground``, ``state``, ``takefocus``,
    ``width``, ``xscrollcommand``, ``yscrollcommand``.

    Differences from tkinter:
        Two coordinate systems meet on this widget, and only one of them is
        Tk's. ``width`` and ``height`` are in **cells**, like every other
        widget here. Item coordinates are in **pixels**: one cell wide, half a
        cell tall, so a canvas 40 cells by 10 is a plane 40 pixels by 20.

        Text is the one thing that cannot live on that plane: a glyph occupies
        a whole cell. A text item snaps to the nearest cell row, and while it
        is on top nothing else can share those cells.

        The insertion cursor is the terminal's own, so ``insertbackground``,
        ``insertborderwidth``, ``insertofftime``, ``insertontime`` and
        ``insertwidth`` draw nothing, and nor does ``selectborderwidth``.
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset(
        {"foreground", "padx", "pady"}
    )

    #: Tk lists its synonyms by database name: ``("bd", "borderWidth")``.
    _synonyms_by_database_name: ClassVar[bool] = True

    #: What each kind of item accepts, on top of the options every item has.
    #: Deliberately smaller than Tk's: dashes, stipples, arrowheads and line
    #: widths have no meaning in a grid of characters, so asking for one
    #: fails rather than quietly doing nothing.
    _COMMON_ITEM_OPTIONS: ClassVar[dict[str, Any]] = {
        "state": "normal",
        "tags": (),
    }
    _ITEM_OPTIONS: ClassVar[dict[str, dict[str, Any]]] = {
        "arc": {
            "extent": 90.0,
            "fill": "",
            "outline": "white",
            "start": 0.0,
            "style": "pieslice",
        },
        "bitmap": {
            "activebackground": "",
            "activebitmap": "",
            "activeforeground": "",
            "anchor": "center",
            "background": "",
            "bitmap": "",
            "disabledbackground": "",
            "disabledbitmap": "",
            "disabledforeground": "",
            "foreground": "white",
        },
        "image": {
            "activeimage": "",
            "anchor": "center",
            "disabledimage": "",
            "image": "",
        },
        "line": {"fill": "white"},
        "rectangle": {"fill": "", "outline": "white"},
        "window": {"anchor": "center", "height": 0, "width": 0, "window": ""},
        "oval": {"fill": "", "outline": "white"},
        "polygon": {"fill": "white", "outline": ""},
        "text": {
            "anchor": "center",
            "fill": "white",
            "font": "",
            "justify": "left",
            "text": "",
        },
    }

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "state": _canvas_state,
        "height": _signed_distance,
        "scrollregion": _scroll_region_value,
        "width": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        **_INSERT_CURSOR_OPTIONS,
        **_SELECTION_OPTIONS,
        "selectborderwidth": 1,  # Tk's default on a Canvas alone
        # How far from an item's ink still counts as being on it. Tk's
        # default is 1, and a terminal needs it more than Tk does: a thin
        # outline is one pixel wide and a click only names a whole cell.
        "closeenough": 1,
        # Whether the view stays inside the scroll region. TkCurses-gm66.10.
        "confine": 1,
        "height": 10,
        "offset": "0,0",
        "relief": "flat",
        "scrollregion": None,
        "state": "normal",
        "takefocus": False,
        "width": 40,
        "xscrollcommand": None,
        "xscrollincrement": 0,
        "yscrollcommand": None,
        "yscrollincrement": 0,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``width`` and ``height`` in cells, ``scrollregion``,
                ``xscrollcommand``, ``yscrollcommand``, and the standard
                options.
        """
        self._items: list[_CanvasItem] = []
        self._ids = itertools.count(1)
        self._left = 0
        self._top = 0
        #: Tag or id -> sequence -> (funcid, callback), in binding order.
        self._item_bindings: dict[
            str, dict[str, list[tuple[str, Callable[[Event], Any]]]]
        ] = {}
        self._current: int | None = None
        #: The text item with the insertion cursor, and each text item's
        #: cursor position: Tk keeps one per item and shows the focus item's.
        self._focus_item: int | None = None
        self._insert_index: dict[int, int] = {}
        #: The selection: which item, its first and last character, and the
        #: anchor ``select_to`` measures from, with the item it is in.
        self._selection_item: int | None = None
        self._selection_first = 0
        self._selection_last = -1
        self._anchor_item: int | None = None
        self._anchor = 0
        self._scan_mark = (0, 0, 0, 0)
        self._insert_at: tuple[int, int] | None = None
        #: File bitmaps made for items, by file and colours.
        self._bitmap_files: dict[tuple[str, str, str], Image] = {}
        #: Each embedded widget and the window item showing it, and where
        #: each was last put, so a redraw re-lays them out only on a change.
        self._windows: dict[BaseWidget, int] = {}
        self._window_places: dict[BaseWidget, Rect | None] = {}
        super().__init__(master, cnf, name=name, **kw)
        self._apply_requested_size()
        self._install_class_bindings()

    def _install_class_bindings(self) -> None:
        """Route mouse events to whichever item is under the pointer."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        for sequence in (
            "<Button-1>",
            "<ButtonRelease-1>",
            "<Motion>",
            "<Double-Button-1>",
        ):
            self.bind_class(name, sequence, _canvas_mouse)

    # --------------------------------------------------------------- options

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-measuring and repainting as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if {"width", "height"} & set(given):
            self._apply_requested_size()
            self._invalidate_layout()
        if "confine" in given:
            # Measured: turning it back on pulls a view that had wandered off
            # the region back inside, at once.
            self._top = self._confined(self._top, vertical=True)
            self._left = self._confined(self._left, vertical=False)
        self._redraw()
        self._report_view()
        return result

    config = configure

    def _apply_requested_size(self) -> None:
        """Ask for the configured cells, plus border and padding."""
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        self._request_size(
            int(self._options["width"]) + 2 * int(self._options["padx"]) + edge,
            int(self._options["height"]) + 2 * int(self._options["pady"]) + edge,
        )

    def _plane_size(self) -> tuple[int, int]:
        """The visible plane, in pixels, falling back to the options.

        Before the widget is laid out its area is nothing, and a canvas asked
        what it can show would answer nothing - so scrolling and ``bbox``
        would both be wrong until the first paint.
        """
        area = self._text_area()
        if area.width > 0 and area.height > 0:
            return (area.width, area.height * 2)
        return (
            max(1, int(self._options["width"])),
            max(1, int(self._options["height"])) * 2,
        )

    def _text_area(self) -> Rect:
        """Where the drawing goes, in cells relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        return Rect(
            edge + padx,
            edge + pady,
            max(0, self._rect.width - 2 * (edge + padx)),
            max(0, self._rect.height - 2 * (edge + pady)),
        )

    # ----------------------------------------------------------- making items

    def create_arc(self, *args: Any, **kw: Any) -> int:
        """Draw part of the oval in a box: ``start`` degrees counter-clockwise
        from three o'clock, through ``extent`` more, closed as ``style``
        says - ``pieslice`` by two radii, ``chord`` by a straight line, or
        ``arc``, open and never filled. Returns the item id.

        Angles are measured on the oval, as Tk measures them, so a quarter
        of a wide box is a quarter of its outline. ``start`` reads back
        between 0 and 360, and ``extent`` modulo 360.

        Sample output:
            # size: 40x10
            canvas = tk.Canvas(root, width=36, height=8)
            canvas.create_arc(1, 1, 13, 13, extent=270, fill="red")
            canvas.create_arc(13, 1, 25, 13, start=30, extent=200, style="chord",
                              fill="cyan")
            canvas.create_arc(25, 1, 35, 13, start=-60, extent=240, style="arc")
            canvas.pack()
        """
        return self._create("arc", args, kw, least=2, exactly=2)

    def create_bitmap(self, *args: Any, **kw: Any) -> int:
        """Show a bitmap at a point, placed by ``anchor``. Returns the item id.

        ``bitmap="@file"`` draws the XBM file's bits on the half-cell plane,
        in ``foreground`` on ``background``. One of Tk's ten built-in names
        draws as one character standing for it, in a cell of its own, like a
        text item's. Each option has an ``active`` variant, shown while the
        pointer is over the item, and a ``disabled`` one.

        Differences from tkinter:
            A built-in bitmap is one cell, so its ``bbox`` is that cell and
            not Tk's 16 pixels or so.
        """
        return self._create("bitmap", args, kw, least=1, exactly=1)

    def create_image(self, *args: Any, **kw: Any) -> int:
        """Show an image at a point, placed by ``anchor``. Returns the item id.

        The image is drawn on the canvas's half-cell plane, one image pixel
        to one canvas pixel, and follows the image: a ``put`` or a resize
        shows at once. ``activeimage`` is shown while the pointer is over
        the item, ``disabledimage`` while it or the canvas is disabled.

        Sample output:
            # size: 40x10
            dot = tk.PhotoImage(width=12, height=12)
            dot.put("red", to=(0, 0, 12, 12))
            dot.put("yellow", to=(3, 3, 9, 9))
            canvas = tk.Canvas(root, width=36, height=8)
            canvas.create_image(18, 8, image=dot)
            canvas.create_image(2, 2, image=dot, anchor="nw")
            canvas.pack()

        Differences from tkinter:
            An image that is deleted while an item shows it leaves the item
            with nothing to draw and no ``bbox``; Tk keeps the old extent.
        """
        return self._create("image", args, kw, least=1, exactly=1)

    def create_window(self, *args: Any, **kw: Any) -> int:
        """Show a widget at a point on the canvas. Returns the item id.

        The canvas becomes the widget's geometry manager - ``winfo_manager``
        answers ``canvas`` - and moves it with the item and with the view,
        taking it off the screen while the item is hidden or wholly out of
        view. ``width`` and ``height`` set its size, 0 meaning the size it
        asks for. The widget must be the canvas's child or a child of one of
        its ancestors, and not a toplevel. Given to a second item, or packed,
        gridded or placed, it leaves the first; destroyed, the item is left
        with no window.

        Sample output:
            # size: 40x10
            canvas = tk.Canvas(root, width=36, height=8)
            canvas.create_oval(2, 2, 34, 14, outline="cyan")
            button = tk.Button(canvas, text="Inside")
            canvas.create_window(18, 8, window=button)
            canvas.pack()

        Differences from tkinter:
            ``width`` and ``height`` are canvas pixels, like the item's
            point: a cell is one pixel wide and two high, so ``height=6`` is
            three rows. A window's top snaps to a whole row, as a text item's
            does, because a widget is drawn in cells.
        """
        return self._create("window", args, kw, least=1, exactly=1)

    def create_line(self, *args: Any, **kw: Any) -> int:
        """Draw a run of connected straight segments. Returns the item id."""
        return self._create("line", args, kw, least=2)

    def create_rectangle(self, *args: Any, **kw: Any) -> int:
        """Draw a rectangle from two opposite corners."""
        return self._create("rectangle", args, kw, least=2, exactly=2)

    def create_oval(self, *args: Any, **kw: Any) -> int:
        """Draw the ellipse inscribed in the rectangle given by two corners."""
        return self._create("oval", args, kw, least=2, exactly=2)

    def create_polygon(self, *args: Any, **kw: Any) -> int:
        """Draw a closed shape through three or more points."""
        return self._create("polygon", args, kw, least=3)

    def create_text(self, *args: Any, **kw: Any) -> int:
        """Draw a string at a point, snapped to the nearest cell row."""
        return self._create("text", args, kw, least=1, exactly=1)

    def _create(
        self,
        kind: str,
        args: tuple[Any, ...],
        options: dict[str, Any],
        *,
        least: int,
        exactly: int | None = None,
    ) -> int:
        """Make an item of one kind, checking its coordinates and options.

        Raises:
            TclError: If there are too few points, the wrong number of them,
                or an option the item does not take.
        """
        options = _given(None, options)
        coords = _canvas_coords(args)
        points = len(coords) // 2
        if points < least or (exactly is not None and points != exactly):
            raise TclError(f"wrong # coordinates: expected {exactly or least}")
        item = _CanvasItem(
            ident=next(self._ids),
            kind=kind,
            coords=coords,
            options=self._checked_item_options(kind, options),
        )
        self._items.append(item)
        if kind == "window":
            self._embed(item)
        self._redraw()
        return item.ident

    def _checked_item_options(self, kind: str, given: dict[str, Any]) -> dict[str, Any]:
        """Resolve an item's options against what its type accepts.

        Raises:
            TclError: If an option is not one the type takes.
        """
        spec = {**self._COMMON_ITEM_OPTIONS, **self._ITEM_OPTIONS[kind]}
        options = dict(spec)
        for name, value in given.items():
            option = _OPTION_ALIASES.get(name, name)
            if option not in spec:
                raise TclError(f'unknown option "-{name}"')
            options[option] = self._checked_item_value(option, value)
        return options

    def _checked_item_value(self, option: str, value: Any) -> Any:
        """An item option's value, a colour refused as Tk refuses it: when it
        is given, not when it is drawn - where it broke the window's layout.
        TkCurses-f760."""
        if option in _ITEM_COLOUR_OPTIONS:
            _colour_or_terminals(self, value)
        if option == "anchor":
            return _tcl_index(value, _ANCHOR_NAMES, "anchor")
        if option in _ITEM_IMAGE_OPTIONS:
            name = _image_name(self, value)
            image = self.tk.images.get(name)
            if image is not None:
                # One watch per canvas: an image shown by several items
                # repaints the canvas once.
                image._watch(self, self._redraw)
            return name
        if option in _ITEM_BITMAP_OPTIONS:
            return _bitmap(self, value)
        if option in ("width", "height"):
            return _signed_distance(self, value)
        if option == "window":
            return self._window_value(value)
        # Measured on Tk 9.0.2: start reads back in [0, 360), so -30 is 330;
        # extent is fmod 360, so 400 is 40 and 360 is 0; a style is taken by
        # any unambiguous prefix.
        if option == "start":
            return _tcl_float(self, value) % 360.0
        if option == "extent":
            return math.fmod(_tcl_float(self, value), 360.0)
        if option == "style":
            word = str(value)
            styles = [
                s for s in ("arc", "chord", "pieslice") if word and s.startswith(word)
            ]
            if len(styles) != 1:
                raise TclError(
                    f'bad -style option "{word}": must be arc, chord, or pieslice'
                )
            return styles[0]
        return value

    # ----------------------------------------------------------- finding them

    def _item(self, ident: int) -> _CanvasItem | None:
        """One item by id, or None if it has been deleted."""
        return next((item for item in self._items if item.ident == ident), None)

    def _matching(self, spec: Any) -> list[_CanvasItem]:
        """Every item a tag, an id, or ``all`` names, in display order."""
        if isinstance(spec, int):
            item = self._item(spec)
            return [item] if item is not None else []
        tag = str(spec)
        if tag == "all":
            return list(self._items)
        if tag == "current":
            # Tk's dynamic tag for whatever the pointer is over. It is not
            # stored on the item, so gettags() does not report it - the one
            # place this differs from Tk, and the alternative is gettags
            # returning a tag nobody set.
            item = None if self._current is None else self._item(self._current)
            return [item] if item is not None else []
        if tag.isdigit():
            item = self._item(int(tag))
            return [item] if item is not None else []
        return [item for item in self._items if tag in item.tags]

    def find_all(self) -> tuple[int, ...]:
        """Every item, in the order they are drawn."""
        return tuple(item.ident for item in self._items)

    def find_withtag(self, spec: Any) -> tuple[int, ...]:
        """Every item a tag or an id names."""
        return tuple(item.ident for item in self._matching(spec))

    def find_overlapping(self, x0: int, y0: int, x1: int, y1: int) -> tuple[int, ...]:
        """Every item whose extent meets a rectangle. Hidden items are
        passed over, as Tk passes them."""
        return tuple(item.ident for item in self._in_area((x0, y0, x1, y1)))

    def find_enclosed(self, x1: int, y1: int, x2: int, y2: int) -> tuple[int, ...]:
        """Every item whose extent lies wholly inside a rectangle, edges
        included."""
        return tuple(
            item.ident for item in self._in_area((x1, y1, x2, y2), enclosed=True)
        )

    def _in_area(
        self, corners: tuple[Any, Any, Any, Any], *, enclosed: bool = False
    ) -> list[_CanvasItem]:
        """The items a rectangle meets, or wholly holds, in display order."""
        x0, y0, x1, y1 = (_canvas_number(value) for value in corners)
        left, right = sorted((x0, x1))
        top, bottom = sorted((y0, y1))
        found = []
        for item in self._items:
            if str(item.options.get("state")) == "hidden":
                continue
            box = self._item_bbox(item)
            if box is None:
                continue
            if enclosed:
                inside = (
                    box[0] >= left
                    and box[2] <= right
                    and box[1] >= top
                    and box[3] <= bottom
                )
            else:
                inside = (
                    box[0] <= right
                    and box[2] >= left
                    and box[1] <= bottom
                    and box[3] >= top
                )
            if inside:
                found.append(item)
        return found

    def find_closest(
        self, x: int, y: int, halo: Any = None, start: Any = None
    ) -> tuple[int, ...]:
        """The item nearest a point, or nothing if the canvas is empty.

        Distance is measured to the item's extent rather than to its ink,
        which is Tk's own approximation for everything but a line. Any item
        within ``halo`` counts as touching the point. Of items equally near,
        the topmost wins; with ``start``, the search begins there and goes
        round the display list, so the one just below ``start`` wins.

        Raises:
            TclError: If ``halo`` is negative, in Tk's words.
        """
        found = self._closest(x, y, halo, start)
        return () if found is None else (found,)

    def _closest(self, x: Any, y: Any, halo: Any, start: Any) -> int | None:
        """Tk's ``find closest``, step for step from ``tkCanvas.c``: walk the
        display list circularly from ``start``, keeping any item at most as
        far as the best so far."""
        point_x, point_y = _canvas_number(x), _canvas_number(y)
        reach = 0.0 if halo is None or halo == "" else float(_canvas_number(halo))
        if reach < 0:
            raise TclError(f'can\'t have negative halo value "{reach:f}"')
        shown = [
            item for item in self._items if str(item.options.get("state")) != "hidden"
        ]
        if not shown:
            return None
        first = 0
        if start is not None and start != "":
            named = self._matching(start)
            if named:
                order = [item.ident for item in self._items]
                position = order.index(named[0].ident)
                after = [
                    i
                    for i, item in enumerate(shown)
                    if order.index(item.ident) >= position
                ]
                first = after[0] if after else 0
        sequence = shown[first:] + shown[:first]

        def distance(item: _CanvasItem) -> float:
            box = self._item_bbox(item)
            if box is None:
                return float("inf")
            near_x = min(max(point_x, box[0]), box[2])
            near_y = min(max(point_y, box[1]), box[3])
            gap = math.hypot(near_x - point_x, near_y - point_y) - reach
            return max(0.0, gap)

        best = sequence[0]
        best_distance = distance(best)
        for item in sequence[1:]:
            gap = distance(item)
            if gap <= best_distance:
                best, best_distance = item, gap
        return best.ident

    def find_above(self, spec: Any) -> tuple[int, ...]:
        """The item just above the topmost one ``spec`` names."""
        found = self._search(("above", spec))
        return tuple(found)

    def find_below(self, spec: Any) -> tuple[int, ...]:
        """The item just below the lowest one ``spec`` names."""
        return tuple(self._search(("below", spec)))

    def find(self, *args: Any) -> tuple[int, ...]:
        """Tk's ``find``: ``above``, ``all``, ``below``, ``closest``,
        ``enclosed``, ``overlapping`` or ``withtag``, then its arguments.

        Raises:
            TclError: If the search is not one of those, or has the wrong
                number of arguments, in Tk's words.
        """
        return tuple(self._search(args, command="find"))

    _SEARCHES: ClassVar[dict[str, tuple[int, int, str]]] = {
        "above": (1, 1, "tagOrId"),
        "all": (0, 0, ""),
        "below": (1, 1, "tagOrId"),
        "closest": (2, 4, "x y ?halo? ?start?"),
        "enclosed": (4, 4, "x1 y1 x2 y2"),
        "overlapping": (4, 4, "x1 y1 x2 y2"),
        "withtag": (1, 1, "tagOrId"),
    }

    def _search(self, args: tuple[Any, ...], command: str = "find") -> list[int]:
        """The items a Tk search specification names, in display order."""
        if not args:
            raise TclError(
                f'wrong # args: should be "{self} {command} searchCommand ?arg ...?"'
            )
        kind, rest = str(args[0]), args[1:]
        if kind not in self._SEARCHES:
            raise TclError(
                f'bad search command "{kind}": must be above, all, below, closest,'
                " enclosed, overlapping, or withtag"
            )
        least, most, usage = self._SEARCHES[kind]
        if not least <= len(rest) <= most:
            words = f"{kind} {usage}".strip()
            raise TclError(f'wrong # args: should be "{self} {command} {words}"')
        if kind == "all":
            return [item.ident for item in self._items]
        if kind == "withtag":
            return [item.ident for item in self._matching(rest[0])]
        if kind in ("above", "below"):
            named = {item.ident for item in self._matching(rest[0])}
            order = [item.ident for item in self._items]
            places = [i for i, ident in enumerate(order) if ident in named]
            if not places:
                return []
            if kind == "above":
                at = places[-1] + 1
                return [order[at]] if at < len(order) else []
            at = places[0] - 1
            return [order[at]] if at >= 0 else []
        if kind == "closest":
            found = self._closest(
                rest[0],
                rest[1],
                rest[2] if len(rest) > 2 else None,
                rest[3] if len(rest) > 3 else None,
            )
            return [] if found is None else [found]
        return [
            item.ident
            for item in self._in_area(
                (rest[0], rest[1], rest[2], rest[3]), enclosed=kind == "enclosed"
            )
        ]

    # ------------------------------------------------------------ changing them

    def coords(self, spec: Any, *args: Any) -> list[int] | None:
        """Read or replace an item's coordinates."""
        items = self._matching(spec)
        if not args:
            return list(items[0].coords) if items else []
        coords = _canvas_coords(args)
        for item in items:
            item.coords = list(coords)
        self._redraw()
        return None

    def move(self, spec: Any, dx: int, dy: int) -> None:
        """Shift everything a tag names by a distance in pixels."""
        for item in self._matching(spec):
            item.coords = [
                value + (int(dx) if index % 2 == 0 else int(dy))
                for index, value in enumerate(item.coords)
            ]
        self._redraw()

    def delete(self, *specs: Any) -> None:
        """Remove everything the tags name."""
        doomed = {item.ident for spec in specs for item in self._matching(spec)}
        self._items = [item for item in self._items if item.ident not in doomed]
        if self._current in doomed:
            self._current = None
        if self._focus_item in doomed:
            self._focus_item = None
        if self._selection_item in doomed:
            self._selection_item = None
        if self._anchor_item in doomed:
            self._anchor_item = None
        for ident in doomed:
            self._insert_index.pop(ident, None)
        for widget, ident in list(self._windows.items()):
            if ident in doomed:
                # Measured on Tk 9.0.2: deleting the item unmaps the window
                # and leaves it with no manager.
                del self._windows[widget]
                widget._leave_manager()
                widget._unmap()
        self._redraw()

    def itemconfigure(
        self, spec: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> Any:
        """Set options on everything a tag names, or read one item's options.

        Raises:
            TclError: If an option is not one the item's type takes.
        """
        items = self._matching(spec)
        given = _given(cnf, kw)
        if not cnf and not kw:
            return dict(items[0].options) if items else {}
        if not given:  # every option None, which tkinter drops
            return None
        for item in items:
            spec_for_kind = {
                **self._COMMON_ITEM_OPTIONS,
                **self._ITEM_OPTIONS[item.kind],
            }
            for name, value in given.items():
                option = _OPTION_ALIASES.get(name, name)
                if option not in spec_for_kind:
                    raise TclError(f'unknown option "-{name}"')
                item.options[option] = self._checked_item_value(option, value)
            if item.kind == "window":
                self._embed(item)
        self._redraw()
        return None

    itemconfig = itemconfigure

    def itemcget(self, spec: Any, option: str) -> Any:
        """One option of the first item a tag names.

        Raises:
            TclError: If nothing matches, or the option is not one it takes.
        """
        items = self._matching(spec)
        if not items:
            raise TclError(f'unknown item "{spec}"')
        name = _OPTION_ALIASES.get(option, option)
        if name not in items[0].options:
            raise TclError(f'unknown option "-{option}"')
        return items[0].options[name]

    def type(self, spec: Any) -> str | None:
        """What kind of item a tag names, or None if nothing does."""
        items = self._matching(spec)
        return items[0].kind if items else None

    def bbox(self, *specs: Any) -> tuple[int, int, int, int] | None:
        """The extent of everything the tags name, in pixels."""
        boxes = [
            box
            for spec in (specs or ("all",))
            for item in self._matching(spec)
            if (box := self._item_bbox(item)) is not None
        ]
        if not boxes:
            return None
        return (
            min(box[0] for box in boxes),
            min(box[1] for box in boxes),
            max(box[2] for box in boxes),
            max(box[3] for box in boxes),
        )

    def _item_bbox(self, item: _CanvasItem) -> tuple[int, int, int, int] | None:
        """One item's extent, in pixels."""
        if item.kind == "text":
            return self._text_bbox(item)
        if item.kind == "window":
            return self._window_box(item)
        if item.kind in ("image", "bitmap"):
            cell = self._bitmap_cell(item)
            if cell is not None:
                column, row, _ = cell
                return (column, row * 2, column, row * 2 + 1)
            placed = self._picture(item)
            if placed is None:
                return None
            picture, (x0, y0) = placed
            # Measured on Tk 9.0.2: a 10x6 image centred on (50, 50) is
            # (45, 47, 55, 53) - its own size exactly, the far edges one past.
            return (x0, y0, x0 + picture.width(), y0 + picture.height())
        if item.kind == "arc":
            # The part drawn, as Tk's: a quarter's box is a quarter of the
            # oval's, and a pieslice's takes in the centre.
            (x0, y0), (x1, y1) = item.points()[:2]
            return bbox_of(
                arc_outline_pixels(
                    x0,
                    y0,
                    x1,
                    y1,
                    float(item.options["start"]),
                    float(item.options["extent"]),
                    str(item.options["style"]),
                )
            )
        return bbox_of(item.points())

    def _text_bbox(self, item: _CanvasItem) -> tuple[int, int, int, int] | None:
        """A text item's extent, in pixels, cell-aligned as it is drawn."""
        placed = self._text_origin(item)
        if placed is None:
            return None
        column, row, lines = placed
        width = max((cells(line) for line in lines), default=0)
        return (
            column,
            row * 2,
            column + max(0, width - 1),
            row * 2 + 2 * len(lines) - 1,
        )

    # ---------------------------------------------------------------- tagging

    def gettags(self, spec: Any) -> tuple[str, ...]:
        """The tags on the first item a tag or id names."""
        items = self._matching(spec)
        return items[0].tags if items else ()

    def addtag_withtag(self, new: str, spec: Any) -> None:
        """Add a tag to everything another tag names."""
        self._add_tag(new, [item.ident for item in self._matching(spec)])

    def _add_tag(self, new: Any, idents: list[int]) -> None:
        """Put ``new`` on each item, once."""
        tag = str(new)
        for ident in idents:
            item = self._item(ident)
            if item is not None and tag not in item.tags:
                item.options["tags"] = (*item.tags, tag)

    def addtag(self, *args: Any) -> None:
        """Tk's ``addtag``: a new tag, then a search as :meth:`find` takes."""
        if not args:
            raise TclError(
                f'wrong # args: should be "{self} addtag tag searchCommand ?arg ...?"'
            )
        self._add_tag(args[0], self._search(args[1:], command=f"addtag {args[0]}"))

    def addtag_above(self, newtag: str, tagOrId: Any) -> None:
        """Tag the item just above the topmost one ``tagOrId`` names."""
        self.addtag(newtag, "above", tagOrId)

    def addtag_all(self, newtag: str) -> None:
        """Tag every item."""
        self.addtag(newtag, "all")

    def addtag_below(self, newtag: str, tagOrId: Any) -> None:
        """Tag the item just below the lowest one ``tagOrId`` names."""
        self.addtag(newtag, "below", tagOrId)

    def addtag_closest(
        self, newtag: str, x: Any, y: Any, halo: Any = None, start: Any = None
    ) -> None:
        """Tag the item nearest a point, as :meth:`find_closest` finds it."""
        found = self._closest(x, y, halo, start)
        self._add_tag(newtag, [] if found is None else [found])

    def addtag_enclosed(self, newtag: str, x1: Any, y1: Any, x2: Any, y2: Any) -> None:
        """Tag every item wholly inside a rectangle."""
        self.addtag(newtag, "enclosed", x1, y1, x2, y2)

    def addtag_overlapping(
        self, newtag: str, x1: Any, y1: Any, x2: Any, y2: Any
    ) -> None:
        """Tag every item a rectangle meets."""
        self.addtag(newtag, "overlapping", x1, y1, x2, y2)

    # ------------------------------------------------------------ transforms

    def scale(
        self,
        tagOrId: Any,
        xOrigin: Any,
        yOrigin: Any,
        xScale: Any,
        yScale: Any,
    ) -> None:
        """Scale every item named about a point: each coordinate moves to
        ``origin + (coordinate - origin) * scale``. A text item's point
        moves; its text keeps its size.

        Raises:
            TclError: If a number is not one, in Tk's words.
        """
        x0, y0 = _tcl_float(self, xOrigin), _tcl_float(self, yOrigin)
        across, down = _tcl_float(self, xScale), _tcl_float(self, yScale)
        for item in self._matching(tagOrId):
            item.coords = [
                round(x0 + (value - x0) * across)
                if index % 2 == 0
                else round(y0 + (value - y0) * down)
                for index, value in enumerate(item.coords)
            ]
        self._redraw()

    def moveto(self, tagOrId: Any, x: Any = "", y: Any = "") -> None:
        """Move every item named, together, so that the top-left corner of
        the lowest one's extent is at ``(x, y)``. An empty ``x`` or ``y``
        leaves that axis where it is."""
        items = self._matching(tagOrId)
        box = self._item_bbox(items[0]) if items else None
        if box is None:
            return
        dx = 0 if x == "" else round(_tcl_float(self, x)) - box[0]
        dy = 0 if y == "" else round(_tcl_float(self, y)) - box[1]
        self.move(tagOrId, dx, dy)

    def postscript(self, cnf: dict[str, Any] | None = None, **kw: Any) -> str:
        """Not available: there is no PostScript to render a terminal into.

        Raises:
            TclError: Always.

        Differences from tkinter:
            tkinter returns the canvas as PostScript, or writes it to a
            file. A canvas of terminal cells has no such rendering.
        """
        del cnf, kw
        raise TclError(
            "postscript is not available: a terminal canvas has no PostScript"
        )

    # ------------------------------------------------------------- scanning

    def scan_mark(self, x: Any, y: Any) -> None:
        """Remember where a scan starts, and where the view was.

        Raises:
            TclError: If ``x`` or ``y`` is not an integer, in Tk's words.
        """
        self._scan_mark = (
            _tcl_integer(None, x),
            _tcl_integer(None, y),
            self._left,
            self._top,
        )

    def scan_dragto(self, x: Any, y: Any, gain: Any = 10) -> None:
        """Move the view by ``gain`` times how far ``(x, y)`` is from the
        mark, as Tk's ``scan dragto`` does.

        Differences from tkinter:
            ``y`` is in rows, as ``event.y`` is here, and a row is two of
            the canvas's units, so the view moves twice as far down per row
            as across per column.
        """
        mark_x, mark_y, left, top = self._scan_mark
        factor = _tcl_integer(None, gain)
        new_left = left - factor * (_tcl_integer(None, x) - mark_x)
        new_top = top - factor * 2 * (_tcl_integer(None, y) - mark_y)
        for vertical, position in ((False, new_left), (True, new_top)):
            increment = self._increment(vertical=vertical)
            if increment:
                position = increment * ((position + increment // 2) // increment)
            position = self._confined(position, vertical=vertical)
            if vertical:
                self._top = position - position % 2
            else:
                self._left = position
        self._redraw()
        self._report_view()

    # ---------------------------------------------------------- editing text

    def focus(self, *args: Any) -> Any:
        """The text item with the insertion cursor, or give it to one.

        With no argument, the item's id, or ``""`` if none has it. With a
        tag or id, the first text item it names takes it; ``""`` takes it
        from every item. The cursor shows only while the canvas itself has
        the keyboard focus, which :meth:`focus_set` gives it.

        As in tkinter, this shadows ``Misc.focus``: ``canvas.focus()`` does
        not give the canvas the keyboard focus.
        """
        if not args:
            return "" if self._focus_item is None else self._focus_item
        if args[0] == "":
            self._focus_item = None
        else:
            texts = [item for item in self._matching(args[0]) if item.kind == "text"]
            if texts:
                self._focus_item = texts[0].ident
        self._redraw()
        return ""

    def _indexable(self, spec: Any, *, selectable: bool = False) -> _CanvasItem | None:
        """The first item ``spec`` names that takes an index: a text item,
        or a line or polygon, whose index counts coordinates."""
        kinds = ("text",) if selectable else ("text", "line", "polygon")
        return next((item for item in self._matching(spec) if item.kind in kinds), None)

    def _index_of(self, item: _CanvasItem, index: Any) -> int:
        """An index in ``item``, as Tk reads one: a number, ``end``,
        ``insert``, ``sel.first``, ``sel.last`` or ``@x,y``."""
        text = str(item.options.get("text") or "")
        size = len(text) if item.kind == "text" else len(item.coords)
        word = str(index)
        if isinstance(index, int) or _is_integer_text(word):
            number = max(0, min(int(word), size))
            return number - number % 2 if item.kind != "text" else number
        if word == "end":
            return size
        if word.startswith("@"):
            x, _, y = word[1:].partition(",")
            try:
                point = (round(float(x)), round(float(y)))
            except ValueError:
                raise TclError(f'bad index "{word}"') from None
            return self._index_at_point(item, *point)
        if item.kind == "text" and word == "insert":
            return min(self._insert_index.get(item.ident, 0), size)
        if item.kind == "text" and word in ("sel.first", "sel.last"):
            if self._selection_item != item.ident:
                raise TclError("selection isn't in item")
            return (
                self._selection_first if word == "sel.first" else self._selection_last
            )
        raise TclError(f'bad index "{word}"')

    def _index_at_point(self, item: _CanvasItem, x: int, y: int) -> int:
        """The character, or the point of a line, nearest ``(x, y)``."""
        if item.kind != "text":
            points = item.points()
            if not points:
                return 0
            nearest = min(
                range(len(points)),
                key=lambda i: (points[i][0] - x) ** 2 + (points[i][1] - y) ** 2,
            )
            return nearest * 2
        placed = self._text_origin(item)
        if placed is None:
            return 0
        column, row, lines = placed
        width = max((cells(line) for line in lines), default=0)
        justify = str(item.options.get("justify") or "left")
        line_number = max(0, min(y // 2 - row, len(lines) - 1))
        line = lines[line_number]
        offset = x - (column + align_offset(cells(line), width, justify))
        position = 0
        for character in line:
            if offset < char_cells(character) or offset <= 0:
                break
            offset -= char_cells(character)
            position += 1
        return sum(len(each) + 1 for each in lines[:line_number]) + position

    def index(self, tagOrId: Any, index: Any) -> int:
        """Where ``index`` is in the first indexable item named: a character
        of a text item, or a coordinate of a line or polygon.

        Raises:
            TclError: If no such item, or a bad index, in Tk's words.
        """
        item = self._indexable(tagOrId)
        if item is None:
            raise TclError(f'can\'t find an indexable item "{tagOrId}"')
        return self._index_of(item, index)

    def icursor(self, tagOrId: Any, index: Any) -> None:
        """Put the insertion cursor of each text item named before ``index``."""
        for item in self._matching(tagOrId):
            if item.kind == "text":
                self._insert_index[item.ident] = self._index_of(item, index)
        self._redraw()

    def insert(self, tagOrId: Any, beforethis: Any, string: Any) -> None:
        """Insert text before ``beforethis`` in each text item named, or
        coordinates into each line and polygon named.

        The cursor and the selection move with the text after them, as in
        Tk's ``tkCanvText.c``.
        """
        for item in self._matching(tagOrId):
            if item.kind == "text":
                self._insert_text(item, self._index_of(item, beforethis), str(string))
            elif item.kind in ("line", "polygon"):
                try:
                    added = _canvas_coords(
                        string.split() if isinstance(string, str) else [string]
                    )
                except (TypeError, ValueError):
                    continue  # Tk inserts nothing, and says nothing
                at = self._index_of(item, beforethis)
                item.coords[at:at] = added[: len(added) - len(added) % 2]
        self._redraw()

    def _insert_text(self, item: _CanvasItem, at: int, string: str) -> None:
        text = str(item.options.get("text") or "")
        item.options["text"] = text[:at] + string + text[at:]
        length = len(string)
        if self._selection_item == item.ident:
            if self._selection_first >= at:
                self._selection_first += length
            if self._selection_last >= at:
                self._selection_last += length
        if self._anchor_item == item.ident and self._anchor >= at:
            self._anchor += length
        if self._insert_index.get(item.ident, 0) >= at:
            self._insert_index[item.ident] = (
                self._insert_index.get(item.ident, 0) + length
            )

    def dchars(self, tagOrId: Any, first: Any, last: Any = None) -> None:
        """Delete the characters ``first`` to ``last``, both included, from
        each text item named - or the points they name from each line and
        polygon. ``last`` defaults to ``first``."""
        for item in self._matching(tagOrId):
            if item.kind not in ("text", "line", "polygon"):
                continue
            start = self._index_of(item, first)
            end = self._index_of(item, first if last is None else last)
            if item.kind == "text":
                self._delete_text(item, start, end)
            else:
                end -= end % 2
                del item.coords[start : end + 2]
        self._redraw()

    def _delete_text(self, item: _CanvasItem, first: int, last: int) -> None:
        text = str(item.options.get("text") or "")
        first, last = max(first, 0), min(last, len(text) - 1)
        if first > last:
            return
        count = last + 1 - first
        item.options["text"] = text[:first] + text[last + 1 :]
        if self._selection_item == item.ident:
            if self._selection_first > first:
                self._selection_first = max(first, self._selection_first - count)
            if self._selection_last >= first:
                self._selection_last = max(first - 1, self._selection_last - count)
            if self._selection_first > self._selection_last:
                self._selection_item = None
        if self._anchor_item == item.ident and self._anchor > first:
            self._anchor = max(first, self._anchor - count)
        cursor = self._insert_index.get(item.ident, 0)
        if cursor > first:
            self._insert_index[item.ident] = max(first, cursor - count)

    # ------------------------------------------------------------ selection

    def _selectable(self, spec: Any) -> _CanvasItem:
        item = self._indexable(spec, selectable=True)
        if item is None:
            raise TclError(f'can\'t find an indexable and selectable item "{spec}"')
        return item

    def select_from(self, tagOrId: Any, index: Any) -> None:
        """Set the anchor the selection is measured from."""
        item = self._selectable(tagOrId)
        self._anchor_item, self._anchor = item.ident, self._index_of(item, index)

    def select_to(self, tagOrId: Any, index: Any) -> None:
        """Select from the anchor to ``index``, both included."""
        item = self._selectable(tagOrId)
        self._select_to(item, self._index_of(item, index))

    def _select_to(self, item: _CanvasItem, index: int) -> None:
        """Tk's ``CanvasSelectTo``."""
        if self._anchor_item != item.ident:
            self._anchor_item, self._anchor = item.ident, index
        if self._anchor <= index:
            first, last = self._anchor, index
        else:
            first, last = index, self._anchor - 1
        self._selection_item = item.ident
        self._selection_first, self._selection_last = first, last
        self._redraw()

    def select_adjust(self, tagOrId: Any, index: Any) -> None:
        """Move whichever end of the selection is nearer ``index`` to it."""
        item = self._selectable(tagOrId)
        at = self._index_of(item, index)
        if self._selection_item == item.ident:
            if at < (self._selection_first + self._selection_last) // 2:
                self._anchor = self._selection_last + 1
            else:
                self._anchor = self._selection_first
            self._anchor_item = item.ident
        self._select_to(item, at)

    def select_clear(self) -> None:
        """Select nothing."""
        self._selection_item = None
        self._redraw()

    def select_item(self) -> int | None:
        """The item holding the selection, or None."""
        return self._selection_item

    def _insert_cell(self) -> tuple[int, int] | None:
        return self._insert_at

    def dtag(self, spec: Any, tag: str | None = None) -> None:
        """Remove a tag. Without one, remove the tag that was used to find them."""
        target = str(spec) if tag is None else tag
        for item in self._matching(spec):
            item.options["tags"] = tuple(t for t in item.tags if t != target)

    def tag_raise(self, spec: Any, above: Any = None) -> None:
        """Move items to the front of the drawing order, or above another."""
        self._reorder_items(spec, above, to_front=True)

    def tag_lower(self, spec: Any, below: Any = None) -> None:
        """Move items to the back of the drawing order, or below another."""
        self._reorder_items(spec, below, to_front=False)

    def _reorder_items(self, spec: Any, other: Any, *, to_front: bool) -> None:
        """Shared by tag_raise and tag_lower."""
        moving = self._matching(spec)
        if not moving:
            return
        idents = {item.ident for item in moving}
        rest = [item for item in self._items if item.ident not in idents]
        if other is None:
            self._items = rest + moving if to_front else moving + rest
        else:
            anchors = [
                item for item in self._matching(other) if item.ident not in idents
            ]
            if not anchors:
                self._items = rest + moving if to_front else moving + rest
            else:
                at = rest.index(anchors[-1] if to_front else anchors[0])
                cut = at + 1 if to_front else at
                self._items = rest[:cut] + moving + rest[cut:]
        self._redraw()

    # --------------------------------------------------------- item bindings

    def tag_bind(
        self,
        tagOrId: Any,
        sequence: str | None = None,
        func: Callable[[Event], Any] | None = None,
        add: bool | str | None = None,
    ) -> Any:
        """Bind an event on the items a tag names.

        Unlike :meth:`Misc.bind`, this is not a binding on the widget: the
        event is delivered only while the pointer is over one of the items,
        and ``event.widget`` is still the canvas. The item it happened to is
        the one ``find_withtag("current")`` names, as in Tk.

        Args:
            tagOrId: A tag, or an item id.
            sequence: The event, such as ``"<Button-1>"``.
            func: What to call.
            add: True to keep any binding already there.

        Returns:
            With a callback, a handle :meth:`tag_unbind` takes, as
            :meth:`Misc.bind` returns. With a sequence and no callback, the
            callbacks bound to it; with neither, the sequences bound.

        Differences from tkinter:
            Asked for a sequence's bindings, tkinter answers the Tcl script
            that runs them, which has no meaning without Tcl; the callbacks
            themselves are answered here.
        """
        bindings = self._item_bindings.get(str(tagOrId), {})
        if sequence is None:
            return tuple(name for name, bound in bindings.items() if bound)
        if func is None:
            return tuple(callback for _funcid, callback in bindings.get(sequence, ()))
        funcid = f"canvas{next(_CANVAS_BINDING_IDS)}{getattr(func, '__name__', '')}"
        bindings = self._item_bindings.setdefault(str(tagOrId), {})
        entry = (funcid, func)
        if add in (True, "+"):
            bindings.setdefault(sequence, []).append(entry)
        else:
            bindings[sequence] = [entry]
        return funcid

    def tag_unbind(
        self, tagOrId: Any, sequence: str, funcid: str | None = None
    ) -> None:
        """Remove the bindings a tag has for one event, or only the one
        ``funcid`` names - the handle :meth:`tag_bind` returned."""
        bindings = self._item_bindings.get(str(tagOrId), {})
        if funcid is None:
            bindings.pop(sequence, None)
            return
        bound = bindings.get(sequence, [])
        bindings[sequence] = [entry for entry in bound if entry[0] != funcid]

    def _item_at(self, x: int, y: int) -> int | None:
        """The topmost item whose ink covers a pixel.

        Ink, not extent. A diagonal line's bounding box is the whole
        rectangle it crosses, so testing by extent let a thin line claim
        everything around it - clicking inside a square picked out the
        diagonal drawn across it rather than the square. Tk tests the item's
        real shape too, which also means that clicking the middle of an
        *unfilled* rectangle selects nothing: there is nothing there.

        Both halves of the clicked cell count. A click names a cell, and
        either of the two pixels stacked in it may be the one with ink.
        """
        slack = max(0, int(self._options["closeenough"]))
        reach = range(-slack, slack + 1)
        for item in reversed(self._items):
            if str(item.options.get("state")) == "hidden":
                continue
            box = self._item_bbox(item)
            # The extent is only a cheap filter before the ink is looked at,
            # and it has to admit both halves of the cell for the same reason
            # the ink test does.
            if box is None or not (
                box[0] - slack <= x <= box[2] + slack
                and any(box[1] - slack <= row <= box[3] + slack for row in (y, y ^ 1))
            ):
                continue
            # Text fills the cells it occupies, so its extent is its ink.
            if item.kind == "text":
                return item.ident
            pixels = self._item_pixels(item)
            if any(
                (x + across, row + down) in pixels
                for row in (y, y ^ 1)
                for across in reach
                for down in reach
            ):
                return item.ident
        return None

    def _deliver(self, ident: int | None, sequence: str, event: Event) -> None:
        """Run whatever is bound to one event on one item.

        The item's own id is consulted first, then its tags in the order they
        were given, then ``all`` - which is the order Tk searches, the id
        being the item's first tag there.
        """
        if ident is None:
            return
        item = self._item(ident)
        if item is None:
            return
        keys = [str(ident), *item.tags, "all"]
        if ident == self._current:
            keys.insert(-1, "current")
        for key in keys:
            for _funcid, callback in list(
                self._item_bindings.get(key, {}).get(sequence, ())
            ):
                callback(event)

    # ---------------------------------------------------------------- the view

    def canvasx(
        self,
        screenx: int,
        gridspacing: Any = None,  # noqa: ARG002 - tkinter signature
    ) -> int:
        """The canvas x coordinate shown at a column of this widget's window.

        ``screenx`` is counted from the window's left edge, as ``event.x``
        is, so ``canvas.canvasx(event.x)`` is the canvas coordinate under the
        pointer.

        Differences from tkinter:
            The canvas's coordinates start inside its border, so that nothing
            drawn at 0 is hidden under it; Tk's start at the window's corner,
            under the border and highlight. ``gridspacing`` is accepted and
            ignored.
        """
        # Tk's canvas(n) names the argument screenx and describes it as "a
        # window x-coordinate"; measured on Tk 9.0, canvasx(10) is 10.0 for a
        # canvas packed with padx=50. This took a screen column until
        # TkCurses-0n21, which made canvasx(event.x) wrong for any canvas not
        # at the screen's left edge.
        return int(screenx) - self._text_area().x + self._left

    def canvasy(
        self,
        screeny: int,
        gridspacing: Any = None,  # noqa: ARG002 - tkinter signature
    ) -> int:
        """The canvas y coordinate shown at a row of this widget's window.

        ``screeny`` is counted from the window's top edge, as ``event.y``
        is. A row holds two of the canvas's units, and the answer is the
        upper one, which is the one a click is taken to mean.

        Differences from tkinter:
            As :meth:`canvasx`: from inside the border, and ``gridspacing``
            is ignored. The answer is in half-rows, the canvas's units.
        """
        row = int(screeny) - self._text_area().y
        return row * 2 + self._top

    def _scroll_region(self) -> tuple[int, int, int, int]:
        """What there is to scroll over: the option, or everything drawn."""
        region = self._options["scrollregion"]
        if region:
            values = _canvas_coords(
                region if isinstance(region, (tuple, list)) else region.split()
            )
            if len(values) >= 4:
                return (values[0], values[1], values[2], values[3])
        return self.bbox() or (0, 0, *self._plane_size())

    def yview(self, *args: Any) -> tuple[float, float] | None:
        """Read or move the vertical view, in the shape Tk uses."""
        if not args:
            return self._fractions(vertical=True)
        self._scroll(args, vertical=True)
        return None

    def xview(self, *args: Any) -> tuple[float, float] | None:
        """Read or move the horizontal view."""
        if not args:
            return self._fractions(vertical=False)
        self._scroll(args, vertical=False)
        return None

    def _scroll(self, args: tuple[Any, ...], *, vertical: bool) -> None:
        """Apply one Tk scrolling command to one axis."""
        left, top, right, bottom = self._scroll_region()
        width, height = self._plane_size()
        span = height if vertical else width
        total = max(1, (bottom - top) if vertical else (right - left))
        origin = top if vertical else left
        increment = self._increment(vertical=vertical)
        action = str(args[0])
        if action == "moveto":
            position = origin + int(float(args[1]) * total)
        elif action == "scroll":
            count = int(float(args[1]))
            unit = str(args[2]) if len(args) > 2 else "units"
            # A vertical unit is a cell, which is two pixels: scrolling by one
            # would swap which half of the cell each pixel row lands in, and
            # the whole picture would shimmer.
            default = 2 if vertical else 1
            step = span if unit.startswith("page") else (increment or default)
            position = (self._top if vertical else self._left) + count * step
        else:
            raise TclError(f'bad option "{action}": must be moveto or scroll')
        if increment:
            # Measured on Tk 9.0.2: with an increment of 30, moveto 47 pixels
            # lands on 60, the nearest multiple - the view is only ever on one.
            position = increment * ((position + increment // 2) // increment)
        position = self._confined(position, vertical=vertical)
        if vertical:
            self._top = position - position % 2
        else:
            self._left = position
        self._redraw()
        self._report_view()

    def _increment(self, *, vertical: bool) -> int:
        """``yscrollincrement`` or ``xscrollincrement``, 0 for Tk's default."""
        name = "yscrollincrement" if vertical else "xscrollincrement"
        return _as_int(self._options[name], 0)

    def _confined(self, position: int, *, vertical: bool) -> int:
        """A view origin kept inside the scroll region, while ``confine`` is on.

        Measured on Tk 9.0.2: off, a view scrolls above the region's top, and
        ``moveto 2`` goes twice its height down; on, neither moves past an
        edge, and a region smaller than the window does not scroll at all.
        """
        if not self.getboolean(self._options["confine"]):
            return position
        left, top, right, bottom = self._scroll_region()
        width, height = self._plane_size()
        span = height if vertical else width
        origin = top if vertical else left
        total = max(1, (bottom - top) if vertical else (right - left))
        return max(origin, min(position, origin + total - span))

    def _fractions(self, *, vertical: bool) -> tuple[float, float]:
        """Where one axis of the view is, as two fractions of the region."""
        left, top, right, bottom = self._scroll_region()
        width, height = self._plane_size()
        span = height if vertical else width
        total = max(1, (bottom - top) if vertical else (right - left))
        origin = top if vertical else left
        start = ((self._top if vertical else self._left) - origin) / total
        return (min(1.0, max(0.0, start)), min(1.0, max(0.0, start + span / total)))

    def _report_scroll_view(self) -> None:
        """A resize changes how much is visible, so the scrollbar is retold."""
        self._report_view()

    def _report_view(self) -> None:
        """Tell the scrollbars where the view is, if anything is listening."""
        for option, fractions in (
            ("yscrollcommand", self._fractions(vertical=True)),
            ("xscrollcommand", self._fractions(vertical=False)),
        ):
            command = self._options[option]
            if command is not None:
                command(*fractions)

    # --------------------------------------------------------------- painting

    def _item_pixels(self, item: _CanvasItem) -> dict[tuple[int, int], str]:
        """Every pixel one item lights, and what colour.

        Interior first and outline second, so an outline of a different
        colour is not swallowed by the fill underneath it.
        """
        points = item.points()
        fill = str(item.options.get("fill") or "")
        outline = str(item.options.get("outline") or "")
        pixels: dict[tuple[int, int], str] = {}
        if item.kind == "line":
            pixels.update(dict.fromkeys(line_pixels(points), fill or "white"))
        elif item.kind in ("rectangle", "oval"):
            (x0, y0), (x1, y1) = points[0], points[1]
            solid = (
                filled_rectangle_pixels
                if item.kind == "rectangle"
                else filled_oval_pixels
            )
            edge = rectangle_pixels if item.kind == "rectangle" else oval_pixels
            if fill and outline:
                pixels.update(dict.fromkeys(solid(x0, y0, x1, y1), fill))
            elif fill:
                # With no outline the fill stops short of x2 and y2, as X's
                # XFillRectangle and XFillArc do given the width x2 - x1.
                # Measured on Tk 9.0: (10, 10, 16, 14) fills columns 10-15
                # and rows 10-13, and an outlined one covers 16 and 14 - the
                # outline is drawn on them. canvas(n) says only that the far
                # edges are left out, which is true without the outline.
                left, right = sorted((x0, x1))
                top, bottom = sorted((y0, y1))
                if right > left and bottom > top:
                    shape = solid(left, top, right - 1, bottom - 1)
                    pixels.update(dict.fromkeys(shape, fill))
            if outline:
                pixels.update(dict.fromkeys(edge(x0, y0, x1, y1), outline))
        elif item.kind == "arc":
            (x0, y0), (x1, y1) = points[0], points[1]
            start = float(item.options["start"])
            extent = float(item.options["extent"])
            style = str(item.options["style"])
            if fill and style != "arc":
                pixels.update(
                    dict.fromkeys(
                        filled_arc_pixels(x0, y0, x1, y1, start, extent, style), fill
                    )
                )
            if outline:
                pixels.update(
                    dict.fromkeys(
                        arc_outline_pixels(x0, y0, x1, y1, start, extent, style),
                        outline,
                    )
                )
        elif item.kind in ("image", "bitmap"):
            placed = self._picture(item)
            if placed is not None:
                picture, (x0, y0) = placed
                # Only the part of the picture the view can show, as a Label
                # asks for: a large photograph otherwise hands over every
                # pixel on every repaint.
                width, height = self._plane_size()
                region = (
                    self._left - x0,
                    self._top - y0,
                    self._left - x0 + width,
                    self._top - y0 + height,
                )
                # Fitted to the colour pairs left, as a Label's picture is:
                # the stand-ins go on the plane, so every cell composed from
                # them is in colours the table has room for.
                colors = self.tk.colors
                palette = (
                    _pair_palette(picture, colors) if colors is not None else None
                ) or {}
                for (x, y), colour in picture.lit(region).items():
                    pixels[(x0 + x, y0 + y)] = palette.get(colour, colour)
        elif item.kind == "polygon":
            if fill:
                pixels.update(dict.fromkeys(filled_polygon_pixels(points), fill))
            if outline:
                pixels.update(dict.fromkeys(polygon_pixels(points), outline))
        return pixels

    # -------------------------------------------------------------- windows

    def _window_value(self, value: Any) -> str:
        """A window item's ``window``: a widget or its path, checked as Tk
        checks it, and stored as the path.

        Raises:
            TclError: If there is no such widget, or it is a toplevel, the
                canvas itself, or not inside the canvas's master, in Tk
                9.0.2's words.
        """
        if value is None or value == "":
            return ""
        try:
            widget = value if isinstance(value, Misc) else self.nametowidget(str(value))
        except (KeyError, TclError):
            raise TclError(f'bad window path name "{value}"') from None
        if not isinstance(widget, BaseWidget):
            raise TclError(f"can't use {widget} in a window item of this canvas")
        parent = widget.master
        allowed = parent is not None and any(
            parent is ancestor for ancestor in self._ancestry()
        )
        if widget is self or widget._is_toplevel or not allowed:
            raise TclError(f"can't use {widget} in a window item of this canvas")
        return str(widget)

    def _embed(self, item: _CanvasItem) -> None:
        """Make the canvas the geometry manager of an item's window, taking
        it from wherever it was - another item included - and letting go of
        the window the item showed before."""
        path = str(item.options.get("window") or "")
        widget = cast("BaseWidget", self.nametowidget(path)) if path else None
        for held, ident in list(self._windows.items()):
            if ident == item.ident and held is not widget:
                del self._windows[held]
                held._leave_manager()
                held._unmap()
        if widget is None:
            return
        previous = self._windows.get(widget)
        if previous == item.ident:
            return
        if previous is not None:
            # Measured: the item that had it reads back window "".
            self._windows.pop(widget)
            other = self._item(previous)
            if other is not None:
                other.options["window"] = ""
        else:
            widget._leave_manager()
        if self._embed_manager is None:
            self._embed_manager = EmbedLayout(self)
        self._embed_manager.add(widget)
        self._windows[widget] = item.ident
        widget._manager = "canvas"
        widget._manager_container = self
        self._window_places.pop(widget, None)
        self.tk.layout.invalidate(self)

    def _embedded_lost(self, widget: BaseWidget) -> None:
        """A window left the canvas - packed elsewhere, or destroyed - and
        its item shows nothing now, as Tk's does."""
        ident = self._windows.pop(widget, None)
        self._window_places.pop(widget, None)
        item = None if ident is None else self._item(ident)
        if item is not None:
            item.options["window"] = ""

    def _window_extent(self, item: _CanvasItem) -> tuple[int, int, int, int] | None:
        """A window item's place on the plane, ``(x, y, width, rows)``: its
        top-left pixel, snapped to a row, its width in cells and its height
        in rows. None with no window."""
        path = str(item.options.get("window") or "")
        if not path:
            return None
        widget = self.nametowidget(path)
        width = int(item.options.get("width") or 0)
        height = int(item.options.get("height") or 0)
        width = width if width > 0 else widget.winfo_reqwidth()
        rows = -(-height // 2) if height > 0 else widget.winfo_reqheight()
        x, y = item.points()[0]
        across, down = parse_anchor(str(item.options.get("anchor") or "center"))
        left = x - int(width * across)
        top = y - int(rows * 2 * down)
        return left, top - top % 2, width, rows

    def _window_box(self, item: _CanvasItem) -> tuple[int, int, int, int] | None:
        """A window item's extent: the window's, or Tk's single pixel at the
        item's point when it has none."""
        extent = self._window_extent(item)
        if extent is None:
            x, y = item.points()[0]
            return (x, y, x + 1, y + 1)
        left, top, width, rows = extent
        return (left, top, left + width, top + rows * 2)

    def _embedded_rect(self, widget: BaseWidget, area: Rect) -> Rect | None:
        """Where an embedded window goes on the screen, or None to take it
        off: its item is hidden, or the window is wholly out of view, which
        Tk unmaps rather than clipping to nothing (tkCanvWind.c,
        ``DisplayWinItem``)."""
        place = self._window_place(widget)
        self._window_places[widget] = place
        if place is None:
            return None
        del area  # the drawing area is the canvas's own, inside its border
        drawing = self._text_area()
        return Rect(
            self.winfo_rootx() + drawing.x + place.x,
            self.winfo_rooty() + drawing.y + place.y,
            place.width,
            place.height,
        )

    def _window_place(self, widget: BaseWidget) -> Rect | None:
        """A window's cells relative to the drawing area, or None when it is
        not to be shown."""
        ident = self._windows.get(widget)
        item = None if ident is None else self._item(ident)
        if item is None:
            return None
        state = str(item.options.get("state") or "") or str(self._options["state"])
        if state == "hidden":
            return None
        extent = self._window_extent(item)
        if extent is None:
            return None
        left, top, width, rows = extent
        column = left - self._left
        row = top // 2 - self._top // 2
        drawing = self._text_area()
        if (
            column + width <= 0
            or row + rows <= 0
            or column >= drawing.width
            or row >= drawing.height
        ):
            return None
        return Rect(column, row, width, rows)

    def _follow_windows(self) -> None:
        """Lay the embedded windows out again if any has moved: the item, the
        view or the window's own size changed. Called from every redraw,
        which every one of those ends in; checking first keeps a redraw that
        moved nothing from laying anything out."""
        for widget in self._windows:
            if self._window_places.get(widget, False) != self._window_place(widget):
                self.tk.layout.invalidate(self)
                return

    def _has_active_look(self, ident: int | None) -> bool:
        """Whether an item draws differently while the pointer is over it."""
        item = None if ident is None else self._item(ident)
        return item is not None and any(
            name.startswith("active") and value for name, value in item.options.items()
        )

    def _variant(self, item: _CanvasItem, option: str) -> Any:
        """An item option as it is drawn now: the ``disabled`` variant while
        the item or the canvas is disabled, the ``active`` one while the
        pointer is over it, each only when it is set."""
        state = str(item.options.get("state") or "") or str(self._options["state"])
        if state == "disabled":
            chosen = item.options.get(f"disabled{option}")
        elif item.ident == self._current:
            chosen = item.options.get(f"active{option}")
        else:
            chosen = None
        return chosen if chosen else item.options.get(option)

    def _picture(self, item: _CanvasItem) -> tuple[Image, tuple[int, int]] | None:
        """An image or file bitmap item's picture and its top-left pixel."""
        picture: Image | None
        if item.kind == "image":
            picture = self.tk.images.get(str(self._variant(item, "image") or ""))
        else:
            bitmap = str(self._variant(item, "bitmap") or "")
            if not bitmap.startswith("@"):
                return None
            fore = str(self._variant(item, "foreground") or "white")
            back = str(self._variant(item, "background") or "")
            key = (bitmap, fore, back)
            if key not in self._bitmap_files:
                try:
                    made = _file_bitmap(self, bitmap[1:], fore)
                except TclError:
                    return None
                if back:
                    made.configure(background=back)
                self._bitmap_files[key] = made
            picture = self._bitmap_files[key]
        if picture is None:
            return None
        x, y = item.points()[0]
        across, down = parse_anchor(str(item.options.get("anchor") or "center"))
        return picture, (
            x - int(picture.width() * across),
            y - int(picture.height() * down),
        )

    def _bitmap_cell(self, item: _CanvasItem) -> tuple[int, int, str] | None:
        """A built-in bitmap's cell, as ``(column, cell row, glyph)``."""
        if item.kind != "bitmap":
            return None
        glyph = _BITMAP_GLYPHS.get(str(self._variant(item, "bitmap") or ""))
        if glyph is None:
            return None
        x, y = item.points()[0]
        across, down = parse_anchor(str(item.options.get("anchor") or "center"))
        return x - int(across), y // 2 - int(down), glyph

    def _text_origin(self, item: _CanvasItem) -> tuple[int, int, list[str]] | None:
        """Where a text item starts, as ``(column, cell row, lines)``.

        The row is a cell row, not a pixel row: a glyph fills a cell, so a
        text item snaps to the nearest one rather than straddling two.
        """
        points = item.points()
        if not points:
            return None
        lines = str(item.options.get("text") or "").split("\n")
        if not lines:
            return None
        x, y = points[0]
        width = max((cells(line) for line in lines), default=0)
        across, down = parse_anchor(str(item.options.get("anchor") or "center"))
        column = x - int(width * across)
        # The cell the point falls in, then whole rows off it for a block of
        # several lines. Taking half the block height off in *pixels* first
        # shifted a single line half a cell and rounded it onto the wrong row.
        row = y // 2 - int(len(lines) * down)
        return (column, row, lines)

    def _redraw(self) -> None:
        """Paint the border, then every item in the order it was made."""
        if self._windows:
            self._follow_windows()
        window = self._window
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        base = self._background_attribute() | self._font_attribute()
        with contextlib.suppress(ValueError):
            base = for_state(str(self._options["state"]), base)
        area = self._text_area()
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", base)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, base
                )
            if not area.is_empty:
                for column, row, glyph, attribute in self._painted(area, base):
                    self._write_line(
                        dispatcher,
                        window,
                        area.y + row,
                        area.x + column,
                        glyph,
                        attribute,
                    )

    def _painted(self, area: Rect, base: int) -> list[tuple[int, int, str, int]]:
        """Every cell to draw, worked out item by item in drawing order.

        Items are composed one at a time rather than all at once so that a
        later item covers an earlier one, including where a drawing and a
        piece of text want the same cell. Composing the whole plane first and
        laying text over it afterwards would put every label on top, whatever
        order it was made in.
        """
        pixels: dict[tuple[int, int], str] = {}
        cells: dict[tuple[int, int], tuple[str, int]] = {}
        self._insert_at = None
        for item in self._items:
            if str(item.options.get("state")) == "hidden":
                continue
            if item.kind == "text":
                self._compose_text(item, pixels, cells, base)
            elif (cell := self._bitmap_cell(item)) is not None:
                column, row, character = cell
                pixels.pop((column, row * 2), None)
                pixels.pop((column, row * 2 + 1), None)
                fore = str(self._variant(item, "foreground") or "")
                back = str(self._variant(item, "background") or "") or None
                cells[(column, row)] = (character, self._ink(fore, back, base))
            else:
                drawn = self._item_pixels(item)
                pixels.update(drawn)
                # Only the cells this item touched are recomposed. Folding
                # the whole plane for every item would make drawing cost the
                # square of what is on the canvas.
                affected = {}
                for x, y in drawn:
                    for half in (y - y % 2, y - y % 2 + 1):
                        if (x, half) in pixels:
                            affected[(x, half)] = pixels[(x, half)]
                for at, (glyph, fore, back) in compose(affected).items():
                    cells[at] = (glyph, self._ink(fore, back, base))
        painted = []
        top_row = self._top // 2
        for (x, row), (glyph, attribute) in cells.items():
            column, screen_row = x - self._left, row - top_row
            if 0 <= column < area.width and 0 <= screen_row < area.height:
                if glyph and column + char_cells(glyph[0]) > area.width:
                    glyph = " "  # Half an ideograph at the edge is a blank.
                painted.append((column, screen_row, glyph, attribute))
        return painted

    def _compose_text(
        self,
        item: _CanvasItem,
        pixels: dict[tuple[int, int], str],
        glyphs: dict[tuple[int, int], tuple[str, int]],
        base: int,
    ) -> None:
        """Put a text item's glyphs into the cells, clearing what was under.

        The pixels beneath are dropped, so a drawing item made later composes
        from its own ink alone rather than resurrecting what the text covered.
        """
        placed = self._text_origin(item)
        if placed is None:
            return
        column, row, lines = placed
        attribute = self._ink(str(item.options.get("fill") or ""), None, base)
        font = str(item.options.get("font") or "").lower()
        attribute |= from_font(
            bold="bold" in font,
            italic="italic" in font,
            underline="underline" in font,
        )
        justify = str(item.options.get("justify") or "left")
        width = max((cells(line) for line in lines), default=0)
        selected = (
            (self._selection_first, self._selection_last)
            if self._selection_item == item.ident
            else (0, -1)
        )
        chosen = self._selection_attribute(attribute)
        cursor = (
            self._insert_index.get(item.ident, 0)
            if self._focus_item == item.ident
            else None
        )
        index = 0
        for offset, line in enumerate(lines):
            at = column + align_offset(cells(line), width, justify)
            down = row + offset
            for character in line:
                if index == cursor:
                    self._note_cursor(at, down)
                look = chosen if selected[0] <= index <= selected[1] else attribute
                index += 1
                size = char_cells(character)
                if size == 0:
                    # A combining mark joins the glyph before it.
                    if (at - 1, down) in glyphs:
                        glyph, look = glyphs[(at - 1, down)]
                        glyphs[(at - 1, down)] = (glyph + character, look)
                    continue
                for across in range(at, at + size):
                    pixels.pop((across, down * 2), None)
                    pixels.pop((across, down * 2 + 1), None)
                    # A wide glyph's second cell is "", which draws nothing:
                    # the terminal fills it from the first.
                    glyphs[(across, down)] = (
                        "" if across > at else character,
                        look,
                    )
                at += size
            if index == cursor:
                self._note_cursor(at, down)
            index += 1  # the newline

    def _note_cursor(self, x: int, row: int) -> None:
        """Note the screen cell of the focus item's insertion cursor, while
        the canvas has the keyboard focus and the cell is in view."""
        if self.focus_get() is not self or self._window is None:
            return
        area = self._text_area()
        column, line = x - self._left, row - self._top // 2
        if 0 <= column < area.width and 0 <= line < area.height:
            self._insert_at = (
                self.winfo_rooty() + area.y + line,
                self.winfo_rootx() + area.x + column,
            )

    def _ink(self, foreground: str, background: str | None, base: int) -> int:
        """The attribute a cell needs, given the colours its two halves want."""
        colors = self.tk.colors
        if colors is None:
            return base
        return with_colors(
            base,
            colors.attribute_for(
                foreground or str(self._options["foreground"] or "white"),
                background or str(self._options["background"] or "black"),
            ),
        )


def _canvas_number(value: Any) -> int:
    """A canvas coordinate, as a whole pixel."""
    return round(_tcl_float(None, value))


def _is_integer_text(word: str) -> bool:
    """True for ``12`` and ``-3``, as an index may be written."""
    return word.lstrip("-").isdigit()


def _canvas_coords(args: Any) -> list[int]:
    """Flatten coordinates however they were given.

    Tk takes ``(x0, y0, x1, y1)``, ``((x0, y0), (x1, y1))`` and a single
    sequence of any of those, so all three arrive here and all three work.
    """
    flat: list[int] = []
    values = list(args)
    if len(values) == 1 and isinstance(values[0], (list, tuple)):
        values = list(values[0])
    for value in values:
        if isinstance(value, (list, tuple)):
            flat.extend(round(float(part)) for part in value)
        else:
            flat.append(round(float(value)))
    return flat


def _canvas_mouse(event: Event) -> None:
    """Deliver a mouse event to whichever item is under the pointer.

    Enter and Leave are synthesised here rather than reported by curses:
    there is no such thing as a pointer crossing an item at the terminal
    level, so the canvas works it out by noticing that the item under the
    pointer has changed.
    """
    canvas = event.widget
    x, y = canvas.canvasx(event.x), canvas.canvasy(event.y)
    found = canvas._item_at(x, y)
    if found != canvas._current:
        canvas._deliver(canvas._current, "<Leave>", event)
        before = canvas._current
        canvas._current = found
        if canvas._has_active_look(before) or canvas._has_active_look(found):
            canvas._redraw()
        canvas._deliver(found, "<Enter>", event)
    sequences: dict[str, str] = {
        EventType.ButtonPress: f"<Button-{event.num}>",
        EventType.ButtonRelease: f"<ButtonRelease-{event.num}>",
        EventType.Motion: "<Motion>",
    }
    sequence = sequences.get(event.type, "")
    if sequence:
        canvas._deliver(canvas._current, sequence, event)


#: The tear-off entry, drawn across the menu as Tk draws its dashed line.
TEAROFF_LINE = "╌"

#: A menu entry's ``-compound`` values, as Tk lists them in its error.
_MENU_COMPOUNDS = ("bottom", "center", "left", "none", "right", "top")


class Menu(_Drawable):
    """A list of things to choose, posted over everything else.

    A menu is the one widget placed against the *screen* rather than inside
    its parent. It is not packed or gridded: it is **posted** at a point - by
    ``post``, by ``tk_popup``, or by a menubar or a Menubutton - and placed
    where it fits. A menu with no room below its point is drawn above it, one
    that would run off the right is pulled left, and one taller than the
    screen scrolls rather than being cut off.

    While a menu is posted every key and every click reaches it - including a
    click somewhere else, which dismisses it. Escape dismisses it too, and so
    does invoking anything on it.

    The same widget is also a **menubar** when a toplevel is given one
    through its ``menu`` option. It then draws in a row across the top of
    that window, its cascades post beneath their labels, and the toplevel
    lays its children out in what is left. As in Tk, F10 opens its first
    menu, and Alt with the letter an entry's ``underline`` marks opens that
    menu or runs that command - wherever the focus is. Some terminals keep
    F10 for themselves; the Alt letters reach the program.

    Sample output:
        # size: 40x8
        menu = tk.Menu(root)
        menu.add_command(label="Open...")
        menu.add_command(label="Save")
        menu.add_separator()
        menu.add_checkbutton(label="Word wrap")
        menu.add_command(label="Quit")
        menu.post(2, 1)

    Options:
        activerelief: The relief of the entry under the mouse or the
            keyboard.
        postcommand: Called just before the menu is posted, to bring its
            entries up to date.
        selectcolor: The colour of a check or radio entry's indicator while it
            is on.
        tearoff: Whether the menu starts with an entry that tears it off into
            a window of its own: a dashed line at index 0. Choosing it puts
            a copy of the menu where the menu was, titled by ``title`` or by
            what opened it, which stays up after a choice, moves by
            dragging its title, and closes with Escape. Off by default, as
            in Tk 9.
        tearoffcommand: Called when the menu is torn off.
        title: The title of the window a torn-off menu becomes.
        type: ``normal``, ``menubar`` or ``tearoff``.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``activeborderwidth``, ``activeforeground``,
    ``background``, ``borderwidth``, ``cursor``, ``disabledforeground``,
    ``font``, ``foreground``, ``relief``, ``takefocus``.

    Differences from tkinter:
        A torn-off menu is not a toplevel with a window manager: its title
        is drawn in its border and drags it, as a Toplevel's does, Escape
        closes it, and ``wm`` does not reach it. Its cascades open the original submenus where Tk's open copies
        of them. A menubar's tear-off entry is counted and not drawn.
        ``activeborderwidth`` draws nothing; the active entry
        is shown by its colours and ``activerelief``. ``cursor`` is accepted
        and draws nothing: the mouse pointer belongs to the terminal. Of an
        entry's own options, ``font`` and ``bitmap`` are accepted and draw
        nothing. Its colours, ``selectcolor``, ``indicatoron`` and
        ``hidemargin`` are drawn, an entry's colours over the menu's.

        An entry's ``image`` is drawn as the terminal draws every image, two
        pixel rows to a cell, so the entry is as many rows tall as that -
        and a row more with ``compound`` ``top`` or ``bottom``. Even a small
        icon makes a tall entry. ``compound`` ``none``, the default, shows
        the image in place of the label, as in Tk, and a chosen check or
        radio entry shows its ``selectimage``. On a menubar only the labels
        are drawn.

    Sample output (tearoff):
        # size: 40x7
        menu = tk.Menu(root, tearoff=1)
        menu.add_command(label="Open...")
        menu.add_command(label="Save")
        menu.post(2, 1)

    Sample output (activerelief):
        # size: 40x7
        menu = tk.Menu(root, activerelief="raised")
        menu.add_command(label="Open...")
        menu.add_command(label="Save")
        menu.post(2, 1)
        menu.activate(0)
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset(
        {"highlightbackground", "highlightcolor", "highlightthickness", "padx", "pady"}
    )

    _clipped_by_master = False

    #: Entry kinds, and what each one accepts on top of the common options.
    #: Measured on Tk 9.0.2 with entryconfigure on each kind: a separator
    #: takes ``background`` and nothing else, and the check and radio kinds
    #: add their indicator's options. TkCurses-aj1.13.1, TkCurses-g373.
    _ENTRY_OPTIONS: ClassVar[dict[str, dict[str, Any]]] = {
        "command": {},
        "cascade": {"menu": None},
        "checkbutton": {
            "onvalue": 1,
            "offvalue": 0,
            "variable": None,
            "indicatoron": 1,
            "selectcolor": "",
            "selectimage": "",
        },
        "radiobutton": {
            "value": "",
            "variable": None,
            "indicatoron": 1,
            "selectcolor": "",
            "selectimage": "",
        },
        "separator": {"background": ""},
    }
    #: What every kind but a separator takes.
    _COMMON_ENTRY_OPTIONS: ClassVar[dict[str, Any]] = {
        "accelerator": "",
        "activebackground": "",
        "activeforeground": "",
        "background": "",
        "bitmap": "",
        "columnbreak": 0,
        "command": None,
        "compound": "none",
        "font": "",
        "foreground": "",
        "hidemargin": 0,
        "image": "",
        "label": "",
        "state": "normal",
        "underline": -1,
    }

    @classmethod
    def _entry_spec(cls, kind: str) -> dict[str, Any]:
        """Every option an entry of this kind takes, with its default."""
        if kind == "separator":
            return dict(cls._ENTRY_OPTIONS[kind])
        if kind == TEAROFF:
            # Measured on Tk 9.0.2: entryconfigure on the tear-off entry
            # answers these two and nothing else.
            return {"background": "", "state": "normal"}
        return {**cls._COMMON_ENTRY_OPTIONS, **cls._ENTRY_OPTIONS[kind]}

    #: What a ticked checkbutton and a chosen radiobutton look like.
    _INDICATORS: ClassVar[dict[str, tuple[str, str]]] = {
        "checkbutton": ("[x] ", "[ ] "),
        "radiobutton": ("(•) ", "( ) "),
    }

    _STATE_COLOURS: ClassVar[dict[str, tuple[str | None, str | None]]] = {
        "active": ("activeforeground", "activebackground"),
        "disabled": ("disabledforeground", None),
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        **_STATE_COLOUR_OPTIONS,
        # The active entry's border, which a row-high entry has no room for,
        # and its relief: sunken is drawn dim. TkCurses-gm66.5.
        "activeborderwidth": 1,
        "activerelief": "raised",
        # The tick or bullet of a chosen check or radio entry. "" here, Tk's
        # #000000: drawn as the label is. TkCurses-gm66.4.
        "selectcolor": "",
        # The labels' styling, as every widget's font is here. TkCurses-gm66.10.
        "font": "",
        "postcommand": None,
        "relief": "raised",
        "takefocus": False,
        # Tk 9.0.2's default, measured; Tk 8.6's was true.
        "tearoff": False,
        "tearoffcommand": "",
        "title": "",
        "type": "normal",
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``postcommand``, ``title``, and the standard options.
        """
        self._entries: list[MenuEntry] = []
        self._active: int | None = None
        self._posted = False
        self._first = 0
        self._as_menubar = False
        self._open_cascade: Menu | None = None
        self._parent_menu: Menu | None = None
        self._focus_before: Misc | None = None
        #: What a torn-off menu's border names it: the window title Tk's
        #: tk::TearOffMenu gives the copy.
        self._torn_title = ""
        #: Where a drag of a torn-off menu's title started: the pointer's
        #: screen cell and the menu's, or None when not dragging.
        self._drag_origin: tuple[int, int, int, int] | None = None
        super().__init__(master, cnf, name=name, **kw)
        self._sync_tearoff()
        self._apply_requested_size()
        self._install_class_bindings()

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, or report them; see :meth:`BaseWidget.configure`.

        Turning ``tearoff`` on puts the tear-off entry in at index 0, and
        turning it off takes it out, moving every other index by one - as
        in Tk.
        """
        answer = super().configure(cnf, **kw)
        if "tearoff" in _given(cnf, kw):
            self._sync_tearoff()
            self._apply_requested_size()
            self._refresh()
        return answer

    config = configure

    def _has_tearoff(self) -> bool:
        """Whether entry 0 is the tear-off entry."""
        return bool(self._entries) and self._entries[0].kind == TEAROFF

    def _sync_tearoff(self) -> None:
        """Put the tear-off entry in, or take it out, as ``tearoff`` says."""
        wanted = bool(self._options.get("tearoff"))
        if wanted and not self._has_tearoff():
            self._entries.insert(0, MenuEntry(TEAROFF, self._entry_spec(TEAROFF)))
            if self._active is not None:
                self._active += 1
        elif not wanted and self._has_tearoff():
            del self._entries[0]
            if self._active is not None:
                self._active = self._active - 1 if self._active > 0 else None
        if self._has_tearoff():
            # A torn-off menu keeps the entry at 0, as Tk's does, and neither
            # draws it nor lands on it: tk::MenuNextEntry skips it there.
            self._entries[0].hidden = self._torn_off

    @property
    def _torn_off(self) -> bool:
        """Whether this menu is a torn-off copy: ``type`` ``tearoff``."""
        return self._options.get("type") == "tearoff"

    def _install_class_bindings(self) -> None:
        """Register the keys and clicks every Menu answers."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Any-Key>", _menu_key)
        # menu.tcl's arrows, on the navigation events: a key event_added to
        # <<NextLine>> moves through a menu as Down does.
        for sequence, keysym in _MENU_ARROWS.items():
            bind(name, sequence, _menu_arrow_binding(keysym))
        bind(name, "<Button-1>", _menu_click)
        bind(name, "<Motion>", _menu_motion)
        # A held button: dragging a torn-off menu by its title, else the
        # pointer running down the entries as <Motion> does.
        bind(name, "<B1-Motion>", _menu_drag)
        bind(name, "<ButtonRelease-1>", _menu_release)

    # ---------------------------------------------------------- making entries

    def add(self, kind: str, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Append an entry of one kind.

        Raises:
            TclError: If the kind is not one Tk defines, or an option is not
                one that kind takes.
        """
        self.insert(len(self._entries), kind, cnf, **kw)

    def insert(
        self, index: Any, kind: str, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Put an entry of one kind at a position.

        Raises:
            TclError: If the kind or an option is not one Tk defines.
        """
        if kind not in self._ENTRY_OPTIONS:
            raise TclError(
                f'bad menu entry type "{kind}": must be cascade, checkbutton, '
                "command, radiobutton, or separator"
            )
        entry = MenuEntry(kind, self._checked_entry(kind, _given(cnf, kw)))
        self._entries.insert(self._insert_at(index), entry)
        self._apply_requested_size()
        self._refresh()

    def add_command(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Append an entry that runs something."""
        self.add("command", cnf, **kw)

    def add_cascade(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Append an entry that opens a submenu."""
        self.add("cascade", cnf, **kw)

    def add_checkbutton(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Append an entry that toggles a variable."""
        self.add("checkbutton", cnf, **kw)

    def add_radiobutton(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Append an entry that sets a variable to its own value."""
        self.add("radiobutton", cnf, **kw)

    def add_separator(self, cnf: dict[str, Any] | None = None, **kw: Any) -> None:
        """Append a dividing line."""
        self.add("separator", cnf, **kw)

    def insert_command(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Insert an entry that runs something."""
        self.insert(index, "command", cnf, **kw)

    def insert_cascade(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Insert an entry that opens a submenu."""
        self.insert(index, "cascade", cnf, **kw)

    def insert_checkbutton(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Insert an entry that toggles a variable."""
        self.insert(index, "checkbutton", cnf, **kw)

    def insert_radiobutton(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Insert an entry that sets a variable."""
        self.insert(index, "radiobutton", cnf, **kw)

    def insert_separator(
        self, index: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> None:
        """Insert a dividing line."""
        self.insert(index, "separator", cnf, **kw)

    def _checked_entry(self, kind: str, given: dict[str, Any]) -> dict[str, Any]:
        """Resolve an entry's options against what its kind accepts.

        Raises:
            TclError: If an option is not one the kind takes.
        """
        spec = self._entry_spec(kind)
        options = dict(spec)
        for name, value in given.items():
            option = _OPTION_ALIASES.get(name, name)
            if option not in spec:
                raise TclError(f'unknown option "-{name}"')
            options[option] = self._entry_value(option, value)
        return options

    def _entry_value(self, option: str, value: Any) -> Any:
        """An entry option's value as Tk checks it. An image must exist and a
        ``compound`` be one of Tk's six, in Tk 9.0.2's words; the rest are
        kept as given."""
        if option in ("image", "selectimage"):
            return _image_name(self, value)
        if option == "compound":
            return _tcl_index(value, _MENU_COMPOUNDS, "compound")
        return value

    # -------------------------------------------------------------- indices

    def index(self, spec: Any) -> int | None:
        """Resolve one of Tk's entry indices.

        Takes a number, ``end`` or ``last``, ``active``, ``none``, ``@y`` for
        a row within the menu, or the label of an entry. Returns None for
        ``none`` and for a label that matches nothing, which is what Tk does.
        """
        if spec is None:
            return None
        if isinstance(spec, int):
            return spec if 0 <= spec < len(self._entries) else None
        text = str(spec).strip()
        if text in ("end", "last"):
            return len(self._entries) - 1 if self._entries else None
        if text == "active":
            return self._active
        if text == "none":
            return None
        if text.startswith("@"):
            # "@y", or "@x,y" in a menu laid out in columns - Tk 9.0.2 takes
            # both, measured, and "@y" alone reads as the first column.
            x, _, y = text[1:].rpartition(",")
            if x:
                return self._entry_at(int(x), int(y))
            return self._entry_at_row(int(y))
        if text.lstrip("-").isdigit():
            number = int(text)
            return number if 0 <= number < len(self._entries) else None
        return next(
            (n for n, entry in enumerate(self._entries) if entry.label == text), None
        )

    def _insert_at(self, spec: Any) -> int:
        """Where an insertion goes, clamped into the list - and never ahead
        of the tear-off entry, which Tk keeps first."""
        if isinstance(spec, int):
            at = max(0, min(spec, len(self._entries)))
        else:
            resolved = self.index(spec)
            at = len(self._entries) if resolved is None else resolved
        return max(at, 1) if self._has_tearoff() else at

    def _entry_at_row(self, row: int) -> int | None:
        """Which entry a row within the widget falls on, in the first column."""
        if self._as_menubar:
            return self._entry_at_column(row)
        return self._entry_at(self._text_area().x, row)

    def _entry_at(self, column: int, row: int) -> int | None:
        """Which entry a cell within the widget falls on.

        A menu in one column answers by the row alone, wherever across it
        the cell is, as it always has; one laid out in columns asks which
        column the cell is in, too. TkCurses-aj1.13.1.
        """
        if self._as_menubar:
            return self._entry_at_column(column)
        area = self._text_area()
        places = self._places()
        columned = self._columned(places)
        wanted = row - area.y + self._top_row(places)
        for number, place in enumerate(places):
            if not place.row <= wanted < place.row + place.height:
                continue
            if not columned:
                return number
            if place.x <= column - area.x < place.x + place.width + COLUMN_GAP:
                return number
        return None

    def _places(self) -> list[Placed]:
        """Where each entry goes when posted - see :func:`lay_out`."""
        places, _ = self._laid_out()
        return places

    def _laid_out(self) -> tuple[list[Placed], tuple[int, int]]:
        """:func:`lay_out`, with each entry's image measured first."""
        for entry in self._entries:
            image = self._entry_image(entry)
            entry.picture = (
                None if image is None else (image.width(), image.cell_height())
            )
        return lay_out(self._entries, indicators=self._has_indicators())

    def _entry_image(self, entry: MenuEntry, *, drawn: bool = False) -> Image | None:
        """The image an entry shows, or None. Drawn, a chosen check or radio
        entry shows its ``selectimage`` if it has one; the size is always
        the ``image``'s. A deleted image is no image, as a Label's is."""
        name = str(entry.options.get("image") or "")
        image: Image | None = self.tk.images.get(name) if name else None
        if image is None or not drawn or entry.kind not in self._INDICATORS:
            return image
        chosen = self._indicator_for(entry) == self._INDICATORS[entry.kind][0]
        select = str(entry.options.get("selectimage") or "")
        if chosen and select:
            chosen_image: Image | None = self.tk.images.get(select)
            return chosen_image or image
        return image

    def _top_row(self, places: list[Placed]) -> int:
        """The first row shown: the scrolled-to entry's, in one column."""
        if self._columned(places) or not places:
            return 0
        return places[min(self._first, len(places) - 1)].row

    @staticmethod
    def _columned(places: list[Placed]) -> bool:
        """True if the entries are laid out in more than one column."""
        return any(place.x for place in places)

    def _entry_at_column(self, column: int) -> int | None:
        """Which menubar entry a column falls on."""
        at = self._text_area().x
        for number, entry in enumerate(self._entries):
            if entry.kind == TEAROFF:
                continue
            width = cells(entry.label) + 2
            if at <= column < at + width:
                return number
            at += width
        return None

    def type(self, spec: Any) -> str | None:
        """What kind of entry an index names."""
        at = self.index(spec)
        return None if at is None else self._entries[at].kind

    def yposition(self, spec: Any) -> int:
        """The row an entry occupies within the menu, as Tk reports it.

        Within its column, in a menu laid out in columns.
        """
        at = self.index(spec)
        if at is None:
            return 0
        places = self._places()
        return places[at].row - self._top_row(places)

    def xposition(self, spec: Any) -> int:
        """The column an entry's column starts at, counted as yposition is.

        0 in a menu of one column; in one laid out with ``columnbreak``, how far
        across its column begins.

        Differences from tkinter:
            Tk answers in pixels and counts the border; this counts cells from
            where the entries start, as :meth:`yposition` does.
        """
        # TkCurses-aj1.13.1.
        at = self.index(spec)
        return 0 if at is None else self._places()[at].x

    # ------------------------------------------------------ changing entries

    def delete(self, first: Any, last: Any = None) -> None:
        """Remove entries from ``first`` up to and including ``last``."""
        start = self.index(first)
        if start is None:
            return
        stop = start if last is None else self.index(last)
        if stop is None:
            stop = len(self._entries) - 1
        if start == 0 and self._has_tearoff():
            # Measured on Tk 9.0.2: deleting from 0 leaves the tear-off
            # entry where it is, and "delete 0" alone deletes nothing.
            start = 1
        del self._entries[start : stop + 1]
        if self._active is not None and self._active >= len(self._entries):
            self._active = None
        self._apply_requested_size()
        self._refresh()

    def entryconfigure(
        self, spec: Any, cnf: dict[str, Any] | None = None, **kw: Any
    ) -> Any:
        """Set options on one entry, or read them all.

        Raises:
            TclError: If the index names nothing, or an option is not one the
                entry's kind takes.
        """
        at = self.index(spec)
        if at is None:
            raise TclError(f'bad menu entry index "{spec}"')
        entry = self._entries[at]
        if not cnf and not kw:
            return dict(entry.options)
        given = _given(cnf, kw)
        if not given:  # every option None, which tkinter drops
            return None
        spec_for_kind = self._entry_spec(entry.kind)
        for name, value in given.items():
            option = _OPTION_ALIASES.get(name, name)
            if option not in spec_for_kind:
                raise TclError(f'unknown option "-{name}"')
            entry.options[option] = self._entry_value(option, value)
        self._apply_requested_size()
        self._refresh()
        return None

    entryconfig = entryconfigure

    def entrycget(self, spec: Any, option: str) -> Any:
        """One option of one entry.

        Raises:
            TclError: If the index or the option names nothing.
        """
        at = self.index(spec)
        if at is None:
            raise TclError(f'bad menu entry index "{spec}"')
        name = _OPTION_ALIASES.get(option, option)
        if name not in self._entries[at].options:
            raise TclError(f'unknown option "-{option}"')
        return self._entries[at].options[name]

    # ------------------------------------------------------------ behaviour

    def activate(self, spec: Any) -> None:
        """Make an entry the active one, or ``none`` to make none of them."""
        at = self.index(spec)
        if at is not None and not self._entries[at].selectable:
            return
        self._active = at
        if at is not None and not self._as_menubar:
            self._first = self._scrolled_to(at)
        self._refresh()

    def invoke(self, spec: Any) -> Any:
        """Do what choosing an entry does, and return what its command did.

        A cascade opens its submenu rather than running anything; a
        checkbutton or radiobutton writes its variable first; everything else
        dismisses the menu before running, so that a command which posts
        another window does not fight with this one.
        """
        at = self.index(spec)
        if at is None:
            return None
        entry = self._entries[at]
        if not entry.selectable:
            return None
        if entry.kind == TEAROFF:
            return self._tear_off()
        if entry.kind == "cascade":
            self._open(at)
            return None
        self._write_variable(entry)
        self._dismiss_all()
        command = entry.options.get("command")
        return None if command is None else command()

    def _raise_torn_off(self) -> None:
        """Bring a torn-off menu in front of the other windows, and give it
        the keys - as clicking a window does where a window manager would."""
        stack = self.tk.panels
        if stack is not None and self._panel is not None:
            stack.raise_to_top(self._panel)
        self.focus_set()
        self._refresh()

    def _move_to_screen_cell(self, x: int, y: int) -> None:
        """Place the menu with its corner at a screen cell."""
        master = self.master
        origin_x = master.winfo_rootx() if master is not None else 0
        origin_y = master.winfo_rooty() if master is not None else 0
        self._allocate(
            Rect(x - origin_x, y - origin_y, self._rect.width, self._rect.height)
        )

    def _move_torn_off(self, x: int, y: int) -> None:
        """Move a torn-off menu, kept wholly on the screen as ``geometry``
        keeps a Toplevel being dragged."""
        screen_width, screen_height = self._screen_size()
        x = max(0, min(x, screen_width - self._rect.width))
        y = max(0, min(y, screen_height - self._rect.height))
        if (x, y) == (self.winfo_rootx(), self.winfo_rooty()):
            return
        self._move_to_screen_cell(x, y)
        self._map()
        self._raise_torn_off()

    def _tear_off(self) -> str:
        """Copy this menu into a window of its own, which stays up.

        Follows ``tk::TearOffMenu`` and ``tk::MenuDup``: the copy is a menu
        of ``type`` ``tearoff`` named ``tearoff1``, ``tearoff2`` and so on in
        the nearest toplevel, with every option and entry of this one; it is
        titled by ``title``, else by the Menubutton's text or the cascade's
        label it came from; it appears where this menu was; and
        ``tearoffcommand`` is called with both menus' names. Returns the
        copy's name, as Tk's invoke does.
        """
        x, y = self.winfo_rootx(), self.winfo_rooty()
        # Titled before this menu is unposted, which takes the parent's
        # active entry with it.
        title = str(self._options.get("title") or "")
        source = self.master
        if not title and isinstance(source, Menubutton):
            title = str(source.cget("text"))
        elif not title and isinstance(source, Menu):
            with contextlib.suppress(TclError, IndexError):
                active = source.index("active")
                if active is not None:
                    title = source._entries[active].label
        self._dismiss_all()
        parent: Misc = self.master if self.master is not None else self
        while (
            isinstance(parent, Menu) or parent.winfo_toplevel() is not parent
        ) and parent.master is not None:
            parent = parent.master
        number = 1
        while f"tearoff{number}" in parent.children:
            number += 1
        options = {
            name: self._options[name]
            for name in self._public_options()
            if name != "type" and name in self._options
        }
        copy = Menu(parent, name=f"tearoff{number}", type="tearoff", **options)
        for entry in self._entries:
            if entry.kind != TEAROFF:
                copy.add(entry.kind, dict(entry.options))
        copy._torn_title = title or f"tearoff{number}"
        copy.post(x, y)
        command = self._options.get("tearoffcommand")
        if callable(command):
            command(str(self), str(copy))
        return str(copy)

    def bind_accelerators(self, target: Misc | None = None) -> list[str]:
        """Bind every entry's accelerator to the entry, submenus included.

        In Tk the accelerator is display only - its manual says the option "does
        not actually set the corresponding binding" - so a program writes each
        shortcut twice, as text and as a binding, and the two drift apart. This
        makes the binding from the text: ``Ctrl+O``, ``^S``, ``Alt+F4``,
        ``Ctrl+X Ctrl+S``.

        Each binding is added rather than replacing what is there, and runs the
        entry it was made for even if entries are inserted before it later. A
        disabled entry's shortcut does nothing, as choosing it would.

        Args:
            target: The widget to bind on. By default every widget, through
                ``bind_all``, which is how Tk programs usually bind a menu's
                shortcuts.

        Returns:
            The sequences bound, in order.

        Raises:
            ValueError: If an accelerator cannot be read, naming the entry -
                before anything is bound, so it is all or nothing.

        TkCurses extension:
            tkinter has no such method.
        """
        # Read by _core.menus.accelerator_sequence. The binding runs the entry
        # by what it is, not by its index. TkCurses-aj1.13.1.
        found: list[tuple[str, Menu, MenuEntry]] = []
        self._collect_accelerators(found, set())
        bind = target.bind if target is not None else self.bind_all
        for sequence, menu, entry in found:
            bind(sequence, _accelerated(menu, entry), add=True)
        return [sequence for sequence, _, _ in found]

    def _collect_accelerators(
        self, found: list[tuple[str, Menu, MenuEntry]], seen: set[int]
    ) -> None:
        """Gather (sequence, menu, entry) for this menu and its submenus."""
        if id(self) in seen:
            return
        seen.add(id(self))
        for entry in self._entries:
            if entry.accelerator:
                try:
                    sequence = accelerator_sequence(entry.accelerator)
                except ValueError as error:
                    raise ValueError(f"menu entry {entry.label!r}: {error}") from None
                found.append((sequence, self, entry))
            submenu = entry.options.get("menu")
            if entry.kind == "cascade" and isinstance(submenu, Menu):
                submenu._collect_accelerators(found, seen)

    def _write_variable(self, entry: MenuEntry) -> None:
        """Put the entry's value in its variable, for the two kinds that have one."""
        variable = entry.options.get("variable")
        if variable is None:
            return
        if entry.kind == "checkbutton":
            on, off = entry.options["onvalue"], entry.options["offvalue"]
            variable.set(off if _same_value(variable.get(), on) else on)
        elif entry.kind == "radiobutton":
            variable.set(entry.options["value"])

    def _indicator_for(self, entry: MenuEntry) -> str:
        """The tick or bullet an entry shows, or spaces to line up with one.

        ``hidemargin`` gives up the spaces; ``indicatoron`` false shows
        them in place of the indicator, as Tk draws no indicator then.
        """
        if entry.kind not in self._INDICATORS or not _entry_flag(
            self, entry.options.get("indicatoron", 1)
        ):
            if _entry_flag(self, entry.options.get("hidemargin", 0)):
                return ""
            return "    " if self._has_indicators() else ""
        on, off = self._INDICATORS[entry.kind]
        variable = entry.options.get("variable")
        if variable is None:
            return off
        wanted = (
            entry.options["onvalue"]
            if entry.kind == "checkbutton"
            else entry.options["value"]
        )
        return on if _same_value(variable.get(), wanted) else off

    def _has_indicators(self) -> bool:
        """True if any entry needs room on the left for a tick."""
        return any(entry.kind in self._INDICATORS for entry in self._entries)

    # -------------------------------------------------------------- posting

    def post(self, x: int, y: int) -> None:
        """Put the menu on screen at a point, moving it to fit.

        Args:
            x: Screen column to post at.
            y: Screen row.
        """
        command = self._options["postcommand"]
        if command is not None:
            command()
        width, height = self._posted_size()
        screen_width, screen_height = self._screen_size()
        x, y, height = place_popup(x, y, width, height, screen_width, screen_height)
        self._posted = True
        # place_popup works in screen cells; _allocate takes coordinates
        # relative to the master, as every geometry manager hands it. They
        # are the same thing only for a menu whose master is the root, which
        # is why nothing noticed until an OptionMenu made its menu a child of
        # the button - Tk builds it that way too - and the menu was allocated
        # at an offset and posted off the screen.
        master = self.master
        origin_x = master.winfo_rootx() if master is not None else 0
        origin_y = master.winfo_rooty() if master is not None else 0
        self._allocate(Rect(x - origin_x, y - origin_y, width, height))
        self._map()
        self._restack_panels()
        self._focus_before = self.tk.focus
        if not self._torn_off:
            # A torn-off menu is a window among the others, and takes no
            # grab: a click elsewhere goes elsewhere, as in Tk.
            self.grab_set()
        self.focus_set()
        self._first = self._scrolled_to(self._active or 0)
        self._refresh()

    def unpost(self) -> None:
        """Take the menu off screen, and any submenu with it."""
        if self._open_cascade is not None:
            self._open_cascade.unpost()
            self._open_cascade = None
        if not self._posted:
            return
        self._posted = False
        self._active = None
        self.grab_release()
        self._unmap()
        parent = self._parent_menu
        self._parent_menu = None
        previous = self._focus_before
        self._focus_before = None
        if parent is not None and parent._as_menubar:
            # A dropdown of the menubar takes the bar's highlight with it, as
            # Tk's MenuUnpost does ("$parent activate {}", read from Tk
            # 9.0.2). The bar is never posted, so the branch below never ran
            # for it, and Colours stayed highlighted after Escape - looking
            # like a keyboard mode the bar was not in. Found by the author in
            # UAT 46; TkCurses-aj1.13.1. Opening the next menu along the bar
            # comes through here too, and _open sets the new active entry
            # after closing the old dropdown, so it is not lost.
            parent._open_cascade = None
            parent._active = None
            parent._refresh()
            if previous is parent:
                # Opened from a bar F10 gave the focus to: the bar lets it
                # go too, rather than keeping it with nothing active.
                _leave_menubar(parent)
                return
        if parent is not None and parent._posted:
            parent._open_cascade = None
            if not parent._torn_off:
                parent.grab_set()
            parent.focus_set()
        elif previous is not None and previous.winfo_exists():
            previous.focus_set()
        # Nothing to give the focus back to: _unmap has already taken it off
        # this menu, and leaving it there is what stopped Escape closing the
        # application after a menu had been opened once.

    def tk_popup(self, x: int, y: int, entry: Any = None) -> None:
        """Post the menu at a point, optionally with one entry active."""
        self.post(x, y)
        if entry is not None:
            self.activate(entry)

    def _open(self, at: int) -> None:
        """Post the submenu of a cascade entry, beside its own row."""
        entry = self._entries[at]
        submenu: Menu | None = entry.options.get("menu")
        if submenu is None:
            return
        # `_posted` first: comparing against _open_cascade, which is
        # `Menu | None`, widens submenu back to include None for a type
        # checker, and the two tests are independent anyway.
        if submenu._posted and self._open_cascade is submenu:
            return
        if self._open_cascade is not None:
            self._open_cascade.unpost()
        self._active = at
        submenu._parent_menu = self
        self._open_cascade = submenu
        if self._as_menubar:
            submenu.post(
                self.winfo_rootx() + self._label_column(at), self.winfo_rooty() + 1
            )
        else:
            submenu.post(
                self.winfo_rootx() + self._rect.width,
                self.winfo_rooty() + self.yposition(at),
            )
        self._refresh()

    def _label_column(self, at: int) -> int:
        """Where one menubar label starts, relative to the bar."""
        column = self._text_area().x
        for entry in self._entries[:at]:
            if entry.kind != TEAROFF:
                column += cells(entry.label) + 2
        return column

    def _dismiss_all(self) -> None:
        """Unpost this menu and every one above it, back to the menubar.

        Each one in turn, rather than walking to the root and unposting that:
        a menubar is never itself posted, so doing it that way dismissed
        nothing at all and left the dropdown on screen. The parent is taken
        before unposting, because unposting forgets it.
        """
        menu: Menu | None = self
        while menu is not None:
            parent = menu._parent_menu
            if menu._torn_off:
                # A torn-off menu stays up after a choice: it is a window
                # now, not a popup. What was opened from it goes.
                menu._open_cascade = None
                menu._refresh()
                return
            if menu._posted:
                menu.unpost()
            else:
                menu._open_cascade = None
                menu._active = None
                menu._refresh()
            menu = parent

    # -------------------------------------------------------------- geometry

    def _scrolled_to(self, at: int) -> int:
        """The first row to show so ``at`` is visible.

        A menu laid out in columns does not scroll - a column is how a long
        menu was made short - so it always starts at the top.
        """
        places = self._places()
        if self._columned(places):
            return 0
        heights = [place.height for place in places]
        return visible_window(len(self._entries), at, self._rows(), heights)

    def _posted_size(self) -> tuple[int, int]:
        """The size a posted menu wants, border included."""
        _, (width, height) = self._laid_out()
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        return (width + edge + 2, height + edge)

    def _apply_requested_size(self) -> None:
        """Ask for a bar's row, or for what the entries need when posted."""
        if self._as_menubar:
            self._request_size(
                sum(cells(entry.label) + 2 for entry in self._entries) or 1, 1
            )
            return
        width, height = self._posted_size()
        self._request_size(width, height)

    def _rows(self) -> int:
        """How many entries are visible at once."""
        return max(1, self._text_area().height)

    def _text_area(self) -> Rect:
        """Where the entries go, in cells relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn and not self._as_menubar else 0
        return Rect(
            edge + 1 if not self._as_menubar else 0,
            edge,
            max(0, self._rect.width - 2 * edge - (2 if not self._as_menubar else 0)),
            max(0, self._rect.height - 2 * edge),
        )

    def _refresh(self) -> None:
        """Repaint, and push it to the terminal if one is running."""
        self._redraw()
        screen = self.tk.screen
        if screen is not None and self._mapped:
            with contextlib.suppress(_curses.error):
                screen.refresh()

    # -------------------------------------------------------------- painting

    def _redraw(self) -> None:
        """Paint the menu, as a bar across the top or as a posted box."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        # Images go to the terminal past curses as well, kept per widget
        # until cleared: without this, a menu that moved - a torn-off one
        # being dragged - left its pictures where it had been.
        painter = getattr(self.tk, "painter", None)
        if painter is not None:
            painter.clear(self)
        dispatcher = CursesDispatcher.get()
        attribute = self._background_attribute() | self._font_attribute()
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._as_menubar:
                self._draw_bar(dispatcher, window, attribute)
                return
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
                if self._torn_off and self._torn_title:
                    room = self._rect.width - 4
                    if room > 0:
                        self._write_line(
                            dispatcher,
                            window,
                            0,
                            2,
                            clip_text(self._torn_title, room),
                            attribute,
                        )
            self._draw_entries(dispatcher, window, attribute)

    def _draw_bar(
        self, dispatcher: CursesDispatcher, window: Any, attribute: int
    ) -> None:
        """Draw the labels in a row, the open one picked out."""
        column = 0
        for number, entry in enumerate(self._entries):
            if entry.kind == TEAROFF:
                # A menubar's tear-off entry is counted and not drawn.
                continue
            text = f" {entry.label} "
            style = self._entry_style(entry, attribute, number == self._active)
            self._write_line(
                dispatcher,
                window,
                0,
                column,
                clip_text(text, self._rect.width - column),
                style,
            )
            column += cells(text)
            if column >= self._rect.width:
                break

    def _draw_entries(
        self, dispatcher: CursesDispatcher, window: Any, attribute: int
    ) -> None:
        """Draw the visible entries, the active one picked out."""
        area = self._text_area()
        if area.is_empty:
            return
        cascades = any(entry.kind == "cascade" for entry in self._entries)
        places = self._places()
        columned = self._columned(places)
        top = self._top_row(places)
        for number, place in enumerate(places):
            first = place.row - top
            if first >= area.height or first + place.height <= 0:
                continue
            entry = self._entries[number]
            # One column draws across the whole menu, as it always has; a
            # column of several, across its own width.
            x = area.x + place.x if columned else area.x
            width = min(place.width, area.width - place.x) if columned else area.width
            if width <= 0:
                continue
            if entry.hidden:
                continue
            style = self._entry_style(entry, attribute, number == self._active)
            if entry.kind == TEAROFF:
                self._write_line(
                    dispatcher, window, area.y + first, x, TEAROFF_LINE * width, style
                )
                continue
            if entry.kind == "separator":
                self._write_line(
                    dispatcher,
                    window,
                    area.y + first,
                    x - 1 if not columned else x,
                    "─" * (width + 2 if not columned else width),
                    style,
                )
                continue
            # An entry taller than a row - one with an image - is filled in
            # its colours on every row, so the active one is picked out whole.
            for extra in range(place.height):
                if 0 <= first + extra < area.height and extra != entry.label_row:
                    self._write_line(
                        dispatcher,
                        window,
                        area.y + first + extra,
                        x,
                        " " * width,
                        style,
                    )
            indicator = self._indicator_for(entry)
            label_at = self._label_offset(entry)
            text = (
                indicator + " " * label_at + (entry.label if entry.shows_label else "")
            )
            line = pad_cells(text, width)
            accelerator = entry.accelerator
            if accelerator:
                line = pad_cells(line, width - cells(accelerator)) + accelerator
            if entry.kind == "cascade" and cascades:
                line = pad_cells(line, width - 1) + CASCADE_GLYPH
            row = first + entry.label_row
            if 0 <= row < area.height:
                self._write_line(
                    dispatcher,
                    window,
                    area.y + row,
                    x,
                    clip_text(line, width),
                    style,
                )
                self._draw_chosen_mark(
                    dispatcher,
                    window,
                    area.y + row,
                    x,
                    entry,
                    style,
                    number == self._active,
                )
                if entry.shows_label:
                    self._draw_underline(
                        dispatcher,
                        window,
                        Rect(x + label_at, area.y, width - label_at, area.height),
                        row,
                        entry,
                        style,
                    )
            self._draw_entry_image(
                dispatcher,
                window,
                entry,
                Rect(x + cells(indicator), area.y + first, width, place.height),
                Rect(x, area.y, width, area.height),
                number == self._active,
            )

    def _label_offset(self, entry: MenuEntry) -> int:
        """How far the label starts after the indicator: past an image on
        its left, centred with one above, below or behind it."""
        if entry.picture is None or not entry.shows_label:
            return 0
        width, _ = entry.picture
        if entry.compound == "left":
            return width + IMAGE_GAP
        if entry.compound == "right":
            return 0
        return (entry.content_width - cells(entry.label)) // 2

    def _draw_entry_image(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        entry: MenuEntry,
        block: Rect,
        area: Rect,
        active: bool,
    ) -> None:
        """Paint an entry's image within ``block``, the entry's rows from
        after its indicator, as ``compound`` places it - clipped to
        ``area``, the part of the menu showing."""
        image = self._entry_image(entry, drawn=True)
        if image is None or entry.picture is None:
            return
        width, _ = entry.picture
        left = block.x
        top = block.y
        if entry.shows_label:
            if entry.compound == "right":
                left += cells(entry.label) + IMAGE_GAP
            elif entry.compound in ("top", "bottom", "center"):
                left += (entry.content_width - width) // 2
            if entry.compound == "bottom":
                top += 1
        own = entry.options.get("activebackground" if active else "background")
        state = self._state_colours("active") if active else None
        background = (
            own
            or (state[1] if state is not None else "")
            or str(self._options["background"] or "black")
        )
        clip = Rect(
            area.x,
            max(area.y, block.y),
            area.width,
            max(
                0,
                min(area.y + area.height, block.y + block.height)
                - max(area.y, block.y),
            ),
        )
        _paint_image(self, dispatcher, window, image, left, top, clip, str(background))

    def _entry_style(self, entry: MenuEntry, attribute: int, active: bool) -> int:
        """How one entry is drawn: its own colours, where it has them, win.

        Tk's manual for the entry options: ``-background`` and the rest
        "override" the menu's for this entry; when active, an entry's
        ``-activeforeground`` and ``-activebackground`` do, falling back to
        the menu's. A disabled entry keeps the menu's ``disabledforeground``.
        """
        own = entry.options
        style = attribute
        disabled = str(own.get("state")) == "disabled"
        if disabled:
            style = self._in_state(style, "disabled")
        if active:
            foreground, background = (
                own.get("activeforeground"),
                own.get("activebackground"),
            )
            if foreground or background:
                menu = self._state_colours("active") or ("", "")
                style = self._coloured(
                    style, foreground or menu[0], background or menu[1]
                )
            else:
                style = self._in_state(style, "active")
            return style | _part_relief(self._options["activerelief"])
        foreground = "" if disabled else own.get("foreground")
        background = own.get("background")
        if foreground or background:
            style = self._coloured(style, foreground, background)
        return style

    def _draw_chosen_mark(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        row: int,
        x: int,
        entry: MenuEntry,
        style: int,
        active: bool,
    ) -> None:
        """Draw a chosen entry's tick or bullet in ``selectcolor``, if given.

        Tk's manual: "the color to display in the indicator when the check
        button or radio button is selected". The mark, not the brackets.
        """
        colour = entry.options.get("selectcolor") or self._options["selectcolor"]
        if not colour or entry.kind not in self._INDICATORS:
            return
        mark = self._INDICATORS[entry.kind][0]
        if self._indicator_for(entry) != mark:
            return
        state = self._state_colours("active") if active else None
        background = state[1] if state is not None else ""
        own = entry.options.get("activebackground" if active else "background")
        background = own or background
        self._write_line(
            dispatcher,
            window,
            row,
            x + 1,
            mark[1],
            self._coloured(style, colour, background),
        )

    def _draw_underline(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        row: int,
        entry: MenuEntry,
        style: int,
    ) -> None:
        """Underline the mnemonic character, as tkinter's ``underline`` does."""
        index = int(entry.options.get("underline", -1))
        if not 0 <= index < len(entry.label):
            return
        column = area.x + cells(self._indicator_for(entry) + entry.label[:index])
        if column >= area.x + area.width:
            return
        with contextlib.suppress(_curses.error):
            self._write_line(
                dispatcher,
                window,
                area.y + row,
                column,
                entry.label[index],
                style | _curses.A_UNDERLINE,
            )

    # --------------------------------------------------------------- moving

    def _step(self, direction: int) -> None:
        """Move the active entry, skipping what cannot be chosen."""
        if not self._entries:
            return
        count = len(self._entries)
        at = (
            self._active if self._active is not None else -1 if direction > 0 else count
        )
        for _ in range(count):
            at = (at + direction) % count
            if self._entries[at].selectable:
                self.activate(at)
                return

    def _within(self, x: int, y: int) -> bool:
        """True if a screen cell is inside this menu."""
        left, top = self.winfo_rootx(), self.winfo_rooty()
        return (
            left <= x < left + self._rect.width and top <= y < top + self._rect.height
        )


def _menu_key(event: Event) -> str | None:
    """Move about a posted menu, choose an entry, or dismiss it.

    Returns ``"break"`` for everything the menu consumed. A posted menu holds
    the grab, so it sees every key; letting one through would send it to a
    widget the user cannot currently see.
    """
    menu = event.widget
    keysym = event.keysym
    if keysym == "Escape":
        if menu._as_menubar and not menu._posted:
            _leave_menubar(menu)
        elif menu._torn_off:
            # There is no window manager here to close a torn-off menu's
            # window, so Escape does: it goes, as closing it does in Tk.
            previous = menu._focus_before
            menu.destroy()
            if previous is not None and previous.winfo_exists():
                previous.focus_set()
        else:
            menu.unpost()
        return "break"
    if menu._as_menubar:
        return _menubar_key(menu, keysym)
    if keysym == "Home":
        menu.activate(_first_selectable(menu, 1))
    elif keysym == "End":
        menu.activate(_first_selectable(menu, -1))
    elif keysym in ("Return", "space"):
        menu.invoke("active")
    else:
        _by_mnemonic(menu, event.char)
    # Every key, whether the menu had a use for it or not: Tk's Menu class
    # binds <KeyPress> to "tk::TraverseWithinMenu %W %A; break", read from
    # Tk 9.0.2. A key let through reached bind_all shortcuts behind the open
    # menu - F5 chose "Last file" with Colours open in UAT 46, found by the
    # author. TkCurses-aj1.13.1.
    return "break"


def _menubar_key(menu: Menu, keysym: str) -> str | None:
    """Open what is under the cursor on a menubar."""
    if keysym in ("Return", "space"):
        menu.invoke("active")
        return "break"
    return None


#: menu.tcl binds ``tk::MenuUpArrow`` and the rest to the navigation events,
#: not to the keys; each is named here by the arrow that raises it.
_MENU_ARROWS: dict[str, str] = {
    "<<PrevLine>>": "Up",
    "<<NextLine>>": "Down",
    "<<PrevChar>>": "Left",
    "<<NextChar>>": "Right",
}


def _menu_arrow_binding(keysym: str) -> Callable[[Event], str | None]:
    """A binding that moves through the menu the event reached as ``keysym``
    would."""
    return lambda event: _menu_arrow(event.widget, keysym)


def _menu_arrow(menu: Menu, keysym: str) -> str | None:
    """``tk::MenuUpArrow``, ``MenuDownArrow``, ``MenuLeftArrow`` and
    ``MenuRightArrow``: move through a posted menu, or along a menubar.

    menu.tcl's bindings for these do not break, but a posted menu here keeps
    every key it is sent, as its ``<KeyPress>`` binding does in Tk (see
    :func:`_menu_key`), so that a ``bind_all`` shortcut cannot fire behind it.
    """
    if menu._as_menubar:
        if keysym in ("Left", "Right"):
            menu._step(-1 if keysym == "Left" else 1)
            _reopen(menu)
        elif keysym == "Down":
            menu.invoke("active")
        else:
            return None
        return "break"
    if keysym == "Up":
        menu._step(-1)
    elif keysym == "Down":
        menu._step(1)
    elif keysym == "Right":
        if menu.type("active") == "cascade":
            menu.invoke("active")
        else:
            _to_parent_bar(menu, 1)
    else:
        # A submenu closes back to the menu it came from; a dropdown of the
        # menubar moves along the bar instead, as Tk's MenuNextMenu does.
        # This asked only "is there a parent?", and a menubar is one, so Left
        # in a dropdown closed it rather than opening the menu to its left.
        parent = menu._parent_menu
        if parent is not None and not parent._as_menubar:
            menu.unpost()
        else:
            _to_parent_bar(menu, -1)
    return "break"


def _leave_menubar(menu: Menu) -> None:
    """Escape on a menu bar holding the focus, which F10 gives it when its
    first entry is not a cascade: nothing active, and the focus back where
    it was, as Tk's ``tk::MenuEscape`` unposts it."""
    menu._active = None
    menu._refresh()
    previous, menu._focus_before = menu._focus_before, None
    if previous is not None and previous.winfo_exists():
        previous.focus_set()


def _reopen(menu: Menu) -> None:
    """Follow the active menubar entry with its dropdown, if one is open."""
    if menu._open_cascade is not None and menu._active is not None:
        menu._open(menu._active)


def _to_parent_bar(menu: Menu, direction: int) -> None:
    """Step along the menubar a dropdown belongs to, opening the next one."""
    root_menu: Menu | None = menu
    while root_menu is not None and root_menu._parent_menu is not None:
        root_menu = root_menu._parent_menu
    if root_menu is None or not root_menu._as_menubar:
        return
    root_menu._step(direction)
    if root_menu._active is not None:
        root_menu._open(root_menu._active)


def _accelerated(menu: Menu, entry: MenuEntry) -> Callable[[Event], str]:
    """A binding that chooses ``entry``, wherever it now is in ``menu``."""

    def choose(_event: Event) -> str:
        if entry in menu._entries:
            menu.invoke(menu._entries.index(entry))
        return "break"

    return choose


def _first_selectable(menu: Menu, direction: int) -> int:
    """The first or last entry that can be chosen."""
    numbers = list(range(len(menu._entries)))
    if direction < 0:
        numbers.reverse()
    return next((n for n in numbers if menu._entries[n].selectable), menu._active or 0)


def _first_menu(event: Event) -> None:
    """F10: open the first menu of the window's menu bar, or its first
    Menubutton's. Follows ``tk::FirstMenu``."""
    _open_from_keyboard(_menu_find(event.widget.winfo_toplevel(), ""), "")


def _traverse_to_menu(event: Event) -> None:
    """Alt and a letter: open the menu whose underlined letter it is, in the
    menu bar or on a Menubutton, ignoring case. Follows
    ``tk::TraverseToMenu``; a posted menu never gets here, because the Menu
    class keeps every key it is sent (see :func:`_menu_key`)."""
    char = event.char if len(event.char) == 1 else event.keysym
    if len(char) != 1 or not char.isprintable():
        return
    char = char.lower()
    _open_from_keyboard(_menu_find(event.widget.winfo_toplevel(), char), char)


def _underlined(label: str, underline: Any) -> str:
    """The lower-cased character ``underline`` picks out of ``label``."""
    index = _underline_position(underline, label)
    return label[index].lower() if 0 <= index < len(label) else ""


def _menu_find(window: Misc, char: str) -> Menu | Menubutton | None:
    """The menu bar with an entry underlined ``char`` (lower case), or else the first
    Menubutton so underlined, searched depth first; with ``char`` empty, the
    bar or the first Menubutton. Disabled ones are passed over. Follows
    ``tk::MenuFind``, whose bar is a child of the toplevel; here it is the one
    the window's ``menu`` option names."""
    bar: Menu | None = getattr(window, "_menubar_shown", None)
    if (
        bar is not None
        and bar.winfo_exists()
        and (
            not char
            or any(
                entry.selectable
                and _underlined(entry.label, entry.options.get("underline")) == char
                for entry in bar._entries
            )
        )
    ):
        return bar
    return _menubutton_find(window, window, char)


def _menubutton_find(top: Misc, window: Misc, char: str) -> Menubutton | None:
    """The second half of ``tk::MenuFind``: Menubuttons, not crossing into
    another toplevel."""
    for child in window.winfo_children():
        if child.winfo_toplevel() is not top:
            continue
        if isinstance(child, Menubutton):
            options = child._options
            mine = _underlined(str(options["text"]), options["underline"])
            if (char == mine or not char) and not child._disabled:
                return child
        else:
            found = _menubutton_find(top, child, char)
            if found is not None:
                return found
    return None


def _open_from_keyboard(found: Menu | Menubutton | None, char: str) -> None:
    """Open what :func:`_menu_find` found, as ``tk::TraverseToMenu`` and
    ``tk::FirstMenu`` do: a Menubutton posts its menu; on the bar, ``char``
    picks the entry (``tk::TraverseWithinMenu``) - a cascade opens, anything
    else is chosen - and with none the first entry opens. Either way the menu
    that opens has its first entry active (``tk::MenuFirstEntry``)."""
    if isinstance(found, Menubutton):
        found.post_menu()
        menu = found._options["menu"]
        if menu is not None and menu._posted:
            _first_entry(menu)
        return
    if found is None:
        return
    for number, entry in enumerate(found._entries):
        if not entry.selectable:
            continue
        if char and _underlined(entry.label, entry.options.get("underline")) != char:
            continue
        if entry.kind != "cascade":
            # Chosen, as Tk's TraverseWithinMenu invokes it; with no letter,
            # F10 on a bar whose first entry is a command, it is only shown
            # active - Tk's MenuFirstEntry activates and does not invoke.
            if char:
                found.invoke(number)
            else:
                found._focus_before = found.tk.focus
                found.focus_set()
                found.activate(number)
            return
        found._open(number)
        submenu = entry.options.get("menu")
        if submenu is not None and submenu._posted:
            _first_entry(submenu)
        return


def _first_entry(menu: Menu) -> None:
    """Make the first entry that can be chosen active, unless one already
    is. Follows ``tk::MenuFirstEntry``."""
    if menu._active is not None:
        return
    for number, entry in enumerate(menu._entries):
        if entry.selectable:
            menu.activate(number)
            return


def _by_mnemonic(menu: Menu, char: str) -> str | None:
    """Choose the entry whose underlined letter was typed.

    Returns None when nothing matches. The open menu keeps the key either
    way - see :func:`_menu_key`.
    """
    if not char or not char.isprintable():
        return None
    for number, entry in enumerate(menu._entries):
        index = int(entry.options.get("underline", -1))
        if not entry.selectable or not 0 <= index < len(entry.label):
            continue
        if entry.label[index].lower() == char.lower():
            menu.activate(number)
            menu.invoke(number)
            return "break"
    return None


def _menu_click(event: Event) -> None:
    """Choose what was clicked, or dismiss the menu if the click was elsewhere.

    A posted menu holds the grab, so a click anywhere on the screen arrives
    here - which is exactly what makes clicking away from a menu close it.
    A press on a torn-off menu raises it, and on its title row starts a drag,
    as a Toplevel's title does.
    """
    menu = event.widget
    if menu._torn_off and menu._within(event.x_root, event.y_root):
        menu._raise_torn_off()
        if event.y_root == menu.winfo_rooty():
            menu._drag_origin = (
                event.x_root,
                event.y_root,
                menu.winfo_rootx(),
                menu.winfo_rooty(),
            )
            return
    if not menu._within(event.x_root, event.y_root):
        if menu._as_menubar:
            menu._open_cascade = None
            menu._active = None
            menu._refresh()
        else:
            menu._dismiss_all()
        return
    at = menu._entry_at(
        event.x_root - menu.winfo_rootx(), event.y_root - menu.winfo_rooty()
    )
    if at is not None:
        menu.activate(at)
        menu.invoke(at)


def _menu_drag(event: Event) -> None:
    """Move a torn-off menu by however far the pointer has travelled since
    its title was pressed, as a Toplevel's title moves it; otherwise follow
    the pointer as :func:`_menu_motion` does."""
    menu = event.widget
    origin = menu._drag_origin
    if origin is None:
        _menu_motion(event)
        return
    press_x, press_y, left, top = origin
    menu._move_torn_off(left + event.x_root - press_x, top + event.y_root - press_y)


def _menu_release(event: Event) -> None:
    """End a drag of a torn-off menu."""
    event.widget._drag_origin = None


def _menu_motion(event: Event) -> None:
    """Follow the pointer, as a menu does while it is open."""
    menu = event.widget
    if not menu._within(event.x_root, event.y_root):
        return
    at = menu._entry_at(
        event.x_root - menu.winfo_rootx(), event.y_root - menu.winfo_rooty()
    )
    if at is None or at == menu._active:
        return
    menu.activate(at)
    # A cascade already open follows the pointer to the next one, which is
    # what makes running down a menubar with the button held work.
    if menu._open_cascade is not None and menu._entries[at].kind == "cascade":
        menu._open(at)


class Listbox(_Drawable, XView, YView):
    """A scrollable list of strings, any of which may be selected.

    Four selection modes, as in Tk. ``browse`` - the default - keeps one item
    selected and moves it with the arrows; ``single`` selects only by click or
    by space, leaving the arrows to move an *active* item that is not
    selected; ``multiple`` toggles items independently; ``extended`` adds
    shifted ranges to that.

    The distinction between active and selected is the one worth holding on
    to: the active item is where the keyboard is, and in every mode but
    browse it can be somewhere the selection is not.

    Sample output:
        fruit = tk.Listbox(root, height=4)
        for name in ("Apples", "Pears", "Plums", "Quinces"):
            fruit.insert("end", name)
        fruit.selection_set(1)
        fruit.pack()

    Options:
        activestyle: How the active item is marked: ``underline``, ``dotbox``
            or ``none``.
        listvariable: A variable holding the items, as a Tcl list. Changing
            either changes the other.
        selectmode: ``browse``, ``single``, ``multiple`` or ``extended``.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``disabledforeground``,
    ``exportselection``, ``font``, ``foreground``, ``height``,
    ``highlightbackground``, ``highlightcolor``, ``highlightthickness``,
    ``justify``, ``relief``, ``selectbackground``, ``selectborderwidth``,
    ``selectforeground``, ``setgrid``, ``state``, ``takefocus``, ``width``,
    ``xscrollcommand``, ``yscrollcommand``.

    Differences from tkinter:
        ``selectborderwidth`` draws nothing: a selection is shown by its
        colours. ``setgrid`` changes nothing, a terminal being a grid already.
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"padx", "pady"})

    _STATE_COLOURS: ClassVar[dict[str, tuple[str | None, str | None]]] = {
        "disabled": ("disabledforeground", None),
    }

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "state": _choices("state", "disabled", "normal"),
        "height": _tcl_integer,
        "width": _tcl_integer,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        **_SELECTION_OPTIONS,
        "disabledforeground": "",  # dimmed, as before; see _in_state
        "activestyle": "underline",
        # The selected items go to PRIMARY. TkCurses-9e8.
        "exportselection": 1,
        "font": "",
        "height": 10,
        # Each item aligned within the wider of the widest item and the window,
        # and a variable holding the items as a Tcl list. TkCurses-gm66.10.
        "justify": "left",
        "listvariable": "",
        "relief": "sunken",
        "selectmode": "browse",
        # Kept: a terminal is already a grid of characters. TkCurses-gm66.7.
        "setgrid": 0,
        "state": "normal",
        "takefocus": True,
        "width": 20,
        "xscrollcommand": None,
        "yscrollcommand": None,
    }

    #: Markers either side of a selected row.
    _SELECTED_MARKERS = ("\u25b6", "\u25c0")

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``height``, ``width``, ``selectmode``, ``state``, and the
                standard options.
        """
        self._items: list[str] = []
        #: Each item's own colours, from itemconfigure, kept beside it.
        self._item_options: list[dict[str, Any]] = []
        self._selection: set[int] = set()
        self._active = 0
        self._anchor = 0
        # Tk's Priv(listboxPrev) and Priv(listboxSelection), kept per widget:
        # where a shifted range last reached, and the selection before it
        # began, which shrinking the range gives back. None is "unset".
        self._extend_prev = -1
        self._extend_saved: tuple[int, ...] | None = None
        # A press in progress, where the pointer last was, and the repeat
        # that scrolls a drag held past an edge - tk::ListboxAutoScan.
        self._dragging = False
        self._drag_x = 0
        self._drag_y = 0
        self._autoscan: str | None = None
        self._top = 0
        # Characters scrolled off to the left, shared by every row as in Tk.
        self._left = 0
        self._list_trace: tuple[Variable, str] | None = None
        super().__init__(master, cnf, name=name, **kw)
        self._apply_requested_size()
        self._install_class_bindings()
        self._follow_list_variable()

    def _install_class_bindings(self) -> None:
        """Register the list keys for every Listbox in this application."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        # Each sequence listbox.tcl binds, virtual events and all, so the
        # matcher chooses between them as Tk's does: Control-Home is its own,
        # Shift-Home falls to <<LineStart>>, Control-Up to <<PrevLine>>.
        for sequence, action in _LISTBOX_KEYS.items():
            bind(name, sequence, _listbox_key_binding(action))
        bind(name, "<Button-1>", _listbox_click)
        # Bound as listbox.tcl binds them, so bind_class lists what Tk's
        # does - not because <Button-1> would miss them: a modifier the
        # pattern does not mention does not stop a match, measured in Tk
        # 9.0.2 and here. This comment used to say the opposite.
        bind(name, "<Shift-Button-1>", _listbox_click)
        bind(name, "<Control-Button-1>", _listbox_click)
        # listbox.tcl's empty script: a double-click is left to the program,
        # and the second click of one selects nothing.
        bind(name, "<Double-Button-1>", _listbox_ignore)
        bind(name, "<Motion>", _listbox_drag)
        bind(name, "<ButtonRelease-1>", _listbox_release)
        bind(name, "<Button-4>", _listbox_wheel)
        bind(name, "<Button-5>", _listbox_wheel)
        bind(name, "<FocusIn>", _listbox_refresh)
        bind(name, "<FocusOut>", _listbox_refresh)

    def _apply_requested_size(self) -> None:
        """Ask for the configured rows and columns, plus border and padding.

        A ``width`` or ``height`` of zero or less asks for room for every
        item instead, as listbox(n) says - the widest item, in cells, with
        its two selection markers, and one row an item - never less than
        one of either, as Tk's ``ListboxComputeGeometry`` does.
        """
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        width = int(self._options["width"])
        if width <= 0:
            width = max(1, self._widest()) + 2
        height = int(self._options["height"])
        if height <= 0:
            height = max(1, len(self._items))
        self._request_size(
            width + 2 * int(self._options["padx"]) + edge,
            height + 2 * int(self._options["pady"]) + edge,
        )

    def _refit(self) -> None:
        """The items changed: a list sized to them asks for a new size."""
        if int(self._options["width"]) <= 0 or int(self._options["height"]) <= 0:
            self._apply_requested_size()
            self._invalidate_layout()

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-measuring and repainting as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if {"width", "height"} & set(given):
            self._apply_requested_size()
            self._invalidate_layout()
        if "listvariable" in given:
            self._follow_list_variable()
        if "exportselection" in given and self._selection:
            # Turning it on exports what is selected at once; turning it off
            # keeps PRIMARY, which then reads as nothing. Measured on Tk
            # 9.0.2 - unlike Entry, which gives PRIMARY up.
            self._claim_primary()
        self._redraw()
        return result

    config = configure

    # ------------------------------------------------------- list variable

    def _list_variable(self) -> tuple[Variable | None, bool]:
        """The ``listvariable`` as a Variable, or None, and whether it held a
        value already. A name is a variable of that name, as Tk's is; asked
        before the Variable is made, because making one gives it a value."""
        option = self._options["listvariable"]
        if not option:
            return None, False
        existed = str(option) in self.tk.variables
        if isinstance(option, Variable):
            return option, existed
        return _NamedVariable(self, str(option)), existed

    def _follow_list_variable(self) -> None:
        """Attach to the ``listvariable``, dropping any previous one.

        Measured on Tk 9.0.2: a variable that already exists gives the list
        its items, and one that does not is made from them; the old variable
        is left alone and no longer followed.

        The selection past the new end goes, as it does when the variable is
        written. Tk keeps those indices hidden instead, and appending items
        brings them back selected while inserting before them does not: an
        accident of how it moves its selection table, not copied here.
        """
        if self._list_trace is not None:
            previous, handle = self._list_trace
            previous._unwatch(handle)
            self._list_trace = None
        variable, existed = self._list_variable()
        if variable is None:
            return
        name = str(variable)
        if existed:
            try:
                self._items = _tcl_list(self.tk.variables[name])
            except TclError as error:
                raise TclError(f"{error}: invalid -listvariable value") from None
            self._fit_item_options()
            self._selection = {i for i in self._selection if i < len(self._items)}
            self._refit()
        else:
            self.tk.variables[name] = tuple(self._items)
        handle = variable._watch(lambda: self._list_written(variable))
        self._list_trace = (variable, handle)

    def _list_written(self, variable: Variable) -> None:
        """The variable changed: it is the items now.

        Measured on Tk 9.0.2: the selection past the new end goes for good,
        the active index stays where it was, and a value that is not a list is
        refused with the variable put back as it was. Also called for this
        list's own writes, which read back as the items they already are.
        """
        name = str(variable)
        try:
            items = _tcl_list(self.tk.variables.get(name, ""))
        except TclError:
            self.tk.variables[name] = tuple(self._items)
            raise TclError(f'can\'t set "{name}": invalid listvar value') from None
        self._items = items
        self._fit_item_options()
        self._selection = {i for i in self._selection if i < len(items)}
        self._clamp_view()
        self._refit()
        self._redraw()

    def _publish_items(self) -> None:
        """Write the items to the ``listvariable``, after they change here."""
        if self._list_trace is not None:
            self._list_trace[0].set(tuple(self._items))

    # ------------------------------------------------------------- contents

    def insert(self, index: Any, *elements: str) -> None:
        """Insert items before ``index``; ``end`` appends.

        Ignored while disabled, as Tk ignores it: "items may not be inserted or
        deleted". So are ``delete``, the ``selection`` methods and ``activate``;
        the view still moves, and the ``listvariable`` still sets the items.
        """
        # Measured on Tk 9.0.2. TkCurses-46ap.
        if self._disabled:
            return
        at = len(self._items) if index in ("end", END) else self.index(index)
        self._items[at:at] = [str(element) for element in elements]
        self._fit_item_options(at, len(elements))
        self._shift_state(at, len(elements))
        self._publish_items()
        self._refit()
        self._redraw()

    def delete(self, first: Any, last: Any = None) -> None:
        """Delete items from ``first`` up to and including ``last``.

        Tk's range is inclusive here, unlike Entry's - a difference in Tk
        itself rather than one introduced here.
        """
        if self._disabled:
            return
        start = self.index(first)
        stop = min(start if last is None else self.index(last), len(self._items) - 1)
        if stop < start:
            return
        count = stop - start + 1
        del self._items[start : stop + 1]
        del self._item_options[start : stop + 1]
        self._selection = {
            i if i < start else i - count
            for i in self._selection
            if not start <= i <= stop
        }
        # Measured on Tk 9.0.2 over every anchor, active item and range on
        # lists of 0, 1 and 5: an anchor at or past the range moves back by
        # its length but never before its start; an active item past it
        # moves back, and one inside it goes to its start, kept on an item.
        # TkCurses-ofko.
        if start <= self._anchor:
            self._anchor = max(start, self._anchor - count)
        # The view keeps its items too, as far as they last.
        if start <= self._top:
            self._top = max(start, self._top - count)
        if self._active > stop:
            self._active -= count
        elif self._active >= start:
            self._active = min(start, max(0, len(self._items) - 1))
        self._publish_items()
        self._clamp_view()
        self._refit()
        self._redraw()

    def get(self, first: Any, last: Any = None) -> Any:
        """One item, or a tuple of them when ``last`` is given."""
        start = self.index(first)
        if last is None:
            return self._items[start] if 0 <= start < len(self._items) else ""
        return tuple(self._items[start : self.index(last) + 1])

    def size(self) -> int:
        """How many items there are."""
        return len(self._items)

    #: The options an item takes, measured on Tk 9.0.2: its colours, with
    #: ``bg`` and ``fg`` for the first two.
    _ITEM_OPTIONS = ("background", "foreground", "selectbackground", "selectforeground")

    def _fit_item_options(self, at: int | None = None, count: int = 0) -> None:
        """Keep one option dict per item: ``count`` new ones at ``at``, or
        the list cut or padded to the items, as Tk keeps them by position
        when a ``listvariable`` changes the items under them."""
        options = self._item_options
        if at is not None:
            options[at:at] = [{} for _ in range(count)]
        del options[len(self._items) :]
        options.extend({} for _ in range(len(self._items) - len(options)))

    def _item_at(self, index: Any) -> int:
        """The item an itemconfigure index names: ``end`` is the last one.

        Raises:
            TclError: If it names none, in Tk's words.
        """
        at = len(self._items) - 1 if index in ("end", END) else self.index(index)
        if not 0 <= at < len(self._items):
            # index() keeps a number on the list; Tk names the one given.
            number = _tcl_number(index)
            shown = number if isinstance(number, int) else at
            raise TclError(f'item number "{shown}" out of range')
        # A number past the end is clamped by index() onto the last item.
        number = _tcl_number(index)
        if isinstance(number, int) and not 0 <= number < len(self._items):
            raise TclError(f'item number "{number}" out of range')
        return at

    def _item_option(self, option: str) -> str:
        """The full name of an item option, or Tk's refusal."""
        name = {"bg": "background", "fg": "foreground"}.get(option, option)
        if name not in self._ITEM_OPTIONS:
            raise TclError(f'unknown option "-{option}"')
        return name

    def itemcget(self, index: Any, option: str) -> Any:
        """One option of one item, ``""`` where it has none of its own.

        Raises:
            TclError: If the index names no item or the option is not one.
        """
        at = self._item_at(index)
        return self._item_options[at].get(self._item_option(option), "")

    def itemconfigure(self, index: Any, cnf: Any = None, **kw: Any) -> Any:
        """Set an item's own colours, or read them.

        ``background``, ``foreground``, ``selectbackground`` and
        ``selectforeground`` - ``bg`` and ``fg`` for short - are drawn over
        the list's own for that item, and stay with it as items are
        inserted or deleted around it. With no options it answers all of
        them; with one name, that one, as tkinter's ``configure`` answers.

        Sample output:
            colours = tk.Listbox(root, height=4, width=12)
            colours.insert("end", "plain", "red", "blue")
            colours.itemconfigure(1, background="red")
            colours.itemconfigure(2, foreground="blue")
            colours.pack()

        Raises:
            TclError: If the index names no item, an option is not one, or
                a colour is not a colour.
        """
        at = self._item_at(index)
        own = self._item_options[at]
        if isinstance(cnf, str) and not kw:
            name = self._item_option(cnf)
            return (name, "", "", "", own.get(name, ""))
        given = _given(cnf if isinstance(cnf, dict) else None, kw)
        if not cnf and not kw:
            answer: dict[str, Any] = {
                name: (name, "", "", "", own.get(name, ""))
                for name in self._ITEM_OPTIONS
            }
            answer["bg"] = ("bg", "-background")
            answer["fg"] = ("fg", "-foreground")
            return answer
        checked = {
            self._item_option(option): _colour_or_terminals(self, value)
            for option, value in given.items()
        }
        own.update(checked)
        self._redraw()
        return None

    itemconfig = itemconfigure

    def _shift_state(self, at: int, count: int) -> None:
        """Move the selection, anchor and active item along after an insert.

        Measured on Tk 9.0.2 over every position on lists of 0, 1 and 5: an
        insertion at or before either moves it along, so items added to an
        empty list leave the anchor one past the last of them - six inserted
        at ``end`` give anchor 6 - while the active item is kept on an item,
        5. The anchor used to stay where it was. TkCurses-ofko.
        """
        self._selection = {i + count if i >= at else i for i in self._selection}
        if at <= self._anchor:
            self._anchor += count
        if at <= self._active:
            self._active = min(self._active + count, len(self._items) - 1)
        # Items inserted above the view push it down, so what was in view
        # stays there: only strictly above - an insertion at the top row
        # shows the new items.
        if at < self._top:
            self._top += count
        self._clamp_view()

    # -------------------------------------------------------------- indices

    def index(self, index: Any) -> int:
        """Resolve one of Tk's index forms to a number.

        Understands integers, ``end``, ``active``, ``anchor`` and ``@x,y``.

        Raises:
            TclError: If the form is not one Tk defines.
        """
        if isinstance(index, int):
            return max(0, min(len(self._items), index))
        text = str(index)
        if text.isdigit() or (text.startswith("-") and text[1:].isdigit()):
            return max(0, min(len(self._items), int(text)))
        if text in ("end", END):
            return len(self._items)
        if text == "active":
            return self._active
        if text in ("anchor", ANCHOR):
            return self._anchor
        if text.startswith("@"):
            _, _, coords = text.partition("@")
            _, _, y = coords.partition(",")
            return self.nearest(int(y or 0))
        raise TclError(f'bad listbox index "{index}"')

    def nearest(self, y: int) -> int:
        """The item nearest row ``y`` **within this widget**.

        Widget-relative, as Tk's is, so ``listbox.nearest(event.y)`` in a
        binding answers the item under the mouse. Outside the rows it is the
        nearest visible one, which is what a drag held past the edge selects
        to.
        """
        # Measured on 9.0.2: nearest(0) is the first visible item wherever the
        # listbox sits on screen. It used to subtract winfo_rooty(), which made
        # nearest(event.y) answer the first item for every click. TkCurses-9hr.
        #
        # A pointer below a four-row list scrolled to 2 gives 5, not the last
        # item; this used to give the last item. TkCurses-cpk9.
        area = self._text_area()
        row = max(0, min(y - area.y, area.height - 1))
        return max(0, min(max(0, len(self._items) - 1), self._top + row))

    # ------------------------------------------------------------ selection

    def curselection(self) -> tuple[int, ...]:
        """The selected indices, in order."""
        return tuple(sorted(self._selection))

    def selection_set(self, first: Any, last: Any = None) -> None:
        """Select from ``first`` to ``last`` inclusive, adding to what is.

        Whatever ``selectmode`` says: the mode belongs to the bindings, not to
        this method, so ``selection_set(1, 4)`` then ``selection_set(0)``
        selects 0 to 4 in browse and single too. It does not fire
        ``<<ListboxSelect>>``; a gesture does.
        """
        # Measured on Tk 9.0.2; the mode lives in listbox.tcl. TkCurses-xk41.
        if self._disabled:
            return
        self._selection |= set(self._index_range(first, last))
        if self._selection:
            self._claim_primary()
        self._redraw()

    select_set = selection_set

    def selection_clear(  # type: ignore[override]
        self, first: Any = 0, last: Any = None
    ) -> None:
        """Deselect from ``first`` to ``last`` inclusive.

        The signature disagrees with ``Misc.selection_clear``, which clears
        the X selection and takes keyword arguments. tkinter has the same
        clash for the same reason - a list's selection and the display's
        selection are different things that ended up with one name.
        """
        # selection_clear(0) is item 0 alone, as in Tk; this used to clear
        # every item when ``first`` was 0 and ``last`` was not given.
        if self._disabled:
            return
        self._selection -= set(self._index_range(first, last))
        self._redraw()

    def _index_range(self, first: Any, last: Any) -> range:
        """The items from ``first`` to ``last``, either way round, that exist."""
        start = self.index(first)
        stop = start if last is None else self.index(last)
        low, high = sorted((start, stop))
        return range(low, min(high, len(self._items) - 1) + 1)

    select_clear = selection_clear

    def selection_includes(self, index: Any) -> bool:
        """True if ``index`` is selected."""
        return self.index(index) in self._selection

    select_includes = selection_includes

    def selection_anchor(self, index: Any) -> None:
        """Set the anchor a shifted range extends from, on an item: Tk
        clamps ``anchor 10`` on three items to 2, not to 3."""
        if self._disabled:
            return
        self._anchor = max(0, min(self.index(index), len(self._items) - 1))

    select_anchor = selection_anchor

    def activate(self, index: Any) -> None:
        """Make ``index`` the active item - where the keyboard is.

        It does not scroll: in Tk the bindings that move the active item call
        :meth:`see` themselves, and a program that calls ``activate`` keeps its
        view.
        """
        # This used to scroll to it. TkCurses-cpk9.
        if self._disabled:
            return
        self._active = max(0, min(max(0, len(self._items) - 1), self.index(index)))
        self._redraw()

    # ------------------------------------------------------------ PRIMARY
    #
    # TkCurses-9e8, measured on Tk 9.0.2: selecting takes PRIMARY, and it
    # reads as the selected items, one per line; clearing keeps it, and then
    # it reads as nothing. Losing it to another widget clears the selection
    # and sends <<ListboxSelect>> - with nothing selected, and while
    # disabled, too. With exportselection off, nothing is taken, and a loss
    # leaves the selection alone.

    def _claim_primary(self) -> None:
        """Take PRIMARY for the selection, if ``exportselection`` says so."""
        if not self.getboolean(self._options["exportselection"]):
            return
        selections = self.tk.selections
        selections.own(self, PRIMARY, lost=self._lost_primary)
        selections.handle(self, self._primary_selection, PRIMARY)

    def _lost_primary(self) -> None:
        """Another widget took PRIMARY: clear, and say so."""
        if not self.getboolean(self._options["exportselection"]):
            return
        self._selection.clear()
        self._redraw()
        self.event_generate("<<ListboxSelect>>")

    def _primary_selection(self, *_args: Any) -> str:
        """The selected items, one per line, for whoever reads PRIMARY."""
        if not self._selection or not self.getboolean(self._options["exportselection"]):
            raise TclError(f"{PRIMARY} selection doesn't exist or form unknown")
        return "\n".join(self._items[i] for i in sorted(self._selection))

    def _fire_select(self) -> None:
        """``<<ListboxSelect>>``, once per gesture, as
        ``tk::FireListboxSelectEvent`` sends it: only from the bindings. It
        is sent whether or not the gesture changed anything - a click on the
        one item already selected sends it too, measured on Tk 9.0.2. Not
        while disabled, where the bindings still run - they scroll - but
        every command that would change the selection is refused.
        """
        if not self._disabled:
            self.event_generate("<<ListboxSelect>>")

    # ----------------------------------------------------------- scrolling

    def see(self, index: Any) -> None:
        """Scroll so ``index`` is visible.

        An item no more than a third of the height out of view is brought to
        the nearest edge, and one further away is centred, as in Tk.
        """
        # Measured on Tk 9.0.2 over every top row and index on 20 items at
        # heights 1 to 9: see(5) on four rows from the top puts 4 at the top,
        # where the nearest edge would have put 2. This used to scroll as little
        # as possible. TkCurses-cpk9.
        position = self.index(index)
        height = self._text_area().height
        if height <= 0:
            return
        centred = position - (height - 1) // 2
        if position < self._top:
            near = self._top - position <= height // 3
            self._top = position if near else centred
        elif position > self._top + height - 1:
            beyond = position - (self._top + height - 1)
            self._top = self._top + beyond if beyond <= height // 3 else centred
        self._clamp_view()
        self._redraw()

    def yview(self, *args: Any) -> Any:
        """Get or set the visible window.

        Called with nothing it reports the view as the pair of fractions a
        scrollbar wants. Called by a scrollbar it takes Tk's own arguments -
        ``("moveto", fraction)`` or ``("scroll", count, "units"|"pages")`` -
        which is what lets any scrollbar drive any widget without either
        knowing what the other is.
        """
        if not args:
            return self._view_fractions()
        if len(args) == 1:
            self._top = self.index(args[0])
        elif args[0] == "moveto":
            # Rounded, halves up, as Tk does; this truncated. TkCurses-md5.
            self._top = math.floor(float(args[1]) * len(self._items) + 0.5)
        elif args[0] == "scroll":
            count = int(args[1])
            # A page is the height less two, never under one, as it is
            # sideways: measured on Tk 9.0.2 at heights 1 to 8. It used to
            # be the whole height. TkCurses-cpk9.
            height = self._text_area().height
            step = max(1, height - 2) if args[2] == "pages" else 1
            self._top += count * step
        self._clamp_view()
        self._redraw()
        return None

    def xview(self, *args: Any) -> Any:
        """Report or move the horizontal view, in characters.

        ``xview()`` answers the first and last columns in view as fractions of
        the widest item, which is what a horizontal scrollbar wants. A unit is
        one character; a page is the width less two, at least one. ``moveto``
        rounds to the nearest character, and a bare index is a character
        offset. All of them stop with the widest item's end at the right edge.
        """
        # Missing outright until TkCurses-019. Measured against Tk 9.0.2, a
        # 10-wide listbox holding a 30-character item: xview() is (0.0,
        # 0.333...); a page is 8 at width 10, 18 at 20, 1 at 3; moveto 0.49 and
        # 0.51 of 30 both land on 15. The width here is the text's, between the
        # two selection markers.
        if not args:
            return self._horizontal_fractions()
        width = self._body_width()
        if len(args) == 1:
            try:
                left = int(args[0])
            except (TypeError, ValueError):
                raise TclError(f'expected integer but got "{args[0]}"') from None
        elif args[0] == "moveto":
            # Halves round UP, as Tk's do; round() would send 2.5 to 2.
            # TkCurses-5e0.
            left = math.floor(float(args[1]) * self._widest() + 0.5)
        elif args[0] == "scroll":
            what = str(args[2])
            if what not in ("units", "pages"):
                raise TclError(f'bad argument "{what}": must be pages or units')
            step = max(1, width - 2) if what == "pages" else 1
            left = self._left + int(args[1]) * step
        else:
            raise TclError(f'expected integer but got "{args[0]}"')
        self._left = max(0, min(left, self._widest() - width))
        self._publish_view()
        self._redraw()
        return None

    def scan_mark(self, x: Any, y: Any) -> None:
        """Remember where a scan starts, and the view there.

        Raises:
            TclError: If ``x`` or ``y`` is not an integer, in Tk's words.
        """
        self._scan = (
            _tcl_integer(None, x),
            _tcl_integer(None, y),
            self._left,
            self._top,
        )

    def scan_dragto(self, x: Any, y: Any) -> None:
        """Scroll by ten times how far ``(x, y)`` is from the mark, as Tk's
        ``scan dragto`` does; a drag that runs into an edge starts again
        from there, so the view moves as soon as the pointer turns back.

        Differences from tkinter:
            ``x`` and ``y`` are columns and rows, as ``event.x`` and
            ``event.y`` are here, so a row of drag is ten items and a
            column ten characters.
        """
        # Tk's ListboxScanTo, tkListbox.c: the mark is reset at an edge, to
        # the edge, even when the edge is below nought because the list is
        # shorter or narrower than the window.
        x, y = _tcl_integer(None, x), _tcl_integer(None, y)
        mark_x, mark_y, mark_left, mark_top = getattr(self, "_scan", (0, 0, 0, 0))
        height = max(1, self._text_area().height)
        last_top = len(self._items) - height
        top = mark_top - 10 * (y - mark_y)
        if top > last_top:
            top = mark_top = last_top
            mark_y = y
        elif top < 0:
            top = mark_top = 0
            mark_y = y
        last_left = self._widest() - self._body_width()
        left = mark_left - 10 * (x - mark_x)
        if left > last_left:
            left = mark_left = last_left
            mark_x = x
        elif left < 0:
            left = mark_left = 0
            mark_x = x
        self._scan = (mark_x, mark_y, mark_left, mark_top)
        self._top = top
        self._left = max(0, left)
        self._clamp_view()
        self._redraw()

    def _widest(self) -> int:
        """The longest item, in cells: what the horizontal view is a fraction of."""
        return max((cells(item) for item in self._items), default=0)

    def _body_width(self) -> int:
        """How many cells of each item show, between the selection markers."""
        return max(1, self._text_area().width - 2)

    def _horizontal_fractions(self) -> tuple[float, float]:
        """Where the visible columns are, as two fractions of the widest item.

        The offset is NOT clamped here, and that is Tk's too: measured, scroll
        one character right and then delete the wide item, and ``xview()``
        answers ``(0.2, 1.0)`` over a five-character remainder. It holds until
        the view next moves.
        """
        widest = self._widest()
        if widest <= 0:
            return (0.0, 1.0)
        width = self._body_width()
        return (
            min(1.0, self._left / widest),
            min(1.0, (self._left + width) / widest),
        )

    def _view_fractions(self) -> tuple[float, float]:
        """Where the window is, as two fractions of the whole list."""
        total = len(self._items)
        if total <= 0:
            return (0.0, 1.0)
        height = max(1, self._text_area().height)
        return (self._top / total, min(1.0, (self._top + height) / total))

    def _report_scroll_view(self) -> None:
        """A resize changes how much is visible, so the scrollbar is retold."""
        self._publish_view()

    def _publish_view(self) -> None:
        """Tell the scrollbars where the view is, if any are listening."""
        command = self._options["yscrollcommand"]
        if command is not None:
            first, last = self._view_fractions()
            command(first, last)
        command = self._options["xscrollcommand"]
        if command is not None:
            first, last = self._horizontal_fractions()
            command(first, last)

    def _clamp_view(self) -> None:
        """Keep the visible window inside the list, and report where it is."""
        height = max(1, self._text_area().height)
        self._top = max(0, min(self._top, max(0, len(self._items) - height)))
        self._publish_view()

    def bbox(self, index: Any) -> tuple[int, int, int, int] | None:
        """Where an item is on screen, or None if it is scrolled out of view."""
        position = self.index(index)
        area = self._text_area()
        row = position - self._top
        if not (0 <= row < area.height):
            return None
        return (
            self.winfo_rootx() + area.x,
            self.winfo_rooty() + area.y + row,
            area.width,
            1,
        )

    # ------------------------------------------------------------- painting

    def _text_area(self) -> Rect:
        """Where the items go, in cells relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        return Rect(
            edge + padx,
            edge + pady,
            max(0, self._rect.width - 2 * (edge + padx)),
            max(0, self._rect.height - 2 * (edge + pady)),
        )

    def _redraw(self) -> None:
        """Paint the visible items, marking the selected and active ones."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        area = self._text_area()
        dispatcher = CursesDispatcher.get()
        attribute = self._in_state(
            self._background_attribute() | self._font_attribute()
        )
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            if area.is_empty:
                return
            self._clamp_view()
            for row in range(area.height):
                position = self._top + row
                if position >= len(self._items):
                    break
                self._draw_item(dispatcher, window, area, row, position, attribute)

    def _draw_item(
        self,
        dispatcher: CursesDispatcher,
        window: Any,
        area: Rect,
        row: int,
        position: int,
        attribute: int,
    ) -> None:
        """Draw one row: its markers if selected, then its text.

        A disabled list keeps its selection and does not show it, as
        ``listbox(n)`` says and Tk 9.0.2 draws it: captured, a red
        ``selectbackground`` covered the selected row and none of it once
        the list was disabled. TkCurses-46ap.
        """
        selected = position in self._selection and not self._disabled
        own = self._item_options[position] if position < len(self._item_options) else {}
        if selected:
            style = self._selection_attribute(
                attribute,
                own.get("selectforeground") or None,
                own.get("selectbackground") or None,
            )
        elif own.get("foreground") or own.get("background"):
            style = self._coloured(
                attribute, own.get("foreground"), own.get("background")
            )
        else:
            style = attribute
        if position == self._active and self.focus_get() is self and not selected:
            style |= _curses.A_UNDERLINE
        left, right = self._SELECTED_MARKERS if selected else (" ", " ")
        item = self._items[position]
        # Measured on Tk 9.0.2: aligned within the wider of the widest item and
        # the window, so the horizontal view moves every row together.
        room = max(self._widest(), self._body_width()) - cells(item)
        justify = str(self._options["justify"])
        shift = {"right": room, "center": room // 2}.get(justify, 0)
        item = " " * max(0, shift) + item
        # Scrolled in cells: an ideograph the left edge cuts leaves a blank.
        item, blank = skip_cells(item, self._left)
        body = clip_text(" " * blank + item, max(0, area.width - 2))
        line = pad_cells(f"{left}{body}", area.width - 1) + right
        # One write, through the shared writer. The marker used to go on
        # separately with insstr, which INSERTS: it shifted the row one cell
        # right and dropped the last one, and on a bordered listbox the cell
        # it dropped was the border. insstr is right only at the window's
        # genuinely last cell, and _write_line is the one thing that knows
        # when that is.
        self._write_line(dispatcher, window, area.y + row, area.x, line, style)


# ----------------------------------------------- Listbox, after listbox.tcl
#
# Each function names the Tk procedure or binding it follows. They run on a
# disabled Listbox too, as Tk's do: the commands that would change it refuse
# for themselves, and the view still scrolls.


def _listbox_key_binding(action: Callable[[Listbox], None]) -> Callable[[Event], None]:
    """A binding that runs ``action`` on the widget the event reached.

    None of them breaks: a key goes on to the toplevel's bindings and
    ``all``'s, handled or not, as listbox.tcl's do. This used to stop the
    keys it handled, which took Escape from a dialog whose list had the
    focus once Escape was bound here. TkCurses-cpk9.
    """
    return lambda event: action(event.widget)


def _listbox_page(listbox: Listbox, amount: int) -> None:
    """``<Prior>``/``<Next>``: scroll a page and make the top row active.
    They select nothing, in any mode; this used to move the selection in
    browse mode."""
    listbox.yview("scroll", amount, "pages")
    listbox.activate(listbox._top)


def _listbox_select_edge(listbox: Listbox, index: int) -> None:
    """``<Control-Home>``/``<Control-End>``: activate, show and select the
    first or last item, whatever the mode."""
    listbox.activate(index)
    listbox.see(index)
    listbox.selection_clear(0, "end")
    listbox.selection_set(index)
    listbox._fire_select()


def _listbox_xview(*args: Any) -> Callable[[Listbox], None]:
    """A key bound to one ``xview`` call."""
    return lambda listbox: listbox.xview(*args)


#: Sequence -> what listbox.tcl binds to it, in its order. Most are virtual
#: events, which tk.tcl maps to the arrows, Home and End on X11; a program
#: can event_add another key to one and the list follows. TkCurses-yu5l.
_LISTBOX_KEYS: dict[str, Callable[[Listbox], None]] = {
    "<<PrevLine>>": lambda lb: _listbox_up_down(lb, -1),
    "<<SelectPrevLine>>": lambda lb: _listbox_extend_up_down(lb, -1),
    "<<NextLine>>": lambda lb: _listbox_up_down(lb, 1),
    "<<SelectNextLine>>": lambda lb: _listbox_extend_up_down(lb, 1),
    "<<PrevChar>>": _listbox_xview("scroll", -1, "units"),
    "<<PrevWord>>": _listbox_xview("scroll", -1, "pages"),
    "<<NextChar>>": _listbox_xview("scroll", 1, "units"),
    "<<NextWord>>": _listbox_xview("scroll", 1, "pages"),
    "<Key-Prior>": lambda lb: _listbox_page(lb, -1),
    "<Key-Next>": lambda lb: _listbox_page(lb, 1),
    "<Control-Key-Prior>": _listbox_xview("scroll", -1, "pages"),
    "<Control-Key-Next>": _listbox_xview("scroll", 1, "pages"),
    "<<LineStart>>": _listbox_xview("moveto", 0),
    "<<LineEnd>>": _listbox_xview("moveto", 1),
    "<Control-Key-Home>": lambda lb: _listbox_select_edge(lb, 0),
    "<Control-Shift-Key-Home>": lambda lb: _listbox_data_extend(lb, 0),
    "<Control-Key-End>": lambda lb: _listbox_select_edge(lb, max(0, lb.size() - 1)),
    "<Control-Shift-Key-End>": lambda lb: _listbox_data_extend(lb, lb.size()),
    "<<Copy>>": lambda lb: _listbox_copy(lb),
    "<Key-space>": lambda lb: _listbox_begin_select(lb, lb._active),
    "<<Invoke>>": lambda lb: _listbox_begin_select(lb, lb._active),
    "<Key-Select>": lambda lb: _listbox_begin_select(lb, lb._active),
    "<Control-Shift-Key-space>": lambda lb: _listbox_begin_extend(lb, lb._active),
    "<Shift-Key-Select>": lambda lb: _listbox_begin_extend(lb, lb._active),
    "<Key-Escape>": lambda lb: _listbox_cancel(lb),
    "<<SelectAll>>": lambda lb: _listbox_select_all(lb),
    # No sequence of its own here: Tk's is Control-backslash, which a tty
    # turns into SIGQUIT, and binding it would take the quit key from every
    # program with a Listbox. A program may event_add one.
    "<<SelectNone>>": lambda lb: _listbox_select_none(lb),
}


def _listbox_copy(listbox: Listbox) -> None:
    """listbox.tcl's ``<<Copy>>``: the exported selection to the clipboard,
    if this list owns PRIMARY. Reading it raises, as Tk's binding does, when
    the list owns it with nothing selected."""
    if listbox.tk.selections.owner(PRIMARY) is listbox:
        text = listbox.selection_get()
        listbox.clipboard_clear()
        listbox.clipboard_append(text)


def _listbox_click(event: Event) -> None:
    """``<Button-1>``, ``<Shift-Button-1>`` and ``<Control-Button-1>``, on
    the item nearest the pointer - the last one, for a click below it."""
    listbox = event.widget
    index = listbox.nearest(event.y)
    listbox._dragging = True
    listbox._drag_y = event.y
    if event.state & _TK_SHIFT:
        _listbox_begin_extend(listbox, index)
    elif event.state & _TK_CONTROL:
        _listbox_begin_toggle(listbox, index)
    else:
        _listbox_begin_select(listbox, index, focus=True)


def _listbox_ignore(event: Event) -> None:
    """listbox.tcl's empty ``<Double-Button-1>``."""
    del event


def _listbox_drag(event: Event) -> None:
    """``<B1-Motion>``: ``tk::ListboxMotion`` to the item under the
    pointer; and ``<B1-Leave>``/``<B1-Enter>`` - ``tk::ListboxAutoScan`` at
    once as the pointer leaves the widget, ``tk::CancelRepeat`` as it comes
    back.

    A drag arrives as ``<Motion>`` while the press is held, as Entry's does.
    """
    listbox = event.widget
    if not listbox._dragging:
        return
    listbox._drag_x, listbox._drag_y = event.x, event.y
    _listbox_motion(listbox, listbox.nearest(event.y))
    inside = 0 <= event.x < listbox.winfo_width() and (
        0 <= event.y < listbox.winfo_height()
    )
    if inside:
        _cancel_autoscan(listbox)
    elif listbox._autoscan is None:
        _listbox_autoscan(listbox)


def _listbox_autoscan(listbox: Listbox) -> None:
    """``tk::ListboxAutoScan``: while the button is held outside, a row
    towards the pointer above or below, else two columns beside, every 50ms,
    and the selection run to the item nearest it."""
    listbox._autoscan = None
    if not listbox.winfo_exists():
        return
    x, y = listbox._drag_x, listbox._drag_y
    if y >= listbox.winfo_height():
        listbox.yview("scroll", 1, "units")
    elif y < 0:
        listbox.yview("scroll", -1, "units")
    elif x >= listbox.winfo_width():
        listbox.xview("scroll", 2, "units")
    elif x < 0:
        listbox.xview("scroll", -2, "units")
    else:
        return
    _listbox_motion(listbox, listbox.nearest(y))
    listbox._autoscan = listbox.after(50, lambda: _listbox_autoscan(listbox))


def _listbox_release(event: Event) -> None:
    """``<ButtonRelease-1>``: stop any repeat, and activate the item under
    the pointer - where a drag ended, not where it began."""
    listbox = event.widget
    listbox._dragging = False
    _cancel_autoscan(listbox)
    listbox.activate(listbox.nearest(event.y))


def _listbox_begin_select(listbox: Listbox, index: int, *, focus: bool = False) -> None:
    """``tk::ListboxBeginSelect``: toggle in multiple mode, otherwise make
    ``index`` the whole selection and the anchor; then take the focus, for a
    click, unless disabled."""
    if str(listbox._options["selectmode"]) == "multiple":
        if index in listbox._selection:
            listbox.selection_clear(index)
        else:
            listbox.selection_set(index)
    else:
        listbox.selection_clear(0, "end")
        listbox.selection_set(index)
        listbox.selection_anchor(index)
        listbox._extend_saved = ()
        listbox._extend_prev = index
    listbox._fire_select()
    if focus and listbox.winfo_exists() and not listbox._disabled:
        listbox.focus_set()


def _listbox_begin_toggle(listbox: Listbox, index: int) -> None:
    """``tk::ListboxBeginToggle``: in extended mode only, toggle ``index``
    and leave the rest of the selection alone."""
    if str(listbox._options["selectmode"]) != "extended":
        return
    listbox._extend_saved = listbox.curselection()
    listbox._extend_prev = index
    listbox.selection_anchor(index)
    if index in listbox._selection:
        listbox.selection_clear(index)
    else:
        listbox.selection_set(index)
    listbox._fire_select()


def _listbox_begin_extend(listbox: Listbox, index: int) -> None:
    """``tk::ListboxBeginExtend``: in extended mode only, run the range from
    the anchor to ``index`` - or begin one, if the anchor is not selected."""
    if str(listbox._options["selectmode"]) != "extended":
        return
    if listbox._anchor in listbox._selection:
        _listbox_motion(listbox, index)
    else:
        _listbox_begin_select(listbox, index)


def _listbox_motion(listbox: Listbox, index: int) -> None:
    """``tk::ListboxMotion``: in browse mode the selection follows; in
    extended mode the range from the anchor is replaced, not added to.

    Moving a range's end back towards the anchor deselects what it gives up,
    except for items selected before it began, which it gives back. From an
    anchor that is not selected - a Control-click took it out - the range
    deselects instead.
    """
    if index == listbox._extend_prev:
        return
    mode = str(listbox._options["selectmode"])
    if mode == "browse":
        listbox.selection_clear(0, "end")
        listbox.selection_set(index)
        listbox._extend_prev = index
        listbox._fire_select()
        return
    if mode != "extended":
        return
    anchor = listbox._anchor
    prev = listbox._extend_prev
    if prev < 0:
        # Tk's Priv(listboxPrev) starts as "", which compares below 0. Not
        # the same as clearing from 0: items a program selected below a
        # higher anchor would go.
        prev = index
        listbox.selection_set(index)
    # Asked before the clear, which may take the anchor out.
    keep = anchor in listbox._selection
    listbox.selection_clear(prev, index)
    if keep:
        listbox.selection_set(anchor, index)
    else:
        listbox.selection_clear(anchor, index)
    if listbox._extend_saved is None:
        listbox._extend_saved = listbox.curselection()
    saved = listbox._extend_saved
    while prev < index and prev < anchor:
        if prev in saved:
            listbox.selection_set(prev)
        prev += 1
    while prev > index and prev > anchor:
        if prev in saved:
            listbox.selection_set(prev)
        prev -= 1
    listbox._extend_prev = index
    listbox._fire_select()


def _listbox_up_down(listbox: Listbox, amount: int) -> None:
    """``tk::ListboxUpDown``: move the active item and show it, and in
    browse and extended mode take the selection with it."""
    listbox.activate(listbox._active + amount)
    listbox.see(listbox._active)
    mode = str(listbox._options["selectmode"])
    if mode in ("browse", "extended"):
        listbox.selection_clear(0, "end")
        listbox.selection_set(listbox._active)
        if mode == "extended":
            listbox.selection_anchor(listbox._active)
            listbox._extend_prev = listbox._active
            listbox._extend_saved = ()
        listbox._fire_select()


def _listbox_extend_up_down(listbox: Listbox, amount: int) -> None:
    """``tk::ListboxExtendUpDown``: in extended mode only, move the active
    item and run the range to it."""
    if str(listbox._options["selectmode"]) != "extended":
        return
    active = listbox._active
    if listbox._extend_saved is None:
        listbox.selection_set(active)
        listbox._extend_saved = listbox.curselection()
    listbox.activate(active + amount)
    listbox.see(listbox._active)
    _listbox_motion(listbox, listbox._active)


def _listbox_data_extend(listbox: Listbox, index: int) -> None:
    """``tk::ListboxDataExtend``: Control-Shift-Home and -End. Extended
    mode moves there and runs the range; multiple mode only moves."""
    mode = str(listbox._options["selectmode"])
    if mode not in ("extended", "multiple"):
        return
    listbox.activate(index)
    listbox.see(index)
    if mode == "extended" and listbox._anchor in listbox._selection:
        _listbox_motion(listbox, listbox._active)


def _listbox_cancel(listbox: Listbox) -> None:
    """``tk::ListboxCancel``: Escape puts back what the range since the
    anchor replaced, in extended mode."""
    if str(listbox._options["selectmode"]) != "extended":
        return
    first, last = listbox._anchor, listbox._extend_prev
    if last < 0:
        return
    first, last = sorted((first, last))
    listbox.selection_clear(first, last)
    saved = listbox._extend_saved or ()
    for index in range(first, last + 1):
        if index in saved:
            listbox.selection_set(index)
    listbox._fire_select()


def _listbox_select_all(listbox: Listbox) -> None:
    """``tk::ListboxSelectAll``: everything, or in single and browse mode
    the active item alone."""
    if str(listbox._options["selectmode"]) in ("single", "browse"):
        listbox.selection_clear(0, "end")
        listbox.selection_set(listbox._active)
    else:
        listbox.selection_set(0, "end")
    listbox._fire_select()


def _listbox_select_none(listbox: Listbox) -> None:
    """listbox.tcl's ``<<SelectNone>>``: clear, except in browse mode."""
    if str(listbox._options["selectmode"]) != "browse":
        listbox.selection_clear(0, "end")
        listbox._fire_select()


def _listbox_wheel(event: Event) -> None:
    """Scroll the list by the wheel, without moving the selection."""
    listbox = event.widget
    listbox.yview("scroll", -1 if event.num == 4 else 1, "units")


def _listbox_refresh(event: Event) -> None:
    """Repaint after the focus moved, so the active row shows or stops."""
    event.widget._redraw()


class PanedWindow(_Drawable):
    """A container whose children are divided by sashes a person can drag.

    Children are added with ``add`` rather than packed or gridded, and the
    paned window arranges them. The difference from pack is that the
    arrangement is *stateful* - a sash someone dragged stays where they put
    it, and a later resize works from there rather than starting again from
    what the children ask for.

    Drag a sash with the mouse, or move it with the arrows once the paned
    window has the focus: a terminal user with no mouse would otherwise have
    no way to resize a pane at all.

    Sample output:
        panes = tk.PanedWindow(root, width=30, height=5)
        panes.pack()
        panes.add(tk.Label(panes, text="Left"))
        panes.add(tk.Label(panes, text="Right"))

    Options:
        handlepad: How far along the sash the handle is drawn.
        handlesize: How long the handle is.
        opaqueresize: Whether the panes follow a sash as it is dragged, or
            move once it is let go.
        proxybackground: The colour of the outline that shows where a sash
            will go while it is dragged.
        proxyborderwidth: The border of that outline.
        proxyrelief: The relief of that outline.
        sashcursor: The mouse pointer over a sash.
        sashpad: Space either side of each sash.
        sashrelief: The relief of each sash.
        sashwidth: How wide each sash is.
        showhandle: Whether each sash has a handle to grab.

    Standard options, described in :doc:`/reference/options`:
    ``background``, ``borderwidth``, ``cursor``, ``height``, ``orient``,
    ``relief``, ``width``.

    Differences from tkinter:
        ``proxyborderwidth`` and ``sashcursor`` are kept and read back and
        change nothing: an outline is one cell, and the pointer is the
        terminal's. So is ``cursor``: the mouse pointer belongs to the
        terminal.

    Sample output (sashrelief, sashwidth, sashpad):
        panes = tk.PanedWindow(root, width=30, height=4, sashrelief="raised",
                               sashwidth=3, sashpad=1)
        panes.pack()
        panes.add(tk.Label(panes, text="Left"))
        panes.add(tk.Label(panes, text="Right"))

    Sample output (showhandle, handlesize, handlepad):
        panes = tk.PanedWindow(root, width=30, height=5, showhandle=1,
                               handlesize=2, handlepad=1)
        panes.pack()
        panes.add(tk.Label(panes, text="Left"))
        panes.add(tk.Label(panes, text="Right"))
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset(
        {
            "foreground",
            "highlightbackground",
            "highlightcolor",
            "highlightthickness",
            "padx",
            "pady",
            "takefocus",
        }
    )

    #: The sash, drawn along the whole division.
    _SASH: ClassVar[dict[str, str]] = {"horizontal": "│", "vertical": "─"}

    #: Drawn in the middle of the sash when ``showhandle`` is on, so a sash
    #: can be told from a border.
    _HANDLE: ClassVar[dict[str, str]] = {"horizontal": "┃", "vertical": "━"}

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        # Tk's are 6 points, about a cell. TkCurses-gm66.9.
        "handlepad": 1,
        "handlesize": 1,
        "height": "",
        "opaqueresize": True,
        "orient": "horizontal",
        "proxybackground": "",
        "proxyborderwidth": 2,
        "proxyrelief": "flat",
        "relief": "flat",
        # A terminal shows no pointer shape; kept for the program to read.
        "sashcursor": "",
        "sashpad": 0,
        "sashrelief": "flat",
        "sashwidth": 1,
        "showhandle": True,
        "takefocus": True,
        "width": "",
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``orient``, ``showhandle``, the sash, handle and proxy
                options, ``opaqueresize``, ``width``, ``height``, and the
                standard options.
        """
        self._active_sash: int | None = None
        #: Where a drag with ``opaqueresize`` off would put the sash, and the
        #: panel the proxy is drawn on, over the panes. Tk's ``Priv(sash)``.
        self._proxy_at: int | None = None
        self._proxy_panel: Any = None
        #: What ``proxy coord`` answers: where it was last placed, kept
        #: after ``proxy forget``, as Tk keeps it.
        self._proxy_xy = (0, 0)
        #: Each sash's mark, for ``sash dragto``; (0, 0) until set.
        self._sash_marks: dict[int, tuple[int, int]] = {}
        super().__init__(master, cnf, name=name, **kw)
        self._paned = PanedLayout(str(self._options["orient"]))
        self._paned.sash = self._sash_span()
        self._paned_manager = self._paned
        self._install_class_bindings()

    def _install_class_bindings(self) -> None:
        """Register sash dragging and the keys that move one."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Button-1>", _paned_press)
        bind(name, "<Motion>", _paned_motion)
        bind(name, "<ButtonRelease-1>", _paned_release)
        bind(name, "<Any-Key>", _paned_key)
        # The sash marks itself as the focused thing, so it has to be
        # repainted when the focus arrives and again when it leaves. A click
        # repainted it as a side effect of starting a drag; Tab had nothing
        # to trigger a repaint, so the focus moved in silence.
        bind(name, "<FocusIn>", _paned_refresh)
        bind(name, "<FocusOut>", _paned_refresh)

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-laying the panes out as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if "orient" in given:
            self._paned.orient = str(self._options["orient"])
        if given:
            self._paned.sash = self._sash_span()
            self._invalidate_layout()
            self._redraw()
        return result

    def _checked(self, given: dict[str, Any]) -> dict[str, Any]:
        """The shared checks, and Tk's ``""`` for an unset width or height."""
        resolved = super()._checked(given)
        for option in ("width", "height"):
            if option in resolved and isinstance(resolved[option], str):
                resolved[option] = _distance_or_empty(self, resolved[option])
        return resolved

    def _outer_size(self, content: Size) -> Size:
        """What the panes need, unless ``width`` or ``height`` says otherwise.

        Measured on Tk 9.0.2: ``width 300`` over two 100-pixel panes asked for
        300, and ``""`` gave the panes' 218 back. Either axis alone.
        """
        size = super()._outer_size(content)
        width = _as_int(self._options["width"], 0)
        height = _as_int(self._options["height"], 0)
        return Size(
            width if width > 0 else size.width, height if height > 0 else size.height
        )

    # ---------------------------------------------------------------- sashes

    def _sash_parts(self) -> tuple[int, int, int]:
        """A sash's ``(pad, core, width)``: the padding either side of it, the
        cells between the paddings, and the drawn line within those.

        Measured on Tk 9.0.2, a sash is as wide as ``sashwidth`` or, with a
        handle shown, ``handlesize`` if that is wider, with ``sashpad`` either
        side: sashwidth 4 and handlesize 8 put the second pane 8 past the
        first with no padding and 18 past with 5. Here a line under one cell
        cannot be drawn or dragged, so one is the least of each.
        """
        width = max(1, _as_int(self._options["sashwidth"], 1))
        core = width
        if self._showhandle:
            core = max(core, _as_int(self._options["handlesize"], 1))
        return max(0, _as_int(self._options["sashpad"], 0)), core, width

    def _sash_span(self) -> int:
        """Cells a sash takes between two panes, its padding included."""
        pad, core, _ = self._sash_parts()
        return core + 2 * pad

    def _sash_inset(self) -> int:
        """How far into its span the drawn line starts. ``sash_coord`` names
        the line, not the span: measured, a 4-pixel sash under an 8-pixel
        handle is at 102 after a 100-pixel pane, and ``sash_place`` at 150
        reads back 150."""
        pad, core, width = self._sash_parts()
        return pad + (core - width) // 2

    config = configure

    # ------------------------------------------------------------------ panes

    def add(self, child: Widget, **kw: Any) -> None:
        """Add a pane at the end.

        Args:
            child: The widget to put in it. Must be a child of this window.
            **kw: ``minsize``, ``sticky``, ``stretch``, ``width`` or
                ``height``.

        A pane starts at its ``width`` (``height`` in a vertical window) or
        else the size its child asks for, and ``stretch`` says which panes
        take the room beyond that: ``last``, the default, gives it all to
        the last pane, and ``always``, ``first``, ``middle`` and ``never``
        are as Tk's. Moving a sash sets every pane's ``width``, so that the
        split stays where it was put.
        """
        self._paned.add(child, self._pane_options(kw, child))
        self._manage(child)

    def insert(self, index: Any, child: Widget, **kw: Any) -> None:
        """Add a pane at a position rather than at the end.

        TkCurses extension:
            tkinter's PanedWindow adds panes only with :meth:`add`, whose
            ``before`` and ``after`` options do the same.
        """
        self._paned.insert(
            self._pane_index(index), child, self._pane_options(kw, child)
        )
        self._manage(child)

    def _manage(self, child: Widget) -> None:
        """Take a child on, the way pack and grid take one on.

        A geometry manager does two things beyond deciding where a child
        goes: it records that it is the one managing it, so a second manager
        cannot also claim it, and it maps the child so there is a window to
        draw into. Adding a pane without this laid the panes out correctly
        and drew nothing at all.

        A child pack or grid was laying out leaves it, as in Tk, where the
        manager also reads ``panedwindow``.
        """
        child._leave_for(self, "panedwindow")
        child._manager = "panedwindow"
        child._manager_container = self
        child._map()
        self._invalidate_layout()
        self._redraw()

    def forget(self, child: Widget | None = None) -> None:
        """Take a pane out and unmap its child.

        With no argument this is the ``forget`` every widget has, which stops
        *this* window being managed by its own parent. Tk's PanedWindow has
        the same overloading, for the same reason: both meanings are wanted
        and there is only one name for them.
        """
        if child is None:
            super().forget()
            return
        self._paned.remove(child)
        if child._manager == "panedwindow" and child._manager_container is self:
            child._manager = ""
            child._manager_container = None
        child._unmap()
        self._invalidate_layout()
        self._redraw()

    def remove(self, child: Widget) -> None:
        """Take a pane out, the spelling Tk also accepts."""
        self.forget(child)

    def panes(self) -> list[str]:
        """The panes' widget paths, in order, as Tk reports them."""
        return [child._w for child in self._paned.slaves()]

    def _pane_options(self, given: dict[str, Any], child: Widget) -> PaneOptions:
        """``child``'s pane options with the keywords it was given applied.

        **Only what is given changes.** Measured on Tk 9.0.2, a pane added with
        ``minsize=10, sticky="n"`` keeps its minsize through
        ``paneconfigure(child, sticky="s")``, and a second ``add`` of the same
        child is the same as a ``paneconfigure``. These were built from the
        keywords alone, so every option left out went back to its default -
        TkCurses-z6pp.

        Raises:
            TclError: If an option is not one a pane takes.
        """
        given = _given(None, given)
        allowed = {"minsize", "sticky", "stretch", "width", "height"}
        unknown = set(given) - allowed
        if unknown:
            raise TclError(f'unknown option "-{sorted(unknown)[0]}"')
        options = self._paned.options_for(child) or PaneOptions()
        if "minsize" in given:
            options = replace(options, minsize=int(given["minsize"]))
        if "sticky" in given:
            options = replace(options, sticky=str(given["sticky"]))
        if "stretch" in given:
            stretch = str(given["stretch"])
            if stretch not in STRETCH_VALUES:
                raise TclError(
                    f'bad stretch "{stretch}": must be always, first, last, '
                    "middle, or never"
                )
            options = replace(options, stretch=stretch)
        along = "height" if self._paned.vertical else "width"
        if along in given:
            options = replace(options, size=int(given[along]))
        return options

    def _pane_index(self, index: Any) -> int:
        """Where a pane goes, taking a number, a widget or a widget path."""
        if isinstance(index, int):
            return index
        children = self._paned.slaves()
        for position, child in enumerate(children):
            if child is index or child._w == str(index):
                return position
        return len(children)

    def panecget(self, child: Widget, option: str) -> Any:
        """One option of one pane.

        Raises:
            TclError: If the widget is not a pane here, or the option is not
                one a pane takes.
        """
        options = self._paned.options_for(child)
        if options is None:
            raise TclError(f'not managed by this window: "{child}"')
        if option == "minsize":
            return options.minsize
        if option == "sticky":
            return options.sticky
        if option == "stretch":
            return options.stretch
        if option in ("width", "height"):
            return options.size
        raise TclError(f'unknown option "-{option}"')

    def paneconfigure(
        self, tagOrId: Widget, cnf: dict[str, Any] | str | None = None, **kw: Any
    ) -> Any:
        """Change one pane's options, or read them.

        With no options, every option the pane takes, each as Tk's
        five-tuple ``(name, dbName, dbClass, default, value)``; with one
        option's name, that option's tuple. Options may be given as a
        dictionary, as in tkinter.

        Raises:
            TclError: If the widget is not a pane here, or an option is not
                one a pane takes.

        Differences from tkinter:
            A pane takes ``minsize``, ``sticky``, ``stretch``, ``width`` and
            ``height`` here; Tk's ``after``, ``before``, ``hide``, ``padx``
            and ``pady`` are refused, and not listed when the options are
            read.
        """
        child = tagOrId
        if self._paned.options_for(child) is None:
            raise TclError(f'not managed by this window: "{child}"')
        if isinstance(cnf, str) and not kw:
            return self._pane_entry(child, cnf)
        if cnf is None and not kw:
            return {name: self._pane_entry(child, name) for name in _PANE_DEFAULTS}
        if isinstance(cnf, dict):
            kw = {**cnf, **kw}
        if kw and not _given(None, kw):
            return  # every option None, which tkinter drops
        self._paned.add(child, self._pane_options(kw, child))
        self._invalidate_layout()
        self._redraw()

    paneconfig = paneconfigure

    def _pane_entry(self, child: Widget, name: str) -> tuple[Any, ...]:
        """One pane option as Tk's five-tuple, measured on Tk 9.0.2: only
        ``stretch`` has a database name and class, and ``""`` stands for
        a size never given."""
        if name not in _PANE_DEFAULTS:
            raise TclError(f'unknown option "-{name}"')
        value = self.panecget(child, name)
        database = ("stretch", "Stretch") if name == "stretch" else ("", "")
        return (name, *database, _PANE_DEFAULTS[name], "" if value is None else value)

    # ------------------------------------------------------------------ sashes

    def _sash_index(self, index: Any) -> int:
        """A sash's index, checked as Tk checks it."""
        number = _tcl_integer(None, index)
        if not 0 <= number < max(0, len(self._paned.slaves()) - 1):
            raise TclError("invalid sash index")
        return number

    def sash(self, *args: Any) -> Any:
        """Tk's ``sash`` command: ``coord``, ``dragto``, ``mark`` or
        ``place``, with its arguments, as :meth:`sash_coord`,
        :meth:`sash_mark` and :meth:`sash_place` take them.

        ``sash("mark", index, x, y)`` remembers where a drag starts, and
        ``sash("dragto", index, x, y)`` moves the sash by how far ``(x,
        y)`` is from that mark - from where the sash is now, so two drags
        to the same place move it twice, as in Tk.

        Raises:
            TclError: For an unknown option, the wrong number of arguments,
                or an index that is not a sash, in Tk's words.
        """
        path = str(self)
        if not args:
            raise TclError(f'wrong # args: should be "{path} sash option ?arg ...?"')
        option, rest = str(args[0]), args[1:]
        shapes = {
            "coord": ((1,), "index"),
            "mark": ((1, 3), "index ?x y?"),
            "dragto": ((3,), "index x y"),
            "place": ((3,), "index x y"),
        }
        if option not in shapes:
            raise TclError(
                f'bad option "{option}": must be coord, dragto, mark, or place'
            )
        counts, usage = shapes[option]
        if len(rest) not in counts:
            raise TclError(f'wrong # args: should be "{path} sash {option} {usage}"')
        index = self._sash_index(rest[0])
        if option == "coord":
            return self.sash_coord(index)
        if option == "mark" and len(rest) == 1:
            return self._sash_marks.get(index, (0, 0))
        x, y = _tcl_integer(None, rest[1]), _tcl_integer(None, rest[2])
        if option == "mark":
            self._sash_marks[index] = (x, y)
        elif option == "place":
            self.sash_place(index, x, y)
        else:
            # Tk's PanedWindowSashCommand: the distance from the mark, added
            # to where the sash is; the mark stays where it was.
            mark_x, mark_y = self._sash_marks.get(index, (0, 0))
            at_x, at_y = self.sash_coord(index)
            if self._paned.vertical:
                self.sash_place(index, at_x, at_y + y - mark_y)
            else:
                self.sash_place(index, at_x + x - mark_x, at_y)
        # tkinter's sash() is _getints(...) or (): nothing comes back as ().
        return ()

    def sash_mark(self, index: Any) -> tuple[int, int]:
        """Where the mark for a drag of this sash is, as ``(x, y)``: what
        ``sash("mark", index, x, y)`` last set, ``(0, 0)`` until then.

        Raises:
            TclError: If ``index`` is not a sash, in Tk's words.
        """
        return self.sash("mark", index)  # type: ignore[no-any-return]

    def sash_coord(self, index: int) -> tuple[int, int]:
        """Where a sash begins, in cells relative to this widget.

        Raises:
            TclError: If ``index`` is not a sash, in Tk's words.
        """
        index = self._sash_index(index)
        area = self._content_area()
        offset = self._paned.sash_position(index) + self._sash_inset()
        if self._paned.vertical:
            return (area.x, area.y + offset)
        return (area.x + offset, area.y)

    def sash_place(self, index: int, x: int, y: int) -> tuple[()]:
        """Put a sash at a position, in cells relative to this widget.
        Answers ``()``, as tkinter's does.

        Raises:
            TclError: If ``index`` is not a sash, in Tk's words.
        """
        index = self._sash_index(index)
        x, y = _tcl_integer(None, x), _tcl_integer(None, y)
        area = self._content_area()
        position = (y - area.y) if self._paned.vertical else (x - area.x)
        position -= self._sash_inset()
        self._paned.move_sash(index, position, self._screen_area())
        self._apply_panes()
        return ()

    def identify(self, x: int, y: int) -> tuple[int, str] | str:
        """Which sash is at a position within this widget, if any.

        Returns ``(index, "sash")`` as Tk does, or ``""`` for anywhere that
        is not on one.
        """
        area = self._content_area()
        offset = (y - area.y) if self._paned.vertical else (x - area.x)
        for index in range(max(0, len(self._paned.slaves()) - 1)):
            at = self._paned.sash_position(index)
            # The padding too, measured: with sashpad 5 every pixel from the
            # first pane's edge to the second's answered (0, "sash").
            if at <= offset < at + self._paned.sash:
                return (index, "sash")
        return ""

    def _screen_area(self) -> Rect:
        """The region the panes are laid out in, in screen cells."""
        return self._content_rect()

    def _content_area(self) -> Rect:
        """The region the panes occupy, relative to this widget's window."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        return Rect(
            edge + padx,
            edge + pady,
            max(0, self._rect.width - 2 * (edge + padx)),
            max(0, self._rect.height - 2 * (edge + pady)),
        )

    def _apply_panes(self) -> None:
        """Re-place the panes after a sash moved, without a full relayout.

        A sash drag must not go through the engine: the engine would ask the
        children what they want and undo the drag, which is the whole reason
        the sizes are remembered.

        A classic window's sash pins every pane's size, so it then asks for
        the size those add up to, as Tk's ``ComputeGeometry`` does after a
        sash moves; going through the engine is safe there.
        """
        self._paned.apply(self, self._screen_area())
        for child in self._paned.slaves():
            child._map()
        if self._paned.classic:
            self._invalidate_layout()
        self._redraw()

    def _move_sash_by(self, distance: int) -> None:
        """Nudge the active sash, for the keyboard."""
        index = self._active_sash if self._active_sash is not None else 0
        if index >= max(0, len(self._paned.slaves()) - 1):
            return
        self._active_sash = index
        self._paned.move_sash(
            index, self._paned.sash_position(index) + distance, self._screen_area()
        )
        self._apply_panes()

    # -------------------------------------------------------------- painting

    def _redraw(self) -> None:
        """Paint the background, any border, and the sashes between panes."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        attribute = self._background_attribute() | self._font_attribute()
        area = self._content_area()
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            self._draw_sashes(dispatcher, window, area, attribute)

    def _draw_sashes(
        self, dispatcher: CursesDispatcher, window: Any, area: Rect, attribute: int
    ) -> None:
        """Draw a line down each division, with its handle.

        The line fills ``sashwidth`` cells in the middle of the sash's span.
        The handle starts ``handlepad`` cells along it and is ``handlesize``
        cells long and wide, as Tk draws its square handle, centred across
        the sash. ``sashrelief`` shows as :func:`_part_relief` shows one.
        """
        if area.is_empty:
            return
        kind = "vertical" if self._paned.vertical else "horizontal"
        line, handle = self._SASH[kind], self._HANDLE[kind]
        show = self._showhandle
        pad, core, width = self._sash_parts()
        inset = self._sash_inset()
        size = max(1, _as_int(self._options["handlesize"], 1))
        across = min(size, core)
        handle_at = pad + (core - across) // 2
        along_from = max(0, _as_int(self._options["handlepad"], 0))
        relief = _part_relief(self._options["sashrelief"])
        length = area.width if self._paned.vertical else area.height
        span = area.height if self._paned.vertical else area.width
        for index in range(max(0, len(self._paned.slaves()) - 1)):
            start = self._paned.sash_position(index)
            focused = self.focus_get() is self and index == (self._active_sash or 0)
            style = attribute | relief | (_curses.A_REVERSE if focused else 0)
            for step in range(self._paned.sash):
                offset = start + step
                if not 0 <= offset < span:
                    continue
                drawn = inset <= step < inset + width
                in_handle = show and handle_at <= step < handle_at + across
                for along in range(length):
                    glyph = line if drawn else " "
                    if in_handle and along_from <= along < along_from + size:
                        glyph = handle
                    if self._paned.vertical:
                        row, column = area.y + offset, area.x + along
                    else:
                        row, column = area.y + along, area.x + offset
                    self._write_line(dispatcher, window, row, column, glyph, style)

    # ----------------------------------------------------------------- proxy

    @property
    def _opaque(self) -> bool:
        """True while a drag moves the panes with the pointer."""
        try:
            return self.getboolean(self._options["opaqueresize"])
        except TclError:
            return True

    def _place_proxy(self, x: int, y: int) -> None:
        """Show where the sash being dragged will go, without moving it.

        Tk raises a separate window for this, its proxy, over the panes. The
        panes here are panels above this widget's own, so the proxy is one
        too: a line of the sash's own glyph, the length of the division, in
        ``proxybackground``, with ``proxyrelief`` shown as a sunken part is.
        Its ``proxyborderwidth`` has no edges to draw in a cell.
        """
        area = self._content_area()
        vertical = self._paned.vertical
        _, _, width = self._sash_parts()
        position = (y - area.y) if vertical else (x - area.x)
        span = area.height if vertical else area.width
        position = max(0, min(position, max(0, span - width)))
        self._proxy_at = position
        stack = self.tk.panels
        if stack is None or area.is_empty:
            return
        origin = self._screen_rect()
        if vertical:
            rect = Rect(
                origin.x + area.x, origin.y + area.y + position, area.width, width
            )
        else:
            rect = Rect(
                origin.x + area.x + position, origin.y + area.y, width, area.height
            )
        if self._proxy_panel is None or self._proxy_panel.destroyed:
            self._proxy_panel = stack.new_panel(rect, userptr=self)
        else:
            stack.move(self._proxy_panel, rect.x, rect.y)
        self._draw_proxy(rect)

    def _draw_proxy(self, rect: Rect) -> None:
        window = getattr(self._proxy_panel, "window", None)
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        attribute = self._coloured(
            self._background_attribute(), "", self._options["proxybackground"]
        ) | _part_relief(self._options["proxyrelief"])
        glyph = self._SASH["vertical" if self._paned.vertical else "horizontal"]
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            for row in range(rect.height):
                for column in range(rect.width):
                    self._write_line(dispatcher, window, row, column, glyph, attribute)

    def proxy(self, *args: Any) -> Any:
        """Tk's ``proxy`` command: ``coord``, ``forget`` or ``place``, as
        :meth:`proxy_coord`, :meth:`proxy_forget` and :meth:`proxy_place`.

        Raises:
            TclError: For an unknown option or the wrong number of
                arguments, in Tk's words.
        """
        path = str(self)
        if not args:
            raise TclError(f'wrong # args: should be "{path} proxy option ?arg ...?"')
        option, rest = str(args[0]), args[1:]
        if option not in ("coord", "forget", "place"):
            raise TclError(f'bad option "{option}": must be coord, forget, or place')
        if option == "place":
            if len(rest) != 2:
                raise TclError(f'wrong # args: should be "{path} proxy place x y"')
            self.proxy_place(rest[0], rest[1])
            return ()
        if rest:
            raise TclError(f'wrong # args: should be "{path} proxy {option}"')
        if option == "coord":
            return self.proxy_coord()
        self.proxy_forget()
        return ()

    def proxy_coord(self) -> tuple[int, int]:
        """Where the proxy was last placed, as ``(x, y)`` in cells; still
        answered once it is forgotten, as Tk answers it."""
        return self._proxy_xy

    def proxy_forget(self) -> tuple[()]:
        """Take the proxy down. Answers ``()``, as tkinter's does."""
        self._forget_proxy()
        return ()

    def proxy_place(self, x: Any, y: Any) -> tuple[()]:
        """Show the proxy - the line a sash dragged with ``opaqueresize``
        off leaves where it will go - at ``(x, y)``.

        As in Tk only the position along the panes counts, kept between
        nought and the far side less the sash; the other is the border's.
        Answers ``()``, as tkinter's does.

        Raises:
            TclError: If ``x`` or ``y`` is not an integer, in Tk's words.
        """
        x, y = _tcl_integer(None, x), _tcl_integer(None, y)
        # Tk's PanedWindowProxyCommand.
        edge = BORDER_WIDTH if self._border_drawn else 0
        _, _, width = self._sash_parts()
        if self._paned.vertical:
            y = max(0, min(y, self._rect.height - edge - width))
            x = edge
        else:
            x = max(0, min(x, self._rect.width - edge - width))
            y = edge
        self._proxy_xy = (x, y)
        self._place_proxy(x, y)
        return ()

    def _forget_proxy(self) -> None:
        """Take the proxy down. Safe when there is none."""
        self._proxy_at = None
        panel, self._proxy_panel = self._proxy_panel, None
        if panel is not None and self.tk.panels is not None:
            self.tk.panels.destroy(panel)

    def _destroy_window(self) -> None:
        self._forget_proxy()
        super()._destroy_window()

    @property
    def _showhandle(self) -> bool:
        """True while the sash shows a handle in its middle."""
        try:
            return self.getboolean(self._options["showhandle"])
        except TclError:
            return True


def _paned_refresh(event: Event) -> None:
    """Repaint after the focus moved in or out."""
    event.widget._redraw()


def _paned_press(event: Event) -> None:
    """Take the focus, and start dragging a sash if one was clicked.

    The one widget here that does take the focus on a click, and the one
    with no Tk counterpart to be faithful to: Tk's panedwindow has no
    takefocus option at all and no keyboard bindings, so its sashes are
    mouse-only. Ours can be moved with the arrows, which is the only way to
    resize a pane without a mouse, and the focus has to arrive somehow. It
    costs nothing, because this widget binds neither Space nor Return and
    passes on every key it does not use.
    """
    paned = event.widget
    paned.focus_set()
    # The classic method, by name: a ttk subclass's own identify answers
    # ttk's element names, which this binding cannot act on. TkCurses-d5u.
    found = PanedWindow.identify(paned, event.x, event.y)
    paned._active_sash = found[0] if found else None
    paned._redraw()


def _paned_motion(event: Event) -> None:
    """Move the sash being dragged to the pointer, or its proxy there.

    With ``opaqueresize`` off the panes stay put and a proxy follows the
    pointer, as ``tk::panedwindow::DragSash`` places Tk's.
    """
    paned = event.widget
    if paned._active_sash is None:
        return
    if paned._opaque:
        paned.sash_place(paned._active_sash, event.x, event.y)
    else:
        paned._place_proxy(event.x, event.y)


def _paned_release(event: Event) -> None:
    """Stop dragging, leaving the sash where it was let go.

    A proxy is taken down and the sash moved to it, as
    ``tk::panedwindow::ReleaseSash`` does in Tk's panedwindow.tcl.
    """
    paned = event.widget
    at = paned._proxy_at
    if at is not None and paned._active_sash is not None:
        paned._forget_proxy()
        area = paned._content_area()
        paned.sash_place(paned._active_sash, area.x + at, area.y + at)
    paned._forget_proxy()
    paned._redraw()


def _paned_key(event: Event) -> str | None:
    """Move the active sash with the arrows.

    Along the window's own direction only: the other two arrows would have
    nothing to move, and swallowing them would trap a keyboard user.
    """
    paned = event.widget
    back, forward = ("Up", "Down") if paned._paned.vertical else ("Left", "Right")
    if event.keysym == back:
        paned._move_sash_by(-1)
    elif event.keysym == forward:
        paned._move_sash_by(1)
    elif event.keysym == "Tab" or len(event.keysym) > 1:
        return None
    else:
        return None
    return "break"


def _scrollbar_key_binding(
    action: Callable[[Scrollbar], None],
) -> Callable[[Event], None]:
    """A binding that runs ``action`` on the scrollbar the key reached. None
    of them breaks, as none of scrlbar.tcl's does."""
    return lambda event: action(event.widget)


def _scroll_by(orient: str, amount: int, what: str) -> Callable[[Scrollbar], None]:
    """``tk::ScrollByUnits`` and ``tk::ScrollByPages``: scroll by ``amount``
    units or pages, if the scrollbar has a command and lies along one of the
    orientations ``orient`` names - ``v``, ``h`` or ``hv``."""

    def action(bar: Scrollbar) -> None:
        command = bar._options["command"]
        if command is None or str(bar._options["orient"])[:1] not in orient:
            return
        command("scroll", amount, what)

    return action


def _scroll_to(fraction: float) -> Callable[[Scrollbar], None]:
    """``tk::ScrollToPos``: move the view to one end, either orientation."""

    def action(bar: Scrollbar) -> None:
        command = bar._options["command"]
        if command is not None:
            command("moveto", fraction)

    return action


#: scrlbar.tcl's key bindings, on the navigation virtual events as Tk binds
#: them: the line events scroll a vertical scrollbar, the character and word
#: events a horizontal one, and Prior, Next, Home and End either.
_SCROLLBAR_KEYS: dict[str, Callable[[Scrollbar], None]] = {
    "<<PrevLine>>": _scroll_by("v", -1, "units"),
    "<<NextLine>>": _scroll_by("v", 1, "units"),
    "<<PrevPara>>": _scroll_by("v", -1, "pages"),
    "<<NextPara>>": _scroll_by("v", 1, "pages"),
    "<<PrevChar>>": _scroll_by("h", -1, "units"),
    "<<NextChar>>": _scroll_by("h", 1, "units"),
    "<<PrevWord>>": _scroll_by("h", -1, "pages"),
    "<<NextWord>>": _scroll_by("h", 1, "pages"),
    "<Key-Prior>": _scroll_by("hv", -1, "pages"),
    "<Key-Next>": _scroll_by("hv", 1, "pages"),
    "<<LineStart>>": _scroll_to(0),
    "<<LineEnd>>": _scroll_to(1),
}


class Scrollbar(_Drawable):
    """A scroll control: arrows, a trough, and a thumb showing the view.

    A scrollbar holds no content of its own. It is told where the view is by
    whatever it scrolls, through ``set``, and it tells that thing to move by
    calling its ``command``. Neither end knows anything else about the other,
    which is why any widget with a ``yview`` can be scrolled by one::

        bar = tk.Scrollbar(root, command=listbox.yview)
        listbox.configure(yscrollcommand=bar.set)

    The command is called the way Tk calls it: ``("moveto", fraction)`` when
    the thumb is dragged, and ``("scroll", count, "units" | "pages")`` when an
    arrow or the trough is clicked.

    With the focus, the keys scroll as well: Up and Down by a unit on a
    vertical scrollbar, Left and Right on a horizontal one, a page with
    Control; Prior and Next by a page and Home and End to either end, on
    both.

    Sample output:
        items = tk.Listbox(root, height=5)
        for n in range(20):
            items.insert("end", f"Item {n}")
        bar = tk.Scrollbar(root, command=items.yview)
        items.configure(yscrollcommand=bar.set)
        bar.pack(side="right", fill="y")
        items.pack(side="left")

    Options:
        activerelief: The relief of the part under the mouse.
        command: Called to move the view, as above.
        elementborderwidth: The border of the arrows and the thumb, in Tk.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``background``, ``borderwidth``, ``cursor``,
    ``highlightbackground``, ``highlightcolor``, ``highlightthickness``,
    ``jump``, ``orient``, ``relief``, ``repeatdelay``, ``repeatinterval``,
    ``takefocus``, ``troughcolor``, ``width``.

    Differences from tkinter:
        ``elementborderwidth`` and ``troughcolor`` are kept and read back and
        draw nothing: the arrows and the thumb are single characters.
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.

        Tab passes a scrollbar by unless its ``takefocus`` is true. Tk stops
        on one, because it has key bindings. One that has the focus - clicked,
        or given it with ``focus_set`` - is left by Tab and Shift-Tab for the
        widgets either side of it, as in Tk.

    Sample output (activerelief):
        bar = tk.Scrollbar(root, activerelief="sunken", width=3)
        bar.pack(fill="y", expand=True)
        bar.set(0.2, 0.5)
        bar.activate("slider")
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset(
        {"foreground", "padx", "pady"}
    )

    #: Tk lists its synonyms by database name: ``("bd", "borderWidth")``.
    _synonyms_by_database_name: ClassVar[bool] = True

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "orient": _scrollbar_orient,
        "width": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        # Tk's are real colours; "" draws the scrollbar as it was. See
        # _part_attribute. TkCurses-gm66.4.
        "activebackground": "",
        "troughcolor": "",
        # The active element's relief, which a press sinks, and the width of
        # the arrows' and slider's borders - "" for borderwidth's. A part is
        # one cell, with no edge to draw one on. TkCurses-gm66.5.
        "activerelief": "raised",
        "elementborderwidth": "",
        "command": None,
        # A drag that scrolls only when released, and an arrow or the trough
        # held down scrolling again after repeatdelay, then every
        # repeatinterval; Tk's defaults. TkCurses-gm66.6.
        "jump": 0,
        "orient": "vertical",
        "relief": "sunken",
        "repeatdelay": 300,
        "repeatinterval": 100,
        "takefocus": False,
        "width": 1,
    }

    #: Trough, thumb, and the two arrows, vertical then horizontal.
    _TROUGH = "\u2591"
    _THUMB = "\u2588"
    _ARROWS: ClassVar[dict[str, tuple[str, str]]] = {
        "vertical": ("\u25b2", "\u25bc"),
        "horizontal": ("\u25c4", "\u25ba"),
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``orient``, ``command``, and the standard options.
        """
        self._first = 0.0
        self._last = 1.0
        self._drag_from: tuple[int, int] | None = None
        self._drag_view = (0.0, 1.0)
        self._active_relief: str | None = None
        self._drag_origin = 0.0
        #: The element :meth:`activate` named, or "" for none.
        self._active_element = ""
        #: The activebackground put aside while the pointer is over the bar
        #: under tk_strictMotif, as scrlbar.tcl's Priv(activeBg).
        self._motif_active_background: Any = None
        super().__init__(master, cnf, name=name, **kw)
        self._apply_requested_size()
        self._install_class_bindings()

    def _install_class_bindings(self) -> None:
        """Register the click behaviour for every Scrollbar in this application."""
        # winfo_class() and not the literal: a subclass reporting another name
        # - every ttk widget does - must bind under THAT name or it receives
        # nothing, because binding tags name one class and not a chain.
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Button-1>", _scrollbar_press)
        # The three together are what makes the thumb draggable, and Tk binds
        # exactly these three. The press holds the implicit grab, so a drag
        # that wanders off the bar still arrives here - with coordinates
        # outside it, which is what the arithmetic wants.
        bind(name, "<B1-Motion>", _scrollbar_drag)
        bind(name, "<ButtonRelease-1>", _scrollbar_release)
        if not _is_ttk(self):
            # scrlbar.tcl's hover; ttk's scrollbar shows none.
            bind(name, "<Enter>", _scrollbar_enter)
            bind(name, "<Motion>", _scrollbar_hover)
            bind(name, "<Leave>", _scrollbar_leave)
            # scrlbar.tcl's keys; ttk/scrollbar.tcl binds none.
            for sequence, action in _SCROLLBAR_KEYS.items():
                bind(name, sequence, _scrollbar_key_binding(action))

    @property
    def _vertical(self) -> bool:
        """True if this scrollbar runs up and down."""
        return str(self._options["orient"]) != "horizontal"

    def _apply_requested_size(self) -> None:
        """One cell across, and as long as whatever it is packed beside."""
        thickness = max(1, int(self._options["width"]))
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        if self._vertical:
            self._request_size(thickness + edge, 3 + edge)
        else:
            self._request_size(3 + edge, thickness + edge)

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-measuring and repainting as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if {"width", "orient"} & set(given):
            self._apply_requested_size()
            self._invalidate_layout()
        self._redraw()
        return result

    config = configure

    # ---------------------------------------------------------------- state

    def set(self, first: float, last: float) -> None:
        """Record where the view is, as two fractions of the whole.

        Called by the widget being scrolled, not by the application. Values
        outside 0 to 1 are clamped rather than refused: a widget reporting a
        view slightly past its own end is common enough during editing that
        failing on it would be worse than tidying it up.
        """
        self._first = min(max(float(first), 0.0), 1.0)
        self._last = min(max(float(last), self._first), 1.0)
        self._redraw()

    def get(self) -> tuple[float, float]:
        """Where the view is, as ``(first, last)``."""
        return self._first, self._last

    def activate(self, index: str | None = None) -> str | None:
        """Mark one element active, or ask which one is.

        Only ``arrow1``, ``slider`` and ``arrow2`` can be active. Any other name,
        the trough included, clears it rather than raising, and asking with none
        active answers None. The active element is drawn on
        ``activebackground``, when one is given, and dim while ``activerelief``
        is sunken, which a press makes it. A classic scrollbar activates the
        element under the mouse pointer as it moves, and clears it when the
        pointer leaves - in a terminal asked to report a pointer moving with
        no button held, which ``[mouse] report_hover`` turns on.

        Args:
            index: The element to make active. Omitted, nothing changes.

        Returns:
            The active element's name when asked, None when setting.
        """
        # Measured on Tk 9.0.2. activebackground: TkCurses-gm66.4; activerelief:
        # TkCurses-gm66.5; the hover bindings: TkCurses-mvvv.
        if index is None:
            return self._active_element or None
        self._active_element = index if index in ("arrow1", "slider", "arrow2") else ""
        self._redraw()
        return None

    def fraction(self, x: int, y: int) -> float:
        """The fraction of the way along that a position within this widget is.

        Args:
            x: Column within this widget, as an Event reports it.
            y: Row within this widget.
        """
        area = self._trough_bounds()
        if area <= 0:
            return 0.0
        offset = y if self._vertical else x
        return min(max((offset - self._trough_start()) / area, 0.0), 1.0)

    def delta(self, deltax: int, deltay: int) -> float:
        """What fraction of the whole a movement of this many cells is.

        tkinter's own method, and the one a drag is built on: the distance
        the pointer has travelled since the press converts to a change in
        the view's position, which is added to where the view started.

        Args:
            deltax: Cells moved across.
            deltay: Cells moved down.
        """
        area = self._trough_bounds()
        if area <= 0:
            return 0.0
        return (deltay if self._vertical else deltax) / area

    def identify(self, x: int, y: int) -> str:
        """Which part of the scrollbar is at a position within this widget.

        Args:
            x: Column within this widget, as an Event reports it - not a
                screen column. That is the coordinate Tk's identify takes.
            y: Row within this widget.
        """
        offset = y if self._vertical else x
        start = self._trough_start()
        if offset < start:
            return "arrow1"
        if offset >= start + self._trough_bounds():
            return "arrow2"
        thumb_start, thumb_end = self._thumb_range()
        if thumb_start <= offset - start < thumb_end:
            return "slider"
        return "trough1" if offset - start < thumb_start else "trough2"

    # -------------------------------------------------------------- geometry

    def _length(self) -> int:
        """Cells along the scrollbar's own direction.

        ``_border_drawn`` and not ``_bordered``, which is the whole bug a
        person found in UAT 40: a vertical scrollbar is one cell WIDE, so
        ``_border_drawn`` is False - it needs two cells each way - while
        ``_bordered`` is True, because the relief is not flat. This method took
        two rows off for a border, and ``_redraw`` inset the glyphs by nothing,
        so a scrollbar nine rows tall drew seven cells from the top and left two
        rows that still took clicks and still painted their background. A
        restyle made it obvious: the blue ran two rows past the last glyph.

        ``_border_drawn``'s own docstring says everything measuring the space
        left inside has to agree with the painting. This did not.
        """
        edge = 2 * BORDER_WIDTH if self._border_drawn else 0
        span = self._rect.height if self._vertical else self._rect.width
        return max(0, span - edge)

    def _trough_start(self) -> int:
        """Where the trough begins, after the first arrow."""
        return (BORDER_WIDTH if self._border_drawn else 0) + 1

    def _trough_bounds(self) -> int:
        """Cells of trough, once the two arrows have taken theirs."""
        return max(0, self._length() - 2)

    def _thumb_range(self) -> tuple[int, int]:
        """The thumb's extent within the trough, as ``(start, end)``.

        The thumb is never shorter than one cell: a view onto a very long
        document would otherwise round to nothing and leave the scrollbar
        looking broken.
        """
        trough = self._trough_bounds()
        if trough <= 0:
            return (0, 0)
        start = int(self._first * trough)
        end = max(start + 1, int(self._last * trough))
        return (min(start, trough - 1), min(end, trough))

    # -------------------------------------------------------------- painting

    def _redraw(self) -> None:
        """Paint the arrows, the trough, and the thumb."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        length = self._length()
        if length <= 0:
            return
        dispatcher = CursesDispatcher.get()
        attribute = self._background_attribute()
        first_arrow, last_arrow = self._ARROWS[
            "vertical" if self._vertical else "horizontal"
        ]
        trough = self._trough_bounds()
        thumb_start, thumb_end = self._thumb_range()
        cells = [(first_arrow, self._part_attribute("arrow1", attribute))]
        thumb = self._part_attribute("slider", attribute)
        empty = self._part_attribute("trough", attribute)
        for index in range(trough):
            cells.append(
                (self._THUMB, thumb)
                if thumb_start <= index < thumb_end
                else (self._TROUGH, empty)
            )
        cells.append((last_arrow, self._part_attribute("arrow2", attribute)))

        edge = BORDER_WIDTH if self._border_drawn else 0
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            # A cell at a time, each in its part's colours. One write of the
            # whole row was enough while every part looked the same.
            for offset, (cell, look) in enumerate(cells):
                row, column = (offset, 0) if self._vertical else (0, offset)
                self._write_line(
                    dispatcher, window, edge + row, edge + column, cell, look
                )

    def _part_attribute(self, part: str, attribute: int) -> int:
        """How one part is drawn: ``troughcolor`` behind the trough, and
        ``activebackground`` behind the element ``activate`` names.

        Both "" by default, Tk's being real colours: the scrollbar as it was.
        TkCurses-gm66.4.
        """
        if part == "trough":
            return self._coloured(attribute, "", self._options["troughcolor"])
        if part == self._active_element:
            attribute = self._coloured(attribute, "", self._options["activebackground"])
            return attribute | _part_relief(self._options["activerelief"])
        return attribute


def _scrollbar_press(event: Event) -> None:
    """Scroll by whatever part of the scrollbar was pressed.

    The Scrollbar's mouse bindings follow Tk's ``scrlbar.tcl`` (see
    ARCHITECTURE.md). A press on the thumb moves nothing. Tk remembers where the press landed
    and where the view was, and waits for the pointer to move - measured
    against Tk 9.0, where pressing the slider and releasing it without moving
    calls the command not at all.
    """
    bar = event.widget
    if not _is_ttk(bar):
        # tk::ScrollButtonDown: the active element sinks until the release.
        bar._active_relief = str(bar.cget("activerelief"))
        bar.configure(activerelief=SUNKEN)
    command = bar._options["command"]
    if command is None:
        return
    # The classic method, by name: a ttk subclass's own identify answers
    # ttk's element names, which this binding cannot act on. TkCurses-d5u.
    part = Scrollbar.identify(bar, event.x, event.y)
    if part == "slider":
        bar._drag_from = (event.x, event.y)
        bar._drag_origin = bar._first
        bar._drag_view = (bar._first, bar._last)
        return
    _scrollbar_select(bar, part, "initial")


#: What each part of a scrollbar scrolls by, as ``tk::ScrollSelect`` has it.
_SCROLLBAR_STEPS = {
    "arrow1": (-1, "units"),
    "arrow2": (1, "units"),
    "trough1": (-1, "pages"),
    "trough2": (1, "pages"),
}


def _scrollbar_select(bar: Any, part: str, repeat: str) -> None:
    """Scroll for a pressed part, and keep on while it is held.

    Tk's ``tk::ScrollSelect``: the first step at once, the second after
    ``repeatdelay``, the rest every ``repeatinterval``. The part is the one
    first pressed, so a trough held down goes on paging after the thumb has
    passed the pointer, as Tk's does. An interval of 0 stops the repeat
    rather than scheduling it at once for ever, which Tk would.
    """
    step = _SCROLLBAR_STEPS.get(part)
    command = bar._options["command"]
    if step is None or command is None:
        return
    if _is_ttk(bar):
        # ttk::scrollbar::Press: ttk::Repeatedly Scroll, with ttk's timing.
        _ttk_repeatedly(bar, _ttk_scroll, bar, *step)
        return
    command("scroll", *step)
    wait = _repeat_option(
        bar, "repeatdelay" if repeat == "initial" else "repeatinterval"
    )
    if wait > 0:
        _repeat_after(bar, wait, _scrollbar_select, bar, part, "again")


def _ttk_scroll(bar: Any, amount: int, what: str) -> None:
    """``ttk::scrollbar::Scroll``: the command as it is now, if there is one."""
    command = bar._options["command"]
    if command is not None:
        command("scroll", amount, what)


def _scrollbar_drag(event: Event) -> None:
    """Move the view by however far the thumb has been dragged.

    The view follows the pointer rather than jumping to it: the offset within
    the thumb where the press landed is preserved, because what moves is the
    *distance* travelled rather than the position arrived at.
    """
    bar = event.widget
    origin = bar._drag_from
    command = bar._options["command"]
    if origin is None or command is None:
        return
    moved = bar.delta(event.x - origin[0], event.y - origin[1])
    if _jumps(bar):
        # tk::ScrollDrag with -jump: the thumb moves and the view waits.
        first, last = bar._drag_view
        bar.set(first + moved, last + moved)
        return
    command("moveto", min(max(bar._drag_origin + moved, 0.0), 1.0))


def _jumps(bar: Any) -> bool:
    """True if a classic scrollbar's ``jump`` holds the scroll for the release."""
    if _is_ttk(bar):
        return False
    try:
        return bool(bar.getboolean(bar._options["jump"]))
    except TclError:
        return False


def _scrollbar_release(event: Event) -> None:
    """End a press: the repeat stops, and a jump drag scrolls at last.

    ``tk::ScrollButtonUp``, which puts back the relief the press sank, and
    ``tk::ScrollEndDrag``, which scrolls to where a ``jump`` drag ended.
    Without ``jump`` the drag has scrolled already and nothing more is done.
    """
    bar = event.widget
    _cancel_repeat(bar)
    origin, bar._drag_from = bar._drag_from, None
    command = bar._options["command"]
    if origin is not None and command is not None and _jumps(bar):
        moved = bar.delta(event.x - origin[0], event.y - origin[1])
        command("moveto", min(max(bar._drag_origin + moved, 0.0), 1.0))
    relief = bar._active_relief
    if relief is not None:
        bar._active_relief = None
        bar.configure(activerelief=relief)
        # tk::ScrollButtonUp: the part under the pointer now.
        bar.activate(Scrollbar.identify(bar, event.x, event.y))


def _scrollbar_enter(event: Event) -> None:
    """scrlbar.tcl's ``<Enter>``: the part under the pointer goes active.

    Under ``tk_strictMotif`` the active part is drawn in the ordinary
    background, as Motif draws it: ``activebackground`` is put aside until
    the pointer leaves. Nothing happens while a press on the bar is held -
    scrlbar.tcl's empty ``<B1-Enter>``.
    """
    bar = event.widget
    if bar._active_relief is not None:
        return
    if bar.tk.strict_motif:
        bar._motif_active_background = bar.cget("activebackground")
        bar.configure(activebackground=bar.cget("background"))
    _scrollbar_hover(event)


def _scrollbar_hover(event: Event) -> None:
    """scrlbar.tcl's ``<Motion>``: ``%W activate [%W identify %x %y]``. A
    drag is ``<B1-Motion>``'s, so a held press does not change it."""
    bar = event.widget
    if bar._active_relief is None:
        bar.activate(Scrollbar.identify(bar, event.x, event.y))


def _scrollbar_leave(event: Event) -> None:
    """scrlbar.tcl's ``<Leave>``: nothing is active, and a background put
    aside under ``tk_strictMotif`` comes back. Not while a press is held -
    its empty ``<B1-Leave>``."""
    bar = event.widget
    if bar._active_relief is not None:
        return
    saved, bar._motif_active_background = bar._motif_active_background, None
    if saved is not None:
        bar.configure(activebackground=saved)
    bar.activate("")


class Scale(_Drawable):
    """A number chosen by sliding a handle along a trough.

    The value is the widget's own, so ``get`` and ``set`` work with no
    variable at all; a ``variable`` makes it visible to other widgets, and
    the two are kept in step both ways. Every arrow key moves the slider by
    ``resolution`` - Up and Left towards ``from``, Down and Right towards
    ``to``, whichever way the scale lies - Control with one by
    ``bigincrement``, and Home and End to the two ends.

    Focus is shown by caps at the ends of the trough, ``[`` and ``]``. Room
    for them is kept whether or not they are showing, so nothing moves when
    the focus arrives.

    Sample output:
        volume = tk.Scale(root, from_=0, to=10, orient="horizontal")
        volume.set(7)
        volume.pack()

    Options:
        bigincrement: The large step, taken with Control and an arrow; 0 is a
            tenth of the range.
        command: Called with the new value, as a string, when it changes.
        digits: How many significant digits the value is shown with; 0 picks
            enough for ``resolution``.
        from: The value at the left of a horizontal scale and at the top of a
            vertical one. Given as ``from_``, ``from`` being a Python keyword.
        label: Text shown beside the scale.
        length: How long the scale is, in cells.
        resolution: The step the value snaps to, measured from ``from``.
        showvalue: Whether the value is shown beside the slider.
        sliderlength: How long the slider is, in cells.
        sliderrelief: The relief of the slider.
        tickinterval: How far apart the numbers along the scale are; 0 shows
            none.
        to: The value at the other end. Below ``from``, the scale runs
            backwards.
        variable: A variable holding the value.

    Standard options, described in :doc:`/reference/options`:
    ``activebackground``, ``background``, ``borderwidth``, ``cursor``,
    ``font``, ``foreground``, ``highlightbackground``, ``highlightcolor``,
    ``highlightthickness``, ``orient``, ``relief``, ``repeatdelay``,
    ``repeatinterval``, ``state``, ``takefocus``, ``troughcolor``,
    ``width``.

    Differences from tkinter:
        ``highlightbackground``, ``highlightcolor`` and ``highlightthickness``
        are accepted and draw nothing: the focus is shown by markers instead. So
        is ``cursor``: the mouse pointer belongs to the terminal.

    Sample output (from, to):
        tk.Scale(root, from_=100, to=0, orient="horizontal").pack()

    Sample output (label):
        tk.Scale(root, label="Volume", from_=0, to=10,
                 orient="horizontal").pack()

    Sample output (length, sliderlength):
        tk.Scale(root, from_=0, to=10, orient="horizontal", length=30,
                 sliderlength=4).pack()

    Sample output (resolution, showvalue):
        for show in (1, 0):
            scale = tk.Scale(root, from_=0, to=1, resolution=0.25,
                             showvalue=show, orient="horizontal")
            scale.set(0.75)
            scale.pack(pady=(0, 1))

    Sample output (sliderrelief):
        tk.Scale(root, from_=0, to=10, orient="horizontal",
                 sliderrelief="sunken").pack()

    Sample output (tickinterval):
        # size: 40x8
        tk.Scale(root, from_=0, to=10, tickinterval=5, length=30,
                 orient="horizontal").pack()
    """

    #: Measured on Tk 9.0.2: not options of Tk's widget.
    _not_tk_options: ClassVar[frozenset[str]] = frozenset({"padx", "pady"})

    #: Trough and handle, the same two glyphs a Scrollbar uses, because they
    #: are the same two things.
    _TROUGH = "░"
    _SLIDER = "█"

    #: Drawn at the ends of the trough while the scale has the focus.
    _FOCUS_CAPS = ("[", "]")

    _value_checks: ClassVar[dict[str, Callable[[Any, Any], Any]]] = {
        "digits": _tcl_integer,
        "from": _tcl_float,
        "length": _signed_distance,
        "resolution": _tcl_float,
        "tickinterval": _tcl_float,
        "to": _tcl_float,
        "width": _signed_distance,
    }

    _widget_options: ClassVar[dict[str, Any]] = {
        "borderwidth": 1,  # Tk's default
        "highlightthickness": 1,  # Tk's default; see Widget._widget_options
        # The handle while active or dragged, and the trough. Tk's are real
        # colours; "" draws the scale as it was. TkCurses-gm66.4.
        "activebackground": "",
        "troughcolor": "",
        "bigincrement": 0,
        "command": None,
        "digits": 0,
        "font": "",
        "from": 0.0,
        "label": "",
        "length": 20,
        "orient": "vertical",
        "resolution": 1.0,
        "showvalue": True,
        # The handle's length in cells, along the trough, and its relief,
        # which the press sinks while it is dragged. Tk's length is 30
        # pixels; one cell is the handle as it was. TkCurses-gm66.5.
        "sliderlength": 1,
        "sliderrelief": "raised",
        # A trough held down steps again after repeatdelay, then every
        # repeatinterval; Tk's defaults. TkCurses-gm66.6.
        "repeatdelay": 300,
        "repeatinterval": 100,
        "state": "normal",
        "takefocus": True,
        "tickinterval": 0,
        "to": 100.0,
        "variable": None,
        "width": 1,
    }

    def __init__(
        self,
        master: Misc | None = None,
        cnf: dict[str, Any] | None = None,
        *,
        name: str | None = None,
        **kw: Any,
    ) -> None:
        """
        Args:
            master: Parent widget; the implicit root when omitted.
            cnf: Options as a dictionary, merged with the keywords.
            name: Path component, generated when omitted.
            **kw: ``from_``, ``to``, ``resolution``, ``orient``, ``length``,
                ``width``, ``label``, ``showvalue``, ``tickinterval``,
                ``variable``, ``command``, ``digits``, ``bigincrement``,
                ``state``, and the standard options.
        """
        self._dragging = False
        #: Cells from the handle's middle to where it was taken hold of:
        #: Tk's Priv(deltaX), so a drag does not jump the handle.
        self._drag_lead = 0
        self._slider_relief: str | None = None
        self._syncing = False
        self._variable_trace: tuple[Variable, str] | None = None
        super().__init__(master, cnf, name=name, **kw)
        self._value = self._snap(self._range()[0])
        self._follow_variable()
        self._apply_requested_size()
        self._install_class_bindings()

    # ------------------------------------------------------------- bindings

    def _install_class_bindings(self) -> None:
        """Register the default behaviour for every Scale in this application.

        Under ``winfo_class()`` rather than the literal ``"Scale"``: binding
        tags name one class, so ``ttk.Scale`` - which reports ``TScale`` -
        would otherwise match none of these and answer no gesture at all.
        The same cure Menubutton carries for OptionMenu.
        """
        name = self.winfo_class()
        if name in self.tk.bound_classes:
            return
        self.tk.bound_classes.add(name)
        bind = self.bind_class
        bind(name, "<Button-1>", _scale_press)
        bind(name, "<Button-2>", _scale_jump)
        bind(name, "<ButtonRelease-2>", _scale_release)
        if _is_ttk(self):
            # ttk/scale.tcl binds button 3 as it does button 2.
            bind(name, "<Button-3>", _scale_jump)
            bind(name, "<ButtonRelease-3>", _scale_release)
        # A drag arrives as Motion: curses reports motion-with-a-button, and
        # there is no Button1 modifier to match a <B1-Motion> against. The
        # press holds the implicit grab, so every one of these belongs to
        # this scale however far the pointer has wandered.
        bind(name, "<Motion>", _scale_motion)
        bind(name, "<ButtonRelease-1>", _scale_release)
        for sequence, (direction, big) in _SCALE_KEYS.items():
            bind(name, sequence, _scale_key_binding(direction, big))
        bind(name, "<<LineStart>>", _scale_to_end("from"))
        bind(name, "<<LineEnd>>", _scale_to_end("to"))
        bind(name, "<FocusIn>", _scale_refresh)
        bind(name, "<FocusOut>", _scale_refresh)

    # --------------------------------------------------------------- options

    def configure(self, cnf: dict[str, Any] | None = None, **kw: Any) -> Any:
        """Set options, re-measuring and repainting as the change requires."""
        given = _given(cnf, kw)
        result = super().configure(cnf, **kw)
        if not given:
            return result
        if "variable" in given:
            self._follow_variable()
        if {"from", "to", "resolution"} & set(given):
            # The value may no longer be reachable: a range that moved under
            # it has to pull it back rather than leave the handle off the end.
            self.set(self._value)
        self._apply_requested_size()
        self._invalidate_layout()
        self._redraw()
        return result

    config = configure

    @property
    def _vertical(self) -> bool:
        """True if this scale runs up and down."""
        return str(self._options["orient"]) != "horizontal"

    def _range(self) -> tuple[float, float]:
        """The two ends, in the order the options name them."""
        return float(self._options["from"]), float(self._options["to"])

    def _thickness(self) -> int:
        """Cells across the trough, at right angles to its length."""
        return max(1, int(self._options["width"]))

    @property
    def _showvalue(self) -> bool:
        """True while the current value is drawn beside the handle."""
        try:
            return self.getboolean(self._options["showvalue"])
        except TclError:
            return True

    # ----------------------------------------------------------- the variable

    def _follow_variable(self) -> None:
        """Track the ``variable``, dropping any previous one."""
        if self._variable_trace is not None:
            previous, handle = self._variable_trace
            previous._unwatch(handle)
            self._variable_trace = None
        variable = self._options["variable"]
        if variable is None:
            return
        _seed_variable(self, variable, self._format(self._value))
        handle = variable._watch(self._variable_changed)
        self._variable_trace = (variable, handle)
        self._variable_changed()

    def _variable_changed(self) -> None:
        """Take the variable's value, unless this scale is what changed it.

        Without the guard the two chase each other: the scale writes the
        variable, whose trace writes the scale, which snaps and writes back.
        """
        if self._syncing:
            return
        variable = self._options["variable"]
        if variable is None:
            return
        with contextlib.suppress(TclError, TypeError, ValueError):
            self.set(float(variable.get()))

    def _publish(self) -> None:
        """Write the value back to the variable, if there is one."""
        variable = self._options["variable"]
        if variable is None:
            return
        self._syncing = True
        try:
            # As text, which is how Tcl holds it: writing the float 6.0 into
            # an IntVar leaves it holding something it cannot read back.
            variable.set(self._format(self._value))
        finally:
            self._syncing = False

    # ---------------------------------------------------------------- value

    def get(self) -> float:
        """The value the handle is on."""
        return self._value

    def set(self, value: float) -> None:
        """Move the handle to ``value``, snapped to the resolution and clamped.

        Calls the ``command`` only when the value actually changes, which is
        what Tk does and what keeps a drag along one cell from firing it on
        every motion event.
        """
        snapped = self._snap(float(value))
        changed = snapped != self._value
        self._value = snapped
        self._publish()
        self._redraw()
        if changed:
            command = self._options["command"]
            if command is not None:
                command(self._format(snapped))

    def _snap(self, value: float) -> float:
        """Round to the nearest step and pull inside the two ends.

        Steps are measured from ``from_``, as Tk measures them, so a scale
        from 1 to 10 by 2 offers 1, 3, 5 and not 2, 4, 6.
        """
        low, high = self._range()
        resolution = float(self._options["resolution"])
        if resolution > 0:
            value = low + round((value - low) / resolution) * resolution
            # round() leaves floating-point dust on anything but integers;
            # a scale showing 0.30000000000000004 is a scale nobody trusts.
            value = round(value, 10)
        return min(max(value, min(low, high)), max(low, high))

    def _format(self, value: float) -> str:
        """The value as text, with as many decimals as it actually has.

        ``digits`` wins when it is set, as it does in Tk; otherwise the
        resolution says how precise the value can be, and showing more than
        that is noise.
        """
        digits = int(self._options["digits"])
        if digits > 0:
            return f"{value:.{digits}g}"
        resolution = abs(float(self._options["resolution"]))
        if resolution == 0 or resolution != int(resolution):
            text = f"{value:.4f}".rstrip("0").rstrip(".")
            return text or "0"
        return str(round(value))

    # -------------------------------------------------------------- geometry

    def _content_area(self) -> Rect:
        """What is left of the widget after its border and padding."""
        edge = BORDER_WIDTH if self._border_drawn else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        return Rect(
            edge + padx,
            edge + pady,
            max(0, self._rect.width - 2 * (edge + padx)),
            max(0, self._rect.height - 2 * (edge + pady)),
        )

    def _value_width(self) -> int:
        """Cells the widest value this scale can show would need.

        The two ends are not enough. A scale from 0 to 1 by 0.1 reads "0"
        and "1" at its ends and "0.5" everywhere between, so measuring the
        ends alone reserves one cell and leaves the value nowhere to go -
        which on a vertical scale means it is simply not drawn.
        """
        low, high = self._range()
        resolution = abs(float(self._options["resolution"]))
        candidates = [low, high]
        if resolution:
            candidates += [self._snap(low + resolution), self._snap(high - resolution)]
        return max(len(self._format(value)) for value in candidates)

    def _head_rows(self) -> int:
        """Rows above the trough, for the label and - horizontally - the value."""
        if self._vertical:
            return 1 if str(self._options["label"]) else 0
        return 1 if str(self._options["label"]) or self._showvalue else 0

    def _tick_span(self) -> int:
        """Room the tick numbers need: a row below, or a column to the left."""
        if not float(self._options["tickinterval"]):
            return 0
        return 1 if not self._vertical else self._value_width() + 1

    def _trough_span(self) -> int:
        """Cells of trough available, after the caps have taken theirs."""
        area = self._content_area()
        if self._vertical:
            return max(0, area.height - self._head_rows() - 2)
        return max(0, area.width - 2)

    def _apply_requested_size(self) -> None:
        """Ask for the trough plus whatever is drawn around it."""
        edge = 2 * BORDER_WIDTH if self._bordered else 0
        padx, pady = int(self._options["padx"]), int(self._options["pady"])
        length = max(1, int(self._options["length"]))
        label = cells(str(self._options["label"]))
        if self._vertical:
            across = self._thickness() + self._tick_span()
            if self._showvalue:
                across += self._value_width() + 1
            width = max(across, label)
            height = length + 2 + self._head_rows()
        else:
            width = max(length + 2, label + self._value_width() + 1)
            height = self._thickness() + self._head_rows() + self._tick_span()
        self._request_size(width + 2 * padx + edge, height + 2 * pady + edge)

    def _trough_origin(self) -> tuple[int, int]:
        """Where the first cell of the trough sits within the widget."""
        area = self._content_area()
        if self._vertical:
            across = self._tick_span()
            if self._showvalue:
                across += self._value_width() + 1
            return (area.x + across, area.y + self._head_rows() + 1)
        return (area.x + 1, area.y + self._head_rows())

    def _slider_cells(self) -> int:
        """How many cells the handle covers: ``sliderlength``, within the trough.

        Never less than one, which Tk also keeps a negative length from going
        below, and never more than the trough has.
        """
        length = _as_int(self._options["sliderlength"], 1)
        return max(1, min(length, self._trough_span()))

    def _slider_lead(self) -> int:
        """Cells of handle before its middle one, the cell a value is at."""
        return (self._slider_cells() - 1) // 2

    def _positions(self) -> int:
        """How many places the handle can stand: the trough less its length.

        Tk's arithmetic, in cells: the slider's middle travels the trough's
        length less the slider's, so a long handle still reaches both ends.
        """
        return max(1, self._trough_span() - self._slider_cells() + 1)

    def _offset_for(self, value: float) -> int:
        """Which trough cell a value falls on: the handle's middle cell there."""
        positions = self._positions()
        low, high = self._range()
        if positions <= 1 or high == low:
            return self._slider_lead()
        fraction = (value - low) / (high - low)
        start = min(max(round(fraction * (positions - 1)), 0), positions - 1)
        return start + self._slider_lead()

    def _value_at(self, offset: int) -> float:
        """The value whose handle has its middle at a trough cell."""
        positions = self._positions()
        low, high = self._range()
        if positions <= 1:
            return self._snap(low)
        start = offset - self._slider_lead()
        fraction = min(max(start, 0), positions - 1) / (positions - 1)
        return self._snap(low + fraction * (high - low))

    def _on_slider(self, offset: int) -> bool:
        """True if a trough cell is one the handle covers."""
        start = self._offset_for(self._value) - self._slider_lead()
        return start <= offset < start + self._slider_cells()

    def coords(self, value: float | None = None) -> tuple[int, int]:
        """Where the handle for a value sits, relative to this widget.

        Args:
            value: The value to locate. The current one when omitted.
        """
        if value is None:
            value = self._value
        x, y = self._trough_origin()
        offset = self._offset_for(self._snap(float(value)))
        return (x, y + offset) if self._vertical else (x + offset, y)

    def identify(self, x: int, y: int) -> str:
        """Which part of the scale is at a screen position.

        Args:
            x: Column within this widget, as an Event reports it - not a
                screen column. That is the coordinate Tk's identify takes.
            y: Row within this widget.

        Returns:
            ``"slider"``, ``"trough1"`` for the side towards ``from_``,
            ``"trough2"`` for the side towards ``to``, or ``""`` for anywhere
            else on the widget - the label, the ticks, or the caps.
        """
        origin_x, origin_y = self._trough_origin()
        offset = (y - origin_y) if self._vertical else (x - origin_x)
        if not 0 <= offset < self._trough_span():
            return ""
        if self._on_slider(offset):
            return "slider"
        return "trough1" if offset < self._offset_for(self._value) else "trough2"

    # -------------------------------------------------------------- painting

    def _redraw(self) -> None:
        """Paint the label, the value, the trough and its handle, and the ticks."""
        window = self._window
        if window is None or self.tk.screen is None:
            return
        dispatcher = CursesDispatcher.get()
        attribute = self._background_attribute() | self._font_attribute()
        # Tk shows an active scale by its handle, in activebackground. Given
        # one, that is how it is shown here too, instead of reversed whole.
        if not (self._active_handle() and self._handle_coloured()):
            attribute = self._in_state(attribute)
        with contextlib.suppress(_curses.error):
            dispatcher.call(window.bkgd, " ", attribute)
            dispatcher.call(window.erase)
            if self._border_drawn:
                self._draw_border(
                    dispatcher, window, self._rect.width, self._rect.height, attribute
                )
            self._draw_head(dispatcher, window, attribute)
            self._draw_trough(dispatcher, window, attribute)
            self._draw_ticks(dispatcher, window, attribute)

    def _draw_head(
        self, dispatcher: CursesDispatcher, window: Any, attribute: int
    ) -> None:
        """The label, and the value where the orientation puts it.

        Horizontally the value rides above the handle, as Tk's does, so it
        reads as belonging to the handle rather than to the widget. There is
        no room for that vertically, so it goes in its own column beside the
        handle's row instead.
        """
        area = self._content_area()
        label = str(self._options["label"])
        if label and area.width > 0:
            self._write_line(
                dispatcher,
                window,
                area.y,
                area.x,
                clip_text(label, area.width),
                attribute,
            )
        if not self._showvalue:
            return
        text = self._format(self._value)
        origin_x, origin_y = self._trough_origin()
        if self._vertical:
            column = origin_x - len(text) - 1
            row = origin_y + self._offset_for(self._value)
        else:
            column = origin_x + self._offset_for(self._value)
            row = origin_y - 1
            column = min(column, area.x + area.width - len(text))
            # The label shares this row, so the value is pushed clear of it
            # rather than written through it - "V0lume" is not a label.
            if label:
                column = max(column, area.x + cells(label) + 1)
        if row < area.y or column < area.x:
            return
        self._write_line(
            dispatcher, window, row, column, clip_text(text, area.width), attribute
        )

    def _draw_trough(
        self, dispatcher: CursesDispatcher, window: Any, attribute: int
    ) -> None:
        """The trough, the handle on it, and the focus caps at its ends."""
        span = self._trough_span()
        if span <= 0:
            return
        origin_x, origin_y = self._trough_origin()
        empty = self._coloured(attribute, "", self._options["troughcolor"])
        held = attribute
        if self._active_handle() and self._handle_coloured():
            held = self._coloured(attribute, "", self._options["activebackground"])
        held |= _part_relief(self._options["sliderrelief"])
        cells = [
            (self._SLIDER, held) if self._on_slider(offset) else (self._TROUGH, empty)
            for offset in range(span)
        ]
        focused = self.focus_get() is self
        left, right = self._FOCUS_CAPS if focused else (" ", " ")
        if self._vertical:
            self._write_line(
                dispatcher, window, origin_y - 1, origin_x, left, attribute
            )
            for thick in range(self._thickness()):
                for offset, (cell, look) in enumerate(cells):
                    self._write_line(
                        dispatcher,
                        window,
                        origin_y + offset,
                        origin_x + thick,
                        cell,
                        look,
                    )
            self._write_line(
                dispatcher, window, origin_y + span, origin_x, right, attribute
            )
        else:
            for thick in range(self._thickness()):
                self._write_line(
                    dispatcher, window, origin_y + thick, origin_x - 1, left, attribute
                )
                for offset, (cell, look) in enumerate(cells):
                    self._write_line(
                        dispatcher,
                        window,
                        origin_y + thick,
                        origin_x + offset,
                        cell,
                        look,
                    )
                self._write_line(
                    dispatcher,
                    window,
                    origin_y + thick,
                    origin_x + span,
                    right,
                    attribute,
                )

    def _active_handle(self) -> bool:
        """True while the handle is active: the state says so, or it is held.

        Tk's ``tk::ScaleActivate``, in ``scale.tcl``, makes the scale active
        while the pointer is over its handle, which it is for the whole of a
        drag. Here there is no hover, so only the drag is seen.
        """
        return str(self._options["state"]) == "active" or self._dragging

    def _handle_coloured(self) -> bool:
        """True if ``activebackground`` is given and the terminal can show it."""
        return bool(self._options["activebackground"]) and self.tk.colors is not None

    def _draw_ticks(
        self, dispatcher: CursesDispatcher, window: Any, attribute: int
    ) -> None:
        """Numbers at every ``tickinterval`` along the trough.

        Drawn only where they fit without overwriting the tick before them,
        so a long range on a short trough thins out rather than turning into
        a row of collided digits.
        """
        interval = abs(float(self._options["tickinterval"]))
        if not interval:
            return
        span = self._trough_span()
        if span <= 0:
            return
        area = self._content_area()
        origin_x, origin_y = self._trough_origin()
        low, high = self._range()
        step = interval if high >= low else -interval
        taken = -1
        value = low
        for _ in range(1000):
            if (step > 0 and value > high) or (step < 0 and value < high):
                break
            text = self._format(value)
            offset = self._offset_for(value)
            if self._vertical:
                row, column = origin_y + offset, area.x
                if row > taken:
                    self._write_line(
                        dispatcher,
                        window,
                        row,
                        column + self._value_width() - len(text),
                        text,
                        attribute,
                    )
                    taken = row
            else:
                row = origin_y + self._thickness()
                column = min(origin_x + offset, area.x + area.width - len(text))
                if column > taken:
                    self._write_line(dispatcher, window, row, column, text, attribute)
                    taken = column + len(text)
            value += step


def _scale_press(event: Event) -> None:
    """Take hold of the handle, or step towards a click on the trough.

    Tk's ``tk::ScaleButtonDown``: the trough steps one ``resolution`` at a
    time, and again while it is held (``tk::ScaleIncrement``); only the
    handle drags, from where it was taken hold of. Button 2 jumps the handle
    to the pointer instead (``_scale_jump``). A ttk scale follows
    ``ttk::scale::Press``: the trough steps 1 towards the pointer, again
    while held, and the slider drags centred on the pointer.

    The focus stays where it was, as it does in Tk: the arrows move a scale
    that has the focus, and a click is already a way of setting the value.
    """
    scale = event.widget
    if scale._disabled:
        return
    x = event.x_root - scale.winfo_rootx()
    y = event.y_root - scale.winfo_rooty()
    if _is_ttk(scale):
        _ttk_scale_press(scale, x, y)
        return
    part = Scale.identify(scale, x, y)
    if part == "slider":
        scale._dragging = True
        scale._drag_lead = _scale_offset(scale, event) - scale._offset_for(scale._value)
        _scale_sink(scale)
    elif part == "trough1":
        _scale_increment(scale, "up", "initial")
    elif part == "trough2":
        _scale_increment(scale, "down", "initial")


def _ttk_scale_press(scale: Any, x: int, y: int) -> None:
    """``ttk::scale::Press``. On the trough, ``ttk::Repeatedly Increment``
    by 1 towards the value under the pointer - the direction settled at the
    press; on the slider, a drag that keeps the slider centred on the
    pointer, as ``ttk::scale::Drag`` sets ``[$w get $x $y]``."""
    if scale.instate(["disabled"]):
        return
    part = scale._element_at(x, y)
    if part == "trough":
        low, high = scale._range()
        down = (scale.get(x, y) <= scale.get()) != (low > high)
        _ttk_repeatedly(scale, _scale_key_step, scale, -1 if down else 1, False)
    elif part == "slider":
        scale._dragging = True
        scale._drag_lead = 0


def _scale_jump(event: Event) -> None:
    """Put the handle under the pointer and drag it from there.

    Tk's ``tk::ScaleButton2Down``, on button 2, which is how a classic scale
    is set by a click in Tk; ttk's ``ttk::scale::Jump`` does the same.
    """
    scale = event.widget
    if scale._disabled:
        return
    scale._dragging = True
    scale._drag_lead = 0
    _scale_move_to(scale, event)


def _scale_increment(scale: Scale, direction: str, repeat: str) -> None:
    """Step the value one ``resolution``, and keep stepping while held.

    Tk's ``tk::ScaleIncrement``, with ``little`` steps: ``up`` is towards
    ``from_``, whichever end that is. The second step comes after
    ``repeatdelay`` and the rest every ``repeatinterval``; an interval of 0
    stops the repeat rather than spinning, which Tk's would. Tk's catching up
    after a slow ``command`` is not done: the after-queue here waits for the
    command to finish before it counts.
    """
    step = abs(float(scale._options["resolution"]))
    backwards = float(scale._options["from"]) > float(scale._options["to"])
    if backwards != (direction == "up"):
        step = -step
    scale.set(scale.get() + step)
    wait = _repeat_option(
        scale, "repeatdelay" if repeat == "initial" else "repeatinterval"
    )
    if wait > 0:
        _repeat_after(scale, wait, _scale_increment, scale, direction, "again")


def _scale_sink(scale: Scale) -> None:
    """Sink the handle while it is held, as Tk's ``tk::ScaleButtonDown`` does:
    raised becomes sunken and ridge groove, the rest stay as they are."""
    relief = str(scale.cget("sliderrelief"))
    scale._slider_relief = relief
    held = {RAISED: SUNKEN, RIDGE: GROOVE}.get(relief)
    if held is not None:
        scale.configure(sliderrelief=held)


def _scale_motion(event: Event) -> None:
    """Follow the pointer while the handle is being dragged: ``tk::ScaleDrag``."""
    scale = event.widget
    if scale._dragging and not scale._disabled:
        scale.set(scale._value_at(_scale_offset(scale, event) - scale._drag_lead))


def _scale_release(event: Event) -> None:
    """Stop repeating and dragging, wherever the pointer ended up, and put the
    relief back as ``tk::CancelRepeat`` and ``tk::ScaleEndDrag`` do."""
    scale = event.widget
    _cancel_repeat(scale)
    scale._dragging = False
    relief = scale._slider_relief
    if relief is not None:
        scale._slider_relief = None
        scale.configure(sliderrelief=relief)


def _scale_move_to(scale: Scale, event: Event) -> None:
    """Set the value from a pointer position on the trough."""
    scale.set(scale._value_at(_scale_offset(scale, event)))


def _scale_offset(scale: Scale, event: Event) -> int:
    """Which trough cell the pointer is level with."""
    origin_x, origin_y = scale._trough_origin()
    if scale._vertical:
        return event.y_root - scale.winfo_rooty() - origin_y
    return event.x_root - scale.winfo_rootx() - origin_x


#: The navigation events scale.tcl and ttk/scale.tcl bind, each with the
#: direction it steps (-1 towards ``from``) and whether it is a big step.
#: Both arrows of a pair step the same way, whatever the orientation.
_SCALE_KEYS: dict[str, tuple[int, bool]] = {
    "<<PrevLine>>": (-1, False),
    "<<NextLine>>": (1, False),
    "<<PrevChar>>": (-1, False),
    "<<NextChar>>": (1, False),
    "<<PrevPara>>": (-1, True),
    "<<NextPara>>": (1, True),
    "<<PrevWord>>": (-1, True),
    "<<NextWord>>": (1, True),
}


def _scale_key_binding(direction: int, big: bool) -> Callable[[Event], None]:
    """A binding that steps the scale the key reached. None of them breaks,
    as none of the scripts' does, so the key goes on to the toplevel's
    bindings and ``all``'s."""
    return lambda event: _scale_key_step(event.widget, direction, big)


def _scale_key_step(scale: Scale, direction: int, big: bool) -> None:
    """Step the scale once from the keyboard.

    The classic scale follows ``tk::ScaleIncrement`` with ``noRepeat``: a
    step of ``resolution``, or for a big one ``bigincrement`` - a tenth of
    the range when that is 0 - and never less than ``resolution``. A themed
    one follows ``ttk::scale::Increment``, stepping 1 or 10. Either way the
    step is towards ``to`` for a positive ``direction``, whichever end that
    is. A disabled scale does not move.
    """
    themed: Any = scale
    if scale._disabled or (_is_ttk(scale) and themed.instate(["disabled"])):
        return
    low, high = scale._range()
    if _is_ttk(scale):
        step = 10.0 if big else 1.0
    else:
        resolution = float(scale._options["resolution"])
        step = resolution
        if big:
            step = float(scale._options["bigincrement"]) or abs(high - low) / 10.0
            step = max(step, resolution)
    step = abs(step) if (direction > 0) == (low <= high) else -abs(step)
    scale.set(scale._value + step)


def _scale_to_end(option: str) -> Callable[[Event], None]:
    """``<<LineStart>>`` and ``<<LineEnd>>``: ``%W set [%W cget -from]``, or
    ``-to``, in both scripts."""

    def binding(event: Event) -> None:
        scale = event.widget
        if not scale._disabled:
            scale.set(float(scale._options[option]))

    return binding


def _scale_refresh(event: Event) -> None:
    """Repaint after the focus moved in or out."""
    event.widget._redraw()
